struct hstex_hbox_builder {
    uint32_t *node_identifiers;
    size_t count;
    size_t capacity;
    int64_t width;
    int32_t height;
    int32_t depth;
};

/* A vertical list is measured as TeX packages it: `extent` accumulates
   everything above the trailing depth, and `trailing_depth` is the depth of
   the last box or rule, which glue and penalties reset. */
struct hstex_vbox_builder {
    uint32_t *node_identifiers;
    size_t count;
    size_t capacity;
    int64_t extent;
    int32_t trailing_depth;
    int32_t width;
    /* \noalign material is part of the alignment's own vertical list, which
       may already hold rows: an empty builder is not an empty list. See
       docs/DECISIONS.md, a-rule-between-rows. */
    bool continues;
    /* WHAT \boxmaxdepth SAID INSIDE THE BOX, taken before the box's own
       group is closed: the reference reads it there, so a `\boxmaxdepth'
       set in the box is the one that limits it. Nought until it is taken.
       See docs/DECISIONS.md, what-boxmaxdepth-is-read-when. */
    bool max_depth_known;
    int32_t max_depth;
};

