    "<17> <02DA>\n"
    "<18> <00B8>\n"
    "<19> <00DF>\n"
    "<1A> <00E6>\n"
    "<1B> <0153>\n"
    "<1C> <00F8>\n"
    "<1D> <00C6>\n"
    "<1E> <0152>\n"
    "<1F> <00D8>\n"
    "<21> <0021>\n"
    "<22> <201D>\n"
    "<27> <2019>\n"
    "<3C> <00A1>\n"
    "<3D> <003D>\n"
    "<3E> <00BF>\n"
    "<5C> <201C>\n"
    "<5F> <02D9>\n"
    "<60> <2018>\n"
    "<7D> <02DD>\n"
    "<7E> <02DC>\n"
    "<7F> <00A8>\n"
    "endbfchar\n"
    "endcmap\n"
    "CMapName currentdict /CMap defineresource pop\n"
    "end\n"
    "end\n"
    "%%EndResource\n"
    "%%EOF\n";

static int pdf_write_one_shared_cmap(struct hstex_engine *engine, bool t1,
                                     char *error, size_t error_capacity)
{
    size_t object = t1 ? engine->pdf_t1_cmap : engine->pdf_ot1_cmap;
    size_t encoding = t1 ? engine->pdf_t1_cmap_encoding
                         : engine->pdf_ot1_cmap_encoding;
    bool *written = t1 ? &engine->pdf_t1_cmap_written
                       : &engine->pdf_ot1_cmap_written;
    if (object == 0U || *written) {
        return 0;
    }
    if (encoding == 0U || encoding > engine->pdf_encoding_count) {
        return set_error(error, error_capacity,
                         "invalid shared PDF CMap encoding");
    }
    const char *content = t1 ? pdf_t1_shared_cmap : pdf_ot1_shared_cmap;
    size_t content_size = t1 ? sizeof(pdf_t1_shared_cmap) - 1U
                             : sizeof(pdf_ot1_shared_cmap) - 1U;
    int status = pdf_write_stream_object(
        engine, object, NULL, 0U, (const uint8_t *)content, content_size,
        error, error_capacity);
    if (status == 0) {
        *written = true;
    }
    return status;
}

static int pdf_write_shared_cmaps(struct hstex_engine *engine, char *error,
                                  size_t error_capacity)
{
    bool t1_first = engine->pdf_ot1_cmap == 0U ||
                    (engine->pdf_t1_cmap != 0U &&
                     engine->pdf_t1_cmap < engine->pdf_ot1_cmap);
    if (pdf_write_one_shared_cmap(engine, t1_first, error, error_capacity) !=
            0 ||
        pdf_write_one_shared_cmap(engine, !t1_first, error, error_capacity) !=
            0) {
        return -1;
    }
    return 0;
}

static int pdf_write_font_cmap(struct hstex_engine *engine,
                               struct hstex_pdf_font *entry, char *error,
                               size_t error_capacity)
{
    if (entry->pk_font != NULL || entry->to_unicode != 0U) {
        return 0;
    }
    const struct hstex_font *font =
        font_by_identifier(engine, entry->identifier);
    if (font == NULL) {
        return set_error(error, error_capacity, "invalid PDF CMap font");
    }
    if (font->pdf_no_builtin_to_unicode) {
        return 0;
    }
    enum hstex_pdf_cmap_kind kind = pdf_font_cmap_kind(engine, entry);
    if (kind == HSTEX_PDF_CMAP_NONE) {
        return 0;
    }
    const char *label = entry->encoding_place == 0U
                            ? "builtin"
                            : engine->pdf_encodings[entry->encoding_place - 1U]
                                  .label;
    if (kind == HSTEX_PDF_CMAP_T1 || kind == HSTEX_PDF_CMAP_OT1) {
        size_t *shared = kind == HSTEX_PDF_CMAP_T1 ? &engine->pdf_t1_cmap
                                                   : &engine->pdf_ot1_cmap;
        const char *ordering =
            kind == HSTEX_PDF_CMAP_T1 ? "T1" : "OT1";
        if (*shared == 0U) {
            *shared = pdf_new_object(engine);
            size_t *encoding = kind == HSTEX_PDF_CMAP_T1
                                   ? &engine->pdf_t1_cmap_encoding
                                   : &engine->pdf_ot1_cmap_encoding;
            *encoding = entry->encoding_place;
        }
        if (pdf_write_shared_cmaps(engine, error, error_capacity) != 0) {
            return -1;
        }
        entry->to_unicode = *shared;
        (void)ordering;
        return 0;
    }
    char ordering[512];
    int length = snprintf(ordering, sizeof(ordering), "%s-%s", font->name,
                          label);
    if (length < 0 || (size_t)length >= sizeof(ordering)) {
        return set_error(error, error_capacity, "PDF CMap name overflow");
    }
    entry->to_unicode = pdf_new_object(engine);
    return pdf_write_cmap(engine, entry->to_unicode, entry, ordering,
                          font->name, UINT8_MAX, error, error_capacity);
}

static int pdf_write_font_widths(struct hstex_engine *engine,
                                 struct hstex_pdf_font *entry,
                                 const struct hstex_font *font, char *error,
                                 size_t error_capacity)
{
    entry->widths = pdf_new_object(engine);
    engine->pdf_page_count = 0U;
    for (uint32_t code = entry->first; code <= entry->last; ++code) {
        if (code != entry->first &&
            pdf_text(engine, " ", error, error_capacity) != 0) {
            return -1;
        }
        int32_t width = packed_dimen(font->characters[code].width);
        if (pdf_font_units(engine, font, width, error, error_capacity) != 0) {
            return -1;
        }
    }
    return pdf_begin_object(engine, entry->widths, error, error_capacity) !=
                       0 ||
                   pdf_out_text(engine, "[", error, error_capacity) != 0 ||
                   pdf_out(engine, (const char *)engine->pdf_page,
                           engine->pdf_page_count, error, error_capacity) != 0 ||
                   pdf_out_text(engine, "]\n", error, error_capacity) != 0 ||
                   pdf_end_object(engine, error, error_capacity) != 0
               ? -1
               : 0;
}

static int pdf_type3_matrix_units(const struct hstex_font *font,
                                  uint32_t resolution, uint64_t *units,
                                  char *error, size_t error_capacity)
{
    if (font->size <= 0 || resolution == 0U) {
        return set_error(error, error_capacity,
                         "invalid Type 3 font scale");
    }
    uint64_t numerator = UINT64_C(7227) * UINT64_C(65536) * UINT64_C(1000);
    uint64_t denominator = (uint64_t)resolution * (uint64_t)font->size;
    *units = numerator / denominator;
    uint64_t remainder = numerator % denominator;
    if (remainder > denominator / 2U) {
        ++*units;
    }
    if (*units == 0U || *units > (uint64_t)INT64_MAX) {
        return set_error(error, error_capacity,
                         "invalid Type 3 font scale");
    }
    return 0;
}

static int pdf_type3_width_text(const struct hstex_font *font, size_t code,
                                uint32_t resolution, char text[64], char *error,
                                size_t error_capacity)
{
    int32_t width = packed_dimen(font->characters[code].width);
    bool negative = width < 0;
    uint64_t matrix_units = 0U;
    if (pdf_type3_matrix_units(font, resolution, &matrix_units, error,
                               error_capacity) != 0) {
        return -1;
    }
    uint64_t magnitude_width =
        (uint64_t)(negative ? -(int64_t)width : (int64_t)width);
    uint64_t numerator = magnitude_width * UINT64_C(10000000);
    uint64_t denominator = (uint64_t)font->size * matrix_units;
    uint64_t magnitude = numerator / denominator;
    uint64_t remainder = numerator % denominator;
    if (remainder > (denominator - 1U) / 2U) {
        ++magnitude;
    }
    if (magnitude > (uint64_t)INT64_MAX) {
        return set_error(error, error_capacity,
                         "Type 3 font width is too large");
    }
    int64_t units = negative ? -(int64_t)magnitude : (int64_t)magnitude;
    (void)pdf_format_units(text, 64U, units, 2);
    return 0;
}

static int pdf_type3_matrix_text(const struct hstex_font *font,
                                 uint32_t resolution, char text[64],
                                 char *error, size_t error_capacity)
{
    uint64_t units = 0U;
    if (pdf_type3_matrix_units(font, resolution, &units, error,
                               error_capacity) != 0) {
        return -1;
    }
    (void)pdf_format_units(text, 64U, (int64_t)units, 5);
    if (text[0] == '0' && text[1] == '.') {
        memmove(text, text + 1, strlen(text));
    }
    return 0;
}

static int pdf_type3_glyph_box(const struct hstex_pk_glyph *glyph,
                               int32_t box[4], char *error,
                               size_t error_capacity)
{
    if (glyph->width == 0 || glyph->height == 0) {
        box[0] = 0;
        box[1] = 0;
        box[2] = 1;
        box[3] = 1;
        return 0;
    }
    int64_t left = -(int64_t)glyph->horizontal_offset;
    int64_t bottom = (int64_t)glyph->vertical_offset - glyph->height + 1;
    int64_t right = (int64_t)glyph->width - glyph->horizontal_offset + 1;
    int64_t top = (int64_t)glyph->vertical_offset + 1;
    if (left < INT32_MIN || left > INT32_MAX || bottom < INT32_MIN ||
        bottom > INT32_MAX || right < INT32_MIN || right > INT32_MAX ||
        top < INT32_MIN || top > INT32_MAX) {
        return set_error(error, error_capacity,
                         "Type 3 glyph bounding box is too large");
    }
    box[0] = (int32_t)left;
    box[1] = (int32_t)bottom;
    box[2] = (int32_t)right;
    box[3] = (int32_t)top;
    return 0;
}

static int pdf_write_type3_widths(struct hstex_engine *engine,
                                  struct hstex_pdf_font *entry,
                                  const struct hstex_font *font, char *error,
                                  size_t error_capacity)
{
    entry->widths = pdf_new_object(engine);
    if (pdf_begin_object(engine, entry->widths, error, error_capacity) != 0 ||
        pdf_out_text(engine, "[", error, error_capacity) != 0) {
        return -1;
    }
    for (size_t code = entry->first; code <= entry->last; ++code) {
        const struct hstex_pk_glyph *glyph = &entry->pk_font->glyphs[code];
        char width[64] = "0";
        if (pdf_font_code_used(entry->used, code) && glyph->present &&
            pdf_type3_width_text(font, code, entry->pk_resolution, width,
                                 error, error_capacity) != 0) {
            return -1;
        }
        if ((code != entry->first &&
             pdf_out_text(engine, " ", error, error_capacity) != 0) ||
            pdf_out_text(engine, width, error, error_capacity) != 0) {
            return -1;
        }
    }
    return pdf_out_text(engine, "]\n", error, error_capacity) != 0 ||
                   pdf_end_object(engine, error, error_capacity) != 0
               ? -1
               : 0;
}

static int pdf_write_type3_glyph(struct hstex_engine *engine,
                                 struct hstex_pdf_font *entry,
                                 const struct hstex_font *font, size_t code,
                                 char *error, size_t error_capacity)
{
    const struct hstex_pk_glyph *glyph = &entry->pk_font->glyphs[code];
    char width[64];
    int32_t box[4] = {0};
    if (pdf_type3_width_text(font, code, entry->pk_resolution, width, error,
                             error_capacity) != 0 ||
        pdf_type3_glyph_box(glyph, box, error, error_capacity) != 0) {
        return -1;
    }
    struct hstex_pdf_font_buffer content = {0};
    int status = pdf_font_buffer_formatted(
        &content, error, error_capacity, "%s 0 %d %d %d %d d1\n", width,
        box[0], box[1], box[2], box[3]);
    if (status == 0 && glyph->width != 0 && glyph->height != 0) {
        status = pdf_font_buffer_formatted(
            &content, error, error_capacity,
            "q\n%d 0 0 %d %d %d cm\nBI\n/W %d\n/H %d\n"
            "/IM true\n/BPC 1\n/D [1 0]\nID ",
            glyph->width, glyph->height, box[0], box[1], glyph->width,
            glyph->height);
        if (status == 0) {
            status = pdf_font_buffer_append(
                &content, glyph->bitmap, glyph->bitmap_length, error,
                error_capacity);
        }
        if (status == 0) {
            status = pdf_font_buffer_text(&content, "\nEI\nQ\n", error,
                                          error_capacity);
        }
    }
    if (status == 0) {
        entry->pk_glyph_objects[code] = pdf_new_object(engine);
        status = pdf_write_stream_object(
            engine, entry->pk_glyph_objects[code], NULL, 0U, content.bytes,
            content.count, error, error_capacity);
    }
    free(content.bytes);
    return status;
}

static int pdf_write_type3_encoding(struct hstex_engine *engine,
                                    struct hstex_pdf_font *entry, char *error,
                                    size_t error_capacity)
{
    entry->pk_encoding = pdf_new_object(engine);
    if (pdf_begin_object(engine, entry->pk_encoding, error, error_capacity) !=
            0 ||
        pdf_out_text(engine,
                     "<<\n/Type /Encoding\n/Differences [", error,
                     error_capacity) != 0) {
        return -1;
    }
    bool first = true;
    for (size_t code = entry->first; code <= entry->last; ++code) {
        if (!pdf_font_code_used(entry->used, code)) {
            continue;
        }
        const char *space = first ? "" : " ";
        if (entry->pk_font->glyphs[code].present) {
            if (pdf_out_formatted(engine, error, error_capacity, "%s%zu /a%zu",
                                  space, code, code) != 0) {
                return -1;
            }
        } else if (pdf_out_formatted(engine, error, error_capacity,
                                     "%s%zu /.notdef", space, code) != 0) {
            return -1;
        }
        first = false;
    }
    return pdf_out_text(engine, "]\n>>\n", error, error_capacity) != 0 ||
                   pdf_end_object(engine, error, error_capacity) != 0
               ? -1
               : 0;
}

static int pdf_write_type3_char_procs(struct hstex_engine *engine,
                                      struct hstex_pdf_font *entry,
                                      char *error, size_t error_capacity)
{
    entry->pk_char_procs = pdf_new_object(engine);
    if (pdf_begin_object(engine, entry->pk_char_procs, error, error_capacity) !=
            0 ||
        pdf_out_text(engine, "<<", error, error_capacity) != 0) {
        return -1;
    }
    for (size_t code = entry->first; code <= entry->last; ++code) {
        if (entry->pk_glyph_objects[code] != 0U &&
            pdf_out_formatted(engine, error, error_capacity,
                              "\n/a%zu %zu 0 R", code,
                              entry->pk_glyph_objects[code]) != 0) {
            return -1;
        }
    }
    return pdf_out_text(engine, "\n>>\n", error, error_capacity) != 0 ||
                   pdf_end_object(engine, error, error_capacity) != 0
               ? -1
               : 0;
}

static int pdf_type3_font_box(const struct hstex_pdf_font *entry,
                              int32_t box[4], char *error,
                              size_t error_capacity)
{
    bool held = false;
    for (size_t code = entry->first; code <= entry->last; ++code) {
        if (!pdf_font_code_used(entry->used, code) ||
            !entry->pk_font->glyphs[code].present) {
            continue;
        }
        int32_t glyph_box[4];
        if (pdf_type3_glyph_box(&entry->pk_font->glyphs[code], glyph_box,
                                error, error_capacity) != 0) {
            return -1;
        }
        if (!held) {
            memcpy(box, glyph_box, sizeof(glyph_box));
            held = true;
        } else {
            if (glyph_box[0] < box[0]) {
                box[0] = glyph_box[0];
            }
            if (glyph_box[1] < box[1]) {
                box[1] = glyph_box[1];
            }
            if (glyph_box[2] > box[2]) {
                box[2] = glyph_box[2];
            }
            if (glyph_box[3] > box[3]) {
                box[3] = glyph_box[3];
            }
        }
    }
    if (!held) {
        box[0] = 0;
        box[1] = 0;
        box[2] = 1;
        box[3] = 1;
    }
    return 0;
}

static int pdf_write_type3_font(struct hstex_engine *engine,
                                struct hstex_pdf_font *entry,
                                const struct hstex_font *font, bool dictionary,
                                char *error, size_t error_capacity)
{
    if (!dictionary) {
        if (pdf_write_type3_widths(engine, entry, font, error,
                                   error_capacity) != 0) {
            return -1;
        }
        for (size_t code = entry->first; code <= entry->last; ++code) {
            if (pdf_font_code_used(entry->used, code) &&
                entry->pk_font->glyphs[code].present &&
                pdf_write_type3_glyph(engine, entry, font, code, error,
                                      error_capacity) != 0) {
                return -1;
            }
        }
        return pdf_write_type3_encoding(engine, entry, error, error_capacity) !=
                       0 ||
                       pdf_write_type3_char_procs(engine, entry, error,
                                                  error_capacity) != 0
                   ? -1
                   : 0;
    }
    char matrix[64];
    int32_t box[4];
    if (pdf_type3_matrix_text(font, entry->pk_resolution, matrix, error,
                              error_capacity) != 0 ||
        pdf_type3_font_box(entry, box, error, error_capacity) != 0) {
        return -1;
    }
    return pdf_begin_object(engine, entry->object, error, error_capacity) != 0 ||
                   pdf_out_formatted(
                       engine, error, error_capacity,
                       "<<\n/Type /Font\n/Subtype /Type3\n/Name /F%u\n"
                       "/FontMatrix [%s 0 0 %s 0 0]\n"
                       "/FontBBox [%d %d %d %d]\n"
                       "/Resources <<\n/ProcSet [/PDF /ImageB]\n>>\n"
                       "/FirstChar %u\n/LastChar %u\n/Widths %zu 0 R\n"
                       "/Encoding %zu 0 R\n/CharProcs %zu 0 R\n>>\n",
                       (unsigned int)entry->number, matrix, matrix, box[0],
                       box[1], box[2], box[3], (unsigned int)entry->first,
                       (unsigned int)entry->last, entry->widths,
                       entry->pk_encoding, entry->pk_char_procs) != 0 ||
                   pdf_end_object(engine, error, error_capacity) != 0
               ? -1
               : 0;
}

/* What the file says of a font it does not carry: how far it reaches above
   and below the line, how wide its widest character is, and a stem width
   guessed from its full stop. */
static int pdf_write_unembedded_descriptor(struct hstex_engine *engine,
                                            struct hstex_pdf_font *entry,
                                            const struct hstex_font *font,
                                            char *error,
                                            size_t error_capacity)
{
    entry->descriptor = pdf_new_object(engine);
    int32_t ascent = pdf_font_measure(
        font, packed_dimen(font->characters['h'].height));
    int32_t capheight = pdf_font_measure(
        font, packed_dimen(font->characters['H'].height));
    int32_t descent = -pdf_font_measure(
        font, packed_dimen(font->characters['y'].depth));
    int32_t xheight =
        pdf_font_measure(font, font->dimen_count > 4U ? font->dimens[4] : 0);
    int32_t quad =
        pdf_font_measure(font, font->dimen_count > 5U ? font->dimens[5] : 0);
    int32_t stem = pdf_font_stem(font);
    int32_t top = ascent > capheight ? ascent : capheight;
    return pdf_begin_object(engine, entry->descriptor, error,
                            error_capacity) != 0 ||
                   pdf_out_formatted(
                       engine, error, error_capacity,
                       "<<\n/Type /FontDescriptor\n/FontName /%s\n"
                       "/Flags 34\n/FontBBox [0 %d %d %d]\n/Ascent %d\n"
                       "/CapHeight %d\n/Descent %d\n/ItalicAngle 0\n"
                       "/StemV %d\n/XHeight %d\n>>\n",
                       pdf_font_name(font), descent, quad, top, ascent,
                       capheight, descent, stem, xheight) != 0 ||
                   pdf_end_object(engine, error, error_capacity) != 0
               ? -1
               : 0;
}

static int pdf_write_font(struct hstex_engine *engine,
                          struct hstex_pdf_font *entry, bool dictionary,
                          char *error, size_t error_capacity)
{
    const struct hstex_font *font =
        font_by_identifier(engine, entry->identifier);
    if (font == NULL) {
        return set_error(error, error_capacity, "invalid font in the PDF file");
    }
    if (entry->pk_font != NULL) {
        return pdf_write_type3_font(engine, entry, font, dictionary, error,
                                    error_capacity);
    }
    struct hstex_pdf_physical_font *physical =
        entry->physical_place == 0U
            ? NULL
            : &engine->pdf_physical_fonts[entry->physical_place - 1U];
    if (!dictionary) {
        if (entry->encoding_place != 0U) {
            pdf_reserve_encoding(
                engine, &engine->pdf_encodings[entry->encoding_place - 1U]);
        }
        if (pdf_write_font_widths(engine, entry, font, error,
                                  error_capacity) != 0) {
            return -1;
        }
        return physical == NULL
                   ? pdf_write_unembedded_descriptor(engine, entry, font,
                                                     error, error_capacity)
                   : 0;
    }
    const char *name =
        physical == NULL ? pdf_font_name(font) : physical->postscript_name;
    if (physical != NULL) {
        entry->descriptor = physical->descriptor_object;
    }
    if (pdf_begin_object(engine, entry->object, error, error_capacity) != 0 ||
        pdf_out_formatted(engine, error, error_capacity,
                          "<<\n/Type /Font\n/Subtype /Type1\n/BaseFont /%s%s%s\n"
                          "/FontDescriptor %zu 0 R\n/FirstChar %u\n"
                          "/LastChar %u\n/Widths %zu 0 R\n",
                          physical == NULL ? "" : physical->subset_tag,
                          physical == NULL ? "" : "+", name,
                          entry->descriptor, (unsigned int)entry->first,
                          (unsigned int)entry->last, entry->widths) != 0 ||
        (entry->encoding_place != 0U &&
         pdf_out_formatted(
             engine, error, error_capacity, "/Encoding %zu 0 R\n",
             engine->pdf_encodings[entry->encoding_place - 1U].object) != 0) ||
        (entry->to_unicode != 0U &&
         pdf_out_formatted(engine, error, error_capacity,
                           "/ToUnicode %zu 0 R\n", entry->to_unicode) != 0) ||
        (font->pdf_attribute != NULL && font->pdf_attribute[0] != '\0' &&
         (pdf_out(engine, font->pdf_attribute,
                  strlen(font->pdf_attribute), error, error_capacity) != 0 ||
          (font->pdf_attribute[strlen(font->pdf_attribute) - 1U] != '\n' &&
           pdf_out_text(engine, "\n", error, error_capacity) != 0))) ||
        pdf_out_text(engine, ">>\n", error, error_capacity) != 0 ||
        pdf_end_object(engine, error, error_capacity) != 0) {
        return -1;
    }
    return 0;
}

/* While the outline is built, the entry whose children are being collected,
   how many of them the document said were still to come, and the last one
   met. */
struct hstex_pdf_outline_frame {
    size_t owner;
    int32_t remaining;
    size_t last;
};

/* The outline the document built: the entries are linked into a tree by the
   number of children each of them declared, and written from the last back
   to the first under a root of their own. See docs/DECISIONS.md,
   the-outline-of-a-document. */
static int pdf_write_outlines(struct hstex_engine *engine, char *error,
                              size_t error_capacity)
{
    size_t count = engine->pdf_outline_count;
    if (count == 0U) {
        return 0;
    }
    struct hstex_pdf_outline *entries = engine->pdf_outlines;
    struct hstex_pdf_outline_frame *stack =
        malloc((count + 1U) * sizeof(*stack));
    if (stack == NULL) {
        return set_error(error, error_capacity,
                         "PDF outline allocation failed");
    }
    size_t depth = 1U;
    stack[0].owner = HSTEX_PDF_OUTLINE_NONE;
    stack[0].remaining = -1;
    stack[0].last = HSTEX_PDF_OUTLINE_NONE;
    size_t first = HSTEX_PDF_OUTLINE_NONE;
    for (size_t index = 0U; index < count; ++index) {
        struct hstex_pdf_outline_frame *frame = &stack[depth - 1U];
        entries[index].parent = frame->owner;
        if (frame->last == HSTEX_PDF_OUTLINE_NONE) {
            if (frame->owner == HSTEX_PDF_OUTLINE_NONE) {
                first = index;
            } else {
                entries[frame->owner].first = index;
            }
        } else {
            entries[frame->last].next = index;
            entries[index].previous = frame->last;
        }
        frame->last = index;
        if (frame->owner != HSTEX_PDF_OUTLINE_NONE) {
            entries[frame->owner].last = index;
        }
        if (frame->remaining > 0) {
            frame->remaining -= 1;
        }
        int32_t children = entries[index].count;
        if (children < 0) {
            children = -children;
        }
        if (children > 0) {
            stack[depth].owner = index;
            stack[depth].remaining = children;
            stack[depth].last = HSTEX_PDF_OUTLINE_NONE;
            depth += 1U;
        } else {
            while (depth > 1U && stack[depth - 1U].remaining == 0) {
                depth -= 1U;
            }
        }
    }
    /* The entry the root calls its last is the last one of whatever list was
       still open when the document ended, which is not the last of its own
       where a count was left unsatisfied -- and nothing at all where that
       list had not begun. */
    size_t ending = stack[depth - 1U].last;
    free(stack);
    /* How many entries show under each one: its own children, and the
       children of every one of those that is open. What stands under an
       entry always comes after it, so counting backwards settles them all. */
    int32_t showing = 0;
    for (size_t index = count; index > 0U; --index) {
        const struct hstex_pdf_outline *entry = &entries[index - 1U];
        int32_t shows = 1 + (entry->count > 0 ? entry->visible : 0);
        if (entry->parent == HSTEX_PDF_OUTLINE_NONE) {
            showing += shows;
        } else {
            entries[entry->parent].visible += shows;
        }
    }
    engine->pdf_outline_object = pdf_new_object(engine);
    if (pdf_begin_object(engine, engine->pdf_outline_object, error,
                         error_capacity) != 0 ||
        pdf_out_formatted(engine, error, error_capacity,
                          "<<\n/Type /Outlines\n/First %zu 0 R\n"
                          "/Last %zu 0 R\n/Count %d\n>>\n",
                          entries[first].object,
                          ending == HSTEX_PDF_OUTLINE_NONE
                              ? (size_t)0
                              : entries[ending].object,
                          showing) != 0 ||
        pdf_end_object(engine, error, error_capacity) != 0) {
        return -1;
    }
    for (size_t index = count; index > 0U; --index) {
        const struct hstex_pdf_outline *entry = &entries[index - 1U];
        size_t parent = entry->parent == HSTEX_PDF_OUTLINE_NONE
                            ? engine->pdf_outline_object
                            : entries[entry->parent].object;
        if (pdf_begin_object(engine, entry->object, error, error_capacity) !=
                0 ||
            pdf_out_formatted(engine, error, error_capacity,
                              "<<\n/Title %zu 0 R\n/A %zu 0 R\n"
                              "/Parent %zu 0 R\n",
                              entry->title, entry->action, parent) != 0 ||
            (entry->previous != HSTEX_PDF_OUTLINE_NONE &&
             pdf_out_formatted(engine, error, error_capacity, "/Prev %zu 0 R\n",
                               entries[entry->previous].object) != 0) ||
            (entry->next != HSTEX_PDF_OUTLINE_NONE &&
             pdf_out_formatted(engine, error, error_capacity, "/Next %zu 0 R\n",
                               entries[entry->next].object) != 0) ||
            (entry->first != HSTEX_PDF_OUTLINE_NONE &&
             pdf_out_formatted(engine, error, error_capacity,
                               "/First %zu 0 R\n",
                               entries[entry->first].object) != 0) ||
            (entry->last != HSTEX_PDF_OUTLINE_NONE &&
             pdf_out_formatted(engine, error, error_capacity, "/Last %zu 0 R\n",
                               entries[entry->last].object) != 0) ||
            (entry->visible != 0 &&
             pdf_out_formatted(engine, error, error_capacity, "/Count %d\n",
                               entry->count < 0 ? -entry->visible
                                                : entry->visible) != 0) ||
            (entry->attributes != NULL &&
             (pdf_out_text(engine, entry->attributes, error, error_capacity) !=
                  0 ||
              pdf_out_text(engine, "\n", error, error_capacity) != 0)) ||
            pdf_out_text(engine, ">>\n", error, error_capacity) != 0 ||
            pdf_end_object(engine, error, error_capacity) != 0) {
            return -1;
        }
    }
    return 0;
}

/* Whether what the document wrote for a dictionary names an entry of its
   own: the reference looks for the name anywhere in that text, inside a
   string or at the head of a longer name as readily as on its own. See
   docs/DECISIONS.md, what-the-document-says-about-itself. */
static bool pdf_dictionary_names(const uint8_t *text, size_t length,
                                 const char *name)
{
    size_t width = strlen(name);
    if (text == NULL || length < width) {
        return false;
    }
    for (size_t index = 0U; index + width <= length; ++index) {
        if (memcmp(text + index, name, width) == 0) {
            return true;
        }
    }
    return false;
}

/* What the document itself wrote for a dictionary, on a line of its own. */
static int pdf_dictionary_text(struct hstex_engine *engine,
                               const uint8_t *text, size_t length, char *error,
                               size_t error_capacity)
{
    if (length == 0U) {
        return 0;
    }
    return pdf_out(engine, (const char *)text, length, error, error_capacity) !=
                   0 ||
                   pdf_out_text(engine, "\n", error, error_capacity) != 0
               ? -1
               : 0;
}

/* Destinations stand in the file's tree of names in the order of their
   names. */
static int compare_destination_names(const void *one, const void *other)
{
    const struct hstex_pdf_dest *const *first = one;
    const struct hstex_pdf_dest *const *second = other;
    return strcmp((*first)->name, (*second)->name);
}

static bool pdf_trailer_identifier(const struct hstex_engine *engine,
                                   char identifier[33]);

static void pdf_xref_field(uint8_t *entry, uint8_t kind, size_t value,
                           uint8_t last)
{
    entry[0] = kind;
    entry[1] = (uint8_t)((value >> 16U) & 0xFFU);
    entry[2] = (uint8_t)((value >> 8U) & 0xFFU);
    entry[3] = (uint8_t)(value & 0xFFU);
    entry[4] = last;
}

/* PDF 1.5 object compression ends in a five-byte-wide cross-reference
   stream: one kind byte, a three-byte file offset or object-stream number,
   and one generation/index byte. Black-box probes pin both that width and
   the free-object chain. */
static int pdf_write_xref_stream(struct hstex_engine *engine, size_t catalog,
                                 size_t info, char *error,
                                 size_t error_capacity)
{
    if (pdf_flush_object_stream(engine, error, error_capacity) != 0) {
        return -1;
    }
    size_t xref = pdf_new_object(engine);
    if (pdf_reserve_offsets(engine, xref, error, error_capacity) != 0) {
        return -1;
    }
    size_t xref_at = engine->pdf_written;
    engine->pdf_offsets[xref - 1U] = xref_at;
    size_t size = xref + 1U;
    uint8_t *content = malloc(size * 5U);
    size_t *next_free = calloc(size, sizeof(*next_free));
    if (content == NULL || next_free == NULL) {
        free(content);
        free(next_free);
        return set_error(error, error_capacity, "PDF xref allocation failed");
    }
    size_t next = 0U;
    for (size_t number = xref; number > 0U; --number) {
        next_free[number] = next;
        bool direct = engine->pdf_offsets[number - 1U] != 0U;
        bool packed = engine->pdf_object_streams[number - 1U] != 0U;
        if (!direct && !packed) {
            next = number;
        }
    }
    pdf_xref_field(content, 0U, next, 255U);
    for (size_t number = 1U; number <= xref; ++number) {
        size_t slot = (number - 1U) * 5U;
        if (engine->pdf_offsets[number - 1U] != 0U) {
            pdf_xref_field(content + slot + 5U, 1U,
                           engine->pdf_offsets[number - 1U], 0U);
        } else if (engine->pdf_object_streams[number - 1U] != 0U) {
            pdf_xref_field(content + slot + 5U, 2U,
                           engine->pdf_object_streams[number - 1U],
                           engine->pdf_object_stream_indices[number - 1U]);
        } else {
            pdf_xref_field(content + slot + 5U, 0U, next_free[number], 255U);
        }
    }
    char identifier[33];
    bool include_identifier = pdf_trailer_identifier(engine, identifier);
    char attributes[320];
    int length = include_identifier
                     ? snprintf(attributes, sizeof(attributes),
                                "/Type /XRef\n/Index [0 %zu]\n/Size %zu\n"
                                "/W [1 3 1]\n/Root %zu 0 R\n/Info %zu 0 R\n"
                                "/ID [<%s> <%s>]\n",
                                size, size, catalog, info, identifier,
                                identifier)
                     : snprintf(attributes, sizeof(attributes),
                                "/Type /XRef\n/Index [0 %zu]\n/Size %zu\n"
                                "/W [1 3 1]\n/Root %zu 0 R\n/Info %zu 0 R\n",
                                size, size, catalog, info);
    int status =
        length < 0 || (size_t)length >= sizeof(attributes)
            ? set_error(error, error_capacity, "PDF xref overflow")
            : pdf_write_stream_object(engine, xref, attributes, (size_t)length,
                                      content, size * 5U, error,
                                      error_capacity);
    free(content);
    free(next_free);
    return status != 0 ||
                   pdf_out_formatted(engine, error, error_capacity,
                                     "startxref\n%zu\n%%%%EOF\n", xref_at) !=
                       0
               ? -1
               : 0;
}

/* One node of the page tree.  Level zero contains the six-page nodes made
   during shipout; higher levels contain groups of six nodes from the level
   below. */
static int pdf_write_page_tree_node(
    struct hstex_engine *engine, size_t level, size_t index,
    size_t *const objects[HSTEX_PDF_TREE_LEVELS],
    size_t *const counts[HSTEX_PDF_TREE_LEVELS],
    const size_t widths[HSTEX_PDF_TREE_LEVELS], size_t parent, char *error,
    size_t error_capacity)
{
    if (pdf_begin_object(engine, objects[level][index], error,
                         error_capacity) != 0 ||
        pdf_out_formatted(engine, error, error_capacity,
                          "<<\n/Type /Pages\n/Count %zu\n",
                          counts[level][index]) != 0 ||
        (parent != 0U &&
         pdf_out_formatted(engine, error, error_capacity,
                           "/Parent %zu 0 R\n", parent) != 0) ||
        pdf_out_text(engine, "/Kids [", error, error_capacity) != 0) {
        return -1;
    }
    size_t first = level == 0U ? engine->pdf_page_nodes[index].first
                               : index * 6U;
    size_t last = level == 0U
                      ? first + engine->pdf_page_nodes[index].pages
                      : first + 6U;
    if (level != 0U && last > widths[level - 1U]) {
        last = widths[level - 1U];
    }
    for (size_t child = first; child < last; ++child) {
        size_t object = level == 0U ? engine->pdf_page_objects[child]
                                    : objects[level - 1U][child];
        if (pdf_out_formatted(engine, error, error_capacity, "%s%zu 0 R",
                              child == first ? "" : " ", object) != 0) {
            return -1;
        }
    }
    return pdf_out_text(engine, "]\n>>\n", error, error_capacity) != 0 ||
                   pdf_end_object(engine, error, error_capacity) != 0
               ? -1
               : 0;
}

/* What the reference writes after the last page: the fonts, the tree of
   pages, what the file is about, and the table of where everything is. */
static int pdf_close(struct hstex_engine *engine, char *error,
                     size_t error_capacity)
{
    if (engine->pdf_file == NULL) {
        return 0;
    }
    if (engine->spec_finished || engine->tile_middle) {
        /* Either the verifier handed off, or this is a middle tiling chunk: its
           pages are in the shared file and everything after them -- deferred
           objects, catalogue, xref -- belongs to the finishing chunk. Flush what
           is buffered and let go of the file. */
        if (pdf_flush(engine, error, error_capacity) != 0) {
            return -1;
        }
        (void)fclose(engine->pdf_file);
        engine->pdf_file = NULL;
        return 0;
    }
    /* Objects not emitted by \immediate (and non-stream objects waiting for
       eventual object-stream packing) still have to exist in the file. */
    for (size_t index = 0U; index < engine->pdf_object_count; ++index) {
        if (pdf_write_document_object(engine, &engine->pdf_objects[index],
                                      error, error_capacity) != 0) {
            return -1;
        }
    }
    /* A destination that was aimed at but never put anywhere is replaced by
       one that stands at the top of the first page, the last one aimed at
       first. See docs/DECISIONS.md, destinations-in-the-file. */
    for (size_t index = engine->pdf_dest_count; index > 0U; --index) {
        const struct hstex_pdf_dest *dest = &engine->pdf_dests[index - 1U];
        if (dest->placed || dest->structured) {
            continue;
        }
        if (pdf_begin_object(engine, dest->object, error, error_capacity) != 0 ||
            pdf_out_formatted(engine, error, error_capacity, "[%zu 0 R /Fit]\n",
                              engine->pdf_first_page) != 0 ||
            pdf_end_object(engine, error, error_capacity) != 0) {
            return -1;
        }
    }
    /* The measurements of the fonts are written from the last font the page
       descriptions met back to the first, and their dictionaries by name.
       See docs/DECISIONS.md, the-fonts-a-page-names. */
    size_t count = engine->pdf_font_count;
    for (size_t index = count; index > 0U; --index) {
        if (pdf_prepare_font(engine, &engine->pdf_fonts[index - 1U], error,
                             error_capacity) != 0 ||
            pdf_collect_font(engine, &engine->pdf_fonts[index - 1U], error,
                             error_capacity) != 0) {
            return -1;
        }
    }
    for (size_t index = count; index > 0U; --index) {
        if (pdf_write_font(engine, &engine->pdf_fonts[index - 1U], false,
                           error, error_capacity) != 0) {
            return -1;
        }
    }
    if (pdf_write_physical_fonts(engine, error, error_capacity) != 0) {
        return -1;
    }
    size_t *order = malloc(count == 0U ? 1U : count * sizeof(*order));
    if (order == NULL) {
        return set_error(error, error_capacity, "PDF font allocation failed");
    }
    for (size_t index = 0U; index < count; ++index) {
        order[index] = index;
    }
    for (size_t index = 0U; index < count; ++index) {
        for (size_t other = index + 1U; other < count; ++other) {
            const struct hstex_font *one = font_by_identifier(
                engine, engine->pdf_fonts[order[index]].identifier);
            const struct hstex_font *two = font_by_identifier(
                engine, engine->pdf_fonts[order[other]].identifier);
            if (one == NULL || two == NULL) {
                continue;
            }
            if (strcmp(two->name, one->name) < 0) {
                size_t swapped = order[index];
                order[index] = order[other];
                order[other] = swapped;
            }
        }
    }
    /* Encoding numbers were reserved beside the widths above, but their
       dictionaries follow the physical font descriptors in encoding-file
       name order.  This order is independent of the first font that happens
       to share an encoding. */
    size_t encoding_count = engine->pdf_encoding_count;
    size_t *encoding_order =
        malloc(encoding_count == 0U ? 1U
                                    : encoding_count * sizeof(*encoding_order));
    if (encoding_order == NULL) {
        free(order);
        return set_error(error, error_capacity, "PDF encoding allocation failed");
    }
    for (size_t index = 0U; index < encoding_count; ++index) {
        encoding_order[index] = index;
    }
    for (size_t index = 0U; index < encoding_count; ++index) {
        for (size_t other = index + 1U; other < encoding_count; ++other) {
            if (strcmp(engine->pdf_encodings[encoding_order[other]].file,
                       engine->pdf_encodings[encoding_order[index]].file) < 0) {
                size_t swapped = encoding_order[index];
                encoding_order[index] = encoding_order[other];
                encoding_order[other] = swapped;
            }
        }
    }
    for (size_t index = 0U; index < encoding_count; ++index) {
        struct hstex_pdf_encoding *encoding =
            &engine->pdf_encodings[encoding_order[index]];
        if (encoding->object != 0U &&
            pdf_write_encoding(engine, encoding, error, error_capacity) != 0) {
            free(encoding_order);
            free(order);
            return -1;
        }
    }
    free(encoding_order);
    for (size_t index = 0U; index < count; ++index) {
        if (pdf_write_font_cmap(engine, &engine->pdf_fonts[order[index]], error,
                                error_capacity) != 0) {
            free(order);
            return -1;
        }
        if (pdf_write_font(engine, &engine->pdf_fonts[order[index]], true,
                           error, error_capacity) != 0) {
            free(order);
            return -1;
        }
    }
    free(order);
    /* The tree of pages: the nodes the pages were shipped into, then a node
       for every six of those, up to the one the catalog names. See
       docs/DECISIONS.md, the-tree-of-pages. */
    if (engine->pdf_page_node_count == 0U) {
        engine->pdf_pages_object = pdf_new_object(engine);
        if (pdf_begin_object(engine, engine->pdf_pages_object, error,
                             error_capacity) != 0 ||
            pdf_out_text(engine, "<<\n/Type /Pages\n/Count 0\n/Kids []\n>>\n",
                         error, error_capacity) != 0 ||
            pdf_end_object(engine, error, error_capacity) != 0) {
            return -1;
        }
    } else {
        size_t *objects[HSTEX_PDF_TREE_LEVELS] = {NULL};
        size_t *counts[HSTEX_PDF_TREE_LEVELS] = {NULL};
        size_t widths[HSTEX_PDF_TREE_LEVELS] = {0U};
        size_t levels = 1U;
        widths[0] = engine->pdf_page_node_count;
        objects[0] = malloc(widths[0] * sizeof(**objects));
        counts[0] = malloc(widths[0] * sizeof(**counts));
        int status = objects[0] == NULL || counts[0] == NULL ? -1 : 0;
        for (size_t index = 0U; status == 0 && index < widths[0]; ++index) {
            objects[0][index] = engine->pdf_page_nodes[index].object;
            counts[0][index] = engine->pdf_page_nodes[index].pages;
        }
        /* A parent is numbered, then its six children are written.  Thus a
           full packed batch can reserve its next container between two
           parent numbers, exactly where the page-tree builder does. */
        while (status == 0 && widths[levels - 1U] > 1U &&
               levels < HSTEX_PDF_TREE_LEVELS) {
            size_t below = widths[levels - 1U];
            size_t width = (below + 5U) / 6U;
            objects[levels] = calloc(width, sizeof(**objects));
            counts[levels] = malloc(width * sizeof(**counts));
            if (objects[levels] == NULL || counts[levels] == NULL) {
                status = -1;
                break;
            }
            for (size_t index = 0U; index < width; ++index) {
                size_t total = 0U;
                for (size_t child = index * 6U;
                     child < below && child < index * 6U + 6U; ++child) {
                    total += counts[levels - 1U][child];
                }
                counts[levels][index] = total;
            }
            widths[levels] = width;
            ++levels;
        }
        if (status == 0 && levels == 1U) {
            status = pdf_write_page_tree_node(
                engine, 0U, 0U, objects, counts, widths, 0U, error,
                error_capacity);
        }
        for (size_t level = 1U; status == 0 && level < levels; ++level) {
            for (size_t parent = 0U;
                 status == 0 && parent < widths[level]; ++parent) {
                pdf_reserve_packed_object_stream(engine);
                objects[level][parent] = pdf_new_object(engine);
                size_t first = parent * 6U;
                size_t last = first + 6U;
                if (last > widths[level - 1U]) {
                    last = widths[level - 1U];
                }
                for (size_t child = first; status == 0 && child < last;
                     ++child) {
                    status = pdf_write_page_tree_node(
                        engine, level - 1U, child, objects, counts, widths,
                        objects[level][parent], error, error_capacity);
                }
            }
        }
        if (status == 0 && levels > 1U) {
            status = pdf_write_page_tree_node(
                engine, levels - 1U, 0U, objects, counts, widths, 0U, error,
                error_capacity);
        }
        if (status == 0) {
            engine->pdf_pages_object = objects[levels - 1U][0];
        }
        for (size_t level = 0U; level < HSTEX_PDF_TREE_LEVELS; ++level) {
            free(objects[level]);
            free(counts[level]);
        }
        if (status != 0) {
            return set_error(error, error_capacity, "PDF page allocation failed");
        }
    }
    if (pdf_write_outlines(engine, error, error_capacity) != 0) {
        return -1;
    }
    /* The names the file knows stand in a tree of their own, sorted, six to
       a node at every level, and each node says what it spans. See
       docs/DECISIONS.md, destinations-in-the-file. */
    size_t names = 0U;
    size_t named = 0U;
    for (size_t index = 0U; index < engine->pdf_dest_count; ++index) {
        if (engine->pdf_dests[index].named &&
            !engine->pdf_dests[index].structured) {
            ++named;
        }
    }
    if (named != 0U) {
        struct hstex_pdf_dest **sorted = malloc(named * sizeof(*sorted));
        size_t *objects[HSTEX_PDF_TREE_LEVELS] = {NULL};
        size_t widths[HSTEX_PDF_TREE_LEVELS] = {0U};
        size_t levels = 1U;
        int status = sorted == NULL ? -1 : 0;
        if (status == 0) {
            size_t at = 0U;
            for (size_t index = 0U; index < engine->pdf_dest_count; ++index) {
                if (engine->pdf_dests[index].named &&
                    !engine->pdf_dests[index].structured) {
                    sorted[at++] = &engine->pdf_dests[index];
                }
            }
            /* The names are sorted rather than picked out one at a time:
               the corpus has 23,513 of them, and comparing every pair is
               276 million comparisons. */
            qsort(sorted, named, sizeof(*sorted), compare_destination_names);
            widths[0] = (named + 5U) / 6U;
            objects[0] = calloc(widths[0], sizeof(**objects));
            status = objects[0] == NULL ? -1 : 0;
        }
        while (status == 0 && widths[levels - 1U] > 1U &&
               levels < HSTEX_PDF_TREE_LEVELS) {
            size_t width = (widths[levels - 1U] + 5U) / 6U;
            objects[levels] = calloc(width, sizeof(**objects));
            if (objects[levels] == NULL) {
                status = -1;
                break;
            }
            widths[levels] = width;
            ++levels;
        }
        for (size_t level = 0U; status == 0 && level < levels; ++level) {
            for (size_t index = 0U; status == 0 && index < widths[level];
                 ++index) {
                objects[level][index] = pdf_new_object(engine);
                size_t first = index * 6U;
                size_t last = first + 6U;
                size_t below = level == 0U ? named : widths[level - 1U];
                if (last > below) {
                    last = below;
                }
                /* What the node spans is what its first and last children
                   span. */
                size_t low = first;
                size_t high = last - 1U;
                for (size_t step = level; step > 0U; --step) {
                    low = low * 6U;
                    high = high * 6U + 5U;
                    size_t limit = step == 1U ? named : widths[step - 2U];
                    if (high >= limit) {
                        high = limit - 1U;
                    }
                }
                status = pdf_begin_object(engine, objects[level][index], error,
                                          error_capacity) != 0 ||
                                 pdf_out_formatted(engine, error, error_capacity,
                                                   "<<\n/%s [",
                                                   level == 0U ? "Names"
                                                               : "Kids") != 0
                             ? -1
                             : 0;
                for (size_t child = first; status == 0 && child < last;
                     ++child) {
                    status =
                        level == 0U
                            ? pdf_out_formatted(engine, error, error_capacity,
                                                "%s(%s) %zu 0 R",
                                                child == first ? "" : " ",
                                                sorted[child]->name,
                                                sorted[child]->object)
                            : pdf_out_formatted(engine, error, error_capacity,
                                                "%s%zu 0 R",
                                                child == first ? "" : " ",
                                                objects[level - 1U][child]);
                }
                if (status == 0) {
                    status = pdf_out_formatted(engine, error, error_capacity,
                                               "]\n/Limits [(%s) (%s)]\n>>\n",
                                               sorted[low]->name,
                                               sorted[high]->name) != 0 ||
                                     pdf_end_object(engine, error,
                                                    error_capacity) != 0
                                 ? -1
                                 : 0;
                }
            }
        }
        if (status == 0) {
            names = pdf_new_object(engine);
            status = pdf_begin_object(engine, names, error, error_capacity) !=
                                 0 ||
                             pdf_out_formatted(engine, error, error_capacity,
                                               "<<\n/Dests %zu 0 R\n>>\n",
                                               objects[levels - 1U][0]) != 0 ||
                             pdf_end_object(engine, error, error_capacity) != 0
                         ? -1
                         : 0;
        }
        free(sorted);
        for (size_t level = 0U; level < HSTEX_PDF_TREE_LEVELS; ++level) {
            free(objects[level]);
        }
        if (status != 0) {
            return set_error(error, error_capacity,
                             "PDF destination allocation failed");
        }
    }
    size_t catalog = pdf_new_object(engine);
    size_t info = pdf_new_object(engine);
    if (pdf_begin_object(engine, catalog, error, error_capacity) != 0 ||
        pdf_out_formatted(engine, error, error_capacity,
                          "<<\n/Type /Catalog\n/Pages %zu 0 R\n",
                          engine->pdf_pages_object) != 0 ||
        (engine->pdf_outline_object != 0U &&
         pdf_out_formatted(engine, error, error_capacity, "/Outlines %zu 0 R\n",
                           engine->pdf_outline_object) != 0) ||
        (names != 0U &&
         pdf_out_formatted(engine, error, error_capacity, "/Names %zu 0 R\n",
                           names) != 0) ||
        pdf_dictionary_text(engine, engine->pdf_catalog,
                            engine->pdf_catalog_length, error,
                            error_capacity) != 0 ||
        (engine->pdf_open_action != 0U &&
         pdf_out_formatted(engine, error, error_capacity,
                           "/OpenAction %zu 0 R\n",
                           engine->pdf_open_action) != 0) ||
        pdf_out_text(engine, ">>\n", error, error_capacity) != 0 ||
        pdf_end_object(engine, error, error_capacity) != 0 ||
        pdf_begin_direct_object(engine, info, error, error_capacity) != 0 ||
        pdf_out_text(engine, "<<\n", error, error_capacity) != 0 ||
        /* The reference writes each of its own entries unless the document
           has already named it. */
        (!pdf_dictionary_names(engine->pdf_info, engine->pdf_info_length,
                               "/Producer") &&
         pdf_out_text(engine, "/Producer (pdfTeX-1.40.25)\n", error,
                      error_capacity) != 0) ||
        pdf_dictionary_text(engine, engine->pdf_info, engine->pdf_info_length,
                            error, error_capacity) != 0 ||
        (!pdf_dictionary_names(engine->pdf_info, engine->pdf_info_length,
                               "/Creator") &&
         pdf_out_text(engine, "/Creator (TeX)\n", error, error_capacity) !=
             0) ||
        (!pdf_dictionary_names(engine->pdf_info, engine->pdf_info_length,
                               "/Trapped") &&
         pdf_out_text(engine, "/Trapped /False\n", error, error_capacity) !=
             0) ||
        (!pdf_dictionary_names(engine->pdf_info, engine->pdf_info_length,
                               "/PTEX.Fullbanner") &&
         pdf_out_text(
             engine,
             "/PTEX.Fullbanner (This is pdfTeX, Version "
             "3.141592653-2.6-1.40.25 (TeX Live 2023/Debian) kpathsea "
             "version 6.3.5)\n",
             error, error_capacity) != 0) ||
        pdf_out_text(engine, ">>\n", error, error_capacity) != 0 ||
        pdf_end_object(engine, error, error_capacity) != 0) {
        return -1;
    }
    if (pdf_object_stream_level(engine) > 0) {
        if (pdf_write_xref_stream(engine, catalog, info, error,
                                  error_capacity) != 0) {
            return -1;
        }
        if (pdf_flush(engine, error, error_capacity) != 0) {
            return -1;
        }
        (void)fclose(engine->pdf_file);
        engine->pdf_file = NULL;
        return 0;
    }
    size_t table = engine->pdf_written;
    size_t numbered = (size_t)engine->pdf_object_counter;
    /* An object that was given a number but never written -- a link in a box
       that was thrown away -- leaves a hole, and the holes are chained
       together from the head of the table; see docs/DECISIONS.md,
       annotations-on-a-page. */
    size_t free_next = 0U;
    for (size_t index = numbered; index > 0U; --index) {
        size_t offset = index <= engine->pdf_offset_capacity
                            ? engine->pdf_offsets[index - 1U]
                            : 0U;
        if (offset == 0U) {
            free_next = index;
        }
    }
    if (pdf_out_formatted(engine, error, error_capacity, "xref\n0 %zu\n",
                          numbered + 1U) != 0 ||
        pdf_out_formatted(engine, error, error_capacity, "%010zu 65535 f \n",
                          free_next) != 0) {
        return -1;
    }
    for (size_t index = 0U; index < numbered; ++index) {
        size_t offset =
            index < engine->pdf_offset_capacity ? engine->pdf_offsets[index] : 0U;
        if (offset != 0U) {
            if (pdf_out_formatted(engine, error, error_capacity,
                                  "%010zu 00000 n \n", offset) != 0) {
                return -1;
            }
            continue;
        }
        size_t next = 0U;
        for (size_t after = index + 2U; after <= numbered; ++after) {
            size_t written = after <= engine->pdf_offset_capacity
                                 ? engine->pdf_offsets[after - 1U]
                                 : 0U;
            if (written == 0U) {
                next = after;
                break;
            }
        }
        if (pdf_out_formatted(engine, error, error_capacity,
                              "%010zu 00000 f \n", next) != 0) {
            return -1;
        }
    }
    char identifier[33];
    bool include_identifier = pdf_trailer_identifier(engine, identifier);
    if (pdf_out_formatted(engine, error, error_capacity,
                          "trailer\n<< /Size %zu\n/Root %zu 0 R\n"
                          "/Info %zu 0 R\n",
                          numbered + 1U, catalog, info) != 0 ||
        (include_identifier &&
         pdf_out_formatted(engine, error, error_capacity,
                           "/ID [<%s> <%s>] >>\n", identifier,
                           identifier) != 0) ||
        (!include_identifier &&
         pdf_out_text(engine, " >>\n", error, error_capacity) != 0) ||
        pdf_out_formatted(engine, error, error_capacity,
                          "startxref\n%zu\n%%%%EOF\n", table) != 0) {
        return -1;
    }
    if (pdf_flush(engine, error, error_capacity) != 0) {
        return -1;
    }
    /* An incremental rebuild finishes by tiling a fresh, possibly shorter, tail
       over the previous build's PDF (whose prefix it reused); trim whatever of
       the old file stands past the new %%EOF so no stale trailer is left for a
       reader to find. For a fresh file this is the size it already is. */
    long end = ftell(engine->pdf_file);
    if (end >= 0 && ftruncate(fileno(engine->pdf_file), (off_t)end) != 0) {
        /* Trimming is a courtesy; a reader stops at %%EOF regardless. */
    }
    (void)fclose(engine->pdf_file);
    engine->pdf_file = NULL;
    return 0;
}

/* \shipout takes a page: the box is emptied and the count of dead cycles
   starts again. Nothing is written yet. */
static int perform_shipout_whatsits(struct hstex_engine *engine,
                                    const struct hstex_box *box, char *error,
                                    size_t error_capacity);

/* A page leaves the engine here, whether \shipout was written out or the
   page builder reached the end of a page by itself. */
static int ship_out(struct hstex_engine *engine, const struct hstex_box *box,
                    char *error, size_t error_capacity)
{
    /* The reference names the page it is shipping by its counts, up to the
       last one that is not zero; see docs/DECISIONS.md, the-print-line. */
    size_t last = 9U;
    while (last > 0U && engine->counts[last] == 0) {
        --last;
    }
    /* \tracingoutput shows the page as it goes. The heading stands on a line
       of its own with a blank line above it, the counts close with their `]'
       here rather than after the page is written, and the box is shown under
       \showboxdepth and \showboxbreadth like any other. See
       tests/trip/probes/what-tracingoutput-writes.tex. */
    bool tracing_shipout =
        engine->integer_parameters[HSTEX_INTEGER_TRACING_OUTPUT] > 0;
    if (tracing_shipout) {
        print_fresh_line(engine);
        print_line(engine);
        print_text(engine, "Completed box being shipped out");
    }
    if (engine->message_column > HSTEX_PRINT_LINE - 9) {
        print_line(engine);
    } else if (engine->message_column > 0) {
        print_byte(engine, ' ');
    }
    print_byte(engine, '[');
    for (size_t index = 0U; index <= last; ++index) {
        print_formatted(engine, "%d", engine->counts[index]);
        if (index < last) {
            print_byte(engine, '.');
        }
    }
    if (tracing_shipout) {
        print_byte(engine, ']');
        /* THE COUNTS GO TO THE TERMINAL AND THE BOX DOES NOT. The reference
           closes `[0.0.0.0.11]' with the terminal still named -- and with no
           line ending it -- and only then begins the diagnostic the box is
           shown under. So the newline that box draws belongs to the log
           alone, and the terminal is left standing mid-line: that is what an
           error later in the page finds when it asks whether to break. */
        bool saved_selector = begin_diagnostic(engine);
        show_box_under_limits(engine, box);
        end_diagnostic(engine, saved_selector, true);
        (void)fflush(diagnostic_stream(engine));
    }
    /* A PAGE THAT WILL NOT FIT IN A PAGE DESCRIPTION IS NOT WRITTEN. The
       reference measures the box against the largest dimension it can hold
       -- eighteen feet or so -- taking \voffset and \hoffset into account,
       says so, and throws the page away. What it does around that goes on:
       the counts close with their `]', \deadcycles goes back to nought, and
       the run carries on. The box is shown as deleted unless \tracingoutput
       has shown it already. trip line 432 ships a \vbox 16384pt tall. */
    int64_t total_height = (int64_t)box->height + box->depth +
                           engine->dimen_parameters[HSTEX_DIMEN_VOFFSET];
    int64_t total_width =
        (int64_t)box->width + engine->dimen_parameters[HSTEX_DIMEN_HOFFSET];
    if (box->height > HSTEX_MAX_DIMEN || box->depth > HSTEX_MAX_DIMEN ||
        total_height > HSTEX_MAX_DIMEN || total_width > HSTEX_MAX_DIMEN) {
        static const char *const help[] = {
            "The page just created is more than 18 feet tall or",
            "more than 18 feet wide, so I suspect something went wrong.",
            NULL};
        tex_error(engine, help, "Huge page cannot be shipped out");
        if (!tracing_shipout) {
            report_deleted_box(engine, box);
            print_byte(engine, ']');
        }
        (void)fflush(diagnostic_stream(engine));
        engine->page_integers[HSTEX_PAGE_DEAD_CYCLES] = 0;
        return 0;
    }
    /* Whatever the page was carrying is done now, in the order it was
       written; see docs/DECISIONS.md, whatsits. */
    clear_pdf_shipout_literals(engine);
    if (perform_shipout_whatsits(engine, box, error, error_capacity) != 0) {
        clear_pdf_shipout_literals(engine);
        return -1;
    }
    /* \pdfoutput decides what is written: nothing positive means the page
       description the reference calls a DVI. See docs/DECISIONS.md,
       the-page-description. */
    int output_status =
        engine->integer_parameters[HSTEX_INTEGER_PDF_OUTPUT] <= 0
            ? dvi_ship(engine, box, error, error_capacity)
            : pdf_ship(engine, box, error, error_capacity);
    clear_pdf_shipout_literals(engine);
    if (output_status != 0) {
        return -1;
    }
    if (!tracing_shipout) {
        print_byte(engine, ']');
    }
    (void)fflush(diagnostic_stream(engine));
    engine->page_integers[HSTEX_PAGE_DEAD_CYCLES] = 0;
    engine->shipped_pages += 1;
    return 0;
}

static int ship_out_box(struct hstex_engine *engine, uint32_t index,
                        char *error, size_t error_capacity)
{
    if ((size_t)index >= engine->count_capacity) {
        return set_error(error, error_capacity,
                         "box register %u is outside 0..%zu",
                         (unsigned int)index, engine->count_capacity - 1U);
    }
    struct hstex_box shipped = engine->boxes[index];
    struct hstex_box empty = {0};
    empty.kind = HSTEX_BOX_VOID;
    if (assign_box(engine, index, empty, true, error, error_capacity) != 0) {
        return -1;
    }
    return ship_out(engine, &shipped, error, error_capacity);
}

/* What \end puts in front of itself so that whatever is left comes out: an
   empty line as wide as the page, glue that fills whatever room is left, and
   a penalty nothing can refuse. */
static int eject_last_pages(struct hstex_engine *engine, char *error,
                            size_t error_capacity)
{
    struct hstex_node line = {
        .kind = HSTEX_NODE_LIST,
        .width = engine->dimen_parameters[HSTEX_DIMEN_HSIZE],
        .value.list = {.box_kind = HSTEX_BOX_HLIST},
    };
    struct hstex_node fill = {
        .kind = HSTEX_NODE_GLUE,
        .value.glue = {.stretch = INT32_C(65536), .stretch_order = 2U},
    };
    struct hstex_node penalty = {
        .kind = HSTEX_NODE_PENALTY,
        .value.penalty = -INT32_C(1073741824),
    };
    /* The reference appends these three directly, so the box gets no
       interline glue in front of it -- AND \prevdepth is not touched by the
       box either, the way it would be had the box been contributed. What
       \showlists says of the outermost list inside the \output routine
       these pages fire is therefore what stood before \end was read. */
    int32_t standing_depth = engine->prev_depth;
    struct hstex_node *nodes[3] = {&line, &fill, &penalty};
    for (size_t index = 0U; index < 3U; ++index) {
        uint32_t identifier = 0U;
        if (store_node(engine, nodes[index], &identifier, error,
                       error_capacity) != 0 ||
            append_vbox_item(engine, identifier, error, error_capacity) != 0) {
            return -1;
        }
    }
    engine->prev_depth = standing_depth;
    return contribute_page(engine, error, error_capacity);
}

/* How much it would cost to break the page here. See docs/DECISIONS.md,
   the-output-routine. */
/* A scaled value the way the page trace writes one: no unit on a finite
   amount, the order's name on an infinite one. */
static void print_page_amount(struct hstex_engine *engine, int32_t value,
                              const char *order)
{
    char digits[64];
    if (format_scaled_value(value, order, digits, sizeof(digits)) > 0) {
        print_text(engine, digits);
    }
}

/* \tracingpages says where an insertion had to be split, how much room
   there was for it, how much of it went, and what the break was worth. */
static void trace_page_split(struct hstex_engine *engine, uint32_t number,
                             int32_t allowed, int32_t reached,
                             int32_t penalty)
{
    if (engine->integer_parameters[HSTEX_INTEGER_TRACING_PAGES] <= 0) {
        return;
    }
    bool saved_selector = begin_diagnostic(engine);
    print_fresh_line(engine);
    print_formatted(engine, "%% split%u to ", (unsigned int)number);
    print_page_amount(engine, allowed, "");
    print_byte(engine, ',');
    print_page_amount(engine, reached, "");
    print_formatted(engine, " p=%d", (int)penalty);
    end_diagnostic(engine, saved_selector, false);
    (void)fflush(diagnostic_stream(engine));
}

/* \tracingpages announces each page's goal as the page starts. */
static void trace_page_goal(struct hstex_engine *engine)
{
    if (engine->integer_parameters[HSTEX_INTEGER_TRACING_PAGES] <= 0) {
        return;
    }
    bool saved_selector = begin_diagnostic(engine);
    print_fresh_line(engine);
    print_text(engine, "%% goal height=");
    print_page_amount(engine, engine->page_dimens[HSTEX_PAGE_GOAL], "");
    print_text(engine, ", max depth=");
    print_page_amount(engine, engine->dimen_parameters[HSTEX_DIMEN_MAX_DEPTH],
                      "");
    end_diagnostic(engine, saved_selector, false);
    (void)fflush(diagnostic_stream(engine));
}

/* \tracingpages writes a line for every place the page could break: what
   stands on it, what it is being fitted to, how badly it would fit, what the
   break costs, and a # where that is the best break so far. See
   tests/trip/probes/what-tracingpages-writes.tex. */
static void trace_page_cost(struct hstex_engine *engine, int32_t penalty,
                            int32_t badness, int64_t cost, bool best)
{
    if (engine->integer_parameters[HSTEX_INTEGER_TRACING_PAGES] <= 0) {
        return;
    }
    static const char *const orders[4] = {"", "fil", "fill", "filll"};
    bool saved_selector = begin_diagnostic(engine);
    print_fresh_line(engine);
    print_text(engine, "% t=");
    print_page_amount(engine, engine->page_dimens[HSTEX_PAGE_TOTAL], "");
    for (size_t order = 0U; order < 4U; ++order) {
        int32_t amount = engine->page_dimens[HSTEX_PAGE_STRETCH + order];
        if (amount == 0) {
            continue;
        }
        print_text(engine, " plus ");
        print_page_amount(engine, amount, orders[order]);
    }
    if (engine->page_dimens[HSTEX_PAGE_SHRINK] != 0) {
        print_text(engine, " minus ");
        print_page_amount(engine, engine->page_dimens[HSTEX_PAGE_SHRINK], "");
    }
    print_text(engine, " g=");
    print_page_amount(engine, engine->page_dimens[HSTEX_PAGE_GOAL], "");
    print_text(engine, " b=");
    if ((int64_t)badness >= HSTEX_AWFUL_BADNESS) {
        print_byte(engine, '*');
    } else {
        print_formatted(engine, "%d", (int)badness);
    }
    print_formatted(engine, " p=%d", (int)penalty);
    print_text(engine, " c=");
    if (cost >= HSTEX_AWFUL_BADNESS) {
        print_byte(engine, '*');
    } else {
        print_formatted(engine, "%d", (int)cost);
    }
    if (best) {
        print_byte(engine, '#');
    }
    end_diagnostic(engine, saved_selector, false);
    (void)fflush(diagnostic_stream(engine));
}

/* `badness_out' is what the page trace names as b: how badly what stands on
   the page would have to be stretched or shrunk to reach the goal. */
static int64_t page_break_cost(const struct hstex_engine *engine,
                               int32_t penalty, int32_t *badness_out)
{
    int32_t goal = engine->page_dimens[HSTEX_PAGE_GOAL];
    int32_t total = engine->page_dimens[HSTEX_PAGE_TOTAL];
    int32_t badness;
    if (total < goal) {
        badness = engine->page_dimens[HSTEX_PAGE_FIL_STRETCH] != 0 ||
                          engine->page_dimens[HSTEX_PAGE_FILL_STRETCH] != 0 ||
                          engine->page_dimens[HSTEX_PAGE_FILLL_STRETCH] != 0
                      ? 0
                      : glue_badness(goal - total,
                                     engine->page_dimens[HSTEX_PAGE_STRETCH]);
    } else if ((int64_t)total - goal >
               engine->page_dimens[HSTEX_PAGE_SHRINK]) {
        if (badness_out != NULL) {
            *badness_out = (int32_t)HSTEX_AWFUL_BADNESS;
        }
        return HSTEX_AWFUL_BADNESS;
    } else {
        badness = glue_badness(total - goal,
                               engine->page_dimens[HSTEX_PAGE_SHRINK]);
    }
    if (badness_out != NULL) {
        *badness_out = badness;
    }
    int32_t insert = engine->page_integers[HSTEX_PAGE_INSERT_PENALTIES];
    int64_t cost;
    if (penalty <= -HSTEX_INFINITE_PENALTY) {
        cost = penalty;
    } else if (badness < HSTEX_INFINITE_BADNESS) {
        cost = badness + penalty + insert;
    } else {
        cost = HSTEX_DEPLORABLE_COST;
    }
    if (insert >= HSTEX_INFINITE_PENALTY) {
        cost = HSTEX_AWFUL_BADNESS;
    }
    return cost;
}

/* One record for each class of insertions that has reached the page being
   built; see docs/DECISIONS.md, an-insertion-that-does-not-fit. */
static struct hstex_page_insert *page_insert_of(struct hstex_engine *engine,
                                                uint16_t number, bool make,
                                                char *error,
                                                size_t error_capacity)
{
    for (size_t index = 0U; index < engine->page_insert_count; ++index) {
        if (engine->page_inserts[index].number == number) {
            return &engine->page_inserts[index];
        }
    }
    if (!make) {
        return NULL;
    }
    if (engine->page_insert_count == engine->page_insert_capacity) {
        size_t capacity = engine->page_insert_capacity == 0U
                              ? 4U
                              : engine->page_insert_capacity * 2U;
        struct hstex_page_insert *grown =
            realloc(engine->page_inserts, capacity * sizeof(*grown));
        if (grown == NULL) {
            (void)set_error(error, error_capacity,
                            "page insertion table allocation failed");
            return NULL;
        }
        engine->page_inserts = grown;
        engine->page_insert_capacity = capacity;
    }
    struct hstex_page_insert *entry =
        &engine->page_inserts[engine->page_insert_count++];
    memset(entry, 0, sizeof(*entry));
    entry->number = number;
    return entry;
}

/* A size scaled by the count of an insertion class: a thousand takes it as
   it stands, and any other count divides by a thousand first, throwing the
   remainder away, and multiplies after. */
static int64_t insertion_size(int32_t size, int32_t factor)
{
    return factor == 1000 ? (int64_t)size : (int64_t)(size / 1000) * factor;
}

/* The best break is forgotten when a page is sent off or a new one starts;
   the totals themselves are left alone, because the output routine still
   reads them. */
static void forget_page_break(struct hstex_engine *engine)
{
    engine->least_page_cost = (int32_t)HSTEX_AWFUL_BADNESS;
    engine->best_page_break = 0U;
    engine->best_page_penalty = HSTEX_INFINITE_PENALTY;
    engine->best_page_size = 0;
    engine->page_has_box = false;
    engine->page_frozen = false;
    engine->page_insert_count = 0U;
}

static void reset_page_state(struct hstex_engine *engine)
{
    memset(engine->page_dimens, 0, sizeof(engine->page_dimens));
    forget_page_break(engine);
}

/* Send the best part of the page to \box255 and run \output over it. */
/* The insertions the page carries, gathered into the box of each class. The
   lists are set one after another, in the order they were written, and the
   box is packed at its natural size. See docs/DECISIONS.md, insertions. */
static int collect_page_insertions(struct hstex_engine *engine,
                                   const uint32_t *items, size_t count,
                                   char *error, size_t error_capacity)
{
    for (size_t index = 0U; index < count; ++index) {
        uint32_t held = items[index];
        if (held == 0U || (size_t)held > engine->node_count ||
            engine->nodes[held - 1U].kind != HSTEX_NODE_INSERT) {
            continue;
        }
        uint16_t number = engine->nodes[held - 1U].value.insert.number;
        bool done = false;
        for (size_t earlier = 0U; !done && earlier < index; ++earlier) {
            uint32_t before = items[earlier];
            done = before != 0U && (size_t)before <= engine->node_count &&
                   engine->nodes[before - 1U].kind == HSTEX_NODE_INSERT &&
                   engine->nodes[before - 1U].value.insert.number == number;
        }
        if (done) {
            continue;
        }
        struct hstex_vbox_builder builder = {0};
        struct hstex_vbox_builder *previous = engine->active_vbox_builder;
        enum hstex_mode previous_mode = engine->mode;
        int32_t enclosing_depth = engine->prev_depth;
        engine->active_vbox_builder = &builder;
        engine->mode = HSTEX_MODE_VERTICAL;
        engine->prev_depth = HSTEX_IGNORE_DEPTH;
        int status = 0;
        /* The page's insertions are added to whatever the box of the class
           already holds: the output routine is expected to empty it. */
        const struct hstex_box *standing = &engine->boxes[number];
        if (standing->kind == HSTEX_BOX_VLIST) {
            for (uint32_t item = 0U; status == 0 && item < standing->node_count;
                 ++item) {
                if ((size_t)standing->node_start + item >=
                    engine->list_item_count) {
                    break;
                }
                status = append_vbox_item(
                    engine, engine->list_items[standing->node_start + item],
                    error, error_capacity);
            }
        }
        const struct hstex_page_insert *record =
            page_insert_of(engine, number, false, error, error_capacity);
        bool past_split = false;
        for (size_t at = index; status == 0 && at < count; ++at) {
            uint32_t other = items[at];
            if (other == 0U || (size_t)other > engine->node_count ||
                engine->nodes[other - 1U].kind != HSTEX_NODE_INSERT ||
                engine->nodes[other - 1U].value.insert.number != number) {
                continue;
            }
            if (past_split) {
                /* Nothing of this class fitted after the one that had to be
                   split, so this insertion waits for the next page. */
                continue;
            }
            uint32_t start = engine->nodes[other - 1U].value.insert.node_start;
            uint32_t held_count =
                engine->nodes[other - 1U].value.insert.node_count;
            if (record != NULL && record->split && record->broken == other) {
                held_count = (uint32_t)record->break_at < held_count
                                 ? (uint32_t)record->break_at
                                 : held_count;
                past_split = true;
            }
            for (uint32_t item = 0U; status == 0 && item < held_count; ++item) {
                if ((size_t)start + item >= engine->list_item_count) {
                    break;
                }
                status = append_vbox_item(engine, engine->list_items[start + item],
                                          error, error_capacity);
            }
        }
        struct hstex_box packed = {0};
        if (status == 0) {
            status = finalize_vbox(engine, &builder, false, false, 0, &packed,
                                   error, error_capacity);
        }
        free(builder.node_identifiers);
        engine->active_vbox_builder = previous;
        engine->mode = previous_mode;
        engine->prev_depth = enclosing_depth;
        if (status != 0) {
            return -1;
        }
        if (assign_box(engine, number, packed, true, error, error_capacity) !=
            0) {
            return -1;
        }
    }
    return 0;
}

/* What the page could not take of its insertions: the remainder of one that
   had to be split, pruned and packed again, and any insertion of that class
   that came after it. They go back to the front of the contribution list, and
   how many there are is what \insertpenalties reports to the output routine.
   See docs/DECISIONS.md, an-insertion-that-does-not-fit. */
static int hold_over_insertions(struct hstex_engine *engine,
                                const uint32_t *items, size_t count,
                                uint32_t **held, size_t *held_count,
                                char *error, size_t error_capacity)
{
    size_t capacity = 0U;
    *held = NULL;
    *held_count = 0U;
    for (size_t index = 0U; index < count; ++index) {
        uint32_t identifier = items[index];
        if (identifier == 0U || (size_t)identifier > engine->node_count ||
            engine->nodes[identifier - 1U].kind != HSTEX_NODE_INSERT) {
            continue;
        }
        uint16_t number = engine->nodes[identifier - 1U].value.insert.number;
        const struct hstex_page_insert *record =
            page_insert_of(engine, number, false, error, error_capacity);
        if (record == NULL || !record->split) {
            continue;
        }
        uint32_t waiting = 0U;
        if (record->broken == identifier) {
            struct hstex_node broken = engine->nodes[identifier - 1U];
            size_t at = record->break_at;
            if (at >= broken.value.insert.node_count) {
                continue;
            }
            size_t rest_count = broken.value.insert.node_count - at;
            uint32_t *rest = calloc(rest_count, sizeof(*rest));
            if (rest == NULL) {
                free(*held);
                *held = NULL;
                return set_error(error, error_capacity,
                                 "insertion allocation failed");
            }
            memcpy(rest,
                   engine->list_items + broken.value.insert.node_start + at,
                   rest_count * sizeof(*rest));
            struct hstex_glue standing =
                engine->glue_parameters[HSTEX_GLUE_SPLIT_TOP_SKIP];
            engine->glue_parameters[HSTEX_GLUE_SPLIT_TOP_SKIP] =
                insert_detail_of(engine, &broken).split_top_skip;
            struct hstex_box packed = {0};
            int status = prune_split_top(engine, rest, rest_count, &packed,
                                         error, error_capacity);
            engine->glue_parameters[HSTEX_GLUE_SPLIT_TOP_SKIP] = standing;
            free(rest);
            if (status != 0) {
                free(*held);
                *held = NULL;
                return -1;
            }
            if (packed.kind == HSTEX_BOX_VOID) {
                continue;
            }
            struct hstex_node node = broken;
            node.height = packed.height + packed.depth;
            node.value.insert.node_start = packed.node_start;
            node.value.insert.node_count = packed.node_count;
            if (store_node(engine, &node, &waiting, error, error_capacity) !=
                0) {
                free(*held);
                *held = NULL;
                return -1;
            }
        } else {
            /* One that came after the split: it waits as it stands. */
            bool after = false;
            for (size_t earlier = 0U; !after && earlier < index; ++earlier) {
                after = items[earlier] == record->broken;
            }
            if (!after) {
                continue;
            }
            waiting = identifier;
        }
        if (*held_count == capacity) {
            size_t grown_capacity = capacity == 0U ? 4U : capacity * 2U;
            uint32_t *grown =
                realloc(*held, grown_capacity * sizeof(*grown));
            if (grown == NULL) {
                free(*held);
                *held = NULL;
                return set_error(error, error_capacity,
                                 "insertion allocation failed");
            }
            *held = grown;
            capacity = grown_capacity;
        }
        (*held)[(*held_count)++] = waiting;
    }
    return 0;
}

static int fire_up(struct hstex_engine *engine, size_t from, char *error,
                   size_t error_capacity)
{
    struct hstex_vbox_builder *page = engine->page_builder;
    struct hstex_vbox_builder *contributions = engine->contribution_builder;
    size_t split = engine->best_page_break;
    if (split > page->count) {
        split = page->count;
    }
    /* THE PENALTY THE PAGE BROKE AT IS SPENT. \outputpenalty takes its
       value, and the node itself is set to ten thousand so that it can
       never be a breakpoint again: the material goes back to the
       contribution list with the penalty still in it, and without this the
       next page breaks at the same place for ever. Measured with a routine
       that \unvbox255es its page: the reference weighs the -5000 once and
       then reports `\outputpenalty' as 10000 on the page after, where hstex
       weighed it twice and reported -5000 again. */
    uint32_t broke_at =
        split < page->count
            ? page->node_identifiers[split]
            : (from < contributions->count
                   ? contributions->node_identifiers[from]
                   : 0U);
    if (broke_at != 0U && (size_t)broke_at <= engine->node_count &&
        engine->nodes[broke_at - 1U].kind == HSTEX_NODE_PENALTY &&
        engine->nodes[broke_at - 1U].value.penalty ==
            engine->best_page_penalty) {
        engine->nodes[broke_at - 1U].value.penalty = HSTEX_INFINITE_PENALTY;
    }
    /* What follows the break, and whatever has not been moved yet, goes
       back to the front of the contribution list. */
    size_t leftover = page->count - split;
    size_t waiting = contributions->count > from ? contributions->count - from
                                                 : 0U;
    uint32_t *returned = NULL;
    size_t returned_count = leftover + waiting;
    if (returned_count != 0U) {
        returned = calloc(returned_count, sizeof(*returned));
        if (returned == NULL) {
            return set_error(error, error_capacity,
                             "page break allocation failed");
        }
        memcpy(returned, page->node_identifiers + split,
               leftover * sizeof(*returned));
        memcpy(returned + leftover, contributions->node_identifiers + from,
               waiting * sizeof(*returned));
    }

    struct hstex_vbox_builder shipped = {0};
    struct hstex_vbox_builder *previous = engine->active_vbox_builder;
    engine->active_vbox_builder = &shipped;
    /* A list built here is not the one \prevdepth belongs to. */
    int32_t enclosing_depth = engine->prev_depth;
    engine->prev_depth = HSTEX_IGNORE_DEPTH;
    int status = 0;
    /* \holdinginserts leaves the insertions where they are, nodes and all,
       for the output routine to deal with; see docs/DECISIONS.md,
       an-insertion-that-does-not-fit. */
    bool holding =
        engine->integer_parameters[HSTEX_INTEGER_HOLDING_INSERTS] > 0;
    for (size_t index = 0U; status == 0 && index < split; ++index) {
        uint32_t held = page->node_identifiers[index];
        /* An insertion is not part of the page: its list goes into the box
           of its class, and the node itself is left out. See
           docs/DECISIONS.md, insertions. */
        if (!holding && held != 0U && (size_t)held <= engine->node_count &&
            engine->nodes[held - 1U].kind == HSTEX_NODE_INSERT) {
            continue;
        }
        status = append_vbox_item(engine, held, error, error_capacity);
    }
    uint32_t *unplaced = NULL;
    size_t unplaced_count = 0U;
    if (status == 0 && !holding) {
        status = collect_page_insertions(engine, page->node_identifiers, split,
                                         error, error_capacity);
    }
    if (status == 0 && !holding) {
        status = hold_over_insertions(engine, page->node_identifiers, split,
                                      &unplaced, &unplaced_count, error,
                                      error_capacity);
    }
    struct hstex_box packed = {0};
    if (status == 0) {
        int32_t limit = engine->dimen_parameters[HSTEX_DIMEN_BOX_MAX_DEPTH];
        engine->dimen_parameters[HSTEX_DIMEN_BOX_MAX_DEPTH] =
            engine->dimen_parameters[HSTEX_DIMEN_MAX_DEPTH];
        /* The page is packed to the size the builder chose and is never
           reported on for it: the reference lifts \vbadness and \vfuzz out
           of the way while it does this one, so a page that came out short
           of \vsize says nothing. */
        bool previous_quiet = engine->packing_quietly;
        engine->packing_quietly = true;
        status = finalize_vbox(engine, &shipped, true, false,
                               engine->best_page_size, &packed, error,
                               error_capacity);
        engine->packing_quietly = previous_quiet;
        engine->dimen_parameters[HSTEX_DIMEN_BOX_MAX_DEPTH] = limit;
    }
    free(shipped.node_identifiers);
    engine->active_vbox_builder = previous;
    engine->prev_depth = enclosing_depth;
    if (status != 0) {
        free(returned);
        free(unplaced);
        return -1;
    }
    /* WHAT THE PAGE COULD NOT TAKE OF ITS INSERTIONS IS HELD OVER ON THE
       PAGE ITSELF, not among the contributions: \showlists writes it under
       `### current page: (held over for next output)' while the routine
       runs. It is counted for the routine as \insertpenalties. See
       docs/DECISIONS.md, insertions-held-over. */
    engine->page_integers[HSTEX_PAGE_INSERT_PENALTIES] =
        (int32_t)unplaced_count;

    /* The marks of the page just shipped: what it ended with becomes
       \topmark for the next one, and the first and last marks in it are
       \firstmark and \botmark. A page with no marks keeps all three at what
       the page before ended with. See docs/DECISIONS.md, marks. */
    for (size_t index = 0U; index < engine->mark_class_count; ++index) {
        struct hstex_mark_class *entry = &engine->mark_classes[index];
        if (entry->bot != 0U) {
            entry->top = entry->bot;
            entry->first = 0U;
        }
    }
    for (size_t index = 0U; index < split; ++index) {
        uint32_t held = page->node_identifiers[index];
        if (held == 0U || (size_t)held > engine->node_count ||
            engine->nodes[held - 1U].kind != HSTEX_NODE_MARK) {
            continue;
        }
        const struct hstex_node *node = &engine->nodes[held - 1U];
        struct hstex_mark_class *entry =
            mark_class_of(engine, node->value.mark.class_number, true, error,
                          error_capacity);
        if (entry == NULL) {
            return -1;
        }
        if (entry->first == 0U) {
            entry->first = node->value.mark.tokens;
        }
        entry->bot = node->value.mark.tokens;
    }
    for (size_t index = 0U; index < engine->mark_class_count; ++index) {
        struct hstex_mark_class *entry = &engine->mark_classes[index];
        if (entry->first == 0U) {
            entry->first = entry->top;
        }
    }
    int32_t penalty = engine->best_page_penalty;
    engine->page_last_taken = false;
    page->count = 0U;
    page->extent = 0;
    page->trailing_depth = 0;
    page->width = 0;
    contributions->count = 0U;
    contributions->extent = 0;
    contributions->trailing_depth = 0;
    contributions->width = 0;
    forget_page_break(engine);
    if (returned_count != 0U) {
        if (reserve_vbox_items(contributions, returned_count, error,
                               error_capacity) != 0) {
            free(returned);
            return -1;
        }
        memcpy(contributions->node_identifiers, returned,
               returned_count * sizeof(*returned));
        contributions->count = returned_count;
    }
    free(returned);
    if (unplaced_count != 0U) {
        if (reserve_vbox_items(page, unplaced_count, error,
                               error_capacity) != 0) {
            free(unplaced);
            return -1;
        }
        memcpy(page->node_identifiers, unplaced,
               unplaced_count * sizeof(*unplaced));
        page->count = unplaced_count;
    }
    free(unplaced);
    engine->held_over_inserts = unplaced_count;

    /* \box255 is the page builder's own; a document that left something in
       it is told so, and what it left is thrown away. */
    if (engine->boxes[255].kind != HSTEX_BOX_VOID) {
        static const char *const help[] = {
            "You shouldn't use \\box255 except in \\output routines.",
            "Proceed, and I'll discard its present contents.", NULL};
        tex_error(engine, help, "\\box255 is not void");
        report_deleted_box(engine, &engine->boxes[255]);
    }
    if (assign_box(engine, 255U, packed, true, error, error_capacity) != 0 ||
        assign_integer_parameter(engine,
                                 (uint32_t)HSTEX_INTEGER_OUTPUT_PENALTY,
                                 penalty, true, error, error_capacity) != 0) {
        return -1;
    }
    uint32_t routine = engine->token_parameters[HSTEX_TOKEN_OUTPUT];
    const struct hstex_token_list *list =
        routine == 0U ? NULL : token_list_by_identifier(engine, routine);
    if (list != NULL && list->count != 0U &&
        engine->page_integers[HSTEX_PAGE_DEAD_CYCLES] >=
            engine->integer_parameters[HSTEX_INTEGER_MAX_DEAD_CYCLES]) {
        /* The reference complains and then ships the page itself, which is
           how a routine that never ships still gets its pages out. */
        static const char *const help[] = {
            "I've concluded that your \\output is awry; it never does a",
            "\\shipout, so I'm shipping \\box255 out myself. Next time",
            "increase \\maxdeadcycles if you want me to be more patient!",
            NULL};
        tex_error(engine, help, "Output loop---%d consecutive dead cycles",
                  engine->page_integers[HSTEX_PAGE_DEAD_CYCLES]);
        engine->page_integers[HSTEX_PAGE_DEAD_CYCLES] = 0;
        return ship_out_box(engine, 255U, error, error_capacity);
    }
    engine->page_integers[HSTEX_PAGE_DEAD_CYCLES] += 1;
    if (list == NULL || list->count == 0U) {
        /* An empty \output means \shipout\box255. */
        return ship_out_box(engine, 255U, error, error_capacity);
    }
    uint32_t level_before_output = engine->group_level;
    /* The routine's own group. The `}' that closes it ends the routine,
       whatever is left of the routine's text. */
    if (begin_group(engine, HSTEX_GROUP_OUTPUT, error, error_capacity) != 0) {
        return -1;
    }
    engine->output_group_closed = false;
    /* A paragraph may begin inside the routine, so the shape one would take
       is cleared here -- INSIDE the routine's group, so that what the
       document set is saved and comes back when the routine ends.
       \tracingrestores shows the four coming back. */
    if (normal_paragraph(engine, error, error_capacity) != 0) {
        return -1;
    }
    /* The routine runs in internal vertical mode, not the vertical mode the
       page builder was in. Measured through \tracingcommands, which names
       the mode where it changes: an \output of `{\count9=1 \shipout\box255
       \count9=2 }' draws {internal vertical mode: \count} at its first
       command and {vertical mode: \message} at the next command after it. */
    enum hstex_mode previous_output_mode = engine->mode;
    bool previous_output_inner = engine->inner_mode;
    /* And it knows nothing of a paragraph that may be standing outside it:
       the routine can be fired while one is being filled -- a display right
       before the page breaks leaves one -- and a paragraph the ROUTINE
       begins is the only one its own end may wind up. */
    bool previous_output_building = engine->building_paragraph;
    struct hstex_hbox_builder *previous_output_paragraph =
        engine->paragraph_builder;
    engine->building_paragraph = false;
    engine->paragraph_builder = NULL;
    /* And it builds a VERTICAL LIST OF ITS OWN. What \unvbox255 puts in it
       does not join the contributions where they stand: when the routine
       ends, its list goes back to the FRONT of the contribution list, in
       front of whatever the page gave back rather than behind it. */
    struct hstex_vbox_builder made = {0};
    struct hstex_vbox_builder *previous_output_builder =
        engine->active_vbox_builder;
    struct hstex_hbox_builder *previous_output_hbox =
        engine->active_hbox_builder;
    int32_t previous_output_depth = engine->prev_depth;
    /* And its list has had no paragraphs: a level of the nest starts
       counting lines from nought, whatever the level under it stands at.
       See docs/DECISIONS.md, where-a-line-count-starts-again. */
    int32_t previous_output_graf = engine->prev_graf;
    /* The level is pushed BEFORE the mode changes, so that the level under
       it keeps the mode the page builder was in: \showlists run inside the
       routine calls the outer list `vertical mode' and not an internal one. */
    if (nest_push(engine, error, error_capacity) != 0) {
        return -1;
    }
    engine->mode = HSTEX_MODE_VERTICAL;
    engine->inner_mode = true;
    engine->nest[engine->nest_count - 1U].output_routine = true;
    engine->active_vbox_builder = &made;
    engine->active_hbox_builder = NULL;
    engine->prev_depth = HSTEX_IGNORE_DEPTH;
    engine->prev_graf = 0;
    engine->output_active = true;
    struct hstex_source_location location = {0};
    if (hstex_source_push_boundary(&engine->sources, error, error_capacity) !=
            0 ||
        hstex_source_push_tokens(&engine->sources, list->tokens, list->count,
                                 location, error, error_capacity) != 0) {
        engine->output_active = false;
        return -1;
    }
    hstex_source_name_top(&engine->sources,
                          (uint8_t)HSTEX_TOKEN_SOURCE_TOKEN_PARAMETER,
                          (uint32_t)HSTEX_TOKEN_OUTPUT);
    trace_token_parameter(engine, (size_t)HSTEX_TOKEN_OUTPUT);
    /* The routine's opening brace is part of its list, and is READ rather
       than obeyed: the reference does not trace it, where it does trace the
       closing one. A list that does not begin with one -- \output taken from
       a \toks register, which keeps no braces -- draws `Missing { inserted'
       here, which is what this scan is for. */
    status = scan_left_brace(engine, error, error_capacity);
    if (status != 0) {
        status = -1;
    }
    for (;;) {
        hstex_token token = 0U;
        struct hstex_source_location where;
        enum hstex_engine_result result = hstex_engine_next_output(
            engine, &token, &where, error, error_capacity);
        if (result == HSTEX_ENGINE_EOF) {
            break;
        }
        if (result == HSTEX_ENGINE_ERROR) {
            status = -1;
            break;
        }
        status = handle_vertical_list_token(engine, token, where, error,
                                            error_capacity);
        if (status != 0) {
            break;
        }
    }
    if (status == 0 && engine->output_group_closed &&
        engine->output_group_unbalanced) {
        /* Only where the routine's braces did not come out even is what is
           left of its text dropped; a `}' the routine's own text ends with
           is read where it stands. */
        hstex_token spare = 0U;
        struct hstex_source_location whence;
        while (raw_next(engine, &spare, &whence, error, error_capacity) ==
               HSTEX_ENGINE_TOKEN) {
        }
    }
    engine->output_group_closed = false;
    engine->output_group_unbalanced = false;
    if (status == 0 && engine->building_paragraph) {
        status = finish_paragraph_line(engine, NULL, error, error_capacity);
    }
    if (hstex_source_pop_boundary(&engine->sources, error, error_capacity) !=
        0) {
        status = -1;
    }
    engine->output_active = false;
    /* \insertpenalties counts the insertions the page could not take while
       the routine is running, and nothing once it has finished: the next
       page is weighed with it at nought. Measured through \showthe. */
    engine->page_integers[HSTEX_PAGE_INSERT_PENALTIES] = 0;
    engine->mode = previous_output_mode;
    engine->inner_mode = previous_output_inner;
    engine->building_paragraph = previous_output_building;
    engine->paragraph_builder = previous_output_paragraph;
    engine->active_vbox_builder = previous_output_builder;
    engine->active_hbox_builder = previous_output_hbox;
    engine->prev_depth = previous_output_depth;
    engine->prev_graf = previous_output_graf;
    nest_pop(engine);
    /* The routine's own closing brace ends the group, and is traced like any
       other. A list that ran out before it did leaves the group open, so
       whatever is still standing is closed here. */
    while (engine->group_level > level_before_output) {
        if (end_group(engine, error, error_capacity) < 0) {
            status = -1;
            break;
        }
    }
    if (status == 0) {
        /* The routine's own list goes on the page BEHIND the insertions the
           page could not take, and then the whole page in front of what was
           waiting among the contributions. */
        struct hstex_vbox_builder *held = engine->page_builder;
        struct hstex_vbox_builder *queue = engine->contribution_builder;
        if (made.count != 0U) {
            if (reserve_vbox_items(held, held->count + made.count, error,
                                   error_capacity) != 0) {
                status = -1;
            } else {
                memcpy(held->node_identifiers + held->count,
                       made.node_identifiers,
                       made.count * sizeof(*made.node_identifiers));
                held->count += made.count;
            }
        }
        if (status == 0 && held->count != 0U) {
            if (reserve_vbox_items(queue, queue->count + held->count, error,
                                   error_capacity) != 0) {
                status = -1;
            } else {
                memmove(queue->node_identifiers + held->count,
                        queue->node_identifiers,
                        queue->count * sizeof(*queue->node_identifiers));
                memcpy(queue->node_identifiers, held->node_identifiers,
                       held->count * sizeof(*held->node_identifiers));
                queue->count += held->count;
                held->count = 0U;
                held->extent = 0;
                held->trailing_depth = 0;
                held->width = 0;
            }
        }
    }
    engine->held_over_inserts = 0U;
    free(made.node_identifiers);
    if (status == 0 && engine->boxes[255].kind != HSTEX_BOX_VOID) {
        /* The reference names it and throws the box away, which is what
           lets the next page be built at all. */
        static const char *const help[] = {
            "Your \\output commands should empty \\box255,",
            "e.g., by saying `\\shipout\\box255'.",
            "Proceed; I'll discard its present contents.", NULL};
        tex_error(engine, help,
                  "Output routine didn't use all of \\box255");
        report_deleted_box(engine, &engine->boxes[255]);
        struct hstex_box empty = {0};
        empty.kind = HSTEX_BOX_VOID;
        status = assign_box(engine, 255U, empty, true, error, error_capacity);
    }
    return status;
}

/* Move what is waiting on the contribution list onto the current page,
   keeping the page totals and firing the output routine where the reference
   fires it. See docs/DECISIONS.md, the-page-builder. */
static int build_page(struct hstex_engine *engine, char *error,
                      size_t error_capacity)
{
    struct hstex_vbox_builder *contributions = engine->contribution_builder;
    struct hstex_vbox_builder *page = engine->page_builder;
    if (contributions == NULL || page == NULL || engine->output_active) {
        return 0;
    }
    while (contributions->count != 0U) {
        size_t index = 0U;
        bool fired = false;
        for (; index < contributions->count; ++index) {
            uint32_t identifier = contributions->node_identifiers[index];
            if (identifier == 0U || (size_t)identifier > engine->node_count) {
                continue;
            }
            struct hstex_node node = engine->nodes[identifier - 1U];
            /* Every node the page builder takes is remembered, discarded or
               not, because it is what \lastnodetype and its relatives
               report; see docs/DECISIONS.md, the-last-node-of-a-page. */
            engine->page_last_node = node;
            engine->page_last_taken = true;
            bool is_box =
                node.kind == HSTEX_NODE_RULE || node.kind == HSTEX_NODE_LIST;
            if (node.kind == HSTEX_NODE_WHATSIT ||
                node.kind == HSTEX_NODE_MARK) {
                /* A whatsit or a mark joins the page wherever it stands and
                   settles nothing; see docs/DECISIONS.md,
                   whatsits-on-an-empty-page and marks. */
            } else if (node.kind == HSTEX_NODE_INSERT) {
                /* An insertion joins the page too, and takes room away from
                   what the page has left for its text. See
                   docs/DECISIONS.md, insertions and
                   an-insertion-that-does-not-fit. */
                if (!engine->page_frozen) {
                    reset_page_state(engine);
                    engine->page_dimens[HSTEX_PAGE_GOAL] =
                        engine->dimen_parameters[HSTEX_DIMEN_VSIZE];
                    engine->page_frozen = true;
                    trace_page_goal(engine);
                }
                uint16_t number = node.value.insert.number;
                /* The class's own box is where the insertion will end up, so
                   it may not already hold an hbox. This is the PAGE
                   BUILDER's complaint, not \insert's: measured, the
                   `%% goal height=' the page draws as it freezes comes
                   FIRST, and the fault after it, even where both are drawn
                   by the same \insert. What is thrown away is the box's
                   present contents, shown as they go, and not the
                   insertion. */
                if ((size_t)number < engine->count_capacity &&
                    engine->boxes[number].kind == HSTEX_BOX_HLIST) {
                    static const char *const help[] = {
                        "Tut tut: You're trying to \\insert into a",
                        "\\box register that now contains an \\hbox.",
                        "Proceed, and I'll discard its present contents.",
                        NULL};
                    tex_error(engine, help,
                              "Insertions can only be added to a vbox");
                    struct hstex_box standing = engine->boxes[number];
                    report_deleted_box(engine, &standing);
                    struct hstex_box empty = {0};
                    if (assign_box(engine, number, empty, true, error,
                                   error_capacity) != 0) {
                        return -1;
                    }
                    /* Storing may have moved the arena. */
                    node = engine->nodes[identifier - 1U];
                }
                int32_t factor = engine->counts[number];
                struct hstex_page_insert *record =
                    page_insert_of(engine, number, false, error,
                                   error_capacity);
                if (record == NULL) {
                    record = page_insert_of(engine, number, true, error,
                                            error_capacity);
                    if (record == NULL) {
                        return -1;
                    }
                    /* The correction glue of a class may not shrink without
                       limit: the page's own shrink is what a break is judged
                       by, and an infinite one would make every break look
                       perfect. The reference says so and goes on with it
                       taken as finite, leaving the register itself alone --
                       measured,
                       measured, \skip100 still reads `minus 1.0fil'
                       afterwards. */
                    if (engine->glues[number].shrink_order != 0U &&
                        engine->glues[number].shrink != 0) {
                        /* Nothing to shrink is no shrinkage, whatever order
                           it claims; glue read from a document has that
                           settled already, but glue reached by arithmetic
                           need not have. */
                        static const char *const help[] = {
                            "The correction glue for page breaking with "
                            "insertions",
                            "must have finite shrinkability. But you may "
                            "proceed,",
                            "since the offensive shrinkability has been made "
                            "finite.", NULL};
                        tex_error(engine, help,
                                  "Infinite glue shrinkage inserted from "
                                  "\\skip%u",
                                  (unsigned int)number);
                    }
                    /* The glue of the class, and room for whatever the box
                       of the class already holds: the page has to carry that
                       too. */
                    const struct hstex_box *standing = &engine->boxes[number];
                    record->held = standing->kind == HSTEX_BOX_VOID
                                       ? 0
                                       : standing->height + standing->depth;
                    engine->page_dimens[HSTEX_PAGE_GOAL] -=
                        (int32_t)(insertion_size(record->held, factor) +
                                  engine->glues[number].width);
                    /* Its stretch and shrink go on the PAGE, which is what
                       the badness of a break is judged by. Measured:
                       \skip100=5pt plus 3filll minus 9pt makes the page read
                       `t=0.0 plus 3.0filll minus 9.0 g=91.0' the moment the
                       first insertion of the class arrives, and the second
                       insertion of the same class adds nothing more. An
                       infinite shrink counts as its amount, the message
                       above having just made it finite. */
                    const struct hstex_glue *correction =
                        &engine->glues[number];
                    if (correction->stretch_order <= 3U) {
                        engine->page_dimens[HSTEX_PAGE_STRETCH +
                                            correction->stretch_order] +=
                            correction->stretch;
                    }
                    engine->page_dimens[HSTEX_PAGE_SHRINK] +=
                        correction->shrink;
                }
                int32_t size = packed_dimen(node.height);
                int64_t wanted = insertion_size(size, factor);
                int64_t room = (int64_t)engine->page_dimens[HSTEX_PAGE_GOAL] -
                               engine->page_dimens[HSTEX_PAGE_TOTAL] -
                               engine->page_dimens[HSTEX_PAGE_DEPTH] +
                               engine->page_dimens[HSTEX_PAGE_SHRINK];
                if (record->split) {
                    /* This class has already had to be split on this page,
                       so nothing more of it can go here. */
                    engine->page_integers[HSTEX_PAGE_INSERT_PENALTIES] +=
                        insert_detail_of(engine, &node).float_cost;
                } else if ((wanted <= 0 || wanted <= room) &&
                           (int64_t)size + record->held <=
                               engine->dimens[number]) {
                    engine->page_dimens[HSTEX_PAGE_GOAL] -= (int32_t)wanted;
                    record->held += size;
                } else {
                    /* Only part of it can stay: find how much room there is
                       for the class and break the list there. */
                    int64_t allowed = INT64_MAX;
                    if (factor > 0) {
                        allowed = (int64_t)engine->page_dimens[HSTEX_PAGE_GOAL] -
                                  engine->page_dimens[HSTEX_PAGE_TOTAL] -
                                  engine->page_dimens[HSTEX_PAGE_DEPTH];
                        if (factor != 1000) {
                            /* Divided by the factor FIRST and then taken a
                               thousand times, which is not the same number as
                               the other way about. Measured: a hundred points
                               of room at \count200=333 leaves 300.29297pt for
                               the class, not the 300.3003pt that multiplying
                               first gives. */
                            allowed = allowed / factor * 1000;
                        }
                    }
                    int64_t limit = (int64_t)engine->dimens[number] -
                                    record->held;
                    if (allowed > limit) {
                        allowed = limit;
                    }
                    if (allowed < -INT64_C(1073741823)) {
                        allowed = -INT64_C(1073741823);
                    }
                    if (allowed > INT64_C(1073741823)) {
                        allowed = INT64_C(1073741823);
                    }
                    int32_t reached = 0;
                    int32_t at_penalty = 0;
                    size_t at = vertical_break_measured(
                        engine, engine->list_items + node.value.insert.node_start,
                        node.value.insert.node_count, (int32_t)allowed,
                        insert_detail_of(engine, &node).split_max_depth, &reached,
                        &at_penalty);
                    trace_page_split(engine, number, (int32_t)allowed, reached,
                                     at_penalty);
                    /* What the break was worth is carried by the page, where
                       it enters the cost of every break after it. Measured
                       through \showthe\insertpenalties. */
                    engine->page_integers[HSTEX_PAGE_INSERT_PENALTIES] +=
                        at_penalty;
                    record->split = true;
                    record->broken = identifier;
                    record->break_at = (uint32_t)at;
                    record->held += reached;
                    engine->page_dimens[HSTEX_PAGE_GOAL] -=
                        (int32_t)insertion_size(reached, factor);
                }
            } else if (page_is_empty(engine)) {
                if (!is_box) {
                    continue;
                }
                /* The first box settles the page's goal, unless an
                   insertion has settled it already, and gets \topskip glue
                   in front of it, shortened by however tall it is. */
                if (!engine->page_frozen) {
                    reset_page_state(engine);
                    engine->page_dimens[HSTEX_PAGE_GOAL] =
                        engine->dimen_parameters[HSTEX_DIMEN_VSIZE];
                    engine->page_frozen = true;
                    trace_page_goal(engine);
                }
                engine->page_has_box = true;
                /* The \topskip glue in front of the first box is a legal
                   breakpoint like any other glue, if what already stands on
                   the page permits one. Measured: a \write or a \mark
                   before the first box draws
                   `% t=0.0 g=50.0 b=10000 p=0 c=100000#' where a page with
                   nothing on it draws no such line, and where a penalty
                   before the first box -- which is discarded -- draws none
                   either. */
                if (page->count != 0U) {
                    uint32_t standing =
                        page->node_identifiers[page->count - 1U];
                    enum hstex_node_kind before =
                        engine->nodes[standing - 1U].kind;
                    if (before != HSTEX_NODE_GLUE &&
                        before != HSTEX_NODE_KERN &&
                        before != HSTEX_NODE_PENALTY) {
                        int32_t badness = 0;
                        int64_t cost = page_break_cost(engine, 0, &badness);
                        trace_page_cost(engine, 0, badness, cost,
                                        cost <= engine->least_page_cost);
                        if (cost <= engine->least_page_cost) {
                            engine->best_page_break = page->count;
                            engine->best_page_penalty = HSTEX_INFINITE_PENALTY;
                            engine->best_page_size =
                                engine->page_dimens[HSTEX_PAGE_GOAL];
                            engine->least_page_cost = (int32_t)cost;
                        }
                        if (cost == HSTEX_AWFUL_BADNESS) {
                            if (fire_up(engine, index, error,
                                        error_capacity) != 0) {
                                return -1;
                            }
                            fired = true;
                            break;
                        }
                    }
                }
                struct hstex_glue top =
                    engine->glue_parameters[HSTEX_GLUE_TOP_SKIP];
                int32_t height = packed_dimen(node.height);
                top.width = top.width > height ? top.width - height : 0;
                struct hstex_node glue = {
                    .kind = HSTEX_NODE_GLUE,
                    .width = top.width,
                    .value.glue = {
                        .stretch = top.stretch,
                        .shrink = top.shrink,
                        .stretch_order = top.stretch_order,
                        .shrink_order = top.shrink_order,
                        .parameter = 1U + (uint8_t)HSTEX_GLUE_TOP_SKIP,
                    },
                };
                uint32_t placed = 0U;
                if (reserve_vbox_items(page, page->count + 1U, error,
                                       error_capacity) != 0 ||
                    store_node(engine, &glue, &placed, error,
                               error_capacity) != 0) {
                    return -1;
                }
                page->node_identifiers[page->count++] = placed;
                engine->page_dimens[HSTEX_PAGE_TOTAL] = top.width;
                engine->page_dimens[HSTEX_PAGE_STRETCH + top.stretch_order] +=
                    top.stretch;
                engine->page_dimens[HSTEX_PAGE_SHRINK] += top.shrink;
                /* Storing the glue may have moved the arena. */
                node = engine->nodes[identifier - 1U];
            } else {
                /* Glue after something that cannot be discarded, a kern
                   before glue, and any penalty are places the page may
                   break. */
                bool legal = false;
                int32_t penalty = 0;
                if (node.kind == HSTEX_NODE_GLUE) {
                    uint32_t before = page->node_identifiers[page->count - 1U];
                    enum hstex_node_kind kind =
                        engine->nodes[before - 1U].kind;
                    legal = kind != HSTEX_NODE_GLUE &&
                            kind != HSTEX_NODE_KERN &&
                            kind != HSTEX_NODE_PENALTY;
                } else if (node.kind == HSTEX_NODE_KERN) {
                    if (index + 1U < contributions->count) {
                        uint32_t after =
                            contributions->node_identifiers[index + 1U];
                        legal = after != 0U &&
                                (size_t)after <= engine->node_count &&
                                engine->nodes[after - 1U].kind ==
                                    HSTEX_NODE_GLUE;
                    }
                } else if (node.kind == HSTEX_NODE_PENALTY) {
                    /* A penalty of ten thousand forbids the break rather
                       than costing that much. */
                    penalty = node.value.penalty;
                    legal = penalty < HSTEX_INFINITE_PENALTY;
                }
                if (legal) {
                    int32_t badness = 0;
                    int64_t cost =
                        page_break_cost(engine, penalty, &badness);
                    trace_page_cost(engine, penalty, badness, cost,
                                    cost <= engine->least_page_cost);
                    if (cost <= engine->least_page_cost) {
                        engine->best_page_break = page->count;
                        engine->best_page_penalty =
                            node.kind == HSTEX_NODE_PENALTY
                                ? penalty
                                : HSTEX_INFINITE_PENALTY;
                        engine->best_page_size =
                            engine->page_dimens[HSTEX_PAGE_GOAL];
                        engine->least_page_cost = (int32_t)cost;
                    }
                    if (cost == HSTEX_AWFUL_BADNESS ||
                        penalty <= -HSTEX_INFINITE_PENALTY) {
                        if (fire_up(engine, index, error, error_capacity) !=
                            0) {
                            return -1;
                        }
                        fired = true;
                        break;
                    }
                }
            }
            int64_t total = engine->page_dimens[HSTEX_PAGE_TOTAL];
            if (is_box) {
                total += engine->page_dimens[HSTEX_PAGE_DEPTH] +
                         packed_dimen(node.height);
                int32_t depth = packed_dimen(node.depth);
                int32_t limit =
                    engine->dimen_parameters[HSTEX_DIMEN_MAX_DEPTH];
                if (depth > limit) {
                    total += (int64_t)depth - limit;
                    depth = limit;
                }
                engine->page_dimens[HSTEX_PAGE_DEPTH] = depth;
            } else if (node.kind == HSTEX_NODE_GLUE ||
                       node.kind == HSTEX_NODE_KERN) {
                total += engine->page_dimens[HSTEX_PAGE_DEPTH] +
                         packed_dimen(node.width);
                engine->page_dimens[HSTEX_PAGE_DEPTH] = 0;
                if (node.kind == HSTEX_NODE_GLUE) {
                    engine->page_dimens[HSTEX_PAGE_STRETCH +
                                        node.value.glue.stretch_order] +=
                        node.value.glue.stretch;
                    /* Glue that shrinks without limit may not stand on a
                       page: the reference says so and makes it finite, and
                       what it leaves behind is the finite part. It says so
                       once for each such glue, as each reaches the page. */
                    if (node.value.glue.shrink_order != 0U) {
                        static const char *const help[] = {
                            "The page about to be output contains some infinitely",
                            "shrinkable glue, e.g., `\\vss' or `\\vskip 0pt minus 1fil'.",
                            "Such glue doesn't belong there; but you can safely proceed,",
                            "since the offensive shrinkability has been made finite.",
                            NULL};
                        tex_error(engine, help,
                                  "Infinite glue shrinkage found on current "
                                  "page");
                        node.value.glue.shrink_order = 0U;
                        if (identifier != 0U &&
                            (size_t)identifier <= engine->node_count) {
                            engine->nodes[identifier - 1U]
                                .value.glue.shrink_order = 0U;
                        }
                    }
                    engine->page_dimens[HSTEX_PAGE_SHRINK] +=
                        node.value.glue.shrink;
                }
            }
            engine->page_dimens[HSTEX_PAGE_TOTAL] =
                (int32_t)(uint32_t)(uint64_t)total;
            if (reserve_vbox_items(page, page->count + 1U, error,
                                   error_capacity) != 0) {
                return -1;
            }
            page->node_identifiers[page->count++] = identifier;
            int32_t reach = packed_dimen(node.width) + node.shift;
            if (is_box && reach > page->width) {
                page->width = reach;
            }
        }
        if (fired) {
            /* fire_up put what is left back on the contribution list. */
            continue;
        }
        contributions->count = 0U;
        contributions->extent = 0;
        contributions->trailing_depth = 0;
        contributions->width = 0;
    }
    return 0;
}

/* Page state is not saved by grouping, so these assignments bypass the save
   stack and ignore \global. */
static int scan_page_integer_assignment(struct hstex_engine *engine,
                                        int32_t index, char *error,
                                        size_t error_capacity)
{
    int32_t value = 0;
    if (index < 0 || index >= (int32_t)HSTEX_PAGE_INTEGER_COUNT) {
        return set_error(error, error_capacity,
                         "invalid page-integer assignment");
    }
    if (scan_optional_equals(engine, error, error_capacity) != 0 ||
        scan_integer(engine, &value, error, error_capacity) != 0) {
        return -1;
    }
    engine->pending_global = false;
    engine->pending_macro_flags = 0U;
    engine->page_integers[(size_t)index] = value;
    return 0;
}

static int scan_page_dimen_assignment(struct hstex_engine *engine,
                                      int32_t index, char *error,
                                      size_t error_capacity)
{
    int32_t value = 0;
    if (index < 0 || index >= (int32_t)HSTEX_PAGE_DIMEN_COUNT) {
        return set_error(error, error_capacity,
                         "invalid page-dimen assignment");
    }
    if (scan_optional_equals(engine, error, error_capacity) != 0 ||
        scan_dimension(engine, &value, error, error_capacity) != 0) {
        return -1;
    }
    engine->pending_global = false;
    engine->pending_macro_flags = 0U;
    /* An assignment to a page dimension is discarded while the page is empty;
       the value is still scanned. */
    if (!page_is_empty(engine)) {
        engine->page_dimens[(size_t)index] = value;
    }
    return 0;
}

/* Setting a dimension of a void box has no effect; the value is still
   scanned. */
static int scan_box_dimen_assignment(struct hstex_engine *engine,
                                     int32_t subtype, char *error,
                                     size_t error_capacity)
{
    int32_t index = 0;
    int32_t value = 0;
    if (scan_integer(engine, &index, error, error_capacity) != 0) {
        return -1;
    }
    if (index < 0 || (size_t)index >= engine->count_capacity) {
        return set_error(error, error_capacity,
                         "box register %d is outside 0..%zu", index,
                         engine->count_capacity - 1U);
    }
    if (scan_optional_equals(engine, error, error_capacity) != 0 ||
        scan_dimension(engine, &value, error, error_capacity) != 0) {
        return -1;
    }
    bool requested_global = engine->pending_global;
    engine->pending_global = false;
    engine->pending_macro_flags = 0U;
    struct hstex_box box = engine->boxes[(size_t)index];
    if (box.kind == HSTEX_BOX_VOID) {
        return 0;
    }
    if (subtype == (int32_t)HSTEX_BOX_DIMEN_HEIGHT) {
        box.height = value;
    } else if (subtype == (int32_t)HSTEX_BOX_DIMEN_DEPTH) {
        box.depth = value;
    } else {
        box.width = value;
    }
    return assign_box(engine, (uint32_t)index, box, requested_global, error,
                      error_capacity);
}

/* Protrusion and expansion settings belong to the font rather than to a
   group, so they bypass the save stack and \global changes nothing. */
static int scan_font_char_code_assignment(struct hstex_engine *engine,
                                          int32_t subtype, char *error,
                                          size_t error_capacity)
{
    if (subtype == (int32_t)HSTEX_FONT_CODE_TAG) {
        return set_error(error, error_capacity,
                         "the metric file's tag cannot be assigned");
    }
    uint32_t identifier = 0U;
    int32_t code = 0;
    int32_t value = 0;
    if (scan_font_identifier(engine, &identifier, error, error_capacity) != 0 ||
        scan_integer(engine, &code, error, error_capacity) != 0) {
        return -1;
    }
    if (scan_optional_equals(engine, error, error_capacity) != 0 ||
        scan_integer(engine, &value, error, error_capacity) != 0) {
        return -1;
    }
    engine->pending_global = false;
    engine->pending_macro_flags = 0U;
    struct hstex_font *font = font_by_identifier(engine, identifier);
    if (font == NULL || font->characters == NULL) {
        return set_error(error, error_capacity,
                         "font code requires a defined font");
    }
    if (code < 0 || (size_t)code >= HSTEX_FONT_CHARACTER_COUNT) {
        return set_error(error, error_capacity, "bad character code (%d)",
                         code);
    }
    struct hstex_char_metric *metric = &font->characters[(size_t)code];
    if (subtype == (int32_t)HSTEX_FONT_CODE_LEFT_PROTRUSION) {
        metric->left_protrusion = value;
    } else if (subtype == (int32_t)HSTEX_FONT_CODE_RIGHT_PROTRUSION) {
        metric->right_protrusion = value;
    } else {
        metric->expansion_factor = value;
    }
    return 0;
}

static int scan_prev_depth_assignment(struct hstex_engine *engine,
                                      char *error, size_t error_capacity)
{
    int32_t value = 0;
    if (engine->mode != HSTEX_MODE_VERTICAL) {
        /* The reference says which mode you are in and reads nothing --
           not even the `=' -- so what was to be assigned is left to be
           typeset. Measured: \prevdepth=2pt in horizontal mode leaves
           "=2pt" in the paragraph. The prefix in front of it is spent
           either way; leaving it pending made the next \par complain. */
        report_illegal_case(engine, engine->executing_token);
        engine->pending_global = false;
        engine->pending_macro_flags = 0U;
        return 0;
    }
    if (scan_optional_equals(engine, error, error_capacity) != 0 ||
        scan_dimension(engine, &value, error, error_capacity) != 0) {
        return -1;
    }
    engine->pending_global = false;
    engine->pending_macro_flags = 0U;
    engine->prev_depth = value;
    return 0;
}

static int scan_glue_parameter_assignment(struct hstex_engine *engine,
                                          int32_t parameter, char *error,
                                          size_t error_capacity)
{
    struct hstex_glue value;
    if (parameter < 0 || parameter >= (int32_t)HSTEX_GLUE_PARAMETER_COUNT) {
        return set_error(error, error_capacity,
                         "invalid glue-parameter assignment");
    }
    if (scan_optional_equals(engine, error, error_capacity) != 0 ||
        scan_glue(engine, &value, error, error_capacity) != 0) {
        return -1;
    }
    bool requested_global = engine->pending_global;
    engine->pending_global = false;
    engine->pending_macro_flags = 0U;
    return assign_glue_parameter(engine, (uint32_t)parameter, value,
                                 requested_global, error, error_capacity);
}

static int scan_muglue_parameter_assignment(struct hstex_engine *engine,
                                             int32_t parameter, char *error,
                                             size_t error_capacity)
{
    struct hstex_glue value;
    if (parameter < 0 ||
        parameter >= (int32_t)HSTEX_MUGLUE_PARAMETER_COUNT) {
        return set_error(error, error_capacity,
                         "invalid math-glue-parameter assignment");
    }
    if (scan_optional_equals(engine, error, error_capacity) != 0 ||
        scan_math_glue(engine, &value, error, error_capacity) != 0) {
        return -1;
    }
    bool requested_global = engine->pending_global;
    engine->pending_global = false;
    engine->pending_macro_flags = 0U;
    return assign_muglue_parameter(engine, (uint32_t)parameter, value,
                                   requested_global, error, error_capacity);
}

static int scan_token_list_value(struct hstex_engine *engine,
                                 uint32_t *identifier, bool wrap, char *error,
                                 size_t error_capacity)
{
    /* The register is named by the control sequence that was written, so
       a \toksdef'd one reads as itself: trip's \tokens, not \toks. */
    char named[128];
    describe_token(engine, engine->executing_token, named, sizeof(named));
    (void)snprintf(engine->scanning_text_name,
                   sizeof(engine->scanning_text_name), "text of %s", named);
    hstex_token first = 0U;
    struct hstex_source_location location;
    if (expanded_next_non_space(engine, &first, &location, error,
                                error_capacity) != HSTEX_ENGINE_TOKEN) {
        return set_error(error, error_capacity,
                         "end of input while scanning a token list");
    }
    if (hstex_token_is_control_sequence(first)) {
        int result = token_list_identifier_from_meaning(
            engine,
            hstex_engine_meaning(engine,
                                 hstex_token_control_sequence_id(first)),
            identifier, error, error_capacity);
        if (result != 0) {
            return result < 0 ? -1 : 0;
        }
    }
    if (!token_is_category(first, HSTEX_CAT_BEGIN_GROUP)) {
        return set_error(error, error_capacity,
                         "token-list assignment requires a register or braces");
    }
    struct hstex_token_vector tokens = {0};
    if (scan_balanced_group(engine, &tokens, true, engine->scanning_text_name, false, error, error_capacity) != 0) {
        vector_destroy(&tokens);
        return -1;
    }
    /* \output KEEPS ITS BRACES. The reference stores the routine's text with
       the `{' and `}' still round it -- `\output={abc}' then
       `\showthe\output' writes `{abc}', and copying it into a \toks keeps
       them -- because that is the brace the routine's group is opened by
       when it runs. An empty text keeps nothing, and a value taken from
       another register is copied as it stands. Measured all three. */
    if (wrap && tokens.count != 0U) {
        struct hstex_token_vector braced = {0};
        hstex_token opening =
            hstex_token_character((uint8_t)HSTEX_CAT_BEGIN_GROUP, (uint8_t)'{');
        hstex_token closing =
            hstex_token_character((uint8_t)HSTEX_CAT_END_GROUP, (uint8_t)'}');
        if (vector_push(&braced, opening, error, error_capacity) != 0) {
            vector_destroy(&braced);
            vector_destroy(&tokens);
            return -1;
        }
        for (size_t index = 0U; index < tokens.count; ++index) {
            if (vector_push(&braced, tokens.data[index], error,
                            error_capacity) != 0) {
                vector_destroy(&braced);
                vector_destroy(&tokens);
                return -1;
            }
        }
        if (vector_push(&braced, closing, error, error_capacity) != 0) {
            vector_destroy(&braced);
            vector_destroy(&tokens);
            return -1;
        }
        vector_destroy(&tokens);
        tokens = braced;
    }
    if (store_token_list(engine, &tokens, identifier, error, error_capacity) !=
        0) {
        vector_destroy(&tokens);
        return -1;
    }
    return 0;
}

static int scan_token_register_assignment(struct hstex_engine *engine,
                                          int32_t index, char *error,
                                          size_t error_capacity)
{
    uint32_t identifier = 0U;
    if (index < 0 || (size_t)index >= engine->count_capacity ||
        scan_optional_equals(engine, error, error_capacity) != 0 ||
        scan_token_list_value(engine, &identifier, false, error,
                              error_capacity) != 0) {
        return set_error(error, error_capacity,
                         "invalid token-register assignment");
    }
    bool requested_global = engine->pending_global;
    engine->pending_global = false;
    engine->pending_macro_flags = 0U;
    return assign_token_register(engine, (uint32_t)index, identifier,
                                 requested_global, error, error_capacity);
}

static int scan_token_family_assignment(struct hstex_engine *engine,
                                        char *error, size_t error_capacity)
{
    int32_t index = 0;
    /* A register number past the end is a fault the reference
       forgives, using zero. */
    if (scan_register_num(engine, &index,
                          (int32_t)engine->count_capacity - 1, error,
                          error_capacity) != 0) {
        return -1;
    }
    return scan_token_register_assignment(engine, index, error,
                                          error_capacity);
}

static int scan_token_parameter_assignment(struct hstex_engine *engine,
                                           int32_t parameter, char *error,
                                           size_t error_capacity)
{
    uint32_t identifier = 0U;
    if (parameter < 0 || parameter >= (int32_t)HSTEX_TOKEN_PARAMETER_COUNT ||
        scan_optional_equals(engine, error, error_capacity) != 0 ||
        scan_token_list_value(engine, &identifier,
                              parameter == (int32_t)HSTEX_TOKEN_OUTPUT, error,
                              error_capacity) != 0) {
        return set_error(error, error_capacity,
                         "invalid token-parameter assignment");
    }
    bool requested_global = engine->pending_global;
    engine->pending_global = false;
    engine->pending_macro_flags = 0U;
    return assign_token_parameter(engine, (uint32_t)parameter, identifier,
                                  requested_global, error, error_capacity);
}

enum arithmetic_variable_kind {
    ARITHMETIC_VARIABLE_COUNT = 0,
    ARITHMETIC_VARIABLE_INTEGER_PARAMETER,
    ARITHMETIC_VARIABLE_DIMEN,
    ARITHMETIC_VARIABLE_DIMEN_PARAMETER,
    ARITHMETIC_VARIABLE_PREV_DEPTH,
    ARITHMETIC_VARIABLE_GLUE,
    ARITHMETIC_VARIABLE_GLUE_PARAMETER,
    ARITHMETIC_VARIABLE_MUGLUE,
    ARITHMETIC_VARIABLE_MUGLUE_PARAMETER,
};

struct arithmetic_variable {
    enum arithmetic_variable_kind kind;
    uint32_t index;
};

/* Returns 0 for a variable the operation can work on, 1 for anything else --
   which the caller reports and forgets -- and -1 for a failure. */
static int scan_arithmetic_variable(struct hstex_engine *engine,
                                    struct arithmetic_variable *variable,
                                    hstex_token *offending, char *error,
                                    size_t error_capacity)
{
    hstex_token token = 0U;
    struct hstex_source_location location;
    *offending = 0U;
    if (expanded_next_non_space(engine, &token, &location, error,
                                error_capacity) != HSTEX_ENGINE_TOKEN) {
        return set_error(error, error_capacity,
                         "arithmetic operation requires a variable");
    }
    *offending = token;
    if (!hstex_token_is_control_sequence(token)) {
        return 1;
    }
    const struct hstex_meaning *meaning = hstex_engine_meaning(
        engine, hstex_token_control_sequence_id(token));
    if (meaning->command == HSTEX_COMMAND_COUNT_REGISTER) {
        if (meaning->value.integer < 0 ||
            (size_t)meaning->value.integer >= engine->count_capacity) {
            return set_error(error, error_capacity,
                             "invalid count-register variable");
        }
        variable->kind = ARITHMETIC_VARIABLE_COUNT;
        variable->index = (uint32_t)meaning->value.integer;
        return 0;
    }
    if (meaning->command == HSTEX_COMMAND_COUNT) {
        int32_t index = 0;
        if (scan_integer(engine, &index, error, error_capacity) != 0 || index < 0 ||
            (size_t)index >= engine->count_capacity) {
            return set_error(error, error_capacity,
                             "count variable outside supported range");
        }
        variable->kind = ARITHMETIC_VARIABLE_COUNT;
        variable->index = (uint32_t)index;
        return 0;
    }
    if (meaning->command == HSTEX_COMMAND_INTEGER_PARAMETER &&
        meaning->value.integer >= 0 &&
        meaning->value.integer < (int32_t)HSTEX_INTEGER_PARAMETER_COUNT) {
        variable->kind = ARITHMETIC_VARIABLE_INTEGER_PARAMETER;
        variable->index = (uint32_t)meaning->value.integer;
        return 0;
    }
    if (meaning->command == HSTEX_COMMAND_DIMEN_REGISTER &&
        meaning->value.integer >= 0 &&
        (size_t)meaning->value.integer < engine->count_capacity) {
        variable->kind = ARITHMETIC_VARIABLE_DIMEN;
        variable->index = (uint32_t)meaning->value.integer;
        return 0;
    }
    if (meaning->command == HSTEX_COMMAND_DIMEN) {
        int32_t index = 0;
        if (scan_integer(engine, &index, error, error_capacity) != 0 ||
            index < 0 || (size_t)index >= engine->count_capacity) {
            return set_error(error, error_capacity,
                             "dimen arithmetic target outside supported range");
        }
        variable->kind = ARITHMETIC_VARIABLE_DIMEN;
        variable->index = (uint32_t)index;
        return 0;
    }
    if (meaning->command == HSTEX_COMMAND_DIMEN_PARAMETER &&
        meaning->value.integer >= 0 &&
        meaning->value.integer < (int32_t)HSTEX_DIMEN_PARAMETER_COUNT) {
        variable->kind = ARITHMETIC_VARIABLE_DIMEN_PARAMETER;
        variable->index = (uint32_t)meaning->value.integer;
        return 0;
    }
    /* \prevdepth is NOT one of them, in any mode: the reference draws
       "You can't use `\prevdepth' after \advance" and changes nothing.
       trip line 434 writes `\advance\prevdepth' inside an \hbox. */
    if (meaning->command == HSTEX_COMMAND_SKIP_REGISTER &&
        meaning->value.integer >= 0 &&
        (size_t)meaning->value.integer < engine->count_capacity) {
        variable->kind = ARITHMETIC_VARIABLE_GLUE;
        variable->index = (uint32_t)meaning->value.integer;
        return 0;
    }
    if (meaning->command == HSTEX_COMMAND_SKIP) {
        int32_t index = 0;
        if (scan_integer(engine, &index, error, error_capacity) != 0 ||
            index < 0 || (size_t)index >= engine->count_capacity) {
            return set_error(error, error_capacity,
                             "skip arithmetic target outside supported range");
        }
        variable->kind = ARITHMETIC_VARIABLE_GLUE;
        variable->index = (uint32_t)index;
        return 0;
    }
    if (meaning->command == HSTEX_COMMAND_GLUE_PARAMETER &&
        meaning->value.integer >= 0 &&
        meaning->value.integer < (int32_t)HSTEX_GLUE_PARAMETER_COUNT) {
        variable->kind = ARITHMETIC_VARIABLE_GLUE_PARAMETER;
        variable->index = (uint32_t)meaning->value.integer;
        return 0;
    }
    if (meaning->command == HSTEX_COMMAND_MUSKIP_REGISTER &&
        meaning->value.integer >= 0 &&
        (size_t)meaning->value.integer < engine->count_capacity) {
        variable->kind = ARITHMETIC_VARIABLE_MUGLUE;
        variable->index = (uint32_t)meaning->value.integer;
        return 0;
    }
    if (meaning->command == HSTEX_COMMAND_MUSKIP) {
        int32_t index = 0;
        if (scan_integer(engine, &index, error, error_capacity) != 0 ||
            index < 0 || (size_t)index >= engine->count_capacity) {
            return set_error(error, error_capacity,
                             "muskip arithmetic target outside supported range");
        }
        variable->kind = ARITHMETIC_VARIABLE_MUGLUE;
        variable->index = (uint32_t)index;
        return 0;
    }
    if (meaning->command == HSTEX_COMMAND_MUGLUE_PARAMETER &&
        meaning->value.integer >= 0 &&
        meaning->value.integer < (int32_t)HSTEX_MUGLUE_PARAMETER_COUNT) {
        variable->kind = ARITHMETIC_VARIABLE_MUGLUE_PARAMETER;
        variable->index = (uint32_t)meaning->value.integer;
        return 0;
    }
    return 1;
}

static bool token_has_character(hstex_token token, uint8_t character)
{
    return hstex_token_is_character(token) &&
           hstex_token_character_code(token) == character;
}

static int scan_optional_by(struct hstex_engine *engine, char *error,
                            size_t error_capacity)
{
    /* A keyword is read without regard to case, `by' among them: trip line
       374 writes `By'. */
    bool matched = false;
    return try_keyword(engine, "by", &matched, error, error_capacity);
}

static bool arithmetic_variable_is_integer(
    enum arithmetic_variable_kind kind)
{
    return kind == ARITHMETIC_VARIABLE_COUNT ||
           kind == ARITHMETIC_VARIABLE_INTEGER_PARAMETER;
}

static bool arithmetic_variable_is_dimen(enum arithmetic_variable_kind kind)
{
    return kind == ARITHMETIC_VARIABLE_DIMEN ||
           kind == ARITHMETIC_VARIABLE_DIMEN_PARAMETER ||
           kind == ARITHMETIC_VARIABLE_PREV_DEPTH;
}

static bool arithmetic_variable_is_glue(enum arithmetic_variable_kind kind)
{
    return kind == ARITHMETIC_VARIABLE_GLUE ||
           kind == ARITHMETIC_VARIABLE_GLUE_PARAMETER;
}

static int arithmetic_scalar_result(struct hstex_engine *engine,
                                    int32_t current, int32_t operand,
                                    enum hstex_command operation,
                                    int64_t lower, int64_t upper,
                                    int32_t *value, char *error,
                                    size_t error_capacity)
{
    (void)error;
    (void)error_capacity;
    static const char *const help[] = {
        "I can't carry out that multiplication or division,",
        "since the result is out of range.", NULL};
    /* \advance is not checked at all: the reference lets it wrap in
       thirty-two bits and says nothing. Measured: 16000pt advanced by
       16000pt three times over comes to -17536.0pt, and \count 2000000000
       advanced by itself to -294967296. The wrap is done in unsigned
       arithmetic because the signed kind would be undefined. */
    if (operation == HSTEX_COMMAND_ADVANCE) {
        uint32_t wrapped = (uint32_t)current + (uint32_t)operand;
        *value = (int32_t)wrapped;
        (void)lower;
        (void)upper;
        return 0;
    }
    int64_t result = 0;
    if (operation == HSTEX_COMMAND_MULTIPLY) {
        result = (int64_t)current * operand;
    } else if (operand == 0) {
        /* Dividing by nothing is the same fault, in the same words. */
        tex_error(engine, help, "Arithmetic overflow");
        *value = current;
        return 0;
    } else {
        result = (int64_t)current / operand;
    }
    if (result < lower || result > upper) {
        /* Reported, and the register keeps what it had. */
        tex_error(engine, help, "Arithmetic overflow");
        *value = current;
        return 0;
    }
    *value = (int32_t)result;
    return 0;
}

static int advance_glue_component(int32_t *left, uint8_t *left_order,
                                  int32_t right, uint8_t right_order,
                                  char *error, size_t error_capacity)
{
    if (right_order > *left_order) {
        *left = right;
        *left_order = right_order;
        return 0;
    }
    if (right_order < *left_order) {
        return 0;
    }
    (void)error;
    (void)error_capacity;
    *left = (int32_t)((uint32_t)*left + (uint32_t)right);
    return 0;
}

static int advance_glue_value(struct hstex_glue *left,
                              const struct hstex_glue *right, char *error,
                              size_t error_capacity)
{
    struct hstex_glue result = *left;
    result.width = (int32_t)((uint32_t)left->width + (uint32_t)right->width);
    if (advance_glue_component(&result.stretch, &result.stretch_order,
                               right->stretch, right->stretch_order, error,
                               error_capacity) != 0 ||
        advance_glue_component(&result.shrink, &result.shrink_order,
                               right->shrink, right->shrink_order, error,
                               error_capacity) != 0) {
        return -1;
    }
    *left = result;
    return 0;
}

static int scale_glue_value(struct hstex_engine *engine,
                            struct hstex_glue *value, int32_t operand,
                            enum hstex_command operation, char *error,
                            size_t error_capacity)
{
    struct hstex_glue result = *value;
    if (arithmetic_scalar_result(engine, result.width, operand, operation,
                                 -INT64_C(1073741823),
                                 INT64_C(1073741823), &result.width, error,
                                 error_capacity) != 0 ||
        arithmetic_scalar_result(engine, result.stretch, operand, operation,
                                 -INT64_C(1073741823),
                                 INT64_C(1073741823), &result.stretch, error,
                                 error_capacity) != 0 ||
        arithmetic_scalar_result(engine, result.shrink, operand, operation,
                                 -INT64_C(1073741823),
                                 INT64_C(1073741823), &result.shrink, error,
                                 error_capacity) != 0) {
        return -1;
    }
    *value = result;
    return 0;
}

static int execute_arithmetic(struct hstex_engine *engine,
                              enum hstex_command operation, char *error,
                              size_t error_capacity)
{
    struct arithmetic_variable variable = {0};
    hstex_token offending = 0U;
    int found = scan_arithmetic_variable(engine, &variable, &offending, error,
                                         error_capacity);
    if (found < 0) {
        return -1;
    }
    if (found > 0) {
        /* Nothing behind it is read: the `by' and the amount are left where
           they stand and become whatever they would have been anyway. */
        static const char *const help[] = {
            "I'm forgetting what you said and not changing anything.", NULL};
        char named[128];
        char operation_name[64];
        describe_token(engine, offending, named, sizeof(named));
        /* The primitive is named behind the ESCAPE CHARACTER, which is not
           always a backslash: trip sets \escapechar to `|' before it writes
           `\advance\prevdepth', and the reference says `after |advance'. */
        const char *word = operation == HSTEX_COMMAND_ADVANCE
                               ? "advance"
                               : (operation == HSTEX_COMMAND_MULTIPLY
                                      ? "multiply"
                                      : "divide");
        int32_t escape =
            engine->integer_parameters[HSTEX_INTEGER_ESCAPE_CHARACTER];
        if (escape >= 1 && escape <= 255) {
            (void)snprintf(operation_name, sizeof(operation_name), "%c%s",
                           (char)escape, word);
        } else if (escape == 0) {
            (void)snprintf(operation_name, sizeof(operation_name), "^^@%s",
                           word);
        } else {
            (void)snprintf(operation_name, sizeof(operation_name), "%s", word);
        }
        tex_error(engine, help, "You can't use `%s' after %s", named,
                  operation_name);
        engine->pending_global = false;
        engine->pending_macro_flags = 0U;
        return 0;
    }
    if (scan_optional_by(engine, error, error_capacity) != 0) {
        return -1;
    }

    bool requested_global = engine->pending_global;
    if (arithmetic_variable_is_integer(variable.kind) ||
        arithmetic_variable_is_dimen(variable.kind)) {
        int32_t operand = 0;
        if ((operation == HSTEX_COMMAND_ADVANCE &&
             arithmetic_variable_is_dimen(variable.kind)
                 ? scan_dimension(engine, &operand, error, error_capacity)
                 : scan_integer(engine, &operand, error, error_capacity)) !=
            0) {
            return -1;
        }
        int32_t current = 0;
        if (variable.kind == ARITHMETIC_VARIABLE_COUNT) {
            current = engine->counts[variable.index];
        } else if (variable.kind ==
                   ARITHMETIC_VARIABLE_INTEGER_PARAMETER) {
            current = engine->integer_parameters[variable.index];
        } else if (variable.kind == ARITHMETIC_VARIABLE_DIMEN) {
            current = engine->dimens[variable.index];
        } else if (variable.kind == ARITHMETIC_VARIABLE_PREV_DEPTH) {
            current = engine->prev_depth;
        } else {
            current = engine->dimen_parameters[variable.index];
        }
        int32_t result = 0;
        int64_t lower = arithmetic_variable_is_integer(variable.kind)
                            ? (int64_t)INT32_MIN
                            : -INT64_C(1073741823);
        int64_t upper = arithmetic_variable_is_integer(variable.kind)
                            ? (int64_t)INT32_MAX
                            : INT64_C(1073741823);
        if (arithmetic_scalar_result(engine, current, operand, operation, lower, upper,
                                     &result, error, error_capacity) != 0) {
            return -1;
        }
        engine->pending_global = false;
        engine->pending_macro_flags = 0U;
        switch (variable.kind) {
        case ARITHMETIC_VARIABLE_COUNT:
            return assign_count(engine, variable.index, result,
                                requested_global, error, error_capacity);
        case ARITHMETIC_VARIABLE_INTEGER_PARAMETER:
            return assign_integer_parameter(engine, variable.index, result,
                                            requested_global, error,
                                            error_capacity);
        case ARITHMETIC_VARIABLE_DIMEN:
            return assign_dimen(engine, variable.index, result,
                                requested_global, error, error_capacity);
        case ARITHMETIC_VARIABLE_DIMEN_PARAMETER:
            return assign_dimen_parameter(engine, variable.index, result,
                                          requested_global, error,
                                          error_capacity);
        case ARITHMETIC_VARIABLE_PREV_DEPTH:
            engine->prev_depth = result;
            return 0;
        default:
            return set_error(error, error_capacity,
                             "internal scalar arithmetic target mismatch");
        }
    }

    struct hstex_glue value;
    if (variable.kind == ARITHMETIC_VARIABLE_GLUE) {
        value = engine->glues[variable.index];
    } else if (variable.kind == ARITHMETIC_VARIABLE_GLUE_PARAMETER) {
        value = engine->glue_parameters[variable.index];
    } else if (variable.kind == ARITHMETIC_VARIABLE_MUGLUE) {
        value = engine->muglues[variable.index];
    } else {
        value = engine->muglue_parameters[variable.index];
    }
    if (operation == HSTEX_COMMAND_ADVANCE) {
        struct hstex_glue operand;
        int scan_status = arithmetic_variable_is_glue(variable.kind)
                              ? scan_glue(engine, &operand, error,
                                          error_capacity)
                              : scan_math_glue(engine, &operand, error,
                                               error_capacity);
        if (scan_status != 0 ||
            advance_glue_value(&value, &operand, error, error_capacity) != 0) {
            return -1;
        }
    } else {
        int32_t operand = 0;
        if (scan_integer(engine, &operand, error, error_capacity) != 0 ||
            scale_glue_value(engine, &value, operand, operation, error,
                             error_capacity) != 0) {
            return -1;
        }
    }
    engine->pending_global = false;
    engine->pending_macro_flags = 0U;
    switch (variable.kind) {
    case ARITHMETIC_VARIABLE_GLUE:
        return assign_glue(engine, variable.index, value, requested_global,
                           error, error_capacity);
    case ARITHMETIC_VARIABLE_GLUE_PARAMETER:
        return assign_glue_parameter(engine, variable.index, value,
                                     requested_global, error, error_capacity);
    case ARITHMETIC_VARIABLE_MUGLUE:
        return assign_muglue(engine, variable.index, value, requested_global,
                             error, error_capacity);
    case ARITHMETIC_VARIABLE_MUGLUE_PARAMETER:
        return assign_muglue_parameter(engine, variable.index, value,
                                       requested_global, error,
                                       error_capacity);
    default:
        return set_error(error, error_capacity,
                         "internal glue arithmetic target mismatch");
    }
}

/* The streams that clamp rather than complain. The reference reads \write's
   and \closeout's stream with the same unrestricted scan -- they build the
   same size of node, and the routine that builds it chooses by size -- and
   sends anything out of range to the log alone (16) or to the log only when
   nothing is being written (17). Measured: \closeout-7 and \closeout20 are
   silent, where \openout of either says "Bad number". */
static int scan_write_stream_number(struct hstex_engine *engine, int32_t *stream,
                                    char *error, size_t error_capacity)
{
    if (scan_integer(engine, stream, error, error_capacity) != 0) {
        return -1;
    }
    if (*stream < 0) {
        *stream = 17;
    } else if (*stream > 15) {
        *stream = 16;
    }
    return 0;
}

/* \read's stream clamps too, and out of range means the terminal. Measured:
   \read-7, \read20 and \read16 all stop the same way with no file open. */
static int scan_read_stream_number(struct hstex_engine *engine, int32_t *stream,
                                   char *error, size_t error_capacity)
{
    if (scan_integer(engine, stream, error, error_capacity) != 0) {
        return -1;
    }
    if (*stream < 0 || *stream > 15) {
        *stream = 16;
    }
    return 0;
}

static char *output_path(struct hstex_engine *engine, const char *filename)
{
    if (filename[0] == '/') {
        return strdup(filename);
    }
    return join_path(engine->output_directory == NULL ? "."
                                                     : engine->output_directory,
                     filename);
}

/* Plain text kept where a token list is expected: how a whatsit remembers a
   file name. */
static int store_text_as_token_list(struct hstex_engine *engine,
                                    const char *text, uint32_t *identifier,
                                    char *error, size_t error_capacity)
{
    struct hstex_token_vector tokens = {0};
    for (const char *cursor = text; *cursor != '\0'; ++cursor) {
        uint8_t byte = (uint8_t)*cursor;
        uint8_t category = byte == (uint8_t)' ' ? (uint8_t)HSTEX_CAT_SPACE
                                                : (uint8_t)HSTEX_CAT_OTHER;
        if (vector_push(&tokens, hstex_token_character(category, byte), error,
                        error_capacity) != 0) {
            vector_destroy(&tokens);
            return -1;
        }
    }
    return store_token_list(engine, &tokens, identifier, error, error_capacity);
}

/* The file a stream is opened on, once the whatsit that asked for it is
   shipped or \immediate has claimed it. */
static int open_write_stream(struct hstex_engine *engine, int32_t stream,
                             char *filename, char *error,
                             size_t error_capacity)
{
    if (stream < 0 || stream >= 16) {
        free(filename);
        return 0;
    }
    /* A stream opened on a name with no extension is opened on that name and
       `.tex': the reference notes `\openout0 = `8terminal.tex'.' for trip's
       `\openout-'78terminal', and writes the file under that name, so that
       an \input of the bare name finds it again. A name that HAS an
       extension keeps it, whatever it is. */
    if (!filename_has_extension(filename)) {
        char *extended = append_tex_extension(filename);
        if (extended == NULL) {
            free(filename);
            return set_error(error, error_capacity,
                             "output name allocation failed");
        }
        free(filename);
        filename = extended;
    }
    char *path = output_path(engine, filename);
    char *name = filename;
    if (path == NULL) {
        free(name);
        return set_error(error, error_capacity,
                         "output path allocation failed");
    }
    FILE *file = NULL;
    if (engine->verifying) {
        size_t path_length = strlen(path);
        char *fleet = malloc(path_length + 7U);
        if (fleet != NULL) {
            memcpy(fleet, path, path_length);
            memcpy(fleet + path_length, "-fleet", 7U);
            file = fopen(fleet, "r+b");
            if (file == NULL) {
                file = fopen(fleet, "w+b");
            }
            free(path);
            path = fleet;
        }
    } else {
        file = fopen(path, "wb");
    }
    ++engine->file_generation;
    if (file == NULL) {
        int saved_errno = errno;
        int status = set_error(error, error_capacity, "cannot open %s: %s", path,
                               strerror(saved_errno));
        free(path);
        free(name);
        return status;
    }
    if (engine->write_streams[(size_t)stream] != NULL) {
        (void)fclose(engine->write_streams[(size_t)stream]);
    }
    engine->write_streams[(size_t)stream] = file;
    free(engine->write_stream_paths[(size_t)stream]);
    engine->write_stream_paths[(size_t)stream] = strdup(path);
    /* The reference notes an opened stream IN ITS LOG, and only there: the
       note is a diagnostic, so the terminal keeps its column across it and
       the blank line under it is end_diagnostic's. See docs/DECISIONS.md,
       the-print-line. */
    bool saved_selector = begin_diagnostic(engine);
    print_fresh_line(engine);
    print_formatted(engine, "\\openout%d = `%s'.", stream, name);
    end_diagnostic(engine, saved_selector, true);
    free(path);
    free(name);
    return 0;
}

static int close_write_stream(struct hstex_engine *engine, int32_t stream,
                              char *error, size_t error_capacity)
{
    if (stream >= 0 && stream < 16 &&
        engine->write_streams[(size_t)stream] != NULL) {
        if (fclose(engine->write_streams[(size_t)stream]) != 0) {
            engine->write_streams[(size_t)stream] = NULL;
            return set_error(error, error_capacity,
                             "failed to close output stream");
        }
        engine->write_streams[(size_t)stream] = NULL;
    }
    return 0;
}

/* \openout reads its file name where it stands, whether or not the opening
   itself waits for the page to be shipped. */
static int execute_open_out(struct hstex_engine *engine, bool immediate,
                            char *error, size_t error_capacity)
{
    int32_t stream = 0;
    char *filename = NULL;
    if (scan_four_bit_int(engine, &stream, error, error_capacity) != 0 ||
        scan_optional_equals(engine, error, error_capacity) != 0 ||
        scan_input_filename(engine, &filename, false, error,
                            error_capacity) != 0) {
        free(filename);
        return -1;
    }
    if (immediate) {
        return open_write_stream(engine, stream, filename, error,
                                 error_capacity);
    }
    uint32_t tokens = 0U;
    int status = store_text_as_token_list(engine, filename, &tokens, error,
                                          error_capacity);
    free(filename);
    if (status != 0) {
        return -1;
    }
    return new_whatsit(engine, HSTEX_WHATSIT_OPEN_OUT, stream, tokens, error,
                       error_capacity);
}

static int execute_close_out(struct hstex_engine *engine, bool immediate,
                             char *error, size_t error_capacity)
{
    int32_t stream = 0;
    if (scan_write_stream_number(engine, &stream, error, error_capacity) != 0) {
        return -1;
    }
    if (immediate) {
        return close_write_stream(engine, stream, error, error_capacity);
    }
    return new_whatsit(engine, HSTEX_WHATSIT_CLOSE_OUT, stream, 0U, error,
                       error_capacity);
}

static int serialize_control_sequence(struct hstex_engine *engine,
                                      hstex_token token, uint8_t **bytes,
                                      size_t *count, size_t *capacity,
                                      bool terminate_control_word,
                                      char *error, size_t error_capacity)
{
    enum hstex_symbol_kind kind;
    const uint8_t *name = NULL;
    size_t length = 0U;
    if (hstex_symbol_name(&engine->lexical_state.symbols,
                          hstex_token_control_sequence_id(token), &kind, &name,
                          &length) != 0) {
        return set_error(error, error_capacity,
                         "invalid control sequence in write text");
    }
    int32_t escape =
        engine->integer_parameters[HSTEX_INTEGER_ESCAPE_CHARACTER];
    static const char *const null_parts[2] = {"csname", "endcsname"};
    size_t parts = control_sequence_is_null(kind, length) ? 2U : 1U;
    for (size_t part = 0U; part < parts; ++part) {
        if (kind == HSTEX_SYMBOL_REGULAR && escape >= 0 && escape <= 255 &&
            append_byte(bytes, count, capacity, (uint8_t)escape, error,
                        error_capacity) != 0) {
            return -1;
        }
        if (parts == 2U) {
            for (size_t index = 0U; null_parts[part][index] != '\0'; ++index) {
                if (append_byte(bytes, count, capacity,
                                (uint8_t)null_parts[part][index], error,
                                error_capacity) != 0) {
                    return -1;
                }
            }
            continue;
        }
        for (size_t index = 0U; index < length; ++index) {
            if (append_byte(bytes, count, capacity, name[index], error,
                            error_capacity) != 0) {
                return -1;
            }
        }
    }
    if (terminate_control_word &&
        regular_control_sequence_needs_space(engine, kind, name, length) &&
        append_byte(bytes, count, capacity, (uint8_t)' ', error,
                    error_capacity) != 0) {
        return -1;
    }
    return 0;
}

static int append_text_bytes(uint8_t **bytes, size_t *count, size_t *capacity,
                             const char *text, char *error,
                             size_t error_capacity)
{
    for (size_t index = 0U; text[index] != '\0'; ++index) {
        if (append_byte(bytes, count, capacity, (uint8_t)text[index], error,
                        error_capacity) != 0) {
            return -1;
        }
    }
    return 0;
}

/* The reference shows what it had read when a runaway is caught: the kind
   on one line and the partial list on the next, cut to within ten
   characters of the width it prints to and finished with \ETC. See
   tests/trip/probes/what-a-runaway-shows.tex. */
static void report_runaway_list(struct hstex_engine *engine, const char *what,
                                const struct hstex_token_vector *lead,
                                const char *prefix,
                                const struct hstex_token_vector *partial)
{
    if (partial == NULL) {
        return;
    }
    uint8_t *bytes = NULL;
    size_t count = 0U;
    size_t capacity = 0U;
    bool cut = false;
    char scratch[256];
    const size_t limit = (size_t)HSTEX_PRINT_LINE - 10U;
    /* Whatever stands in front of the part that ran away -- a definition
       shows the parameter text it had matched before its `->'. Each
       parameter of that text sets the character the rest of the list is
       written with, as it does anywhere a list is shown. */
    shown_parameter_character = (uint8_t)'#';
    for (size_t index = 0U; lead != NULL && index < lead->count; ++index) {
        if (hstex_token_is_parameter(lead->data[index])) {
            shown_parameter_character =
                hstex_token_parameter_character(lead->data[index]);
        }
        if (append_token_description(engine, lead->data[index], &bytes, &count,
                                     &capacity, scratch,
                                     sizeof(scratch)) != 0) {
            free(bytes);
            return;
        }
    }
    if (prefix != NULL) {
        for (const char *at = prefix; *at != '\0'; ++at) {
            if (append_byte(&bytes, &count, &capacity, (uint8_t)*at, scratch,
                            sizeof(scratch)) != 0) {
                free(bytes);
                return;
            }
        }
    }
    for (size_t index = 0U; index < partial->count; ++index) {
        if (count >= limit) {
            cut = true;
            break;
        }
        if (append_token_description(engine, partial->data[index],
                                     &bytes, &count, &capacity, scratch,
                                     sizeof(scratch)) != 0) {
            free(bytes);
            return;
        }
    }
    print_fresh_line(engine);
    print_formatted(engine, "Runaway %s?", what);
    print_line(engine);
    if (count != 0U) {
        print_bytes(engine, (const char *)bytes, count);
    }
    if (cut) {
        print_esc_text(engine, "\\ETC.");
    }
    free(bytes);
}

/* The same, from whatever list the engine is filling. */
static void report_runaway(struct hstex_engine *engine, const char *what)
{
    report_runaway_list(engine, what, runaway_partial_lead,
                        runaway_partial_prefix,
                        runaway_partial);
}

static int append_token_description(struct hstex_engine *engine,
                                    hstex_token token, uint8_t **bytes,
                                    size_t *count, size_t *capacity, char *error,
                                    size_t error_capacity)
{
    token = normalize_frozen_control_sequence(token);
    if (hstex_token_is_character(token)) {
        uint8_t character = hstex_token_character_code(token);
        /* A character token of the parameter category is displayed doubled,
           so that reading the display back yields the same token. */
        if (token_is_category(token, HSTEX_CAT_PARAMETER) &&
            append_byte(bytes, count, capacity, character, error,
                        error_capacity) != 0) {
            return -1;
        }
        return append_byte(bytes, count, capacity, character, error,
                           error_capacity);
    }
    if (hstex_token_is_parameter(token)) {
        if (append_byte(bytes, count, capacity, shown_parameter_character,
                        error, error_capacity) != 0) {
            return -1;
        }
        return append_byte(bytes, count, capacity,
                           (uint8_t)('0' +
                                     hstex_token_parameter_number(token)),
                           error, error_capacity);
    }
    if (hstex_token_is_control_sequence(token)) {
        return serialize_control_sequence(engine, token, bytes, count, capacity,
                                          true, error, error_capacity);
    }
    return set_error(error, error_capacity,
                     "internal token in meaning description");
}

/* \string makes tokens, and a token list is never written in ^^ notation:
   the reference reserves that for what it prints to the terminal. So every
   byte goes through as it stands, however unprintable it would look. See
   docs/DECISIONS.md, string-is-not-escaped. */
static int append_string_character(uint8_t **bytes, size_t *count,
                                   size_t *capacity, uint8_t character,
                                   char *error, size_t error_capacity)
{
    return append_byte(bytes, count, capacity, character, error,
                       error_capacity);
}

static int expand_string(struct hstex_engine *engine,
                         struct hstex_source_location location, char *error,
                         size_t error_capacity)
{
    hstex_token subject = 0U;
    struct hstex_source_location subject_location;
    if (raw_next(engine, &subject, &subject_location, error, error_capacity) !=
        HSTEX_ENGINE_TOKEN) {
        return set_error(error, error_capacity, "end of input after string");
    }
    (void)subject_location;
    uint8_t *bytes = NULL;
    size_t count = 0U;
    size_t capacity = 0U;
    if (hstex_token_is_character(subject)) {
        if (append_string_character(&bytes, &count, &capacity,
                                    hstex_token_character_code(subject), error,
                                    error_capacity) != 0) {
            free(bytes);
            return -1;
        }
    } else if (hstex_token_is_control_sequence(subject)) {
        enum hstex_symbol_kind kind;
        const uint8_t *name = NULL;
        size_t length = 0U;
        if (hstex_symbol_name(&engine->lexical_state.symbols,
                              hstex_token_control_sequence_id(subject), &kind,
                              &name, &length) != 0) {
            free(bytes);
            return set_error(error, error_capacity,
                             "invalid control sequence after string");
        }
        if (kind == HSTEX_SYMBOL_ACTIVE && length == 1U) {
            if (append_string_character(&bytes, &count, &capacity, name[0],
                                        error, error_capacity) != 0) {
                free(bytes);
                return -1;
            }
        } else {
            int32_t escape =
                engine->integer_parameters[HSTEX_INTEGER_ESCAPE_CHARACTER];
            static const char *const null_parts[2] = {"csname", "endcsname"};
            size_t parts = control_sequence_is_null(kind, length) ? 2U : 1U;
            for (size_t part = 0U; part < parts; ++part) {
                if (escape >= 0 && escape <= 255 &&
                    append_string_character(&bytes, &count, &capacity,
                                            (uint8_t)escape, error,
                                            error_capacity) != 0) {
                    free(bytes);
                    return -1;
                }
                const char *spelled = parts == 2U ? null_parts[part] : NULL;
                for (size_t index = 0U;
                     spelled != NULL && spelled[index] != '\0'; ++index) {
                    if (append_string_character(&bytes, &count, &capacity,
                                                (uint8_t)spelled[index], error,
                                                error_capacity) != 0) {
                        free(bytes);
                        return -1;
                    }
                }
                for (size_t index = 0U; spelled == NULL && index < length;
                     ++index) {
                    if (append_string_character(&bytes, &count, &capacity,
                                                name[index], error,
                                                error_capacity) != 0) {
                        free(bytes);
                        return -1;
                    }
                }
            }
        }
    } else {
        free(bytes);
        return set_error(error, error_capacity,
                         "internal token after string");
    }
    struct hstex_token_vector expansion = {0};
    for (size_t index = 0U; index < count; ++index) {
        uint8_t category = bytes[index] == (uint8_t)' '
                               ? (uint8_t)HSTEX_CAT_SPACE
                               : (uint8_t)HSTEX_CAT_OTHER;
        if (vector_push(&expansion,
                        hstex_token_character(category, bytes[index]), error,
                        error_capacity) != 0) {
            free(bytes);
            vector_destroy(&expansion);
            return -1;
        }
    }
    free(bytes);
    if (push_owned_vector(engine, &expansion, location, error, error_capacity) !=
        0) {
        vector_destroy(&expansion);
        return -1;
    }
    return 0;
}

/* A control sequence defined by \countdef and friends reports itself as the
   primitive it stands for, so \meaning\scratchcounter is \count298 rather
   than the name; see docs/DECISIONS.md, defined-register-meanings. */
static const char *defined_register_primitive(enum hstex_command command)
{
    switch (command) {
    case HSTEX_COMMAND_COUNT_REGISTER:
        return "count";
    case HSTEX_COMMAND_DIMEN_REGISTER:
        return "dimen";
    case HSTEX_COMMAND_SKIP_REGISTER:
        return "skip";
    case HSTEX_COMMAND_MUSKIP_REGISTER:
        return "muskip";
    case HSTEX_COMMAND_TOKS_REGISTER:
        return "toks";
    case HSTEX_COMMAND_CHAR_GIVEN:
        return "char";
    case HSTEX_COMMAND_MATH_CHAR_GIVEN:
        return "mathchar";
    default:
        return NULL;
    }
}

static int append_defined_register_meaning(struct hstex_engine *engine,
                                           const struct hstex_meaning *meaning,
                                           uint8_t **bytes, size_t *count,
                                           size_t *capacity, char *error,
                                           size_t error_capacity)
{
    const char *primitive = defined_register_primitive(meaning->command);
    char rendered[64];
    /* Character codes are shown in hexadecimal, register numbers in decimal. */
    bool hexadecimal = meaning->command == HSTEX_COMMAND_CHAR_GIVEN ||
                       meaning->command == HSTEX_COMMAND_MATH_CHAR_GIVEN;
    int length = hexadecimal
                     ? snprintf(rendered, sizeof(rendered), "%s\"%" PRIX32,
                                primitive, meaning->value.integer)
                     : snprintf(rendered, sizeof(rendered), "%s%" PRId32,
                                primitive, meaning->value.integer);
    if (length <= 0 || (size_t)length >= sizeof(rendered)) {
        return set_error(error, error_capacity,
                         "could not format a defined register meaning");
    }
    int32_t escape = engine->integer_parameters[HSTEX_INTEGER_ESCAPE_CHARACTER];
    if (escape >= 0 && escape <= 255 &&
        append_byte(bytes, count, capacity, (uint8_t)escape, error,
                    error_capacity) != 0) {
        return -1;
    }
    return append_text_bytes(bytes, count, capacity, rendered, error,
                             error_capacity);
}

/* What the reference calls a character token: the category has a name of its
   own, and the character follows it. See docs/DECISIONS.md,
   implicit-characters. */
static int append_character_meaning(struct hstex_engine *engine,
                                    hstex_token token, uint8_t **bytes,
                                    size_t *count, size_t *capacity,
                                    char *error, size_t error_capacity)
{
    static const struct {
        uint8_t category;
        const char *name;
    } names[] = {
        {(uint8_t)HSTEX_CAT_BEGIN_GROUP, "begin-group character "},
        {(uint8_t)HSTEX_CAT_END_GROUP, "end-group character "},
        {(uint8_t)HSTEX_CAT_MATH_SHIFT, "math shift character "},
        {(uint8_t)HSTEX_CAT_ALIGNMENT_TAB, "alignment tab character "},
        {(uint8_t)HSTEX_CAT_PARAMETER, "macro parameter character "},
        {(uint8_t)HSTEX_CAT_SUPERSCRIPT, "superscript character "},
        {(uint8_t)HSTEX_CAT_SUBSCRIPT, "subscript character "},
        {(uint8_t)HSTEX_CAT_SPACE, "blank space "},
        {(uint8_t)HSTEX_CAT_LETTER, "the letter "},
        {(uint8_t)HSTEX_CAT_OTHER, "the character "},
    };
    (void)engine;
    uint8_t category = hstex_token_category(token);
    const char *name = "the character ";
    for (size_t index = 0U; index < sizeof(names) / sizeof(names[0]);
         ++index) {
        if (names[index].category == category) {
            name = names[index].name;
            break;
        }
    }
    if (append_text_bytes(bytes, count, capacity, name, error,
                          error_capacity) != 0) {
        return -1;
    }
    return append_byte(bytes, count, capacity,
                       hstex_token_character_code(token), error,
                       error_capacity);
}

/* The text of a token's meaning: what \meaning expands to, and what \show
   prints after the `='. */
static int meaning_bytes(struct hstex_engine *engine, hstex_token subject,
                         uint8_t **bytes_out, size_t *count_out,
                         size_t *capacity_out, size_t *after_prefix,
                         size_t limit, bool *truncated, bool mark_text,
                         char *error, size_t error_capacity)
{
    uint8_t *bytes = NULL;
    size_t count = 0U;
    size_t capacity = 0U;
    /* Each list starts with the usual character and picks up whatever its
       own parameter text uses. */
    shown_parameter_character = (uint8_t)'#';
    if (truncated != NULL) {
        *truncated = false;
    }
    if (hstex_token_is_character(subject)) {
        if (append_character_meaning(engine, subject, &bytes, &count, &capacity,
                                     error, error_capacity) != 0) {
            free(bytes);
            return -1;
        }
    } else if (hstex_token_is_control_sequence(subject)) {
        const struct hstex_meaning *meaning = hstex_engine_meaning(
            engine, hstex_token_control_sequence_id(subject));
        /* A control sequence \\let to a character has that character's
           meaning, not a name of its own. */
        if (meaning->command == HSTEX_COMMAND_TOKEN_ALIAS &&
            hstex_token_is_character(meaning->value.token)) {
            if (append_character_meaning(engine, meaning->value.token, &bytes,
                                         &count, &capacity, error,
                                         error_capacity) != 0) {
                free(bytes);
                return -1;
            }
        } else if (meaning->command == HSTEX_COMMAND_END_TEMPLATE) {
            /* What stands at the end of an alignment entry shows as an
               \outer macro would, but named for itself and with nothing
               after the colon: "\outer endtemplate:". \show breaks the
               line after the colon, as it breaks it for any macro, so what
               follows is the terminating period alone. */
            int32_t escape =
                engine->integer_parameters[HSTEX_INTEGER_ESCAPE_CHARACTER];
            if ((escape >= 0 && escape <= 255 &&
                 append_byte(&bytes, &count, &capacity, (uint8_t)escape, error,
                             error_capacity) != 0) ||
                append_text_bytes(&bytes, &count, &capacity,
                                  "outer endtemplate:", error,
                                  error_capacity) != 0) {
                free(bytes);
                return -1;
            }
            if (after_prefix != NULL) {
                *after_prefix = count;
            }
        } else if (meaning->command == HSTEX_COMMAND_MACRO &&
            meaning->value.macro_identifier != 0U &&
            (size_t)meaning->value.macro_identifier <= engine->macro_count) {
            const struct hstex_macro *macro =
                &engine->macros[meaning->value.macro_identifier - 1U];
            /* The prefixes are named in the order \protected, \long,
               \outer, each behind the escape character and with no
               separator; one space then precedes `macro:'. */
            static const struct {
                uint8_t flag;
                const char *name;
            } prefixes[] = {
                {(uint8_t)HSTEX_MACRO_PROTECTED, "protected"},
                {(uint8_t)HSTEX_MACRO_LONG, "long"},
                {(uint8_t)HSTEX_MACRO_OUTER, "outer"},
            };
            bool prefixed = false;
            for (size_t index = 0U;
                 index < sizeof(prefixes) / sizeof(prefixes[0]); ++index) {
                if ((macro->flags & prefixes[index].flag) == 0U) {
                    continue;
                }
                int32_t escape =
                    engine->integer_parameters[HSTEX_INTEGER_ESCAPE_CHARACTER];
                if ((escape >= 0 && escape <= 255 &&
                     append_byte(&bytes, &count, &capacity, (uint8_t)escape,
                                 error, error_capacity) != 0) ||
                    append_text_bytes(&bytes, &count, &capacity,
                                      prefixes[index].name, error,
                                      error_capacity) != 0) {
                    free(bytes);
                    return -1;
                }
                prefixed = true;
            }
            if (prefixed &&
                append_byte(&bytes, &count, &capacity, (uint8_t)' ', error,
                            error_capacity) != 0) {
                free(bytes);
                return -1;
            }
            if (append_text_bytes(&bytes, &count, &capacity, "macro:", error,
                                  error_capacity) != 0) {
                free(bytes);
                return -1;
            }
            /* \\show breaks the line here, between what the macro is and
               what it says. \\meaning does not; see docs/DECISIONS.md,
               where-show-breaks-a-macro. */
            if (after_prefix != NULL) {
                *after_prefix = count;
            }
            /* What is counted against the limit is the parameter text, the
               `->' between, and the replacement -- not the `macro:' in front
               of them, nor the \long and \outer before that. */
            size_t shown_from = count;
            bool cut = false;
            for (size_t index = 0U; index < macro->parameter_count_tokens;
                 ++index) {
                if (limit != 0U && count - shown_from >= limit) {
                    cut = true;
                    break;
                }
                /* A parameter of the parameter text sets the character the
                   rest of the list is written with. */
                if (hstex_token_is_parameter(macro->parameter_text[index])) {
                    shown_parameter_character = hstex_token_parameter_character(
                        macro->parameter_text[index]);
                }
                if (append_token_description(
                        engine, macro->parameter_text[index], &bytes, &count,
                        &capacity, error, error_capacity) != 0) {
                    free(bytes);
                    return -1;
                }
            }
            if (!cut && limit != 0U && count - shown_from >= limit) {
                cut = true;
            }
            if (!cut && append_text_bytes(&bytes, &count, &capacity, "->",
                                          error, error_capacity) != 0) {
                free(bytes);
                return -1;
            }
            for (size_t index = 0U; !cut && index < macro->replacement_count;
                 ++index) {
                if (limit != 0U && count - shown_from >= limit) {
                    cut = true;
                    break;
                }
                if (append_token_description(
                        engine, macro->replacement[index], &bytes, &count,
                        &capacity, error, error_capacity) != 0) {
                    free(bytes);
                    return -1;
                }
            }
            if (cut && truncated != NULL) {
                *truncated = true;
            }
        } else if (meaning->command == HSTEX_COMMAND_FONT_GIVEN) {
            uint32_t identifier = meaning->value.integer > 0
                                      ? (uint32_t)meaning->value.integer
                                      : 0U;
            const struct hstex_font *font =
                font_by_identifier(engine, identifier);
            if (font == NULL || font->name == NULL ||
                append_text_bytes(&bytes, &count, &capacity, "select font ",
                                  error, error_capacity) != 0 ||
                append_text_bytes(&bytes, &count, &capacity, font->name, error,
                                  error_capacity) != 0) {
                free(bytes);
                return font == NULL || font->name == NULL
                           ? set_error(error, error_capacity,
                                       "invalid font meaning")
                           : -1;
            }
            if (font->size != INT32_C(10) * INT32_C(65536)) {
                char size_text[64];
                int size_length = format_scaled_value(
                    font->size, "pt", size_text, sizeof(size_text));
                if (size_length < 0 ||
                    append_text_bytes(&bytes, &count, &capacity, " at ", error,
                                      error_capacity) != 0) {
                    free(bytes);
                    return size_length < 0
                               ? set_error(error, error_capacity,
                                           "could not format font meaning")
                               : -1;
                }
                for (int index = 0; index < size_length; ++index) {
                    if (append_byte(&bytes, &count, &capacity,
                                    (uint8_t)size_text[index], error,
                                    error_capacity) != 0) {
                        free(bytes);
                        return -1;
                    }
                }
            }
        } else if (meaning->command == HSTEX_COMMAND_UNDEFINED) {
            if (append_text_bytes(&bytes, &count, &capacity, "undefined", error,
                                  error_capacity) != 0) {
                free(bytes);
                return -1;
            }
        } else if (meaning->command == HSTEX_COMMAND_MARK_TEXT && mark_text &&
                   meaning->value.integer < 8) {
            /* One of the five marks TeX82 has shows what it holds as well as
               what it is: the name, a colon, and then the text, which \show
               puts on a line of its own the way it does a macro's body.
               \meaning gives the same two parts with nothing between them.
               The marks CLASSES eTeX adds do not do this -- `\show\botmarks'
               is `\botmarks.' and no more -- so only the five are here. */
            if (serialize_control_sequence(
                    engine,
                    meaning->primitive_origin == 0U
                        ? subject
                        : hstex_token_control_sequence(
                              meaning->primitive_origin),
                    &bytes, &count, &capacity, false, error,
                    error_capacity) != 0 ||
                append_byte(&bytes, &count, &capacity, (uint8_t)':', error,
                            error_capacity) != 0) {
                free(bytes);
                return -1;
            }
            if (after_prefix != NULL) {
                *after_prefix = count;
            }
            const struct hstex_mark_class *entry =
                mark_class_of(engine, 0U, false, error, error_capacity);
            uint32_t identifier = 0U;
            if (entry != NULL) {
                switch (meaning->value.integer) {
                case 0:
                    identifier = entry->top;
                    break;
                case 1:
                    identifier = entry->first;
                    break;
                case 2:
                    identifier = entry->bot;
                    break;
                case 3:
                    identifier = entry->split_first;
                    break;
                default:
                    identifier = entry->split_bot;
                    break;
                }
            }
            const struct hstex_token_list *list =
                identifier == 0U ? NULL
                                 : token_list_by_identifier(engine, identifier);
            for (size_t index = 0U; list != NULL && index < list->count;
                 ++index) {
                if (append_token_description(engine, list->tokens[index],
                                             &bytes, &count, &capacity, error,
                                             error_capacity) != 0) {
                    free(bytes);
                    return -1;
                }
            }
        } else if (defined_register_primitive(meaning->command) != NULL) {
            if (append_defined_register_meaning(engine, meaning, &bytes, &count,
                                                &capacity, error,
                                                error_capacity) != 0) {
                free(bytes);
                return -1;
            }
        } else if (serialize_control_sequence(
                       engine,
                       meaning->primitive_origin == 0U
                           ? subject
                           : hstex_token_control_sequence(
                                 meaning->primitive_origin),
                       &bytes, &count, &capacity, false, error,
                                              error_capacity) != 0) {
            free(bytes);
            return -1;
        }
    } else {
        free(bytes);
        return set_error(error, error_capacity,
                         "internal token after meaning");
    }

    *bytes_out = bytes;
    *count_out = count;
    *capacity_out = capacity;
    return 0;
}

static int expand_meaning(struct hstex_engine *engine,
                          struct hstex_source_location location, char *error,
                          size_t error_capacity)
{
    hstex_token subject = 0U;
    struct hstex_source_location subject_location;
    if (raw_next(engine, &subject, &subject_location, error, error_capacity) !=
        HSTEX_ENGINE_TOKEN) {
        return set_error(error, error_capacity, "end of input after meaning");
    }
    (void)subject_location;
    uint8_t *bytes = NULL;
    size_t count = 0U;
    size_t capacity = 0U;
    if (meaning_bytes(engine, subject, &bytes, &count, &capacity, NULL, 0U,
                      NULL, true, error, error_capacity) != 0) {
        return -1;
    }
    (void)capacity;
    struct hstex_token_vector expansion = {0};
    for (size_t index = 0U; index < count; ++index) {
        uint8_t category = bytes[index] == (uint8_t)' '
                               ? (uint8_t)HSTEX_CAT_SPACE
                               : (uint8_t)HSTEX_CAT_OTHER;
        if (vector_push(&expansion,
                        hstex_token_character(category, bytes[index]), error,
                        error_capacity) != 0) {
            free(bytes);
            vector_destroy(&expansion);
            return -1;
        }
    }
    free(bytes);
    if (push_owned_vector(engine, &expansion, location, error, error_capacity) !=
        0) {
        vector_destroy(&expansion);
        return -1;
    }
    return 0;
}

/* Reads whatever the sources have to give down to the boundary the caller
   pushed, expanding as it goes, and lays it out as the bytes a stream would
   receive. The boundary is popped here. */
/* One token of an expanded text, as the bytes a stream would receive. */
static int append_token_bytes(struct hstex_engine *engine, hstex_token token,
                              uint8_t **result, size_t *count,
                              size_t *capacity, char *error,
                              size_t error_capacity)
{
    if (hstex_token_is_character(token)) {
        uint8_t character = hstex_token_character_code(token);
        /* A parameter-category character is written doubled. */
        if (token_is_category(token, HSTEX_CAT_PARAMETER) &&
            append_byte(result, count, capacity, character, error,
                        error_capacity) != 0) {
            return -1;
        }
        return append_byte(result, count, capacity, character, error,
                           error_capacity);
    }
    if (hstex_token_is_control_sequence(token)) {
        return serialize_control_sequence(engine, token, result, count,
                                          capacity, true, error,
                                          error_capacity);
    }
    return set_error(error, error_capacity,
                     "internal token in expanded write text");
}

static int expand_to_bytes(struct hstex_engine *engine, uint8_t **bytes,
                           size_t *byte_count, char *error,
                           size_t error_capacity)
{
    uint8_t *result = NULL;
    size_t count = 0U;
    size_t capacity = 0U;
    for (;;) {
        hstex_token token = 0U;
        struct hstex_source_location location;
        bool previous_inhibition = engine->inhibit_protected_expansion;
        bool previous_gathering = engine->gathering_expanded_text;
        engine->inhibit_protected_expansion = true;
        engine->gathering_expanded_text = true;
        enum hstex_engine_result expansion_result = hstex_engine_next_expanded(
            engine, &token, &location, error, error_capacity);
        engine->inhibit_protected_expansion = previous_inhibition;
        engine->gathering_expanded_text = previous_gathering;
        if (expansion_result == HSTEX_ENGINE_EOF) {
            if (hstex_source_pop_boundary(&engine->sources, error,
                                          error_capacity) != 0) {
                free(result);
                return -1;
            }
            break;
        }
        if (expansion_result != HSTEX_ENGINE_TOKEN) {
            (void)hstex_source_pop_boundary(&engine->sources, NULL, 0U);
            free(result);
            return -1;
        }
        if (append_token_bytes(engine, token, &result, &count, &capacity,
                               error, error_capacity) != 0) {
            free(result);
            return -1;
        }
    }
    *bytes = result;
    *byte_count = count;
    return 0;
}

/* The same bytes, from a text already in hand. */
static int tokens_to_bytes(struct hstex_engine *engine,
                           const struct hstex_token_vector *text,
                           uint8_t **bytes, size_t *byte_count, char *error,
                           size_t error_capacity)
{
    uint8_t *result = NULL;
    size_t count = 0U;
    size_t capacity = 0U;
    for (size_t index = 0U; index < text->count; ++index) {
        if (append_token_bytes(engine, text->data[index], &result, &count,
                               &capacity, error, error_capacity) != 0) {
            free(result);
            return -1;
        }
    }
    *bytes = result;
    *byte_count = count;
    return 0;
}

/* An expanded text read STRAIGHT FROM THE INPUT, the way the reference
   reads the text of \message, \special and \mark: expand as you go, count
   braces on what cannot be expanded, and stop at the brace matching the one
   already read. Nothing is pushed, so a fault raised inside the text names
   the line the text stands on rather than a list of its own -- trip line
   293's `\mark{\the\spacefactor}' draws "Improper \spacefactor" against
   l.293. An \outer macro is forbidden here as it is in a definition, and
   the expander reports it before expanding, which is why the name is lent
   to the engine for the length of the read. */
/* `ending` is the token the text is bounded by where there is one behind the
   material pushed for it -- a \write puts a `}' there, and something the
   text opened may swallow it. Where that happens the reference meets its own
   terminator, which is an OUTER name, and says so; the name becomes a space,
   another `}' goes in, and the scan carries on until the braces come out
   even. Null for a text that is simply read to its end. */
static int scan_expanded_text_from_input(struct hstex_engine *engine,
                                         struct hstex_token_vector *text,
                                         const char *scanning,
                                         bool bounded, char *error,
                                         size_t error_capacity)
{
    size_t depth = 1U;
    const char *previous_text_name = engine->expanded_text_name;
    const struct hstex_token_vector *previous_partial = runaway_partial;
    const char *previous_prefix = runaway_partial_prefix;
    const struct hstex_token_vector *previous_lead = runaway_partial_lead;
    engine->expanded_text_name = scanning;
    runaway_partial = text;
    runaway_partial_prefix = NULL;
    runaway_partial_lead = NULL;
    for (;;) {
        hstex_token token = 0U;
        struct hstex_source_location location;
        bool previous_inhibition = engine->inhibit_protected_expansion;
        bool previous_gathering = engine->gathering_expanded_text;
        engine->inhibit_protected_expansion = true;
        engine->gathering_expanded_text = true;
        enum hstex_engine_result result = hstex_engine_next_expanded(
            engine, &token, &location, error, error_capacity);
        engine->inhibit_protected_expansion = previous_inhibition;
        engine->gathering_expanded_text = previous_gathering;
        if (result == HSTEX_ENGINE_EOF && bounded) {
            /* The terminator has been swallowed by something the text
               opened. */
            static const char *const help[] = {
                "I suspect you have forgotten a `}', causing me",
                "to read past where you wanted me to stop.",
                "I'll try to recover; but if the error is serious,",
                "you'd better type `E' or `X' now and fix your file.", NULL};
            /* What has been read is shown BEFORE the terminator becomes
               anything, so the space is not in it. */
            report_runaway_list(engine, "text", NULL, NULL, text);
            hstex_token space =
                hstex_token_character((uint8_t)HSTEX_CAT_SPACE, (uint8_t)' ');
            if (vector_push(text, space, error, error_capacity) != 0) {
                engine->expanded_text_name = previous_text_name;
                runaway_partial = previous_partial;
                runaway_partial_prefix = previous_prefix;
                runaway_partial_lead = previous_lead;
                return -1;
            }
            hstex_token closer = hstex_token_character(
                (uint8_t)HSTEX_CAT_END_GROUP, (uint8_t)'}');
            struct hstex_source_location where = {0};
            if (push_one(engine, closer, where, error, error_capacity) != 0) {
                engine->expanded_text_name = previous_text_name;
                runaway_partial = previous_partial;
                runaway_partial_prefix = previous_prefix;
                runaway_partial_lead = previous_lead;
                return -1;
            }
            hstex_source_name_top(&engine->sources,
                                  (uint8_t)HSTEX_TOKEN_SOURCE_INSERTED, 0U);
            tex_error(engine, help,
                      "Forbidden control sequence found while scanning %s",
                      scanning);
            continue;
        }
        if (result != HSTEX_ENGINE_TOKEN) {
            engine->expanded_text_name = previous_text_name;
            runaway_partial = previous_partial;
            runaway_partial_prefix = previous_prefix;
            runaway_partial_lead = previous_lead;
            if (result == HSTEX_ENGINE_EOF) {
                return set_error(error, error_capacity,
                                 "File ended while scanning %s", scanning);
            }
            return -1;
        }
        if (token_is_category(token, HSTEX_CAT_END_GROUP)) {
            --depth;
            if (depth == 0U) {
                engine->expanded_text_name = previous_text_name;
                runaway_partial = previous_partial;
                runaway_partial_prefix = previous_prefix;
                runaway_partial_lead = previous_lead;
                return 0;
            }
        } else if (token_is_category(token, HSTEX_CAT_BEGIN_GROUP)) {
            ++depth;
        }
        if (vector_push(text, token, error, error_capacity) != 0) {
            engine->expanded_text_name = previous_text_name;
            runaway_partial = previous_partial;
            runaway_partial_prefix = previous_prefix;
            runaway_partial_lead = previous_lead;
            return -1;
        }
    }
}

/* Whether the text is expanded as it is read or only after it has been
   taken whole decides one thing beyond speed: a conversion's operand is
   only reached, and so only exempted from the \outer check, in the first
   kind. Measured: \message{\meaning\lz} is quiet and
   \immediate\write16{\meaning\lz} is not, though both end up writing the
   same bytes. */
/* THE TEXT OF A \write GOES BACK INTO THE INPUT WITH A `}' BEHIND IT, and is
   then read the way an \edef body is. That brace is what a macro called
   inside the text meets when it runs off the end -- the reference's
   `Argument of \l has an extra }' comes from exactly that -- and a text that
   closes the group early leaves the brace standing, which is `Unbalanced
   write command'. HSTeX had bounded the text with nothing but the end of the
   input, so neither fault could be drawn. */
/* The frozen name the reference puts behind a \write text, so that the text
   ends where it was meant to and the context under a fault in it says so.
   See docs/DECISIONS.md, how-a-write-text-is-bounded. */
static int end_write_token(struct hstex_engine *engine, hstex_token *token,
                           char *error, size_t error_capacity)
{
    static const uint8_t name[] = "endwrite";
    hstex_cs_id identifier = 0U;
    if (hstex_symbol_intern(&engine->lexical_state.symbols,
                            HSTEX_SYMBOL_REGULAR, name, sizeof(name) - 1U,
                            &identifier, error, error_capacity) != 0) {
        return -1;
    }
    /* It is an OUTER MACRO WITH NOTHING IN IT. What it is for is to be
       READ, so that the text ends where it was meant to -- and being outer
       is what stops a text that ran past its own brace from swallowing it:
       the reference draws `Forbidden control sequence found while scanning
       text of \write' instead. */
    const struct hstex_meaning *standing =
        hstex_engine_meaning(engine, identifier);
    if (standing->command != HSTEX_COMMAND_MACRO) {
        uint32_t record = engine->macro_free_list;
        if (record != 0U) {
            engine->macro_free_list = engine->macros[record - 1U].next_free;
        } else {
            if (reserve_macros(engine, engine->macro_count + 1U, error,
                               error_capacity) != 0) {
                return -1;
            }
            ++engine->macro_count;
            record = (uint32_t)engine->macro_count;
        }
        struct hstex_macro *empty = &engine->macros[record - 1U];
        memset(empty, 0, sizeof(*empty));
        empty->flags = (uint8_t)HSTEX_MACRO_OUTER;
        struct hstex_meaning meaning = {
            .command = HSTEX_COMMAND_MACRO,
            .level = 0U,
            .value = {.macro_identifier = record},
        };
        if (set_meaning(engine, identifier, meaning, true, error,
                        error_capacity) != 0) {
            return -1;
        }
    }
    *token = hstex_token_control_sequence(identifier);
    return 0;
}

static int expand_write_text(struct hstex_engine *engine,
                             struct hstex_token_vector *text,
                             struct hstex_source_location location,
                             uint8_t **bytes, size_t *byte_count, char *error,
                             size_t error_capacity)
{
    if (hstex_source_push_boundary(&engine->sources, error, error_capacity) !=
        0) {
        vector_destroy(text);
        return -1;
    }
    hstex_token opener =
        hstex_token_character((uint8_t)HSTEX_CAT_BEGIN_GROUP, (uint8_t)'{');
    hstex_token closer =
        hstex_token_character((uint8_t)HSTEX_CAT_END_GROUP, (uint8_t)'}');
    hstex_token ending = 0U;
    if (end_write_token(engine, &ending, error, error_capacity) != 0) {
        (void)hstex_source_pop_boundary(&engine->sources, NULL, 0U);
        vector_destroy(text);
        return -1;
    }
    /* The brace and the name that ends the text are PUT IN together, as one
       inserted list, and the context shows them so. */
    hstex_token *pair = token_block_alloc(2U);
    if (pair == NULL) {
        (void)hstex_source_pop_boundary(&engine->sources, NULL, 0U);
        vector_destroy(text);
        return set_error(error, error_capacity,
                         "write terminator allocation failed");
    }
    pair[0] = closer;
    pair[1] = ending;
    if (hstex_source_push_owned_tokens(&engine->sources, pair, 2U, location,
                                       error, error_capacity) != 0) {
        (void)hstex_source_pop_boundary(&engine->sources, NULL, 0U);
        vector_destroy(text);
        return -1;
    }
    hstex_source_name_top(&engine->sources,
                          (uint8_t)HSTEX_TOKEN_SOURCE_INSERTED, 0U);
    /* A text begun here is traced the way a token parameter's is: at two and
       above, `\write->' and what it holds -- an empty one included. */
    if (engine->integer_parameters[HSTEX_INTEGER_TRACING_MACROS] > 1) {
        uint8_t *shown = NULL;
        size_t shown_count = 0U;
        size_t shown_room = 0U;
        char scratch[256];
        bool made = true;
        for (size_t index = 0U; made && index < text->count; ++index) {
            if (append_token_description(engine, text->data[index], &shown,
                                         &shown_count, &shown_room, scratch,
                                         sizeof(scratch)) != 0) {
                made = false;
            }
        }
        if (made) {
            bool saved_selector = begin_diagnostic(engine);
            print_fresh_line(engine);
            print_escaped_name(engine, "write");
            print_text(engine, "->");
            if (shown_count != 0U) {
                print_bytes(engine, (const char *)shown, shown_count);
            }
            end_diagnostic(engine, saved_selector, false);
            (void)fflush(diagnostic_stream(engine));
        }
        free(shown);
    }
    if (push_owned_vector(engine, text, location, error, error_capacity) != 0) {
        (void)hstex_source_pop_boundary(&engine->sources, NULL, 0U);
        vector_destroy(text);
        return -1;
    }
    hstex_source_name_top(&engine->sources,
                          (uint8_t)HSTEX_TOKEN_SOURCE_WRITE, 0U);
    /* The stored text is scanned inside a FRESH BALANCED GROUP. The opening
       brace must be read from the input stack, rather than merely assumed by
       the scanner: while a write is expanded inside an alignment entry it
       both shields tab and \cr tokens in the text and balances the synthetic
       closing brace already waiting behind it. See docs/DECISIONS.md,
       balanced-write-expansion. */
    if (hstex_source_begin_one(&engine->sources, opener, location, error,
                               error_capacity) != 0) {
        (void)hstex_source_pop_boundary(&engine->sources, NULL, 0U);
        vector_destroy(text);
        return -1;
    }
    hstex_source_name_top(&engine->sources,
                          (uint8_t)HSTEX_TOKEN_SOURCE_INSERTED, 0U);
    hstex_token scanned_opener = 0U;
    struct hstex_source_location opener_location;
    enum hstex_engine_result opener_result =
        raw_next(engine, &scanned_opener, &opener_location, error,
                 error_capacity);
    if (opener_result != HSTEX_ENGINE_TOKEN || scanned_opener != opener) {
        (void)hstex_source_pop_boundary(&engine->sources, NULL, 0U);
        vector_destroy(text);
        if (opener_result == HSTEX_ENGINE_ERROR) {
            return -1;
        }
        return set_error(error, error_capacity,
                         "write expansion lost its opening brace");
    }
    struct hstex_token_vector expanded = {0};
    int status = scan_expanded_text_from_input(
        engine, &expanded, engine->scanning_text_name, true, error,
        error_capacity);
    if (status == 0) {
        /* What stands behind the text's own closing brace should be nothing
           at all. Anything else is the brace this put in, still waiting
           because the text closed the group before it. */
        hstex_token after = 0U;
        struct hstex_source_location where;
        if (raw_next(engine, &after, &where, error, error_capacity) ==
            HSTEX_ENGINE_TOKEN &&
            normalize_frozen_control_sequence(after) != ending) {
            static const char *const help[] = {
                "On this page there's a \\write with fewer real {'s than }'s.",
                "I can't handle that very well; good luck.", NULL};
            tex_error(engine, help, "Unbalanced write command");
            while (raw_next(engine, &after, &where, error, error_capacity) ==
                   HSTEX_ENGINE_TOKEN) {
            }
        }
    }
    (void)hstex_source_pop_boundary(&engine->sources, NULL, 0U);
    if (status != 0) {
        vector_destroy(&expanded);
        return -1;
    }
    status = tokens_to_bytes(engine, &expanded, bytes, byte_count, error,
                             error_capacity);
    vector_destroy(&expanded);
    return status;
}

static int scan_general_text_bytes(struct hstex_engine *engine,
                                   uint8_t **bytes, size_t *byte_count,
                                   bool expanding, char *error,
                                   size_t error_capacity)
{
    hstex_token opening = 0U;
    struct hstex_source_location location;
    if (expanded_next_non_space_unrestricted(
            engine, &opening, &location, error, error_capacity) !=
            HSTEX_ENGINE_TOKEN ||
        !token_is_category(opening, HSTEX_CAT_BEGIN_GROUP)) {
        char named[128];
        describe_token(engine, engine->executing_token, named, sizeof(named));
        return set_error(error, error_capacity,
                         "%s requires a braced token list", named);
    }
    /* The reference names the primitive whose text it is -- "text of
       \\message", "text of \\write" -- and only the main loop knows which
       one that is. */
    char named[128];
    describe_token(engine, engine->executing_token, named, sizeof(named));
    (void)snprintf(engine->scanning_text_name,
                   sizeof(engine->scanning_text_name), "text of %s", named);
    struct hstex_token_vector text = {0};
    if (expanding) {
        /* Expanded where it stands, so nothing is pushed and a fault inside
           the text names the line it is on. */
        if (scan_expanded_text_from_input(engine, &text,
                                          engine->scanning_text_name, false,
                                          error, error_capacity) != 0) {
            vector_destroy(&text);
            return -1;
        }
        int status = tokens_to_bytes(engine, &text, bytes, byte_count, error,
                                     error_capacity);
        vector_destroy(&text);
        return status;
    }
    if (scan_balanced_group(engine, &text, true, engine->scanning_text_name,
                            expanding, error, error_capacity) != 0) {
        vector_destroy(&text);
        return -1;
    }
    /* A \write's text is put back between braces and read as an \edef body
       is; every other text that is gathered and then expanded is read to the
       end of what was gathered and no further. */
    bool is_write = false;
    if (hstex_token_is_control_sequence(engine->executing_token)) {
        const struct hstex_meaning *meaning = hstex_engine_meaning(
            engine, hstex_token_control_sequence_id(engine->executing_token));
        is_write = meaning->command == HSTEX_COMMAND_WRITE;
    }
    if (is_write) {
        return expand_write_text(engine, &text, location, bytes, byte_count,
                                 error, error_capacity);
    }
    if (hstex_source_push_boundary(&engine->sources, error, error_capacity) != 0) {
        vector_destroy(&text);
        return -1;
    }
    if (push_owned_vector(engine, &text, location, error, error_capacity) != 0) {
        (void)hstex_source_pop_boundary(&engine->sources, NULL, 0U);
        vector_destroy(&text);
        return -1;
    }
    return expand_to_bytes(engine, bytes, byte_count, error, error_capacity);
}


/* The text of a \write is kept as it was written, so it can be expanded when
   the page reaches the shipper. See docs/DECISIONS.md, whatsits. */
/* The text of \write, \pdfliteral and the rest: taken whole, expanded
   after. */
static int scan_expanded_general_text(struct hstex_engine *engine,
                                      uint8_t **bytes, size_t *byte_count,
                                      char *error, size_t error_capacity)
{
    return scan_general_text_bytes(engine, bytes, byte_count, false, error,
                                   error_capacity);
}

/* The text of \message and \special: expanded as it is read. */
static int scan_general_text_expanding(struct hstex_engine *engine,
                                       uint8_t **bytes, size_t *byte_count,
                                       char *error, size_t error_capacity)
{
    return scan_general_text_bytes(engine, bytes, byte_count, true, error,
                                   error_capacity);
}

static int scan_general_text(struct hstex_engine *engine,
                             struct hstex_token_vector *text, char *error,
                             size_t error_capacity)
{
    hstex_token opening = 0U;
    struct hstex_source_location location;
    if (expanded_next_non_space_unrestricted(engine, &opening, &location, error,
                                             error_capacity) !=
            HSTEX_ENGINE_TOKEN ||
        !token_is_category(opening, HSTEX_CAT_BEGIN_GROUP)) {
        char named[128];
        describe_token(engine, engine->executing_token, named, sizeof(named));
        return set_error(error, error_capacity,
                         "%s requires a braced token list", named);
    }
    char named[128];
    describe_token(engine, engine->executing_token, named, sizeof(named));
    (void)snprintf(engine->scanning_text_name,
                   sizeof(engine->scanning_text_name), "text of %s", named);
    if (scan_balanced_group(engine, text, true, engine->scanning_text_name,
                            false, error, error_capacity) != 0) {
        vector_destroy(text);
        return -1;
    }
    return 0;
}

/* The bytes a stored token list stands for, with no expansion: what
   \showbox prints for a whatsit. A limit stops the walk once that many
   characters have been written -- the token that reaches it is written
   whole -- and says so. See docs/DECISIONS.md, whatsits. */
static int stored_token_list_text(struct hstex_engine *engine,
                                  uint32_t identifier, uint8_t **bytes,
                                  size_t *byte_count, size_t limit,
                                  bool *truncated, char *error,
                                  size_t error_capacity)
{
    const struct hstex_token_list *list =
        token_list_by_identifier(engine, identifier);
    uint8_t *result = NULL;
    size_t count = 0U;
    size_t capacity = 0U;
    if (truncated != NULL) {
        *truncated = false;
    }
    for (size_t index = 0U; list != NULL && index < list->count; ++index) {
        if (limit != 0U && count >= limit) {
            if (truncated != NULL) {
                *truncated = true;
            }
            break;
        }
        hstex_token token = list->tokens[index];
        if (hstex_token_is_character(token)) {
            uint8_t character = hstex_token_character_code(token);
            if ((token_is_category(token, HSTEX_CAT_PARAMETER) &&
                 append_byte(&result, &count, &capacity, character, error,
                             error_capacity) != 0) ||
                append_byte(&result, &count, &capacity, character, error,
                            error_capacity) != 0) {
                free(result);
                return -1;
            }
        } else if (serialize_control_sequence(engine, token, &result, &count,
                                              &capacity, true, error,
                                              error_capacity) != 0) {
            free(result);
            return -1;
        }
    }
    *bytes = result;
    *byte_count = count;
    return 0;
}

/* The bytes a stored token list stands for once it is expanded, which is what
   a deferred \write sends when its page is shipped. */
static int expand_stored_token_list(struct hstex_engine *engine,
                                    uint32_t identifier, uint8_t **bytes,
                                    size_t *byte_count, char *error,
                                    size_t error_capacity)
{
    const struct hstex_token_list *list =
        token_list_by_identifier(engine, identifier);
    struct hstex_token_vector text = {0};
    for (size_t index = 0U; list != NULL && index < list->count; ++index) {
        if (vector_push(&text, list->tokens[index], error, error_capacity) !=
            0) {
            vector_destroy(&text);
            return -1;
        }
    }
    struct hstex_source_location location = {0};
    /* This is a \write's text and nothing else, so it goes back between
       braces the way an \immediate one does. */
    (void)snprintf(engine->scanning_text_name,
                   sizeof(engine->scanning_text_name), "text of \\write");
    return expand_write_text(engine, &text, location, bytes, byte_count, error,
                             error_capacity);
}

static int hex_digit_value(uint8_t byte)
{
    if (byte >= (uint8_t)'0' && byte <= (uint8_t)'9') {
        return byte - (uint8_t)'0';
    }
    if (byte >= (uint8_t)'a' && byte <= (uint8_t)'f') {
        return byte - (uint8_t)'a' + 10;
    }
    if (byte >= (uint8_t)'A' && byte <= (uint8_t)'F') {
        return byte - (uint8_t)'A' + 10;
    }
    return -1;
}

/* RFC 1321's little-endian MD5 compression.  pdfTeX exposes this digest for
   reproducible identifiers and file fingerprints; keeping the implementation
   here avoids an optional system-crypto dependency changing the engine's
   observable primitive set. */
struct hstex_md5_state {
    uint32_t words[4];
    uint64_t byte_count;
    uint8_t block[64];
    size_t used;
};

static uint32_t md5_rotate_left(uint32_t value, unsigned int amount)
{
    return (value << amount) | (value >> (32U - amount));
}

static void md5_compress(struct hstex_md5_state *state,
                         const uint8_t block[64])
{
    static const uint32_t constants[64] = {
        UINT32_C(0xd76aa478), UINT32_C(0xe8c7b756),
        UINT32_C(0x242070db), UINT32_C(0xc1bdceee),
        UINT32_C(0xf57c0faf), UINT32_C(0x4787c62a),
        UINT32_C(0xa8304613), UINT32_C(0xfd469501),
        UINT32_C(0x698098d8), UINT32_C(0x8b44f7af),
        UINT32_C(0xffff5bb1), UINT32_C(0x895cd7be),
        UINT32_C(0x6b901122), UINT32_C(0xfd987193),
        UINT32_C(0xa679438e), UINT32_C(0x49b40821),
        UINT32_C(0xf61e2562), UINT32_C(0xc040b340),
        UINT32_C(0x265e5a51), UINT32_C(0xe9b6c7aa),
        UINT32_C(0xd62f105d), UINT32_C(0x02441453),
        UINT32_C(0xd8a1e681), UINT32_C(0xe7d3fbc8),
        UINT32_C(0x21e1cde6), UINT32_C(0xc33707d6),
        UINT32_C(0xf4d50d87), UINT32_C(0x455a14ed),
        UINT32_C(0xa9e3e905), UINT32_C(0xfcefa3f8),
        UINT32_C(0x676f02d9), UINT32_C(0x8d2a4c8a),
        UINT32_C(0xfffa3942), UINT32_C(0x8771f681),
        UINT32_C(0x6d9d6122), UINT32_C(0xfde5380c),
        UINT32_C(0xa4beea44), UINT32_C(0x4bdecfa9),
        UINT32_C(0xf6bb4b60), UINT32_C(0xbebfbc70),
        UINT32_C(0x289b7ec6), UINT32_C(0xeaa127fa),
        UINT32_C(0xd4ef3085), UINT32_C(0x04881d05),
        UINT32_C(0xd9d4d039), UINT32_C(0xe6db99e5),
        UINT32_C(0x1fa27cf8), UINT32_C(0xc4ac5665),
        UINT32_C(0xf4292244), UINT32_C(0x432aff97),
        UINT32_C(0xab9423a7), UINT32_C(0xfc93a039),
        UINT32_C(0x655b59c3), UINT32_C(0x8f0ccc92),
        UINT32_C(0xffeff47d), UINT32_C(0x85845dd1),
        UINT32_C(0x6fa87e4f), UINT32_C(0xfe2ce6e0),
        UINT32_C(0xa3014314), UINT32_C(0x4e0811a1),
        UINT32_C(0xf7537e82), UINT32_C(0xbd3af235),
        UINT32_C(0x2ad7d2bb), UINT32_C(0xeb86d391),
    };
    static const unsigned int shifts[64] = {
        7U, 12U, 17U, 22U, 7U, 12U, 17U, 22U,
        7U, 12U, 17U, 22U, 7U, 12U, 17U, 22U,
        5U, 9U, 14U, 20U, 5U, 9U, 14U, 20U,
        5U, 9U, 14U, 20U, 5U, 9U, 14U, 20U,
        4U, 11U, 16U, 23U, 4U, 11U, 16U, 23U,
        4U, 11U, 16U, 23U, 4U, 11U, 16U, 23U,
        6U, 10U, 15U, 21U, 6U, 10U, 15U, 21U,
        6U, 10U, 15U, 21U, 6U, 10U, 15U, 21U,
    };
    uint32_t message[16];
    for (size_t index = 0U; index < 16U; ++index) {
        size_t at = index * 4U;
        message[index] =
            (uint32_t)block[at] | ((uint32_t)block[at + 1U] << 8U) |
            ((uint32_t)block[at + 2U] << 16U) |
            ((uint32_t)block[at + 3U] << 24U);
    }
    uint32_t a = state->words[0];
    uint32_t b = state->words[1];
    uint32_t c = state->words[2];
    uint32_t d = state->words[3];
    for (size_t index = 0U; index < 64U; ++index) {
        uint32_t mixed = 0U;
        size_t message_index = 0U;
        if (index < 16U) {
            mixed = (b & c) | ((~b) & d);
            message_index = index;
        } else if (index < 32U) {
            mixed = (d & b) | ((~d) & c);
            message_index = (5U * index + 1U) % 16U;
        } else if (index < 48U) {
            mixed = b ^ c ^ d;
            message_index = (3U * index + 5U) % 16U;
        } else {
            mixed = c ^ (b | (~d));
            message_index = (7U * index) % 16U;
        }
        uint32_t previous_d = d;
        d = c;
        c = b;
        b += md5_rotate_left(a + mixed + constants[index] +
                                 message[message_index],
                             shifts[index]);
        a = previous_d;
    }
    state->words[0] += a;
    state->words[1] += b;
    state->words[2] += c;
    state->words[3] += d;
}

static void md5_initialize(struct hstex_md5_state *state)
{
    state->words[0] = UINT32_C(0x67452301);
    state->words[1] = UINT32_C(0xefcdab89);
    state->words[2] = UINT32_C(0x98badcfe);
    state->words[3] = UINT32_C(0x10325476);
    state->byte_count = 0U;
    state->used = 0U;
}

static void md5_update(struct hstex_md5_state *state, const uint8_t *bytes,
                       size_t count)
{
    state->byte_count += (uint64_t)count;
    if (state->used != 0U) {
        size_t fill = 64U - state->used;
        if (fill > count) {
            fill = count;
        }
        memcpy(state->block + state->used, bytes, fill);
        state->used += fill;
        bytes += fill;
        count -= fill;
        if (state->used == 64U) {
            md5_compress(state, state->block);
            state->used = 0U;
        }
    }
    while (count >= 64U) {
        md5_compress(state, bytes);
        bytes += 64U;
        count -= 64U;
    }
    if (count != 0U) {
        memcpy(state->block, bytes, count);
        state->used = count;
    }
}

static void md5_finish(struct hstex_md5_state *state, uint8_t digest[16])
{
    uint64_t bit_count = state->byte_count << 3U;
    static const uint8_t padding[64] = {0x80U};
    size_t padding_count =
        state->used < 56U ? 56U - state->used : 120U - state->used;
    md5_update(state, padding, padding_count);
    uint8_t length[8];
    for (size_t index = 0U; index < 8U; ++index) {
        length[index] = (uint8_t)(bit_count >> (8U * index));
    }
    md5_update(state, length, sizeof(length));
    for (size_t word = 0U; word < 4U; ++word) {
        for (size_t byte = 0U; byte < 4U; ++byte) {
            digest[word * 4U + byte] =
                (uint8_t)(state->words[word] >> (8U * byte));
        }
    }
}

static bool pdf_trailer_identifier(const struct hstex_engine *engine,
                                   char identifier[33])
{
    if (engine->pdf_trailer_id_set &&
        engine->pdf_trailer_id_seed_length == 0U) {
        return false;
    }
    struct hstex_md5_state state;
    md5_initialize(&state);
    if (engine->pdf_trailer_id_set) {
        md5_update(&state, engine->pdf_trailer_id_seed,
                   engine->pdf_trailer_id_seed_length);
    } else {
        md5_update(&state, (const uint8_t *)engine->pdf_creation_date,
                   strlen(engine->pdf_creation_date));
        const char *output =
            engine->output_name == NULL ? "" : engine->output_name;
        md5_update(&state, (const uint8_t *)output, strlen(output));
    }
    uint8_t digest[16];
    md5_finish(&state, digest);
    static const char hex[] = "0123456789ABCDEF";
    for (size_t index = 0U; index < sizeof(digest); ++index) {
        identifier[index * 2U] = hex[digest[index] >> 4U];
        identifier[index * 2U + 1U] = hex[digest[index] & 0x0FU];
    }
    identifier[32] = '\0';
    return true;
}

static int expand_pdf_md5_sum(struct hstex_engine *engine,
                              struct hstex_source_location location,
                              char *error, size_t error_capacity)
{
    bool from_file = false;
    if (try_keyword(engine, "file", &from_file, error, error_capacity) != 0) {
        return -1;
    }
    uint8_t *bytes = NULL;
    size_t byte_count = 0U;
    if (scan_expanded_general_text(engine, &bytes, &byte_count, error,
                                   error_capacity) != 0) {
        free(bytes);
        return -1;
    }
    struct hstex_md5_state state;
    md5_initialize(&state);
    if (from_file) {
        if (byte_count == SIZE_MAX ||
            (byte_count != 0U && memchr(bytes, 0, byte_count) != NULL)) {
            free(bytes);
            return 0;
        }
        char *filename = malloc(byte_count + 1U);
        if (filename == NULL) {
            free(bytes);
            return set_error(error, error_capacity,
                             "MD5 filename allocation failed");
        }
        memcpy(filename, bytes, byte_count);
        filename[byte_count] = '\0';
        free(bytes);
        char *path = resolve_input_path(engine, filename);
        free(filename);
        if (path == NULL) {
            return 0;
        }
        FILE *file = fopen(path, "rb");
        free(path);
        if (file == NULL) {
            return 0;
        }
        uint8_t buffer[8192];
        size_t read_count = 0U;
        while ((read_count = fread(buffer, 1U, sizeof(buffer), file)) != 0U) {
            md5_update(&state, buffer, read_count);
        }
        bool failed = ferror(file) != 0;
        int closed = fclose(file);
        if (failed || closed != 0) {
            return set_error(error, error_capacity,
                             "could not read file for MD5 sum");
        }
    } else {
        md5_update(&state, bytes, byte_count);
        free(bytes);
    }
    uint8_t digest[16];
    md5_finish(&state, digest);
    static const char hex_digits[] = "0123456789ABCDEF";
    char rendered[32];
    for (size_t index = 0U; index < sizeof(digest); ++index) {
        rendered[index * 2U] = hex_digits[(digest[index] >> 4U) & 0x0FU];
        rendered[index * 2U + 1U] = hex_digits[digest[index] & 0x0FU];
    }
    return push_other_character_expansion(engine, rendered, sizeof(rendered),
                                          location, error, error_capacity);
}

/* The four PDF string escapes. \pdfescapestring quotes the bytes PDF string
   syntax reserves, \pdfescapename applies PDF name syntax, and the hex pair
   converts to and from hexadecimal; see docs/DECISIONS.md, pdf-escapes. */
static int expand_pdf_escape(struct hstex_engine *engine,
                             enum pdf_escape_kind kind,
                             struct hstex_source_location location, char *error,
                             size_t error_capacity)
{
    uint8_t *bytes = NULL;
    size_t byte_count = 0U;
    if (scan_expanded_general_text(engine, &bytes, &byte_count, error,
                                   error_capacity) != 0) {
        free(bytes);
        return -1;
    }
    static const char hex_digits[] = "0123456789ABCDEF";
    /* Four output bytes per input byte covers the widest escape, \\ooo. */
    char *rendered = malloc(byte_count * 4U + 1U);
    if (rendered == NULL) {
        free(bytes);
        return set_error(error, error_capacity, "escape allocation failed");
    }
    size_t length = 0U;
    int status = 0;
    for (size_t index = 0U; index < byte_count; ++index) {
        uint8_t byte = bytes[index];
        switch (kind) {
        case PDF_ESCAPE_STRING:
            if (byte == (uint8_t)'(' || byte == (uint8_t)')' ||
                byte == (uint8_t)'\\') {
                rendered[length++] = '\\';
                rendered[length++] = (char)byte;
            } else if (byte < 0x21U || byte > 0x7EU) {
                rendered[length++] = '\\';
                rendered[length++] = (char)('0' + ((byte >> 6) & 0x07U));
                rendered[length++] = (char)('0' + ((byte >> 3) & 0x07U));
                rendered[length++] = (char)('0' + (byte & 0x07U));
            } else {
                rendered[length++] = (char)byte;
            }
            break;
        case PDF_ESCAPE_NAME:
            if (byte < 0x21U || byte > 0x7EU || byte == (uint8_t)'#' ||
                byte == (uint8_t)'(' || byte == (uint8_t)')' ||
                byte == (uint8_t)'<' || byte == (uint8_t)'>' ||
                byte == (uint8_t)'[' || byte == (uint8_t)']' ||
                byte == (uint8_t)'{' || byte == (uint8_t)'}' ||
                byte == (uint8_t)'/' || byte == (uint8_t)'%') {
                rendered[length++] = '#';
                rendered[length++] = hex_digits[(byte >> 4) & 0x0FU];
                rendered[length++] = hex_digits[byte & 0x0FU];
            } else {
                rendered[length++] = (char)byte;
            }
            break;
        case PDF_ESCAPE_HEX:
            rendered[length++] = hex_digits[(byte >> 4) & 0x0FU];
            rendered[length++] = hex_digits[byte & 0x0FU];
            break;
        case PDF_UNESCAPE_HEX: {
            int high = hex_digit_value(byte);
            if (high < 0) {
                continue;
            }
            int low = 0;
            while (index + 1U < byte_count) {
                int candidate = hex_digit_value(bytes[index + 1U]);
                ++index;
                if (candidate >= 0) {
                    low = candidate;
                    break;
                }
            }
            rendered[length++] = (char)((high << 4) | low);
            break;
        }
        }
    }
    free(bytes);
    if (status == 0) {
        status = push_other_character_expansion(engine, rendered, length,
                                                location, error,
                                                error_capacity);
    }
    free(rendered);
    return status;
}

/* \pdfglyphtounicode records the mapping the ToUnicode CMap is built from.
   The mapping is stored rather than discarded because extracted text is one
   of the correctness gates. */
static int execute_pdf_glyph_to_unicode(struct hstex_engine *engine,
                                        char *error, size_t error_capacity)
{
    uint8_t *glyph = NULL;
    uint8_t *unicode = NULL;
    size_t glyph_count = 0U;
    size_t unicode_count = 0U;
    if (scan_expanded_general_text(engine, &glyph, &glyph_count, error,
                                   error_capacity) != 0 ||
        scan_expanded_general_text(engine, &unicode, &unicode_count, error,
                                   error_capacity) != 0) {
        free(glyph);
        free(unicode);
        return -1;
    }
    if (engine->glyph_unicode_count == engine->glyph_unicode_capacity) {
        size_t capacity = engine->glyph_unicode_capacity == 0U
                              ? 64U
                              : engine->glyph_unicode_capacity * 2U;
        struct hstex_glyph_unicode *grown = realloc(
            engine->glyph_unicode, capacity * sizeof(*grown));
        if (grown == NULL) {
            free(glyph);
            free(unicode);
            return set_error(error, error_capacity,
                             "glyph-to-unicode allocation failed");
        }
        engine->glyph_unicode = grown;
        engine->glyph_unicode_capacity = capacity;
    }
    char *glyph_text = malloc(glyph_count + 1U);
    char *unicode_text = malloc(unicode_count + 1U);
    if (glyph_text == NULL || unicode_text == NULL) {
        free(glyph);
        free(unicode);
        free(glyph_text);
        free(unicode_text);
        return set_error(error, error_capacity,
                         "glyph-to-unicode allocation failed");
    }
    memcpy(glyph_text, glyph, glyph_count);
    glyph_text[glyph_count] = '\0';
    memcpy(unicode_text, unicode, unicode_count);
    unicode_text[unicode_count] = '\0';
    free(glyph);
    free(unicode);
    if (glyph_unicode_reserve_slots(engine, engine->glyph_unicode_count + 1U,
                                    error, error_capacity) != 0) {
        free(glyph_text);
        free(unicode_text);
        return -1;
    }
    engine->glyph_unicode[engine->glyph_unicode_count].glyph = glyph_text;
    engine->glyph_unicode[engine->glyph_unicode_count].unicode = unicode_text;
    ++engine->glyph_unicode_count;
    glyph_unicode_chain(engine, (uint32_t)engine->glyph_unicode_count);
    return 0;
}

/* Font dictionaries may carry document-supplied entries.  The cmap package
   uses this pair of primitives to install one shared CMap object: it disables
   automatic ToUnicode generation for each font and supplies the reference
   through /ToUnicode in the font attribute. */
static int execute_pdf_font_attribute(struct hstex_engine *engine,
                                      char *error, size_t error_capacity)
{
    uint32_t identifier = 0U;
    uint8_t *bytes = NULL;
    size_t count = 0U;
    if (scan_font_identifier(engine, &identifier, error, error_capacity) != 0 ||
        scan_expanded_general_text(engine, &bytes, &count, error,
                                   error_capacity) != 0) {
        free(bytes);
        return -1;
    }
    struct hstex_font *font = font_by_identifier(engine, identifier);
    char *attribute = malloc(count + 1U);
    if (font == NULL || attribute == NULL) {
        free(bytes);
        free(attribute);
        return set_error(error, error_capacity,
                         "PDF font attribute allocation failed");
    }
    if (count != 0U) {
        memcpy(attribute, bytes, count);
    }
    attribute[count] = '\0';
    free(bytes);
    free(font->pdf_attribute);
    font->pdf_attribute = attribute;
    return 0;
}

static int execute_pdf_no_builtin_to_unicode(
    struct hstex_engine *engine, char *error, size_t error_capacity)
{
    uint32_t identifier = 0U;
    if (scan_font_identifier(engine, &identifier, error, error_capacity) != 0) {
        return -1;
    }
    struct hstex_font *font = font_by_identifier(engine, identifier);
    if (font == NULL) {
        return set_error(error, error_capacity,
                         "invalid font for PDF ToUnicode control");
    }
    font->pdf_no_builtin_to_unicode = true;
    return 0;
}

static void clear_match_groups(struct hstex_engine *engine)
{
    for (size_t index = 0U; index < engine->match_group_count; ++index) {
        free(engine->match_groups[index].text);
    }
    free(engine->match_groups);
    engine->match_groups = NULL;
    engine->match_group_count = 0U;
}

/* \pdfmatch reports 1 for a match, 0 for no match, and -1 for a pattern the
   matcher rejects; see docs/DECISIONS.md, pdf-match. */
static int expand_pdf_match(struct hstex_engine *engine,
                            struct hstex_source_location location, char *error,
                            size_t error_capacity)
{
    bool ignore_case = false;
    int32_t subcount = HSTEX_DEFAULT_MATCH_SUBCOUNT;
    for (;;) {
        bool matched = false;
        if (try_keyword(engine, "icase", &matched, error, error_capacity) != 0) {
            return -1;
        }
        if (matched) {
            ignore_case = true;
            continue;
        }
        if (try_keyword(engine, "subcount", &matched, error, error_capacity) !=
            0) {
            return -1;
        }
        if (!matched) {
            break;
        }
        if (scan_integer(engine, &subcount, error, error_capacity) != 0) {
            return -1;
        }
        if (subcount < 0) {
            return set_error(error, error_capacity,
                             "pdfmatch subcount must not be negative");
        }
    }

    uint8_t *pattern = NULL;
    uint8_t *subject = NULL;
    size_t pattern_count = 0U;
    size_t subject_count = 0U;
    if (scan_expanded_general_text(engine, &pattern, &pattern_count, error,
                                   error_capacity) != 0 ||
        scan_expanded_general_text(engine, &subject, &subject_count, error,
                                   error_capacity) != 0) {
        free(pattern);
        free(subject);
        return -1;
    }
    char *pattern_text = malloc(pattern_count + 1U);
    char *subject_text = malloc(subject_count + 1U);
    if (pattern_text == NULL || subject_text == NULL) {
        free(pattern);
        free(subject);
        free(pattern_text);
        free(subject_text);
        return set_error(error, error_capacity, "match argument allocation failed");
    }
    memcpy(pattern_text, pattern, pattern_count);
    pattern_text[pattern_count] = '\0';
    memcpy(subject_text, subject, subject_count);
    subject_text[subject_count] = '\0';
    free(pattern);
    free(subject);

    clear_match_groups(engine);
    regex_t compiled;
    int flags = REG_EXTENDED | (ignore_case ? REG_ICASE : 0);
    int32_t result = 1;
    if (regcomp(&compiled, pattern_text, flags) != 0) {
        result = -1;
    } else {
        size_t group_capacity =
            subcount > 0 ? (size_t)subcount : (size_t)1;
        regmatch_t *positions = calloc(group_capacity, sizeof(*positions));
        if (positions == NULL) {
            regfree(&compiled);
            free(pattern_text);
            free(subject_text);
            return set_error(error, error_capacity,
                             "match position allocation failed");
        }
        if (regexec(&compiled, subject_text, group_capacity, positions, 0) !=
            0) {
            result = 0;
        } else if (subcount > 0) {
            engine->match_groups =
                calloc(group_capacity, sizeof(*engine->match_groups));
            if (engine->match_groups == NULL) {
                free(positions);
                regfree(&compiled);
                free(pattern_text);
                free(subject_text);
                return set_error(error, error_capacity,
                                 "match group allocation failed");
            }
            engine->match_group_count = group_capacity;
            for (size_t index = 0U; index < group_capacity; ++index) {
                engine->match_groups[index].offset = -1;
                if (positions[index].rm_so < 0) {
                    continue;
                }
                size_t start = (size_t)positions[index].rm_so;
                size_t length = (size_t)(positions[index].rm_eo -
                                         positions[index].rm_so);
                char *text = malloc(length + 1U);
                if (text == NULL) {
                    free(positions);
                    regfree(&compiled);
                    free(pattern_text);
                    free(subject_text);
                    clear_match_groups(engine);
                    return set_error(error, error_capacity,
                                     "match text allocation failed");
                }
                memcpy(text, subject_text + start, length);
                text[length] = '\0';
                engine->match_groups[index].offset = (int32_t)start;
                engine->match_groups[index].text = text;
            }
        }
        free(positions);
        regfree(&compiled);
    }
    free(pattern_text);
    free(subject_text);
    return push_integer_expansion(engine, result, location, error,
                                  error_capacity);
}

/* \pdflastmatch<n> expands to "<offset>-><text>", and to "-1->" when the
   group did not participate or lies beyond the stored subcount. */
static int expand_pdf_last_match(struct hstex_engine *engine,
                                 struct hstex_source_location location,
                                 char *error, size_t error_capacity)
{
    int32_t index = 0;
    if (scan_integer(engine, &index, error, error_capacity) != 0) {
        return -1;
    }
    if (index < 0) {
        return set_error(error, error_capacity, "bad match number (%d)", index);
    }
    const char *text = "";
    int32_t offset = -1;
    if ((size_t)index < engine->match_group_count &&
        engine->match_groups[(size_t)index].offset >= 0) {
        offset = engine->match_groups[(size_t)index].offset;
        text = engine->match_groups[(size_t)index].text;
    }
    char rendered[64];
    int length = snprintf(rendered, sizeof(rendered), "%" PRId32 "->", offset);
    if (length < 0 || (size_t)length >= sizeof(rendered)) {
        return set_error(error, error_capacity, "could not format last match");
    }
    size_t text_length = strlen(text);
    char *combined = malloc((size_t)length + text_length + 1U);
    if (combined == NULL) {
        return set_error(error, error_capacity, "last-match allocation failed");
    }
    memcpy(combined, rendered, (size_t)length);
    memcpy(combined + length, text, text_length + 1U);
    int status = push_other_character_expansion(
        engine, combined, (size_t)length + text_length, location, error,
        error_capacity);
    free(combined);
    return status;
}

/* \scantokens turns its argument into characters, without expanding it, and
   reads them back as though they came from a file: each line ends with
   \endlinechar and the catcodes in force at that moment apply; see
   docs/DECISIONS.md, scantokens. */
static int expand_scan_tokens(struct hstex_engine *engine,
                              struct hstex_source_location location,
                              char *error, size_t error_capacity)
{
    hstex_token opening = 0U;
    struct hstex_source_location opening_location;
    enum hstex_engine_result opening_result =
        expanded_next_non_space_unrestricted(engine, &opening,
                                             &opening_location, error,
                                             error_capacity);
    if (opening_result == HSTEX_ENGINE_ERROR) {
        return -1;
    }
    if (opening_result != HSTEX_ENGINE_TOKEN ||
        !token_is_category(opening, HSTEX_CAT_BEGIN_GROUP)) {
        return set_error(error, error_capacity,
                         "scantokens requires a braced token list");
    }
    struct hstex_token_vector input = {0};
    if (scan_balanced_group(engine, &input, true, "text of \\scantokens", false, error, error_capacity) != 0) {
        vector_destroy(&input);
        return -1;
    }
    (void)location;

    uint8_t *bytes = NULL;
    size_t count = 0U;
    size_t capacity = 0U;
    for (size_t index = 0U; index < input.count; ++index) {
        hstex_token token = normalize_frozen_control_sequence(input.data[index]);
        if (hstex_token_is_character(token)) {
            uint8_t character = hstex_token_character_code(token);
            if ((token_is_category(token, HSTEX_CAT_PARAMETER) &&
                 append_byte(&bytes, &count, &capacity, character, error,
                             error_capacity) != 0) ||
                append_byte(&bytes, &count, &capacity, character, error,
                            error_capacity) != 0) {
                vector_destroy(&input);
                free(bytes);
                return -1;
            }
            continue;
        }
        if (!hstex_token_is_control_sequence(token)) {
            vector_destroy(&input);
            free(bytes);
            return set_error(error, error_capacity,
                             "internal token inside scantokens");
        }
        if (serialize_control_sequence(engine, token, &bytes, &count, &capacity,
                                       true, error, error_capacity) != 0) {
            vector_destroy(&input);
            free(bytes);
            return -1;
        }
    }
    vector_destroy(&input);
    return hstex_source_push_pseudo_file(&engine->sources, bytes, count,
                                         "<scantokens>", error, error_capacity);
}

static int expand_pdf_string_compare(
    struct hstex_engine *engine, struct hstex_source_location location,
    char *error, size_t error_capacity)
{
    uint8_t *left = NULL;
    uint8_t *right = NULL;
    size_t left_count = 0U;
    size_t right_count = 0U;
    if (scan_expanded_general_text(engine, &left, &left_count, error,
                                   error_capacity) != 0 ||
        scan_expanded_general_text(engine, &right, &right_count, error,
                                   error_capacity) != 0) {
        free(left);
        free(right);
        return -1;
    }
    size_t common = left_count < right_count ? left_count : right_count;
    int comparison = common == 0U ? 0 : memcmp(left, right, common);
    int32_t result = 0;
    if (comparison < 0 || (comparison == 0 && left_count < right_count)) {
        result = -1;
    } else if (comparison > 0 ||
               (comparison == 0 && left_count > right_count)) {
        result = 1;
    }
    free(left);
    free(right);
    return push_integer_expansion(engine, result, location, error,
                                  error_capacity);
}

/* An action spec, as \pdfcatalog's openaction and the link and outline
   primitives take it. Nothing acts on it yet; it is scanned so that the
   tokens it covers are consumed exactly, and no more. */
static char *own_general_text(const uint8_t *bytes, size_t count);

static int store_expanded_text(struct hstex_engine *engine, uint32_t *tokens,
                               char *error, size_t error_capacity)
{
    uint8_t *bytes = NULL;
    size_t count = 0U;
    if (scan_expanded_general_text(engine, &bytes, &count, error,
                                   error_capacity) != 0) {
        free(bytes);
        return -1;
    }
    char *text = own_general_text(bytes, count);
    free(bytes);
    if (text == NULL) {
        return set_error(error, error_capacity, "pdf text allocation failed");
    }
    int status = store_text_as_token_list(engine, text, tokens, error,
                                          error_capacity);
    free(text);
    return status;
}

/* What a link is to do when it is followed: go to a place in this document
   or another, take up a thread, or whatever the document itself says. See
   docs/DECISIONS.md, pdf-links. */
static int scan_pdf_action(struct hstex_engine *engine,
                           struct hstex_pdf_action *action, char *error,
                           size_t error_capacity)
{
    memset(action, 0, sizeof(*action));
    bool matched = false;
    if (try_keyword(engine, "user", &matched, error, error_capacity) != 0) {
        return -1;
    }
    if (matched) {
        action->kind = (uint8_t)HSTEX_PDF_ACTION_USER;
        return store_expanded_text(engine, &action->text, error,
                                   error_capacity);
    }
    bool thread = false;
    if (try_keyword(engine, "goto", &matched, error, error_capacity) != 0) {
        return -1;
    }
    if (!matched) {
        if (try_keyword(engine, "thread", &thread, error, error_capacity) !=
            0) {
            return -1;
        }
        if (!thread) {
            return set_error(error, error_capacity,
                             "an action specification was expected here");
        }
    }
    action->kind = thread ? (uint8_t)HSTEX_PDF_ACTION_THREAD
                          : (uint8_t)HSTEX_PDF_ACTION_GOTO;
    if (!thread &&
        try_keyword(engine, "struct", &action->structured, error,
                    error_capacity) != 0) {
        return -1;
    }
    if (action->structured) {
        if (try_keyword(engine, "name", &action->structure_named, error,
                        error_capacity) != 0) {
            return -1;
        }
        if (action->structure_named) {
            if (store_expanded_text(engine, &action->structure_name, error,
                                    error_capacity) != 0) {
                return -1;
            }
        } else {
            bool numbered = false;
            if (try_keyword(engine, "num", &numbered, error, error_capacity) !=
                0) {
                return -1;
            }
            if (!numbered) {
                return set_error(error, error_capacity,
                                 "a structure destination was expected here");
            }
            if (scan_integer(engine, &action->structure_number, error,
                             error_capacity) != 0) {
                return -1;
            }
        }
    }
    bool file = false;
    if (try_keyword(engine, "file", &file, error, error_capacity) != 0) {
        return -1;
    }
    if (file &&
        store_expanded_text(engine, &action->file, error, error_capacity) !=
            0) {
        return -1;
    }
    bool named = false;
    if (try_keyword(engine, "name", &named, error, error_capacity) != 0) {
        return -1;
    }
    if (named) {
        if (store_expanded_text(engine, &action->name, error, error_capacity) !=
            0) {
            return -1;
        }
    } else {
        bool numbered = false;
        if (try_keyword(engine, "num", &numbered, error, error_capacity) != 0) {
            return -1;
        }
        if (numbered) {
            action->numbered = true;
            if (scan_integer(engine, &action->number, error, error_capacity) !=
                0) {
                return -1;
            }
        } else if (!thread) {
            /* `page <number> <general text>` is the remaining goto form. */
            bool page = false;
            if (try_keyword(engine, "page", &page, error, error_capacity) !=
                0) {
                return -1;
            }
            if (!page) {
                return set_error(error, error_capacity,
                                 "a destination was expected here");
            }
            action->numbered = true;
            action->paged = true;
            if (scan_integer(engine, &action->number, error, error_capacity) !=
                    0 ||
                store_expanded_text(engine, &action->text, error,
                                    error_capacity) != 0) {
                return -1;
            }
        }
    }
    bool window = false;
    if (try_keyword(engine, "newwindow", &window, error, error_capacity) != 0) {
        return -1;
    }
    action->windowed = window;
    action->new_window = window;
    if (!window) {
        if (try_keyword(engine, "nonewwindow", &window, error,
                        error_capacity) != 0) {
            return -1;
        }
        action->windowed = window;
    }
    return 0;
}

/* Keep the action, so that the link that carries it can name it again when
   the page is written. */
static int add_pdf_action(struct hstex_engine *engine,
                          const struct hstex_pdf_action *action,
                          uint32_t *index, char *error, size_t error_capacity)
{
    if (engine->pdf_action_count == engine->pdf_action_capacity) {
        size_t capacity = engine->pdf_action_capacity == 0U
                              ? 16U
                              : engine->pdf_action_capacity * 2U;
        struct hstex_pdf_action *grown =
            realloc(engine->pdf_actions, capacity * sizeof(*grown));
        if (grown == NULL) {
            return set_error(error, error_capacity,
                             "pdf action allocation failed");
        }
        engine->pdf_actions = grown;
        engine->pdf_action_capacity = capacity;
    }
    engine->pdf_actions[engine->pdf_action_count] = *action;
    *index = (uint32_t)(engine->pdf_action_count + 1U);
    ++engine->pdf_action_count;
    return 0;
}

/* Copy a scanned general text into an owned string. */
static char *own_general_text(const uint8_t *bytes, size_t count)
{
    char *text = malloc(count + 1U);
    if (text == NULL) {
        return NULL;
    }
    memcpy(text, bytes, count);
    text[count] = '\0';
    return text;
}

/* \pdfcatalog and \pdfinfo each accumulate into one dictionary, so repeated
   uses append rather than replace. */
/* What the document says about itself, kept as it was written: a second
   \pdfinfo or \pdfcatalog is joined to the first with nothing between them.
   See docs/DECISIONS.md, what-the-document-says-about-itself. */
static int append_pdf_dictionary(uint8_t **buffer, size_t *length,
                                 size_t *capacity, const uint8_t *bytes,
                                 size_t count, char *error,
                                 size_t error_capacity)
{
    for (size_t index = 0U; index < count; ++index) {
        if (append_byte(buffer, length, capacity, bytes[index], error,
                        error_capacity) != 0) {
            return -1;
        }
    }
    return 0;
}

static int execute_pdf_dictionary(struct hstex_engine *engine, bool catalog,
                                  char *error, size_t error_capacity)
{
    uint8_t *bytes = NULL;
    size_t count = 0U;
    if (scan_expanded_general_text(engine, &bytes, &count, error,
                                   error_capacity) != 0) {
        free(bytes);
        return -1;
    }
    /* \pdfcatalog may name an action to take when the document opens; it is
       scanned so that execution continues, and recorded with the rest. */
    bool matched = false;
    if (catalog &&
        try_keyword(engine, "openaction", &matched, error, error_capacity) !=
            0) {
        free(bytes);
        return -1;
    }
    struct hstex_pdf_action opened = {0};
    if (matched &&
        scan_pdf_action(engine, &opened, error, error_capacity) != 0) {
        free(bytes);
        return -1;
    }
    /* The action goes into an object of its own where it is written, and the
       catalogue points at it. A second one is an error the reference stops
       on. See docs/DECISIONS.md, what-the-document-says-about-itself. */
    if (matched) {
        if (engine->pdf_open_action != 0U) {
            free(bytes);
            return set_error(error, error_capacity,
                             "duplicate of openaction");
        }
        size_t object = pdf_new_object(engine);
        if (pdf_open(engine, error, error_capacity) != 0 ||
            pdf_begin_object(engine, object, error, error_capacity) != 0 ||
            pdf_write_action(engine, &opened, false, error, error_capacity) !=
                0 ||
            pdf_end_object(engine, error, error_capacity) != 0) {
            free(bytes);
            return -1;
        }
        engine->pdf_open_action = object;
    }
    int status = append_pdf_dictionary(
        catalog ? &engine->pdf_catalog : &engine->pdf_info,
        catalog ? &engine->pdf_catalog_length : &engine->pdf_info_length,
        catalog ? &engine->pdf_catalog_capacity : &engine->pdf_info_capacity,
        bytes, count, error, error_capacity);
    free(bytes);
    return status;
}

/* \pdftrailerid hashes its expanded general text verbatim.  An empty text
   suppresses /ID; without the primitive, pdfTeX hashes the creation date
   followed immediately by the output path.  Public reproducible-output
   probes pin both cases. */
static int execute_pdf_trailer_id(struct hstex_engine *engine, char *error,
                                  size_t error_capacity)
{
    uint8_t *bytes = NULL;
    size_t count = 0U;
    if (scan_expanded_general_text(engine, &bytes, &count, error,
                                   error_capacity) != 0) {
        free(bytes);
        return -1;
    }
    free(engine->pdf_trailer_id_seed);
    engine->pdf_trailer_id_seed = bytes;
    engine->pdf_trailer_id_seed_length = count;
    engine->pdf_trailer_id_set = true;
    return 0;
}

static int reserve_pdf_objects(struct hstex_engine *engine, size_t required,
                               char *error, size_t error_capacity)
{
    if (required <= engine->pdf_object_capacity) {
        return 0;
    }
    size_t capacity = engine->pdf_object_capacity == 0U
                          ? 16U
                          : engine->pdf_object_capacity * 2U;
    while (capacity < required) {
        capacity *= 2U;
    }
    struct hstex_pdf_object *grown =
        realloc(engine->pdf_objects, capacity * sizeof(*grown));
    if (grown == NULL) {
        return set_error(error, error_capacity, "pdf object table allocation failed");
    }
    engine->pdf_objects = grown;
    engine->pdf_object_capacity = capacity;
    return 0;
}

static struct hstex_pdf_object *pdf_object_by_number(struct hstex_engine *engine,
                                                     int32_t number)
{
    for (size_t index = 0U; index < engine->pdf_object_count; ++index) {
        if (engine->pdf_objects[index].number == number) {
            return &engine->pdf_objects[index];
        }
    }
    return NULL;
}

/* \pdfobj [reserveobjnum | useobjnum <n>] [stream [attr <text>]] <text> */
static int execute_pdf_object(struct hstex_engine *engine, bool immediate,
                              char *error, size_t error_capacity)
{
    bool reserve = false;
    bool use_number = false;
    bool stream = false;
    bool from_file = false;
    int32_t number = 0;
    if (try_keyword(engine, "reserveobjnum", &reserve, error, error_capacity) !=
        0) {
        return -1;
    }
    /* `reserveobjnum' is the whole object specification, and the reference
       consumes one expanded spacer after it. This matters in horizontal
       mode: LaTeX's object allocator leaves a spacer there, and exposing it
       would create interword glue before the following hook whatsit. See
       docs/DECISIONS.md, PDF objects. */
    if (reserve && skip_optional_space(engine, error, error_capacity) != 0) {
        return -1;
    }
    if (!reserve) {
        if (try_keyword(engine, "useobjnum", &use_number, error,
                        error_capacity) != 0) {
            return -1;
        }
        if (use_number &&
            scan_integer(engine, &number, error, error_capacity) != 0) {
            return -1;
        }
        if (try_keyword(engine, "stream", &stream, error, error_capacity) !=
            0) {
            return -1;
        }
    }
    uint8_t *attributes = NULL;
    size_t attribute_count = 0U;
    if (stream) {
        bool matched = false;
        if (try_keyword(engine, "attr", &matched, error, error_capacity) != 0) {
            return -1;
        }
        if (matched && scan_expanded_general_text(engine, &attributes,
                                                  &attribute_count, error,
                                                  error_capacity) != 0) {
            free(attributes);
            return -1;
        }
        if (try_keyword(engine, "file", &from_file, error, error_capacity) !=
            0) {
            free(attributes);
            return -1;
        }
    }
    uint8_t *content = NULL;
    size_t content_count = 0U;
    if (!reserve && scan_expanded_general_text(engine, &content, &content_count,
                                               error, error_capacity) != 0) {
        free(attributes);
        free(content);
        return -1;
    }
    if (from_file) {
        if (content_count == SIZE_MAX ||
            (content_count != 0U && memchr(content, 0, content_count) != NULL)) {
            free(attributes);
            free(content);
            return set_error(error, error_capacity,
                             "invalid PDF stream filename");
        }
        char *filename = malloc(content_count + 1U);
        if (filename == NULL) {
            free(attributes);
            free(content);
            return set_error(error, error_capacity,
                             "PDF stream filename allocation failed");
        }
        memcpy(filename, content, content_count);
        filename[content_count] = '\0';
        free(content);
        content = NULL;
        content_count = 0U;
        char *path = resolve_input_path(engine, filename);
        free(filename);
        if (path == NULL ||
            read_whole_path(path, &content, &content_count, error,
                            error_capacity) != 0) {
            free(path);
            free(attributes);
            free(content);
            return path == NULL
                       ? set_error(error, error_capacity,
                                   "cannot find PDF stream file")
                       : -1;
        }
        free(path);
    }

    struct hstex_pdf_object *target = NULL;
    if (use_number) {
        target = pdf_object_by_number(engine, number);
        if (target == NULL) {
            free(attributes);
            free(content);
            return set_error(error, error_capacity,
                             "pdf object %d was never reserved", number);
        }
    } else {
        if (reserve_pdf_objects(engine, engine->pdf_object_count + 1U, error,
                                error_capacity) != 0) {
            free(attributes);
            free(content);
            return -1;
        }
        target = &engine->pdf_objects[engine->pdf_object_count++];
        memset(target, 0, sizeof(*target));
        target->number = ++engine->pdf_object_counter;
    }
    engine->pdf_last[HSTEX_PDF_LAST_OBJECT] = target->number;
    target->reserved = reserve;
    target->stream = stream;
    free(target->attributes);
    free(target->content);
    target->attributes = attributes == NULL
                             ? NULL
                             : own_general_text(attributes, attribute_count);
    target->attribute_length = attribute_count;
    target->content =
        content == NULL ? NULL : own_general_text(content, content_count);
    target->content_length = content_count;
    free(attributes);
    free(content);
    if ((!reserve && target->attributes == NULL && attribute_count != 0U) ||
        (!reserve && target->content == NULL && content_count != 0U)) {
        return set_error(error, error_capacity,
                         "pdf object content allocation failed");
    }
    /* An immediate object is written now regardless of whether that means a
       direct object or an entry in the current object stream.  Postponing a
       compressed one changes both the object-stream membership and the
       numbers assigned to containers created later in the document. */
    if (immediate && !reserve) {
        if (pdf_open(engine, error, error_capacity) != 0 ||
            pdf_write_document_object(engine, target, error, error_capacity) !=
                0) {
            return -1;
        }
    }
    return 0;
}

/* \pdfrefobj marks an object as reachable; with no backend there is nothing
   to prune, so the number is only checked. */
static int execute_pdf_ref_object(struct hstex_engine *engine, char *error,
                                  size_t error_capacity)
{
    int32_t number = 0;
    if (scan_integer(engine, &number, error, error_capacity) != 0) {
        return -1;
    }
    if (pdf_object_by_number(engine, number) == NULL) {
        return set_error(error, error_capacity,
                         "pdf object %d does not exist", number);
    }
    return 0;
}

static int execute_pdf_literal(struct hstex_engine *engine, char *error,
                               size_t error_capacity)
{
    int32_t mode = (int32_t)HSTEX_PDF_LITERAL_SET;
    bool shipout = false;
    bool matched = false;
    if (try_keyword(engine, "shipout", &shipout, error, error_capacity) != 0) {
        return -1;
    }
    if (try_keyword(engine, "direct", &matched, error, error_capacity) != 0) {
        return -1;
    }
    if (matched) {
        mode = (int32_t)HSTEX_PDF_LITERAL_DIRECT;
    } else {
        if (try_keyword(engine, "page", &matched, error, error_capacity) != 0) {
            return -1;
        }
        if (matched) {
            mode = (int32_t)HSTEX_PDF_LITERAL_PAGE;
        }
    }
    uint8_t action = (uint8_t)mode;
    if (shipout) {
        action |= (uint8_t)HSTEX_PDF_LITERAL_SHIPOUT;
    }
    uint32_t tokens = 0U;
    char *recorded = NULL;
    if (shipout) {
        struct hstex_token_vector text = {0};
        if (scan_general_text(engine, &text, error, error_capacity) != 0 ||
            store_token_list(engine, &text, &tokens, error, error_capacity) !=
                0) {
            vector_destroy(&text);
            return -1;
        }
        uint8_t *shown = NULL;
        size_t shown_count = 0U;
        if (stored_token_list_text(engine, tokens, &shown, &shown_count, 0U,
                                   NULL, error, error_capacity) != 0) {
            free(shown);
            return -1;
        }
        recorded = own_general_text(shown, shown_count);
        free(shown);
    } else {
        uint8_t *content = NULL;
        size_t count = 0U;
        if (scan_expanded_general_text(engine, &content, &count, error,
                                       error_capacity) != 0) {
            free(content);
            return -1;
        }
        recorded = own_general_text(content, count);
        free(content);
        if (recorded != NULL &&
            store_text_as_token_list(engine, recorded, &tokens, error,
                                     error_capacity) != 0) {
            free(recorded);
            return -1;
        }
    }
    if (recorded == NULL) {
        return set_error(error, error_capacity,
                         "pdf literal allocation failed");
    }
    if (engine->pdf_literal_count == engine->pdf_literal_capacity) {
        size_t capacity = engine->pdf_literal_capacity == 0U
                              ? 16U
                              : engine->pdf_literal_capacity * 2U;
        struct hstex_pdf_literal *grown =
            realloc(engine->pdf_literals, capacity * sizeof(*grown));
        if (grown == NULL) {
            free(recorded);
            return set_error(error, error_capacity,
                             "pdf literal table allocation failed");
        }
        engine->pdf_literals = grown;
        engine->pdf_literal_capacity = capacity;
    }
    struct hstex_pdf_literal *literal =
        &engine->pdf_literals[engine->pdf_literal_count];
    literal->mode = (int32_t)action;
    literal->content = recorded;
    ++engine->pdf_literal_count;
    /* The literal stands in the list where it was written, so that the page
       carries it at that place. See docs/DECISIONS.md, colour-on-a-page. */
    struct hstex_node node = {
        .kind = HSTEX_NODE_WHATSIT,
        .value.whatsit = {.kind = (uint8_t)HSTEX_WHATSIT_LITERAL,
                          .action = action,
                          .tokens = tokens},
    };
    return append_current_list_node(engine, &node, error, error_capacity);
}

/* The public pdfTeX interface represents graphics-state transforms as
   zero-width whatsits at the current TeX point.  Matrix text is expanded
   when the primitive is read; the PDF coordinate pass adds the two zero
   translation operands and the cm operator. See docs/DECISIONS.md,
   PDF transformations. */
static int execute_pdf_transform(struct hstex_engine *engine, uint8_t kind,
                                 char *error, size_t error_capacity)
{
    uint32_t tokens = 0U;
    if (kind == (uint8_t)HSTEX_WHATSIT_PDF_SET_MATRIX &&
        store_expanded_text(engine, &tokens, error, error_capacity) != 0) {
        return -1;
    }
    struct hstex_node node = {
        .kind = HSTEX_NODE_WHATSIT,
        .value.whatsit = {.kind = kind, .tokens = tokens},
    };
    return append_current_list_node(engine, &node, error, error_capacity);
}

/* The node most recently contributed to the list being built, or NULL when
   that list is empty; see docs/DECISIONS.md, last-node-queries. */
static const struct hstex_node *current_list_last_node(
    const struct hstex_engine *engine)
{
    const uint32_t *identifiers = NULL;
    size_t count = 0U;
    if (engine->mode == HSTEX_MODE_HORIZONTAL) {
        if (engine->active_hbox_builder == NULL) {
            return NULL;
        }
        identifiers = engine->active_hbox_builder->node_identifiers;
        count = engine->active_hbox_builder->count;
    } else if (engine->mode == HSTEX_MODE_VERTICAL) {
        if (engine->active_vbox_builder == NULL) {
            return NULL;
        }
        identifiers = engine->active_vbox_builder->node_identifiers;
        count = engine->active_vbox_builder->count;
    }
    if (count == 0U || identifiers == NULL) {
        return NULL;
    }
    uint32_t identifier = identifiers[count - 1U];
    if (identifier == 0U || (size_t)identifier > engine->node_count) {
        return NULL;
    }
    return &engine->nodes[identifier - 1U];
}

/* The last thing in the formula being built. A math list is made of noads
   rather than of nodes, so a last-item query in math mode has to look at it
   here. Glue, a kern and a penalty written in a formula keep the shape they
   have anywhere else and are held inside a noad; \mskip and \mkern do not,
   and are looked at where each query wants them. */
static const struct hstex_noad *last_math_noad(const struct hstex_engine *engine)
{
    if (engine->mode != HSTEX_MODE_MATH || engine->math_depth == 0U) {
        return NULL;
    }
    const struct hstex_math_builder *builder =
        &engine->math_stack[engine->math_depth - 1U];
    if (builder->count == 0U || builder->noads == NULL) {
        return NULL;
    }
    return &builder->noads[builder->count - 1U];
}

/* \lastnodetype and its relatives look at the contribution list, and when
   the page builder has emptied that they report the last node it took; see
   docs/DECISIONS.md, the-last-node-of-a-page. */
static const struct hstex_node *last_item_node(const struct hstex_engine *engine)
{
    if (engine->mode == HSTEX_MODE_MATH) {
        const struct hstex_noad *noad = last_math_noad(engine);
        if (noad == NULL || noad->kind != (uint8_t)HSTEX_NOAD_NODE ||
            noad->node == 0U || (size_t)noad->node > engine->node_count) {
            return NULL;
        }
        return &engine->nodes[noad->node - 1U];
    }
    const struct hstex_node *node = current_list_last_node(engine);
    if (node != NULL || engine->mode != HSTEX_MODE_VERTICAL ||
        engine->active_vbox_builder != engine->contribution_builder ||
        !engine->page_last_taken) {
        return node;
    }
    return &engine->page_last_node;
}

/* The node type numbers are the ones the reference reports, with -1 for an
   empty list. */
static int32_t last_node_type(const struct hstex_node *node)
{
    if (node == NULL) {
        return -1;
    }
    switch (node->kind) {
    case HSTEX_NODE_CHARACTER:
        return 0;
    case HSTEX_NODE_LIST:
        return node->value.list.box_kind == HSTEX_BOX_VLIST ? 2 : 1;
    case HSTEX_NODE_RULE:
        return 3;
    case HSTEX_NODE_GLUE:
        return 11;
    case HSTEX_NODE_KERN:
        return 12;
    case HSTEX_NODE_LIGATURE:
        return 7;
    case HSTEX_NODE_UNSET:
    case HSTEX_NODE_ADJUST:
        return 5;
    case HSTEX_NODE_PENALTY:
        return 13;
    case HSTEX_NODE_WHATSIT:
        return 9;
    case HSTEX_NODE_DISCRETIONARY:
        return 8;
    case HSTEX_NODE_MATH:
        return 10;
    case HSTEX_NODE_MARK:
        return 5;
    case HSTEX_NODE_INSERT:
        return 4;
    }
    return -1;
}

/* Record something the backend will place. Nothing is written; see
   docs/DECISIONS.md, pdf-annotations. */
static struct hstex_pdf_record *add_pdf_record(struct hstex_engine *engine,
                                               enum hstex_pdf_record_kind kind,
                                               char *error,
                                               size_t error_capacity)
{
    if (engine->pdf_record_count == engine->pdf_record_capacity) {
        size_t capacity = engine->pdf_record_capacity == 0U
                              ? 16U
                              : engine->pdf_record_capacity * 2U;
        struct hstex_pdf_record *grown =
            realloc(engine->pdf_records, capacity * sizeof(*grown));
        if (grown == NULL) {
            (void)set_error(error, error_capacity,
                            "pdf record table allocation failed");
            return NULL;
        }
        engine->pdf_records = grown;
        engine->pdf_record_capacity = capacity;
    }
    struct hstex_pdf_record *record =
        &engine->pdf_records[engine->pdf_record_count++];
    memset(record, 0, sizeof(*record));
    record->kind = kind;
    return record;
}

/* An optional `attr <general text>`, returned as an owned string. */
static int scan_optional_pdf_text(struct hstex_engine *engine,
                                  const char *keyword, char **text,
                                  char *error, size_t error_capacity)
{
    *text = NULL;
    bool matched = false;
    if (try_keyword(engine, keyword, &matched, error, error_capacity) != 0) {
        return -1;
    }
    if (!matched) {
        return 0;
    }
    uint8_t *bytes = NULL;
    size_t count = 0U;
    if (scan_expanded_general_text(engine, &bytes, &count, error,
                                   error_capacity) != 0) {
        free(bytes);
        return -1;
    }
    *text = own_general_text(bytes, count);
    free(bytes);
    return *text == NULL
               ? set_error(error, error_capacity, "pdf text allocation failed")
               : 0;
}

/* A destination type. The longer names are tried first, because `fitb` is a
   prefix of `fitbh` and `fit` of the rest. */
/* A destination's dimension is written as a star where it is left to the
   document, exactly as a rule's is. */
static size_t append_destination_dimen(char *buffer, size_t used, size_t size,
                                       int32_t value)
{
    char digits[64];
    int length = value == HSTEX_RUNNING_DIMEN
                     ? snprintf(digits, sizeof(digits), "*")
                     : format_scaled_value(value, "", digits, sizeof(digits));
    if (length <= 0 || used + (size_t)length >= size) {
        return used;
    }
    memcpy(buffer + used, digits, (size_t)length);
    return used + (size_t)length;
}

/* The type reads back the way the reference writes it out: `xyz zoom2000`,
   `fitr(3.0+1.0)x10.0` and the bare names. See docs/DECISIONS.md,
   pdf-destinations. */
static int scan_pdf_destination_type(struct hstex_engine *engine, char **type,
                                     struct hstex_node *shape, char *error,
                                     size_t error_capacity)
{
    static const char *const types[] = {"fitbh", "fitbv", "fitb", "fith",
                                        "fitv",  "fitr",  "xyz",  "fit"};
    static const uint8_t kinds[] = {
        (uint8_t)HSTEX_PDF_DEST_FITBH, (uint8_t)HSTEX_PDF_DEST_FITBV,
        (uint8_t)HSTEX_PDF_DEST_FITB,  (uint8_t)HSTEX_PDF_DEST_FITH,
        (uint8_t)HSTEX_PDF_DEST_FITV,  (uint8_t)HSTEX_PDF_DEST_FITR,
        (uint8_t)HSTEX_PDF_DEST_XYZ,   (uint8_t)HSTEX_PDF_DEST_FIT,
    };
    for (size_t index = 0U; index < sizeof(types) / sizeof(types[0]); ++index) {
        bool matched = false;
        if (try_keyword(engine, types[index], &matched, error,
                        error_capacity) != 0) {
            return -1;
        }
        if (!matched) {
            continue;
        }
        char text[128];
        size_t used = strlen(types[index]);
        memcpy(text, types[index], used);
        shape->value.whatsit.action = kinds[index];
        if (strcmp(types[index], "xyz") == 0) {
            bool zoom = false;
            if (try_keyword(engine, "zoom", &zoom, error, error_capacity) !=
                0) {
                return -1;
            }
            int32_t factor = 0;
            if (zoom) {
                if (scan_integer(engine, &factor, error, error_capacity) != 0) {
                    return -1;
                }
                shape->value.whatsit.action =
                    (uint8_t)HSTEX_PDF_DEST_XYZ_ZOOM;
                shape->shift = factor;
                int written = snprintf(text + used, sizeof(text) - used,
                                       " zoom%d", factor);
                if (written > 0) {
                    used += (size_t)written;
                }
            }
        } else if (strcmp(types[index], "fitr") == 0) {
            struct hstex_node rule = {
                .kind = HSTEX_NODE_RULE,
                .width = HSTEX_RUNNING_DIMEN,
                .height = HSTEX_RUNNING_DIMEN,
                .depth = HSTEX_RUNNING_DIMEN,
            };
            if (scan_rule_dimensions(engine, &rule, error, error_capacity) !=
                0) {
                return -1;
            }
            shape->width = rule.width;
            shape->height = rule.height;
            shape->depth = rule.depth;
            text[used++] = '(';
            used = append_destination_dimen(text, used, sizeof(text),
                                            rule.height);
            text[used++] = '+';
            used = append_destination_dimen(text, used, sizeof(text),
                                            rule.depth);
            text[used++] = ')';
            text[used++] = 'x';
            used = append_destination_dimen(text, used, sizeof(text),
                                            rule.width);
        }
        text[used] = '\0';
        *type = own_general_text((const uint8_t *)text, used);
        if (*type == NULL) {
            return set_error(error, error_capacity,
                             "pdf destination allocation failed");
        }
        /* The reference looks for another keyword after the type and throws
           away the space it finds first; see docs/DECISIONS.md,
           destinations-in-the-file. */
        return skip_optional_space(engine, error, error_capacity);
    }
    return set_error(error, error_capacity,
                     "a destination type was expected here");
}

static int execute_pdf_dest(struct hstex_engine *engine, char *error,
                            size_t error_capacity)
{
    bool structured = false;
    int32_t structure = 0;
    if (try_keyword(engine, "struct", &structured, error, error_capacity) !=
        0) {
        return -1;
    }
    if (structured) {
        if (scan_integer(engine, &structure, error, error_capacity) != 0) {
            return -1;
        }
        if (structure <= 0) {
            return set_error(error, error_capacity,
                             "a positive structure object was expected here");
        }
    }
    bool named = false;
    int32_t number = 0;
    char *name = NULL;
    if (try_keyword(engine, "num", &named, error, error_capacity) != 0) {
        return -1;
    }
    if (named) {
        if (scan_integer(engine, &number, error, error_capacity) != 0) {
            return -1;
        }
    } else {
        bool by_name = false;
        if (try_keyword(engine, "name", &by_name, error, error_capacity) != 0) {
            return -1;
        }
        if (!by_name) {
            return set_error(error, error_capacity,
                             "a destination identifier was expected here");
        }
        uint8_t *bytes = NULL;
        size_t count = 0U;
        if (scan_expanded_general_text(engine, &bytes, &count, error,
                                       error_capacity) != 0) {
            free(bytes);
            return -1;
        }
        name = own_general_text(bytes, count);
        free(bytes);
        if (name == NULL) {
            return set_error(error, error_capacity,
                             "pdf destination allocation failed");
        }
    }
    char *type = NULL;
    struct hstex_node node = {
        .kind = HSTEX_NODE_WHATSIT,
        .value.whatsit = {.kind = (uint8_t)HSTEX_WHATSIT_PDF_DEST},
    };
    if (scan_pdf_destination_type(engine, &type, &node, error,
                                  error_capacity) != 0) {
        free(name);
        return -1;
    }
    /* The destination is a whatsit in the list as well as a record for the
       backend: it is what \lastnodetype sees and where the page may break.
       See docs/DECISIONS.md, pdf-destinations. */
    uint32_t name_tokens = 0U;
    uint32_t type_tokens = 0U;
    if ((name != NULL && store_text_as_token_list(engine, name, &name_tokens,
                                                  error, error_capacity) != 0) ||
        store_text_as_token_list(engine, type, &type_tokens, error,
                                 error_capacity) != 0) {
        free(name);
        free(type);
        return -1;
    }
    node.value.whatsit.stream = name != NULL ? 1U : 0U;
    node.value.whatsit.tokens = name_tokens;
    node.value.whatsit.detail = type_tokens;
    node.value.whatsit.number = number;
    node.value.whatsit.structure = structure;
    if (append_current_list_node(engine, &node, error, error_capacity) != 0) {
        free(name);
        free(type);
        return -1;
    }
    struct hstex_pdf_record *record =
        add_pdf_record(engine, HSTEX_PDF_RECORD_DESTINATION, error,
                       error_capacity);
    if (record == NULL) {
        free(name);
        free(type);
        return -1;
    }
    record->number = structure;
    record->value = number;
    record->name = name;
    record->content = type;
    return 0;
}

/* \pdfstartlink leaves a whatsit where it stands, so that the page can put
   an annotation over the material that follows it, and \pdfendlink another
   where that material ends. The size is what the box the link covers
   measures unless the link says otherwise. See docs/DECISIONS.md,
   pdf-links. */
static int execute_pdf_start_link(struct hstex_engine *engine, char *error,
                                  size_t error_capacity)
{
    struct hstex_node rule = {.width = HSTEX_RUNNING_DIMEN,
                              .height = HSTEX_RUNNING_DIMEN,
                              .depth = HSTEX_RUNNING_DIMEN};
    if (scan_rule_dimensions(engine, &rule, error, error_capacity) != 0) {
        return -1;
    }
    char *attributes = NULL;
    if (scan_optional_pdf_text(engine, "attr", &attributes, error,
                               error_capacity) != 0) {
        return -1;
    }
    struct hstex_pdf_action action = {0};
    if (scan_pdf_action(engine, &action, error, error_capacity) != 0) {
        free(attributes);
        return -1;
    }
    uint32_t attribute_tokens = 0U;
    if (attributes != NULL &&
        store_text_as_token_list(engine, attributes, &attribute_tokens, error,
                                 error_capacity) != 0) {
        free(attributes);
        return -1;
    }
    uint32_t index = 0U;
    if (add_pdf_action(engine, &action, &index, error, error_capacity) != 0) {
        free(attributes);
        return -1;
    }
    struct hstex_pdf_record *record =
        add_pdf_record(engine, HSTEX_PDF_RECORD_LINK, error, error_capacity);
    if (record == NULL) {
        free(attributes);
        return -1;
    }
    record->number = ++engine->pdf_object_counter;
    engine->pdf_last[HSTEX_PDF_LAST_LINK] = record->number;
    record->content = attributes;
    struct hstex_node node = {
        .kind = HSTEX_NODE_WHATSIT,
        .width = rule.width,
        .height = rule.height,
        .depth = rule.depth,
        .value.whatsit = {.kind = (uint8_t)HSTEX_WHATSIT_START_LINK,
                          .stream = attributes != NULL ? 1U : 0U,
                          .tokens = attribute_tokens,
                          .detail = index,
                          .number = record->number},
    };
    return append_current_list_node(engine, &node, error, error_capacity);
}

static int execute_pdf_end_link(struct hstex_engine *engine, char *error,
                                size_t error_capacity)
{
    struct hstex_node node = {
        .kind = HSTEX_NODE_WHATSIT,
        .value.whatsit = {.kind = (uint8_t)HSTEX_WHATSIT_END_LINK},
    };
    return append_current_list_node(engine, &node, error, error_capacity);
}

/* Room for one more entry of the outline. */
static struct hstex_pdf_outline *add_pdf_outline(struct hstex_engine *engine,
                                                 char *error,
                                                 size_t error_capacity)
{
    if (engine->pdf_outline_count == engine->pdf_outline_capacity) {
        size_t capacity = engine->pdf_outline_capacity == 0U
                              ? 8U
                              : engine->pdf_outline_capacity * 2U;
        struct hstex_pdf_outline *grown =
            realloc(engine->pdf_outlines, capacity * sizeof(*grown));
        if (grown == NULL) {
            (void)set_error(error, error_capacity,
                            "PDF outline allocation failed");
            return NULL;
        }
        engine->pdf_outlines = grown;
        engine->pdf_outline_capacity = capacity;
    }
    struct hstex_pdf_outline *entry =
        &engine->pdf_outlines[engine->pdf_outline_count++];
    memset(entry, 0, sizeof(*entry));
    entry->parent = HSTEX_PDF_OUTLINE_NONE;
    entry->previous = HSTEX_PDF_OUTLINE_NONE;
    entry->next = HSTEX_PDF_OUTLINE_NONE;
    entry->first = HSTEX_PDF_OUTLINE_NONE;
    entry->last = HSTEX_PDF_OUTLINE_NONE;
    return entry;
}

static int execute_pdf_outline(struct hstex_engine *engine, char *error,
                               size_t error_capacity)
{
    char *attributes = NULL;
    if (scan_optional_pdf_text(engine, "attr", &attributes, error,
                               error_capacity) != 0) {
        return -1;
    }
    struct hstex_pdf_action action = {0};
    if (scan_pdf_action(engine, &action, error, error_capacity) != 0) {
        free(attributes);
        return -1;
    }
    bool counted = false;
    int32_t count = 0;
    if (try_keyword(engine, "count", &counted, error, error_capacity) != 0 ||
        (counted && scan_integer(engine, &count, error, error_capacity) != 0)) {
        free(attributes);
        return -1;
    }
    uint8_t *title = NULL;
    size_t title_count = 0U;
    if (scan_expanded_general_text(engine, &title, &title_count, error,
                                   error_capacity) != 0) {
        free(attributes);
        free(title);
        return -1;
    }
    /* The entry's own object is numbered here and written when the tree is
       finished, but what it does and what it shows are written as they are
       met: the action first, then the entry's number, then the title. See
       docs/DECISIONS.md, the-outline-of-a-document. */
    struct hstex_pdf_outline *entry =
        add_pdf_outline(engine, error, error_capacity);
    if (entry == NULL) {
        free(attributes);
        free(title);
        return -1;
    }
    entry->attributes = attributes;
    entry->count = count;
    entry->action = pdf_new_object(engine);
    int status =
        pdf_open(engine, error, error_capacity) != 0 ||
                pdf_begin_object(engine, entry->action, error,
                                 error_capacity) != 0 ||
                pdf_write_action(engine, &action, false, error,
                                 error_capacity) != 0 ||
                pdf_end_object(engine, error, error_capacity) != 0
            ? -1
            : 0;
    entry->object = pdf_new_object(engine);
    entry->title = pdf_new_object(engine);
    if (status == 0) {
        status = pdf_begin_object(engine, entry->title, error,
                                  error_capacity) != 0 ||
                         pdf_out_text(engine, "(", error, error_capacity) != 0 ||
                         pdf_out(engine, (const char *)title, title_count,
                                 error, error_capacity) != 0 ||
                         pdf_out_text(engine, ")\n", error, error_capacity) !=
                             0 ||
                         pdf_end_object(engine, error, error_capacity) != 0
                     ? -1
                     : 0;
    }
    free(title);
    return status;
}

static int execute_pdf_xform(struct hstex_engine *engine, char *error,
                             size_t error_capacity)
{
    char *attributes = NULL;
    char *resources = NULL;
    int32_t index = 0;
    if (scan_optional_pdf_text(engine, "attr", &attributes, error,
                               error_capacity) != 0) {
        return -1;
    }
    if (scan_optional_pdf_text(engine, "resources", &resources, error,
                               error_capacity) != 0) {
        free(attributes);
        return -1;
    }
    if (scan_integer(engine, &index, error, error_capacity) != 0 || index < 0 ||
        (size_t)index >= engine->count_capacity) {
        free(attributes);
        free(resources);
        return set_error(error, error_capacity,
                         "box register %d is outside 0..%zu", index,
                         engine->count_capacity - 1U);
    }
    struct hstex_pdf_record *record =
        add_pdf_record(engine, HSTEX_PDF_RECORD_FORM, error, error_capacity);
    if (record == NULL) {
        free(attributes);
        free(resources);
        return -1;
    }
    /* A form takes two object numbers: the form itself and its resources. */
    record->number = ++engine->pdf_object_counter;
    ++engine->pdf_object_counter;
    engine->pdf_last[HSTEX_PDF_LAST_FORM] = record->number;
    record->value = index;
    record->name = attributes;
    record->content = resources;
    return 0;
}

static int execute_pdf_annot(struct hstex_engine *engine, char *error,
                             size_t error_capacity)
{
    struct hstex_node rule = {.width = HSTEX_RUNNING_DIMEN,
                              .height = HSTEX_RUNNING_DIMEN,
                              .depth = HSTEX_RUNNING_DIMEN};
    if (scan_rule_dimensions(engine, &rule, error, error_capacity) != 0) {
        return -1;
    }
    bool use_number = false;
    int32_t number = 0;
    if (try_keyword(engine, "useobjnum", &use_number, error, error_capacity) !=
            0 ||
        (use_number &&
         scan_integer(engine, &number, error, error_capacity) != 0)) {
        return -1;
    }
    uint8_t *bytes = NULL;
    size_t count = 0U;
    if (scan_expanded_general_text(engine, &bytes, &count, error,
                                   error_capacity) != 0) {
        free(bytes);
        return -1;
    }
    struct hstex_pdf_record *record =
        add_pdf_record(engine, HSTEX_PDF_RECORD_ANNOTATION, error,
                       error_capacity);
    if (record == NULL) {
        free(bytes);
        return -1;
    }
    record->number = use_number ? number : ++engine->pdf_object_counter;
    engine->pdf_last[HSTEX_PDF_LAST_ANNOTATION] = record->number;
    record->content = own_general_text(bytes, count);
    free(bytes);
    if (record->content == NULL) {
        return set_error(error, error_capacity, "pdf annotation allocation failed");
    }
    /* The annotation stands in the list where it was written, so that the
       page can put it at that place. See docs/DECISIONS.md, pdf-links. */
    uint32_t tokens = 0U;
    if (store_text_as_token_list(engine, record->content, &tokens, error,
                                 error_capacity) != 0) {
        return -1;
    }
    struct hstex_node node = {
        .kind = HSTEX_NODE_WHATSIT,
        .width = rule.width,
        .height = rule.height,
        .depth = rule.depth,
        .value.whatsit = {.kind = (uint8_t)HSTEX_WHATSIT_ANNOT,
                          .stream = 1U,
                          .tokens = tokens,
                          .number = record->number},
    };
    return append_current_list_node(engine, &node, error, error_capacity);
}

static int reserve_color_stacks(struct hstex_engine *engine, size_t required,
                                char *error, size_t error_capacity);

/* Stack zero exists without being made: it starts in black, says so at the
   top of a page once something has been pushed on it, and writes what it
   says without leaving the text. See docs/DECISIONS.md, colour-on-a-page. */
static int ensure_built_in_color_stack(struct hstex_engine *engine,
                                       char *error, size_t error_capacity)
{
    if (engine->color_stack_count != 0U) {
        return 0;
    }
    if (reserve_color_stacks(engine, 1U, error, error_capacity) != 0) {
        return -1;
    }
    engine->color_stack_count = 1U;
    memset(&engine->color_stacks[0], 0, sizeof(engine->color_stacks[0]));
    engine->color_stacks[0].page = true;
    engine->color_stacks[0].direct = true;
    engine->color_stacks[0].initial =
        own_general_text((const uint8_t *)"0 g 0 G", 7U);
    return engine->color_stacks[0].initial == NULL
               ? set_error(error, error_capacity,
                           "colour stack allocation failed")
               : 0;
}

static int reserve_color_stacks(struct hstex_engine *engine, size_t required,
                                char *error, size_t error_capacity)
{
    if (required <= engine->color_stack_capacity) {
        return 0;
    }
    size_t capacity = engine->color_stack_capacity == 0U
                          ? 8U
                          : engine->color_stack_capacity * 2U;
    while (capacity < required) {
        capacity *= 2U;
    }
    struct hstex_color_stack *grown =
        realloc(engine->color_stacks, capacity * sizeof(*grown));
    if (grown == NULL) {
        return set_error(error, error_capacity,
                         "colour stack table allocation failed");
    }
    memset(grown + engine->color_stack_capacity, 0,
           (capacity - engine->color_stack_capacity) * sizeof(*grown));
    engine->color_stacks = grown;
    engine->color_stack_capacity = capacity;
    return 0;
}

/* \pdfcolorstackinit expands to the number of the stack it makes. Stack zero
   is the page's own, so the first one made is stack one. */
static int expand_pdf_color_stack_init(struct hstex_engine *engine,
                                       struct hstex_source_location location,
                                       char *error, size_t error_capacity)
{
    bool page = false;
    bool direct = false;
    if (try_keyword(engine, "page", &page, error, error_capacity) != 0 ||
        try_keyword(engine, "direct", &direct, error, error_capacity) != 0) {
        return -1;
    }
    uint8_t *bytes = NULL;
    size_t count = 0U;
    if (scan_expanded_general_text(engine, &bytes, &count, error,
                                   error_capacity) != 0) {
        free(bytes);
        return -1;
    }
    /* The built-in page stack occupies slot zero. */
    if (engine->color_stack_count == 0U &&
        ensure_built_in_color_stack(engine, error, error_capacity) != 0) {
        free(bytes);
        return -1;
    }
    if (reserve_color_stacks(engine, engine->color_stack_count + 1U, error,
                             error_capacity) != 0) {
        free(bytes);
        return -1;
    }
    struct hstex_color_stack *stack =
        &engine->color_stacks[engine->color_stack_count];
    memset(stack, 0, sizeof(*stack));
    stack->page = page;
    stack->direct = direct;
    stack->created = true;
    stack->initial = own_general_text(bytes, count);
    free(bytes);
    if (stack->initial == NULL) {
        return set_error(error, error_capacity,
                         "colour stack allocation failed");
    }
    int32_t number = (int32_t)engine->color_stack_count++;
    return push_integer_expansion(engine, number, location, error,
                                  error_capacity);
}

/* \pdfcolorstack <number> (push <text> | pop | set <text> | current) */
static int execute_pdf_color_stack(struct hstex_engine *engine, char *error,
                                   size_t error_capacity)
{
    int32_t number = 0;
    if (scan_integer(engine, &number, error, error_capacity) != 0) {
        return -1;
    }
    if (number < 0) {
        return set_error(error, error_capacity, "invalid colour stack %d",
                         number);
    }
    if ((size_t)number >= engine->color_stack_count) {
        if (number != 0 ||
            ensure_built_in_color_stack(engine, error, error_capacity) != 0) {
            return set_error(error, error_capacity,
                             "colour stack %d does not exist", number);
        }
    }
    struct hstex_color_stack *stack = &engine->color_stacks[(size_t)number];
    static const char *const actions[] = {"push", "pop", "set", "current"};
    size_t action = 0U;
    bool matched = false;
    for (; action < sizeof(actions) / sizeof(actions[0]); ++action) {
        if (try_keyword(engine, actions[action], &matched, error,
                        error_capacity) != 0) {
            return -1;
        }
        if (matched) {
            break;
        }
    }
    if (!matched) {
        return set_error(error, error_capacity,
                         "a colour stack action was expected here");
    }
    /* Whichever it is, the list gets a node saying so; see
       docs/DECISIONS.md, colour-stack-nodes. */
    if (action == 1U || action == 3U) {
        if (action == 1U && stack->count != 0U) { /* pop */
            free(stack->values[--stack->count]);
        }
        struct hstex_node node = {
            .kind = HSTEX_NODE_WHATSIT,
            .value.whatsit = {.kind = (uint8_t)HSTEX_WHATSIT_COLOR_STACK,
                              .stream = (uint8_t)number,
                              .action = (uint8_t)action},
        };
        return append_current_list_node(engine, &node, error, error_capacity);
    }
    uint8_t *bytes = NULL;
    size_t count = 0U;
    if (scan_expanded_general_text(engine, &bytes, &count, error,
                                   error_capacity) != 0) {
        free(bytes);
        return -1;
    }
    /* The text is expanded where it stands and kept as it was read, the way
       a \special's is. */
    struct hstex_token_vector tokens = {0};
    for (size_t index = 0U; index < count; ++index) {
        uint8_t category = bytes[index] == (uint8_t)' '
                               ? (uint8_t)HSTEX_CAT_SPACE
                               : (uint8_t)HSTEX_CAT_OTHER;
        if (vector_push(&tokens,
                        hstex_token_character(category, bytes[index]), error,
                        error_capacity) != 0) {
            vector_destroy(&tokens);
            free(bytes);
            return -1;
        }
    }
    uint32_t stored = 0U;
    if (store_token_list(engine, &tokens, &stored, error, error_capacity) !=
        0) {
        vector_destroy(&tokens);
        free(bytes);
        return -1;
    }
    struct hstex_node node = {
        .kind = HSTEX_NODE_WHATSIT,
        .value.whatsit = {.kind = (uint8_t)HSTEX_WHATSIT_COLOR_STACK,
                          .stream = (uint8_t)number,
                          .action = (uint8_t)action,
                          .tokens = stored},
    };
    char *value = own_general_text(bytes, count);
    free(bytes);
    if (value == NULL) {
        return set_error(error, error_capacity,
                         "colour stack allocation failed");
    }
    if (action == 2U && stack->count != 0U) {
        /* set: replaces the top rather than growing */
        free(stack->values[stack->count - 1U]);
        stack->values[stack->count - 1U] = value;
        return append_current_list_node(engine, &node, error, error_capacity);
    }
    if (stack->count == stack->capacity) {
        size_t capacity = stack->capacity == 0U ? 8U : stack->capacity * 2U;
        char **grown = realloc(stack->values, capacity * sizeof(*grown));
        if (grown == NULL) {
            free(value);
            return set_error(error, error_capacity,
                             "colour stack allocation failed");
        }
        stack->values = grown;
        stack->capacity = capacity;
    }
    stack->values[stack->count++] = value;
    return append_current_list_node(engine, &node, error, error_capacity);
}

/* Unboxing appends a box's own list to the one being built and discards the
   box itself; the copying forms leave the register alone. No interline glue
   is inserted, since the list already carries its own; see
   docs/DECISIONS.md, unboxing. */
static int execute_unbox(struct hstex_engine *engine, int32_t subtype,
                         char *error, size_t error_capacity)
{
    if (engine->pending_global || engine->pending_macro_flags != 0U) {
        return set_error(error, error_capacity,
                         "unboxing does not accept prefixes");
    }
    bool vertical = subtype == (int32_t)HSTEX_UNBOX_VERTICAL ||
                    subtype == (int32_t)HSTEX_UNBOX_VERTICAL_COPY;
    bool keep = subtype == (int32_t)HSTEX_UNBOX_HORIZONTAL_COPY ||
                subtype == (int32_t)HSTEX_UNBOX_VERTICAL_COPY;
    /* \unhbox is allowed in a formula, where LaTeX's \leavevmode reaches it
       as \unhbox\voidb@x; only a void register may be unboxed there. See
       docs/DECISIONS.md, unboxing-in-a-formula. */
    bool formula = !vertical && engine->mode == HSTEX_MODE_MATH;
    if (!vertical && !formula &&
        ensure_horizontal_mode(engine, error, error_capacity) != 0) {
        return -1;
    }
    if (!formula && (vertical ? engine->mode != HSTEX_MODE_VERTICAL
                              : engine->mode != HSTEX_MODE_HORIZONTAL)) {
        return set_error(error, error_capacity,
                         vertical ? "unvbox requires vertical mode"
                                  : "unhbox requires horizontal mode");
    }
    int32_t index = 0;
    if (scan_integer(engine, &index, error, error_capacity) != 0) {
        return -1;
    }
    if (index < 0 || (size_t)index >= engine->count_capacity) {
        return set_error(error, error_capacity,
                         "box register %d is outside 0..%zu", index,
                         engine->count_capacity - 1U);
    }
    struct hstex_box box = engine->boxes[(size_t)index];
    if (box.kind == HSTEX_BOX_VOID) {
        return 0;
    }
    static const char *const mismatch_help[] = {
        "Sorry, Pandora. (You sneaky devil.)",
        "I refuse to unbox an \\hbox in vertical mode or vice versa.",
        "And I can't open any boxes in math mode.", NULL};
    if (formula) {
        /* Named and ignored; the box keeps its contents. */
        tex_error(engine, mismatch_help, "Incompatible list can't be unboxed");
        return 0;
    }
    enum hstex_box_kind wanted =
        vertical ? HSTEX_BOX_VLIST : HSTEX_BOX_HLIST;
    if (box.kind != wanted) {
        tex_error(engine, mismatch_help, "Incompatible list can't be unboxed");
        return 0;
    }
    /* Unboxing puts a list where it stands and says nothing about what
       should be set against what: the reference leaves \\prevdepth where it
       found it, however deep the last box inside was. Plain TeX's \\+ turns
       on this -- it unboxes its row and takes it back with \\lastbox, and the
       glue in front of it is measured from the line before the table. See
       docs/DECISIONS.md, unboxing-says-nothing-about-depth. */
    int32_t depth_before_unboxing = engine->prev_depth;
    for (uint32_t offset = 0U; offset < box.node_count; ++offset) {
        size_t slot = (size_t)box.node_start + offset;
        if (slot >= engine->list_item_count) {
            engine->prev_depth = depth_before_unboxing;
            return set_error(error, error_capacity,
                             "box %d refers outside the list arena", index);
        }
        uint32_t identifier = engine->list_items[slot];
        int status = vertical
                         ? append_vbox_item(engine, identifier, error,
                                            error_capacity)
                         : append_hbox_item(engine, identifier, error,
                                            error_capacity);
        if (status != 0) {
            engine->prev_depth = depth_before_unboxing;
            return -1;
        }
    }
    engine->prev_depth = depth_before_unboxing;
    if (keep) {
        return 0;
    }
    empty_box_register(engine, (uint32_t)index);
    return 0;
}

/* \indent puts an empty box of width \parindent in the horizontal list;
   \noindent puts nothing. From vertical mode either starts a paragraph, which
   needs the paragraph builder; see docs/DECISIONS.md, indentation. */
static int execute_indent(struct hstex_engine *engine, bool indent,
                          char *error, size_t error_capacity)
{
    if (engine->pending_global || engine->pending_macro_flags != 0U) {
        return set_error(error, error_capacity,
                         "indentation does not accept prefixes");
    }
    if (engine->mode == HSTEX_MODE_VERTICAL) {
        return start_paragraph(engine, indent, error, error_capacity);
    }
    /* A formula takes them too: measured, \indent puts the same empty box
       in the math list and \noindent puts nothing, neither drawing a
       word. */
    if (!indent) {
        return 0;
    }
    struct hstex_box box = {0};
    box.kind = HSTEX_BOX_HLIST;
    box.width = engine->dimen_parameters[HSTEX_DIMEN_PAR_INDENT];
    return append_box_node(engine, &box, error, error_capacity);
}

/* Walk a font's ligature and kerning program for a pair of characters, and
   say what it has to say about them: nothing, a kern, or one of the eight
   ligature operations. See docs/DECISIONS.md, ligature-operations. */
static int font_lig_kern_from(const struct hstex_font *font, uint8_t left,
                              uint8_t right, bool from_boundary,
                              struct hstex_lig_kern_result *result,
                              char *error, size_t error_capacity)
{
    result->kind = HSTEX_LIG_KERN_NOTHING;
    result->kern = 0;
    result->ligature = 0U;
    result->keep_left = false;
    result->keep_right = false;
    result->advance = 0U;
    if (font->characters == NULL || font->lig_kern_count == 0U) {
        return 0;
    }
    size_t step = 0U;
    if (from_boundary) {
        /* The program for what stands beyond the left end of a word, which
           the table's last instruction points at. */
        if (font->boundary_label < 0) {
            return 0;
        }
        step = (size_t)font->boundary_label;
    } else {
        const struct hstex_char_metric *metric = &font->characters[left];
        if (metric->tag != 1) {
            return 0;
        }
        step = (size_t)metric->remainder;
    }
    if (step >= font->lig_kern_count) {
        return 0;
    }
    /* A first step that skips more than the table is a long jump to the real
       start of the program. */
    if (font->lig_kern[step].skip > 128U) {
        step = (size_t)font->lig_kern[step].operation * 256U +
               (size_t)font->lig_kern[step].remainder;
        if (step >= font->lig_kern_count) {
            return 0;
        }
    }
    for (;;) {
        const struct hstex_lig_kern *entry = &font->lig_kern[step];
        if (entry->skip <= 128U && entry->next == right) {
            if (entry->operation >= 128U) {
                size_t index = (size_t)(entry->operation - 128U) * 256U +
                               (size_t)entry->remainder;
                if (index >= font->kern_count) {
                    return set_error(error, error_capacity,
                                     "font kern index is out of range");
                }
                result->kind = HSTEX_LIG_KERN_KERN;
                result->kern = font->kerns[index];
                return 0;
            }
            /* 4*advance + 2*keep_left + keep_right. Only 0, 1, 2, 3, 5, 6, 7
               and 11 are written by a font tool; anything else is taken as
               the plain `=:', which is what the reference does with it. */
            uint8_t operation = entry->operation;
            if (operation > 11U || operation == 4U || operation == 8U ||
                operation == 9U || operation == 10U) {
                operation = 0U;
            }
            result->kind = HSTEX_LIG_KERN_LIGATURE;
            result->ligature = entry->remainder;
            result->keep_right = (operation & 1U) != 0U;
            result->keep_left = (operation & 2U) != 0U;
            result->advance = (uint8_t)(operation >> 2);
            return 0;
        }
        if (entry->skip >= 128U) {
            return 0;
        }
        step += (size_t)entry->skip + 1U;
        if (step >= font->lig_kern_count) {
            return 0;
        }
    }
}

/* A character sets the space factor from its \sfcode, which the next space
   then uses. */
static void advance_space_factor(struct hstex_engine *engine, uint8_t code)
{
    int32_t factor = engine->code_tables[0][code];
    if (factor == 1000) {
        engine->space_factor = 1000;
    } else if (factor == 0) {
        return;
    } else if (factor < 1000) {
        engine->space_factor = factor;
    } else {
        engine->space_factor =
            engine->space_factor < 1000 ? 1000 : factor;
    }
}

/* Interword glue: the font's own, with the stretch scaled by the space factor
   and the shrink scaled against it. */
static int append_interword_glue(struct hstex_engine *engine, char *error,
                                 size_t error_capacity)
{
    const struct hstex_font *font =
        font_by_identifier(engine, engine->current_font);
    if (font == NULL || font->dimen_count < 4U) {
        return set_error(error, error_capacity,
                         "current font does not define interword spacing");
    }
    /* A space is \xspaceskip where the space factor has reached two
       thousand and that glue is not zero, otherwise \spaceskip, otherwise
       what the font says. Only a space of the ordinary width keeps the name
       of the parameter it came from; anything the space factor has touched
       is a spec of its own. See docs/DECISIONS.md, interword-glue. */
    int32_t factor = engine->space_factor;
    struct hstex_glue extra = engine->glue_parameters[HSTEX_GLUE_XSPACE_SKIP];
    uint8_t parameter = 0U;
    struct hstex_glue glue = {0};
    if (factor >= 2000 &&
        !(extra.width == 0 && extra.stretch == 0 && extra.shrink == 0)) {
        glue = extra;
        parameter = 1U + (uint8_t)HSTEX_GLUE_XSPACE_SKIP;
    } else {
        struct hstex_glue named =
            engine->glue_parameters[HSTEX_GLUE_SPACE_SKIP];
        bool from_font =
            named.width == 0 && named.stretch == 0 && named.shrink == 0;
        if (from_font) {
            glue.width = font->dimens[1];
            glue.stretch = font->dimens[2];
            glue.shrink = font->dimens[3];
        } else {
            glue = named;
        }
        if (factor == 1000) {
            parameter =
                from_font ? 0U : 1U + (uint8_t)HSTEX_GLUE_SPACE_SKIP;
        } else {
            if (factor >= 2000 && font->dimen_count >= 7U) {
                glue.width += font->dimens[6];
            }
            if (factor > 0) {
                glue.stretch =
                    (int32_t)(((int64_t)glue.stretch * factor) / 1000);
                glue.shrink =
                    (int32_t)(((int64_t)glue.shrink * 1000) / factor);
            }
        }
    }
    struct hstex_node node = {
        .kind = HSTEX_NODE_GLUE,
        .width = glue.width,
        .value.glue = {
            .stretch = glue.stretch,
            .shrink = glue.shrink,
            .stretch_order = glue.stretch_order,
            .shrink_order = glue.shrink_order,
            .parameter = parameter,
        },
    };
    return append_hbox_node(engine, &node, error, error_capacity);
}

/* Put a character, or a ligature standing for several, into the list. */
static int append_character_node(struct hstex_engine *engine, uint8_t code,
                                 bool ligature, const uint8_t *originals,
                                 uint8_t original_count, uint8_t boundary,
                                 char *error, size_t error_capacity)
{
    const struct hstex_font *font =
        font_by_identifier(engine, engine->current_font);
    if (font == NULL || font->characters == NULL ||
        font->characters[code].tag < 0) {
        /* A character the font does not define contributes nothing at all,
           though it has already moved the space factor; see
           docs/DECISIONS.md, missing-characters. */
        return 0;
    }
    const struct hstex_char_metric *metric = &font->characters[code];
    struct hstex_node node = {
        .kind = ligature ? HSTEX_NODE_LIGATURE : HSTEX_NODE_CHARACTER,
        .width = metric->width,
        .height = metric->height,
        .depth = metric->depth,
        .value.character = {
            .font = engine->current_font,
            .character = code,
        },
    };
    if (ligature) {
        uint8_t room = (uint8_t)sizeof(node.value.character.originals);
        node.value.character.original_count =
            original_count < room ? original_count : room;
        memcpy(node.value.character.originals, originals,
               node.value.character.original_count);
        node.value.character.boundary = boundary;
    }
    return append_hbox_node(engine, &node, error, error_capacity);
}

/* Whether a token will put a character in the list: a letter or other
   character, or a control sequence that stands for one. */
static bool character_follows(struct hstex_engine *engine, hstex_token token)
{
    if (hstex_token_is_character(token)) {
        return token_is_category(token, HSTEX_CAT_LETTER) ||
               token_is_category(token, HSTEX_CAT_OTHER);
    }
    if (!hstex_token_is_control_sequence(token)) {
        return false;
    }
    const struct hstex_meaning *meaning =
        hstex_engine_meaning(engine, hstex_token_control_sequence_id(token));
    if (meaning->command == HSTEX_COMMAND_CHAR_GIVEN ||
        meaning->command == HSTEX_COMMAND_CHAR) {
        return true;
    }
    return meaning->command == HSTEX_COMMAND_TOKEN_ALIAS &&
           hstex_token_is_character(meaning->value.token);
}

/* A character the font does not define is dropped before anything else sees
   it -- it joins no list and no ligature -- and the reference says so where
   \tracinglostchars asks. It has moved the space factor first. See
   docs/DECISIONS.md, missing-characters. */
static void char_warning(struct hstex_engine *engine,
                         const struct hstex_font *font, uint8_t code)
{
    if (engine->integer_parameters[HSTEX_INTEGER_TRACING_LOST_CHARS] <= 0) {
        return;
    }
    bool saved_selector = begin_diagnostic(engine);
    print_fresh_line(engine);
    print_text(engine, "Missing character: There is no ");
    if (character_needs_caret(code)) {
        print_formatted(engine, "^^%c",
                        (char)(code < 64U ? code + 64U : code - 64U));
    } else {
        print_byte(engine, (char)code);
    }
    print_formatted(engine, " in font %s!", font->name);
    end_diagnostic(engine, saved_selector, false);
    (void)fflush(diagnostic_stream(engine));
}

/* Let out the missing characters a hyphenation kept back, as far as the
   place the trace has reached. Called with SIZE_MAX where the paragraph is
   done and whatever is left must come out wherever it is. */
static void release_lost_characters(struct hstex_engine *engine, size_t reached)
{
    size_t kept = 0U;
    for (size_t index = 0U; index < engine->lost_character_count; ++index) {
        struct hstex_lost_character *lost = &engine->lost_characters[index];
        if (lost->at >= reached) {
            engine->lost_characters[kept++] = *lost;
            continue;
        }
        const struct hstex_font *font = font_by_identifier(engine, lost->font);
        if (font != NULL) {
            char_warning(engine, font, lost->code);
        }
    }
    engine->lost_character_count = kept;
}

/* One character on its way into a horizontal list, with what it was made of
   if the ligature program made it. */
struct hstex_lig_item {
    uint8_t character;
    bool is_ligature;
    bool is_hyphen;
    /* The boundary character standing beyond one end of the word. It is not
       a character of the list: it takes part in the program and then goes
       away, leaving its mark on whatever it helped make. */
    bool is_boundary;
    /* Which ends of it the boundary took part in, where the item was made
       from a node that already stood in the list. */
    uint8_t boundary;
    uint8_t originals[10];
    uint8_t original_count;
};

static void lig_item_plain(struct hstex_lig_item *item, uint8_t code,
                           bool hyphen)
{
    memset(item, 0, sizeof(*item));
    item->character = code;
    item->is_hyphen = hyphen;
}

/* What a character is made of: itself, unless it is already a ligature, in
   which case what that was made of. This is what a ligature built from it
   inherits. */
static void lig_item_append_originals(struct hstex_lig_item *target,
                                      const struct hstex_lig_item *source)
{
    uint8_t room = (uint8_t)sizeof(target->originals);
    if (!source->is_ligature) {
        if (target->original_count < room) {
            target->originals[target->original_count++] = source->character;
        }
        return;
    }
    for (uint8_t index = 0U; index < source->original_count; ++index) {
        if (target->original_count < room) {
            target->originals[target->original_count++] =
                source->originals[index];
        }
    }
}

/* True where nothing of the word stands after this item but the boundary,
   which is where the reference finds its lookahead empty and puts the right
   mark on the ligature it is making. */
static bool lig_nothing_after(const struct hstex_lig_item *work, size_t count,
                              size_t index)
{
    for (size_t next = index + 1U; next < count; ++next) {
        if (!work[next].is_boundary) {
            return false;
        }
    }
    return true;
}

/* Where a character the program has finished with goes. The two callers put
   it in different places -- a horizontal list, or an array of nodes a word
   is being set again into -- so the walk hands each one out as it is made
   rather than collecting them. */
typedef int (*hstex_lig_emit)(void *context, const struct hstex_lig_item *item,
                              bool is_kern, int32_t kern, char *error,
                              size_t error_capacity);

/* A program that neither finishes a character nor shortens the work list is
   contradicting itself; the reference walks such a font for ever. The trip
   font, which is built to stress this, reaches eight characters and 126
   turns. */
#define HSTEX_LIG_TURNS 4096U

/* A pair the program has spoken about becomes at most three characters --
   the left one if it is kept, the character the operation names, the right
   one if it is kept -- and the walk then starts again at the first of them
   that is not finished with. Each turn either finishes a character or
   changes one, so the work list is short; the bound is there for a font
   whose program contradicts itself. */
#define HSTEX_LIG_WORK 64U

static int lig_advance(struct hstex_engine *engine,
                       const struct hstex_font *font,
                       struct hstex_lig_item *work, size_t *count,
                       hstex_lig_emit emit, void *context, char *error,
                       size_t error_capacity);
static int lig_emit_horizontal(void *context,
                               const struct hstex_lig_item *item, bool is_kern,
                               int32_t kern, char *error,
                               size_t error_capacity);

static int emit_lig_item(struct hstex_engine *engine,
                         const struct hstex_lig_item *item, char *error,
                         size_t error_capacity)
{
    if (item->is_boundary) {
        return 0;
    }
    uint8_t boundary = 0U;
    if (item->is_ligature) {
        /* The left mark goes on the first ligature the word makes; the right
           one on the ligature after which nothing of the word is left, which
           is where the reference finds its lig_stack empty. */
        if (engine->lig_left_hit) {
            boundary |= 2U;
            engine->lig_left_hit = false;
        }
        if (engine->lig_right_hit && engine->lig_last_of_word) {
            boundary |= 1U;
            engine->lig_right_hit = false;
        }
    }
    int status = append_character_node(engine, item->character,
                                       item->is_ligature, item->originals,
                                       item->original_count, boundary, error,
                                       error_capacity);
    /* An explicit hyphen is followed into the paragraph by an empty
       discretionary, so the line may break after it; see docs/DECISIONS.md,
       the-discretionary-after-an-explicit-hyphen. */
    if (status == 0 && item->is_hyphen) {
        struct hstex_node node = {.kind = HSTEX_NODE_DISCRETIONARY};
        status = append_hbox_node(engine, &node, error, error_capacity);
    }
    return status;
}

/* Put the held-back character into the list. Everything that is not another
   character does this first, so a command between two characters breaks the
   pair exactly as it does in the reference. */
static int flush_pending_character(struct hstex_engine *engine, char *error,
                                   size_t error_capacity)
{
    if (!engine->has_pending_character) {
        return 0;
    }
    struct hstex_lig_item work[HSTEX_LIG_WORK];
    lig_item_plain(&work[0], engine->pending_character,
                   engine->pending_is_hyphen);
    work[0].is_ligature = engine->pending_is_ligature;
    work[0].original_count = engine->pending_original_count;
    memcpy(work[0].originals, engine->pending_originals,
           sizeof(work[0].originals));
    engine->has_pending_character = false;
    engine->pending_is_hyphen = false;
    /* The word ends, so the character beyond its right end takes part in the
       program one last time -- unless \noboundary said not to. See
       docs/DECISIONS.md, boundary-characters. */
    const struct hstex_font *font =
        font_by_identifier(engine, engine->current_font);
    bool cancelled = engine->cancel_boundary;
    if (font != NULL && !cancelled && font->boundary_character >= 0 &&
        font->boundary_character <= 255) {
        size_t count = 1U;
        lig_item_plain(&work[count], (uint8_t)font->boundary_character, false);
        work[count].is_boundary = true;
        ++count;
        if (lig_advance(engine, font, work, &count, lig_emit_horizontal,
                        engine, error, error_capacity) != 0) {
            return -1;
        }
        for (size_t index = 0U; index < count; ++index) {
            engine->lig_last_of_word = lig_nothing_after(work, count, index);
            if (emit_lig_item(engine, &work[index], error, error_capacity) !=
                0) {
                engine->lig_last_of_word = false;
                return -1;
            }
        }
        engine->lig_last_of_word = false;
        engine->cancel_boundary = false;
        return 0;
    }
    engine->cancel_boundary = false;
    engine->lig_last_of_word = true;
    int status = emit_lig_item(engine, &work[0], error, error_capacity);
    engine->lig_last_of_word = false;
    return status;
}


static int font_lig_kern(const struct hstex_font *font, uint8_t left,
                         uint8_t right,
                         struct hstex_lig_kern_result *result, char *error,
                         size_t error_capacity)
{
    return font_lig_kern_from(font, left, right, false, result, error,
                              error_capacity);
}

/* Run the font's program over the work list until only one character is
   left to be looked at beside whatever comes next, and leave everything it
   has finished with in `out`. See docs/DECISIONS.md, ligature-operations. */
static int lig_advance(struct hstex_engine *engine,
                       const struct hstex_font *font,
                       struct hstex_lig_item *work, size_t *count,
                       hstex_lig_emit emit, void *context, char *error,
                       size_t error_capacity)
{
    for (size_t turn = 0U; *count >= 2U; ++turn) {
        if (turn == HSTEX_LIG_TURNS) {
            return set_error(error, error_capacity,
                             "the font's ligature program does not settle");
        }
        struct hstex_lig_kern_result step;
        if (font_lig_kern_from(font, work[0].character, work[1].character,
                               work[0].is_boundary, &step, error,
                               error_capacity) != 0) {
            return -1;
        }
        if (step.kind != HSTEX_LIG_KERN_LIGATURE) {
            /* The boundary is not a character of the list, so nothing of it
               is put there. */
            engine->lig_last_of_word = lig_nothing_after(work, *count, 0U);
            bool failed = !work[0].is_boundary &&
                          emit(context, &work[0], false, 0, error,
                               error_capacity) != 0;
            engine->lig_last_of_word = false;
            if (failed) {
                return -1;
            }
            if (step.kind == HSTEX_LIG_KERN_KERN && step.kern != 0 &&
                emit(context, NULL, true, step.kern, error,
                     error_capacity) != 0) {
                return -1;
            }
            memmove(&work[0], &work[1], (*count - 1U) * sizeof(work[0]));
            --*count;
            continue;
        }
        /* The character the operation names is a ligature made of whichever
           of the pair it replaces: the left one where the left is not kept,
           the right one where the right is not kept, and nothing at all
           where both are kept and it is only inserted between them. */
        struct hstex_lig_item made;
        lig_item_plain(&made, step.ligature, false);
        made.is_ligature = true;
        /* Whichever end the boundary stood at leaves its mark on the word,
           whether or not the boundary itself is kept; the first ligature the
           word puts in the list wears it. */
        if (work[0].is_boundary) {
            engine->lig_left_hit = true;
        }
        if (work[1].is_boundary) {
            engine->lig_right_hit = true;
        }
        /* WHICH HYPHEN EARNS THE DISCRETIONARY is the LAST character taken
           into the run, not any of them: the reference asks what the last
           character it put down was. `--' in cmr10 makes a ligature that
           draws one, because the second of the two is a hyphen; trip's
           `-^^@' makes one that draws none. See docs/DECISIONS.md,
           the-discretionary-after-an-explicit-hyphen. */
        made.is_hyphen =
            step.keep_right ? work[0].is_hyphen : work[1].is_hyphen;
        if (!step.keep_left && !work[0].is_boundary) {
            lig_item_append_originals(&made, &work[0]);
        }
        if (!step.keep_right && !work[1].is_boundary) {
            lig_item_append_originals(&made, &work[1]);
        }
        struct hstex_lig_item built[3];
        size_t built_count = 0U;
        if (step.keep_left) {
            built[built_count++] = work[0];
        }
        built[built_count++] = made;
        if (step.keep_right) {
            built[built_count++] = work[1];
        }
        size_t remaining = *count - 2U;
        if (built_count + remaining > HSTEX_LIG_WORK) {
            return set_error(error, error_capacity,
                             "the font's ligature program does not settle");
        }
        memmove(&work[built_count], &work[2], remaining * sizeof(work[0]));
        memcpy(work, built, built_count * sizeof(work[0]));
        *count = built_count + remaining;
        /* What the operation is finished with goes out now; the walk starts
           again at the first character it is not finished with. */
        size_t done = step.advance < *count ? step.advance : *count;
        for (size_t index = 0U; index < done; ++index) {
            engine->lig_last_of_word = lig_nothing_after(work, *count, index);
            bool failed = !work[index].is_boundary &&
                          emit(context, &work[index], false, 0, error,
                               error_capacity) != 0;
            engine->lig_last_of_word = false;
            if (failed) {
                return -1;
            }
        }
        if (done != 0U) {
            memmove(&work[0], &work[done], (*count - done) * sizeof(work[0]));
            *count -= done;
        }
    }
    return 0;
}

/* Into a horizontal list. */
static int lig_emit_horizontal(void *context,
                               const struct hstex_lig_item *item, bool is_kern,
                               int32_t kern, char *error,
                               size_t error_capacity)
{
    struct hstex_engine *engine = context;
    if (is_kern) {
        struct hstex_node node = {.kind = HSTEX_NODE_KERN, .width = kern};
        return append_hbox_node(engine, &node, error, error_capacity);
    }
    return emit_lig_item(engine, item, error, error_capacity);
}

/* A paragraph remembers which language it is setting. Where \\language has
   moved on since, a whatsit says so before the next character joins the
   list, exactly as \\setlanguage would. Only an unrestricted horizontal
   list does this. See docs/DECISIONS.md, setlanguage. */
static int fix_language(struct hstex_engine *engine, char *error,
                        size_t error_capacity)
{
    if (engine->mode != HSTEX_MODE_HORIZONTAL || engine->inner_mode ||
        engine->nest_count == 0U) {
        return 0;
    }
    struct hstex_nest_level *level = &engine->nest[engine->nest_count - 1U];
    int32_t language = engine->integer_parameters[HSTEX_INTEGER_LANGUAGE];
    if (language < 0 || language > 255) {
        language = 0;
    }
    if (language == level->current_language) {
        return 0;
    }
    level->current_language = language;
    struct hstex_node node = {
        .kind = HSTEX_NODE_WHATSIT,
        .value.whatsit = {
            .kind = (uint8_t)HSTEX_WHATSIT_LANGUAGE,
            .stream = normalised_hyphen_min(
                engine->integer_parameters[HSTEX_INTEGER_LEFT_HYPHEN_MIN]),
            .action = normalised_hyphen_min(
                engine->integer_parameters[HSTEX_INTEGER_RIGHT_HYPHEN_MIN]),
            .number = language,
        },
    };
    return append_hbox_node(engine, &node, error, error_capacity);
}

/* Take one character into the horizontal list, consulting the font's
   ligature and kerning program against the character held back before it.
   See docs/DECISIONS.md, ligature-operations. */
static int append_horizontal_character(struct hstex_engine *engine,
                                       uint8_t code, char *error,
                                       size_t error_capacity)
{
    const struct hstex_font *font =
        font_by_identifier(engine, engine->current_font);
    /* Only a paragraph gets the discretionary; a character in a box is just
       a character. See docs/DECISIONS.md,
       the-discretionary-after-an-explicit-hyphen. */
    bool hyphen = !engine->inner_mode && font != NULL &&
                  font->hyphen_character == (int32_t)code;
    /* The space factor follows the characters as they are read, so a
       ligature leaves behind whatever the last of its parts said; see
       docs/DECISIONS.md, the-space-factor-of-a-ligature. */
    advance_space_factor(engine, code);
    if (fix_language(engine, error, error_capacity) != 0) {
        return -1;
    }
    if (font != NULL &&
        (font->characters == NULL || font->characters[code].tag < 0)) {
        /* The word ends here, and without the character beyond its right
           end: the reference had already looked ahead and found this one, so
           the boundary never came into it. That is what keeps `uZ' from
           ligaturing through a Z that is not there. */
        engine->cancel_boundary = true;
        if (flush_pending_character(engine, error, error_capacity) != 0) {
            return -1;
        }
        engine->cancel_boundary = false;
        char_warning(engine, font, code);
        /* A character the font does not have joins no list, so it does not
           carry a run of characters on either: \tracingcommands draws a line
           for the NEXT one as well. Measured, with \nullfont in force,
           `hello' draws five lines where in a real font it draws one. */
        engine->traced_character = false;
        return 0;
    }
    /* PDF font resources are numbered when the character is taken in, not
       when ligature processing eventually emits its node.  Tagged-PDF
       whatsits can allocate several objects between those two events. */
    if (font != NULL &&
        pdf_reserve_shared_cmap(engine, engine->current_font, error,
                                error_capacity) != 0) {
        return -1;
    }
    struct hstex_lig_item work[HSTEX_LIG_WORK];
    size_t count = 0U;
    if (!engine->has_pending_character || font == NULL) {
        if (font == NULL &&
            flush_pending_character(engine, error, error_capacity) != 0) {
            return -1;
        }
        bool cancelled = engine->cancel_boundary;
        engine->cancel_boundary = false;
        engine->lig_left_hit = false;
        engine->lig_right_hit = false;
        /* A word begins, so what stands beyond its left end takes part in
           the program before the first character does. */
        if (font == NULL || cancelled || font->boundary_label < 0) {
            engine->has_pending_character = true;
            engine->pending_is_ligature = false;
            engine->pending_original_count = 0U;
            engine->pending_character = code;
            engine->pending_is_hyphen = hyphen;
            return 0;
        }
        lig_item_plain(&work[count], 0U, false);
        work[count].is_boundary = true;
        ++count;
        lig_item_plain(&work[count++], code, hyphen);
    } else {
        engine->cancel_boundary = false;
        work[count].character = engine->pending_character;
        work[count].is_ligature = engine->pending_is_ligature;
        work[count].is_hyphen = engine->pending_is_hyphen;
        work[count].is_boundary = false;
        work[count].original_count = engine->pending_original_count;
        memcpy(work[count].originals, engine->pending_originals,
               sizeof(work[count].originals));
        ++count;
        lig_item_plain(&work[count++], code, hyphen);
        engine->has_pending_character = false;
        engine->pending_is_hyphen = false;
    }

    if (lig_advance(engine, font, work, &count, lig_emit_horizontal, engine,
                    error, error_capacity) != 0) {
        return -1;
    }
    if (count == 1U && !work[0].is_boundary) {
        engine->has_pending_character = true;
        engine->pending_character = work[0].character;
        engine->pending_is_ligature = work[0].is_ligature;
        engine->pending_is_hyphen = work[0].is_hyphen;
        engine->pending_original_count = work[0].original_count;
        memcpy(engine->pending_originals, work[0].originals,
               sizeof(engine->pending_originals));
    }
    return 0;
}

/* Begin a paragraph: the vertical list gets \parskip if it has anything in
   it, and always in the outermost one, and the horizontal list gets the
   indentation and \everypar; see docs/DECISIONS.md, paragraphs. */
static int start_paragraph(struct hstex_engine *engine, bool indent,
                           char *error, size_t error_capacity)
{
    /* A paragraph of its own starts counting lines again; one resumed after
       a display does not. See docs/DECISIONS.md,
       lines-carry-on-past-a-display. */
    engine->prev_graf = 0;
    if (engine->paragraph_builder == NULL) {
        engine->paragraph_builder =
            calloc(1U, sizeof(*engine->paragraph_builder));
        if (engine->paragraph_builder == NULL) {
            return set_error(error, error_capacity,
                             "paragraph list allocation failed");
        }
    }
    /* The outermost vertical list gets \parskip whether or not anything is
       waiting to be contributed, because what came before may already have
       been moved to the page; an inner one gets it only when it is not
       empty. See docs/DECISIONS.md, parskip-in-the-outermost-list. */
    if (engine->active_vbox_builder != NULL &&
        (engine->active_vbox_builder == engine->contribution_builder ||
         engine->active_vbox_builder->count != 0U ||
         engine->active_vbox_builder->continues)) {
        struct hstex_glue skip = engine->glue_parameters[HSTEX_GLUE_PAR_SKIP];
        struct hstex_node node = {
            .kind = HSTEX_NODE_GLUE,
            .width = skip.width,
            .value.glue = {
                .stretch = skip.stretch,
                .shrink = skip.shrink,
                .stretch_order = skip.stretch_order,
                .shrink_order = skip.shrink_order,
                .parameter = 1U + (uint8_t)HSTEX_GLUE_PAR_SKIP,
            },
        };
        if (append_vbox_node(engine, &node, error, error_capacity) != 0) {
            return -1;
        }
        /* Glue on the outermost list is somewhere the page may break, and
           the reference looks at it the moment it is there: a page already
           full is shipped out here, before a word of the paragraph that
           follows has been read. What the output routine can see -- the
           current font, \\inputlineno -- depends on its being entered here
           rather than a paragraph later. See docs/DECISIONS.md,
           when-the-page-builder-fires. */
        if (contribute_page(engine, error, error_capacity) != 0) {
            return -1;
        }
    }
    engine->paragraph_builder->count = 0U;
    engine->paragraph_builder->width = 0;
    engine->paragraph_builder->height = 0;
    engine->paragraph_builder->depth = 0;
    /* A paragraph is a list of its own, above the vertical one it will
       join, so it is a level of the nest of its own. A paragraph resumed
       after a display already has one and does not take another. */
    if (nest_push(engine, error, error_capacity) != 0) {
        return -1;
    }
    engine->active_hbox_builder = engine->paragraph_builder;
    engine->mode = HSTEX_MODE_HORIZONTAL;
    engine->inner_mode = false;
    engine->building_paragraph = true;
    engine->space_factor = 1000;
    engine->has_pending_character = false;
    if (indent) {
        struct hstex_box box = {0};
        box.kind = HSTEX_BOX_HLIST;
        box.width = engine->dimen_parameters[HSTEX_DIMEN_PAR_INDENT];
        if (append_box_node(engine, &box, error, error_capacity) != 0) {
            return -1;
        }
    }
    uint32_t every_par = engine->token_parameters[HSTEX_TOKEN_EVERY_PAR];
    if (every_par == 0U) {
        return 0;
    }
    const struct hstex_token_list *list =
        token_list_by_identifier(engine, every_par);
    struct hstex_source_location location = {0};
    if (list == NULL ||
        hstex_source_push_tokens(&engine->sources, list->tokens, list->count,
                                 location, error, error_capacity) != 0) {
        return set_error(error, error_capacity,
                         "could not install everypar tokens");
    }
    hstex_source_name_top(&engine->sources,
                          (uint8_t)HSTEX_TOKEN_SOURCE_TOKEN_PARAMETER,
                          (uint32_t)HSTEX_TOKEN_EVERY_PAR);
    trace_token_parameter(engine, (size_t)HSTEX_TOKEN_EVERY_PAR);
    return 0;
}

/* End a paragraph: the list is finished off and broken into lines, which join
   the vertical list. Only a paragraph that fits on one line is handled. */
/* ---------------------------------------------------------------------- */
/* Breaking a paragraph into lines.                                       */
/*                                                                        */
/* The reference's optimal-fit method: every legal breakpoint is tried    */
/* against every break that could still start the line, and the sequence  */
/* with the fewest demerits wins. See docs/DECISIONS.md, line-breaking.   */
/* ---------------------------------------------------------------------- */

#define HSTEX_EJECT_PENALTY (-10000)

enum hstex_fitness {
    HSTEX_FIT_VERY_LOOSE = 0,
    HSTEX_FIT_LOOSE,
    HSTEX_FIT_DECENT,
    HSTEX_FIT_TIGHT,
    HSTEX_FIT_COUNT,
};

/* Everything a line's measurement needs, summed over the nodes before a
   point so that any line's totals are one subtraction apart. */
struct hstex_break_totals {
    int64_t width;
    int64_t stretch[4];
    int64_t shrink;
};

/* One break that a later line could start from. */
struct hstex_break_record {
    size_t breakpoint;
    size_t start;
    int32_t line;
    uint8_t fitness;
    int64_t demerits;
    size_t previous;
    /* What a line starting here carries in front of it: the text a
       discretionary puts after the break. See docs/DECISIONS.md,
       discretionaries. */
    int32_t entry_width;
    uint32_t entry_start;
    uint16_t entry_count;
    /* This break is a discretionary's, which is what \brokenpenalty and the
       double-hyphen demerits are about. */
    bool hyphenated;
    /* How much narrower a line starting here is for letting its first
       character stick out past the margin. */
    int32_t left_kern;
};

/* Everything a breakpoint contributes beyond its position. */
struct hstex_break_site {
    int32_t penalty;
    /* The text a discretionary puts at the end of the line that breaks
       here, and the text it puts at the start of the next one. */
    int32_t pre_width;
    int32_t entry_width;
    uint32_t entry_start;
    uint16_t entry_count;
    /* Where the next line begins, or SIZE_MAX to work it out by pruning. */
    size_t start;
    bool hyphenated;
};

/* What \tracingparagraphs is in the middle of writing; see
   docs/DECISIONS.md, tracing-paragraphs. */
struct hstex_break_trace {
    /* Whether \tracingparagraphs is writing at all; the writing itself goes
       through the engine's printer. */
    bool active;
    /* The first node of the paragraph that has not been shown yet. */
    size_t printed;
    /* The font the short display is in, so that a change is announced. */
    uint32_t font;
    bool font_known;
    /* False when the output stands at the start of a line. */
    bool column;
};

struct hstex_break_state {
    struct hstex_break_trace trace;
    struct hstex_break_totals *totals;
    /* Where the paragraph's first glue that shrinks without limit stands,
       and whether the fault has been reported: one report a paragraph,
       whether it was a skip parameter or a glue in the list. */
    size_t shrink_error_at;
    bool shrink_error_reported;
    size_t node_count;
    struct hstex_break_record *records;
    size_t record_count;
    size_t record_capacity;
    size_t *active;
    size_t active_count;
    size_t active_capacity;
    /* The active list is rebuilt into this one and the two are swapped, so a
       new node can go in AT THE WALK'S POSITION rather than at the end. That
       is what keeps the list in class order, and what lets a class be
       finished the moment the walk moves past it. */
    size_t *rebuilt;
    size_t rebuilt_count;
    size_t rebuilt_capacity;
};

/* Glue that shrinks without limit would let a paragraph of any length fit
   on one line, so the reference says so and takes the shrinkage as finite --
   keeping the amount and dropping the order, so that `\hskip 3pt minus 1fil'
   becomes `\glue 3.0 minus 1.0'. Once a paragraph, whether the offender was
   \leftskip, \rightskip or a glue in the list. See
   tests/trip/probes/glue-that-shrinks-without-limit.tex. */
static void report_infinite_shrinkage(struct hstex_engine *engine)
{
    static const char *const help[] = {
        "The paragraph just ended includes some glue that has",
        "infinite shrinkability, e.g., `\\hskip 0pt minus 1fil'.",
        "Such glue doesn't belong there---it allows a paragraph",
        "of any length to fit on one line. But it's safe to proceed,",
        "since the offensive shrinkability has been made finite.", NULL};
    /* The paragraph trace is a diagnostic, and a fault reported while one is
       open CLOSES IT FIRST -- which leaves a blank line -- and it is opened
       again afterwards. Measured: with \tracingparagraphs on there is one
       more blank line above the `!' than without, whether the fault comes
       before the first pass or in the middle of it. */
    if (engine->integer_parameters[HSTEX_INTEGER_TRACING_PARAGRAPHS] > 0) {
        print_fresh_line(engine);
        print_line(engine);
    }
    tex_error(engine, help, "Infinite glue shrinkage found in a paragraph");
}

static int emit_parameter_glue(struct hstex_engine *engine,
                               struct hstex_glue glue, int parameter,
                               char *error, size_t error_capacity);
static int emit_math_glue(struct hstex_engine *engine, struct hstex_glue glue,
                          char *error, size_t error_capacity);

static bool node_is_discardable(const struct hstex_node *node)
{
    switch (node->kind) {
    case HSTEX_NODE_GLUE:
    case HSTEX_NODE_PENALTY:
    case HSTEX_NODE_MATH:
        return true;
    case HSTEX_NODE_KERN:
        /* A kern the document asked for is thrown away at the start of a
           line; one the font asked for belongs to the text and stays. See
           docs/DECISIONS.md, what-a-line-keeps-of-its-break. */
        return node->explicit_kern;
    default:
        return false;
    }
}

/* Where the line after a break really begins: the reference throws away the
   glue, penalties and engine-made kerns that follow it. */
/* How far a character may stick out past a margin: its font's quad times the
   \lpcode or \rpcode the font gives it, in thousandths, and negative because
   the kern pulls the line's edge back. See docs/DECISIONS.md,
   character-protrusion. */
static int32_t protrusion_kern(struct hstex_engine *engine,
                               uint32_t identifier, bool left)
{
    if (identifier == 0U || (size_t)identifier > engine->node_count) {
        return 0;
    }
    const struct hstex_node *node = &engine->nodes[identifier - 1U];
    if (node->kind != HSTEX_NODE_CHARACTER &&
        node->kind != HSTEX_NODE_LIGATURE) {
        return 0;
    }
    const struct hstex_font *font =
        font_by_identifier(engine, node->value.character.font);
    uint32_t code = node->value.character.character;
    if (font == NULL || font->characters == NULL ||
        code >= (uint32_t)HSTEX_FONT_CHARACTER_COUNT || font->dimen_count < 6U) {
        return 0;
    }
    int32_t factor = left ? font->characters[code].left_protrusion
                          : font->characters[code].right_protrusion;
    if (factor == 0) {
        return 0;
    }
    /* The reference rounds this product when the code is positive and
       truncates it when the code is negative -- the routine it divides with
       was never meant for a negative multiplier. See docs/DECISIONS.md,
       character-protrusion. */
    int64_t product = (int64_t)font->dimens[5] * factor;
    int64_t scaled = factor >= 0 ? (product + 500) / 1000
                                 : -((-product) / 1000);
    return -(int32_t)scaled;
}

/* Whether the search for the character that may stick out passes over this
   node. Anything with a width of its own stops the search, as does a
   character; everything else is stepped over. */
static bool protrusion_passes_over(const struct hstex_node *node)
{
    switch (node->kind) {
    case HSTEX_NODE_CHARACTER:
    case HSTEX_NODE_LIGATURE:
        return false;
    case HSTEX_NODE_PENALTY:
    case HSTEX_NODE_WHATSIT:
    case HSTEX_NODE_MARK:
    case HSTEX_NODE_INSERT:
    case HSTEX_NODE_UNSET:
    case HSTEX_NODE_ADJUST:
        return true;
    case HSTEX_NODE_DISCRETIONARY:
        /* A discretionary with nothing of its own is stepped over; one that
           carries text either way, or replaces what follows it, stops the
           search. See docs/DECISIONS.md, a-box-at-the-edge. */
        return node->value.disc.pre_count == 0U &&
               node->value.disc.post_count == 0U &&
               node->value.disc.replace_count == 0U;
    case HSTEX_NODE_GLUE:
        /* Glue of any width stops the search, but the \parfillskip a
           paragraph ends with is not part of the line's own text. */
        return node->value.glue.parameter ==
               1U + (uint8_t)HSTEX_GLUE_PAR_FILL_SKIP;
    case HSTEX_NODE_KERN:
        /* A kern the font supplied -- an italic correction, for one -- is
           stepped over; one the document asked for stops the search unless
           it takes up no room. See docs/DECISIONS.md, protruding-past-a-kern. */
        return !node->explicit_kern || packed_dimen(node->width) == 0;
    case HSTEX_NODE_LIST:
        /* Boxes are settled by the search itself, which looks into them. */
        return false;
    case HSTEX_NODE_RULE:
        return false;
    case HSTEX_NODE_MATH:
        return packed_dimen(node->width) == 0;
    }
    return true;
}

/* The character at one end of a run of nodes, or zero when the run does not
   offer one. A horizontal box is looked into; a vertical one is not. A box
   that offers nothing of its own is stepped over, so the search carries on
   in front of it -- but only when nothing inside it stopped the search: that
   is what `stopped' reports. See docs/DECISIONS.md, a-box-at-the-edge. */
static uint32_t protruding_character(struct hstex_engine *engine,
                                     const uint32_t *items, size_t from,
                                     size_t to, bool left, bool *stopped)
{
    *stopped = false;
    for (size_t step = 0U; step < to - from; ++step) {
        size_t index = left ? from + step : to - 1U - step;
        uint32_t identifier = items[index];
        if (identifier == 0U || (size_t)identifier > engine->node_count) {
            *stopped = true;
            return 0U;
        }
        const struct hstex_node *node = &engine->nodes[identifier - 1U];
        if (node->kind == HSTEX_NODE_CHARACTER ||
            node->kind == HSTEX_NODE_LIGATURE) {
            return identifier;
        }
        if (node->kind == HSTEX_NODE_LIST) {
            if (node->value.list.box_kind == HSTEX_BOX_HLIST &&
                node->value.list.node_count != 0U &&
                (size_t)node->value.list.node_start +
                        node->value.list.node_count <=
                    engine->list_item_count) {
                bool inside = false;
                uint32_t found = protruding_character(
                    engine, engine->list_items, node->value.list.node_start,
                    (size_t)node->value.list.node_start +
                        node->value.list.node_count,
                    left, &inside);
                if (found != 0U) {
                    return found;
                }
                if (!inside) {
                    continue;
                }
                *stopped = true;
                return 0U;
            }
            /* A horizontal box with nothing in it is stepped over when it
               takes up no room at all; a vertical box always stops the
               search. */
            if (node->value.list.box_kind != HSTEX_BOX_VLIST &&
                node->value.list.node_count == 0U &&
                packed_dimen(node->width) == 0 &&
                packed_dimen(node->height) == 0 &&
                packed_dimen(node->depth) == 0) {
                continue;
            }
            *stopped = true;
            return 0U;
        }
        if (protrusion_passes_over(node)) {
            continue;
        }
        *stopped = true;
        return 0U;
    }
    return 0U;
}

/* The natural width of a run of nodes in the arena: what one of a
   discretionary's lists adds to a line. */
static int32_t list_run_width(const struct hstex_engine *engine, uint32_t start,
                              uint16_t count)
{
    int64_t width = 0;
    if (count == 0U || (size_t)start + count > engine->list_item_count) {
        return 0;
    }
    for (uint16_t index = 0U; index < count; ++index) {
        uint32_t identifier = engine->list_items[start + index];
        if (identifier == 0U || (size_t)identifier > engine->node_count) {
            continue;
        }
        width += packed_dimen(engine->nodes[identifier - 1U].width);
    }
    return (int32_t)(uint32_t)(uint64_t)width;
}

/* Whether glue right after this node is a place the line may break. Glue,
   a penalty, a formula's fence and a kern the document asked for are not
   things a line may end just after; a kern the font asked for is. See
   docs/DECISIONS.md, what-a-line-keeps-of-its-break. */
static bool precedes_glue_break(const struct hstex_node *node)
{
    switch (node->kind) {
    case HSTEX_NODE_GLUE:
    case HSTEX_NODE_PENALTY:
    case HSTEX_NODE_MATH:
        return false;
    case HSTEX_NODE_KERN:
        return !node->explicit_kern;
    case HSTEX_NODE_CHARACTER:
    case HSTEX_NODE_LIGATURE:
    case HSTEX_NODE_LIST:
    case HSTEX_NODE_RULE:
    case HSTEX_NODE_DISCRETIONARY:
    case HSTEX_NODE_WHATSIT:
    case HSTEX_NODE_MARK:
    case HSTEX_NODE_INSERT:
    case HSTEX_NODE_UNSET:
    case HSTEX_NODE_ADJUST:
        return true;
    }
    return true;
}

static size_t line_start_after(const struct hstex_engine *engine,
                               const uint32_t *items, size_t count,
                               size_t breakpoint)
{
    size_t index = breakpoint;
    while (index < count) {
        uint32_t identifier = items[index];
        if (identifier == 0U || (size_t)identifier > engine->node_count) {
            break;
        }
        if (!node_is_discardable(&engine->nodes[identifier - 1U])) {
            break;
        }
        ++index;
    }
    return index;
}

static int reserve_break_records(struct hstex_break_state *state, char *error,
                                 size_t error_capacity)
{
    if (state->record_count < state->record_capacity) {
        return 0;
    }
    size_t next = state->record_capacity == 0U ? 32U : state->record_capacity * 2U;
    if (next > SIZE_MAX / sizeof(*state->records)) {
        return set_error(error, error_capacity, "break record overflow");
    }
    void *allocation = realloc(state->records, next * sizeof(*state->records));
    if (allocation == NULL) {
        return set_error(error, error_capacity, "break record allocation failed");
    }
    state->records = allocation;
    state->record_capacity = next;
    return 0;
}

static int reserve_rebuilt_breaks(struct hstex_break_state *state, char *error,
                                  size_t error_capacity)
{
    if (state->rebuilt_count < state->rebuilt_capacity) {
        return 0;
    }
    size_t next =
        state->rebuilt_capacity == 0U ? 16U : state->rebuilt_capacity * 2U;
    if (next > SIZE_MAX / sizeof(*state->rebuilt)) {
        return set_error(error, error_capacity, "active break overflow");
    }
    void *allocation = realloc(state->rebuilt, next * sizeof(*state->rebuilt));
    if (allocation == NULL) {
        return set_error(error, error_capacity, "active break allocation failed");
    }
    state->rebuilt = allocation;
    state->rebuilt_capacity = next;
    return 0;
}

static int reserve_active_breaks(struct hstex_break_state *state, char *error,
                                 size_t error_capacity)
{
    if (state->active_count < state->active_capacity) {
        return 0;
    }
    size_t next = state->active_capacity == 0U ? 16U : state->active_capacity * 2U;
    if (next > SIZE_MAX / sizeof(*state->active)) {
        return set_error(error, error_capacity, "active break overflow");
    }
    void *allocation = realloc(state->active, next * sizeof(*state->active));
    if (allocation == NULL) {
        return set_error(error, error_capacity, "active break allocation failed");
    }
    state->active = allocation;
    state->active_capacity = next;
    return 0;
}

/* The badness and fitness of a line that runs short or long by `shortfall`,
   with `totals` the glue it has available. */
static int32_t line_badness(int64_t shortfall,
                            const struct hstex_break_totals *totals,
                            uint8_t *fitness)
{
    if (shortfall > 0) {
        if (totals->stretch[1] != 0 || totals->stretch[2] != 0 ||
            totals->stretch[3] != 0) {
            *fitness = (uint8_t)HSTEX_FIT_DECENT;
            return 0;
        }
        /* A line that would have to stretch further than the reference is
           willing to measure is infinitely bad, and as loose as a line can
           be. See docs/DECISIONS.md, a-line-too-short-to-measure. */
        if (shortfall > INT64_C(7230584) &&
            totals->stretch[0] < INT64_C(1663497)) {
            *fitness = (uint8_t)HSTEX_FIT_VERY_LOOSE;
            return HSTEX_INFINITE_BADNESS;
        }
        int32_t badness =
            glue_badness((int32_t)shortfall, (int32_t)totals->stretch[0]);
        *fitness = badness > 99   ? (uint8_t)HSTEX_FIT_VERY_LOOSE
                   : badness > 12 ? (uint8_t)HSTEX_FIT_LOOSE
                                  : (uint8_t)HSTEX_FIT_DECENT;
        return badness;
    }
    if (-shortfall > totals->shrink) {
        *fitness = (uint8_t)HSTEX_FIT_TIGHT;
        return HSTEX_INFINITE_BADNESS + 1;
    }
    int32_t badness =
        glue_badness((int32_t)-shortfall, (int32_t)totals->shrink);
    *fitness = badness > 12 ? (uint8_t)HSTEX_FIT_TIGHT
                            : (uint8_t)HSTEX_FIT_DECENT;
    return badness;
}

/* Try every active break as the start of a line ending here. */
/* The kern that goes in front of a line starting here, so that its first
   character may stick out past the left margin. A line that begins with what
   a discretionary put after the break looks there first. */
static int32_t line_left_kern(struct hstex_engine *engine,
                              const uint32_t *items, size_t count,
                              size_t start,
                              const struct hstex_break_site *site)
{
    uint32_t character = 0U;
    bool stopped = false;
    if (site->entry_count != 0U &&
        (size_t)site->entry_start + site->entry_count <=
            engine->list_item_count) {
        character = protruding_character(
            engine, engine->list_items, site->entry_start,
            (size_t)site->entry_start + site->entry_count, true, &stopped);
    }
    if (character == 0U && !stopped && start < count) {
        character = protruding_character(engine, items, start, count, true,
                                         &stopped);
    }
    return protrusion_kern(engine, character, true);
}

/* The kern that goes at the end of a line breaking here. A line that ends at
   a discretionary ends with the text that goes before the break. */
static int32_t line_right_kern(struct hstex_engine *engine,
                               const uint32_t *items, size_t count,
                               size_t breakpoint)
{
    uint32_t character = 0U;
    bool stopped = false;
    const struct hstex_node *node =
        breakpoint < count && items[breakpoint] != 0U &&
                (size_t)items[breakpoint] <= engine->node_count
            ? &engine->nodes[items[breakpoint] - 1U]
            : NULL;
    if (node != NULL && node->kind == HSTEX_NODE_DISCRETIONARY &&
        node->value.disc.pre_count != 0U &&
        (size_t)node->value.disc.pre_start + node->value.disc.pre_count <=
            engine->list_item_count) {
        character = protruding_character(
            engine, engine->list_items, node->value.disc.pre_start,
            (size_t)node->value.disc.pre_start + node->value.disc.pre_count,
            false, &stopped);
    }
    if (character == 0U && !stopped && breakpoint != 0U) {
        character = protruding_character(engine, items, 0U, breakpoint, false,
                                         &stopped);
    }
    return protrusion_kern(engine, character, false);
}

/* print_nl: a newline first unless the output already stands at one. */
static void trace_newline(struct hstex_engine *engine,
                          struct hstex_break_trace *trace)
{
    if (engine->message_column > 0) {
        print_line(engine);
        trace->column = false;
    }
}

static void trace_font(struct hstex_engine *engine,
                       struct hstex_break_trace *trace, uint32_t font)
{
    if (trace->font_known && trace->font == font) {
        return;
    }
    trace->font = font;
    trace->font_known = true;
    const struct hstex_font *metrics = font_by_identifier(engine, font);
    print_escape_character(engine);
    size_t length = 0U;
    const uint8_t *name = NULL;
    enum hstex_symbol_kind kind = HSTEX_SYMBOL_REGULAR;
    if (metrics != NULL && metrics->identifier_cs != 0U &&
        hstex_symbol_name(&engine->lexical_state.symbols,
                          metrics->identifier_cs, &kind, &name, &length) == 0 &&
        name != NULL) {
        print_bytes(engine, (const char *)name, length);
    } else if (metrics != NULL && metrics->name != NULL) {
        print_text(engine, metrics->name);
    }
    print_byte(engine, ' ');
    trace->column = true;
}

/* short_display: the text of a run of nodes, with everything that is not a
   character standing for itself. See docs/DECISIONS.md, tracing-paragraphs. */
static void trace_short_display(struct hstex_engine *engine,
                                struct hstex_break_trace *trace,
                                const uint32_t *items, size_t from, size_t to)
{
    for (size_t index = from; index < to; ++index) {
        uint32_t identifier = items[index];
        if (identifier == 0U || (size_t)identifier > engine->node_count) {
            continue;
        }
        const struct hstex_node *node = &engine->nodes[identifier - 1U];
        switch (node->kind) {
        case HSTEX_NODE_CHARACTER:
            trace_font(engine, trace, node->value.character.font);
            show_ascii(engine, (uint8_t)node->value.character.character);
            trace->column = true;
            break;
        case HSTEX_NODE_LIGATURE: {
            trace_font(engine, trace, node->value.character.font);
            /* A ligature stands for what it was made of, so one that was
               made of nothing -- the character an operation put between two
               it kept -- stands for nothing. */
            uint8_t count = node->value.character.original_count;
            for (uint8_t item = 0U; item < count; ++item) {
                show_ascii(engine, node->value.character.originals[item]);
            }
            trace->column = true;
            break;
        }
        case HSTEX_NODE_LIST:
        case HSTEX_NODE_UNSET:
        case HSTEX_NODE_WHATSIT:
        /* An insertion, a mark and a \vadjust stand in a horizontal list
           until the line they are on is packed, and a short display shows
           each of them the way it shows a box: as `[]'. */
        case HSTEX_NODE_INSERT:
        case HSTEX_NODE_MARK:
        case HSTEX_NODE_ADJUST:
            print_text(engine, "[]");
            trace->column = true;
            break;
        case HSTEX_NODE_RULE:
            print_byte(engine, '|');
            trace->column = true;
            break;
        case HSTEX_NODE_GLUE: {
            /* A space for every glue but the SHARED ZERO one. A parameter or
               a register assigned nothing at all becomes that shared glue --
               an untouched \rightskip, or one set to 0pt -- and shows
               nothing. Glue written out keeps a spec of its own however
               empty it is, so `\hskip0pt' between two letters does show a
               space. A kern is not glue and never shows one. See
               docs/DECISIONS.md, a-short-display-of-glue. */
            bool empty = node->width == 0 && node->value.glue.stretch == 0 &&
                         node->value.glue.shrink == 0;
            /* Math spacing is worked out from a mu parameter rather than
               taken from it, so it has a glue of its own however empty it
               comes out, and shows a space. Its name is beyond the ordinary
               glue parameters. */
            bool own_glue =
                node->value.glue.parameter == 0U ||
                node->value.glue.parameter > (uint8_t)HSTEX_GLUE_PARAMETER_COUNT;
            if (!empty || own_glue) {
                print_byte(engine, ' ');
                trace->column = true;
            }
            break;
        }
        case HSTEX_NODE_MATH:
            print_byte(engine, '$');
            trace->column = true;
            break;
        case HSTEX_NODE_DISCRETIONARY: {
            const struct hstex_node saved = *node;
            if ((size_t)saved.value.disc.pre_start + saved.value.disc.pre_count <=
                engine->list_item_count) {
                trace_short_display(engine, trace,
                                    engine->list_items +
                                        saved.value.disc.pre_start,
                                    0U, saved.value.disc.pre_count);
            }
            if ((size_t)saved.value.disc.post_start +
                    saved.value.disc.post_count <=
                engine->list_item_count) {
                trace_short_display(engine, trace,
                                    engine->list_items +
                                        saved.value.disc.post_start,
                                    0U, saved.value.disc.post_count);
            }
            index += saved.value.disc.replace_count;
            break;
        }
        default:
            break;
        }
    }
}
/* The text of a run of nodes, as an over- or underfull box is reported
   with, and then the nodes themselves. */
static void show_short_display_of(struct hstex_engine *engine,
                                  const uint32_t *items, size_t count)
{
    struct hstex_break_trace trace = {0};
    trace_short_display(engine, &trace, items, 0U, count);
}

static void show_list_at_top(struct hstex_engine *engine,
                             const uint32_t *items, size_t count)
{
    int32_t threshold = engine->integer_parameters[HSTEX_INTEGER_SHOW_BOX_DEPTH];
    int32_t breadth = engine->integer_parameters[HSTEX_INTEGER_SHOW_BOX_BREADTH];
    if (breadth <= 0) {
        breadth = 5;
    }
    if (threshold < 0) {
        threshold = 0;
    }
    if (threshold > 255) {
        threshold = 255;
    }
    char prefix[256];
    memset(prefix, '.', sizeof(prefix));
    /* The nodes stand inside the box, so they are shown one level under
       it. */
    show_node_list(engine, items, count, prefix, 1U, (size_t)threshold,
                   (size_t)breadth, '.');
}


/* The command that stands at a breakpoint, as the trace names it. */
static const char *trace_break_name(const struct hstex_engine *engine,
                                    const uint32_t *items, size_t count,
                                    size_t breakpoint)
{
    if (breakpoint >= count) {
        return "\\par";
    }
    uint32_t identifier = items[breakpoint];
    if (identifier == 0U || (size_t)identifier > engine->node_count) {
        return "";
    }
    switch (engine->nodes[identifier - 1U].kind) {
    case HSTEX_NODE_GLUE:
        return "";
    case HSTEX_NODE_PENALTY:
        return "\\penalty";
    case HSTEX_NODE_DISCRETIONARY:
        return "\\discretionary";
    case HSTEX_NODE_KERN:
        return "\\kern";
    default:
        return "\\math";
    }
}

/* The width a line of the given number is set to; \parshape and \hangindent
   make it differ from line to line. */
static int32_t line_width_for(const struct hstex_engine *engine, int32_t line);

/* WHICH BREAKS ARE ALIKE. A break that would start line four and one that
   would start line five are the same break, or different ones, according to
   this number; the reference keeps one active node per fitness for each. It
   is NOT the line's width that decides -- measured, under \hangafter=2 lines
   two and three are alike although their widths differ, and under
   \hangafter=1 lines one and two are alike although theirs do too. What
   fits every measurement is min(line, E), where E is the last line whose
   width is its own: \parshape's pair count, or |\hangafter| where
   \hangindent is set, or nought -- and unbounded where there is any
   \looseness. See
   tests/trip/probes/every-break-is-weighed-against-its-own-line.tex. */
static int32_t break_line_class(const struct hstex_engine *engine,
                                int32_t line)
{
    if (engine->integer_parameters[HSTEX_INTEGER_LOOSENESS] != 0) {
        return line;
    }
    int32_t last = 0;
    if (engine->parshape != 0U) {
        /* \parshape's last pair stands for every line after it, so the last
           line whose width differs from the next one's is the one BEFORE the
           last pair: three pairs make lines three and four alike. */
        const int32_t *shape = engine->parshapes + (engine->parshape - 1U);
        last = shape[0] > 1 ? shape[0] - 1 : 0;
    } else if (engine->dimen_parameters[HSTEX_DIMEN_HANG_INDENT] != 0) {
        /* \hangafter names where the width changes, either way about, so
           that line and the next really are different. */
        int32_t after = engine->integer_parameters[HSTEX_INTEGER_HANG_AFTER];
        last = after < 0 ? -after : after;
    }
    return line < last ? line : last;
}

/* The best feasible break of each fitness among the candidates just weighed,
   made into active nodes on the rebuilt list. Called once for every class the
   candidates covered, at the moment the walk leaves that class, so the `@@n:'
   lines fall between the `@ via' lines the way the reference writes them. */
static int create_break_records(struct hstex_engine *engine,
                                struct hstex_break_state *state,
                                const uint32_t *items, size_t count,
                                size_t breakpoint, size_t start,
                                const struct hstex_break_site *site,
                                bool protruding, const int64_t *minimal,
                                const size_t *best, const int32_t *best_line,
                                int64_t minimum, int32_t adjacent,
                                char *error, size_t error_capacity)
{
    if (minimum == HSTEX_AWFUL_BADNESS) {
        return 0;
    }
    int64_t ceiling = minimum + (adjacent < 0 ? -(int64_t)adjacent : adjacent);
    for (size_t fit = 0U; fit < (size_t)HSTEX_FIT_COUNT; ++fit) {
        if (minimal[fit] > ceiling) {
            continue;
        }
        if (reserve_break_records(state, error, error_capacity) != 0 ||
            reserve_rebuilt_breaks(state, error, error_capacity) != 0) {
            return -1;
        }
        struct hstex_break_record *record = &state->records[state->record_count];
        memset(record, 0, sizeof(*record));
        record->breakpoint = breakpoint;
        record->start = start;
        record->line = best_line[fit] + 1;
        record->fitness = (uint8_t)fit;
        record->demerits = minimal[fit];
        record->previous = best[fit];
        record->entry_width = site->entry_width;
        record->entry_start = site->entry_start;
        record->entry_count = site->entry_count;
        record->hyphenated = site->hyphenated;
        record->left_kern =
            protruding ? line_left_kern(engine, items, count, start, site) : 0;
        if (state->trace.active) {
            trace_newline(engine, &state->trace);
            print_formatted(engine, "@@%zu: line %d.%zu%s t=%lld -> @@%zu\n",
                          state->record_count, record->line, fit,
                          site->hyphenated ? "-" : "",
                          (long long)record->demerits,
                          best[fit] == SIZE_MAX ? (size_t)0U : best[fit]);
            state->trace.column = false;
        }
        state->rebuilt[state->rebuilt_count++] = state->record_count;
        ++state->record_count;
    }
    return 0;
}

static int try_break_at(struct hstex_engine *engine,
                        struct hstex_break_state *state,
                        const uint32_t *items, size_t count,
                        const struct hstex_break_totals *background,
                        size_t breakpoint,
                        const struct hstex_break_site *site, int32_t threshold,
                        bool final_pass, char *error, size_t error_capacity)
{
    int32_t penalty = site->penalty;
    /* THE PENALTY IS BROUGHT INTO RANGE FIRST. Ten thousand or more forbids
       the break outright, and ten thousand or more the other way IS exactly
       -10000 from here on, whatever the document wrote -- so the reference
       traces `p=-10000' for a `\penalty-1000000000', and takes the break as
       a forced one, which a raw -1000000000 would not have matched. */
    if (penalty >= HSTEX_INFINITE_PENALTY) {
        return 0;
    }
    if (penalty <= HSTEX_EJECT_PENALTY) {
        penalty = HSTEX_EJECT_PENALTY;
    }
    int64_t minimal[HSTEX_FIT_COUNT];
    size_t best[HSTEX_FIT_COUNT];
    int32_t best_line[HSTEX_FIT_COUNT];
    for (size_t fit = 0U; fit < (size_t)HSTEX_FIT_COUNT; ++fit) {
        minimal[fit] = HSTEX_AWFUL_BADNESS;
        best[fit] = SIZE_MAX;
        best_line[fit] = 0;
    }
    int64_t minimum = HSTEX_AWFUL_BADNESS;
    /* ONE ACTIVE NODE PER CLASS, not one for the whole breakpoint. The list
       is walked in class order, so a class is finished the moment the walk
       moves past it, and its nodes go in at that point. */
    int32_t open_class = 0;
    bool class_open = false;
    size_t start = site->start == SIZE_MAX
                       ? line_start_after(engine, items, count, breakpoint)
                       : site->start;
    int32_t line_penalty = engine->integer_parameters[HSTEX_INTEGER_LINE_PENALTY];
    int32_t adjacent = engine->integer_parameters[HSTEX_INTEGER_ADJ_DEMERITS];
    /* Only \pdfprotrudechars=2 lets a character sticking out past the margin
       change where the line is broken; see docs/DECISIONS.md,
       character-protrusion. */
    bool protruding =
        engine->integer_parameters[HSTEX_INTEGER_PDF_PROTRUDE_CHARS] >= 2;
    /* The break that ends the paragraph is measured without the kern that
       lets its last character stick out, even though the line is set with
       one; see docs/DECISIONS.md, the-last-line-is-measured-square. */
    int32_t right_kern =
        protruding && breakpoint < count
            ? line_right_kern(engine, items, count, breakpoint)
            : 0;

    state->rebuilt_count = 0U;
    for (size_t slot = 0U; slot < state->active_count; ++slot) {
        size_t index = state->active[slot];
        int32_t line_class =
            break_line_class(engine, state->records[index].line + 1);
        if (class_open && line_class != open_class) {
            /* Making records may move the record arena, so nothing may be
               held across this. */
            if (create_break_records(engine, state, items, count, breakpoint,
                                     start, site, protruding, minimal, best,
                                     best_line, minimum, adjacent, error,
                                     error_capacity) != 0) {
                return -1;
            }
            for (size_t fit = 0U; fit < (size_t)HSTEX_FIT_COUNT; ++fit) {
                minimal[fit] = HSTEX_AWFUL_BADNESS;
                best[fit] = SIZE_MAX;
                best_line[fit] = 0;
            }
            minimum = HSTEX_AWFUL_BADNESS;
        }
        open_class = line_class;
        class_open = true;
        const struct hstex_break_record *record = &state->records[index];
        struct hstex_break_totals totals = *background;
        totals.width += (int64_t)record->entry_width + site->pre_width +
                        record->left_kern + right_kern +
                        state->totals[breakpoint].width -
                        state->totals[record->start].width;
        for (size_t order = 0U; order < 4U; ++order) {
            totals.stretch[order] += state->totals[breakpoint].stretch[order] -
                                     state->totals[record->start].stretch[order];
        }
        totals.shrink += state->totals[breakpoint].shrink -
                         state->totals[record->start].shrink;
        uint8_t fitness = (uint8_t)HSTEX_FIT_DECENT;
        int32_t badness =
            /* EVERY CANDIDATE IS WEIGHED AGAINST ITS OWN LINE'S WIDTH. A
               break that would start line five is measured against line
               five, not against whatever line the first active node happens
               to sit on -- which only shows where \parshape or \hangindent
               makes the widths differ. */
            line_badness((int64_t)line_width_for(engine, record->line + 1) -
                             totals.width,
                         &totals, &fitness);

        bool artificial = false;
        bool stays_active = true;
        if (badness > HSTEX_INFINITE_BADNESS || penalty == HSTEX_EJECT_PENALTY) {
            /* The last resort is taken only when NOTHING has been put on
               the rebuilt list -- neither a node that stays active nor a
               record made for an earlier class. `minimum' alone will not do,
               since it is given back at every class boundary. */
            if (final_pass && minimum == HSTEX_AWFUL_BADNESS &&
                slot + 1U == state->active_count &&
                state->rebuilt_count == 0U) {
                artificial = true;
            } else if (badness > threshold) {
                continue; /* this break can never start a line again */
            }
            stays_active = false;
        } else {
            if (badness > threshold) {
                if (reserve_rebuilt_breaks(state, error, error_capacity) != 0) {
                    return -1;
                }
                state->rebuilt[state->rebuilt_count++] = index;
                continue;
            }
        }

        int64_t demerits;
        if (artificial) {
            demerits = 0;
        } else {
            int64_t scaled = (int64_t)line_penalty + badness;
            demerits = scaled >= HSTEX_INFINITE_BADNESS ||
                               scaled <= -HSTEX_INFINITE_BADNESS
                           ? INT64_C(100000000)
                           : scaled * scaled;
            if (penalty != 0) {
                if (penalty > 0) {
                    demerits += (int64_t)penalty * penalty;
                } else if (penalty > HSTEX_EJECT_PENALTY) {
                    demerits -= (int64_t)penalty * penalty;
                }
            }
            int fit_gap = (int)fitness - (int)record->fitness;
            if (fit_gap > 1 || fit_gap < -1) {
                demerits += adjacent;
            }
            /* Two hyphenated lines in a row cost extra, and more still when
               the second of them is the last line of the paragraph. */
            if (site->hyphenated && record->hyphenated) {
                demerits += breakpoint >= count
                                ? engine->integer_parameters
                                      [HSTEX_INTEGER_FINAL_HYPHEN_DEMERITS]
                                : engine->integer_parameters
                                      [HSTEX_INTEGER_DOUBLE_HYPHEN_DEMERITS];
            }
        }
        if (state->trace.active) {
            trace_newline(engine, &state->trace);
            /* The text runs to the breakpoint and takes it in, so that the
               glue a line breaks at shows as the space it is. */
            if (state->trace.printed <= breakpoint) {
                size_t end = breakpoint < count ? breakpoint + 1U : count;
                /* A word is hyphenated where the pass REACHES it, which is
                   the start of the stretch about to be drawn rather than its
                   end: the warning belongs in front of that stretch. */
                release_lost_characters(engine, state->trace.printed + 1U);
                trace_short_display(engine, &state->trace, items,
                                    state->trace.printed, end);
                /* What a discretionary replaces was shown with the
                   discretionary -- as its two texts, not as itself -- so the
                   next stretch begins past it. Measured: the reference shows
                   ` ' for the stretch after
                   `\discretionary{}{\kern2pt-}{B\kern2pt} ', not `B '. */
                if (end != 0U && end <= count) {
                    uint32_t last = items[end - 1U];
                    if (last != 0U && (size_t)last <= engine->node_count &&
                        engine->nodes[last - 1U].kind ==
                            HSTEX_NODE_DISCRETIONARY) {
                        end += engine->nodes[last - 1U].value.disc.replace_count;
                        if (end > count) {
                            end = count;
                        }
                    }
                }
                state->trace.printed = end;
                trace_newline(engine, &state->trace);
            }
            print_byte(engine, '@');
            print_esc_text(engine,
                           trace_break_name(engine, items, count, breakpoint));
            print_formatted(engine, " via @@%zu b=", index);
            if (badness > HSTEX_INFINITE_BADNESS) {
                print_byte(engine, '*');
            } else {
                print_formatted(engine, "%d", badness);
            }
            print_formatted(engine, " p=%d d=", penalty);
            if (artificial) {
                print_byte(engine, '*');
            } else {
                print_formatted(engine, "%lld", (long long)demerits);
            }
            print_line(engine);
            state->trace.column = false;
        }
        demerits += record->demerits;
        if (demerits <= minimal[fitness]) {
            minimal[fitness] = demerits;
            best[fitness] = index;
            best_line[fitness] = record->line;
            if (demerits < minimum) {
                minimum = demerits;
            }
        }
        if (stays_active) {
            if (reserve_rebuilt_breaks(state, error, error_capacity) != 0) {
                return -1;
            }
            state->rebuilt[state->rebuilt_count++] = index;
        }
    }
    if (create_break_records(engine, state, items, count, breakpoint, start,
                             site, protruding, minimal, best, best_line,
                             minimum, adjacent, error, error_capacity) != 0) {
        return -1;
    }
    /* The rebuilt list becomes the active one, and the old buffer is kept to
       be rebuilt into next time. */
    size_t *swapped = state->active;
    size_t swapped_capacity = state->active_capacity;
    state->active = state->rebuilt;
    state->active_count = state->rebuilt_count;
    state->active_capacity = state->rebuilt_capacity;
    state->rebuilt = swapped;
    state->rebuilt_capacity = swapped_capacity;
    state->rebuilt_count = 0U;
    return 0;
}

/* The indent and length \parshape gives a line, the last pair standing for
   every line after it. See docs/DECISIONS.md, parshape. */
static const int32_t *parshape_pair(const struct hstex_engine *engine,
                                    int32_t line)
{
    if (engine->parshape == 0U) {
        return NULL;
    }
    const int32_t *shape = engine->parshapes + (engine->parshape - 1U);
    int32_t count = shape[0];
    if (count <= 0) {
        return NULL;
    }
    int32_t which = line < 1 ? 1 : line;
    if (which > count) {
        which = count;
    }
    return shape + 1 + 2 * (which - 1);
}

/* The width a given line is set to. \parshape says so outright; failing
   that, hanging indentation narrows the lines it covers. */
static int32_t line_width_for(const struct hstex_engine *engine, int32_t line)
{
    const int32_t *pair = parshape_pair(engine, line);
    if (pair != NULL) {
        return pair[1];
    }
    int32_t hsize = engine->dimen_parameters[HSTEX_DIMEN_HSIZE];
    int32_t hang = engine->dimen_parameters[HSTEX_DIMEN_HANG_INDENT];
    if (hang == 0) {
        return hsize;
    }
    int32_t after = engine->integer_parameters[HSTEX_INTEGER_HANG_AFTER];
    bool hanging = after >= 0 ? line > after : line <= -after;
    int32_t amount = hang < 0 ? -hang : hang;
    return hanging ? hsize - amount : hsize;
}

static int32_t line_shift_for(const struct hstex_engine *engine, int32_t line)
{
    const int32_t *pair = parshape_pair(engine, line);
    if (pair != NULL) {
        return pair[0];
    }
    int32_t hang = engine->dimen_parameters[HSTEX_DIMEN_HANG_INDENT];
    if (hang <= 0) {
        return 0;
    }
    int32_t after = engine->integer_parameters[HSTEX_INTEGER_HANG_AFTER];
    bool hanging = after >= 0 ? line > after : line <= -after;
    return hanging ? hang : 0;
}

/* One pass over the paragraph at a given badness threshold. Returns 1 when a
   sequence of breaks was found, 0 when none was. */
static int find_paragraph_breaks(struct hstex_engine *engine,
                                 struct hstex_break_state *state,
                                 const uint32_t *items, size_t count,
                                 const struct hstex_break_totals *background,
                                 int32_t threshold, bool final_pass,
                                 size_t *best, char *error,
                                 size_t error_capacity)
{
    state->record_count = 0U;
    state->active_count = 0U;
    if (reserve_break_records(state, error, error_capacity) != 0 ||
        reserve_active_breaks(state, error, error_capacity) != 0) {
        return -1;
    }
    struct hstex_break_record *first = &state->records[state->record_count];
    memset(first, 0, sizeof(*first));
    first->breakpoint = 0U;
    first->start = 0U;
    first->line = engine->prev_graf;
    first->fitness = (uint8_t)HSTEX_FIT_DECENT;
    first->demerits = 0;
    first->previous = SIZE_MAX;
    /* The paragraph's own first line lets its first character stick out just
       as any other line does; see docs/DECISIONS.md, character-protrusion. */
    if (engine->integer_parameters[HSTEX_INTEGER_PDF_PROTRUDE_CHARS] >= 2) {
        struct hstex_break_site opening = {0};
        opening.start = SIZE_MAX;
        first->left_kern = line_left_kern(engine, items, count, 0U, &opening);
    }
    state->active[state->active_count++] = state->record_count;
    ++state->record_count;

    bool after_box = false;
    /* Glue inside a formula is not a place to break; the nodes that fence
       one turn that off and on again. See docs/DECISIONS.md, math-nodes. */
    bool automatic = true;
    for (size_t index = 0U; index < count; ++index) {
        uint32_t identifier = items[index];
        if (identifier == 0U || (size_t)identifier > engine->node_count) {
            continue;
        }
        const struct hstex_node *node = &engine->nodes[identifier - 1U];
        struct hstex_break_site site = {0};
        site.start = SIZE_MAX;
        bool legal = false;
        if (node->kind == HSTEX_NODE_GLUE) {
            legal = after_box && automatic;
        } else if (node->kind == HSTEX_NODE_MATH) {
            automatic = node->value.math.after;
            if (automatic && index + 1U < count) {
                uint32_t next = items[index + 1U];
                legal = next != 0U && (size_t)next <= engine->node_count &&
                        engine->nodes[next - 1U].kind == HSTEX_NODE_GLUE;
            }
        } else if (node->kind == HSTEX_NODE_KERN) {
            if (node->explicit_kern && index + 1U < count) {
                uint32_t next = items[index + 1U];
                legal = next != 0U && (size_t)next <= engine->node_count &&
                        engine->nodes[next - 1U].kind == HSTEX_NODE_GLUE;
            }
        } else if (node->kind == HSTEX_NODE_PENALTY) {
            site.penalty = node->value.penalty;
            legal = site.penalty < HSTEX_INFINITE_BADNESS;
        } else if (node->kind == HSTEX_NODE_DISCRETIONARY) {
            /* A discretionary with nothing to put before the break costs
               \exhyphenpenalty; one that writes a hyphen costs
               \hyphenpenalty. See docs/DECISIONS.md, discretionaries. */
            legal = true;
            site.hyphenated = true;
            site.penalty =
                node->value.disc.pre_count == 0U
                    ? engine->integer_parameters
                          [HSTEX_INTEGER_EX_HYPHEN_PENALTY]
                    : engine->integer_parameters[HSTEX_INTEGER_HYPHEN_PENALTY];
            site.pre_width = list_run_width(engine, node->value.disc.pre_start,
                                            node->value.disc.pre_count);
            site.entry_width = list_run_width(
                engine, node->value.disc.post_start,
                node->value.disc.post_count);
            site.entry_start = node->value.disc.post_start;
            site.entry_count = node->value.disc.post_count;
            size_t after = index + 1U + node->value.disc.replace_count;
            if (after > count) {
                after = count;
            }
            /* Nothing is pruned in front of text the discretionary itself
               put there. */
            site.start = node->value.disc.post_count != 0U
                             ? after
                             : line_start_after(engine, items, count, after);
        }
        if (legal && state->active_count != 0U) {
            if (try_break_at(engine, state, items, count, background,
                             index, &site, threshold, final_pass, error,
                             error_capacity) != 0) {
                return -1;
            }
        }
        /* The glue that shrinks without limit is complained about HERE, once
           the break in front of it has been weighed -- measured, the line
           comes after the `@@1:' the breakpoint drew and before the next
           one. */
        if (index == state->shrink_error_at && !state->shrink_error_reported) {
            state->shrink_error_reported = true;
            report_infinite_shrinkage(engine);
        }
        /* WHAT A DISCRETIONARY REPLACES IS NOT LOOKED AT FOR BREAKS. The
           nodes it stands in front of belong to it, and the search steps
           straight over them: measured on
           `\discretionary{}{\kern2pt-}{B\kern2pt} C', where the reference
           breaks at the space after the C and hstex was breaking at the
           kern inside the replacement. Their widths are still counted --
           the totals are taken by position, not by this walk. */
        if (node->kind == HSTEX_NODE_DISCRETIONARY) {
            size_t replaced = node->value.disc.replace_count;
            if (replaced > count - index - 1U) {
                replaced = count - index - 1U;
            }
            index += replaced;
        }
        after_box = precedes_glue_break(node);
    }
    if (state->active_count == 0U) {
        *best = SIZE_MAX;
        return 0;
    }
    /* The forced break at the end counts as a hyphenated one, so that a
       hyphen on the second-to-last line costs \finalhyphendemerits. */
    struct hstex_break_site final_site = {0};
    final_site.penalty = HSTEX_EJECT_PENALTY;
    final_site.start = SIZE_MAX;
    final_site.hyphenated = true;
    if (try_break_at(engine, state, items, count, background,
                     count, &final_site,
                     threshold, final_pass, error, error_capacity) != 0) {
        return -1;
    }
    /* Whatever the forced final break created is the answer; the cheapest of
       them is the paragraph's shape. */
    size_t chosen = SIZE_MAX;
    int64_t cheapest = HSTEX_AWFUL_BADNESS;
    for (size_t slot = 0U; slot < state->active_count; ++slot) {
        size_t index = state->active[slot];
        if (state->records[index].breakpoint != count) {
            continue;
        }
        if (state->records[index].demerits < cheapest) {
            cheapest = state->records[index].demerits;
            chosen = index;
        }
    }
    /* \looseness ASKS FOR A PARAGRAPH SO MANY LINES LONGER than the best
       way of breaking it. The reference takes the way whose line count comes
       closest to that, and among equals the cheapest. Measured: a paragraph
       that breaks into three lines becomes four at \looseness=1, five at 2
       and twelve at 9, and stays at three when asked to be shorter than it
       can be. */
    int32_t looseness = engine->integer_parameters[HSTEX_INTEGER_LOOSENESS];
    if (chosen != SIZE_MAX && looseness != 0) {
        int32_t best_line = state->records[chosen].line;
        int32_t actual = 0;
        int64_t fewest = state->records[chosen].demerits;
        size_t wanted = chosen;
        for (size_t slot = 0U; slot < state->active_count; ++slot) {
            size_t index = state->active[slot];
            if (state->records[index].breakpoint != count) {
                continue;
            }
            int32_t difference = state->records[index].line - best_line;
            if ((difference < actual && looseness <= difference) ||
                (difference > actual && looseness >= difference)) {
                wanted = index;
                actual = difference;
                fewest = state->records[index].demerits;
            } else if (difference == actual &&
                       state->records[index].demerits < fewest) {
                wanted = index;
                fewest = state->records[index].demerits;
            }
        }
        chosen = wanted;
        /* What was asked for could not be had, so the reference tries again
           with more tolerance rather than settling for this. */
        if (actual != looseness && !final_pass) {
            *best = SIZE_MAX;
            return 0;
        }
    }
    *best = chosen;
    return chosen == SIZE_MAX ? 0 : 1;
}

/* Package the chosen sequence of breaks into lines and contribute them. */
static int emit_paragraph_lines(struct hstex_engine *engine,
                                struct hstex_break_state *state,
                                const uint32_t *items, size_t count,
                                size_t best, struct hstex_box *out_last,
                                char *error, size_t error_capacity)
{
    size_t depth = 0U;
    for (size_t index = best; index != SIZE_MAX;
         index = state->records[index].previous) {
        ++depth;
    }
    size_t *chain = calloc(depth, sizeof(*chain));
    if (chain == NULL) {
        return set_error(error, error_capacity, "line chain allocation failed");
    }
    size_t position = depth;
    for (size_t index = best; index != SIZE_MAX;
         index = state->records[index].previous) {
        chain[--position] = index;
    }

    struct hstex_glue left = engine->glue_parameters[HSTEX_GLUE_LEFT_SKIP];
    struct hstex_glue right = engine->glue_parameters[HSTEX_GLUE_RIGHT_SKIP];
    int32_t interline =
        engine->integer_parameters[HSTEX_INTEGER_INTERLINE_PENALTY];
    int32_t club = engine->integer_parameters[HSTEX_INTEGER_CLUB_PENALTY];
    int32_t widow =
        engine->integer_parameters[engine->breaking_for_display
                                       ? HSTEX_INTEGER_DISPLAY_WIDOW_PENALTY
                                       : HSTEX_INTEGER_WIDOW_PENALTY];
    int status = 0;
    size_t lines = depth - 1U;
    engine->paragraph_lines =
        lines > (size_t)INT32_MAX ? INT32_MAX : (int32_t)lines;
    /* \prevgraf counts every line the paragraph has produced so far. */
    engine->prev_graf = state->records[chain[depth - 1U]].line;
    for (size_t line = 1U; status == 0 && line < depth; ++line) {
        size_t from = state->records[chain[line - 1U]].start;
        size_t to = state->records[chain[line]].breakpoint;
        /* The line's own number, which carries on past a display; see
           docs/DECISIONS.md, lines-carry-on-past-a-display. */
        int32_t numbered = state->records[chain[line]].line;
        struct hstex_hbox_builder builder = {0};
        struct hstex_hbox_builder *previous = engine->active_hbox_builder;
        enum hstex_mode previous_mode = engine->mode;
        engine->active_hbox_builder = &builder;
        engine->mode = HSTEX_MODE_HORIZONTAL;
        /* The reference only puts \leftskip in front of a line when it is
           not the zero glue; \rightskip always goes at the end. */
        status = left.width == 0 && left.stretch == 0 && left.shrink == 0
                     ? 0
                     : emit_parameter_glue(engine, left,
                                           HSTEX_GLUE_LEFT_SKIP, error,
                                           error_capacity);
        /* A character at either end of the line may be allowed to stick
           out past the margin; see docs/DECISIONS.md,
           character-protrusion. */
        bool protruding =
            engine->integer_parameters[HSTEX_INTEGER_PDF_PROTRUDE_CHARS] > 0;
        const struct hstex_break_record *opening = &state->records[chain[line - 1U]];
        if (status == 0 && protruding) {
            struct hstex_break_site opening_site = {0};
            opening_site.entry_start = opening->entry_start;
            opening_site.entry_count = opening->entry_count;
            int32_t kern = line_left_kern(engine, items, count, from,
                                          &opening_site);
            if (kern != 0) {
                struct hstex_node node = {
                    .kind = HSTEX_NODE_KERN,
                    .width = kern,
                    .value.kern = {.margin = 1U},
                };
                status = append_hbox_node(engine, &node, error, error_capacity);
            }
        }
        for (uint16_t item = 0U;
             status == 0 && item < opening->entry_count &&
             (size_t)opening->entry_start + opening->entry_count <=
                 engine->list_item_count;
             ++item) {
            status = append_hbox_item(
                engine, engine->list_items[opening->entry_start + item], error,
                error_capacity);
        }
        for (size_t index = from; status == 0 && index < to && index < count;
             ++index) {
            status = append_hbox_item(engine, items[index], error,
                                      error_capacity);
        }
        /* A line that ends at a discretionary keeps the node, emptied, and
           the text that goes before the break follows it; one that ends at a
           kern or at a formula's fence keeps that node with no width left.
           See docs/DECISIONS.md, what-a-line-keeps-of-its-break. */
        bool broken = false;
        /* A discretionary with something to put before the break brings that
           text into the line, so it stands in front of the protrusion kern;
           one with nothing goes behind it. */
        bool disc_after_kern = false;
        if (status == 0 && to < count) {
            uint32_t identifier = items[to];
            if (identifier != 0U && (size_t)identifier <= engine->node_count &&
                engine->nodes[identifier - 1U].kind ==
                    HSTEX_NODE_DISCRETIONARY) {
                broken = true;
                uint32_t pre_start =
                    engine->nodes[identifier - 1U].value.disc.pre_start;
                uint16_t pre_count =
                    engine->nodes[identifier - 1U].value.disc.pre_count;
                disc_after_kern = pre_count == 0U;
                if (!disc_after_kern) {
                    struct hstex_node emptied = {
                        .kind = HSTEX_NODE_DISCRETIONARY,
                    };
                    status = append_hbox_node(engine, &emptied, error,
                                              error_capacity);
                    for (uint16_t item = 0U;
                         status == 0 && item < pre_count &&
                         (size_t)pre_start + pre_count <=
                             engine->list_item_count;
                         ++item) {
                        status = append_hbox_item(
                            engine, engine->list_items[pre_start + item],
                            error, error_capacity);
                    }
                }
            }
        }
        /* The kern that lets the last character stick out goes in front of
           whatever glue trails the line, which on the last line is
           \parfillskip. */
        if (status == 0 && protruding) {
            int32_t kern = line_right_kern(engine, items, count, to);
            if (kern != 0) {
                size_t trailing = builder.count;
                while (trailing != 0U &&
                       engine->nodes[builder.node_identifiers[trailing - 1U] -
                                     1U]
                               .kind == HSTEX_NODE_GLUE) {
                    --trailing;
                }
                struct hstex_node node = {
                    .kind = HSTEX_NODE_KERN,
                    .width = kern,
                    .value.kern = {.margin = 2U},
                };
                uint32_t placed = 0U;
                status = store_node(engine, &node, &placed, error,
                                    error_capacity);
                if (status == 0) {
                    status = append_hbox_item(engine, placed, error,
                                              error_capacity);
                }
                if (status == 0 && trailing != builder.count - 1U) {
                    memmove(builder.node_identifiers + trailing + 1U,
                            builder.node_identifiers + trailing,
                            (builder.count - 1U - trailing) *
                                sizeof(*builder.node_identifiers));
                    builder.node_identifiers[trailing] = placed;
                }
            }
        }
        /* A line that ends at a kern, at a formula's fence, or at a
           discretionary with nothing to put before the break keeps that node
           with no width left, behind the protrusion kern. */
        if (status == 0 && disc_after_kern) {
            struct hstex_node emptied = {.kind = HSTEX_NODE_DISCRETIONARY};
            status = append_hbox_node(engine, &emptied, error, error_capacity);
        }
        if (status == 0 && to < count) {
            uint32_t identifier = items[to];
            const struct hstex_node *at =
                identifier != 0U && (size_t)identifier <= engine->node_count
                    ? &engine->nodes[identifier - 1U]
                    : NULL;
            if (at != NULL && (at->kind == HSTEX_NODE_KERN ||
                               at->kind == HSTEX_NODE_MATH ||
                               at->kind == HSTEX_NODE_PENALTY)) {
                struct hstex_node kept = *at;
                kept.width = 0;
                status = append_hbox_node(engine, &kept, error, error_capacity);
            }
        }
        if (status == 0) {
            status = emit_parameter_glue(engine, right, HSTEX_GLUE_RIGHT_SKIP,
                                         error, error_capacity);
        }
        /* A mark or an insertion does not stay in the line it was written
           in: it moves to the vertical list, behind the line's box. See
           docs/DECISIONS.md, marks and insertions. */
        uint32_t *migrated = NULL;
        size_t migrated_count = 0U;
        if (status == 0) {
            size_t kept = 0U;
            for (size_t item = 0U; item < builder.count; ++item) {
                uint32_t held = builder.node_identifiers[item];
                const struct hstex_node *at =
                    held != 0U && (size_t)held <= engine->node_count
                        ? &engine->nodes[held - 1U]
                        : NULL;
                if (at == NULL || (at->kind != HSTEX_NODE_MARK &&
                                   at->kind != HSTEX_NODE_INSERT &&
                                   at->kind != HSTEX_NODE_ADJUST)) {
                    builder.node_identifiers[kept++] = held;
                    continue;
                }
                /* A mark or an insertion moves itself; what a \\vadjust
                   moves is the material it holds, and the node it was
                   written as does not survive the move. */
                size_t moving = 1U;
                const uint32_t *contents = &held;
                if (at->kind == HSTEX_NODE_ADJUST) {
                    if ((size_t)at->value.list.node_start +
                            at->value.list.node_count >
                        engine->list_item_count) {
                        continue;
                    }
                    moving = at->value.list.node_count;
                    contents = engine->list_items + at->value.list.node_start;
                }
                if (moving == 0U) {
                    continue;
                }
                uint32_t *grown = realloc(
                    migrated, (migrated_count + moving) * sizeof(*migrated));
                if (grown == NULL) {
                    status = set_error(error, error_capacity,
                                       "mark migration allocation failed");
                    break;
                }
                migrated = grown;
                for (size_t move = 0U; move < moving; ++move) {
                    migrated[migrated_count++] = contents[move];
                }
            }
            if (status == 0) {
                builder.count = kept;
            }
        }
        struct hstex_box box = {0};
        if (status == 0) {
            /* A line of a paragraph is reported against the line the
               paragraph began on. */
            int32_t previous_pack = engine->pack_begin_line;
            engine->pack_begin_line = engine->paragraph_line;
            status = finalize_hbox(engine, &builder, true, false,
                                   line_width_for(engine, numbered), &box,
                                   error, error_capacity);
            engine->pack_begin_line = previous_pack;
        }
        free(builder.node_identifiers);
        engine->active_hbox_builder = previous;
        engine->mode = previous_mode;
        if (status != 0) {
            free(migrated);
            break;
        }
        if (out_last != NULL) {
            *out_last = box;
        }
        struct hstex_node line_node = {
            .kind = HSTEX_NODE_LIST,
            .width = box.width,
            .height = box.height,
            .depth = box.depth,
            .shift = line_shift_for(engine, numbered),
            .value.list = {
                .node_start = box.node_start,
                .node_count = box.node_count,
                .box_kind = box.kind,
                .glue = box.glue,
            },
        };
        status = append_vbox_node(engine, &line_node, error, error_capacity);
        /* What a \\vadjust moves goes onto the list as it stands. It is not a
           box the next one is set against: the reference measures the glue
           before the following line from the depth of the *line*, however
           deep the moved material is. See docs/DECISIONS.md,
           what-a-vadjust-leaves-behind. */
        int32_t depth_before_migration = engine->prev_depth;
        for (size_t item = 0U; status == 0 && item < migrated_count; ++item) {
            status = append_vbox_item(engine, migrated[item], error,
                                      error_capacity);
        }
        engine->prev_depth = depth_before_migration;
        free(migrated);
        if (status == 0 && line != lines) {
            int32_t penalty = interline;
            if (line == 1U) {
                penalty += club;
            }
            if (line + 1U == lines) {
                penalty += widow;
            }
            if (broken) {
                penalty +=
                    engine->integer_parameters[HSTEX_INTEGER_BROKEN_PENALTY];
            }
            if (penalty != 0) {
                struct hstex_node node = {
                    .kind = HSTEX_NODE_PENALTY,
                    .value.penalty = penalty,
                };
                status = append_vbox_node(engine, &node, error, error_capacity);
            }
        }
    }
    free(chain);
    return status;
}

/* The running width, stretch and shrink of the paragraph up to each node,
   which is what the breaker measures a line from. */
static int measure_break_totals(struct hstex_engine *engine,
                                struct hstex_break_state *state,
                                const uint32_t *items, size_t count,
                                char *error, size_t error_capacity)
{
    state->node_count = count;
    state->totals = calloc(count + 1U, sizeof(*state->totals));
    if (state->totals == NULL) {
        return set_error(error, error_capacity,
                         "break totals allocation failed");
    }
    state->shrink_error_at = SIZE_MAX;
    for (size_t index = 0U; index < count; ++index) {
        state->totals[index + 1U] = state->totals[index];
        uint32_t identifier = items[index];
        if (identifier == 0U || (size_t)identifier > engine->node_count) {
            continue;
        }
        const struct hstex_node *node = &engine->nodes[identifier - 1U];
        state->totals[index + 1U].width += packed_dimen(node->width);
        if (node->kind == HSTEX_NODE_GLUE) {
            uint8_t up = node->value.glue.stretch_order;
            if (up < 4U) {
                state->totals[index + 1U].stretch[up] +=
                    node->value.glue.stretch;
            }
            /* Taken as finite before the totals are made, so that what the
               passes weigh is what the line will hold. */
            if (node->value.glue.shrink_order != 0U &&
                node->value.glue.shrink != 0) {
                engine->nodes[identifier - 1U].value.glue.shrink_order = 0U;
                if (state->shrink_error_at == SIZE_MAX) {
                    state->shrink_error_at = index;
                }
                node = &engine->nodes[identifier - 1U];
            }
            if (node->value.glue.shrink_order == 0U) {
                state->totals[index + 1U].shrink += node->value.glue.shrink;
            }
        }
    }
    return 0;
}

/* The letters of one word, as the hyphenation pass reads them off the
   paragraph's nodes. */
enum { HSTEX_MAX_HYPHENATED_WORD = 63 };

struct hstex_word {
    uint8_t letters[HSTEX_MAX_HYPHENATED_WORD];
    /* Where each letter's node sits in the paragraph. A ligature stands for
       several letters, so several of these may name the same node. */
    size_t positions[HSTEX_MAX_HYPHENATED_WORD];
    size_t count;
    uint32_t font;
    /* One past the last letter's node. */
    size_t end;
};

/* Takes the letters a node stands for: one for a character, and whatever a
   ligature was made of. Returns false when the node is not part of a word.
   See docs/DECISIONS.md, hyphenation. */
static bool take_word_letters(struct hstex_engine *engine,
                              const struct hstex_node *node, uint32_t font,
                              struct hstex_word *word, size_t index)
{
    if (node->value.character.font != font) {
        return false;
    }
    if (node->kind == HSTEX_NODE_CHARACTER) {
        uint32_t code = node->value.character.character;
        if (code >= 256U || engine->code_tables[1][code] == 0 ||
            word->count >= (size_t)HSTEX_MAX_HYPHENATED_WORD) {
            return false;
        }
        word->letters[word->count] = (uint8_t)code;
        word->positions[word->count] = index;
        ++word->count;
        return true;
    }
    uint8_t originals = node->value.character.original_count;
    /* A ligature made of nothing -- the character an operation puts between
       two it keeps -- is part of the word and contributes no letter to it,
       the way the reference passes over one whose list of originals is
       empty. */
    if (originals == 0U) {
        return true;
    }
    if (word->count + originals > (size_t)HSTEX_MAX_HYPHENATED_WORD) {
        return false;
    }
    for (uint8_t item = 0U; item < originals; ++item) {
        uint8_t code = node->value.character.originals[item];
        if (engine->code_tables[1][code] == 0) {
            return false;
        }
    }
    for (uint8_t item = 0U; item < originals; ++item) {
        word->letters[word->count] = node->value.character.originals[item];
        word->positions[word->count] = index;
        ++word->count;
    }
    return true;
}

/* Reads the word that begins somewhere at or after `from`, the way the
   reference looks for one: leading characters that are not letters are
   passed over, and the word itself is characters of one font whose \lccode
   is not zero, with the font's own kerns allowed between them and ligatures
   standing for the letters they were made of. Returns false when there is no
   word to hyphenate here. See docs/DECISIONS.md, hyphenation. */
static bool read_hyphenatable_word(struct hstex_engine *engine,
                                   const uint32_t *items, size_t count,
                                   size_t from, struct hstex_word *word)
{
    memset(word, 0, sizeof(*word));
    size_t index = from;
    uint32_t font = 0U;
    for (;;) {
        if (index >= count) {
            return false;
        }
        uint32_t identifier = items[index];
        if (identifier == 0U || (size_t)identifier > engine->node_count) {
            return false;
        }
        const struct hstex_node *node = &engine->nodes[identifier - 1U];
        if (node->kind == HSTEX_NODE_CHARACTER ||
            node->kind == HSTEX_NODE_LIGATURE) {
            uint32_t code = node->kind == HSTEX_NODE_CHARACTER
                                ? node->value.character.character
                                : (node->value.character.original_count != 0U
                                       ? node->value.character.originals[0]
                                       : 256U);
            int32_t lower = code < 256U ? engine->code_tables[1][code] : 0;
            if (lower != 0) {
                /* A word that starts with a capital is only hyphenated when
                   \uchyph says so. */
                if (lower != (int32_t)code &&
                    engine->integer_parameters[HSTEX_INTEGER_UC_HYPH] <= 0) {
                    return false;
                }
                font = node->value.character.font;
                break;
            }
        } else if (node->kind == HSTEX_NODE_KERN) {
            if (node->explicit_kern) {
                return false;
            }
        } else if (node->kind == HSTEX_NODE_WHATSIT) {
            /* A \setlanguage passed on the way to the word says what that
               word is hyphenated by. The reference reads these here, while
               it is looking for the word, which is why one standing between
               the glue and the first letter still counts. See
               docs/DECISIONS.md, hyphenation-minima. */
            if (node->value.whatsit.kind ==
                (uint8_t)HSTEX_WHATSIT_LANGUAGE) {
                int32_t chosen = node->value.whatsit.number;
                if (chosen < 0 || (size_t)chosen >= engine->count_capacity) {
                    chosen = 0;
                }
                engine->hyphenating_language = chosen;
                engine->hyphenating_left_min = node->value.whatsit.stream;
                engine->hyphenating_right_min = node->value.whatsit.action;
            }
        } else {
            return false;
        }
        ++index;
    }
    const struct hstex_font *metrics = font_by_identifier(engine, font);
    if (metrics == NULL || metrics->hyphen_character < 0 ||
        metrics->hyphen_character > 255) {
        return false;
    }
    word->font = font;
    while (index < count) {
        uint32_t identifier = items[index];
        if (identifier == 0U || (size_t)identifier > engine->node_count) {
            break;
        }
        const struct hstex_node *node = &engine->nodes[identifier - 1U];
        if (node->kind == HSTEX_NODE_CHARACTER ||
            node->kind == HSTEX_NODE_LIGATURE) {
            if (!take_word_letters(engine, node, font, word, index)) {
                break;
            }
            word->end = index + 1U;
        } else if (node->kind == HSTEX_NODE_KERN && !node->explicit_kern) {
            /* A kern the font asked for stays inside the word. */
        } else {
            break;
        }
        ++index;
    }
    if (word->count < 2U) {
        return false;
    }
    /* Nothing but ligatures, the font's own kerns and other characters may
       follow a word that is going to be hyphenated; a box, a rule, a formula
       or a discretionary means this is not a word to hyphenate at all. */
    for (size_t after = word->end; after < count; ++after) {
        uint32_t identifier = items[after];
        if (identifier == 0U || (size_t)identifier > engine->node_count) {
            break;
        }
        const struct hstex_node *node = &engine->nodes[identifier - 1U];
        if (node->kind == HSTEX_NODE_CHARACTER ||
            node->kind == HSTEX_NODE_LIGATURE) {
            continue;
        }
        if (node->kind == HSTEX_NODE_KERN) {
            if (node->explicit_kern) {
                break;
            }
            continue;
        }
        /* WHAT MAY STAND BEHIND A WORD: glue, a penalty, a whatsit, and
           the three that migrate out of a line once it is packed -- an
           insertion, a \vadjust and a \mark. Each of them ends the word
           and lets it be hyphenated. */
        if (node->kind == HSTEX_NODE_GLUE ||
            node->kind == HSTEX_NODE_PENALTY ||
            node->kind == HSTEX_NODE_WHATSIT ||
            node->kind == HSTEX_NODE_INSERT ||
            node->kind == HSTEX_NODE_ADJUST ||
            node->kind == HSTEX_NODE_MARK) {
            break;
        }
        /* A discretionary after the word -- the one an explicit hyphen
           leaves behind, for instance -- means this is not a word to
           hyphenate at all. */
        return false;
    }
    return true;
}

/* The node a hyphen makes in the font the word is set in. */
/* How many of a word's letters one node of the list stands for: a character
   stands for itself, a ligature for the letters it was made of, and a kern
   for none. */
static size_t letters_a_node_stands_for(const struct hstex_engine *engine,
                                        uint32_t identifier)
{
    if (identifier == 0U || (size_t)identifier > engine->node_count) {
        return 0U;
    }
    const struct hstex_node *node = &engine->nodes[identifier - 1U];
    if (node->kind == HSTEX_NODE_CHARACTER) {
        return 1U;
    }
    if (node->kind != HSTEX_NODE_LIGATURE) {
        return 0U;
    }
    return node->value.character.original_count == 0U
               ? 1U
               : (size_t)node->value.character.original_count;
}

static bool node_is_a_kern(const struct hstex_engine *engine,
                           uint32_t identifier)
{
    return identifier != 0U && (size_t)identifier <= engine->node_count &&
           engine->nodes[identifier - 1U].kind == HSTEX_NODE_KERN;
}

static int make_hyphen_node(struct hstex_engine *engine, uint32_t font,
                            uint32_t *identifier, char *error,
                            size_t error_capacity)
{
    *identifier = 0U;
    const struct hstex_font *metrics = font_by_identifier(engine, font);
    if (metrics == NULL || metrics->characters == NULL ||
        metrics->hyphen_character < 0 || metrics->hyphen_character > 255) {
        return 0;
    }
    if (metrics->characters[metrics->hyphen_character].tag < 0) {
        /* A HYPHEN THE FONT HAS NOT GOT is named where \tracinglostchars
           asks, as any other missing character is, and the word is broken
           without one. See docs/DECISIONS.md, missing-characters.

           WHERE it is named is the reference's pass walking the paragraph
           and hyphenating each word as it reaches it, so the line falls
           between two of \tracingparagraphs' own. This engine hyphenates
           the paragraph before the pass walks it, which would put every such
           line in front of the whole trace, so while a trace is being drawn
           the warning is kept until the walk reaches the word. */
        if (engine->hyphenating_defers &&
            engine->integer_parameters[HSTEX_INTEGER_TRACING_PARAGRAPHS] > 0 &&
            engine->integer_parameters[HSTEX_INTEGER_TRACING_LOST_CHARS] > 0) {
            if (engine->lost_character_count ==
                engine->lost_character_capacity) {
                size_t capacity = engine->lost_character_capacity == 0U
                                      ? 8U
                                      : engine->lost_character_capacity * 2U;
                void *room =
                    realloc(engine->lost_characters,
                            capacity * sizeof(*engine->lost_characters));
                if (room == NULL) {
                    return set_error(error, error_capacity,
                                     "lost-character list allocation failed");
                }
                engine->lost_characters = room;
                engine->lost_character_capacity = capacity;
            }
            struct hstex_lost_character kept = {
                .at = engine->hyphenating_at,
                .font = font,
                .code = (uint8_t)metrics->hyphen_character,
            };
            engine->lost_characters[engine->lost_character_count++] = kept;
            return 0;
        }
        char_warning(engine, metrics,
                     (uint8_t)metrics->hyphen_character);
        return 0;
    }
    const struct hstex_char_metric *metric =
        &metrics->characters[metrics->hyphen_character];
    struct hstex_node node = {
        .kind = HSTEX_NODE_CHARACTER,
        .width = metric->width,
        .height = metric->height,
        .depth = metric->depth,
        .value.character = {.font = font,
                            .character =
                                (uint32_t)metrics->hyphen_character},
    };
    return store_node(engine, &node, identifier, error, error_capacity);
}

static int reserve_hyphenated_items(uint32_t **items, size_t *capacity,
                                    size_t required, char *error,
                                    size_t error_capacity)
{
    if (required <= *capacity) {
        return 0;
    }
    size_t next = *capacity == 0U ? 32U : *capacity;
    while (next < required) {
        next *= 2U;
    }
    uint32_t *grown = realloc(*items, next * sizeof(**items));
    if (grown == NULL) {
        return set_error(error, error_capacity,
                         "hyphenation list allocation failed");
    }
    *items = grown;
    *capacity = next;
    return 0;
}

/* Where a word being set again is written to. */
struct reconstitution {
    struct hstex_engine *engine;
    const struct hstex_font *metrics;
    uint32_t font;
    uint32_t *identifiers;
    size_t capacity;
    size_t *written;
};

static int lig_emit_reconstituted(void *context,
                                  const struct hstex_lig_item *item,
                                  bool is_kern, int32_t kern, char *error,
                                  size_t error_capacity)
{
    struct reconstitution *place = context;
    struct hstex_node node = {0};
    if (!is_kern && item->is_boundary) {
        return 0;
    }
    if (is_kern) {
        node.kind = HSTEX_NODE_KERN;
        node.width = kern;
    } else {
        uint8_t code = item->character;
        if (place->metrics->characters[code].tag < 0) {
            return 0;
        }
        const struct hstex_char_metric *metric =
            &place->metrics->characters[code];
        node.kind = item->is_ligature ? HSTEX_NODE_LIGATURE
                                      : HSTEX_NODE_CHARACTER;
        node.width = metric->width;
        node.height = metric->height;
        node.depth = metric->depth;
        node.value.character.font = place->font;
        node.value.character.character = code;
        if (item->is_ligature) {
            node.value.character.original_count = item->original_count;
            memcpy(node.value.character.originals, item->originals,
                   sizeof(node.value.character.originals));
            /* A ligature the boundary took part in is written with `|' on
               the side it stood, and one set again has to say so too or it
               will not answer to the one already in the list. */
            if (place->engine->lig_left_hit) {
                node.value.character.boundary |= 2U;
                place->engine->lig_left_hit = false;
            }
            if (place->engine->lig_right_hit &&
                place->engine->lig_last_of_word) {
                node.value.character.boundary |= 1U;
                place->engine->lig_right_hit = false;
            }
        }
    }
    if (*place->written == place->capacity) {
        return set_error(error, error_capacity,
                         "a word set again does not fit");
    }
    if (store_node(place->engine, &node, &place->identifiers[*place->written],
                   error, error_capacity) != 0) {
        return -1;
    }
    ++*place->written;
    return 0;
}

/* Runs the font's ligature and kern program over a run of characters and
   leaves the nodes it makes in `identifiers`. This is how the two halves of
   a word are set again when the break falls inside a ligature; see
   docs/DECISIONS.md, breaking-inside-a-ligature. */
/* A word is set again from what stands in FRONT of its first letter, where
   that is a character or a ligature of the same font: the reference takes
   that node into the run it rebuilds, and what the node was made of is what
   the rebuilt one starts from. See docs/DECISIONS.md, what-a-word-is-set-
   again-from. */
static int reconstitute_seeded(struct hstex_engine *engine, uint32_t font,
                               const struct hstex_lig_item *seed,
                               const uint8_t *characters, size_t count,
                               bool from_left_boundary,
                               bool to_right_boundary,
                               uint32_t *identifiers, size_t capacity,
                               size_t *written, char *error,
                               size_t error_capacity);

static int reconstitute_characters(struct hstex_engine *engine, uint32_t font,
                                   const uint8_t *characters, size_t count,
                                   bool from_left_boundary,
                                   bool to_right_boundary,
                                   uint32_t *identifiers, size_t capacity,
                                   size_t *written, char *error,
                                   size_t error_capacity)
{
    return reconstitute_seeded(engine, font, NULL, characters, count,
                               from_left_boundary, to_right_boundary,
                               identifiers, capacity, written, error,
                               error_capacity);
}

static int reconstitute_seeded(struct hstex_engine *engine, uint32_t font,
                               const struct hstex_lig_item *seed,
                               const uint8_t *characters, size_t count,
                               bool from_left_boundary,
                               bool to_right_boundary,
                               uint32_t *identifiers, size_t capacity,
                               size_t *written, char *error,
                               size_t error_capacity)
{
    *written = 0U;
    const struct hstex_font *metrics = font_by_identifier(engine, font);
    if (metrics == NULL || metrics->characters == NULL) {
        return set_error(error, error_capacity,
                         "a word cannot be set again without its font");
    }
    struct reconstitution place = {
        .engine = engine,
        .metrics = metrics,
        .font = font,
        .identifiers = identifiers,
        .capacity = capacity,
        .written = written,
    };
    struct hstex_lig_item work[HSTEX_LIG_WORK];
    size_t work_count = 0U;
    /* Setting a word again must not disturb the marks the list being built
       is keeping. */
    bool left_hit = engine->lig_left_hit;
    bool right_hit = engine->lig_right_hit;
    bool last_of_word = engine->lig_last_of_word;
    engine->lig_left_hit = false;
    engine->lig_right_hit = false;
    /* What stands beyond a word's left end takes part in the program before
       its first character does, exactly as it does where the word was first
       set. A line that starts after a break meets it too. See
       docs/DECISIONS.md, boundary-characters. */
    if (seed != NULL) {
        /* What stood in front of the word takes the place of the boundary:
           the run starts from it, already made -- and where the boundary had
           taken part in making it, the node it becomes says so again. */
        work[work_count++] = *seed;
        engine->lig_left_hit = (seed->boundary & 2U) != 0U;
    } else if (from_left_boundary && metrics->boundary_label >= 0) {
        lig_item_plain(&work[work_count], 0U, false);
        work[work_count].is_boundary = true;
        ++work_count;
    }
    for (size_t index = 0U; index < count; ++index) {
        if (work_count == HSTEX_LIG_WORK) {
            engine->lig_left_hit = left_hit;
            engine->lig_right_hit = right_hit;
            engine->lig_last_of_word = last_of_word;
            return set_error(error, error_capacity,
                             "a word set again does not fit");
        }
        lig_item_plain(&work[work_count++], characters[index], false);
        if (lig_advance(engine, metrics, work, &work_count,
                        lig_emit_reconstituted, &place, error,
                        error_capacity) != 0) {
            engine->lig_left_hit = left_hit;
            engine->lig_right_hit = right_hit;
            engine->lig_last_of_word = last_of_word;
            return -1;
        }
    }
    int status = 0;
    /* The word ends, so the character beyond its right end takes part in the
       program one last time, exactly as it does where the word was first
       set. See docs/DECISIONS.md, boundary-characters. */
    if (to_right_boundary && metrics->boundary_character >= 0 &&
        metrics->boundary_character <= 255) {
        if (work_count == HSTEX_LIG_WORK) {
            engine->lig_left_hit = left_hit;
            engine->lig_right_hit = right_hit;
            engine->lig_last_of_word = last_of_word;
            return set_error(error, error_capacity,
                             "a word set again does not fit");
        }
        lig_item_plain(&work[work_count], (uint8_t)metrics->boundary_character,
                       false);
        work[work_count].is_boundary = true;
        ++work_count;
        if (lig_advance(engine, metrics, work, &work_count,
                        lig_emit_reconstituted, &place, error,
                        error_capacity) != 0) {
            status = -1;
        }
    }
    /* Whatever is still held simply goes into the list. */
    for (size_t item = 0U; status == 0 && item < work_count; ++item) {
        engine->lig_last_of_word =
            to_right_boundary && lig_nothing_after(work, work_count, item);
        if (lig_emit_reconstituted(&place, &work[item], false, 0, error,
                                   error_capacity) != 0) {
            status = -1;
        }
    }
    engine->lig_left_hit = left_hit;
    engine->lig_right_hit = right_hit;
    engine->lig_last_of_word = last_of_word;
    return status;
}


/* WHETHER A WORD SET AGAIN MEETS THE BOUNDARY BEYOND ITS RIGHT END. The
   reference looks at what the word was made of the first time: only where a
   node the boundary took part in stands at the word's end does the boundary
   take part again. A word whose boundary was cancelled -- `11\noboundary'
   -- ends in a plain character and stays without one. See
   docs/DECISIONS.md, what-follows-a-break-in-a-word. */
static bool word_meets_right_boundary(const struct hstex_engine *engine,
                                      const uint32_t *items, size_t end)
{
    if (end == 0U) {
        return false;
    }
    uint32_t last = items[end - 1U];
    if (last == 0U || (size_t)last > engine->node_count) {
        return false;
    }
    const struct hstex_node *node = &engine->nodes[last - 1U];
    return node->kind == HSTEX_NODE_LIGATURE &&
           node->value.character.boundary != 0U;
}

/* And whether it meets the boundary beyond its LEFT end, which is settled
   the same way: only where the word's first node is a ligature the boundary
   took part in. A word begun after \noboundary starts with a plain
   character and is set again without one. */
static bool word_meets_left_boundary(const struct hstex_engine *engine,
                                     const uint32_t *items, size_t count,
                                     size_t word_start)
{
    if (word_start >= count) {
        return false;
    }
    uint32_t first = items[word_start];
    if (first == 0U || (size_t)first > engine->node_count) {
        return false;
    }
    const struct hstex_node *node = &engine->nodes[first - 1U];
    return node->kind == HSTEX_NODE_LIGATURE &&
           (node->value.character.boundary & 2U) != 0U;
}

/* HOW MANY OF A WORD'S LETTERS ONE NODE STANDS FOR. A character is one, a
   ligature is however many letters it was made from, and a kern -- or a
   character the font's own ligature program put between two letters, which
   is made from none -- is none at all. Used to tell where a letter BEGINS in
   a run, which is what the two branches of a break fall back into step on. */
static size_t letters_of_node(const struct hstex_engine *engine,
                              uint32_t identifier)
{
    if (identifier == 0U || (size_t)identifier > engine->node_count) {
        return 0U;
    }
    const struct hstex_node *node = &engine->nodes[identifier - 1U];
    if (node->kind == HSTEX_NODE_CHARACTER) {
        return 1U;
    }
    if (node->kind == HSTEX_NODE_LIGATURE) {
        return node->value.character.original_count;
    }
    return 0U;
}

/* Two nodes stand for the same thing when they would be set the same way. */
static bool set_the_same_way(const struct hstex_engine *engine, uint32_t left,
                             uint32_t right)
{
    if (left == 0U || right == 0U || (size_t)left > engine->node_count ||
        (size_t)right > engine->node_count) {
        return false;
    }
    const struct hstex_node *one = &engine->nodes[left - 1U];
    const struct hstex_node *other = &engine->nodes[right - 1U];
    if (one->kind != other->kind || one->width != other->width) {
        return false;
    }
    if (one->kind == HSTEX_NODE_KERN) {
        return true;
    }
    if (one->kind != HSTEX_NODE_CHARACTER &&
        one->kind != HSTEX_NODE_LIGATURE) {
        return false;
    }
    if (one->value.character.font != other->value.character.font ||
        one->value.character.character != other->value.character.character ||
        one->value.character.boundary != other->value.character.boundary ||
        one->value.character.original_count !=
            other->value.character.original_count) {
        return false;
    }
    return memcmp(one->value.character.originals,
                  other->value.character.originals,
                  one->value.character.original_count) == 0;
}

/* WHAT A \tabskip COMES TO once a row's glue setting is applied to it, which
   is what an entry spanning past it is measured against. See
   docs/DECISIONS.md, what-an-entry-that-spans-is-set-to. */
static int32_t tabskip_set_width(struct hstex_glue skip,
                                 struct hstex_glue_set set)
{
    int32_t width = skip.width;
    if (set.sign == (uint8_t)HSTEX_GLUE_SIGN_NORMAL || set.total == 0) {
        return width;
    }
    double ratio = (double)set.needed / (double)set.total;
    if (set.sign == (uint8_t)HSTEX_GLUE_SIGN_STRETCHING) {
        if (skip.stretch_order == set.order) {
            width += rounded_amount(ratio * (double)skip.stretch);
        }
    } else if (skip.shrink_order == set.order) {
        width -= rounded_amount(ratio * (double)skip.shrink);
    }
    return width;
}

/* A WORD IS SET AGAIN FROM ITS LETTERS BEFORE IT IS BROKEN. The reference
   rebuilds the whole run it is about to break, so what the two branches of a
   break are developed against is the run its letters make rather than the
   nodes the setting happened to leave -- which differ where the setting was
   broken part-way, by a character the font has not got standing among them.
   The paragraph's list is handed back with the run replaced. Where the
   rebuilt run is what was already there, nothing is done at all.
   See docs/DECISIONS.md, a-word-set-again-before-it-is-broken. */
static int rebuild_word_before_breaking(struct hstex_engine *engine,
                                        const uint32_t **items, size_t *count,
                                        uint32_t **owned,
                                        const struct hstex_word *word,
                                        size_t word_start, bool meets_left,
                                        char *error, size_t error_capacity)
{
    if (word->count == 0U || word->end <= word_start) {
        return 0;
    }
    /* What stands in front of the word's first letter is taken into the run
       where it is a character or a ligature of the word's own font. */
    struct hstex_lig_item seed_item;
    bool seeded = false;
    if (word_start != 0U) {
        uint32_t ahead_of = (*items)[word_start - 1U];
        if (ahead_of != 0U && (size_t)ahead_of <= engine->node_count) {
            const struct hstex_node *front = &engine->nodes[ahead_of - 1U];
            if ((front->kind == HSTEX_NODE_CHARACTER ||
                 front->kind == HSTEX_NODE_LIGATURE) &&
                front->value.character.font == word->font) {
                memset(&seed_item, 0, sizeof(seed_item));
                seed_item.character =
                    (uint8_t)front->value.character.character;
                seed_item.is_ligature = front->kind == HSTEX_NODE_LIGATURE;
                seed_item.original_count =
                    front->value.character.original_count;
                seed_item.boundary = front->value.character.boundary;
                memcpy(seed_item.originals, front->value.character.originals,
                       sizeof(seed_item.originals));
                seeded = true;
            }
        }
    }
    size_t base = word_start - (seeded ? 1U : 0U);
    size_t room = (word->end - base) * 4U + (size_t)word->count * 8U + 64U;
    uint32_t *rebuilt = calloc(room, sizeof(*rebuilt));
    if (rebuilt == NULL) {
        return set_error(error, error_capacity,
                         "hyphenation rebuild allocation failed");
    }
    size_t made = 0U;
    if (reconstitute_seeded(engine, word->font, seeded ? &seed_item : NULL,
                            word->letters, word->count,
                            !seeded && meets_left,
                            word_meets_right_boundary(engine, *items,
                                                      word->end),
                            rebuilt, room, &made, error,
                            error_capacity) != 0) {
        free(rebuilt);
        return -1;
    }
    bool same = made == word->end - base;
    for (size_t at = 0U; same && at < made; ++at) {
        same = set_the_same_way(engine, rebuilt[at], (*items)[base + at]);
    }
    if (same) {
        free(rebuilt);
        return 0;
    }
    size_t tail = *count - word->end;
    size_t total = base + made + tail;
    uint32_t *next = calloc(total == 0U ? 1U : total, sizeof(*next));
    if (next == NULL) {
        free(rebuilt);
        return set_error(error, error_capacity,
                         "hyphenation rebuild allocation failed");
    }
    memcpy(next, *items, base * sizeof(*next));
    memcpy(next + base, rebuilt, made * sizeof(*next));
    memcpy(next + base + made, *items + word->end, tail * sizeof(*next));
    free(rebuilt);
    free(*owned);
    *owned = next;
    *items = next;
    *count = total;
    return 0;
}

/* Puts a discretionary wherever the patterns allow a break in a word, and
   returns the paragraph's nodes again with those discretionaries in them.
   See docs/DECISIONS.md, hyphenation. */
static int hyphenate_paragraph(struct hstex_engine *engine,
                               const uint32_t *items, size_t count,
                               uint32_t **out_items, size_t *out_count,
                               char *error, size_t error_capacity)
{
    *out_items = NULL;
    *out_count = 0U;
    /* The reference builds its trie here, the first time a paragraph asks
       to be hyphenated, and will not take a pattern afterwards. */
    engine->hyphen_trie_settled = true;
    int32_t language = engine->paragraph_language;
    if (language < 0 || (size_t)language >= engine->count_capacity) {
        language = 0;
    }
    engine->hyphenating_language = language;
    engine->hyphenating_left_min = engine->paragraph_left_min;
    engine->hyphenating_right_min = engine->paragraph_right_min;
    size_t capacity = count + 16U;
    uint32_t *result = calloc(capacity, sizeof(*result));
    if (result == NULL) {
        return set_error(error, error_capacity,
                         "hyphenation list allocation failed");
    }
    size_t written = 0U;
    size_t index = 0U;
    int status = 0;
    engine->hyphenating_defers = true;
    engine->hyphenating_at = 0U;
    /* The list the walk reads, which is the one handed in until a word has
       to be set again. */
    uint32_t *owned = NULL;
    /* Nothing between the two ends of a formula is hyphenated; see
       docs/DECISIONS.md, no-hyphens-inside-a-formula. */
    bool breaking = true;
    while (status == 0 && index < count) {
        if (reserve_hyphenated_items(&result, &capacity, written + 1U, error,
                                     error_capacity) != 0) {
            status = -1;
            break;
        }
        uint32_t identifier = items[index];
        result[written++] = identifier;
        if (identifier != 0U && (size_t)identifier <= engine->node_count &&
            engine->nodes[identifier - 1U].kind == HSTEX_NODE_MATH) {
            breaking = engine->nodes[identifier - 1U].value.math.after;
        }
        /* A \setlanguage passed on the way says what the words after it are
           hyphenated by. */
        if (identifier != 0U && (size_t)identifier <= engine->node_count &&
            engine->nodes[identifier - 1U].kind == HSTEX_NODE_WHATSIT &&
            engine->nodes[identifier - 1U].value.whatsit.kind ==
                (uint8_t)HSTEX_WHATSIT_LANGUAGE) {
            const struct hstex_node *at = &engine->nodes[identifier - 1U];
            language = at->value.whatsit.number;
            if (language < 0 || (size_t)language >= engine->count_capacity) {
                language = 0;
            }
            engine->hyphenating_language = language;
            engine->hyphenating_left_min = at->value.whatsit.stream;
            engine->hyphenating_right_min = at->value.whatsit.action;
        }
        if (!breaking || identifier == 0U ||
            (size_t)identifier > engine->node_count ||
            engine->nodes[identifier - 1U].kind != HSTEX_NODE_GLUE) {
            ++index;
            continue;
        }
        /* The reference looks for a word only after glue, which is why the
           first word of a paragraph is never hyphenated. */
        struct hstex_word word;
        ++index;
        if (!read_hyphenatable_word(engine, items, count, index, &word)) {
            continue;
        }
        uint8_t breaks[HSTEX_MAX_HYPHENATED_WORD + 1U] = {0};
        if (hstex_engine_hyphenate_word(engine, engine->hyphenating_language,
                                        word.letters,
                                        word.count, breaks, sizeof(breaks),
                                        error, error_capacity) != 0) {
            status = -1;
            break;
        }
        size_t letter = 0U;
        size_t word_start = word.count != 0U ? word.positions[0] : index;
        /* A WORD SET AGAIN WITHOUT A LEFT BOUNDARY BEGINS WITH ITS FIRST TWO
           LETTERS IN ONE RUN, so a break between them is not one that can be
           taken -- unless those two are the whole word, where the run reaches
           the word's end and the break stands after all. Measured against the
           reference with trip's font, whose `1' joins to whatever follows:
           `\noboundary111' takes only the later break where `111' takes both,
           and `\noboundary11' takes its one break. See docs/DECISIONS.md,
           where-a-rebuilt-run-begins. */
        const struct hstex_font *word_metrics =
            font_by_identifier(engine, word.font);
        bool meets_left =
            word_metrics == NULL || word_metrics->boundary_label < 0 ||
            word_meets_left_boundary(engine, items, count, word_start);
        /* THE WORD IS SET AGAIN FROM ITS LETTERS BEFORE ANY BREAK IS TAKEN.
           The reference rebuilds the run it is going to break rather than
           breaking the nodes that are already there, so a run the setting
           had broken -- a character the font has not got standing in the
           middle of it, say -- is joined again first. Where the rebuilt run
           is what was there, which is every word but a handful, nothing
           moves. See docs/DECISIONS.md, a-word-set-again-before-it-is-
           broken. */
        bool wanted_anywhere = false;
        for (size_t at = 1U; at < word.count; ++at) {
            if (breaks[at] != 0U) {
                wanted_anywhere = true;
                break;
            }
        }
        if (wanted_anywhere &&
            rebuild_word_before_breaking(engine, &items, &count, &owned, &word,
                                         word_start, meets_left, error,
                                         error_capacity) != 0) {
            status = -1;
            break;
        }
        if (wanted_anywhere) {
            /* The word stands in other nodes now, so where its letters are
               is asked again. */
            if (!read_hyphenatable_word(engine, items, count, index, &word)) {
                continue;
            }
            word_start = word.count != 0U ? word.positions[0] : index;
            meets_left =
                word_metrics == NULL || word_metrics->boundary_label < 0 ||
                word_meets_left_boundary(engine, items, count, word_start);
        }
        /* Where the run the last discretionary made reaches to. A break
           inside it is not one that can be taken: the reference develops
           both branches of a break until they fall back into step, and
           whatever hyphen points it passed on the way are gone. */
        size_t settled_to = 0U;
        /* WHERE THE LAST SPANNED BREAK'S RUN ENDED, as an item index. The
           next break's run begins there and not at its own letter: the
           reference lays the discretionaries end to end over the word's
           nodes, so what one replaces the next takes up from. */
        size_t settled_item = 0U;
        bool settled_item_set = false;
        /* Where this word's own output begins, which is where the trace has
           to have reached before what hyphenating it noticed may be let out;
           see release_lost_characters. */
        engine->hyphenating_at = written;
        while (status == 0 && index < word.end) {
            /* How many of the word's letters this one node stands for; a
               break inside a ligature is not one HSTeX can take. */
            size_t here = 0U;
            while (letter + here < word.count &&
                   word.positions[letter + here] == index) {
                ++here;
            }
            bool blocked = index < settled_to;
            bool wanted =
                !blocked && here != 0U && letter >= 1U && breaks[letter] != 0U;
            if (wanted && letter == 1U && word.count > 2U && !meets_left) {
                wanted = false;
                /* THE RUN THOSE TWO LETTERS MAKE IS STILL A RUN, and the next
                   break takes up past it. A break that cannot be taken leaves
                   no discretionary behind, but it does leave the development
                   standing at the letter after it -- so the next break's run
                   begins there rather than at its own letter, it replaces
                   only what stands from there, and the letter in front of it
                   is already laid down, which leaves the hyphen on its own in
                   front of the break. See
                   tests/trip/probes/where-a-run-a-lost-break-made-reaches-to.tex. */
                if (letter + 1U < word.count) {
                    settled_item = word.positions[letter + 1U];
                    settled_item_set = true;
                }
            }
            size_t previous = wanted ? word.positions[letter - 1U] : 0U;
            bool adjacent = wanted && previous + 1U == index;
            /* A kern the font put between the two letters is not there when
               the line breaks between them, so the letter in front of the
               break is set again as part of what goes before it. */
            bool kerned = wanted && previous + 2U == index &&
                          items[previous + 1U] != 0U &&
                          (size_t)items[previous + 1U] <= engine->node_count &&
                          engine->nodes[items[previous + 1U] - 1U].kind ==
                              HSTEX_NODE_KERN;
            /* Where the two letters are neither next to one another nor
               parted by a single kern, a whole run of the font's own
               characters stands between them -- trip's font puts one between
               every pair. The discretionary replaces that run, and the run
               ends where the text after the break falls back into step with
               what is already there. See docs/DECISIONS.md,
               where-a-rebuilt-run-begins. */
            bool spanned = wanted && !adjacent && !kerned &&
                           index > previous + 1U;
            if (spanned) {
                /* WHAT A WORD IS SET AGAIN FROM: where the node standing in
                   front of the word's first letter is a character or a
                   ligature of the word's own font, the reference takes it
                   into the run it rebuilds, starts the ligature program from
                   what that node was made of, and puts no left boundary in
                   front of it. */
                struct hstex_lig_item seed_item;
                bool seeded = false;
                if (previous == word_start && word_start != 0U) {
                    uint32_t ahead_of = items[word_start - 1U];
                    if (ahead_of != 0U &&
                        (size_t)ahead_of <= engine->node_count) {
                        const struct hstex_node *front =
                            &engine->nodes[ahead_of - 1U];
                        if ((front->kind == HSTEX_NODE_CHARACTER ||
                             front->kind == HSTEX_NODE_LIGATURE) &&
                            front->value.character.font == word.font) {
                            memset(&seed_item, 0, sizeof(seed_item));
                            seed_item.character =
                                (uint8_t)front->value.character.character;
                            seed_item.is_ligature =
                                front->kind == HSTEX_NODE_LIGATURE;
                            seed_item.original_count =
                                front->value.character.original_count;
                            seed_item.boundary =
                                front->value.character.boundary;
                            memcpy(seed_item.originals,
                                   front->value.character.originals,
                                   sizeof(seed_item.originals));
                            seeded = true;
                        }
                    }
                }
                size_t base = word_start - (seeded ? 1U : 0U);
                size_t whole = word.end - base;
                size_t room = whole * 4U + (size_t)word.count * 8U + 64U;
                uint32_t *ahead = calloc(room, sizeof(*ahead));
                uint32_t *behind = calloc(room, sizeof(*behind));
                uint8_t taken[HSTEX_MAX_HYPHENATED_WORD + 2U];
                const struct hstex_font *metrics =
                    font_by_identifier(engine, word.font);
                if (ahead == NULL || behind == NULL || metrics == NULL ||
                    metrics->hyphen_character < 0) {
                    free(ahead);
                    free(behind);
                    status = set_error(error, error_capacity,
                                       "a word cannot be broken here");
                    break;
                }
                /* What goes before the break: the letters the node in front
                   of it stands for, and the hyphen. */
                size_t first = letter;
                while (first > 0U && word.positions[first - 1U] == previous) {
                    --first;
                }
                size_t count_before = 0U;
                /* THE LETTER IN FRONT OF THE BREAK IS ONLY SET AGAIN WHILE IT
                   IS STILL THE ENGINE'S TO SET. One an earlier discretionary
                   has already taken into its own run is gone, and what is
                   left in front of this break is the hyphen standing on its
                   own -- or nothing at all, where the font has not got it.
                   The reference draws trip's second break as `\trip -' and
                   not as the letter and the hyphen together. */
                bool fresh = !settled_item_set || previous >= settled_item;
                if (fresh) {
                    for (size_t item = first; item < letter; ++item) {
                        taken[count_before++] = word.letters[item];
                    }
                }
                /* A HYPHEN THE FONT HAS NOT GOT IS NAMED HERE TOO. This
                   path puts the hyphen in as a character code and sets the
                   run again from it, rather than asking make_hyphen_node for
                   a node -- so the check that one makes was not being made,
                   and a font without the character broke the word in
                   silence. The reference names it once for every break it
                   tries. See
                   tests/trip/probes/what-a-word-hyphenates-to-when-the-hyphen-is-not-there.tex. */
                if (metrics->characters != NULL &&
                    metrics->hyphen_character <= 255 &&
                    metrics->characters[metrics->hyphen_character].tag < 0) {
                    char_warning(engine, metrics,
                                 (uint8_t)metrics->hyphen_character);
                } else {
                    taken[count_before++] =
                        (uint8_t)metrics->hyphen_character;
                }
                size_t made_before = 0U;
                size_t made_after = 0U;
                bool from_boundary =
                    !seeded && previous == word_start &&
                    word_meets_left_boundary(engine, items, count, word_start);
                if (reconstitute_seeded(engine, word.font,
                                        seeded ? &seed_item : NULL, taken,
                                        count_before, from_boundary,
                                        true, behind, room, &made_before,
                                        error, error_capacity) != 0 ||
                    reconstitute_characters(engine, word.font,
                                            word.letters + letter,
                                            word.count - letter, true,
                                            word_meets_right_boundary(
                                                engine, items, word.end),
                                            ahead, room, &made_after, error,
                                            error_capacity) != 0) {
                    free(ahead);
                    free(behind);
                    status = -1;
                    break;
                }
                const uint32_t *unbroken = items + base;
                /* The run replaces what stood in front of the word too. */
                size_t start = previous - base - (seeded ? 1U : 0U);
                if (settled_item_set && settled_item > base &&
                    settled_item - base > start) {
                    start = settled_item - base;
                }
                /* WHERE THE TWO BRANCHES FALL BACK INTO STEP. The reference
                   develops the text after the break beside the text that was
                   already there until both stand at the same LETTER of the
                   word, and shares everything from there on.

                   Matching the two from their ENDS cannot find that place.
                   trip's ligature program makes a run so repetitive --
                   `5 7 6 7 kern' over and over -- that the last seven nodes
                   of the after-text match the last seven of the run although
                   the two are nowhere near the same letter, and seven other
                   cuts match just as well. So the cut is looked for from the
                   front: the letters on each side must add up, and it must
                   fall where a letter BEGINS rather than in the middle of
                   what the font's program put between two of them. Measured:
                   the reference shares two nodes here, where matching
                   backwards would share seven. See
                   tests/trip/probes/what-a-word-hyphenates-to-when-the-hyphen-is-not-there.tex. */
                size_t lead = 0U;
                for (size_t at = start; at + base < index && at < whole; ++at) {
                    lead += letters_of_node(engine, unbroken[at]);
                }
                size_t tail = 0U;
                size_t reach = made_after;
                if (reach > whole - start) {
                    reach = whole - start;
                }
                for (size_t candidate = reach; candidate > 0U; --candidate) {
                    size_t major_stop = whole - candidate;
                    size_t minor_stop = made_after - candidate;
                    if (letters_of_node(engine, unbroken[major_stop]) == 0U ||
                        letters_of_node(engine, ahead[minor_stop]) == 0U) {
                        continue;
                    }
                    bool same = true;
                    for (size_t at = 0U; same && at < candidate; ++at) {
                        same = set_the_same_way(engine, ahead[minor_stop + at],
                                                unbroken[major_stop + at]);
                    }
                    if (!same) {
                        continue;
                    }
                    size_t major = 0U;
                    for (size_t at = start; at < major_stop; ++at) {
                        major += letters_of_node(engine, unbroken[at]);
                    }
                    size_t minor = 0U;
                    for (size_t at = 0U; at < minor_stop; ++at) {
                        minor += letters_of_node(engine, ahead[at]);
                    }
                    if (major == lead + minor) {
                        tail = candidate;
                        break;
                    }
                }
                size_t stop = whole - tail;
                /* Two discretionaries cannot replace the same nodes. They no
                   longer can: each run begins where the last one settled,
                   and ends where its own branches fell back into step. The
                   cap on the next break's LETTER that used to stand here cut
                   the first run down to where the second letter began --
                   five nodes of seventy -- which is not where the reference
                   ends it. */
                if (stop < start) {
                    stop = start;
                    tail = whole - stop;
                    if (tail > made_after) {
                        tail = made_after;
                    }
                }
                struct hstex_node disc = {.kind = HSTEX_NODE_DISCRETIONARY};
                uint32_t run = 0U;
                uint32_t placed = 0U;
                if (stop - start > 255U ||
                    store_list_run(engine, behind, made_before, &run, error,
                                   error_capacity) != 0) {
                    free(ahead);
                    free(behind);
                    status = -1;
                    break;
                }
                disc.value.disc.pre_start = run;
                disc.value.disc.pre_count = (uint16_t)made_before;
                if (store_list_run(engine, ahead, made_after - tail, &run,
                                   error, error_capacity) != 0 ||
                    store_node(engine, &disc, &placed, error,
                               error_capacity) != 0) {
                    free(ahead);
                    free(behind);
                    status = -1;
                    break;
                }
                struct hstex_node *settled = &engine->nodes[placed - 1U];
                settled->value.disc.post_start = run;
                settled->value.disc.post_count = (uint16_t)(made_after - tail);
                settled->value.disc.replace_count = (uint8_t)(stop - start);
                free(ahead);
                free(behind);
                /* The nodes from where this run begins onwards have been
                   written out already; they belong after it. */
                size_t back = base + start;
                settled_item = base + stop;
                settled_item_set = true;
                written -= index - back;
                if (reserve_hyphenated_items(&result, &capacity,
                                             written + 1U + (index - back),
                                             error, error_capacity) != 0) {
                    status = -1;
                    break;
                }
                result[written++] = placed;
                for (size_t item = back; item < index; ++item) {
                    result[written++] = items[item];
                }
            }
            if (wanted && (adjacent || kerned)) {
                uint32_t hyphen = 0U;
                if (make_hyphen_node(engine, word.font, &hyphen, error,
                                     error_capacity) != 0) {
                    status = -1;
                    break;
                }
                struct hstex_node disc = {.kind = HSTEX_NODE_DISCRETIONARY};
                /* THE LETTER IN FRONT OF THE BREAK IS SET AGAIN TOGETHER
                   WITH THE HYPHEN whenever the font has anything to say
                   about the pair -- a ligature OR a kern. The discretionary
                   then replaces that letter, and the kern the font had put
                   after it. See docs/DECISIONS.md, a-hyphen-that-ligatures. */
                size_t covered = adjacent ? 1U : 2U;
                bool joined = false;
                /* The letter in front of the break can only be set again if
                   it is still the engine's to set: one an earlier
                   discretionary already read is gone, and what is left is a
                   hyphen standing on its own. */
                bool fresh = previous >= settled_to;
                if (hyphen != 0U && fresh) {
                    const struct hstex_font *metrics =
                        font_by_identifier(engine, word.font);
                    const struct hstex_node *before =
                        &engine->nodes[items[previous] - 1U];
                    uint8_t hyphen_code =
                        (uint8_t)engine->nodes[hyphen - 1U]
                            .value.character.character;
                    bool joins = false;
                    struct hstex_lig_kern_result step = {0};
                    if (metrics != NULL &&
                        (before->kind == HSTEX_NODE_CHARACTER ||
                         before->kind == HSTEX_NODE_LIGATURE)) {
                        if (font_lig_kern(
                                metrics,
                                (uint8_t)before->value.character.character,
                                hyphen_code, &step, error,
                                error_capacity) != 0) {
                            status = -1;
                        }
                        joins = step.kind == HSTEX_LIG_KERN_LIGATURE ||
                                step.kind == HSTEX_LIG_KERN_KERN;
                    }
                    if (status == 0 && joins && written >= covered &&
                        result[written - covered] == items[previous]) {
                        uint8_t letters[16];
                        size_t letter_count = 0U;
                        if (before->kind == HSTEX_NODE_LIGATURE &&
                            before->value.character.original_count != 0U) {
                            uint8_t originals =
                                before->value.character.original_count;
                            if (originals > 15U) {
                                originals = 15U;
                            }
                            for (uint8_t item = 0U; item < originals; ++item) {
                                letters[letter_count++] =
                                    before->value.character.originals[item];
                            }
                        } else {
                            letters[letter_count++] =
                                (uint8_t)before->value.character.character;
                        }
                        letters[letter_count++] = hyphen_code;
                        uint32_t pre[48];
                        size_t pre_count = 0U;
                        uint32_t start = 0U;
                        /* The character beyond the word's right end takes
                           part in what goes in front of the break too: the
                           reference hands the font's boundary to that
                           reconstitution as it does to the one after the
                           break. */
                        if (reconstitute_characters(engine, word.font, letters,
                                                    letter_count, false, true,
                                                    pre, 48U, &pre_count, error,
                                                    error_capacity) != 0 ||
                            store_list_run(engine, pre, pre_count, &start,
                                           error, error_capacity) != 0) {
                            status = -1;
                        } else {
                            disc.value.disc.pre_start = start;
                            disc.value.disc.pre_count = (uint16_t)pre_count;
                            disc.value.disc.replace_count = (uint8_t)covered;
                            joined = true;
                        }
                    }
                }
                if (status != 0) {
                    break;
                }
                if (!joined && hyphen != 0U && (adjacent || !fresh)) {
                    status = store_list_run(engine, &hyphen, 1U,
                                            &disc.value.disc.pre_start, error,
                                            error_capacity);
                    disc.value.disc.pre_count = 1U;
                } else if (!joined && hyphen != 0U) {
                    uint32_t pre[2] = {items[previous], hyphen};
                    status = store_list_run(engine, pre, 2U,
                                            &disc.value.disc.pre_start, error,
                                            error_capacity);
                    disc.value.disc.pre_count = 2U;
                    disc.value.disc.replace_count = 2U;
                }
                /* WHAT FOLLOWS THE BREAK IS THE REST OF THE WORD, set
                   again from a fresh left boundary -- a line that starts
                   there meets the boundary as the first one did. The
                   reference develops that run beside what already stands
                   there and keeps only as much of it as differs: where the
                   two fall back into step, the nodes already there serve
                   both branches. See docs/DECISIONS.md, what-follows-a-
                   break-in-a-word. */
                if (status == 0 && letter < word.count && index < word.end) {
                    uint32_t ahead[48];
                    size_t made_after = 0U;
                    if (reconstitute_characters(
                            engine, word.font, word.letters + letter,
                            word.count - letter, true,
                            word_meets_right_boundary(engine, items,
                                                      word.end),
                            ahead, 48U, &made_after, error,
                            error_capacity) != 0) {
                        status = -1;
                    } else {
                        size_t following = word.end - index;
                        size_t tail = 0U;
                        while (tail < made_after && tail < following &&
                               set_the_same_way(
                                   engine, ahead[made_after - 1U - tail],
                                   items[word.end - 1U - tail])) {
                            ++tail;
                        }
                        size_t keep = made_after - tail;
                        if (keep != 0U) {
                            uint32_t run = 0U;
                            if (store_list_run(engine, ahead, keep, &run,
                                               error, error_capacity) != 0) {
                                status = -1;
                            } else {
                                disc.value.disc.post_start = run;
                                disc.value.disc.post_count = (uint16_t)keep;
                            }
                        }
                    }
                }
                uint32_t placed = 0U;
                if (status == 0) {
                    status = store_node(engine, &disc, &placed, error,
                                        error_capacity);
                }
                if (status != 0) {
                    break;
                }
                /* The nodes it replaces have been written out already; they
                   belong behind it. */
                size_t back = joined ? covered : ((kerned && fresh) ? 2U : 0U);
                written -= back;
                if (reserve_hyphenated_items(&result, &capacity, written + 4U,
                                             error, error_capacity) != 0) {
                    status = -1;
                    break;
                }
                result[written++] = placed;
                for (size_t item = 0U; item < back; ++item) {
                    result[written++] = items[previous + item];
                }
            }
            /* A break that falls inside a ligature replaces it: the two
               halves of the word are set again, and what was there stands
               as the text that is used when the line does not break. See
               docs/DECISIONS.md, breaking-inside-a-ligature. */
            size_t inside = 0U;
            for (size_t item = 1U; status == 0 && !blocked && item < here;
                 ++item) {
                if (breaks[letter + item] != 0U) {
                    inside = item;
                    break;
                }
            }
            if (status == 0 && inside != 0U) {
                const struct hstex_node *node =
                    &engine->nodes[items[index] - 1U];
                uint8_t originals[10];
                uint8_t original_count = node->value.character.original_count;
                memcpy(originals, node->value.character.originals,
                       sizeof(originals));
                uint32_t pre[48];
                size_t pre_count = 0U;
                size_t post_count = 0U;
                /* WHAT FOLLOWS THE BREAK IS THE REST OF THE WORD, not the
                   rest of this ligature: the two branches are developed
                   until they fall back into step, and the discretionary
                   replaces everything up to where they do. See
                   docs/DECISIONS.md, breaking-inside-a-ligature. */
                size_t cut = letter + inside;
                size_t room = (word.count + 8U) * 4U + 64U;
                uint32_t *post = calloc(room, sizeof(*post));
                struct hstex_node disc = {.kind = HSTEX_NODE_DISCRETIONARY};
                /* THE HYPHEN IS ONE OF THE LETTERS THE FONT IS ASKED ABOUT:
                   it goes in behind the ones before the break and the whole
                   run is set again, so a font that ligatures a letter with
                   a hyphen does so here. See docs/DECISIONS.md,
                   breaking-inside-a-ligature. */
                uint8_t before[16];
                size_t before_count = inside < 15U ? inside : 15U;
                memcpy(before, originals, before_count);
                const struct hstex_font *metrics =
                    font_by_identifier(engine, word.font);
                uint32_t hyphen_here = 0U;
                if (make_hyphen_node(engine, word.font, &hyphen_here, error,
                                     error_capacity) != 0) {
                    status = -1;
                }
                if (hyphen_here != 0U && metrics != NULL) {
                    before[before_count++] =
                        (uint8_t)metrics->hyphen_character;
                }
                if (status == 0 && post != NULL && inside < original_count &&
                    reconstitute_characters(engine, word.font, before,
                                            before_count, false, false, pre,
                                            48U, &pre_count, error,
                                            error_capacity) == 0 &&
                    reconstitute_characters(engine, word.font,
                                            word.letters + cut,
                                            word.count - cut, false, false,
                                            post, room, &post_count, error,
                                            error_capacity) == 0) {
                    /* HOW FAR THE TWO BRANCHES RUN BEFORE THEY FALL BACK
                       INTO STEP is counted in LETTERS, not in nodes: each
                       takes one more of the font's own steps whenever it
                       stands behind the other, and they are in step again
                       when both have read the same letters. What the major
                       branch read by then is what the discretionary
                       replaces. */
                    size_t minor_at = cut;
                    size_t major_at = letter + here;
                    size_t major_item = index + 1U;
                    size_t letter_at = letter + here;
                    size_t taken = 0U;
                    /* A kern the font put after this node belongs to the
                       step that made it. */
                    while (major_item < word.end &&
                           (letter_at >= word.count ||
                            word.positions[letter_at] > major_item)) {
                        ++major_item;
                    }
                    while (minor_at != major_at) {
                        if (minor_at < major_at) {
                            if (taken >= post_count) {
                                break;
                            }
                            minor_at += letters_a_node_stands_for(
                                engine, post[taken]);
                            ++taken;
                            /* A kern the font asked for belongs to the step
                               that made it. */
                            while (taken < post_count &&
                                   node_is_a_kern(engine, post[taken])) {
                                ++taken;
                            }
                            continue;
                        }
                        if (major_item >= word.end) {
                            break;
                        }
                        size_t stood = 0U;
                        while (letter_at < word.count &&
                               word.positions[letter_at] == major_item) {
                            ++stood;
                            ++letter_at;
                        }
                        major_at += stood;
                        ++major_item;
                        /* A node standing for no letter of its own -- a kern
                           the font put in -- belongs to the step in front of
                           it. */
                        while (major_item < word.end &&
                               (letter_at >= word.count ||
                                word.positions[letter_at] > major_item)) {
                            ++major_item;
                        }
                    }
                    if (taken == 0U) {
                        taken = post_count;
                    }
                    size_t stop = major_item;
                    if (stop <= index) {
                        stop = index + 1U;
                    }
                    size_t tail = post_count - taken;
                    size_t replaced = stop - index;
                    uint32_t start = 0U;
                    if (replaced > 255U ||
                        store_list_run(engine, pre, pre_count, &start, error,
                                       error_capacity) != 0) {
                        status = replaced > 255U ? status : -1;
                    } else {
                        disc.value.disc.pre_start = start;
                        disc.value.disc.pre_count = (uint16_t)pre_count;
                        if (store_list_run(engine, post, post_count - tail,
                                           &start, error,
                                           error_capacity) != 0) {
                            status = -1;
                        } else {
                            disc.value.disc.post_start = start;
                            disc.value.disc.post_count =
                                (uint16_t)(post_count - tail);
                            disc.value.disc.replace_count = (uint8_t)replaced;
                            uint32_t placed = 0U;
                            if (store_node(engine, &disc, &placed, error,
                                           error_capacity) != 0 ||
                                reserve_hyphenated_items(&result, &capacity,
                                                         written + 2U, error,
                                                         error_capacity) != 0) {
                                status = -1;
                            } else {
                                result[written++] = placed;
                                settled_to = stop;
                            }
                        }
                    }
                }
                free(post);
            }
            if (status == 0 &&
                reserve_hyphenated_items(&result, &capacity, written + 1U,
                                         error, error_capacity) != 0) {
                status = -1;
                break;
            }
            if (status != 0) {
                break;
            }
            result[written++] = items[index];
            letter += here;
            ++index;
        }
    }
    free(owned);
    engine->hyphenating_defers = false;
    if (status != 0) {
        free(result);
        return -1;
    }
    *out_items = result;
    *out_count = written;
    return 0;
}

/* Break the paragraph the engine has been filling into lines. */
static int break_paragraph(struct hstex_engine *engine,
                           struct hstex_box *out_last, char *error,
                           size_t error_capacity)
{
    struct hstex_hbox_builder *paragraph = engine->paragraph_builder;
    size_t count = paragraph->count;
    const uint32_t *items = paragraph->node_identifiers;
    struct hstex_break_state state = {0};
    /* \leftskip and \rightskip are looked at first, and their fault comes
       out before the first pass: measured, a \rightskip that shrinks without
       limit draws its line above `@firstpass' where a glue in the list draws
       one during the pass, at the glue. The parameter itself is changed, and
       not by an assignment -- no save is made and \showthe reads the finite
       glue afterwards. */
    for (size_t which = 0U; which < 2U; ++which) {
        struct hstex_glue *skip =
            &engine->glue_parameters[which == 0U ? HSTEX_GLUE_LEFT_SKIP
                                                 : HSTEX_GLUE_RIGHT_SKIP];
        if (skip->shrink_order != 0U && skip->shrink != 0) {
            skip->shrink_order = 0U;
            if (!state.shrink_error_reported) {
                state.shrink_error_reported = true;
                report_infinite_shrinkage(engine);
            }
        }
    }
    if (measure_break_totals(engine, &state, items, count, error,
                             error_capacity) != 0) {
        return -1;
    }
    struct hstex_break_totals background = {0};
    struct hstex_glue left = engine->glue_parameters[HSTEX_GLUE_LEFT_SKIP];
    struct hstex_glue right = engine->glue_parameters[HSTEX_GLUE_RIGHT_SKIP];
    background.width = (int64_t)left.width + right.width;
    if (left.stretch_order < 4U) {
        background.stretch[left.stretch_order] += left.stretch;
    }
    if (right.stretch_order < 4U) {
        background.stretch[right.stretch_order] += right.stretch;
    }
    if (left.shrink_order == 0U) {
        background.shrink += left.shrink;
    }
    if (right.shrink_order == 0U) {
        background.shrink += right.shrink;
    }

    size_t best = SIZE_MAX;
    int found = 0;
    /* \tracingparagraphs writes the passes out as the reference does; see
       docs/DECISIONS.md, tracing-paragraphs. */
    /* The whole of the line-break trace is one diagnostic, opened before the
       first pass names itself and closed after the last line is drawn. */
    bool saved_selector = false;
    if (engine->integer_parameters[HSTEX_INTEGER_TRACING_PARAGRAPHS] > 0) {
        state.trace.active = true;
        saved_selector = begin_diagnostic(engine);
    }
    int32_t emergency =
        engine->dimen_parameters[HSTEX_DIMEN_EMERGENCY_STRETCH];
    int32_t pretolerance = engine->integer_parameters[HSTEX_INTEGER_PRETOLERANCE];
    if (pretolerance >= 0) {
        if (state.trace.active) {
            print_fresh_line(engine);
            print_text(engine, "@firstpass\n");
        }
        found = find_paragraph_breaks(engine, &state, items, count, &background,
                                      pretolerance, false, &best, error,
                                      error_capacity);
    }
    /* The first pass never hyphenates; the second one does, over the whole
       paragraph at once. See docs/DECISIONS.md, hyphenation. */
    uint32_t *hyphenated = NULL;
    if (found == 0) {
        size_t hyphenated_count = 0U;
        if (hyphenate_paragraph(engine, items, count, &hyphenated,
                                &hyphenated_count, error, error_capacity) != 0) {
            free(state.totals);
            end_log_only(engine, saved_selector);
            return -1;
        }
        if (hyphenated_count != count) {
            items = hyphenated;
            count = hyphenated_count;
            free(state.totals);
            state.totals = NULL;
            if (measure_break_totals(engine, &state, items, count, error,
                                     error_capacity) != 0) {
                free(hyphenated);
                end_log_only(engine, saved_selector);
                return -1;
            }
        }
        /* The pass that hyphenates is the last one only when there is no
           \emergencystretch to fall back on. See docs/DECISIONS.md,
           emergency-stretch. */
        /* The second pass announces itself only when the first one ran and
           came to nothing; see docs/DECISIONS.md, tracing-paragraphs. */
        if (state.trace.active && pretolerance >= 0) {
            trace_newline(engine, &state.trace);
            print_text(engine, "@secondpass\n");
            state.trace.printed = 0U;
            state.trace.font_known = false;
        }
        found = find_paragraph_breaks(
            engine, &state, items, count, &background,
            engine->integer_parameters[HSTEX_INTEGER_TOLERANCE],
            emergency <= 0, &best, error, error_capacity);
    }
    /* Anything the walk never reached comes out here rather than being lost,
       and a paragraph that was not traced at all lets everything out. */
    if (found == 0 && emergency > 0) {
        /* One more pass, with that much more stretch behind every line. */
        if (state.trace.active) {
            trace_newline(engine, &state.trace);
            print_text(engine, "@emergencypass\n");
            state.trace.printed = 0U;
            state.trace.font_known = false;
        }
        background.stretch[0] += emergency;
        found = find_paragraph_breaks(
            engine, &state, items, count, &background,
            engine->integer_parameters[HSTEX_INTEGER_TOLERANCE], true, &best,
            error, error_capacity);
    }
    int status = found < 0 ? -1 : 0;
    if (status == 0 && found == 0) {
        status = set_error(error, error_capacity,
                           "no way to break this paragraph into lines");
    }
    /* Whatever the trace never reached comes out now rather than being lost,
       and so does everything where there was no trace to interleave with. */
    release_lost_characters(engine, SIZE_MAX);
    if (state.trace.active) {
        trace_newline(engine, &state.trace);
        end_diagnostic(engine, saved_selector, true);
        (void)fflush(diagnostic_stream(engine));
    }
    if (status == 0) {
        status = emit_paragraph_lines(engine, &state, items, count, best,
                                      out_last, error, error_capacity);
    }
    free(hyphenated);
    free(state.totals);
    free(state.records);
    free(state.active);
    free(state.rebuilt);
    return status;
}

/* Package the paragraph so far as one line. A paragraph with nothing in it
   contributes no line at all, which is what the reference does and what
   \noindent$$ depends on. */
/* Package the paragraph so far into lines and contribute them. A paragraph
   with nothing in it contributes nothing at all, which is what the reference
   does and what \noindent$$ depends on. */
static int finish_paragraph_line(struct hstex_engine *engine,
                                 struct hstex_box *out_line, char *error,
                                 size_t error_capacity)
{
    if (flush_pending_character(engine, error, error_capacity) != 0) {
        return -1;
    }
    if (engine->paragraph_builder == NULL ||
        engine->paragraph_builder->count == 0U) {
        engine->active_hbox_builder = NULL;
        engine->mode = HSTEX_MODE_VERTICAL;
        /* The list the paragraph goes back to is the one that held it, and
           inside a \vbox that is an internal one -- the same rule as for a
           paragraph with something in it, below. */
        engine->inner_mode =
            engine->nest_count != 0U &&
            engine->nest[engine->nest_count - 1U].inner;
        engine->building_paragraph = false;
        engine->has_pending_character = false;
        return 0;
    }
    struct hstex_node penalty = {
        .kind = HSTEX_NODE_PENALTY,
        .value.penalty = HSTEX_INFINITE_PENALTY,
    };
    /* Glue at the end of a paragraph becomes the penalty rather than being
       followed by one, so a \hskip written just before \par leaves nothing
       behind. */
    struct hstex_hbox_builder *ending = engine->paragraph_builder;
    if (ending->count != 0U) {
        uint32_t last = ending->node_identifiers[ending->count - 1U];
        if (last != 0U && (size_t)last <= engine->node_count &&
            engine->nodes[last - 1U].kind == HSTEX_NODE_GLUE) {
            ending->width -= packed_dimen(engine->nodes[last - 1U].width);
            --ending->count;
        }
    }
    struct hstex_glue fill = engine->glue_parameters[HSTEX_GLUE_PAR_FILL_SKIP];
    struct hstex_node fill_node = {
        .kind = HSTEX_NODE_GLUE,
        .width = fill.width,
        .value.glue = {
            .stretch = fill.stretch,
            .shrink = fill.shrink,
            .stretch_order = fill.stretch_order,
            .shrink_order = fill.shrink_order,
            .parameter = 1U + (uint8_t)HSTEX_GLUE_PAR_FILL_SKIP,
        },
    };
    if (append_hbox_node(engine, &penalty, error, error_capacity) != 0 ||
        append_hbox_node(engine, &fill_node, error, error_capacity) != 0) {
        return -1;
    }
    int status = break_paragraph(engine, out_line, error, error_capacity);
    engine->active_hbox_builder = NULL;
    engine->mode = HSTEX_MODE_VERTICAL;
    /* The vertical list the paragraph goes back to is the one that held it,
       which inside a \vbox is an internal one. Measured with \ifinner:
       `\vbox{hello\par \ifinner...}' is inner in the reference and was
       outer here. */
    engine->inner_mode =
        engine->nest_count != 0U && engine->nest[engine->nest_count - 1U].inner;
    engine->building_paragraph = false;
    engine->has_pending_character = false;
    return status;
}

/* The shape of a paragraph belongs to that paragraph: the reference clears
   it whenever a new one may begin, which is after \par and at the start of a
   vertical box, but not at the start of an hbox. The assignments are local,
   and are made only when they change something. See docs/DECISIONS.md,
   parshape. */
static int normal_paragraph(struct hstex_engine *engine, char *error,
                            size_t error_capacity)
{
    if (engine->integer_parameters[HSTEX_INTEGER_LOOSENESS] != 0 &&
        assign_integer_parameter(engine, (uint32_t)HSTEX_INTEGER_LOOSENESS, 0,
                                 false, error, error_capacity) != 0) {
        return -1;
    }
    if (engine->dimen_parameters[HSTEX_DIMEN_HANG_INDENT] != 0 &&
        assign_dimen_parameter(engine, (uint32_t)HSTEX_DIMEN_HANG_INDENT, 0,
                               false, error, error_capacity) != 0) {
        return -1;
    }
    if (engine->integer_parameters[HSTEX_INTEGER_HANG_AFTER] != 1 &&
        assign_integer_parameter(engine, (uint32_t)HSTEX_INTEGER_HANG_AFTER, 1,
                                 false, error, error_capacity) != 0) {
        return -1;
    }
    if (engine->parshape != 0U &&
        assign_parshape(engine, 0U, false, error, error_capacity) != 0) {
        return -1;
    }
    return 0;
}

static int finish_paragraph(struct hstex_engine *engine, char *error,
                            size_t error_capacity)
{
    /* What the paragraph was entered with is what its first words are
       hyphenated by; the level holding it goes away here. */
    if (engine->nest_count != 0U) {
        const struct hstex_nest_level *level =
            &engine->nest[engine->nest_count - 1U];
        engine->paragraph_language = level->language;
        engine->paragraph_left_min = level->left_hyphen_min;
        engine->paragraph_right_min = level->right_hyphen_min;
        engine->paragraph_line = (int32_t)level->line;
    }
    nest_pop(engine);
    /* The hundred-error limit counts within one paragraph, so ending one
       forgives what went wrong inside it. */
    engine->error_count = 0;
    if (finish_paragraph_line(engine, NULL, error, error_capacity) != 0 ||
        normal_paragraph(engine, error, error_capacity) != 0) {
        return -1;
    }
    return contribute_page(engine, error, error_capacity);
}

/* A horizontal command met in vertical mode starts an indented paragraph and
   is then read again, so that \everypar runs before the command's own
   operands are scanned; see docs/DECISIONS.md, starting-a-paragraph. The
   executor does the pushing back, so by the time an executor runs, the mode
   is already right and this only reports a genuinely misplaced command. */
static int ensure_horizontal_mode(struct hstex_engine *engine, char *error,
                                  size_t error_capacity)
{
    if (engine->mode == HSTEX_MODE_HORIZONTAL) {
        return 0;
    }
    uint32_t line = 0U;
    const char *origin = current_source_line(engine, &line);
    return set_error(error, error_capacity,
                     "horizontal command \\%s used outside horizontal mode, "
                     "at %s:%u",
                     executing_name(engine), origin, (unsigned int)line);
}

/* The commands that begin a paragraph when they are met in vertical mode.
   Everything else either belongs to the vertical list or is an error there:
   pdfTeX rejects \/ in internal vertical mode rather than starting one. */
/* The commands that end a paragraph when they are met while one is being
   built: the reference puts a \par in front of them and reads them again,
   so that what they make goes into the vertical list. See
   docs/DECISIONS.md, ending-a-paragraph. */
static bool command_ends_paragraph(const struct hstex_meaning *meaning)
{
    switch (meaning->command) {
    case HSTEX_COMMAND_HRULE:
    case HSTEX_COMMAND_VSKIP:
    case HSTEX_COMMAND_HALIGN:
    case HSTEX_COMMAND_END:
        return true;
    case HSTEX_COMMAND_UNBOX:
        return meaning->value.integer == (int32_t)HSTEX_UNBOX_VERTICAL ||
               meaning->value.integer == (int32_t)HSTEX_UNBOX_VERTICAL_COPY;
    default:
        return false;
    }
}

static bool command_starts_paragraph(const struct hstex_meaning *meaning)
{
    switch (meaning->command) {
    case HSTEX_COMMAND_HSKIP:
    case HSTEX_COMMAND_VRULE:
    case HSTEX_COMMAND_CONTROL_SPACE:
    case HSTEX_COMMAND_CHAR:
    case HSTEX_COMMAND_ACCENT:
    /* A discretionary is a horizontal command, so it opens a paragraph
       rather than failing; \- does too, being the same command. \/ does
       not, and the reference says so. */
    case HSTEX_COMMAND_DISCRETIONARY:
    case HSTEX_COMMAND_DISCRETIONARY_HYPHEN:
    /* \valign builds columns out of a horizontal list, so meeting one in
       vertical mode starts the paragraph that will hold it -- where
       \halign, which builds rows, belongs to the vertical list itself.
       trip line 171 opens its second pass this way. */
    case HSTEX_COMMAND_VALIGN:
        return true;
    case HSTEX_COMMAND_UNBOX:
        return meaning->value.integer ==
                   (int32_t)HSTEX_UNBOX_HORIZONTAL ||
               meaning->value.integer ==
                   (int32_t)HSTEX_UNBOX_HORIZONTAL_COPY;
    default:
        return false;
    }
}

/* A control space is the font's own interword glue, with no space-factor
   adjustment; see docs/DECISIONS.md, control-space-and-italic. */
/* \  takes \spaceskip when that is set and the current font's interword
   glue otherwise, neither adjusted by the space factor, and a formula gets
   exactly the same glue as a paragraph does. See docs/DECISIONS.md,
   control-space. */
static int execute_control_space(struct hstex_engine *engine, char *error,
                                 size_t error_capacity)
{
    if (engine->mode != HSTEX_MODE_MATH &&
        ensure_horizontal_mode(engine, error, error_capacity) != 0) {
        return -1;
    }
    if (flush_pending_character(engine, error, error_capacity) != 0) {
        return -1;
    }
    struct hstex_glue glue = engine->glue_parameters[HSTEX_GLUE_SPACE_SKIP];
    bool from_font = glue.width == 0 && glue.stretch == 0 && glue.shrink == 0;
    if (from_font) {
        const struct hstex_font *font =
            font_by_identifier(engine, engine->current_font);
        if (font == NULL || font->dimen_count < 4U) {
            return set_error(error, error_capacity,
                             "current font does not define interword spacing");
        }
        glue.width = font->dimens[1];
        glue.stretch = font->dimens[2];
        glue.shrink = font->dimens[3];
        glue.stretch_order = 0U;
        glue.shrink_order = 0U;
    }
    struct hstex_node node = {
        .kind = HSTEX_NODE_GLUE,
        .width = glue.width,
        .value.glue = {
            .stretch = glue.stretch,
            .shrink = glue.shrink,
            .stretch_order = glue.stretch_order,
            .shrink_order = glue.shrink_order,
            .parameter =
                from_font ? 0U : 1U + (uint8_t)HSTEX_GLUE_SPACE_SKIP,
        },
    };
    return append_current_list_node(engine, &node, error, error_capacity);
}

/* \/ adds the italic correction of whatever character precedes it. */
static int execute_italic_correction(struct hstex_engine *engine, char *error,
                                     size_t error_capacity)
{
    /* Inside a formula \/ is a kern of zero, whatever stands before it --
       measured: `$x\/y$' puts \kern0.0 after the x, where the same \/ in
       a paragraph would put the character's own italic correction. trip
       line 298 writes one in a formula. */
    if (engine->mode == HSTEX_MODE_MATH) {
        struct hstex_node kern = {.kind = HSTEX_NODE_KERN};
        return append_current_list_node(engine, &kern, error, error_capacity);
    }
    /* \/ does not open a paragraph -- it is one of the few horizontal
       commands the reference refuses in vertical mode rather than starting
       one for. It says so and carries on. */
    if (engine->mode != HSTEX_MODE_HORIZONTAL) {
        report_illegal_case(engine, engine->executing_token);
        return 0;
    }
    if (flush_pending_character(engine, error, error_capacity) != 0) {
        return -1;
    }
    /* Nothing at all is added unless a character stands at the end of the
       list; see docs/DECISIONS.md, control-space-and-italic. */
    const struct hstex_node *node = current_list_last_node(engine);
    if (node == NULL || (node->kind != HSTEX_NODE_CHARACTER &&
                         node->kind != HSTEX_NODE_LIGATURE)) {
        return 0;
    }
    int32_t correction = 0;
    const struct hstex_font *font =
        font_by_identifier(engine, node->value.character.font);
    if (font != NULL && font->characters != NULL) {
        correction =
            font->characters[node->value.character.character & 0xFFU].italic;
    }
    /* The reference marks this kern explicit, which is what \showbox shows
       and what keeps it from being thrown away at a line break. */
    struct hstex_node kern = {
        .kind = HSTEX_NODE_KERN,
        .explicit_kern = true,
        .width = correction,
    };
    return append_hbox_node(engine, &kern, error, error_capacity);
}

/* \char names a character by code; it joins the list like any other. */
static int execute_char(struct hstex_engine *engine, char *error,
                        size_t error_capacity)
{
    int32_t code = 0;
    if (scan_integer(engine, &code, error, error_capacity) != 0) {
        return -1;
    }
    if (code < 0 || code > 255) {
        return set_error(error, error_capacity, "bad character code (%d)",
                         code);
    }
    if (engine->mode == HSTEX_MODE_VERTICAL) {
        if (start_paragraph(engine, true, error, error_capacity) != 0) {
            return -1;
        }
    }
    /* Inside a formula \char names a math character, through \mathcode,
       exactly as the character itself would. Appending it horizontally
       happened to work in an inline formula, where the paragraph's own
       list was there to take it, and failed in a display, where there is
       none. trip line 266 writes \char`B inside a display. */
    if (engine->mode == HSTEX_MODE_MATH) {
        return math_append_character(engine, (uint8_t)code, error,
                                     error_capacity);
    }
    return append_horizontal_character(engine, (uint8_t)code, error,
                                       error_capacity);
}

/* ---------------------------------------------------------------------- */
/* Math lists.                                                            */
/*                                                                        */
/* A formula is collected as a list of noads and translated into a        */
/* horizontal list when it closes. Only the text size is implemented, and */
/* scripts, fractions and delimiters are not; see docs/DECISIONS.md,      */
/* math-mode, for what was measured and what is deferred.                 */
/* ---------------------------------------------------------------------- */

static struct hstex_math_builder *current_math_list(struct hstex_engine *engine)
{
    if (engine->math_depth == 0U) {
        return NULL;
    }
    return &engine->math_stack[engine->math_depth - 1U];
}

static int push_math_list(struct hstex_engine *engine, uint8_t style,
                          char *error, size_t error_capacity)
{
    if (engine->math_depth == engine->math_capacity) {
        size_t capacity =
            engine->math_capacity == 0U ? 8U : engine->math_capacity * 2U;
        if (capacity > SIZE_MAX / sizeof(*engine->math_stack)) {
            return set_error(error, error_capacity, "math list nesting overflow");
        }
        void *allocation =
            realloc(engine->math_stack, capacity * sizeof(*engine->math_stack));
        if (allocation == NULL) {
            return set_error(error, error_capacity,
                             "math list allocation failed");
        }
        engine->math_stack = allocation;
        engine->math_capacity = capacity;
    }
    struct hstex_math_builder *builder =
        &engine->math_stack[engine->math_depth++];
    memset(builder, 0, sizeof(*builder));
    builder->forced_class = -1;
    builder->style = style;
    builder->current_style = style;
    builder->saved_inner_mode = engine->inner_mode;
    /* A formula is a level of the nest of its own, which is what \showlists
       walks: the reference writes a `### math mode entered at line' for
       every sub-formula that is open, innermost first, with the noads it
       holds under each. */
    if (nest_push(engine, error, error_capacity) != 0) {
        --engine->math_depth;
        return -1;
    }
    struct hstex_nest_level *level = &engine->nest[engine->nest_count - 1U];
    level->mode = (uint8_t)HSTEX_MODE_MATH;
    level->math = (uint32_t)engine->math_depth;
    level->prev_depth = HSTEX_IGNORE_DEPTH;
    level->space_factor = 1000;
    /* A list nested inside a formula is internal, even when the formula is
       a display: \ifinner is true in `$${...}$$' and in a script, and the
       reference names the mode "math mode" there rather than "display math
       mode". The formula's own list is not nested and keeps what the
       opening shift decided. */
    if (engine->math_depth > engine->math_floor + 1U) {
        engine->inner_mode = true;
    }
    return 0;
}

static void pop_math_list(struct hstex_engine *engine)
{
    if (engine->math_depth == 0U) {
        return;
    }
    nest_pop(engine);
    struct hstex_math_builder *builder =
        &engine->math_stack[--engine->math_depth];
    if (engine->math_depth != 0U) {
        engine->math_stack[engine->math_depth - 1U].pending_atom = 0U;
    }
    if (engine->math_depth >= engine->math_floor + 1U) {
        engine->inner_mode = builder->saved_inner_mode;
    }
    free(builder->noads);
    memset(builder, 0, sizeof(*builder));
}

static int reserve_noads(struct hstex_math_builder *builder, size_t required,
                         char *error, size_t error_capacity)
{
    if (required <= builder->capacity) {
        return 0;
    }
    size_t capacity = builder->capacity == 0U ? 16U : builder->capacity;
    while (capacity < required) {
        if (capacity > SIZE_MAX / 2U) {
            return set_error(error, error_capacity, "math list overflow");
        }
        capacity *= 2U;
    }
    if (capacity > SIZE_MAX / sizeof(*builder->noads)) {
        return set_error(error, error_capacity, "math list overflow");
    }
    void *allocation =
        realloc(builder->noads, capacity * sizeof(*builder->noads));
    if (allocation == NULL) {
        return set_error(error, error_capacity, "math list allocation failed");
    }
    builder->noads = allocation;
    builder->capacity = capacity;
    return 0;
}

/* \radical, \overline and \underline make noads that are ordinary atoms
   once the list is set: they carry scripts and count for the spacing on
   either side of them, so everything that looks for an atom must see them
   too. */
static bool math_noad_is_atom(uint8_t kind)
{
    return kind == (uint8_t)HSTEX_NOAD_ATOM ||
           kind == (uint8_t)HSTEX_NOAD_RADICAL ||
           kind == (uint8_t)HSTEX_NOAD_ACCENT ||
           kind == (uint8_t)HSTEX_NOAD_FENCE ||
           kind == (uint8_t)HSTEX_NOAD_OVERLINE ||
           kind == (uint8_t)HSTEX_NOAD_UNDERLINE ||
           kind == (uint8_t)HSTEX_NOAD_MIDDLE;
}

static int math_append(struct hstex_engine *engine,
                       const struct hstex_noad *noad, char *error,
                       size_t error_capacity)
{
    struct hstex_math_builder *builder = current_math_list(engine);
    if (builder == NULL) {
        return set_error(error, error_capacity,
                         "math material used outside a formula");
    }
    if (reserve_noads(builder, builder->count + 1U, error, error_capacity) !=
        0) {
        return -1;
    }
    builder->noads[builder->count++] = *noad;
    return 0;
}

/* \mathord and its relatives set the class of the atom that follows. */
static int math_append_atom(struct hstex_engine *engine,
                            struct hstex_noad *noad, char *error,
                            size_t error_capacity)
{
    struct hstex_math_builder *builder = current_math_list(engine);
    if (builder == NULL) {
        return set_error(error, error_capacity,
                         "math material used outside a formula");
    }
    /* A script mark is waiting: this atom is the script, not a list item. */
    if (builder->slot != (uint8_t)HSTEX_MATH_SLOT_NONE) {
        if (builder->slot_target >= builder->count) {
            return set_error(error, error_capacity,
                             "a script has no atom to attach to");
        }
        struct hstex_noad *target = &builder->noads[builder->slot_target];
        if (builder->slot == (uint8_t)HSTEX_MATH_SLOT_SUPERSCRIPT) {
            target->superscript = noad->nucleus;
        } else if (builder->slot == (uint8_t)HSTEX_MATH_SLOT_RADICAND) {
            target->nucleus = noad->nucleus;
        } else {
            target->subscript = noad->nucleus;
        }
        builder->slot = (uint8_t)HSTEX_MATH_SLOT_NONE;
        return 0;
    }
    if (builder->forced_class >= 0) {
        noad->atom_class = (uint8_t)builder->forced_class;
        builder->forced_class = -1;
    }
    return math_append(engine, noad, error, error_capacity);
}

/* What may stand as a math field with no brace round it: a character that
   is a letter or an other, a brace (which opens a list of its own), and
   \char, \mathchar and \delimiter with the things \chardef and
   \mathchardef make. Measured against the reference, everything else draws
   a brace instead -- \radical, \hbox, \vcenter, \mathop, \kern, \penalty,
   a \countdef'd register, and every character of another catcode. */
static bool token_can_be_math_field(struct hstex_engine *engine,
                                    hstex_token token)
{
    if (hstex_token_is_character(token)) {
        return token_is_category(token, HSTEX_CAT_LETTER) ||
               token_is_category(token, HSTEX_CAT_OTHER) ||
               token_is_category(token, HSTEX_CAT_BEGIN_GROUP);
    }
    if (!hstex_token_is_control_sequence(token)) {
        return false;
    }
    /* A control sequence \let to a `{' opens a list just as the character
       does -- plain's \bgroup, which is how gentle writes a good many of
       its fields. */
    if (token_is_effective_begin_group(engine, token)) {
        return true;
    }
    const struct hstex_meaning *meaning =
        hstex_engine_meaning(engine, hstex_token_control_sequence_id(token));
    if (meaning == NULL) {
        return false;
    }
    switch (meaning->command) {
    case HSTEX_COMMAND_CHAR:
    case HSTEX_COMMAND_CHAR_GIVEN:
    case HSTEX_COMMAND_MATH_CHAR:
    case HSTEX_COMMAND_MATH_CHAR_GIVEN:
    case HSTEX_COMMAND_DELIMITER:
        return true;
    default:
        return false;
    }
}

/* A field that is none of those: the reference puts a `{' in front of it, so
   the field becomes a list of its own, and says so. The `}' it wants turns
   up by itself when the formula or the group above it ends. This is asked
   where the token is about to be obeyed rather than by looking ahead, since
   looking ahead expands it a moment too early and moves what the engine
   makes of the characters around it. */
static bool math_field_is_wanted(struct hstex_engine *engine)
{
    const struct hstex_math_builder *builder =
        engine->mode == HSTEX_MODE_MATH ? current_math_list(engine) : NULL;
    if (builder == NULL) {
        return false;
    }
    return builder->slot != (uint8_t)HSTEX_MATH_SLOT_NONE ||
           builder->forced_class >= 0;
}

static int insert_math_field_brace(struct hstex_engine *engine,
                                   hstex_token offending,
                                   struct hstex_source_location location,
                                   char *error, size_t error_capacity)
{
    static const char *const help[] = {
        "A left brace was mandatory here, so I've put one in.",
        "You might want to delete and/or insert some corrections",
        "so that I will find a matching right brace soon.",
        "(If you're confused by all this, try typing `I}' now.)", NULL};
    hstex_token opener =
        hstex_token_character((uint8_t)HSTEX_CAT_BEGIN_GROUP, (uint8_t)'{');
    /* The reference reports over the token it choked on, and only then
       takes the `{' it made: the brace is never a frame of its own in the
       context, so it goes in behind the report. */
    if (push_one(engine, offending, location, error, error_capacity) != 0) {
        return -1;
    }
    hstex_source_name_top(&engine->sources,
                          (uint8_t)HSTEX_TOKEN_SOURCE_BACKED_UP, 0U);
    tex_error(engine, help, "Missing { inserted");
    return push_one(engine, opener, location, error, error_capacity);
}

/* A script mark attaches to the atom before it, or to a fresh ordinary atom
   with nothing in it when there is none. */
static int begin_math_script(struct hstex_engine *engine, bool superscript,
                             char *error, size_t error_capacity)
{
    struct hstex_math_builder *builder = current_math_list(engine);
    if (builder == NULL) {
        return set_error(error, error_capacity,
                         "a script mark is only allowed in a formula");
    }
    if (builder->slot != (uint8_t)HSTEX_MATH_SLOT_NONE) {
        return set_error(error, error_capacity,
                         "one script mark followed another");
    }
    bool have_atom =
        builder->count != 0U &&
        math_noad_is_atom(builder->noads[builder->count - 1U].kind);
    if (have_atom) {
        const struct hstex_noad *last = &builder->noads[builder->count - 1U];
        const struct hstex_math_field *taken =
            superscript ? &last->superscript : &last->subscript;
        if (taken->kind != (uint8_t)HSTEX_MATH_FIELD_EMPTY) {
            return set_error(error, error_capacity,
                             "this atom already has a %s",
                             superscript ? "superscript" : "subscript");
        }
    } else {
        struct hstex_noad empty = {
            .kind = (uint8_t)HSTEX_NOAD_ATOM,
            .atom_class = (uint8_t)HSTEX_ATOM_ORD,
        };
        if (math_append(engine, &empty, error, error_capacity) != 0) {
            return -1;
        }
    }
    builder->slot = superscript ? (uint8_t)HSTEX_MATH_SLOT_SUPERSCRIPT
                                : (uint8_t)HSTEX_MATH_SLOT_SUBSCRIPT;
    builder->slot_target = builder->count - 1U;
    return 0;
}

/* A mathcode of class 7 means "the family is \fam if that is a real family",
   and is otherwise an ordinary atom in the code's own family; the reference
   sets \fam to -1 on entry to a formula. */
static int math_append_code(struct hstex_engine *engine, int32_t code,
                            char *error, size_t error_capacity)
{
    uint8_t class_code = (uint8_t)((code >> 12) & 0x7);
    uint8_t family = (uint8_t)((code >> 8) & 0xF);
    uint8_t character = (uint8_t)(code & 0xFF);
    if (class_code == 7U) {
        int32_t requested = engine->integer_parameters[HSTEX_INTEGER_FAMILY];
        if (requested >= 0 && requested < 16) {
            family = (uint8_t)requested;
        }
        class_code = (uint8_t)HSTEX_ATOM_ORD;
    }
    struct hstex_noad noad = {
        .kind = (uint8_t)HSTEX_NOAD_ATOM,
        .atom_class = class_code,
        .nucleus = {.kind = (uint8_t)HSTEX_MATH_FIELD_CHARACTER,
                    .family = family,
                    .character = character},
    };
    return math_append_atom(engine, &noad, error, error_capacity);
}

static int math_append_character(struct hstex_engine *engine, uint8_t code,
                                 char *error, size_t error_capacity)
{
    int table = code_table_index(HSTEX_COMMAND_MATH_CODE);
    if (table < 0) {
        return set_error(error, error_capacity, "no mathcode table");
    }
    return math_append_code(engine, engine->code_tables[(size_t)table][code],
                            error, error_capacity);
}

static int math_append_box_field(struct hstex_engine *engine,
                                 const struct hstex_box *box,
                                 bool single_character, uint32_t sublist,
                                 uint8_t list_style, char *error,
                                 size_t error_capacity)
{
    return math_append_box_field_kind(engine, box, single_character, sublist,
                                      list_style, false, error,
                                      error_capacity);
}

static int math_append_box_field_kind(struct hstex_engine *engine,
                                      const struct hstex_box *box,
                                      bool single_character, uint32_t sublist,
                                      uint8_t list_style, bool vcentered,
                                      char *error, size_t error_capacity)
{
    struct hstex_node node = {
        .kind = HSTEX_NODE_LIST,
        .width = box->width,
        .height = box->height,
        .depth = box->depth,
        .value.list = {
            .node_start = box->node_start,
            .node_count = box->node_count,
            .box_kind = box->kind,
            .glue = box->glue,
        },
    };
    uint32_t identifier = 0U;
    if (store_node(engine, &node, &identifier, error, error_capacity) != 0) {
        return -1;
    }
    struct hstex_noad noad = {
        .kind = (uint8_t)HSTEX_NOAD_ATOM,
        .atom_class = (uint8_t)HSTEX_ATOM_ORD,
        .nucleus = {.kind = (uint8_t)HSTEX_MATH_FIELD_BOX,
                    .single_character = single_character ? 1U : 0U,
                    .node = identifier,
                    .sublist = sublist,
                    .list_style = list_style},
        .vcentered = vcentered,
    };
    return math_append_atom(engine, &noad, error, error_capacity);
}

static int math_append_box(struct hstex_engine *engine,
                           const struct hstex_box *box, char *error,
                           size_t error_capacity)
{
    return math_append_box_field(engine, box, false, 0U, 0U, error,
                                 error_capacity);
}

/* Glue, kerns and penalties keep the shape they already have. */
static int math_append_node(struct hstex_engine *engine,
                            const struct hstex_node *node, char *error,
                            size_t error_capacity)
{
    uint32_t identifier = 0U;
    if (store_node(engine, node, &identifier, error, error_capacity) != 0) {
        return -1;
    }
    struct hstex_noad noad = {
        .kind = (uint8_t)HSTEX_NOAD_NODE,
        .node = identifier,
    };
    return math_append(engine, &noad, error, error_capacity);
}


/* The style decides which of the three font tables a family is read from. */
static uint8_t math_size_of_style(uint8_t style)
{
    if (style < (uint8_t)HSTEX_STYLE_SCRIPT) {
        return (uint8_t)HSTEX_MATH_TEXT;
    }
    if (style < (uint8_t)HSTEX_STYLE_SCRIPT_SCRIPT) {
        return (uint8_t)HSTEX_MATH_SCRIPT;
    }
    return (uint8_t)HSTEX_MATH_SCRIPT_SCRIPT;
}

static uint8_t math_superscript_style(uint8_t style)
{
    return (uint8_t)(2U * (style / 4U) + (uint8_t)HSTEX_STYLE_SCRIPT +
                     (style % 2U));
}

static uint8_t math_subscript_style(uint8_t style)
{
    return (uint8_t)(2U * (style / 4U) + (uint8_t)HSTEX_STYLE_SCRIPT + 1U);
}

static const struct hstex_font *math_family_font(struct hstex_engine *engine,
                                                 uint8_t size, uint8_t family)
{
    if (family >= 16U || size >= (uint8_t)HSTEX_MATH_SIZE_COUNT) {
        return NULL;
    }
    return font_by_identifier(engine, engine->math_fonts[size][family]);
}

/* One mu is a eighteenth of the quad of the symbol family, truncated; a mu
   quantity is that many times the stored value, again truncated toward zero.
   See docs/DECISIONS.md, math-mode. */
static int math_unit(struct hstex_engine *engine, uint8_t size, int32_t *unit,
                     char *error, size_t error_capacity)
{
    const struct hstex_font *symbols = math_family_font(engine, size, 2U);
    if (symbols == NULL || symbols->dimen_count < 6U) {
        return set_error(error, error_capacity,
                         "math units need \\textfont2 with six parameters");
    }
    *unit = symbols->dimens[5] / 18;
    return 0;
}

static int32_t scaled_by_unit(int32_t value, int32_t unit)
{
    bool negative = value < 0;
    int64_t magnitude = negative ? -(int64_t)value : (int64_t)value;
    int64_t result = magnitude * (int64_t)unit / INT64_C(65536);
    return negative ? (int32_t)-result : (int32_t)result;
}

static struct hstex_glue math_glue_in_points(struct hstex_glue glue,
                                             int32_t unit)
{
    struct hstex_glue result = glue;
    result.width = scaled_by_unit(glue.width, unit);
    /* AN INFINITE PART IS NOT IN MU AND IS NOT SCALED: a fil is a fil
       whatever the quad is, and only a finite stretch or shrink is a length
       the mu stands for. See docs/DECISIONS.md, math-glue-in-points. */
    if (glue.stretch_order == 0U) {
        result.stretch = scaled_by_unit(glue.stretch, unit);
    }
    if (glue.shrink_order == 0U) {
        result.shrink = scaled_by_unit(glue.shrink, unit);
    }
    return result;
}

/* The spacing between two adjacent atom classes, measured against pdfTeX:
   0 none, 1 \thinmuskip, 2 \medmuskip, 3 \thickmuskip. The entries a Bin
   atom can never reach are marked 0 because the class conversion below
   removes them first. */
/* Which of those spaces survive outside display and text style. Measured the
   same way inside a superscript: only the five that touch a large operator
   do. See docs/DECISIONS.md, math-scripts. */
static const uint8_t math_spacing_all_styles[HSTEX_ATOM_CLASS_COUNT]
                                            [HSTEX_ATOM_CLASS_COUNT] = {
    /*            ord op   bin  rel  open close punct inner */
    /* ord   */ {  0,  1,   0,   0,   0,   0,    0,    0 },
    /* op    */ {  1,  1,   0,   0,   0,   0,    0,    0 },
    /* bin   */ {  0,  0,   0,   0,   0,   0,    0,    0 },
    /* rel   */ {  0,  0,   0,   0,   0,   0,    0,    0 },
    /* open  */ {  0,  0,   0,   0,   0,   0,    0,    0 },
    /* close */ {  0,  1,   0,   0,   0,   0,    0,    0 },
    /* punct */ {  0,  0,   0,   0,   0,   0,    0,    0 },
    /* inner */ {  0,  1,   0,   0,   0,   0,    0,    0 },
};

static const uint8_t math_spacing_table[HSTEX_ATOM_CLASS_COUNT]
                                       [HSTEX_ATOM_CLASS_COUNT] = {
    /*            ord op   bin  rel  open close punct inner */
    /* ord   */ {  0,  1,   2,   3,   0,   0,    0,    1 },
    /* op    */ {  1,  1,   0,   3,   0,   0,    0,    1 },
    /* bin   */ {  2,  2,   0,   0,   2,   0,    0,    2 },
    /* rel   */ {  3,  3,   0,   0,   3,   0,    0,    3 },
    /* open  */ {  0,  0,   0,   0,   0,   0,    0,    0 },
    /* close */ {  0,  1,   2,   3,   0,   0,    0,    1 },
    /* punct */ {  1,  1,   1,   1,   1,   1,    1,    1 },
    /* inner */ {  1,  1,   2,   3,   1,   0,    1,    1 },
};

/* A Bin atom is only a binary operator between two things it can join. The
   reference turns it into an Ord at the start of a list, after another Bin,
   an Op, a Rel, an Open or a Punct, and before a Rel, a Close or a Punct or
   the end of the list. */
static void resolve_binary_atoms(struct hstex_math_builder *builder)
{
    int previous = -1;
    for (size_t index = 0U; index < builder->count; ++index) {
        struct hstex_noad *noad = &builder->noads[index];
        if (!math_noad_is_atom(noad->kind)) {
            continue;
        }
        if (noad->atom_class == (uint8_t)HSTEX_ATOM_BIN) {
            if (previous < 0 || previous == (int)HSTEX_ATOM_BIN ||
                previous == (int)HSTEX_ATOM_OP ||
                previous == (int)HSTEX_ATOM_REL ||
                previous == (int)HSTEX_ATOM_OPEN ||
                previous == (int)HSTEX_ATOM_PUNCT) {
                noad->atom_class = (uint8_t)HSTEX_ATOM_ORD;
            }
        } else if (noad->atom_class == (uint8_t)HSTEX_ATOM_REL ||
                   noad->atom_class == (uint8_t)HSTEX_ATOM_CLOSE ||
                   noad->atom_class == (uint8_t)HSTEX_ATOM_PUNCT) {
            for (size_t back = index; back != 0U; --back) {
                struct hstex_noad *earlier = &builder->noads[back - 1U];
                if (!math_noad_is_atom(earlier->kind)) {
                    continue;
                }
                if (earlier->atom_class == (uint8_t)HSTEX_ATOM_BIN) {
                    earlier->atom_class = (uint8_t)HSTEX_ATOM_ORD;
                }
                break;
            }
        }
        /* A \middle is a closing atom to what stands before it and an
           opening one to what follows; see docs/DECISIONS.md,
           middle-delimiters. */
        previous = noad->kind == (uint8_t)HSTEX_NOAD_MIDDLE
                       ? (int)HSTEX_ATOM_OPEN
                       : (int)noad->atom_class;
    }
    for (size_t index = builder->count; index != 0U; --index) {
        struct hstex_noad *noad = &builder->noads[index - 1U];
        if (!math_noad_is_atom(noad->kind)) {
            continue;
        }
        if (noad->atom_class == (uint8_t)HSTEX_ATOM_BIN) {
            noad->atom_class = (uint8_t)HSTEX_ATOM_ORD;
        }
        break;
    }
}

/* Returns 1 when the character is there, 0 when the font simply does not
   have it -- which the reference reports and then carries on without, so
   the atom contributes nothing. */
static int math_character_metric(struct hstex_engine *engine,
                                 struct hstex_math_field *field,
                                 uint8_t size, const struct hstex_font **font,
                                 const struct hstex_char_metric **metric,
                                 bool complain, char *error,
                                 size_t error_capacity)
{
    const struct hstex_font *resolved =
        math_family_font(engine, size, field->family);
    if (resolved == NULL) {
        return set_error(error, error_capacity,
                         "math family %u has no font in this size",
                         (unsigned int)field->family);
    }
    /* A family still holding \nullfont is one the document never set up.
       The reference names it, with the size it wanted and the character it
       wanted, and goes on without that character. */
    if (complain && field->family < 16U &&
        size < (uint8_t)HSTEX_MATH_SIZE_COUNT &&
        engine->math_fonts[size][field->family] == engine->null_font) {
        static const char *const help[] = {
            "Somewhere in the math formula just ended, you used the",
            "stated character from an undefined font family. For example,",
            "plain TeX doesn't allow \\it or \\sl in subscripts. Proceed,",
            "and I'll try to forget that I needed that character.", NULL};
        static const char *const sizes[] = {"textfont", "scriptfont",
                                            "scriptscriptfont"};
        /* The character is written the way the log writes any character it
           cannot write as itself, and building it here rather than passing
           the byte keeps a character zero from ending the message. */
        char shown[8];
        uint8_t code = (uint8_t)(field->character & 0xFFU);
        if (character_needs_caret(code)) {
            shown[0] = '^';
            shown[1] = '^';
            shown[2] = (char)(code < 64U ? code + 64U : code - 64U);
            shown[3] = '\0';
        } else {
            shown[0] = (char)code;
            shown[1] = '\0';
        }
        tex_error(engine, help, "\\%s %u is undefined (character %s)",
                  sizes[size], (unsigned int)field->family, shown);
        /* And the field is EMPTIED, so a second reading of it -- an accent
           asks its nucleus twice, once for the skew and once for the box --
           finds nothing there and says nothing more. Measured:
           `\mathaccent"161 A' with \fam13 draws one complaint, not two. */
        field->kind = (uint8_t)HSTEX_MATH_FIELD_EMPTY;
        field->single_character = 0U;
        return 0;
    }
    if (resolved->characters == NULL ||
        resolved->characters[field->character].tag < 0) {
        /* A character the family's font has not got is dropped, and the
           reference says so where \tracinglostchars asks, exactly as it
           does for one in text. A family still holding \nullfont has said
           so already, in words of its own, and says nothing more here. See
           docs/DECISIONS.md, missing-characters. */
        if (complain && resolved != font_by_identifier(engine,
                                                       engine->null_font)) {
            char_warning(engine, resolved,
                         (uint8_t)(field->character & 0xFFU));
        }
        return 0;
    }
    *font = resolved;
    *metric = &resolved->characters[field->character];
    return 1;
}

/* Two adjacent ordinary characters of the same family go through that
   font's ligature and kerning program, exactly as they would in text. */
static int apply_math_ligatures(struct hstex_engine *engine,
                                struct hstex_math_builder *builder,
                                uint8_t style, char *error,
                                size_t error_capacity)
{
    uint8_t size = math_size_of_style(style);
    for (size_t index = 0U; index + 1U < builder->count;) {
        struct hstex_noad *left = &builder->noads[index];
        struct hstex_noad *right = &builder->noads[index + 1U];
        if (left->kind == (uint8_t)HSTEX_NOAD_STYLE) {
            size = math_size_of_style(left->atom_class);
        }
        /* The reference asks only that the atom on the left be a plain
           character with nothing attached and that another character of the
           same family follow it, whatever that one carries. See
           docs/DECISIONS.md, math-text-characters. */
        if (left->kind != (uint8_t)HSTEX_NOAD_ATOM ||
            right->kind != (uint8_t)HSTEX_NOAD_ATOM ||
            left->atom_class != (uint8_t)HSTEX_ATOM_ORD ||
            right->atom_class > (uint8_t)HSTEX_ATOM_PUNCT ||
            left->nucleus.kind != (uint8_t)HSTEX_MATH_FIELD_CHARACTER ||
            right->nucleus.kind != (uint8_t)HSTEX_MATH_FIELD_CHARACTER ||
            left->nucleus.family != right->nucleus.family ||
            left->superscript.kind != (uint8_t)HSTEX_MATH_FIELD_EMPTY ||
            left->subscript.kind != (uint8_t)HSTEX_MATH_FIELD_EMPTY) {
            ++index;
            continue;
        }
        left->text_character = true;
        const struct hstex_font *font = NULL;
        const struct hstex_char_metric *metric = NULL;
        /* The ligature pass is only looking, not setting: the reading that
           wants the character reports for it. */
        int present = math_character_metric(engine, &left->nucleus, size, &font,
                                            &metric, false, error,
                                            error_capacity);
        if (present < 0) {
            return -1;
        }
        if (present == 0) {
            ++index;
            continue;
        }
        struct hstex_lig_kern_result step;
        if (font_lig_kern(font, (uint8_t)left->nucleus.character,
                          (uint8_t)right->nucleus.character, &step, error,
                          error_capacity) != 0) {
            return -1;
        }
        if (step.kind == HSTEX_LIG_KERN_LIGATURE) {
            /* A formula keeps its characters in noads rather than in a
               list, so the operation is carried out on the pair of noads:
               the one it does not keep takes the character it names, or a
               noad of its own is put between the two it keeps. An operation
               that is finished with what it made is not looked at again.
               See docs/DECISIONS.md, ligature-operations. */
            left->text_character = false;
            if (!step.keep_left) {
                left->nucleus.character = step.ligature;
            }
            if (!step.keep_right) {
                right->nucleus.character = step.ligature;
            }
            if (!step.keep_left && !step.keep_right) {
                memmove(&builder->noads[index + 1U],
                        &builder->noads[index + 2U],
                        (builder->count - index - 2U) *
                            sizeof(*builder->noads));
                --builder->count;
            } else if (step.keep_left && step.keep_right) {
                if (reserve_noads(builder, builder->count + 1U, error,
                                  error_capacity) != 0) {
                    return -1;
                }
                left = &builder->noads[index];
                struct hstex_noad inserted = builder->noads[index];
                inserted.nucleus.character = step.ligature;
                inserted.superscript.kind = (uint8_t)HSTEX_MATH_FIELD_EMPTY;
                inserted.subscript.kind = (uint8_t)HSTEX_MATH_FIELD_EMPTY;
                inserted.text_character = false;
                memmove(&builder->noads[index + 2U],
                        &builder->noads[index + 1U],
                        (builder->count - index - 1U) *
                            sizeof(*builder->noads));
                builder->noads[index + 1U] = inserted;
                ++builder->count;
            }
            if (step.advance != 0U) {
                index += step.advance;
            }
            continue;
        }
        if (step.kind == HSTEX_LIG_KERN_KERN && step.kern != 0) {
            int32_t kern = step.kern;
            struct hstex_node node = {
                .kind = HSTEX_NODE_KERN,
                .width = kern,
            };
            uint32_t identifier = 0U;
            struct hstex_noad inserted = {
                .kind = (uint8_t)HSTEX_NOAD_NODE,
            };
            if (store_node(engine, &node, &identifier, error,
                           error_capacity) != 0 ||
                reserve_noads(builder, builder->count + 1U, error,
                              error_capacity) != 0) {
                return -1;
            }
            inserted.node = identifier;
            memmove(&builder->noads[index + 2U], &builder->noads[index + 1U],
                    (builder->count - index - 1U) * sizeof(*builder->noads));
            builder->noads[index + 1U] = inserted;
            ++builder->count;
            index += 2U;
            continue;
        }
        ++index;
    }
    return 0;
}

/* A large operator sits with its middle on the axis of the symbol family.
   The builder derives the reach of a shifted node itself, so only the
   displacement is recorded here. */
static int centre_on_axis(struct hstex_engine *engine, uint8_t size,
                          struct hstex_node *node, char *error,
                          size_t error_capacity)
{
    const struct hstex_font *symbols = math_family_font(engine, size, 2U);
    if (symbols == NULL || symbols->dimen_count < 22U) {
        return set_error(error, error_capacity,
                         "a large operator needs \\textfont2 with "
                         "twenty-two parameters");
    }
    node->shift = half_of((int64_t)packed_dimen(node->height) -
                          packed_dimen(node->depth)) -
                  symbols->dimens[21];
    return 0;
}

static int emit_parameter_glue(struct hstex_engine *engine,
                               struct hstex_glue glue, int parameter,
                               char *error, size_t error_capacity)
{
    struct hstex_node node = {
        .kind = HSTEX_NODE_GLUE,
        .width = glue.width,
        .value.glue = {
            .stretch = glue.stretch,
            .shrink = glue.shrink,
            .stretch_order = glue.stretch_order,
            .shrink_order = glue.shrink_order,
            .parameter = parameter < 0 ? 0U : (uint8_t)(parameter + 1),
        },
    };
    return append_hbox_node(engine, &node, error, error_capacity);
}

/* The same glue, in a vertical list: a \\valign keeps its \\tabskip between
   the rows of a column rather than between the columns. */
static int emit_parameter_glue_vertically(struct hstex_engine *engine,
                                          struct hstex_glue glue,
                                          int parameter, char *error,
                                          size_t error_capacity)
{
    struct hstex_node node = {
        .kind = HSTEX_NODE_GLUE,
        .width = glue.width,
        .value.glue = {
            .stretch = glue.stretch,
            .shrink = glue.shrink,
            .stretch_order = glue.stretch_order,
            .shrink_order = glue.shrink_order,
            .parameter = parameter < 0 ? 0U : (uint8_t)(parameter + 1),
        },
    };
    return append_vbox_node(engine, &node, error, error_capacity);
}

static int emit_math_glue(struct hstex_engine *engine, struct hstex_glue glue,
                          char *error, size_t error_capacity)
{
    return emit_parameter_glue(engine, glue, -1, error, error_capacity);
}

/* Spacing the math list asked one of the three muskip parameters for; it
   keeps that name in \showbox. */
static int emit_math_parameter_glue(struct hstex_engine *engine,
                                    struct hstex_glue glue, size_t muskip,
                                    char *error, size_t error_capacity)
{
    struct hstex_node node = {
        .kind = HSTEX_NODE_GLUE,
        .width = glue.width,
        .value.glue = {
            .stretch = glue.stretch,
            .shrink = glue.shrink,
            .stretch_order = glue.stretch_order,
            .shrink_order = glue.shrink_order,
            .parameter =
                (uint8_t)(HSTEX_GLUE_PARAMETER_COUNT + 1U + muskip),
        },
    };
    return append_hbox_node(engine, &node, error, error_capacity);
}

static int emit_math_kern(struct hstex_engine *engine, int32_t amount,
                          bool explicit_kern, char *error,
                          size_t error_capacity)
{
    struct hstex_node node = {
        .kind = HSTEX_NODE_KERN,
        .width = amount,
        /* A kern \mkern asked for is an explicit one still, once the mu has
           been turned into points; the italic correction a character carries
           is not. See docs/DECISIONS.md, a-kern-in-mu. */
        .explicit_kern = explicit_kern,
    };
    return append_hbox_node(engine, &node, error, error_capacity);
}

/* Translate one finished math list into the horizontal list the engine is
   building. The caller has already pointed active_hbox_builder at it. */
static int translate_math_list_with(struct hstex_engine *engine,
                                    struct hstex_math_builder *builder,
                                    bool penalties, char *error,
                                    size_t error_capacity);

static bool math_fonts_are_missing(struct hstex_engine *engine);

/* A sub-formula gets no penalties of its own; only the outer list of a
   formula in a paragraph does. */
static int translate_math_list(struct hstex_engine *engine,
                               struct hstex_math_builder *builder, char *error,
                               size_t error_capacity)
{
    return translate_math_list_with(engine, builder, false, error,
                                    error_capacity);
}

static int translate_math_fraction(struct hstex_engine *engine,
                                   struct hstex_math_builder *builder,
                                   char *error, size_t error_capacity);

static int build_math_radical(struct hstex_engine *engine,
                              struct hstex_noad *noad, uint8_t style,
                              char *error, size_t error_capacity);

static int build_math_accent(struct hstex_engine *engine,
                             struct hstex_noad *noad, uint8_t style,
                             char *error, size_t error_capacity);

static int build_math_fence(struct hstex_engine *engine,
                            struct hstex_noad *outer_noad, uint8_t style,
                            char *error, size_t error_capacity);

static int build_operator_box(struct hstex_engine *engine,
                              struct hstex_noad *noad, uint8_t style,
                              int32_t *delta, struct hstex_node *boxed,
                              char *error, size_t error_capacity);

static int build_operator_limits(struct hstex_engine *engine,
                                 struct hstex_noad *noad, uint8_t style,
                                 int32_t delta, struct hstex_node *boxed,
                                 char *error, size_t error_capacity);

static int build_math_line(struct hstex_engine *engine,
                           struct hstex_noad *noad, uint8_t style, bool over,
                           char *error, size_t error_capacity);

static int variant_delimiter(struct hstex_engine *engine, int32_t code,
                             uint8_t size, int32_t wanted,
                             struct hstex_box *box, char *error,
                             size_t error_capacity);

/* Pack one field into a box at the given style. An empty field gives an empty
   box, a character gives that character with its italic correction, and a box
   field is the box that is already there. */
static int store_box_node(struct hstex_engine *engine,
                          const struct hstex_box *box, int32_t shift,
                          uint32_t *identifier, char *error,
                          size_t error_capacity);

/* Keep a sub-formula where a field can point at it. The records live as long
   as the engine, so a field never owns what it refers to. */
static int store_math_sublist(struct hstex_engine *engine,
                              const struct hstex_math_builder *list,
                              uint32_t *index, char *error,
                              size_t error_capacity)
{
    *index = 0U;
    size_t count = list->count;
    uint32_t start = 0U;
    if (count != 0U) {
        if (engine->math_item_count + count > engine->math_item_capacity) {
            size_t capacity = engine->math_item_capacity == 0U
                                  ? 64U
                                  : engine->math_item_capacity;
            while (capacity < engine->math_item_count + count) {
                if (capacity > SIZE_MAX / 2U) {
                    return set_error(error, error_capacity,
                                     "sub-formula arena overflow");
                }
                capacity *= 2U;
            }
            if (capacity > SIZE_MAX / sizeof(*engine->math_items)) {
                return set_error(error, error_capacity,
                                 "sub-formula arena overflow");
            }
            void *allocation = realloc(engine->math_items,
                                       capacity * sizeof(*engine->math_items));
            if (allocation == NULL) {
                return set_error(error, error_capacity,
                                 "sub-formula arena allocation failed");
            }
            engine->math_items = allocation;
            engine->math_item_capacity = capacity;
        }
        if (engine->math_item_count + count > (size_t)UINT32_MAX) {
            return set_error(error, error_capacity,
                             "sub-formula arena overflow");
        }
        start = (uint32_t)engine->math_item_count;
        memcpy(engine->math_items + engine->math_item_count, list->noads,
               count * sizeof(*list->noads));
        engine->math_item_count += count;
    }
    if (engine->math_sublist_count == engine->math_sublist_capacity) {
        size_t capacity = engine->math_sublist_capacity == 0U
                              ? 32U
                              : engine->math_sublist_capacity * 2U;
        if (capacity > SIZE_MAX / sizeof(*engine->math_sublists)) {
            return set_error(error, error_capacity,
                             "sub-formula record overflow");
        }
        void *allocation = realloc(engine->math_sublists,
                                   capacity * sizeof(*engine->math_sublists));
        if (allocation == NULL) {
            return set_error(error, error_capacity,
                             "sub-formula record allocation failed");
        }
        engine->math_sublists = allocation;
        engine->math_sublist_capacity = capacity;
    }
    if (engine->math_sublist_count >= (size_t)UINT32_MAX) {
        return set_error(error, error_capacity, "sub-formula record overflow");
    }
    struct hstex_math_sublist *record =
        &engine->math_sublists[engine->math_sublist_count++];
    record->start = start;
    record->count = (uint32_t)count;
    record->style = list->style;
    record->has_fraction = list->has_fraction;
    record->fraction_at = list->fraction_at;
    record->fraction_thickness = list->fraction_thickness;
    record->fraction_default_thickness = list->fraction_default_thickness;
    record->fraction_left = list->fraction_left;
    record->fraction_right = list->fraction_right;
    *index = (uint32_t)engine->math_sublist_count;
    return 0;
}

/* Fill a list from a kept sub-formula, to be set in the style asked for. */
static int load_math_sublist(struct hstex_engine *engine, uint32_t index,
                             uint8_t style, struct hstex_math_builder *list,
                             char *error, size_t error_capacity)
{
    memset(list, 0, sizeof(*list));
    list->forced_class = -1;
    list->style = style;
    list->current_style = style;
    if (index == 0U || (size_t)index > engine->math_sublist_count) {
        return set_error(error, error_capacity,
                         "a sub-formula record went missing");
    }
    const struct hstex_math_sublist *record =
        &engine->math_sublists[index - 1U];
    list->has_fraction = record->has_fraction;
    list->fraction_at = record->fraction_at;
    list->fraction_thickness = record->fraction_thickness;
    list->fraction_default_thickness = record->fraction_default_thickness;
    list->fraction_left = record->fraction_left;
    list->fraction_right = record->fraction_right;
    if (record->count == 0U) {
        return 0;
    }
    if (reserve_noads(list, record->count, error, error_capacity) != 0) {
        return -1;
    }
    memcpy(list->noads, engine->math_items + record->start,
           record->count * sizeof(*list->noads));
    list->count = record->count;
    return 0;
}

/* Set a sub-formula again, in the style it has turned out to be wanted in.
   Nothing happens unless the style differs from the one it was read in. */
static int math_field_restyle(struct hstex_engine *engine,
                              struct hstex_math_field *field, uint8_t style,
                              char *error, size_t error_capacity)
{
    if (field->kind != (uint8_t)HSTEX_MATH_FIELD_BOX || field->sublist == 0U ||
        field->list_style == style) {
        return 0;
    }
    struct hstex_math_builder part = {0};
    if (load_math_sublist(engine, field->sublist, style, &part, error,
                          error_capacity) != 0) {
        free(part.noads);
        return -1;
    }
    struct hstex_hbox_builder packed = {0};
    struct hstex_hbox_builder *previous = engine->active_hbox_builder;
    enum hstex_mode previous_mode = engine->mode;
    engine->active_hbox_builder = &packed;
    engine->mode = HSTEX_MODE_HORIZONTAL;
    int status = translate_math_list(engine, &part, error, error_capacity);
    engine->active_hbox_builder = previous;
    engine->mode = previous_mode;
    struct hstex_box box = {0};
    if (status == 0) {
        status = finalize_hbox(engine, &packed, false, false, 0, &box, error,
                               error_capacity);
    }
    free(packed.node_identifiers);
    free(part.noads);
    if (status != 0) {
        return -1;
    }
    bool single = false;
    if (box.node_count == 1U &&
        (size_t)box.node_start < engine->list_item_count) {
        uint32_t item = engine->list_items[box.node_start];
        if (item != 0U && item <= engine->node_count) {
            const struct hstex_node *node = &engine->nodes[item - 1U];
            single = (node->kind == HSTEX_NODE_CHARACTER ||
                      node->kind == HSTEX_NODE_LIGATURE) &&
                     node->shift == 0;
        }
    }
    uint32_t identifier = 0U;
    if (store_box_node(engine, &box, 0, &identifier, error, error_capacity) !=
        0) {
        return -1;
    }
    field->node = identifier;
    field->single_character = single ? 1U : 0U;
    field->list_style = style;
    return 0;
}

/* A lone character keeps the width its italic correction gave the box but
   loses the kern itself, so that an accent over it sees only the letter;
   see docs/DECISIONS.md, a-clean-box-of-one-character. */
static void simplify_clean_box(struct hstex_engine *engine,
                               struct hstex_box *box)
{
    if (box->node_count != 2U ||
        (size_t)box->node_start + 2U > engine->list_item_count) {
        return;
    }
    const uint32_t *items = engine->list_items + box->node_start;
    if (items[0] == 0U || (size_t)items[0] > engine->node_count ||
        items[1] == 0U || (size_t)items[1] > engine->node_count) {
        return;
    }
    const struct hstex_node *first = &engine->nodes[items[0] - 1U];
    const struct hstex_node *second = &engine->nodes[items[1] - 1U];
    if ((first->kind == HSTEX_NODE_CHARACTER ||
         first->kind == HSTEX_NODE_LIGATURE) &&
        second->kind == HSTEX_NODE_KERN) {
        box->node_count = 1U;
    }
}

/* The same box before the trivial-box simplification, for the callers that
   widen it first: what a box ends with is settled after that, not before.
   See docs/DECISIONS.md, a-clean-box-of-one-character. */
static int math_field_box_unsimplified(struct hstex_engine *engine,
                                       const struct hstex_math_field *field,
                                       uint8_t style, struct hstex_box *box,
                                       char *error, size_t error_capacity);

static int math_field_box(struct hstex_engine *engine,
                          const struct hstex_math_field *field, uint8_t style,
                          struct hstex_box *box, char *error,
                          size_t error_capacity)
{
    int status = math_field_box_unsimplified(engine, field, style, box, error,
                                             error_capacity);
    if (status == 0) {
        simplify_clean_box(engine, box);
    }
    return status;
}

static int math_field_box_unsimplified(struct hstex_engine *engine,
                                       const struct hstex_math_field *field,
                                       uint8_t style, struct hstex_box *box,
                                       char *error, size_t error_capacity)
{
    memset(box, 0, sizeof(*box));
    box->kind = HSTEX_BOX_HLIST;
    struct hstex_math_field restyled = *field;
    if (math_field_restyle(engine, &restyled, style, error, error_capacity) !=
        0) {
        return -1;
    }
    field = &restyled;
    if (field->kind == (uint8_t)HSTEX_MATH_FIELD_BOX) {
        if (field->node == 0U || field->node > engine->node_count) {
            return set_error(error, error_capacity,
                             "math field refers to a missing node");
        }
        const struct hstex_node *node = &engine->nodes[field->node - 1U];
        /* A sub-formula that came to one unshifted box is that box; the box
           a \hbox put there is taken as it stands. See docs/DECISIONS.md,
           a-list-that-is-one-box. */
        if (field->sublist != 0U && node->value.list.node_count == 1U &&
            (size_t)node->value.list.node_start <
                engine->list_item_count) {
            uint32_t item =
                engine->list_items[node->value.list.node_start];
            if (item != 0U && (size_t)item <= engine->node_count &&
                engine->nodes[item - 1U].kind == HSTEX_NODE_LIST &&
                engine->nodes[item - 1U].shift == 0) {
                node = &engine->nodes[item - 1U];
            }
        }
        box->kind = node->value.list.box_kind;
        box->width = node->width;
        box->height = node->height;
        box->depth = node->depth;
        box->node_start = node->value.list.node_start;
        box->node_count = node->value.list.node_count;
        box->glue = node->value.list.glue;
        return 0;
    }
    if (field->kind == (uint8_t)HSTEX_MATH_FIELD_EMPTY) {
        return 0;
    }
    struct hstex_math_builder single = {0};
    single.forced_class = -1;
    single.style = style;
    struct hstex_noad noad = {
        .kind = (uint8_t)HSTEX_NOAD_ATOM,
        .atom_class = (uint8_t)HSTEX_ATOM_ORD,
        .nucleus = *field,
    };
    if (reserve_noads(&single, 1U, error, error_capacity) != 0) {
        return -1;
    }
    single.noads[0] = noad;
    single.count = 1U;
    struct hstex_hbox_builder packed = {0};
    struct hstex_hbox_builder *previous = engine->active_hbox_builder;
    engine->active_hbox_builder = &packed;
    int status = translate_math_list(engine, &single, error, error_capacity);
    engine->active_hbox_builder = previous;
    if (status == 0) {
        status = finalize_hbox(engine, &packed, false, false, 0, box, error,
                               error_capacity);
    }
    free(packed.node_identifiers);
    free(single.noads);
    if (status != 0) {
        return status;
    }
    return 0;
}

static int store_box_node(struct hstex_engine *engine,
                          const struct hstex_box *box, int32_t shift,
                          uint32_t *identifier, char *error,
                          size_t error_capacity)
{
    struct hstex_node node = {
        .kind = HSTEX_NODE_LIST,
        .width = box->width,
        .height = box->height,
        .depth = box->depth,
        .shift = shift,
        .value.list = {
            .node_start = box->node_start,
            .node_count = box->node_count,
            .box_kind = box->kind,
            .glue = box->glue,
        },
    };
    return store_node(engine, &node, identifier, error, error_capacity);
}

/* A family-two parameter at a given size. */
static int math_symbol_parameter(struct hstex_engine *engine, uint8_t size,
                                 size_t parameter, int32_t *value, char *error,
                                 size_t error_capacity)
{
    const struct hstex_font *symbols = math_family_font(engine, size, 2U);
    if (symbols == NULL || symbols->dimen_count < parameter) {
        return set_error(error, error_capacity,
                         "math family two needs at least %zu parameters in "
                         "this size",
                         parameter);
    }
    *value = symbols->dimens[parameter - 1U];
    return 0;
}

static int math_extension_parameter(struct hstex_engine *engine, uint8_t size,
                                    size_t parameter, int32_t *value,
                                    char *error, size_t error_capacity)
{
    const struct hstex_font *extension = math_family_font(engine, size, 3U);
    if (extension == NULL || extension->dimen_count < parameter) {
        return set_error(error, error_capacity,
                         "math family three needs at least %zu parameters in "
                         "this size",
                         parameter);
    }
    *value = extension->dimens[parameter - 1U];
    return 0;
}

/* Attach the scripts of one atom, after its nucleus has been contributed.
   All of the arithmetic here was measured; see docs/DECISIONS.md,
   math-scripts. */
static int attach_math_scripts(struct hstex_engine *engine,
                               const struct hstex_noad *noad, uint8_t style,
                               int32_t nucleus_height, int32_t nucleus_depth,
                               bool nucleus_is_character, int32_t italic,
                               char *error, size_t error_capacity)
{
    bool has_superscript = noad->superscript.kind !=
                           (uint8_t)HSTEX_MATH_FIELD_EMPTY ||
                           noad->superscript.node != 0U;
    bool has_subscript =
        noad->subscript.kind != (uint8_t)HSTEX_MATH_FIELD_EMPTY ||
        noad->subscript.node != 0U;
    if (!has_superscript && !has_subscript) {
        return italic == 0
                   ? 0
                   : emit_math_kern(engine, italic, false, error,
                                    error_capacity);
    }
    /* The italic correction is a kern of its own only when there is no
       subscript; otherwise it displaces the superscript instead. */
    int32_t delta = italic;
    if (!has_subscript && delta != 0) {
        if (emit_math_kern(engine, delta, false, error, error_capacity) !=
            0) {
            return -1;
        }
        delta = 0;
    }

    uint8_t size = math_size_of_style(style);
    uint8_t superscript_style = math_superscript_style(style);
    uint8_t subscript_style = math_subscript_style(style);
    uint8_t script_size = math_size_of_style(superscript_style);

    int32_t shift_up = 0;
    int32_t shift_down = 0;
    if (!nucleus_is_character) {
        int32_t superscript_drop = 0;
        int32_t subscript_drop = 0;
        if (math_symbol_parameter(engine, script_size, 18U, &superscript_drop,
                                  error, error_capacity) != 0 ||
            math_symbol_parameter(engine, script_size, 19U, &subscript_drop,
                                  error, error_capacity) != 0) {
            return -1;
        }
        shift_up = nucleus_height - superscript_drop;
        shift_down = nucleus_depth + subscript_drop;
    }

    int32_t x_height = 0;
    if (math_symbol_parameter(engine, size, 5U, &x_height, error,
                              error_capacity) != 0) {
        return -1;
    }
    int32_t x_height_magnitude = x_height < 0 ? -x_height : x_height;
    int32_t scriptspace = engine->dimen_parameters[HSTEX_DIMEN_SCRIPT_SPACE];

    struct hstex_box superscript = {0};
    struct hstex_box subscript = {0};
    if (has_superscript &&
        math_field_box(engine, &noad->superscript, superscript_style,
                       &superscript, error, error_capacity) != 0) {
        return -1;
    }
    if (has_subscript &&
        math_field_box(engine, &noad->subscript, subscript_style, &subscript,
                       error, error_capacity) != 0) {
        return -1;
    }
    superscript.width += scriptspace;
    subscript.width += scriptspace;

    if (!has_superscript) {
        int32_t floor_one = 0;
        if (math_symbol_parameter(engine, size, 16U, &floor_one, error,
                                  error_capacity) != 0) {
            return -1;
        }
        if (shift_down < floor_one) {
            shift_down = floor_one;
        }
        int32_t clearance =
            subscript.height - (int32_t)(((int64_t)x_height_magnitude * 4) / 5);
        if (shift_down < clearance) {
            shift_down = clearance;
        }
        uint32_t identifier = 0U;
        return store_box_node(engine, &subscript, shift_down, &identifier,
                              error, error_capacity) != 0
                   ? -1
                   : append_hbox_item(engine, identifier, error,
                                      error_capacity);
    }

    /* A cramped style takes the third superscript parameter, display style
       the first, and everything else the second. See docs/DECISIONS.md,
       superscripts-in-display-style. */
    uint32_t superscript_parameter =
        (style % 2U) != 0U ? 15U
                           : (style < (uint8_t)HSTEX_STYLE_TEXT ? 13U : 14U);
    int32_t superscript_floor = 0;
    if (math_symbol_parameter(engine, size, superscript_parameter,
                              &superscript_floor, error, error_capacity) != 0) {
        return -1;
    }
    if (shift_up < superscript_floor) {
        shift_up = superscript_floor;
    }
    int32_t clearance = superscript.depth + x_height_magnitude / 4;
    if (shift_up < clearance) {
        shift_up = clearance;
    }

    if (!has_subscript) {
        uint32_t identifier = 0U;
        return store_box_node(engine, &superscript, -shift_up, &identifier,
                              error, error_capacity) != 0
                   ? -1
                   : append_hbox_item(engine, identifier, error,
                                      error_capacity);
    }

    int32_t floor_two = 0;
    int32_t rule_thickness = 0;
    if (math_symbol_parameter(engine, size, 17U, &floor_two, error,
                              error_capacity) != 0 ||
        math_extension_parameter(engine, size, 8U, &rule_thickness, error,
                                 error_capacity) != 0) {
        return -1;
    }
    if (shift_down < floor_two) {
        shift_down = floor_two;
    }
    int64_t gap = (int64_t)4 * rule_thickness -
                  (((int64_t)shift_up - superscript.depth) -
                   ((int64_t)subscript.height - shift_down));
    if (gap > 0) {
        shift_down += (int32_t)gap;
        int64_t rise = ((int64_t)x_height_magnitude * 4) / 5 -
                       ((int64_t)shift_up - superscript.depth);
        if (rise > 0) {
            shift_up += (int32_t)rise;
            shift_down -= (int32_t)rise;
        }
    }

    /* The two scripts stack in a vertical list: the superscript on top,
       displaced right by the nucleus's italic correction, then a kern that
       holds them the computed distance apart, then the subscript. */
    int32_t separation = (shift_up - superscript.depth) -
                         (subscript.height - shift_down);
    uint32_t superscript_node = 0U;
    uint32_t subscript_node = 0U;
    uint32_t kern_node = 0U;
    struct hstex_node kern = {
        .kind = HSTEX_NODE_KERN,
        .width = separation,
    };
    if (store_box_node(engine, &superscript, delta, &superscript_node, error,
                       error_capacity) != 0 ||
        store_node(engine, &kern, &kern_node, error, error_capacity) != 0 ||
        store_box_node(engine, &subscript, 0, &subscript_node, error,
                       error_capacity) != 0) {
        return -1;
    }
    uint32_t items[3] = {superscript_node, kern_node, subscript_node};
    if (engine->list_item_count > (size_t)UINT32_MAX - 3U ||
        reserve_list_items(engine, engine->list_item_count + 3U, error,
                           error_capacity) != 0) {
        return -1;
    }
    struct hstex_box stack = {0};
    stack.kind = HSTEX_BOX_VLIST;
    stack.node_start = (uint32_t)engine->list_item_count;
    stack.node_count = 3U;
    for (size_t index = 0U; index < 3U; ++index) {
        engine->list_items[engine->list_item_count++] = items[index];
    }
    /* A vertical package reaches from the top of the first box down to the
       baseline of the last, and carries the last box's depth below it. */
    stack.height = superscript.height + superscript.depth + separation +
                   subscript.height;
    stack.depth = subscript.depth;
    int32_t left = superscript.width + delta;
    stack.width = left > subscript.width ? left : subscript.width;
    uint32_t identifier = 0U;
    return store_box_node(engine, &stack, shift_down, &identifier, error,
                          error_capacity) != 0
               ? -1
               : append_hbox_item(engine, identifier, error, error_capacity);
}

/* Translate one finished math list into the horizontal list the engine is
   building. The caller has already pointed active_hbox_builder at it. */
/* Put the branch of every \mathchoice that the style in force asks for in
   the list's place, before anything else is done with the list. A branch may
   hold a \mathchoice of its own, so the list is swept until none is left. */
static int expand_math_choices(struct hstex_engine *engine,
                               struct hstex_math_builder *builder, char *error,
                               size_t error_capacity)
{
    for (size_t sweep = 0U; sweep < 64U; ++sweep) {
        bool any = false;
        for (size_t index = 0U; index < builder->count; ++index) {
            if (builder->noads[index].kind == (uint8_t)HSTEX_NOAD_CHOICE) {
                any = true;
                break;
            }
        }
        if (!any) {
            return 0;
        }
        struct hstex_math_builder out = {0};
        uint8_t style = builder->style;
        int status = 0;
        for (size_t index = 0U; status == 0 && index < builder->count;
             ++index) {
            const struct hstex_noad *noad = &builder->noads[index];
            if (noad->kind == (uint8_t)HSTEX_NOAD_STYLE) {
                style = noad->atom_class;
            }
            if (noad->kind != (uint8_t)HSTEX_NOAD_CHOICE) {
                if (reserve_noads(&out, out.count + 1U, error,
                                  error_capacity) != 0) {
                    status = -1;
                    break;
                }
                out.noads[out.count++] = *noad;
                continue;
            }
            uint32_t record = noad->choices[style / 2U];
            if (record == 0U ||
                (size_t)record > engine->math_sublist_count) {
                continue;
            }
            const struct hstex_math_sublist *chosen =
                &engine->math_sublists[record - 1U];
            if (chosen->has_fraction) {
                /* A branch that is a fraction cannot be spliced, because a
                   fraction is a property of the list it ends: it goes in as
                   one atom, to be set when the style is known. */
                struct hstex_noad atom = {
                    .kind = (uint8_t)HSTEX_NOAD_ATOM,
                    .atom_class = (uint8_t)HSTEX_ATOM_INNER,
                    .nucleus = {.kind = (uint8_t)HSTEX_MATH_FIELD_BOX,
                                .sublist = record,
                                .list_style = (uint8_t)0xFFU},
                };
                if (reserve_noads(&out, out.count + 1U, error,
                                  error_capacity) != 0) {
                    status = -1;
                    break;
                }
                out.noads[out.count++] = atom;
                continue;
            }
            if (chosen->count == 0U) {
                continue;
            }
            if (reserve_noads(&out, out.count + chosen->count, error,
                              error_capacity) != 0) {
                status = -1;
                break;
            }
            memcpy(&out.noads[out.count], engine->math_items + chosen->start,
                   chosen->count * sizeof(*out.noads));
            out.count += chosen->count;
        }
        if (status != 0) {
            free(out.noads);
            return -1;
        }
        free(builder->noads);
        builder->noads = out.noads;
        builder->count = out.count;
        builder->capacity = out.capacity;
    }
    return set_error(error, error_capacity,
                     "\\mathchoice branches nest too deeply");
}

static int translate_math_list_with(struct hstex_engine *engine,
                                    struct hstex_math_builder *builder,
                                    bool penalties, char *error,
                                    size_t error_capacity)
{
    /* A fraction is split before anything else, because each of its sides
       is set in a style of its own -- which is what decides a \mathchoice
       inside it. */
    if (builder->has_fraction) {
        return translate_math_fraction(engine, builder, error, error_capacity);
    }
    if (expand_math_choices(engine, builder, error, error_capacity) != 0) {
        return -1;
    }
    uint8_t style = builder->style;
    uint8_t size = math_size_of_style(style);
    bool all_spacing = style < (uint8_t)HSTEX_STYLE_SCRIPT;
    resolve_binary_atoms(builder);
    if (apply_math_ligatures(engine, builder, style, error, error_capacity) !=
        0) {
        return -1;
    }
    int previous_class = -1;
    /* A binary operator or a relation is a place the line may break, so the
       reference leaves a penalty behind it -- but not when what follows is
       itself a relation, and not when what follows is a penalty already:
       one place to break wants one penalty, and the list's own is the one
       that stands. See docs/DECISIONS.md, math-penalties. */
    int32_t pending_penalty = HSTEX_INFINITE_PENALTY;
    for (size_t index = 0U; index < builder->count; ++index) {
        struct hstex_noad *noad = &builder->noads[index];
        if (pending_penalty < HSTEX_INFINITE_PENALTY) {
            bool relation = noad->kind == (uint8_t)HSTEX_NOAD_ATOM &&
                            noad->atom_class == (uint8_t)HSTEX_ATOM_REL;
            if (!relation && noad->kind == (uint8_t)HSTEX_NOAD_NODE &&
                noad->node != 0U && noad->node <= engine->node_count &&
                engine->nodes[noad->node - 1U].kind == HSTEX_NODE_PENALTY) {
                relation = true;
            }
            if (!relation) {
                struct hstex_node node = {
                    .kind = HSTEX_NODE_PENALTY,
                    .value.penalty = pending_penalty,
                };
                if (append_hbox_node(engine, &node, error, error_capacity) !=
                    0) {
                    return -1;
                }
            }
            pending_penalty = HSTEX_INFINITE_PENALTY;
        }
        if (noad->kind == (uint8_t)HSTEX_NOAD_STYLE) {
            style = noad->atom_class;
            size = math_size_of_style(style);
            all_spacing = style < (uint8_t)HSTEX_STYLE_SCRIPT;
            continue;
        }
        if (noad->kind == (uint8_t)HSTEX_NOAD_RADICAL &&
            build_math_radical(engine, noad, style, error, error_capacity) !=
                0) {
            return -1;
        }
        if (noad->kind == (uint8_t)HSTEX_NOAD_ACCENT &&
            build_math_accent(engine, noad, style, error, error_capacity) !=
                0) {
            return -1;
        }
        if (noad->kind == (uint8_t)HSTEX_NOAD_FENCE &&
            build_math_fence(engine, noad, style, error, error_capacity) !=
                0) {
            return -1;
        }
        if ((noad->kind == (uint8_t)HSTEX_NOAD_OVERLINE ||
             noad->kind == (uint8_t)HSTEX_NOAD_UNDERLINE) &&
            build_math_line(engine, noad, style,
                            noad->kind == (uint8_t)HSTEX_NOAD_OVERLINE, error,
                            error_capacity) != 0) {
            return -1;
        }
        if (noad->kind == (uint8_t)HSTEX_NOAD_NONSCRIPT) {
            /* In a script the glue or kern that follows goes away with it;
               see docs/DECISIONS.md, nonscript. */
            if (style >= (uint8_t)HSTEX_STYLE_SCRIPT &&
                index + 1U < builder->count) {
                const struct hstex_noad *next = &builder->noads[index + 1U];
                bool removable =
                    next->kind == (uint8_t)HSTEX_NOAD_MU_GLUE ||
                    next->kind == (uint8_t)HSTEX_NOAD_MU_KERN;
                if (!removable && next->kind == (uint8_t)HSTEX_NOAD_NODE &&
                    next->node != 0U && next->node <= engine->node_count) {
                    enum hstex_node_kind following =
                        engine->nodes[next->node - 1U].kind;
                    removable = following == HSTEX_NODE_GLUE ||
                                following == HSTEX_NODE_KERN;
                }
                if (removable) {
                    ++index;
                }
            }
            /* The marker itself stays in the list whatever the style; see
               docs/DECISIONS.md, nonscript. */
            struct hstex_node marker = {
                .kind = HSTEX_NODE_GLUE,
                .value.glue = {.parameter = HSTEX_GLUE_NONSCRIPT},
            };
            if (append_hbox_node(engine, &marker, error, error_capacity) != 0) {
                return -1;
            }
            continue;
        }
        bool middle_atom = noad->kind == (uint8_t)HSTEX_NOAD_MIDDLE;
        if (middle_atom) {
            /* While the group is being measured the delimiter is not there
               yet; it takes its size from the whole group. */
            noad->kind = (uint8_t)HSTEX_NOAD_ATOM;
            noad->atom_class = (uint8_t)HSTEX_ATOM_CLOSE;
            memset(&noad->nucleus, 0, sizeof(noad->nucleus));
            if (engine->middle_delimiter_size >= 0) {
                struct hstex_box piece = {0};
                int32_t axis = 0;
                if (variant_delimiter(engine, noad->delimiter, size,
                                      engine->middle_delimiter_size, &piece,
                                      error, error_capacity) != 0 ||
                    math_symbol_parameter(engine, size, 22U, &axis, error,
                                          error_capacity) != 0) {
                    return -1;
                }
                uint32_t placed = 0U;
                if (store_box_node(engine, &piece,
                                   half_of((int64_t)piece.height -
                                           piece.depth) -
                                       axis,
                                   &placed, error, error_capacity) != 0) {
                    return -1;
                }
                noad->nucleus.kind = (uint8_t)HSTEX_MATH_FIELD_BOX;
                noad->nucleus.node = placed;
            }
        }
        if (noad->kind == (uint8_t)HSTEX_NOAD_NODE) {
            if (append_hbox_item(engine, noad->node, error, error_capacity) !=
                0) {
                return -1;
            }
            continue;
        }
        if (noad->kind == (uint8_t)HSTEX_NOAD_MU_GLUE ||
            noad->kind == (uint8_t)HSTEX_NOAD_MU_KERN) {
            int32_t unit = 0;
            if (math_unit(engine, size, &unit, error, error_capacity) != 0) {
                return -1;
            }
            int status =
                noad->kind == (uint8_t)HSTEX_NOAD_MU_GLUE
                    ? emit_math_glue(engine,
                                     math_glue_in_points(noad->glue, unit),
                                     error, error_capacity)
                    : emit_math_kern(engine, scaled_by_unit(noad->kern, unit),
                                     true, error, error_capacity);
            if (status != 0) {
                return -1;
            }
            continue;
        }
        if (previous_class >= 0) {
            uint8_t which =
                math_spacing_table[previous_class][noad->atom_class];
            if (which != 0U &&
                (all_spacing ||
                 math_spacing_all_styles[previous_class][noad->atom_class])) {
                static const size_t parameters[4] = {
                    0U,
                    (size_t)HSTEX_MUGLUE_THIN,
                    (size_t)HSTEX_MUGLUE_MEDIUM,
                    (size_t)HSTEX_MUGLUE_THICK,
                };
                int32_t unit = 0;
                if (math_unit(engine, size, &unit, error, error_capacity) !=
                    0) {
                    return -1;
                }
                struct hstex_glue amount = math_glue_in_points(
                    engine->muglue_parameters[parameters[which]], unit);
                if (emit_math_parameter_glue(engine, amount,
                                             parameters[which], error,
                                             error_capacity) != 0) {
                    return -1;
                }
            }
        }
        previous_class = middle_atom ? (int)HSTEX_ATOM_OPEN
                                     : (int)noad->atom_class;
        if (penalties && noad->kind == (uint8_t)HSTEX_NOAD_ATOM &&
            !middle_atom) {
            if (noad->atom_class == (uint8_t)HSTEX_ATOM_BIN) {
                pending_penalty =
                    engine->integer_parameters[HSTEX_INTEGER_BIN_OP_PENALTY];
            } else if (noad->atom_class == (uint8_t)HSTEX_ATOM_REL) {
                pending_penalty =
                    engine->integer_parameters[HSTEX_INTEGER_REL_PENALTY];
            }
        }

        int32_t nucleus_height = 0;
        int32_t nucleus_depth = 0;
        int32_t italic = 0;
        bool nucleus_is_character =
            noad->nucleus.kind == (uint8_t)HSTEX_MATH_FIELD_CHARACTER ||
            noad->nucleus.single_character != 0U;
        if (math_field_restyle(engine, &noad->nucleus, style, error,
                               error_capacity) != 0) {
            return -1;
        }
        nucleus_is_character =
            noad->nucleus.kind == (uint8_t)HSTEX_MATH_FIELD_CHARACTER ||
            noad->nucleus.single_character != 0U;
        if (noad->nucleus.kind == (uint8_t)HSTEX_MATH_FIELD_BOX) {
            if (noad->nucleus.node == 0U ||
                noad->nucleus.node > engine->node_count) {
                return set_error(error, error_capacity,
                                 "math list refers to a missing node");
            }
            struct hstex_node contributed = engine->nodes[noad->nucleus.node - 1U];
            /* A \vcenter is hung on the axis of the size it is SET at, which
               is settled here and not where it was written. */
            if (noad->vcentered) {
                int32_t axis = 0;
                if (math_symbol_parameter(engine, size, 22U, &axis, error,
                                          error_capacity) != 0) {
                    return -1;
                }
                int64_t total = (int64_t)contributed.height + contributed.depth;
                contributed.height = axis + half_of(total);
                contributed.depth = (int32_t)(total - contributed.height);
            }
            /* Only a large operator whose nucleus is a character of its
               own is centred on the axis; one that is a box -- \log, or a
               sub-formula that came to a box -- stands on the baseline. See
               docs/DECISIONS.md, only-a-character-is-centred. */
            /* A large operator carries its limits above and below in display
               style whatever its nucleus is; see docs/DECISIONS.md,
               large-operators. */
            if (noad->atom_class == (uint8_t)HSTEX_ATOM_OP &&
                (noad->limits == 1U ||
                 (noad->limits == 0U && style < (uint8_t)HSTEX_STYLE_TEXT))) {
                if (build_operator_limits(engine, noad, style, 0, &contributed,
                                          error, error_capacity) != 0 ||
                    append_hbox_node(engine, &contributed, error,
                                     error_capacity) != 0) {
                    return -1;
                }
                continue;
            }
            nucleus_height = contributed.height - contributed.shift;
            nucleus_depth = contributed.depth + contributed.shift;
            if (append_hbox_node(engine, &contributed, error, error_capacity) !=
                0) {
                return -1;
            }
        } else if (nucleus_is_character) {
            const struct hstex_font *font = NULL;
            const struct hstex_char_metric *metric = NULL;
            int present = math_character_metric(engine, &noad->nucleus, size,
                                                &font, &metric, true, error,
                                                error_capacity);
            if (present < 0) {
                return -1;
            }
            if (present == 0) {
                /* The font has no such character; the reference carries on
                   without it -- except for a large operator, which is set in
                   a box of its own whatever became of its nucleus, and the
                   box is hung on the axis even when it is empty. Measured
                   with a family whose font has not got the character: an
                   \mathop draws `\hbox(0.0+0.0)x0.0, shifted -2.5' where
                   the axis is 2.5pt, and every other class -- ord, bin, rel,
                   open, close, punct, inner -- draws nothing at all. trip
                   line 275 writes `\mathop y' in a font with no y, and that
                   empty box is the one thing its second pass drew that this
                   engine did not. See docs/DECISIONS.md, large-operators. */
                if (noad->atom_class == (uint8_t)HSTEX_ATOM_OP) {
                    struct hstex_node empty = {
                        .kind = HSTEX_NODE_LIST,
                        .value.list = {.box_kind = (uint8_t)HSTEX_BOX_HLIST},
                    };
                    if (centre_on_axis(engine, size, &empty, error,
                                       error_capacity) != 0) {
                        return -1;
                    }
                    if (noad->limits == 1U ||
                        (noad->limits == 0U &&
                         style < (uint8_t)HSTEX_STYLE_TEXT)) {
                        if (build_operator_limits(engine, noad, style, 0,
                                                  &empty, error,
                                                  error_capacity) != 0 ||
                            append_hbox_node(engine, &empty, error,
                                             error_capacity) != 0) {
                            return -1;
                        }
                        continue;
                    }
                    if (append_hbox_node(engine, &empty, error,
                                         error_capacity) != 0 ||
                        attach_math_scripts(engine, noad, style,
                                            empty.height - empty.shift,
                                            empty.depth + empty.shift, false,
                                            0, error, error_capacity) != 0) {
                        return -1;
                    }
                    continue;
                }
                if (attach_math_scripts(engine, noad, style, 0, 0, true, 0,
                                        error, error_capacity) != 0) {
                    return -1;
                }
                continue;
            }
            struct hstex_node node = {
                .kind = HSTEX_NODE_CHARACTER,
                .width = metric->width,
                .height = metric->height,
                .depth = metric->depth,
                .value.character = {
                    .font = engine->math_fonts[size][noad->nucleus.family],
                    .character = noad->nucleus.character,
                },
            };
            italic = metric->italic;
            if (noad->atom_class == (uint8_t)HSTEX_ATOM_OP) {
                /* A large operator is set in a box of its own, which sits on
                   the axis; in display style it takes a bigger shape, and
                   unless it is told otherwise its scripts go above and below
                   it there. See docs/DECISIONS.md, large-operators. */
                struct hstex_node boxed = {0};
                int32_t operator_delta = 0;
                if (build_operator_box(engine, noad, style, &operator_delta,
                                       &boxed, error, error_capacity) < 0) {
                    return -1;
                }
                bool stacked = noad->limits == 1U ||
                               (noad->limits == 0U &&
                                style < (uint8_t)HSTEX_STYLE_TEXT);
                bool has_below =
                    noad->subscript.kind != (uint8_t)HSTEX_MATH_FIELD_EMPTY;
                if (has_below && !stacked) {
                    boxed.width -= operator_delta;
                }
                if (centre_on_axis(engine, size, &boxed, error,
                                   error_capacity) != 0) {
                    return -1;
                }
                if (stacked) {
                    if (build_operator_limits(engine, noad, style,
                                              operator_delta, &boxed, error,
                                              error_capacity) != 0 ||
                        append_hbox_node(engine, &boxed, error,
                                         error_capacity) != 0) {
                        return -1;
                    }
                    continue;
                }
                nucleus_height = boxed.height - boxed.shift;
                nucleus_depth = boxed.depth + boxed.shift;
                nucleus_is_character = false;
                if (append_hbox_node(engine, &boxed, error, error_capacity) !=
                    0) {
                    return -1;
                }
                /* The italic correction is already in the operator's box,
                   so it never becomes a kern of its own; it only displaces a
                   superscript that shares the atom with a subscript. */
                if (attach_math_scripts(engine, noad, style, nucleus_height,
                                        nucleus_depth, false,
                                        has_below ? operator_delta : 0, error,
                                        error_capacity) != 0) {
                    return -1;
                }
                continue;
            }
            nucleus_height = node.height - node.shift;
            nucleus_depth = node.depth + node.shift;
            /* A character read as part of a word in a text font carries no
               italic correction; a font with no interword space of its own
               is a math font and does. */
            if (noad->text_character && font != NULL &&
                font->dimen_count >= 2U && font->dimens[1] != 0) {
                italic = 0;
            }
            if (append_hbox_node(engine, &node, error, error_capacity) != 0) {
                return -1;
            }
        }
        if (attach_math_scripts(engine, noad, style, nucleus_height,
                                nucleus_depth, nucleus_is_character, italic,
                                error, error_capacity) != 0) {
            return -1;
        }
    }
    return 0;
}

static int append_display_glue(struct hstex_engine *engine,
                               struct hstex_glue glue,
                               enum hstex_glue_parameter parameter,
                               char *error, size_t error_capacity)
{
    struct hstex_node node = {
        .kind = HSTEX_NODE_GLUE,
        .width = glue.width,
        .value.glue = {
            .stretch = glue.stretch,
            .shrink = glue.shrink,
            .stretch_order = glue.stretch_order,
            .shrink_order = glue.shrink_order,
            .parameter = 1U + (uint8_t)parameter,
        },
    };
    return append_vbox_node(engine, &node, error, error_capacity);
}

/* The width the last line before a display reaches to, which decides whether
   the display gets the short skips. Glue that can stretch or shrink before
   the last visible node makes the width indeterminate. See
   docs/DECISIONS.md, display-math. */
static int32_t pre_display_size(struct hstex_engine *engine,
                                const struct hstex_box *line, int32_t shift,
                                bool had_line)
{
    if (!had_line) {
        return -HSTEX_MAX_DIMEN;
    }
    const struct hstex_font *font =
        font_by_identifier(engine, engine->current_font);
    /* The reach starts where the line itself does; see docs/DECISIONS.md,
       the-size-before-a-display. */
    int64_t reach = shift;
    if (font != NULL && font->dimen_count >= 6U) {
        reach += (int64_t)2 * font->dimens[5];
    }
    int64_t width = -(int64_t)HSTEX_MAX_DIMEN;
    bool indeterminate = false;
    for (uint32_t offset = 0U; offset < line->node_count; ++offset) {
        size_t slot = (size_t)line->node_start + offset;
        if (slot >= engine->list_item_count) {
            break;
        }
        uint32_t identifier = engine->list_items[slot];
        if (identifier == 0U || identifier > engine->node_count) {
            break;
        }
        const struct hstex_node *node = &engine->nodes[identifier - 1U];
        int32_t amount = packed_dimen(node->width);
        switch (node->kind) {
        case HSTEX_NODE_CHARACTER:
        case HSTEX_NODE_LIGATURE:
        case HSTEX_NODE_RULE:
        case HSTEX_NODE_LIST:
            if (indeterminate) {
                return HSTEX_MAX_DIMEN;
            }
            reach += amount;
            width = reach;
            break;
        case HSTEX_NODE_GLUE:
            /* Glue that is taking part in the line's own stretching or
               shrinking makes the reach unknowable; glue that is not just
               counts. See docs/DECISIONS.md, the-size-before-a-display. */
            if (line->glue.sign == (uint8_t)HSTEX_GLUE_SIGN_STRETCHING) {
                if (node->value.glue.stretch_order == line->glue.order &&
                    node->value.glue.stretch != 0) {
                    indeterminate = true;
                }
            } else if (line->glue.sign ==
                       (uint8_t)HSTEX_GLUE_SIGN_SHRINKING) {
                if (node->value.glue.shrink_order == line->glue.order &&
                    node->value.glue.shrink != 0) {
                    indeterminate = true;
                }
            }
            reach += amount;
            /* Leaders are something to see, so they settle the reach. */
            if (node->value.glue.leader != 0U) {
                if (indeterminate) {
                    return HSTEX_MAX_DIMEN;
                }
                width = reach;
            }
            break;
        default:
            reach += amount;
            break;
        }
    }
    if (width < -(int64_t)HSTEX_MAX_DIMEN) {
        width = -(int64_t)HSTEX_MAX_DIMEN;
    }
    return (int32_t)width;
}

/* $$ in a paragraph ends the lines built so far, then sets the formula in
   display style. */
static int begin_display_math(struct hstex_engine *engine, char *error,
                              size_t error_capacity)
{
    struct hstex_box line = {0};
    /* A character still held back for the ligature program is part of the
       paragraph too: `\noindent A$$' has a line, and hstex was calling it
       empty because its one character had not reached the list yet. That
       made \predisplaysize -16383.99998pt -- the answer for no line at all
       -- where the reference gives 27.50005pt, the A's width and two quads.
       Two characters were enough to hide it, since the first is let go when
       the second arrives. */
    bool had_line = engine->paragraph_builder != NULL &&
                    (engine->paragraph_builder->count != 0U ||
                     engine->has_pending_character);
    /* The line before a display is a widow of a different kind. It is still
       a line of the paragraph, so a box that will not fit is reported
       against the line the paragraph began on. */
    if (engine->nest_count != 0U) {
        engine->paragraph_line =
            (int32_t)engine->nest[engine->nest_count - 1U].line;
    }
    engine->breaking_for_display = true;
    int broken = finish_paragraph_line(engine, &line, error, error_capacity);
    engine->breaking_for_display = false;
    if (broken != 0) {
        return -1;
    }
    /* THE PARAGRAPH'S OWN LEVEL IS DONE WITH. Its lines have reached the
       vertical list, and the display is a level of its own beside them
       rather than inside them -- so \showlists run in a display writes the
       display's list and the VERTICAL one under it, with the paragraph's
       \prevdepth and \prevgraf on that vertical level. A fresh level is
       pushed for the paragraph when the display gives it back. */
    nest_pop(engine);
    /* And the mode goes back to the list under it before anything notes it:
       a display inside a \vbox stands in an INTERNAL vertical list, and the
       level that holds it must be left saying so. */
    engine->mode = HSTEX_MODE_VERTICAL;
    engine->inner_mode = vertical_list_is_inner(engine);
    int32_t size = pre_display_size(
        engine, &line, line_shift_for(engine, engine->prev_graf),
        had_line);
    /* The display stands where the line after the paragraph so far would,
       plus one: the reference counts the display as taking two.  WHICH LINE
       THAT IS COMES FROM \prevgraf, which carries on past an earlier display
       in the same paragraph rather than counting only the lines just broken.
       See docs/DECISIONS.md, lines-carry-on-past-a-display. */
    int32_t where = engine->prev_graf + 2;
    (void)had_line;
    if (begin_group(engine, HSTEX_GROUP_MATH_SHIFT, error, error_capacity) != 0) {
        return -1;
    }
    /* \fam is set FIRST, before the three parameters, which is why the
       reference gives them back in the order \displayindent, \displaywidth,
       \predisplaysize, \fam when the display's group ends. */
    if (assign_integer_parameter(engine, (uint32_t)HSTEX_INTEGER_FAMILY, -1,
                                 false, error, error_capacity) != 0) {
        return -1;
    }
    /* The three parameters belong to the display: they are set inside its
       group and go back to what they were when it ends. */
    if (assign_dimen_parameter(engine, (uint32_t)HSTEX_DIMEN_PRE_DISPLAY_SIZE,
                               size, false, error, error_capacity) != 0 ||
        assign_dimen_parameter(engine, (uint32_t)HSTEX_DIMEN_DISPLAY_WIDTH,
                               line_width_for(engine, where), false, error,
                               error_capacity) != 0 ||
        assign_dimen_parameter(engine, (uint32_t)HSTEX_DIMEN_DISPLAY_INDENT,
                               line_shift_for(engine, where), false, error,
                               error_capacity) != 0) {
        return -1;
    }
    /* The lines of the paragraph so far have reached the vertical list, so
       the page builder runs before the formula is read -- and the output
       routine it fires sees the display's own parameters already set. See
       docs/DECISIONS.md, a-page-that-breaks-at-a-display. */
    if (contribute_page(engine, error, error_capacity) != 0) {
        return -1;
    }
    if (push_math_list(engine, (uint8_t)HSTEX_STYLE_DISPLAY, error,
                       error_capacity) != 0) {
        return -1;
    }
    engine->mode = HSTEX_MODE_MATH;
    engine->inner_mode = false;
    engine->displayed_math = true;
    uint32_t every = engine->token_parameters[HSTEX_TOKEN_EVERY_DISPLAY];
    if (every == 0U) {
        return 0;
    }
    const struct hstex_token_list *list = token_list_by_identifier(engine, every);
    struct hstex_source_location location = {0};
    if (list == NULL ||
        hstex_source_push_tokens(&engine->sources, list->tokens, list->count,
                                 location, error, error_capacity) != 0) {
        return set_error(error, error_capacity,
                         "could not install everydisplay tokens");
    }
    hstex_source_name_top(&engine->sources,
                          (uint8_t)HSTEX_TOKEN_SOURCE_TOKEN_PARAMETER,
                          (uint32_t)HSTEX_TOKEN_EVERY_DISPLAY);
    trace_token_parameter(engine, (size_t)HSTEX_TOKEN_EVERY_DISPLAY);
    return 0;
}

/* The closing $$ centres the formula in \displaywidth, surrounds it with the
   display penalties and skips, and lets the paragraph carry on. */
/* Translate the formula the engine has been reading into a box. */
static int package_displayed_formula(struct hstex_engine *engine, bool deleted,
                                     struct hstex_box *box, char *error,
                                     size_t error_capacity)
{
    struct hstex_math_builder *list = current_math_list(engine);
    if (list == NULL || engine->math_depth != engine->math_floor + 1U) {
        return set_error(error, error_capacity,
                         "a display closed inside a math group");
    }
    struct hstex_hbox_builder builder = {0};
    struct hstex_hbox_builder *previous = engine->active_hbox_builder;
    engine->active_hbox_builder = &builder;
    /* A display is deleted for want of the fonts to measure it against
       just as an inline formula is: what is packaged is then an empty box
       where the formula would have been.  WHETHER IT IS DELETED IS SETTLED
       BEFORE THE SECOND $ IS READ, and the setting itself happens after. */
    int status =
        deleted ? 0 : translate_math_list(engine, list, error, error_capacity);
    engine->active_hbox_builder = previous;
    if (status == 0) {
        status = finalize_hbox(engine, &builder, false, false, 0, box, error,
                               error_capacity);
    }
    free(builder.node_identifiers);
    pop_math_list(engine);
    return status;
}

/* Put one character in a box of its own, as wide as the character plus its
   italic correction. */
static int character_box(struct hstex_engine *engine, uint32_t font_identifier,
                         const struct hstex_font *font, uint8_t code,
                         struct hstex_box *box, char *error,
                         size_t error_capacity)
{
    const struct hstex_char_metric *metric = &font->characters[code];
    struct hstex_node node = {
        .kind = HSTEX_NODE_CHARACTER,
        .width = metric->width,
        .height = metric->height,
        .depth = metric->depth,
        .value.character = {.font = font_identifier, .character = code},
    };
    struct hstex_hbox_builder builder = {0};
    struct hstex_hbox_builder *previous = engine->active_hbox_builder;
    engine->active_hbox_builder = &builder;
    int status = append_hbox_node(engine, &node, error, error_capacity);
    engine->active_hbox_builder = previous;
    if (status == 0) {
        status = finalize_hbox(engine, &builder, false, false, 0, box, error,
                               error_capacity);
    }
    free(builder.node_identifiers);
    if (status == 0) {
        /* A box made for ONE CHARACTER takes the character's own three
           dimensions, not the ones packing them would settle: a character
           of negative height gives a box of negative height, where packing
           would have stopped at nought. See docs/DECISIONS.md,
           extensible-delimiters. */
        box->width = metric->width + metric->italic;
        box->height = metric->height;
        box->depth = metric->depth;
    }
    return status;
}

/* Stack the pieces of an extensible recipe until they reach `wanted`. */
static int extensible_box(struct hstex_engine *engine,
                          uint32_t font_identifier,
                          const struct hstex_font *font,
                          const struct hstex_extensible *recipe,
                          int32_t wanted, struct hstex_box *box, char *error,
                          size_t error_capacity)
{
    /* A recipe whose repeater is missing reaches only as far as its fixed
       pieces do. The reference builds what it can and says nothing; trip's
       own font leaves one such recipe behind.

       A repeater of CODE NOUGHT is a character like any other. It is only
       the three FIXED pieces that a nought stands for `none' in -- the
       repeater is asked for its size and its width whatever its code, and a
       recipe whose repeater is character 0 stacks character 0. See
       docs/DECISIONS.md, extensible-delimiters. */
    bool has_repeater = font->characters[recipe->repeated].tag >= 0;
    int64_t step = 0;
    if (has_repeater) {
        const struct hstex_char_metric *piece =
            &font->characters[recipe->repeated];
        step = (int64_t)piece->height + piece->depth;
    }
    int64_t reach = 0;
    uint8_t fixed[3] = {recipe->bottom, recipe->middle, recipe->top};
    for (size_t index = 0U; index < 3U; ++index) {
        if (fixed[index] != 0U && font->characters[fixed[index]].tag >= 0) {
            reach += (int64_t)font->characters[fixed[index]].height +
                     font->characters[fixed[index]].depth;
        }
    }
    size_t repeats = 0U;
    if (step > 0) {
        while (reach < wanted) {
            reach += step;
            ++repeats;
            if (recipe->middle != 0U) {
                reach += step;
            }
            if (repeats > 10000U) {
                return set_error(error, error_capacity,
                                 "an extensible delimiter did not converge");
            }
        }
    }

    /* The pieces go in from the bottom up, and the last one placed gives the
       box its height. */
    struct hstex_vbox_builder builder = {0};
    struct hstex_vbox_builder *previous_vbox = engine->active_vbox_builder;
    struct hstex_hbox_builder *previous_hbox = engine->active_hbox_builder;
    enum hstex_mode previous_mode = engine->mode;
    int32_t previous_depth = engine->prev_depth;
    engine->active_vbox_builder = &builder;
    engine->active_hbox_builder = NULL;
    engine->mode = HSTEX_MODE_VERTICAL;
    engine->prev_depth = HSTEX_IGNORE_DEPTH;

    int status = 0;
    int32_t top_height = 0;
    int64_t total = 0;
    bool first = true;
    /* Written from the top down: top, then the repeats and the middle, then
       the repeats again, then the bottom. */
    size_t written = 0U;
    for (size_t stage = 0U; status == 0 && stage < 5U; ++stage) {
        size_t times = 1U;
        uint8_t code = 0U;
        bool repeated = stage == 1U || stage == 3U;
        switch (stage) {
        case 0: code = recipe->top; break;
        case 1: code = recipe->repeated;
                times = recipe->middle != 0U ? repeats : 0U; break;
        case 2: code = recipe->middle; break;
        case 3: code = recipe->repeated; times = repeats; break;
        default: code = recipe->bottom; break;
        }
        if ((!repeated && code == 0U) || font->characters[code].tag < 0) {
            continue;
        }
        for (size_t index = 0U; status == 0 && index < times; ++index) {
            struct hstex_box piece_box = {0};
            status = character_box(engine, font_identifier, font, code,
                                   &piece_box, error, error_capacity);
            if (status != 0) {
                break;
            }
            if (first) {
                top_height = piece_box.height;
                first = false;
            }
            total += (int64_t)piece_box.height + piece_box.depth;
            ++written;
            struct hstex_node node = {
                .kind = HSTEX_NODE_LIST,
                .width = piece_box.width,
                .height = piece_box.height,
                .depth = piece_box.depth,
                .value.list = {
                    .node_start = piece_box.node_start,
                    .node_count = piece_box.node_count,
                    .box_kind = piece_box.kind,
                    .glue = piece_box.glue,
                },
            };
            /* The pieces are stacked flush, with no interline glue between
               them; see docs/DECISIONS.md, extensible-delimiters. */
            engine->prev_depth = HSTEX_IGNORE_DEPTH;
            status = append_vbox_node(engine, &node, error, error_capacity);
        }
    }
    (void)written;
    struct hstex_box packed = {0};
    if (status == 0) {
        status = finalize_vbox(engine, &builder, false, false, 0, &packed,
                               error, error_capacity);
    }
    free(builder.node_identifiers);
    engine->active_vbox_builder = previous_vbox;
    engine->active_hbox_builder = previous_hbox;
    engine->mode = previous_mode;
    engine->prev_depth = previous_depth;
    if (status != 0) {
        return -1;
    }
    packed.height = top_height;
    packed.depth = (int32_t)(total - top_height);
    /* The width is the repeater's, or -- when there is none -- that of
       whichever fixed piece the recipe does have. */
    uint8_t widest = recipe->repeated;
    bool found_widest = has_repeater;
    if (!found_widest) {
        uint8_t order[3] = {recipe->bottom, recipe->middle, recipe->top};
        for (size_t index = 0U; index < 3U; ++index) {
            if (order[index] != 0U &&
                font->characters[order[index]].tag >= 0) {
                widest = order[index];
                found_widest = true;
                break;
            }
        }
    }
    if (found_widest) {
        const struct hstex_char_metric *shape = &font->characters[widest];
        packed.width = shape->width + shape->italic;
    }
    *box = packed;
    return 0;
}

/* Find a delimiter at least `wanted` tall: walk the small variant's chain of
   larger versions, then the large variant's, and fall back to building one
   out of pieces. See docs/DECISIONS.md, extensible-delimiters. */
static int variant_delimiter(struct hstex_engine *engine, int32_t code,
                             uint8_t size, int32_t wanted,
                             struct hstex_box *box, char *error,
                             size_t error_capacity)
{
    uint8_t families[2] = {(uint8_t)((code >> 20) & 0xF),
                           (uint8_t)((code >> 8) & 0xF)};
    uint8_t characters[2] = {(uint8_t)((code >> 12) & 0xFF),
                             (uint8_t)(code & 0xFF)};
    const struct hstex_font *best_font = NULL;
    uint32_t best_identifier = 0U;
    uint8_t best_character = 0U;
    /* A VARIANT OF NO SIZE AT ALL IS NO VARIANT: the reference keeps the
       tallest it has seen and starts that at nought, so a character whose
       height and depth are both nought never becomes the choice and the
       delimiter comes out as an empty box of \nulldelimiterspace. */
    int64_t best_reach = 0;
    bool extensible = false;

    for (size_t attempt = 0U; attempt < 2U && !extensible; ++attempt) {
        if (families[attempt] == 0U && characters[attempt] == 0U) {
            continue;
        }
        for (int32_t which = (int32_t)size; which >= 0; --which) {
            uint32_t identifier =
                engine->math_fonts[which][families[attempt]];
            const struct hstex_font *font =
                font_by_identifier(engine, identifier);
            if (font == NULL || font->characters == NULL) {
                continue;
            }
            uint8_t character = characters[attempt];
            for (size_t step = 0U; step < 256U; ++step) {
                const struct hstex_char_metric *metric =
                    &font->characters[character];
                if (metric->tag < 0) {
                    break;
                }
                if (metric->tag == 3) {
                    best_font = font;
                    best_identifier = identifier;
                    best_character = character;
                    extensible = true;
                    break;
                }
                int64_t reach = (int64_t)metric->height + metric->depth;
                if (reach > best_reach) {
                    best_font = font;
                    best_identifier = identifier;
                    best_character = character;
                    best_reach = reach;
                    if (reach >= wanted) {
                        break;
                    }
                }
                if (metric->tag != 2) {
                    break;
                }
                character = (uint8_t)metric->remainder;
            }
            if (extensible || (best_font != NULL && best_reach >= wanted)) {
                break;
            }
        }
        if (extensible || (best_font != NULL && best_reach >= wanted)) {
            break;
        }
    }

    memset(box, 0, sizeof(*box));
    box->kind = HSTEX_BOX_HLIST;
    if (best_font == NULL) {
        /* No variant at all: an empty box of \nulldelimiterspace. */
        box->width = engine->dimen_parameters[HSTEX_DIMEN_NULL_DELIMITER_SPACE];
        return 0;
    }
    if (extensible) {
        const struct hstex_char_metric *metric =
            &best_font->characters[best_character];
        if ((size_t)metric->remainder >= best_font->extensible_count) {
            return set_error(error, error_capacity,
                             "extensible recipe %d is out of range",
                             metric->remainder);
        }
        return extensible_box(
            engine, best_identifier, best_font,
            &best_font->extensibles[(size_t)metric->remainder], wanted, box,
            error, error_capacity);
    }
    return character_box(engine, best_identifier, best_font, best_character,
                         box, error, error_capacity);
}

/* The style a fraction sets its numerator in, and its denominator, which is
   the cramped variant of the same size. Both were measured with
   \mathchoice; see docs/DECISIONS.md, fractions. */
static uint8_t math_numerator_style(uint8_t style)
{
    return (uint8_t)(style + 2U - 2U * (style / 6U));
}

static uint8_t math_denominator_style(uint8_t style)
{
    return (uint8_t)(2U * (style / 2U) + 3U - 2U * (style / 6U));
}

/* The cramped variant of a style: the same size, with superscripts kept
   lower. */
static uint8_t math_cramped_style(uint8_t style)
{
    return (uint8_t)(style | 1U);
}

/* Set part of a math list -- one side of a fraction -- as a box of its own. */
static int math_range_box(struct hstex_engine *engine,
                          const struct hstex_math_builder *builder,
                          size_t begin, size_t end, uint8_t style,
                          struct hstex_box *box, char *error,
                          size_t error_capacity)
{
    struct hstex_math_builder part = {0};
    part.forced_class = -1;
    part.style = style;
    part.current_style = style;
    size_t count = end - begin;
    if (count != 0U) {
        if (reserve_noads(&part, count, error, error_capacity) != 0) {
            return -1;
        }
        memcpy(part.noads, builder->noads + begin,
               count * sizeof(*part.noads));
        part.count = count;
    }
    struct hstex_hbox_builder packed = {0};
    struct hstex_hbox_builder *previous = engine->active_hbox_builder;
    enum hstex_mode previous_mode = engine->mode;
    engine->active_hbox_builder = &packed;
    engine->mode = HSTEX_MODE_HORIZONTAL;
    int status = translate_math_list(engine, &part, error, error_capacity);
    engine->active_hbox_builder = previous;
    engine->mode = previous_mode;
    if (status == 0) {
        status = finalize_hbox(engine, &packed, false, false, 0, box, error,
                               error_capacity);
    }
    free(packed.node_identifiers);
    free(part.noads);
    /* A side that came to one unshifted box is that box; see
       docs/DECISIONS.md, a-list-that-is-one-box. */
    if (status == 0 && box->node_count == 1U &&
        (size_t)box->node_start < engine->list_item_count) {
        uint32_t item = engine->list_items[box->node_start];
        if (item != 0U && (size_t)item <= engine->node_count &&
            engine->nodes[item - 1U].kind == HSTEX_NODE_LIST &&
            engine->nodes[item - 1U].shift == 0) {
            const struct hstex_node *only = &engine->nodes[item - 1U];
            box->kind = only->value.list.box_kind;
            box->width = only->width;
            box->height = only->height;
            box->depth = only->depth;
            box->node_start = only->value.list.node_start;
            box->node_count = only->value.list.node_count;
            box->glue = only->value.list.glue;
        }
    }
    return status;
}

/* Widen a box to match the other side of the fraction, its contents centred
   between two \hss. A box with nothing in it is simply declared wider. */
static int math_rebox(struct hstex_engine *engine, struct hstex_box *box,
                      int32_t width, char *error, size_t error_capacity)
{
    if (box->width == width) {
        return 0;
    }
    if (box->node_count == 0U) {
        box->width = width;
        return 0;
    }
    struct hstex_hbox_builder builder = {0};
    struct hstex_hbox_builder *previous = engine->active_hbox_builder;
    enum hstex_mode previous_mode = engine->mode;
    engine->active_hbox_builder = &builder;
    engine->mode = HSTEX_MODE_HORIZONTAL;
    struct hstex_node fill = {
        .kind = HSTEX_NODE_GLUE,
        .value.glue = {
            .stretch = INT32_C(65536),
            .shrink = INT32_C(65536),
            .stretch_order = 1U,
            .shrink_order = 1U,
        },
    };
    int status = append_hbox_node(engine, &fill, error, error_capacity);
    if (status == 0 && box->kind == HSTEX_BOX_VLIST) {
        /* A vertical list is set beside the glue whole; only a horizontal one
           is unpacked. See docs/DECISIONS.md, a-side-that-stands-upright. */
        status = append_box_node(engine, box, error, error_capacity);
    } else {
        for (uint32_t offset = 0U; status == 0 && offset < box->node_count;
             ++offset) {
            size_t slot = (size_t)box->node_start + offset;
            if (slot >= engine->list_item_count) {
                status = set_error(error, error_capacity,
                                   "a fraction lost part of its list");
                break;
            }
            status = append_hbox_item(engine, engine->list_items[slot], error,
                                      error_capacity);
        }
    }
    if (status == 0) {
        status = append_hbox_node(engine, &fill, error, error_capacity);
    }
    struct hstex_box packed = {0};
    if (status == 0) {
        status = finalize_hbox(engine, &builder, true, false, width, &packed,
                               error, error_capacity);
    }
    free(builder.node_identifiers);
    engine->active_hbox_builder = previous;
    engine->mode = previous_mode;
    if (status == 0) {
        *box = packed;
    }
    return status;
}

/* \radical puts a sign of its own height beside the radicand, with a rule
   over it. All of the arithmetic here was measured; see docs/DECISIONS.md,
   radicals. */
static int build_math_radical(struct hstex_engine *engine,
                              struct hstex_noad *noad, uint8_t style,
                              char *error, size_t error_capacity)
{
    uint8_t size = math_size_of_style(style);
    int32_t thickness = 0;
    if (math_extension_parameter(engine, size, 8U, &thickness, error,
                                 error_capacity) != 0) {
        return -1;
    }
    struct hstex_box radicand = {0};
    if (math_field_box(engine, &noad->nucleus, math_cramped_style(style),
                       &radicand, error, error_capacity) != 0) {
        return -1;
    }
    /* How much room to leave over the radicand: a quarter of the x height in
       display, a quarter of the rule's own thickness otherwise. */
    int32_t reference = thickness;
    if (style < (uint8_t)HSTEX_STYLE_TEXT &&
        math_symbol_parameter(engine, size, 5U, &reference, error,
                              error_capacity) != 0) {
        return -1;
    }
    if (reference < 0) {
        reference = -reference;
    }
    int64_t clearance = (int64_t)thickness + reference / 4;
    int64_t wanted =
        (int64_t)radicand.height + radicand.depth + clearance + thickness;
    if (wanted > HSTEX_MAX_DIMEN) {
        wanted = HSTEX_MAX_DIMEN;
    }
    struct hstex_box sign = {0};
    if (variant_delimiter(engine, noad->delimiter, size, (int32_t)wanted,
                          &sign, error, error_capacity) != 0) {
        return -1;
    }
    /* A sign taller than it needs to be spreads the extra room evenly. */
    int64_t excess = (int64_t)sign.depth -
                     ((int64_t)radicand.height + radicand.depth + clearance);
    if (excess > 0) {
        clearance += half_of(excess);
    }

    struct hstex_vbox_builder body = {0};
    struct hstex_vbox_builder *previous_vbox = engine->active_vbox_builder;
    enum hstex_mode previous_mode = engine->mode;
    engine->active_vbox_builder = &body;
    /* A list built here is not the one \prevdepth belongs to. */
    int32_t enclosing_depth = engine->prev_depth;
    engine->prev_depth = HSTEX_IGNORE_DEPTH;
    engine->mode = HSTEX_MODE_VERTICAL;
    /* The bar over the radicand is as thick as the sign is tall, and sits
       that same distance below the top of the whole thing; the default rule
       thickness only decides how much room is left over the radicand. */
    struct hstex_node above = {.kind = HSTEX_NODE_KERN, .width = sign.height};
    struct hstex_node rule = {
        .kind = HSTEX_NODE_RULE,
        .width = HSTEX_RUNNING_DIMEN,
        .height = sign.height,
        .depth = 0,
    };
    struct hstex_node gap = {.kind = HSTEX_NODE_KERN,
                             .width = (int32_t)clearance};
    uint32_t identifier = 0U;
    int status = append_vbox_node(engine, &above, error, error_capacity);
    if (status == 0) {
        status = append_vbox_node(engine, &rule, error, error_capacity);
    }
    if (status == 0) {
        status = append_vbox_node(engine, &gap, error, error_capacity);
    }
    if (status == 0 &&
        (store_box_node(engine, &radicand, 0, &identifier, error,
                        error_capacity) != 0 ||
         append_vbox_item(engine, identifier, error, error_capacity) != 0)) {
        status = -1;
    }
    struct hstex_box over = {0};
    if (status == 0) {
        status = finalize_vbox(engine, &body, false, false, 0, &over, error,
                               error_capacity);
    }
    free(body.node_identifiers);
    engine->active_vbox_builder = previous_vbox;
    engine->prev_depth = enclosing_depth;
    engine->mode = previous_mode;
    if (status != 0) {
        return -1;
    }
    over.width = radicand.width;
    over.height = (int32_t)(2 * (int64_t)sign.height + clearance +
                            radicand.height);
    over.depth = radicand.depth;

    struct hstex_hbox_builder whole = {0};
    struct hstex_hbox_builder *previous = engine->active_hbox_builder;
    engine->active_hbox_builder = &whole;
    engine->mode = HSTEX_MODE_HORIZONTAL;
    status = 0;
    int32_t shift =
        (int32_t)(-((int64_t)radicand.height + clearance));
    identifier = 0U;
    if (store_box_node(engine, &sign, shift, &identifier, error,
                       error_capacity) != 0 ||
        append_hbox_item(engine, identifier, error, error_capacity) != 0 ||
        store_box_node(engine, &over, 0, &identifier, error,
                       error_capacity) != 0 ||
        append_hbox_item(engine, identifier, error, error_capacity) != 0) {
        status = -1;
    }
    struct hstex_box packed = {0};
    if (status == 0) {
        status = finalize_hbox(engine, &whole, false, false, 0, &packed, error,
                               error_capacity);
    }
    free(whole.node_identifiers);
    engine->active_hbox_builder = previous;
    engine->mode = previous_mode;
    if (status != 0) {
        return -1;
    }
    identifier = 0U;
    if (store_box_node(engine, &packed, 0, &identifier, error,
                       error_capacity) != 0) {
        return -1;
    }
    noad->kind = (uint8_t)HSTEX_NOAD_ATOM;
    noad->atom_class = (uint8_t)HSTEX_ATOM_ORD;
    memset(&noad->nucleus, 0, sizeof(noad->nucleus));
    noad->nucleus.kind = (uint8_t)HSTEX_MATH_FIELD_BOX;
    noad->nucleus.node = identifier;
    return 0;
}

/* The kern the nucleus's font gives against its skew character, which is how
   far the accent slides to the right. */
static int accent_skew(struct hstex_engine *engine,
                       struct hstex_math_field *nucleus, uint8_t size,
                       int32_t *skew, char *error, size_t error_capacity)
{
    *skew = 0;
    if (nucleus->kind != (uint8_t)HSTEX_MATH_FIELD_CHARACTER) {
        return 0;
    }
    const struct hstex_font *font = NULL;
    const struct hstex_char_metric *metric = NULL;
    int present = math_character_metric(engine, nucleus, size, &font, &metric,
                                        true,
                                        error, error_capacity);
    if (present <= 0) {
        return present;
    }
    if (font->skew_character < 0 || font->skew_character > 255) {
        return 0;
    }
    struct hstex_lig_kern_result step;
    if (font_lig_kern(font, (uint8_t)nucleus->character,
                      (uint8_t)font->skew_character, &step, error,
                      error_capacity) != 0) {
        return -1;
    }
    if (step.kind == HSTEX_LIG_KERN_KERN) {
        *skew = step.kern;
    }
    return 0;
}

static int rebox_limit(struct hstex_engine *engine, struct hstex_box *box,
                       int32_t width, char *error, size_t error_capacity);

/* The limits of a large operator, set above and below it; see
   docs/DECISIONS.md, large-operators. */
static int build_operator_limits(struct hstex_engine *engine,
                                 struct hstex_noad *noad, uint8_t style,
                                 int32_t delta, struct hstex_node *boxed,
                                 char *error, size_t error_capacity)
{
    uint8_t size = math_size_of_style(style);
    const struct hstex_font *extension = math_family_font(engine, size, 3U);
    if (extension == NULL || extension->dimen_count < 13U) {
        return set_error(error, error_capacity,
                         "a large operator's limits need \\textfont3 with "
                         "thirteen parameters");
    }
    int32_t spacing[5];
    for (size_t index = 0U; index < 5U; ++index) {
        spacing[index] = extension->dimens[8U + index];
    }
    /* The operator's own box, packaged again when it carries a shift; an
       unshifted one is already clean. */
    struct hstex_box middle = {0};
    if (boxed->shift == 0) {
        middle.kind = boxed->value.list.box_kind;
        middle.width = boxed->width;
        middle.height = boxed->height;
        middle.depth = boxed->depth;
        middle.node_start = boxed->value.list.node_start;
        middle.node_count = boxed->value.list.node_count;
        middle.glue = boxed->value.list.glue;
    } else {
        struct hstex_hbox_builder builder = {0};
        struct hstex_hbox_builder *previous = engine->active_hbox_builder;
        enum hstex_mode previous_mode = engine->mode;
        engine->active_hbox_builder = &builder;
        engine->mode = HSTEX_MODE_HORIZONTAL;
        int packed = append_hbox_node(engine, boxed, error, error_capacity);
        if (packed == 0) {
            packed = finalize_hbox(engine, &builder, false, false, 0, &middle,
                                   error, error_capacity);
        }
        free(builder.node_identifiers);
        engine->active_hbox_builder = previous;
        engine->mode = previous_mode;
        if (packed != 0) {
            return -1;
        }
    }
    struct hstex_box above = {0};
    struct hstex_box below = {0};
    bool has_above = noad->superscript.kind != (uint8_t)HSTEX_MATH_FIELD_EMPTY;
    bool has_below = noad->subscript.kind != (uint8_t)HSTEX_MATH_FIELD_EMPTY;
    if ((has_above &&
         math_field_box_unsimplified(engine, &noad->superscript,
                                     math_superscript_style(style), &above,
                                     error, error_capacity) != 0) ||
        (has_below &&
         math_field_box_unsimplified(engine, &noad->subscript,
                                     math_subscript_style(style), &below,
                                     error, error_capacity) != 0)) {
        return -1;
    }
    int32_t width = middle.width;
    if (has_above && above.width > width) {
        width = above.width;
    }
    if (has_below && below.width > width) {
        width = below.width;
    }
    if ((has_above &&
         rebox_limit(engine, &above, width, error, error_capacity) != 0) ||
        (has_below &&
         rebox_limit(engine, &below, width, error, error_capacity) != 0) ||
        rebox_limit(engine, &middle, width, error, error_capacity) != 0) {
        return -1;
    }
    /* A limit left at its own width loses the italic correction it ends
       with; one widened to match keeps it, because the kern is no longer
       what the box ends with. */
    simplify_clean_box(engine, &above);
    simplify_clean_box(engine, &below);

    struct hstex_vbox_builder body = {0};
    struct hstex_vbox_builder *previous_vbox = engine->active_vbox_builder;
    enum hstex_mode previous_mode = engine->mode;
    int32_t enclosing_depth = engine->prev_depth;
    engine->active_vbox_builder = &body;
    engine->prev_depth = HSTEX_IGNORE_DEPTH;
    engine->mode = HSTEX_MODE_VERTICAL;
    int32_t height = middle.height;
    int32_t depth = middle.depth;
    int status = 0;
    if (has_above) {
        int32_t gap = spacing[2] - above.depth;
        if (gap < spacing[0]) {
            gap = spacing[0];
        }
        struct hstex_node top = {.kind = HSTEX_NODE_KERN, .width = spacing[4]};
        struct hstex_node between = {.kind = HSTEX_NODE_KERN, .width = gap};
        uint32_t placed = 0U;
        status = append_vbox_node(engine, &top, error, error_capacity);
        if (status == 0) {
            status = store_box_node(engine, &above, half_of(delta), &placed,
                                    error, error_capacity);
        }
        if (status == 0) {
            status = append_vbox_item(engine, placed, error, error_capacity);
        }
        if (status == 0) {
            status = append_vbox_node(engine, &between, error, error_capacity);
        }
        height = (int32_t)((int64_t)height + spacing[4] + above.height +
                           above.depth + gap);
    }
    uint32_t placed = 0U;
    if (status == 0) {
        status = store_box_node(engine, &middle, 0, &placed, error,
                                error_capacity);
    }
    if (status == 0) {
        status = append_vbox_item(engine, placed, error, error_capacity);
    }
    if (status == 0 && has_below) {
        int32_t gap = spacing[3] - below.height;
        if (gap < spacing[1]) {
            gap = spacing[1];
        }
        struct hstex_node between = {.kind = HSTEX_NODE_KERN, .width = gap};
        struct hstex_node bottom = {.kind = HSTEX_NODE_KERN,
                                    .width = spacing[4]};
        status = append_vbox_node(engine, &between, error, error_capacity);
        if (status == 0) {
            status = store_box_node(engine, &below, -half_of(delta), &placed,
                                    error, error_capacity);
        }
        if (status == 0) {
            status = append_vbox_item(engine, placed, error, error_capacity);
        }
        if (status == 0) {
            status = append_vbox_node(engine, &bottom, error, error_capacity);
        }
        depth = (int32_t)((int64_t)depth + spacing[4] + below.height +
                          below.depth + gap);
    }
    struct hstex_box stacked = {0};
    if (status == 0) {
        status = finalize_vbox(engine, &body, false, false, 0, &stacked, error,
                               error_capacity);
    }
    free(body.node_identifiers);
    engine->active_vbox_builder = previous_vbox;
    engine->prev_depth = enclosing_depth;
    engine->mode = previous_mode;
    if (status != 0) {
        return -1;
    }
    /* The stack is as tall as the operator plus whatever the limits added,
       not what packaging it would make of it. */
    memset(boxed, 0, sizeof(*boxed));
    boxed->kind = HSTEX_NODE_LIST;
    boxed->width = width;
    boxed->height = height;
    boxed->depth = depth;
    boxed->value.list.node_start = stacked.node_start;
    boxed->value.list.node_count = stacked.node_count;
    boxed->value.list.box_kind = HSTEX_BOX_VLIST;
    return 0;
}

/* A large operator takes a bigger shape from the charlist in display style,
   and its box carries the italic correction; see docs/DECISIONS.md,
   large-operators. */
static int build_operator_box(struct hstex_engine *engine,
                              struct hstex_noad *noad, uint8_t style,
                              int32_t *delta, struct hstex_node *boxed,
                              char *error, size_t error_capacity)
{
    uint8_t size = math_size_of_style(style);
    *delta = 0;
    const struct hstex_font *font = NULL;
    const struct hstex_char_metric *metric = NULL;
    int present = math_character_metric(engine, &noad->nucleus, size, &font,
                                        &metric, true, error, error_capacity);
    if (present < 0) {
        return -1;
    }
    if (present == 0) {
        return 0;
    }
    uint32_t character = noad->nucleus.character;
    if (style < (uint8_t)HSTEX_STYLE_TEXT && metric->tag == 2) {
        uint32_t next = (uint32_t)(metric->remainder & 0xFF);
        if (font->characters[next].tag >= 0) {
            character = next;
            metric = &font->characters[next];
        }
    }
    *delta = metric->italic;
    struct hstex_node node = {
        .kind = HSTEX_NODE_CHARACTER,
        .width = metric->width,
        .height = metric->height,
        .depth = metric->depth,
        .value.character = {.font = engine->math_fonts[size]
                                                      [noad->nucleus.family],
                            .character = character},
    };
    uint32_t placed = 0U;
    uint32_t start = 0U;
    if (store_node(engine, &node, &placed, error, error_capacity) != 0 ||
        store_list_run(engine, &placed, 1U, &start, error, error_capacity) !=
            0) {
        return -1;
    }
    memset(boxed, 0, sizeof(*boxed));
    boxed->kind = HSTEX_NODE_LIST;
    boxed->width = (int32_t)((int64_t)metric->width + metric->italic);
    boxed->height = metric->height;
    boxed->depth = metric->depth;
    boxed->value.list.node_start = start;
    boxed->value.list.node_count = 1U;
    boxed->value.list.box_kind = HSTEX_BOX_HLIST;
    return 1;
}

/* One of the three boxes of a large operator's limits, set to the width they
   share; see docs/DECISIONS.md, large-operators. */
static int rebox_limit(struct hstex_engine *engine, struct hstex_box *box,
                       int32_t width, char *error, size_t error_capacity)
{
    if (box->width == width || box->node_count == 0U) {
        box->width = width;
        return 0;
    }
    struct hstex_hbox_builder builder = {0};
    struct hstex_hbox_builder *previous = engine->active_hbox_builder;
    enum hstex_mode previous_mode = engine->mode;
    engine->active_hbox_builder = &builder;
    engine->mode = HSTEX_MODE_HORIZONTAL;
    struct hstex_glue fill = {.stretch = 65536, .stretch_order = 1U,
                              .shrink = 65536, .shrink_order = 1U};
    int status = emit_math_glue(engine, fill, error, error_capacity);
    if (status == 0 && box->kind == HSTEX_BOX_VLIST) {
        uint32_t identifier = 0U;
        status = store_box_node(engine, box, 0, &identifier, error,
                               error_capacity);
        if (status == 0) {
            status = append_hbox_item(engine, identifier, error,
                                      error_capacity);
        }
    } else {
        for (uint32_t item = 0U;
             status == 0 && item < box->node_count &&
             (size_t)box->node_start + box->node_count <=
                 engine->list_item_count;
             ++item) {
            status = append_hbox_item(
                engine, engine->list_items[box->node_start + item], error,
                error_capacity);
        }
    }
    if (status == 0) {
        status = emit_math_glue(engine, fill, error, error_capacity);
    }
    if (status == 0) {
        status = finalize_hbox(engine, &builder, true, false, width, box,
                               error, error_capacity);
    }
    free(builder.node_identifiers);
    engine->active_hbox_builder = previous;
    engine->mode = previous_mode;
    return status;
}

/* \mathaccent puts a character over what follows, sliding it right by the
   nucleus's skew and lowering it onto the letter. See docs/DECISIONS.md,
   math-accents. */
static int build_math_accent(struct hstex_engine *engine,
                             struct hstex_noad *noad, uint8_t style,
                             char *error, size_t error_capacity)
{
    uint8_t size = math_size_of_style(style);
    struct hstex_math_field accent = {
        .kind = (uint8_t)HSTEX_MATH_FIELD_CHARACTER,
        .family = (uint8_t)((noad->delimiter >> 8) & 0x0F),
        .character = (uint32_t)(noad->delimiter & 0xFF),
    };
    const struct hstex_font *font = NULL;
    const struct hstex_char_metric *metric = NULL;
    int present = math_character_metric(engine, &accent, size, &font, &metric,
                                        true,
                                        error, error_capacity);
    if (present < 0) {
        return -1;
    }
    if (present == 0) {
        /* No such character: the accent is dropped and the nucleus stands. */
        noad->kind = (uint8_t)HSTEX_NOAD_ATOM;
        noad->atom_class = (uint8_t)HSTEX_ATOM_ORD;
        return 0;
    }
    int32_t skew = 0;
    if (accent_skew(engine, &noad->nucleus, size, &skew, error,
                    error_capacity) != 0) {
        return -1;
    }
    struct hstex_box under = {0};
    if (math_field_box(engine, &noad->nucleus, math_cramped_style(style),
                       &under, error, error_capacity) != 0) {
        return -1;
    }
    /* Where the accent goes is settled by the nucleus alone, but what it
       goes over is that nucleus with its scripts; see docs/DECISIONS.md,
       an-accent-over-a-script. */
    int32_t nucleus_width = under.width;
    int32_t nucleus_height = under.height;
    bool carries_scripts =
        (noad->nucleus.kind == (uint8_t)HSTEX_MATH_FIELD_CHARACTER ||
         noad->nucleus.single_character != 0U) &&
        (noad->superscript.kind != (uint8_t)HSTEX_MATH_FIELD_EMPTY ||
         noad->superscript.node != 0U ||
         noad->subscript.kind != (uint8_t)HSTEX_MATH_FIELD_EMPTY ||
         noad->subscript.node != 0U);
    if (carries_scripts) {
        struct hstex_math_builder single = {0};
        single.forced_class = -1;
        single.style = style;
        struct hstex_noad scripted = {
            .kind = (uint8_t)HSTEX_NOAD_ATOM,
            .atom_class = (uint8_t)HSTEX_ATOM_ORD,
            .nucleus = noad->nucleus,
            .superscript = noad->superscript,
            .subscript = noad->subscript,
        };
        if (reserve_noads(&single, 1U, error, error_capacity) != 0) {
            return -1;
        }
        single.noads[0] = scripted;
        single.count = 1U;
        struct hstex_hbox_builder packed = {0};
        struct hstex_hbox_builder *previous = engine->active_hbox_builder;
        enum hstex_mode previous_mode = engine->mode;
        engine->active_hbox_builder = &packed;
        engine->mode = HSTEX_MODE_HORIZONTAL;
        int status = translate_math_list(engine, &single, error,
                                         error_capacity);
        engine->active_hbox_builder = previous;
        engine->mode = previous_mode;
        if (status == 0) {
            status = finalize_hbox(engine, &packed, false, false, 0, &under,
                                   error, error_capacity);
        }
        free(packed.node_identifiers);
        free(single.noads);
        if (status != 0) {
            return -1;
        }
        memset(&noad->superscript, 0, sizeof(noad->superscript));
        memset(&noad->subscript, 0, sizeof(noad->subscript));
    }
    /* A wider variant is taken while one exists that is no wider than what
       is being accented. */
    uint32_t character = accent.character;
    while (metric->tag == 2) {
        uint32_t next = (uint32_t)(metric->remainder & 0xFF);
        if (font->characters[next].tag < 0 ||
            font->characters[next].width > nucleus_width) {
            break;
        }
        character = next;
        metric = &font->characters[next];
    }
    int32_t x_height = 0;
    if (font->dimen_count >= 5U) {
        x_height = font->dimens[4];
    }
    int32_t delta = nucleus_height < x_height ? nucleus_height : x_height;
    /* The accent is set in a box of its own, which is then given no width so
       that it hangs over the letter. */
    struct hstex_node character_node = {
        .kind = HSTEX_NODE_CHARACTER,
        .width = metric->width,
        .height = metric->height,
        .depth = metric->depth,
        .value.character = {.font = engine->math_fonts[size][accent.family],
                            .character = character},
    };
    uint32_t placed = 0U;
    uint32_t start = 0U;
    if (store_node(engine, &character_node, &placed, error, error_capacity) !=
            0 ||
        store_list_run(engine, &placed, 1U, &start, error, error_capacity) !=
            0) {
        return -1;
    }
    int32_t accent_width = (int32_t)((int64_t)metric->width + metric->italic);
    struct hstex_node accent_box = {
        .kind = HSTEX_NODE_LIST,
        .width = 0,
        .height = metric->height,
        .depth = metric->depth,
        .shift = (int32_t)((int64_t)skew +
                           half_of((int64_t)nucleus_width - accent_width)),
        .value.list = {.node_start = start,
                       .node_count = 1U,
                       .box_kind = HSTEX_BOX_HLIST},
    };

    struct hstex_vbox_builder body = {0};
    struct hstex_vbox_builder *previous_vbox = engine->active_vbox_builder;
    enum hstex_mode previous_mode = engine->mode;
    int32_t enclosing_depth = engine->prev_depth;
    engine->active_vbox_builder = &body;
    engine->prev_depth = HSTEX_IGNORE_DEPTH;
    engine->mode = HSTEX_MODE_VERTICAL;
    /* The accent keeps the place it would have over the nucleus alone, so
       the gap grows by whatever the scripts added on top. */
    int32_t drop = (int32_t)((int64_t)under.height - nucleus_height + delta);
    struct hstex_node gap = {.kind = HSTEX_NODE_KERN, .width = -drop};
    uint32_t identifier = 0U;
    /* The stack is never shorter than what it accents; a kern at the top
       makes up the difference. */
    int64_t raw = (int64_t)metric->height + metric->depth - drop +
                  under.height;
    int status = 0;
    if (raw < under.height) {
        struct hstex_node lift = {
            .kind = HSTEX_NODE_KERN,
            .width = (int32_t)((int64_t)under.height - raw),
        };
        status = append_vbox_node(engine, &lift, error, error_capacity);
    }
    if (status == 0) {
        status = append_vbox_node(engine, &accent_box, error, error_capacity);
    }
    if (status == 0) {
        status = append_vbox_node(engine, &gap, error, error_capacity);
    }
    if (status == 0 &&
        (store_box_node(engine, &under, 0, &identifier, error,
                        error_capacity) != 0 ||
         append_vbox_item(engine, identifier, error, error_capacity) != 0)) {
        status = -1;
    }
    struct hstex_box stacked = {0};
    if (status == 0) {
        status = finalize_vbox(engine, &body, false, false, 0, &stacked, error,
                               error_capacity);
    }
    free(body.node_identifiers);
    engine->active_vbox_builder = previous_vbox;
    engine->prev_depth = enclosing_depth;
    engine->mode = previous_mode;
    if (status != 0) {
        return -1;
    }
    stacked.width = under.width;
    if (store_box_node(engine, &stacked, 0, &identifier, error,
                       error_capacity) != 0) {
        return -1;
    }
    noad->kind = (uint8_t)HSTEX_NOAD_ATOM;
    noad->atom_class = (uint8_t)HSTEX_ATOM_ORD;
    memset(&noad->nucleus, 0, sizeof(noad->nucleus));
    noad->nucleus.kind = (uint8_t)HSTEX_MATH_FIELD_BOX;
    noad->nucleus.node = identifier;
    return 0;
}

/* \overline and \underline put a rule of the default thickness over or under
   what follows, three thicknesses clear of it. See docs/DECISIONS.md,
   over-and-underline. */
static int build_math_line(struct hstex_engine *engine,
                           struct hstex_noad *noad, uint8_t style, bool over,
                           char *error, size_t error_capacity)
{
    uint8_t size = math_size_of_style(style);
    int32_t thickness = 0;
    if (math_extension_parameter(engine, size, 8U, &thickness, error,
                                 error_capacity) != 0) {
        return -1;
    }
    /* A bar over cramps what is under it; a bar under does not. */
    struct hstex_box inner = {0};
    if (math_field_box(engine, &noad->nucleus,
                       over ? math_cramped_style(style) : style, &inner, error,
                       error_capacity) != 0) {
        return -1;
    }
    struct hstex_node rule = {
        .kind = HSTEX_NODE_RULE,
        .width = HSTEX_RUNNING_DIMEN,
        .height = thickness,
        .depth = 0,
    };
    struct hstex_node edge = {.kind = HSTEX_NODE_KERN, .width = thickness};
    struct hstex_node gap = {.kind = HSTEX_NODE_KERN,
                             .width = (int32_t)(3 * (int64_t)thickness)};

    struct hstex_vbox_builder body = {0};
    struct hstex_vbox_builder *previous_vbox = engine->active_vbox_builder;
    enum hstex_mode previous_mode = engine->mode;
    engine->active_vbox_builder = &body;
    /* A list built here is not the one \prevdepth belongs to. */
    int32_t enclosing_depth = engine->prev_depth;
    engine->prev_depth = HSTEX_IGNORE_DEPTH;
    engine->mode = HSTEX_MODE_VERTICAL;
    uint32_t identifier = 0U;
    int status = 0;
    if (over) {
        if (append_vbox_node(engine, &edge, error, error_capacity) != 0 ||
            append_vbox_node(engine, &rule, error, error_capacity) != 0 ||
            append_vbox_node(engine, &gap, error, error_capacity) != 0 ||
            store_box_node(engine, &inner, 0, &identifier, error,
                           error_capacity) != 0 ||
            append_vbox_item(engine, identifier, error, error_capacity) != 0) {
            status = -1;
        }
    } else if (store_box_node(engine, &inner, 0, &identifier, error,
                              error_capacity) != 0 ||
               append_vbox_item(engine, identifier, error, error_capacity) !=
                   0 ||
               append_vbox_node(engine, &gap, error, error_capacity) != 0 ||
               append_vbox_node(engine, &rule, error, error_capacity) != 0) {
        status = -1;
    }
    struct hstex_box packed = {0};
    if (status == 0) {
        status = finalize_vbox(engine, &body, false, false, 0, &packed, error,
                               error_capacity);
    }
    free(body.node_identifiers);
    engine->active_vbox_builder = previous_vbox;
    engine->prev_depth = enclosing_depth;
    engine->mode = previous_mode;
    if (status != 0) {
        return -1;
    }
    packed.width = inner.width;
    if (over) {
        packed.height = (int32_t)(5 * (int64_t)thickness + inner.height);
        packed.depth = inner.depth;
    } else {
        /* One thickness more of clear space is left under the rule. */
        packed.height = inner.height;
        packed.depth =
            (int32_t)((int64_t)inner.depth + 5 * (int64_t)thickness);
    }
    identifier = 0U;
    if (store_box_node(engine, &packed, 0, &identifier, error,
                       error_capacity) != 0) {
        return -1;
    }
    noad->kind = (uint8_t)HSTEX_NOAD_ATOM;
    noad->atom_class = (uint8_t)HSTEX_ATOM_ORD;
    memset(&noad->nucleus, 0, sizeof(noad->nucleus));
    noad->nucleus.kind = (uint8_t)HSTEX_MATH_FIELD_BOX;
    noad->nucleus.node = identifier;
    return 0;
}

/* Set a list that holds a generalized fraction. All of the arithmetic here
   was measured; see docs/DECISIONS.md, fractions. */
static int translate_math_fraction(struct hstex_engine *engine,
                                   struct hstex_math_builder *builder,
                                   char *error, size_t error_capacity)
{
    uint8_t style = builder->style;
    uint8_t size = math_size_of_style(style);
    bool display = style < (uint8_t)HSTEX_STYLE_TEXT;
    int32_t axis = 0;
    int32_t default_thickness = 0;
    if (math_symbol_parameter(engine, size, 22U, &axis, error,
                              error_capacity) != 0 ||
        math_extension_parameter(engine, size, 8U, &default_thickness, error,
                                 error_capacity) != 0) {
        return -1;
    }
    int32_t thickness = builder->fraction_default_thickness
                            ? default_thickness
                            : builder->fraction_thickness;

    struct hstex_box numerator = {0};
    struct hstex_box denominator = {0};
    if (math_range_box(engine, builder, 0U, builder->fraction_at,
                       math_numerator_style(style), &numerator, error,
                       error_capacity) != 0 ||
        math_range_box(engine, builder, builder->fraction_at, builder->count,
                       math_denominator_style(style), &denominator, error,
                       error_capacity) != 0) {
        return -1;
    }
    int32_t width = numerator.width > denominator.width ? numerator.width
                                                        : denominator.width;
    if (math_rebox(engine, &numerator, width, error, error_capacity) != 0 ||
        math_rebox(engine, &denominator, width, error, error_capacity) != 0) {
        return -1;
    }
    /* A side widened to match the other keeps its italic correction, because
       the kern is no longer what the box ends with; a side left as it stands
       loses it. See docs/DECISIONS.md, a-clean-box-of-one-character. */
    simplify_clean_box(engine, &numerator);
    simplify_clean_box(engine, &denominator);

    /* Where the two sides sit before the space between them is checked. */
    int32_t shift_up = 0;
    int32_t shift_down = 0;
    if (math_symbol_parameter(engine, size, display ? 8U : (thickness != 0 ? 9U : 10U),
                              &shift_up, error, error_capacity) != 0 ||
        math_symbol_parameter(engine, size, display ? 11U : 12U, &shift_down,
                              error, error_capacity) != 0) {
        return -1;
    }

    int32_t above = 0;
    int32_t below = 0;
    if (thickness == 0) {
        /* Nothing between the two sides, so the whole gap is checked at
           once and any shortfall is shared equally. */
        int64_t clearance = display ? 7 * (int64_t)default_thickness
                                    : 3 * (int64_t)default_thickness;
        int64_t gap = ((int64_t)shift_up - numerator.depth) -
                      ((int64_t)denominator.height - shift_down);
        if (gap < clearance) {
            int32_t share = half_of(clearance - gap);
            shift_up += share;
            shift_down += share;
        }
        above = (int32_t)(((int64_t)shift_up - numerator.depth) -
                          ((int64_t)denominator.height - shift_down));
    } else {
        /* The rule sits on the axis, and each side is kept clear of it. */
        int64_t clearance = display ? 3 * (int64_t)thickness : thickness;
        int32_t half = half_of(thickness);
        int64_t over = ((int64_t)shift_up - numerator.depth) -
                       ((int64_t)axis + half);
        if (over < clearance) {
            shift_up += (int32_t)(clearance - over);
            over = clearance;
        }
        int64_t under = ((int64_t)axis - half) -
                        ((int64_t)denominator.height - shift_down);
        if (under < clearance) {
            shift_down += (int32_t)(clearance - under);
            under = clearance;
        }
        above = (int32_t)over;
        below = (int32_t)under;
    }

    struct hstex_vbox_builder body = {0};
    struct hstex_vbox_builder *previous_vbox = engine->active_vbox_builder;
    enum hstex_mode previous_mode = engine->mode;
    engine->active_vbox_builder = &body;
    /* A list built here is not the one \prevdepth belongs to. */
    int32_t enclosing_depth = engine->prev_depth;
    engine->prev_depth = HSTEX_IGNORE_DEPTH;
    engine->mode = HSTEX_MODE_VERTICAL;
    int status = 0;
    uint32_t identifier = 0U;
    if (store_box_node(engine, &numerator, 0, &identifier, error,
                       error_capacity) != 0 ||
        append_vbox_item(engine, identifier, error, error_capacity) != 0) {
        status = -1;
    }
    struct hstex_node gap = {.kind = HSTEX_NODE_KERN, .width = above};
    if (status == 0 &&
        append_vbox_node(engine, &gap, error, error_capacity) != 0) {
        status = -1;
    }
    if (status == 0 && thickness != 0) {
        struct hstex_node rule = {
            .kind = HSTEX_NODE_RULE,
            .width = HSTEX_RUNNING_DIMEN,
            .height = thickness,
            .depth = 0,
        };
        struct hstex_node second = {.kind = HSTEX_NODE_KERN, .width = below};
        if (append_vbox_node(engine, &rule, error, error_capacity) != 0 ||
            append_vbox_node(engine, &second, error, error_capacity) != 0) {
            status = -1;
        }
    }
    if (status == 0 &&
        (store_box_node(engine, &denominator, 0, &identifier, error,
                        error_capacity) != 0 ||
         append_vbox_item(engine, identifier, error, error_capacity) != 0)) {
        status = -1;
    }
    struct hstex_box vertical = {0};
    if (status == 0) {
        status = finalize_vbox(engine, &body, false, false, 0, &vertical, error,
                               error_capacity);
    }
    free(body.node_identifiers);
    engine->active_vbox_builder = previous_vbox;
    engine->prev_depth = enclosing_depth;
    engine->mode = previous_mode;
    if (status != 0) {
        return -1;
    }
    vertical.width = width;
    vertical.height = (int32_t)((int64_t)shift_up + numerator.height);
    vertical.depth = (int32_t)((int64_t)denominator.depth + shift_down);

    /* The delimiters are as tall as the style asks for, whatever the
       fraction itself came to. */
    int32_t wanted = 0;
    if (math_symbol_parameter(engine, size, display ? 20U : 21U, &wanted, error,
                              error_capacity) != 0) {
        return -1;
    }
    struct hstex_box left = {0};
    struct hstex_box right = {0};
    if (variant_delimiter(engine, builder->fraction_left, size, wanted, &left,
                          error, error_capacity) != 0 ||
        variant_delimiter(engine, builder->fraction_right, size, wanted, &right,
                          error, error_capacity) != 0) {
        return -1;
    }

    struct hstex_hbox_builder whole = {0};
    struct hstex_hbox_builder *previous = engine->active_hbox_builder;
    engine->active_hbox_builder = &whole;
    engine->mode = HSTEX_MODE_HORIZONTAL;
    status = 0;
    struct hstex_box *parts[3] = {&left, &vertical, &right};
    for (size_t index = 0U; status == 0 && index < 3U; ++index) {
        int32_t shift = index == 1U ? 0
                                    : half_of((int64_t)parts[index]->height -
                                              parts[index]->depth) -
                                          axis;
        identifier = 0U;
        if (store_box_node(engine, parts[index], shift, &identifier, error,
                           error_capacity) != 0) {
            status = -1;
            break;
        }
        status = append_hbox_item(engine, identifier, error, error_capacity);
    }
    struct hstex_box packed = {0};
    if (status == 0) {
        status = finalize_hbox(engine, &whole, false, false, 0, &packed, error,
                               error_capacity);
    }
    free(whole.node_identifiers);
    engine->active_hbox_builder = previous;
    engine->mode = previous_mode;
    if (status != 0) {
        return -1;
    }
    identifier = 0U;
    if (store_box_node(engine, &packed, 0, &identifier, error,
                       error_capacity) != 0) {
        return -1;
    }
    return append_hbox_item(engine, identifier, error, error_capacity);
}

/* A delimiter is named either by a character, whose \delcode says which one
   it is, or by \delimiter and a number. */
static int scan_delimiter(struct hstex_engine *engine, int32_t *code,
                          char *error, size_t error_capacity)
{
    hstex_token token = 0U;
    struct hstex_source_location location;
    if (expanded_next_non_space_non_relax(engine, &token, &location, error,
                                          error_capacity) !=
        HSTEX_ENGINE_TOKEN) {
        return set_error(error, error_capacity,
                         "end of input while scanning a delimiter");
    }
    int32_t value = -1;
    if (hstex_token_is_character(token) &&
        (token_is_category(token, HSTEX_CAT_LETTER) ||
         token_is_category(token, HSTEX_CAT_OTHER))) {
        int table = code_table_index(HSTEX_COMMAND_DEL_CODE);
        if (table < 0) {
            return set_error(error, error_capacity, "no delcode table");
        }
        value = engine->code_tables[(size_t)table]
                                   [hstex_token_character_code(token)];
    } else if (hstex_token_is_control_sequence(token)) {
        const struct hstex_meaning *meaning = hstex_engine_meaning(
            engine, hstex_token_control_sequence_id(token));
        if (meaning->command == HSTEX_COMMAND_DELIMITER) {
            if (scan_integer(engine, &value, error, error_capacity) != 0) {
                return -1;
            }
        }
    }
    if (value < 0 || value > 0x7FFFFFF) {
        /* The reference reads the offending token again and stands in the
           null delimiter, which measures nothing. trip line 256 writes
           `$\right\relax'. */
        static const char *const help[] = {
            "I was expecting to see something like `(' or `\\{' or",
            "`\\}' here. If you typed, e.g., `{' instead of `\\{', you",
            "should probably delete the `{' by typing `1' now, so that",
            "braces don't get unbalanced. Otherwise just proceed.",
            "Acceptable delimiters are characters whose \\delcode is",
            "nonnegative, or you can use `\\delimiter <delimiter code>'.",
            NULL};
        if (push_one(engine, token, location, error, error_capacity) != 0) {
            return -1;
        }
        tex_error(engine, help, "Missing delimiter (. inserted)");
        value = 0;
    }
    *code = value;
    return 0;
}

/* \left opens a list of its own; \right closes it and makes an inner atom of
   the two delimiters with that list between them. */
/* How tall a \\left group's delimiters must be: the contents' reach from the
   axis, scaled by \\delimiterfactor, but never more than
   \\delimitershortfall short of covering them twice over. */
static int32_t delimiter_target(struct hstex_engine *engine, int32_t height,
                                int32_t depth, int32_t axis)
{
    int64_t below = (int64_t)depth + axis;
    int64_t above = (int64_t)height + depth - below;
    int64_t reach = above > below ? above : below;
    int64_t factor =
        (reach / 500) *
        engine->integer_parameters[HSTEX_INTEGER_DELIMITER_FACTOR];
    int64_t shortfall =
        reach + reach -
        engine->dimen_parameters[HSTEX_DIMEN_DELIMITER_SHORTFALL];
    int64_t wanted = factor > shortfall ? factor : shortfall;
    if (wanted < 0) {
        wanted = 0;
    }
    if (wanted > HSTEX_MAX_DIMEN) {
        wanted = HSTEX_MAX_DIMEN;
    }
    return (int32_t)wanted;
}

static int execute_left_right(struct hstex_engine *engine, int32_t kind,
                              char *error, size_t error_capacity)
{
    struct hstex_math_builder *list = current_math_list(engine);
    if (engine->mode != HSTEX_MODE_MATH || list == NULL) {
        return set_error(error, error_capacity,
                         "\\left and \\right are only allowed in a formula");
    }
    int32_t code = 0;
    if (scan_delimiter(engine, &code, error, error_capacity) != 0) {
        return -1;
    }
    if (kind == 0) {
        uint8_t style = list->current_style;
        if (push_math_list(engine, style, error, error_capacity) != 0) {
            return -1;
        }
        current_math_list(engine)->left_delimiter = code;
        current_math_list(engine)->is_left_group = true;
        return 0;
    }
    if (!list->is_left_group || engine->math_depth <= engine->math_floor + 1U) {
        /* The reference ignores one that closes nothing and goes on. Its
           delimiter has already been read, which is why trip line 256's
           `$\right\relax' draws the missing-delimiter fault first. */
        const char *name = kind == 2 ? "\\middle" : "\\right";
        const char *help_line =
            kind == 2 ? "I'm ignoring a \\middle that had no matching \\left."
                      : "I'm ignoring a \\right that had no matching \\left.";
        const char *const help[] = {help_line, NULL};
        tex_error(engine, help, "Extra %s", name);
        return 0;
    }
    if (kind == 2) {
        /* The delimiter cannot be made yet: it is as tall as the whole group
           will turn out to be. See docs/DECISIONS.md, middle-delimiters. */
        struct hstex_noad noad = {
            .kind = (uint8_t)HSTEX_NOAD_MIDDLE,
            .atom_class = (uint8_t)HSTEX_ATOM_CLOSE,
            .delimiter = code,
        };
        return math_append(engine, &noad, error, error_capacity);
    }
    /* The group is kept as it stands and set when the list it belongs to is,
       because the style it lands in is not known yet: a fraction sets its
       numerator smaller. See docs/DECISIONS.md, a-fence-is-set-in-place. */
    uint32_t record = 0U;
    int stored = store_math_sublist(engine, list, &record, error,
                                    error_capacity);
    int32_t left_code = list->left_delimiter;
    pop_math_list(engine);
    if (stored != 0) {
        return -1;
    }
    struct hstex_noad noad = {
        .kind = (uint8_t)HSTEX_NOAD_FENCE,
        .atom_class = (uint8_t)HSTEX_ATOM_INNER,
        .delimiter = code,
        .left_delimiter = left_code,
        .nucleus = {.kind = (uint8_t)HSTEX_MATH_FIELD_BOX, .sublist = record},
    };
    return math_append_atom(engine, &noad, error, error_capacity);
}

/* \left ... \right, set at the style the list it belongs to turned out to
   have; see docs/DECISIONS.md, a-fence-is-set-in-place. */
static int build_math_fence(struct hstex_engine *engine,
                            struct hstex_noad *outer_noad, uint8_t style,
                            char *error, size_t error_capacity)
{
    struct hstex_math_builder loaded = {0};
    if (load_math_sublist(engine, outer_noad->nucleus.sublist, style, &loaded,
                          error, error_capacity) != 0) {
        free(loaded.noads);
        return -1;
    }
    struct hstex_math_builder *list = &loaded;
    int32_t code = outer_noad->delimiter;
    int32_t left_code = outer_noad->left_delimiter;
    uint8_t size = math_size_of_style(style);

    /* A group with a \middle in it has to be set twice: once to find out how
       tall it is, and again with delimiters of that height in place. */
    bool has_middle = false;
    for (size_t index = 0U; index < list->count; ++index) {
        if (list->noads[index].kind == (uint8_t)HSTEX_NOAD_MIDDLE) {
            has_middle = true;
            break;
        }
    }
    int32_t previous_size = engine->middle_delimiter_size;
    struct hstex_box measured = {0};
    if (has_middle) {
        struct hstex_math_builder trial = {0};
        trial.forced_class = -1;
        trial.style = list->style;
        trial.current_style = list->current_style;
        if (list->count != 0U) {
            if (reserve_noads(&trial, list->count, error, error_capacity) !=
                0) {
                return -1;
            }
            memcpy(trial.noads, list->noads,
                   list->count * sizeof(*trial.noads));
            trial.count = list->count;
        }
        struct hstex_hbox_builder measuring = {0};
        struct hstex_hbox_builder *outer = engine->active_hbox_builder;
        engine->active_hbox_builder = &measuring;
        engine->middle_delimiter_size = -1;
        int trial_status =
            translate_math_list(engine, &trial, error, error_capacity);
        engine->active_hbox_builder = outer;
        if (trial_status == 0) {
            trial_status = finalize_hbox(engine, &measuring, false, false, 0,
                                         &measured, error, error_capacity);
        }
        free(measuring.node_identifiers);
        free(trial.noads);
        if (trial_status != 0) {
            engine->middle_delimiter_size = previous_size;
            return -1;
        }
    }

    struct hstex_hbox_builder builder = {0};
    struct hstex_hbox_builder *previous = engine->active_hbox_builder;
    engine->active_hbox_builder = &builder;
    engine->middle_delimiter_size = -1;
    int32_t target = -1;
    int status = 0;
    if (has_middle) {
        int32_t trial_axis = 0;
        if (math_symbol_parameter(engine, size, 22U, &trial_axis, error,
                                  error_capacity) != 0) {
            status = -1;
        } else {
            target = delimiter_target(engine, measured.height, measured.depth,
                                      trial_axis);
            engine->middle_delimiter_size = target;
        }
    }
    /* The two delimiters take part in the spacing as an opening and a
       closing atom, so they are put into the list while it is set and the
       boxes are spliced in where they stood. See docs/DECISIONS.md,
       delimiters-are-atoms. */
    /* A GROUP THAT TURNED INTO A FRACTION is not spaced that way: what
       stands between the delimiters is the fraction alone, and the numerator
       is what was read BEFORE the \over, delimiter and all left out of it.
       The two atoms would fall inside the numerator and move the split, and
       they would earn no space anyway -- an opening before an inner atom and
       an inner before a closing are both spaced by nothing. See
       docs/DECISIONS.md, fractions. */
    if (status == 0 && !list->has_fraction) {
        struct hstex_noad opening = {
            .kind = (uint8_t)HSTEX_NOAD_ATOM,
            .atom_class = (uint8_t)HSTEX_ATOM_OPEN,
        };
        struct hstex_noad closing = {
            .kind = (uint8_t)HSTEX_NOAD_ATOM,
            .atom_class = (uint8_t)HSTEX_ATOM_CLOSE,
        };
        if (reserve_noads(list, list->count + 2U, error, error_capacity) != 0) {
            status = -1;
        } else {
            memmove(&list->noads[1], &list->noads[0],
                    list->count * sizeof(*list->noads));
            list->noads[0] = opening;
            ++list->count;
            list->noads[list->count++] = closing;
        }
    }
    if (status == 0) {
        status = translate_math_list(engine, list, error, error_capacity);
    }
    engine->active_hbox_builder = previous;
    engine->middle_delimiter_size = previous_size;
    struct hstex_box inner = {0};
    if (status == 0) {
        status = finalize_hbox(engine, &builder, false, false, 0, &inner, error,
                               error_capacity);
    }
    free(builder.node_identifiers);
    if (status != 0) {
        free(loaded.noads);
        return -1;
    }

    int32_t axis = 0;
    if (math_symbol_parameter(engine, size, 22U, &axis, error,
                              error_capacity) != 0) {
        free(loaded.noads);
        return -1;
    }
    /* The height the delimiters must cover is the group's own, taken before
       any \\middle delimiter was put into it. */
    int32_t wanted =
        target >= 0 ? target
                    : delimiter_target(engine, inner.height, inner.depth, axis);

    struct hstex_box left_box = {0};
    struct hstex_box right_box = {0};
    if (variant_delimiter(engine, left_code, size, wanted, &left_box, error,
                          error_capacity) != 0 ||
        variant_delimiter(engine, code, size, wanted, &right_box, error,
                          error_capacity) != 0) {
        return -1;
    }

    struct hstex_hbox_builder whole = {0};
    enum hstex_mode previous_mode = engine->mode;
    engine->active_hbox_builder = &whole;
    engine->mode = HSTEX_MODE_HORIZONTAL;
    status = 0;
    struct hstex_box *parts[2] = {&left_box, &right_box};
    for (size_t index = 0U; status == 0 && index < 2U; ++index) {
        /* A delimiter is centred on the axis; what stands between them is
           not boxed at all but spliced in as it is, so that its glue still
           belongs to the line. See docs/DECISIONS.md,
           what-stands-between-delimiters. */
        int32_t shift = half_of((int64_t)parts[index]->height -
                                parts[index]->depth) -
                        axis;
        uint32_t identifier = 0U;
        if (store_box_node(engine, parts[index], shift, &identifier, error,
                           error_capacity) != 0) {
            status = -1;
            break;
        }
        status = append_hbox_item(engine, identifier, error, error_capacity);
        if (status == 0 && index == 0U &&
            (size_t)inner.node_start + inner.node_count <=
                engine->list_item_count) {
            for (uint32_t item = 0U; status == 0 && item < inner.node_count;
                 ++item) {
                status = append_hbox_item(
                    engine, engine->list_items[inner.node_start + item], error,
                    error_capacity);
            }
        }
    }
    struct hstex_box packed = {0};
    if (status == 0) {
        status = finalize_hbox(engine, &whole, false, false, 0, &packed, error,
                               error_capacity);
    }
    free(whole.node_identifiers);
    engine->active_hbox_builder = previous;
    engine->mode = previous_mode;
    if (status != 0) {
        return -1;
    }
    uint32_t identifier = 0U;
    if (store_box_node(engine, &packed, 0, &identifier, error,
                       error_capacity) != 0) {
        return -1;
    }
    struct hstex_noad noad = {
        .kind = (uint8_t)HSTEX_NOAD_ATOM,
        .atom_class = (uint8_t)HSTEX_ATOM_INNER,
        .nucleus = {.kind = (uint8_t)HSTEX_MATH_FIELD_BOX, .node = identifier},
    };
    outer_noad->kind = noad.kind;
    outer_noad->atom_class = noad.atom_class;
    outer_noad->nucleus = noad.nucleus;
    free(loaded.noads);
    return 0;
}

/* \vcenter builds a vertical box and hangs it on the axis of the symbol
   family; see docs/DECISIONS.md, vcenter. */
static int execute_vcenter(struct hstex_engine *engine, char *error,
                           size_t error_capacity)
{
    struct hstex_math_builder *list = current_math_list(engine);
    if (engine->mode != HSTEX_MODE_MATH || list == NULL) {
        return set_error(error, error_capacity,
                         "\\vcenter is only allowed in a formula");
    }
    uint8_t size = math_size_of_style(list->current_style);
    struct hstex_box box = {0};
    if (scan_vbox(engine, false, &box, error, error_capacity) != 0) {
        return -1;
    }
    (void)size;
    /* THE BOX IS NOT HUNG ON THE AXIS YET. Which axis it hangs on is the one
       of the size the ATOM is set at, and that is not known here: a \vcenter
       written in a fraction's numerator is set smaller than one written
       beside it. The box is kept as it was made and hung when it is set,
       which is also why a \vcenter in a formula whose symbol fonts are
       short of parameters draws the reference's `Math formula deleted'
       rather than stopping here. See docs/DECISIONS.md, vcenter.
       Marked as \vcenter's, so that braces round it package it; see
       docs/DECISIONS.md, a-vcenter-in-braces. */
    return math_append_box_field_kind(engine, &box, false, 0U, 0U, true, error,
                                      error_capacity);
}

/* \insert reads a class and a vertical list, which is packed at its natural
   size and set aside for the page builder; see docs/DECISIONS.md,
   insertions. */
static int execute_insert(struct hstex_engine *engine, char *error,
                          size_t error_capacity)
{
    /* An insertion class stops at 255 whatever the register width, and 255
       itself is the page builder's own: past 255 is a bad register code,
       255 is refused by name. Both are forgiven, and both give class 0. */
    int32_t number = 0;
    if (scan_register_num(engine, &number, 255, error, error_capacity) != 0) {
        return -1;
    }
    if (number == 255) {
        static const char *const help[] = {
            "I'm changing to \\insert0; box 255 is special.", NULL};
        tex_error(engine, help, "You can't \\insert255");
        number = 0;
    }
    hstex_token opening = 0U;
    struct hstex_source_location location;
    enum hstex_engine_result result = expanded_next_non_space_unrestricted(
        engine, &opening, &location, error, error_capacity);
    if (result != HSTEX_ENGINE_TOKEN ||
        !token_is_effective_begin_group(engine, opening)) {
        return set_error(error, error_capacity,
                         "\\insert requires a braced vertical list");
    }
    struct hstex_vbox_builder builder = {0};
    struct hstex_insert_settings settings = {0};
    int status = evaluate_vbox_contents(engine, &builder, HSTEX_IGNORE_DEPTH,
                                        NULL, &settings, false, error,
                                        error_capacity);
    struct hstex_box packed = {0};
    if (status == 0) {
        /* The list is packed at its natural size, with the depth the
           insertion itself allows. */
        int32_t limit = engine->dimen_parameters[HSTEX_DIMEN_BOX_MAX_DEPTH];
        engine->dimen_parameters[HSTEX_DIMEN_BOX_MAX_DEPTH] =
            settings.split_max_depth;
        status = finalize_vbox(engine, &builder, false, false, 0, &packed,
                               error, error_capacity);
        engine->dimen_parameters[HSTEX_DIMEN_BOX_MAX_DEPTH] = limit;
    }
    free(builder.node_identifiers);
    if (status != 0) {
        return -1;
    }
    struct hstex_insert_detail detail = {
        .split_top_skip = settings.split_top_skip,
        .split_max_depth = settings.split_max_depth,
        .float_cost = settings.float_cost,
    };
    uint32_t detail_at = 0U;
    if (store_insert_detail(engine, &detail, &detail_at, error,
                            error_capacity) != 0) {
        return -1;
    }
    struct hstex_node node = {
        .kind = HSTEX_NODE_INSERT,
        /* What the page builder measures: everything the list came to. */
        .height = packed.height + packed.depth,
        .value.insert = {
            .node_start = packed.node_start,
            .node_count = packed.node_count,
            .number = (uint16_t)number,
            .detail = detail_at,
        },
    };
    if (append_current_list_node(engine, &node, error, error_capacity) != 0) {
        return -1;
    }
    /* An insertion on the main vertical list sets the page builder going
       where it stands, so what it freezes, splits and complains about is
       reported before the next command is read. Measured: an insertion that
       must split on an empty page draws its `%% goal' and its `% split100'
       before the \message after it, not after the following box. */
    if (engine->mode != HSTEX_MODE_VERTICAL) {
        return 0;
    }
    return contribute_page(engine, error, error_capacity);
}

/* \vadjust: vertical material written inside a paragraph, which leaves the
   line it was written in and stands behind it. In a box that is not a line
   it stays where it was put. See docs/DECISIONS.md, vadjust. */
static int execute_vadjust(struct hstex_engine *engine, char *error,
                           size_t error_capacity)
{
    if (engine->mode == HSTEX_MODE_VERTICAL) {
        report_illegal_case(engine, engine->executing_token);
        return 0;
    }
    if (scan_left_brace(engine, error, error_capacity) != 0) {
        return -1;
    }
    struct hstex_vbox_builder builder = {0};
    int status = evaluate_vbox_contents(engine, &builder, HSTEX_IGNORE_DEPTH,
                                        NULL, NULL, false, error,
                                        error_capacity);
    struct hstex_box packed = {0};
    if (status == 0) {
        status = finalize_vbox(engine, &builder, false, false, 0, &packed,
                               error, error_capacity);
    }
    free(builder.node_identifiers);
    if (status != 0) {
        return -1;
    }
    struct hstex_node node = {
        .kind = HSTEX_NODE_ADJUST,
        .value.list = {
            .node_start = packed.node_start,
            .node_count = packed.node_count,
        },
    };
    if (engine->mode == HSTEX_MODE_HORIZONTAL &&
        flush_pending_character(engine, error, error_capacity) != 0) {
        return -1;
    }
    return append_current_list_node(engine, &node, error, error_capacity);
}

/* \mark and \marks leave a token list in the list being built, expanded once
   as \edef expands one; see docs/DECISIONS.md, marks. */
static int execute_mark(struct hstex_engine *engine, bool classed, char *error,
                        size_t error_capacity)
{
    int32_t class_number = 0;
    if (classed &&
        scan_integer(engine, &class_number, error, error_capacity) != 0) {
        return -1;
    }
    if (class_number < 0 || class_number > 32767) {
        return set_error(error, error_capacity,
                         "mark class %d is outside 0..32767", class_number);
    }
    hstex_token opening = 0U;
    struct hstex_source_location location;
    if (expanded_next_non_space_unrestricted(engine, &opening, &location, error,
                                             error_capacity) !=
            HSTEX_ENGINE_TOKEN ||
        !token_is_category(opening, HSTEX_CAT_BEGIN_GROUP)) {
        return set_error(error, error_capacity,
                         "\\mark requires a braced token list");
    }
    /* Expanded where it stands, so a fault inside the text names the line
       the \mark is on. */
    struct hstex_token_vector text = {0};
    if (scan_expanded_text_from_input(engine, &text, "text of \\mark", false,
                                      error,
                                      error_capacity) != 0) {
        vector_destroy(&text);
        return -1;
    }
    uint32_t identifier = 0U;
    if (store_token_list(engine, &text, &identifier, error, error_capacity) !=
        0) {
        vector_destroy(&text);
        return -1;
    }
    struct hstex_node node = {
        .kind = HSTEX_NODE_MARK,
        .value.mark = {.tokens = identifier,
                       .class_number = (uint16_t)class_number},
    };
    return append_current_list_node(engine, &node, error, error_capacity);
}

/* \parshape reads a count and that many indent and length pairs. A count of
   zero or less takes the shape away and reads nothing more. */
static int execute_parshape(struct hstex_engine *engine, char *error,
                            size_t error_capacity)
{
    bool global = engine->pending_global;
    int32_t count = 0;
    if (scan_optional_equals(engine, error, error_capacity) != 0 ||
        scan_integer(engine, &count, error, error_capacity) != 0) {
        return -1;
    }
    if (count <= 0) {
        if (assign_parshape(engine, 0U, global, error, error_capacity) != 0) {
            return -1;
        }
        return finish_assignment(engine, 0, error, error_capacity);
    }
    if ((size_t)count > (SIZE_MAX - 1U) / 2U) {
        return set_error(error, error_capacity, "\\parshape is too long");
    }
    size_t needed = 1U + 2U * (size_t)count;
    if (engine->parshape_used + needed > engine->parshape_capacity) {
        size_t capacity = engine->parshape_capacity == 0U
                              ? 64U
                              : engine->parshape_capacity;
        while (capacity < engine->parshape_used + needed) {
            if (capacity > SIZE_MAX / 2U) {
                return set_error(error, error_capacity,
                                 "\\parshape arena overflow");
            }
            capacity *= 2U;
        }
        if (capacity > SIZE_MAX / sizeof(*engine->parshapes)) {
            return set_error(error, error_capacity, "\\parshape arena overflow");
        }
        void *allocation =
            realloc(engine->parshapes, capacity * sizeof(*engine->parshapes));
        if (allocation == NULL) {
            return set_error(error, error_capacity,
                             "\\parshape allocation failed");
        }
        engine->parshapes = allocation;
        engine->parshape_capacity = capacity;
    }
    if (engine->parshape_used + needed > (size_t)UINT32_MAX) {
        return set_error(error, error_capacity, "\\parshape arena overflow");
    }
    size_t start = engine->parshape_used;
    engine->parshapes[start] = count;
    for (int32_t index = 0; index < count; ++index) {
        int32_t indent = 0;
        int32_t length = 0;
        if (scan_dimension(engine, &indent, error, error_capacity) != 0 ||
            scan_dimension(engine, &length, error, error_capacity) != 0) {
            return -1;
        }
        engine->parshapes[start + 1U + 2U * (size_t)index] = indent;
        engine->parshapes[start + 2U + 2U * (size_t)index] = length;
    }
    engine->parshape_used = start + needed;
    if (assign_parshape(engine, (uint32_t)(start + 1U), global, error,
                        error_capacity) != 0) {
        return -1;
    }
    return finish_assignment(engine, 0, error, error_capacity);
}

/* \nonscript marks the glue after it as one a script does not want; see
   docs/DECISIONS.md, nonscript. */
static int execute_non_script(struct hstex_engine *engine, char *error,
                              size_t error_capacity)
{
    if (engine->mode != HSTEX_MODE_MATH ||
        current_math_list(engine) == NULL) {
        return set_error(error, error_capacity,
                         "\\nonscript is only allowed in a formula");
    }
    struct hstex_noad noad = {.kind = (uint8_t)HSTEX_NOAD_NONSCRIPT};
    return math_append(engine, &noad, error, error_capacity);
}

/* \radical names a delimiter and then reads one field, which becomes what
   the sign is put over. See docs/DECISIONS.md, radicals. */
static int execute_radical(struct hstex_engine *engine, char *error,
                           size_t error_capacity)
{
    struct hstex_math_builder *builder = current_math_list(engine);
    if (engine->mode != HSTEX_MODE_MATH || builder == NULL) {
        return set_error(error, error_capacity,
                         "\\radical is only allowed in a formula");
    }
    if (builder->slot != (uint8_t)HSTEX_MATH_SLOT_NONE) {
        return set_error(error, error_capacity,
                         "\\radical met where a field was expected");
    }
    int32_t code = 0;
    if (scan_twenty_seven_bit_int(engine, &code, error, error_capacity) != 0) {
        return -1;
    }
    struct hstex_noad noad = {
        .kind = (uint8_t)HSTEX_NOAD_RADICAL,
        .atom_class = (uint8_t)HSTEX_ATOM_ORD,
        .delimiter = code,
    };
    if (math_append(engine, &noad, error, error_capacity) != 0) {
        return -1;
    }
    builder->slot = (uint8_t)HSTEX_MATH_SLOT_RADICAND;
    builder->slot_target = builder->count - 1U;
    return 0;
}

/* \mathaccent reads a mathchar and then one field, exactly as \radical
   reads a delimiter and one; see docs/DECISIONS.md, math-accents. */
static int execute_math_accent(struct hstex_engine *engine, char *error,
                               size_t error_capacity)
{
    struct hstex_math_builder *builder = current_math_list(engine);
    if (engine->mode != HSTEX_MODE_MATH || builder == NULL) {
        return set_error(error, error_capacity,
                         "\\mathaccent is only allowed in a formula");
    }
    if (builder->slot != (uint8_t)HSTEX_MATH_SLOT_NONE) {
        return set_error(error, error_capacity,
                         "\\mathaccent met where a field was expected");
    }
    int32_t code = 0;
    if (scan_integer(engine, &code, error, error_capacity) != 0) {
        return -1;
    }
    if (code < 0 || code > 0x7FFF) {
        return set_error(error, error_capacity,
                         "math accent %d is outside 0..32767", code);
    }
    if (((code >> 12) & 0x07) == 7) {
        int32_t requested = engine->integer_parameters[HSTEX_INTEGER_FAMILY];
        if (requested >= 0 && requested < 16) {
            code = (code & ~0x0F00) | (requested << 8);
        }
    }
    struct hstex_noad noad = {
        .kind = (uint8_t)HSTEX_NOAD_ACCENT,
        .atom_class = (uint8_t)HSTEX_ATOM_ORD,
        .delimiter = code,
    };
    if (math_append(engine, &noad, error, error_capacity) != 0) {
        return -1;
    }
    builder->slot = (uint8_t)HSTEX_MATH_SLOT_RADICAND;
    builder->slot_target = builder->count - 1U;
    return 0;
}

/* \overline and \underline read one field, exactly as \radical does. */
static int execute_over_under_line(struct hstex_engine *engine, bool over,
                                   char *error, size_t error_capacity)
{
    struct hstex_math_builder *builder = current_math_list(engine);
    if (engine->mode != HSTEX_MODE_MATH || builder == NULL) {
        return set_error(error, error_capacity,
                         "%s is only allowed in a formula",
                         over ? "\\overline" : "\\underline");
    }
    if (builder->slot != (uint8_t)HSTEX_MATH_SLOT_NONE) {
        return set_error(error, error_capacity,
                         "%s met where a field was expected",
                         over ? "\\overline" : "\\underline");
    }
    struct hstex_noad noad = {
        .kind = (uint8_t)(over ? HSTEX_NOAD_OVERLINE : HSTEX_NOAD_UNDERLINE),
        .atom_class = (uint8_t)HSTEX_ATOM_ORD,
    };
    if (math_append(engine, &noad, error, error_capacity) != 0) {
        return -1;
    }
    builder->slot = (uint8_t)HSTEX_MATH_SLOT_RADICAND;
    builder->slot_target = builder->count - 1U;
    return 0;
}

/* \over and its relatives split the list being read: what has been read so
   far is the numerator and what follows is the denominator. See
   docs/DECISIONS.md, fractions. */
static int execute_fraction(struct hstex_engine *engine, int32_t subtype,
                            char *error, size_t error_capacity)
{
    struct hstex_math_builder *list = current_math_list(engine);
    if (engine->mode != HSTEX_MODE_MATH || list == NULL) {
        return set_error(error, error_capacity,
                         "a fraction is only allowed in a formula");
    }
    bool delimited = subtype >= 3;
    int32_t kind = subtype % 3;
    int32_t left = 0;
    int32_t right = 0;
    if (delimited &&
        (scan_delimiter(engine, &left, error, error_capacity) != 0 ||
         scan_delimiter(engine, &right, error, error_capacity) != 0)) {
        return -1;
    }
    int32_t thickness = 0;
    if (kind == 2 &&
        scan_dimension(engine, &thickness, error, error_capacity) != 0) {
        return -1;
    }
    /* The operands are read before the list is asked whether it already
       holds a fraction: the reference reports the delimiters and the
       thickness first and the ambiguity last, and then ignores this
       specification rather than the earlier one. trip line 257 writes
       `\left.A\over A\abovewithdelims.?'. */
    if (list->has_fraction) {
        static const char *const help[] = {
            "I'm ignoring this fraction specification, since I don't",
            "know whether a construction like `x \\over y \\over z'",
            "means `{x \\over y} \\over z' or `x \\over {y \\over z}'.",
            NULL};
        tex_error(engine, help, "Ambiguous; you need another { and }");
        return 0;
    }
    list->has_fraction = true;
    list->fraction_at = list->count;
    list->fraction_thickness = thickness;
    list->fraction_default_thickness = kind == 0;
    list->fraction_left = left;
    list->fraction_right = right;
    return 0;
}

/* \eqno and \leqno end the equation and begin its number, which is set in
   text style; see docs/DECISIONS.md, equation-numbers. */
static int execute_equation_number(struct hstex_engine *engine, bool left,
                                   char *error, size_t error_capacity)
{
    if (engine->mode != HSTEX_MODE_MATH || !engine->displayed_math ||
        engine->reading_equation_number) {
        /* Nowhere but a display has an equation to number, and the
           reference names the mode and carries on. trip line 254 reaches
           this after the $$ it had to insert closed the display. */
        report_illegal_case(engine, engine->executing_token);
        return 0;
    }
    /* The display's own list STAYS ON THE STACK while the number is read.
       The reference measures the number first and the equation afterwards,
       which is what puts its two `Insufficient extension fonts' either side
       of the complaint about a display closed by one $. Raising the floor
       keeps the number's list looking like the outermost one, so that a
       group opened inside it is still told apart from the formula. */
    engine->reading_equation_number = true;
    engine->equation_number_on_left = left;
    /* The number has a GROUP of its own, with its own \fam: the reference
       gives that one back on its own -- `{restoring \fam=-1}' -- between the
       complaint about a single $ and the measuring of the equation. */
    if (begin_group(engine, HSTEX_GROUP_MATH_SHIFT, error, error_capacity) !=
            0 ||
        assign_integer_parameter(engine, (uint32_t)HSTEX_INTEGER_FAMILY, -1,
                                 false, error, error_capacity) != 0) {
        return -1;
    }
    /* An equation number is set in text style and is internal: \ifinner is
       true inside one, and the reference names the mode "math mode" rather
       than "display math mode" when it refuses a second \eqno there. The
       mode is changed AFTER the number's list is pushed, so that the
       display's own level keeps the mode it was in -- pushing a level writes
       down what the level under it holds. */
    ++engine->math_floor;
    if (push_math_list(engine, (uint8_t)HSTEX_STYLE_TEXT, error,
                       error_capacity) != 0) {
        return -1;
    }
    engine->inner_mode = true;
    return 0;
}

/* AN OVERFULL EQUATION GETS A RULE. A display's equation is squeezed into
   the room it has rather than packed afresh, but the reference still puts
   \overfullrule at its right where the squeeze asks for more than the glue
   can give up -- which is why the short display of such a line ends in `|'.
   The equation's nodes stand at the end of the list store, so the rule joins
   them there. See docs/DECISIONS.md, a-display-squeezed-to-fit. */
static int add_overfull_rule(struct hstex_engine *engine,
                             struct hstex_box *box, int32_t natural,
                             const struct hstex_glue *total, char *error,
                             size_t error_capacity)
{
    int64_t excess = (int64_t)natural - box->width;
    int32_t rule_width = engine->dimen_parameters[HSTEX_DIMEN_OVERFULL_RULE];
    if (engine->packing_quietly || box->node_count == 0U || rule_width <= 0 ||
        excess <= 0 || total->shrink_order != 0U ||
        excess - (int64_t)total->shrink <=
            (int64_t)engine->dimen_parameters[HSTEX_DIMEN_HFUZZ]) {
        return 0;
    }
    struct hstex_node rule = {
        .kind = HSTEX_NODE_RULE,
        .width = rule_width,
        .height = HSTEX_RUNNING_DIMEN,
        .depth = HSTEX_RUNNING_DIMEN,
    };
    uint32_t identifier = 0U;
    if (store_node(engine, &rule, &identifier, error, error_capacity) != 0) {
        return -1;
    }
    if ((size_t)box->node_start + box->node_count == engine->list_item_count) {
        /* The equation's nodes are the last in the store, so the rule joins
           them where they stand. */
        if (reserve_list_items(engine, engine->list_item_count + 1U, error,
                               error_capacity) != 0) {
            return -1;
        }
        engine->list_items[engine->list_item_count++] = identifier;
        box->node_count += 1U;
        return 0;
    }
    /* Otherwise the run is written out again with the rule behind it. */
    size_t held = box->node_count;
    if (reserve_list_items(engine, engine->list_item_count + held + 1U, error,
                           error_capacity) != 0) {
        return -1;
    }
    size_t start = engine->list_item_count;
    memcpy(engine->list_items + start, engine->list_items + box->node_start,
           held * sizeof(*engine->list_items));
    engine->list_items[start + held] = identifier;
    engine->list_item_count = start + held + 1U;
    box->node_start = (uint32_t)start;
    box->node_count = (uint32_t)(held + 1U);
    return 0;
}

/* Build the line the display occupies, with its number beside it when there
   is room. */
/* Whether the number can stand beside the equation: the reference wants a
   quad of the symbol family between them as well. */
static int equation_number_fits(struct hstex_engine *engine,
                                const struct hstex_box *equation,
                                const struct hstex_box *number, int32_t width,
                                bool *fits, char *error, size_t error_capacity)
{
    if (number == NULL) {
        *fits = false;
        return 0;
    }
    /* A NUMBER OF NO WIDTH DOES NOT GO BESIDE THE EQUATION. Measured:
       `$$\hbox{}\eqno\hbox{}$$' sets the number on a line of its own, where
       `$$\hbox{}\eqno\hbox to 10pt{}$$' sets it beside. What the reference
       measures is the number's own width, and nought means there is nothing
       to set beside -- the same answer it gives when there is no number at
       all. */
    if (number->width == 0) {
        *fits = false;
        return 0;
    }
    int32_t quad = 0;
    if (math_symbol_parameter(engine, (uint8_t)HSTEX_MATH_TEXT, 6U, &quad,
                              error, error_capacity) != 0) {
        return -1;
    }
    /* The equation may shrink to make room for its number; see
       docs/DECISIONS.md, a-number-beside-a-squeezed-equation. */
    struct hstex_glue spare = {0};
    if ((size_t)equation->node_start + equation->node_count <=
        engine->list_item_count) {
        spare = list_total_glue(engine,
                                engine->list_items + equation->node_start,
                                equation->node_count);
    }
    if (spare.shrink_order != 0U) {
        *fits = true;
        return 0;
    }
    *fits = (int64_t)equation->width - spare.shrink + number->width + quad <=
            width;
    return 0;
}

static int append_display_line(struct hstex_engine *engine,
                               struct hstex_box equation,
                               const struct hstex_box *number, bool left,
                               int32_t width, int32_t indent, int32_t *shift,
                               bool dropped, char *error,
                               size_t error_capacity)
{
    int32_t e = number == NULL || dropped ? 0 : number->width;
    if (e != 0) {
        /* The equation is set to exactly the room the number leaves it; see
           docs/DECISIONS.md, a-number-beside-a-squeezed-equation. */
        int32_t quad = 0;
        if (math_symbol_parameter(engine, (uint8_t)HSTEX_MATH_TEXT, 6U, &quad,
                                  error, error_capacity) != 0) {
            return -1;
        }
        int32_t room = (int32_t)((int64_t)width - e - quad);
        if (equation.width > room &&
            (size_t)equation.node_start + equation.node_count <=
                engine->list_item_count) {
            struct hstex_glue spare = list_total_glue(
                engine, engine->list_items + equation.node_start,
                equation.node_count);
            /* The reference packs the equation again here rather than
               setting its glue, so a squeeze that does not fit is
               reported. See docs/DECISIONS.md, boxes-that-do-not-fit. */
            int32_t natural = equation.width;
            equation.glue = packing_glue_set(equation.width, room, &spare);
            equation.width = room;
            engine->badness = packing_badness(natural, room, &spare);
            if (add_overfull_rule(engine, &equation, natural, &spare, error,
                                  error_capacity) != 0) {
                return -1;
            }
            report_packing(engine, &equation, natural, &spare, false,
                           engine->list_items + equation.node_start,
                           equation.node_count);
        }
    }
    if (e == 0 && equation.width > width) {
        /* An equation too wide for the room it has is squeezed into it
           rather than centred, and its glue takes up the difference; see
           docs/DECISIONS.md, a-display-squeezed-to-fit. */
        if ((size_t)equation.node_start + equation.node_count <=
            engine->list_item_count) {
            struct hstex_glue spare = list_total_glue(
                engine, engine->list_items + equation.node_start,
                equation.node_count);
            int32_t natural = equation.width;
            equation.glue = packing_glue_set(equation.width, width, &spare);
            equation.width = width;
            engine->badness = packing_badness(natural, width, &spare);
            if (add_overfull_rule(engine, &equation, natural, &spare, error,
                                  error_capacity) != 0) {
                return -1;
            }
            report_packing(engine, &equation, natural, &spare, false,
                           engine->list_items + equation.node_start,
                           equation.node_count);
        }
        equation.width = width;
    }
    int32_t w = equation.width;
    int32_t d = (int32_t)(((int64_t)width - w + 1) / 2);
    if (e > 0 && d < 2 * e) {
        d = (int32_t)(((int64_t)width - w - e + 1) / 2);
        /* AND WHERE THE EQUATION BEGINS WITH GLUE there is no room to take:
           the reference gives the number all of it and leaves the equation
           where the display's indentation puts it. See docs/DECISIONS.md,
           a-number-beside-an-equation-that-begins-with-glue. */
        if (equation.node_count != 0U &&
            (size_t)equation.node_start < engine->list_item_count) {
            uint32_t first_item = engine->list_items[equation.node_start];
            if (first_item != 0U &&
                (size_t)first_item <= engine->node_count &&
                engine->nodes[first_item - 1U].kind == HSTEX_NODE_GLUE) {
                d = 0;
            }
        }
    }
    *shift = indent + (left && e != 0 ? 0 : d);
    if (e == 0) {
        struct hstex_node node = {
            .kind = HSTEX_NODE_LIST,
            .width = equation.width,
            .height = equation.height,
            .depth = equation.depth,
            .shift = *shift,
            .value.list = {
                .node_start = equation.node_start,
                .node_count = equation.node_count,
                .box_kind = equation.kind,
                .glue = equation.glue,
                .display = true,
            },
        };
        return append_vbox_node(engine, &node, error, error_capacity);
    }
    struct hstex_hbox_builder builder = {0};
    struct hstex_hbox_builder *previous = engine->active_hbox_builder;
    enum hstex_mode previous_mode = engine->mode;
    engine->active_hbox_builder = &builder;
    engine->mode = HSTEX_MODE_HORIZONTAL;
    struct hstex_node gap = {
        .kind = HSTEX_NODE_KERN,
        .width = (int32_t)((int64_t)width - w - e - d),
    };
    uint32_t identifier = 0U;
    int status = 0;
    const struct hstex_box *first = left ? number : &equation;
    const struct hstex_box *second = left ? &equation : number;
    /* The equation and its number are each marked; the line they are packed
       into is not. See docs/DECISIONS.md, display-math. */
    if (store_box_node(engine, first, 0, &identifier, error, error_capacity) !=
        0) {
        status = -1;
    } else {
        engine->nodes[identifier - 1U].value.list.display = true;
        if (append_hbox_item(engine, identifier, error, error_capacity) != 0 ||
            append_hbox_node(engine, &gap, error, error_capacity) != 0 ||
            store_box_node(engine, second, 0, &identifier, error,
                           error_capacity) != 0) {
            status = -1;
        } else {
            engine->nodes[identifier - 1U].value.list.display = true;
            if (append_hbox_item(engine, identifier, error, error_capacity) !=
                0) {
                status = -1;
            }
        }
    }
    struct hstex_box line = {0};
    if (status == 0) {
        status = finalize_hbox(engine, &builder, false, false, 0, &line, error,
                               error_capacity);
    }
    free(builder.node_identifiers);
    engine->active_hbox_builder = previous;
    engine->mode = previous_mode;
    if (status != 0) {
        return -1;
    }
    struct hstex_node node = {
        .kind = HSTEX_NODE_LIST,
        .width = line.width,
        .height = line.height,
        .depth = line.depth,
        .shift = *shift,
        .value.list = {
            .node_start = line.node_start,
            .node_count = line.node_count,
            .box_kind = line.kind,
            .glue = line.glue,
        },
    };
    return append_vbox_node(engine, &node, error, error_capacity);
}

static int resume_paragraph_after_display(struct hstex_engine *engine,
                                          char *error, size_t error_capacity);

/* The closing $$ centres the formula in \displaywidth, surrounds it with the
   display penalties and skips, and lets the paragraph carry on. */
static int end_display_math(struct hstex_engine *engine,
                            struct hstex_box packaged, char *error,
                            size_t error_capacity)
{
    bool numbered = engine->reading_equation_number;
    bool left = engine->equation_number_on_left;
    struct hstex_box equation = packaged;
    struct hstex_box number = packaged;
    if (numbered) {
        /* The number's group is given back first, and only then is the
           equation measured: `{restoring \fam=-1}' stands between the
           complaint about the single $ and the second `Insufficient
           extension fonts'. */
        if (end_group(engine, error, error_capacity) < 0) {
            return -1;
        }
        /* What was in hand was the NUMBER; the equation is measured now, so
           its own `Insufficient extension fonts' comes after the complaint
           about the single $ rather than before it. */
        if (engine->math_floor != 0U) {
            --engine->math_floor;
        }
        if (package_displayed_formula(engine, math_fonts_are_missing(engine),
                                      &equation, error,
                                      error_capacity) != 0) {
            return -1;
        }
    }
    engine->reading_equation_number = false;
    /* The group the display opened is closed only once the display has been
       put on the vertical list, so that the glue in front of it is the glue
       the display itself asked for; see docs/DECISIONS.md,
       a-display-closes-its-group-last. */
    engine->displayed_math = false;
    engine->mode = HSTEX_MODE_VERTICAL;
    engine->inner_mode = vertical_list_is_inner(engine);

    int32_t width = engine->dimen_parameters[HSTEX_DIMEN_DISPLAY_WIDTH];
    int32_t indent = engine->dimen_parameters[HSTEX_DIMEN_DISPLAY_INDENT];
    int32_t before = engine->dimen_parameters[HSTEX_DIMEN_PRE_DISPLAY_SIZE];
    int32_t shift = 0;
    bool fits = false;
    if (equation_number_fits(engine, &equation, numbered ? &number : NULL,
                             width, &fits, error, error_capacity) != 0) {
        return -1;
    }
    bool dropped = numbered && !fits;

    /* The line is measured first, because whether the number fits beside it
       decides both the skips and where the number goes. The offset is the
       one the display will really be given, number and all; see
       docs/DECISIONS.md, a-short-display-skip. */
    int32_t room = numbered && !dropped ? number.width : 0;
    int32_t measured = equation.width;
    if (room == 0 && measured > width) {
        measured = width;
    }
    int32_t trial = (int32_t)(((int64_t)width - measured + 1) / 2);
    if (room > 0 && trial < 2 * room) {
        trial = (int32_t)(((int64_t)width - measured - room + 1) / 2);
    }
    bool roomy = numbered && left
                     ? true
                     : (int64_t)trial + indent <= (int64_t)before;
    enum hstex_glue_parameter above_parameter =
        roomy ? HSTEX_GLUE_ABOVE_DISPLAY_SKIP
              : HSTEX_GLUE_ABOVE_DISPLAY_SHORT_SKIP;
    enum hstex_glue_parameter below_parameter =
        roomy ? HSTEX_GLUE_BELOW_DISPLAY_SKIP
              : HSTEX_GLUE_BELOW_DISPLAY_SHORT_SKIP;
    struct hstex_glue above = engine->glue_parameters[above_parameter];
    struct hstex_glue below = engine->glue_parameters[below_parameter];
    struct hstex_node penalty = {
        .kind = HSTEX_NODE_PENALTY,
        .value.penalty =
            engine->integer_parameters[HSTEX_INTEGER_PRE_DISPLAY_PENALTY],
    };
    struct hstex_node infinite = {
        .kind = HSTEX_NODE_PENALTY,
        .value.penalty = HSTEX_INFINITE_PENALTY,
    };

    /* A number on the left that will not fit beside the equation takes the
       place of the GLUE above it -- but not of the penalty, which still
       comes first: measured, `$$\hbox{}\leqno\hbox{}$$' puts
       \predisplaypenalty above the number's own line and no
       \abovedisplayskip at all. */
    bool left_alone = dropped && left;
    if (left_alone) {
        if (append_vbox_node(engine, &penalty, error, error_capacity) != 0) {
            return -1;
        }
        struct hstex_node node = {
            .kind = HSTEX_NODE_LIST,
            .width = number.width,
            .height = number.height,
            .depth = number.depth,
            .shift = indent,
            .value.list = {
                .node_start = number.node_start,
                .node_count = number.node_count,
                .box_kind = number.kind,
                .glue = number.glue,
                .display = true,
            },
        };
        if (append_vbox_node(engine, &node, error, error_capacity) != 0 ||
            append_vbox_node(engine, &infinite, error, error_capacity) != 0) {
            return -1;
        }
    } else if (append_vbox_node(engine, &penalty, error, error_capacity) != 0 ||
               append_display_glue(engine, above, above_parameter, error,
                                   error_capacity) != 0) {
        return -1;
    }

    /* What a \vadjust, an \insert or a \mark left at the top level of the
       equation moves out of it, the way it moves out of an \hbox put on a
       vertical list: it lands right behind the display's line and in front
       of \postdisplaypenalty. See
       tests/trip/probes/what-migrates-out-of-a-display.tex. */
    uint32_t *migrated = NULL;
    size_t migrated_count = 0U;
    if (migrate_out_of_hbox(engine, &equation, &migrated, &migrated_count,
                            error, error_capacity) != 0) {
        return -1;
    }
    if (append_display_line(engine, equation, numbered ? &number : NULL, left,
                            width, indent, &shift, dropped, error,
                            error_capacity) != 0) {
        free(migrated);
        return -1;
    }
    if (dropped && !left) {
        /* A number on the right that would not fit goes below, against the
           right edge, and the glue under the display goes away. */
        struct hstex_node node = {
            .kind = HSTEX_NODE_LIST,
            .width = number.width,
            .height = number.height,
            .depth = number.depth,
            .shift = indent + width - number.width,
            .value.list = {
                .node_start = number.node_start,
                .node_count = number.node_count,
                .box_kind = number.kind,
                .glue = number.glue,
                /* A number set on a line of its own is still a display
                   line; see docs/DECISIONS.md, display-math. */
                .display = true,
            },
        };
        if (append_vbox_node(engine, &infinite, error, error_capacity) != 0 ||
            append_vbox_node(engine, &node, error, error_capacity) != 0) {
            free(migrated);
            return -1;
        }
        below.width = 0;
        below.stretch = 0;
        below.shrink = 0;
        below.stretch_order = 0U;
        below.shrink_order = 0U;
    }
    /* As with a box, what moves out goes on as it stands and is not
       something the next line is set against -- and it goes behind the
       WHOLE display, a number set on a line of its own included. */
    int32_t depth_before_migration = engine->prev_depth;
    for (size_t item = 0U; item < migrated_count; ++item) {
        if (append_vbox_item(engine, migrated[item], error,
                             error_capacity) != 0) {
            free(migrated);
            return -1;
        }
    }
    engine->prev_depth = depth_before_migration;
    free(migrated);
    penalty.value.penalty =
        engine->integer_parameters[HSTEX_INTEGER_POST_DISPLAY_PENALTY];
    if (append_vbox_node(engine, &penalty, error, error_capacity) != 0) {
        return -1;
    }
    if (!(dropped && !left) &&
        append_display_glue(engine, below, below_parameter, error,
                            error_capacity) != 0) {
        return -1;
    }
    if (end_group(engine, error, error_capacity) < 0) {
        return -1;
    }
    return resume_paragraph_after_display(engine, error, error_capacity);
}

/* The paragraph carries on, with no indentation and no \everypar, and a
   space right after the display is ignored. */
static int resume_paragraph_after_display(struct hstex_engine *engine,
                                          char *error, size_t error_capacity)
{
    if (engine->paragraph_builder == NULL) {
        engine->paragraph_builder =
            calloc(1U, sizeof(*engine->paragraph_builder));
        if (engine->paragraph_builder == NULL) {
            return set_error(error, error_capacity,
                             "paragraph list allocation failed");
        }
    }
    engine->paragraph_builder->count = 0U;
    engine->paragraph_builder->width = 0;
    engine->paragraph_builder->height = 0;
    engine->paragraph_builder->depth = 0;
    /* The reference starts a FRESH LEVEL here rather than taking the old one
       up again -- the paragraph's own went when the display began -- so what
       is reported of the lines after a display is reported against the line
       the display ended on. The push comes before the mode changes, so that
       the vertical level under it keeps the mode it was in. See
       docs/DECISIONS.md, boxes-that-do-not-fit. */
    if (nest_push(engine, error, error_capacity) != 0) {
        return -1;
    }
    engine->active_hbox_builder = engine->paragraph_builder;
    engine->mode = HSTEX_MODE_HORIZONTAL;
    engine->inner_mode = false;
    engine->building_paragraph = true;
    engine->space_factor = 1000;
    engine->has_pending_character = false;
    /* The display counts as three lines of the paragraph it interrupted; see
       docs/DECISIONS.md, lines-carry-on-past-a-display. */
    engine->prev_graf += 3;
    if (skip_optional_space(engine, error, error_capacity) != 0) {
        return -1;
    }
    /* Everything the display contributes has reached the vertical list, so
       the page builder runs here -- outside the display's group, which has
       already given its parameters back, and after the blank the display may
       be followed by, which is looked for first and expands as it looks. An
       expandable token standing right after the $$ is therefore expanded
       BEFORE the output routine any of this fires. See docs/DECISIONS.md,
       a-page-that-breaks-at-a-display. The paragraph is already standing in
       horizontal mode by now; the reference's page builder does not consult
       the mode at all, only the list, so the vertical mode it works in is
       lent to it here and given back after. */
    if (engine->active_vbox_builder != engine->contribution_builder) {
        return 0;
    }
    enum hstex_mode resumed_mode = engine->mode;
    bool resumed_inner = engine->inner_mode;
    engine->mode = HSTEX_MODE_VERTICAL;
    engine->inner_mode = false;
    int built = build_page(engine, error, error_capacity);
    engine->mode = resumed_mode;
    engine->inner_mode = resumed_inner;
    return built;
}

/* The $$ that closes an alignment used as a display reads the penalties and
   skips around it -- assignments between the alignment and the $$ still
   count -- and puts the rows between them. See docs/DECISIONS.md,
   display-alignments. */
static int end_display_alignment(struct hstex_engine *engine, char *error,
                                 size_t error_capacity)
{
    struct hstex_vbox_builder *rows = engine->display_rows;
    engine->display_rows = NULL;
    engine->display_alignment = false;
    engine->mode = HSTEX_MODE_VERTICAL;
    engine->inner_mode = false;
    struct hstex_node penalty = {
        .kind = HSTEX_NODE_PENALTY,
        .value.penalty =
            engine->integer_parameters[HSTEX_INTEGER_PRE_DISPLAY_PENALTY],
    };
    int status = append_vbox_node(engine, &penalty, error, error_capacity);
    if (status == 0) {
        status = append_display_glue(
            engine, engine->glue_parameters[HSTEX_GLUE_ABOVE_DISPLAY_SKIP],
            HSTEX_GLUE_ABOVE_DISPLAY_SKIP, error, error_capacity);
    }
    for (size_t index = 0U; status == 0 && rows != NULL && index < rows->count;
         ++index) {
        status = append_vbox_item(engine, rows->node_identifiers[index], error,
                                  error_capacity);
    }
    if (status == 0) {
        engine->prev_depth = engine->display_prev_depth;
    }
    if (rows != NULL) {
        free(rows->node_identifiers);
        free(rows);
    }
    if (status != 0) {
        return -1;
    }
    penalty.value.penalty =
        engine->integer_parameters[HSTEX_INTEGER_POST_DISPLAY_PENALTY];
    if (append_vbox_node(engine, &penalty, error, error_capacity) != 0 ||
        append_display_glue(
            engine, engine->glue_parameters[HSTEX_GLUE_BELOW_DISPLAY_SKIP],
            HSTEX_GLUE_BELOW_DISPLAY_SKIP, error, error_capacity) != 0) {
        return -1;
    }
    if (end_group(engine, error, error_capacity) < 0) {
        return -1;
    }
    return resume_paragraph_after_display(engine, error, error_capacity);
}

/* Entering a formula opens a group, sets \fam to none, and inserts
   \everymath. The reference sets \fam before \everymath runs, so a token
   list may select a family for the whole formula. */
static int begin_math(struct hstex_engine *engine, char *error,
                      size_t error_capacity)
{
    if (flush_pending_character(engine, error, error_capacity) != 0) {
        return -1;
    }
    if (begin_group(engine, HSTEX_GROUP_MATH_SHIFT, error, error_capacity) != 0) {
        return -1;
    }
    if (assign_integer_parameter(engine, (uint32_t)HSTEX_INTEGER_FAMILY, -1,
                                 false, error, error_capacity) != 0) {
        return -1;
    }
    if (push_math_list(engine, (uint8_t)HSTEX_STYLE_TEXT, error,
                       error_capacity) != 0) {
        return -1;
    }
    /* A formula between single shifts is an inner mode, and is never a
       display even when one encloses it. */
    current_math_list(engine)->outer_inner_mode = engine->inner_mode;
    current_math_list(engine)->outer_displayed = engine->displayed_math;
    engine->inner_mode = true;
    engine->displayed_math = false;
    engine->mode = HSTEX_MODE_MATH;
    uint32_t every_math = engine->token_parameters[HSTEX_TOKEN_EVERY_MATH];
    if (every_math == 0U) {
        return 0;
    }
    const struct hstex_token_list *list =
        token_list_by_identifier(engine, every_math);
    struct hstex_source_location location = {0};
    if (list == NULL ||
        hstex_source_push_tokens(&engine->sources, list->tokens, list->count,
                                 location, error, error_capacity) != 0) {
        return set_error(error, error_capacity,
                         "could not install everymath tokens");
    }
    hstex_source_name_top(&engine->sources,
                          (uint8_t)HSTEX_TOKEN_SOURCE_TOKEN_PARAMETER,
                          (uint32_t)HSTEX_TOKEN_EVERY_MATH);
    trace_token_parameter(engine, (size_t)HSTEX_TOKEN_EVERY_MATH);
    return 0;
}

/* A brace inside a formula collects a sub-formula, which becomes one
   ordinary atom -- or the script the mark before it is waiting for, in which
   case it is set in the style that script will be typeset at. */
static int begin_math_group(struct hstex_engine *engine, char *error,
                            size_t error_capacity)
{
    struct hstex_math_builder *outer = current_math_list(engine);
    uint8_t style =
        outer == NULL ? (uint8_t)HSTEX_STYLE_TEXT : outer->current_style;
    if (outer != NULL && outer->choice_remaining == 0U) {
        if (outer->slot == (uint8_t)HSTEX_MATH_SLOT_SUPERSCRIPT) {
            style = math_superscript_style(outer->current_style);
        } else if (outer->slot == (uint8_t)HSTEX_MATH_SLOT_SUBSCRIPT) {
            style = math_subscript_style(outer->current_style);
        } else if (outer->slot == (uint8_t)HSTEX_MATH_SLOT_RADICAND) {
            style = math_cramped_style(outer->current_style);
        }
    }
    /* A sub-formula that stands as an ordinary atom is the NUCLEUS of a noad
       the reference has already put in the list around it; HSTeX makes that
       noad when the braces close, so the list remembers it is coming and
       \showlists writes it. A sub-formula filling a script or a branch of a
       \mathchoice fills a noad that is there already. */
    if (outer != NULL && outer->choice_remaining == 0U &&
        outer->slot == (uint8_t)HSTEX_MATH_SLOT_NONE) {
        outer->pending_atom =
            (uint8_t)(1U + (outer->forced_class >= 0
                                ? (uint8_t)outer->forced_class
                                : (uint8_t)HSTEX_ATOM_ORD));
    }
    return push_math_list(engine, style, error, error_capacity);
}

/* Returns 1 when the brace closed nothing and was deleted, so that the
   caller ends no group for it either; 0 when a group really closed. */
static int finish_math_group(struct hstex_engine *engine, char *error,
                             size_t error_capacity)
{
    struct hstex_math_builder *inner = current_math_list(engine);
    if (inner == NULL || engine->math_depth < engine->math_floor + 2U) {
        /* The reference deletes a } that closes nothing and goes on.
           trip line 249 writes one more } than it opened. */
        static const char *const help[] = {
            "I've deleted a group-closing symbol because it seems to be",
            "spurious, as in `$x}$'. But perhaps the } is legitimate and",
            "you forgot something else, as in `\\hbox{$x}'. In such cases",
            "the way to recover is to insert both the forgotten and the",
            "deleted material, e.g., by typing `I$}'.", NULL};
        tex_error(engine, help, "Extra }, or forgotten $");
        return 1;
    }
    struct hstex_math_builder *outer = &engine->math_stack[engine->math_depth - 2U];
    if (outer->choice_remaining != 0U) {
        /* One branch of a \mathchoice. All four are kept, because which one
           is wanted depends on the style the list is finally set in, and a
           fraction settles that only when \over is read. */
        uint32_t record = 0U;
        int status =
            store_math_sublist(engine, inner, &record, error, error_capacity);
        if (status == 0 && outer->choice_noad < outer->count) {
            outer->noads[outer->choice_noad].choices[outer->choice_index] =
                record;
        }
        ++outer->choice_index;
        --outer->choice_remaining;
        pop_math_list(engine);
        /* The brace of the branch that follows is wanted here, where the one
           before has just closed. */
        if (status == 0 && outer->choice_remaining != 0U) {
            status = require_left_brace(engine, error, error_capacity);
        }
        return status;
    }
    /* One ordinary atom in braces is that atom: {x} carries scripts exactly
       as x does, however deeply the braces nest. A list that turned into a
       FRACTION is not one atom, however few noads stand on either side of
       the \over: `{B\over}' is a fraction with an empty denominator. */
    if (inner->count == 1U && !inner->has_fraction &&
        inner->noads[0].kind == (uint8_t)HSTEX_NOAD_ATOM &&
        inner->noads[0].atom_class == (uint8_t)HSTEX_ATOM_ORD &&
        !inner->noads[0].vcentered &&
        inner->noads[0].superscript.kind ==
            (uint8_t)HSTEX_MATH_FIELD_EMPTY &&
        inner->noads[0].subscript.kind == (uint8_t)HSTEX_MATH_FIELD_EMPTY &&
        inner->slot == (uint8_t)HSTEX_MATH_SLOT_NONE) {
        struct hstex_noad passed = inner->noads[0];
        pop_math_list(engine);
        return math_append_atom(engine, &passed, error, error_capacity);
    }
    /* An accent alone in braces takes the place of the ordinary atom the
       braces would have made, scripts and all. Only an ordinary atom gives
       way to it: \mathop{...} and a script keep the sub-formula. See
       docs/DECISIONS.md, an-accent-alone-in-braces. */
    if (inner->count == 1U && !inner->has_fraction &&
        inner->noads[0].kind == (uint8_t)HSTEX_NOAD_ACCENT &&
        inner->slot == (uint8_t)HSTEX_MATH_SLOT_NONE &&
        outer->slot == (uint8_t)HSTEX_MATH_SLOT_NONE &&
        (outer->forced_class < 0 ||
         outer->forced_class == (int)HSTEX_ATOM_ORD)) {
        struct hstex_noad passed = inner->noads[0];
        outer->forced_class = -1;
        pop_math_list(engine);
        return math_append(engine, &passed, error, error_capacity);
    }
    struct hstex_hbox_builder builder = {0};
    struct hstex_hbox_builder *previous = engine->active_hbox_builder;
    engine->active_hbox_builder = &builder;
    if (inner->slot != (uint8_t)HSTEX_MATH_SLOT_NONE) {
        engine->active_hbox_builder = previous;
        free(builder.node_identifiers);
        pop_math_list(engine);
        return set_error(error, error_capacity,
                         "a script mark was left without a script");
    }
    /* A SUB-FORMULA IS NOT SET WHEN ITS BRACE CLOSES: the reference keeps
       the list and sets the whole formula when the $ arrives, so whatever
       the setting reports -- an undefined family, a character the font has
       not got, an overfull box -- is reported there and not here, and a
       formula that never gets set at all reports nothing. Keeping a style
       that no style can equal makes the setting happen when the field is
       first asked for its box. See docs/DECISIONS.md,
       when-a-sub-formula-is-set. */
    bool deferred = true;
    /* The list is kept as well as the box, because a fraction sets each of
       its sides in a style that is not known until \over is read. */
    uint32_t record = 0U;
    uint8_t item_style = deferred ? (uint8_t)0xFFU : inner->style;
    int status = store_math_sublist(engine, inner, &record, error,
                                    error_capacity);
    if (status == 0 && !deferred) {
        status = translate_math_list(engine, inner, error, error_capacity);
    }
    engine->active_hbox_builder = previous;
    struct hstex_box box = {0};
    if (status == 0 && !deferred) {
        status = finalize_hbox(engine, &builder, false, false, 0, &box, error,
                               error_capacity);
    }
    free(builder.node_identifiers);
    pop_math_list(engine);
    if (status != 0) {
        return -1;
    }
    /* A sub-formula that came to one character carries scripts the way that
       character would; see docs/DECISIONS.md, math-scripts. A shifted node is
       not one, because a centred large operator is a box. */
    bool single = false;
    if (box.node_count == 1U &&
        (size_t)box.node_start < engine->list_item_count) {
        uint32_t identifier = engine->list_items[box.node_start];
        if (identifier != 0U && identifier <= engine->node_count) {
            const struct hstex_node *node = &engine->nodes[identifier - 1U];
            single = (node->kind == HSTEX_NODE_CHARACTER ||
                      node->kind == HSTEX_NODE_LIGATURE) &&
                     node->shift == 0;
        }
    }
    return math_append_box_field(engine, &box, single, record, item_style,
                                 error, error_capacity);
}

/* Leaving a formula puts \mathsurround on both sides of the translation and
   splices it into the horizontal list that was interrupted. */
/* A formula needs the fonts it will measure itself against: family 2 in
   all three sizes with the twenty-two parameters a symbol font has, and
   family 3 with the thirteen an extension font has. Measured against the
   reference: twelve in family 3 is not enough and thirteen is, twenty-one
   in family 2 is not enough and twenty-two is, and family 2 is asked about
   first. A formula that cannot be measured is DELETED -- what is left is
   the \mathon and \mathoff around nothing. */
static bool math_family_is_short(struct hstex_engine *engine, uint8_t family,
                                 size_t wanted)
{
    for (uint8_t size = 0U; size < (uint8_t)HSTEX_MATH_SIZE_COUNT; ++size) {
        const struct hstex_font *font = math_family_font(engine, size, family);
        if (font == NULL || font->dimen_count < wanted) {
            return true;
        }
    }
    return false;
}

static bool math_fonts_are_missing(struct hstex_engine *engine)
{
    if (math_family_is_short(engine, 2U, 22U)) {
        static const char *const help[] = {
            "Sorry, but I can't typeset math unless \\textfont 2",
            "and \\scriptfont 2 and \\scriptscriptfont 2 have all",
            "the \\fontdimen values needed in math symbol fonts.", NULL};
        tex_error(engine, help,
                  "Math formula deleted: Insufficient symbol fonts");
        return true;
    }
    if (math_family_is_short(engine, 3U, 13U)) {
        static const char *const help[] = {
            "Sorry, but I can't typeset math unless \\textfont 3",
            "and \\scriptfont 3 and \\scriptscriptfont 3 have all",
            "the \\fontdimen values needed in math extension fonts.", NULL};
        tex_error(engine, help,
                  "Math formula deleted: Insufficient extension fonts");
        return true;
    }
    return false;
}

static int end_math(struct hstex_engine *engine, char *error,
                    size_t error_capacity)
{
    struct hstex_math_builder *list = current_math_list(engine);
    if (list == NULL || engine->math_depth != engine->math_floor + 1U) {
        return set_error(error, error_capacity,
                         "a formula closed inside a math group");
    }
    engine->mode = HSTEX_MODE_HORIZONTAL;
    engine->inner_mode = list->outer_inner_mode;
    engine->displayed_math = list->outer_displayed;
    /* A formula sets the space factor back to a thousand; see
       docs/DECISIONS.md, what-resets-the-space-factor. */
    engine->space_factor = 1000;
    /* The formula is fenced with nodes of its own rather than kerns: they
       carry \mathsurround, they tell the line breaker where a formula
       begins and ends, and \showbox names them. See docs/DECISIONS.md,
       math-nodes. */
    int32_t surround = engine->dimen_parameters[HSTEX_DIMEN_MATH_SURROUND];
    struct hstex_node opening = {
        .kind = HSTEX_NODE_MATH,
        .width = surround,
        .value.math = {.after = false},
    };
    struct hstex_node closing = {
        .kind = HSTEX_NODE_MATH,
        .width = surround,
        .value.math = {.after = true},
    };
    bool deleted = math_fonts_are_missing(engine);
    int status = append_hbox_node(engine, &opening, error, error_capacity);
    if (status == 0 && !deleted) {
        /* Only a formula set in a paragraph gets the penalties. */
        status = translate_math_list_with(engine, list, !engine->inner_mode,
                                          error, error_capacity);
    }
    if (status == 0) {
        status = append_hbox_node(engine, &closing, error, error_capacity);
    }
    pop_math_list(engine);
    if (status != 0) {
        return -1;
    }
    /* A brace with no group to end is gone, and that is not a failure. */
    return end_group(engine, error, error_capacity) < 0 ? -1 : 0;
}

/* \textfont, \scriptfont and \scriptscriptfont: a family number, then a font.
   The assignment is local like a register's, and \global makes it global
   like a register's -- trip line 268 writes `\global\scriptscriptfont0=
   \trip' and nothing is restored for it. The prefix is read before the
   operands, as every prefix is. */
static int execute_math_font(struct hstex_engine *engine, int32_t size,
                             char *error, size_t error_capacity)
{
    bool global = assignment_is_global(engine, engine->pending_global);
    int32_t family = 0;
    if (scan_four_bit_int(engine, &family, error, error_capacity) != 0) {
        return -1;
    }
    if (scan_optional_equals(engine, error, error_capacity) != 0) {
        return -1;
    }
    uint32_t identifier = 0U;
    if (scan_font_identifier(engine, &identifier, error, error_capacity) != 0) {
        return -1;
    }
    if (size < 0 || size >= (int32_t)HSTEX_MATH_SIZE_COUNT) {
        return set_error(error, error_capacity, "invalid math font size");
    }
    uint32_t index = (uint32_t)size * 16U + (uint32_t)family;
    uint32_t *level = &engine->math_font_levels[size][family];
    if (!global && engine->group_level != 0U) {
        if (save_value(engine, HSTEX_SAVE_MATH_FONT, index, *level,
                       (int32_t)engine->math_fonts[size][family], 0U, error,
                       error_capacity) != 0) {
            return -1;
        }
        *level = engine->group_level;
    } else {
        *level = 0U;
    }
    engine->math_fonts[size][family] = identifier;
    engine->pending_global = false;
    return 0;
}

/* Choosing a font is an assignment like any other: the group that made it
   puts the old font back on the way out. See docs/DECISIONS.md,
   the-current-font-is-grouped. */
static int select_font(struct hstex_engine *engine, uint32_t identifier,
                       char *error, size_t error_capacity)
{
    bool global = assignment_is_global(engine, engine->pending_global);
    if (!global && engine->group_level != 0U) {
        if (save_value(engine, HSTEX_SAVE_FONT, 0U, engine->current_font_level,
                       (int32_t)engine->current_font, 0U, error,
                       error_capacity) != 0) {
            return -1;
        }
        engine->current_font_level = engine->group_level;
    } else {
        engine->current_font_level = 0U;
    }
    engine->current_font = identifier;
    return 0;
}

static int execute_math_char(struct hstex_engine *engine, char *error,
                             size_t error_capacity)
{
    int32_t code = 0;
    if (scan_integer(engine, &code, error, error_capacity) != 0) {
        return -1;
    }
    if (code < 0 || code > 0x7FFF) {
        return set_error(error, error_capacity,
                         "mathchar %d is outside 0..32767", code);
    }
    if (engine->mode != HSTEX_MODE_MATH) {
        return set_error(error, error_capacity,
                         "a math character is only allowed in a formula");
    }
    return math_append_code(engine, code, error, error_capacity);
}

/* A style command changes the style of everything after it in its list. */
static int execute_math_style(struct hstex_engine *engine, int32_t style,
                              char *error, size_t error_capacity)
{
    if (engine->mode != HSTEX_MODE_MATH) {
        return set_error(error, error_capacity,
                         "a math style is only allowed in a formula");
    }
    struct hstex_noad noad = {
        .kind = (uint8_t)HSTEX_NOAD_STYLE,
        .atom_class = (uint8_t)style,
    };
    current_math_list(engine)->current_style = (uint8_t)style;
    return math_append(engine, &noad, error, error_capacity);
}

/* \mathchoice reads four sub-formulas -- so all four are executed -- and
   keeps the one the current style calls for, spliced into the list so that
   its atoms space against their neighbours; see docs/DECISIONS.md,
   math-choices. */
/* A MANDATORY left brace that the caller has not read yet: the four
   branches of a \mathchoice each want one, and the reference reads it the
   moment the branch before is done rather than waiting to see what turns up.
   A brace that is there is put back for the executor to open the branch
   with; one that is not is reported and put in. Spaces, \relax and an
   undefined name are stepped over, the same as for any mandatory brace. */
static int require_left_brace(struct hstex_engine *engine, char *error,
                              size_t error_capacity)
{
    static const char *const help[] = {
        "A left brace was mandatory here, so I've put one in.",
        "You might want to delete and/or insert some corrections",
        "so that I will find a matching right brace soon.",
        "(If you're confused by all this, try typing `I}' now.)", NULL};
    hstex_token token = 0U;
    struct hstex_source_location location;
    for (;;) {
        if (expanded_next_non_space_unrestricted(engine, &token, &location,
                                                 error, error_capacity) !=
            HSTEX_ENGINE_TOKEN) {
            return set_error(error, error_capacity,
                             "end of input where a { was expected");
        }
        if (hstex_token_is_control_sequence(token)) {
            const struct hstex_meaning *meaning = hstex_engine_meaning(
                engine, hstex_token_control_sequence_id(token));
            if (meaning->command == HSTEX_COMMAND_RELAX) {
                continue;
            }
            if (meaning->command == HSTEX_COMMAND_UNDEFINED) {
                record_executing_name(engine, token);
                report_undefined_control_sequence(engine);
                continue;
            }
        }
        break;
    }
    if (push_one(engine, token, location, error, error_capacity) != 0) {
        return -1;
    }
    if (token_is_effective_begin_group(engine, token)) {
        /* The reference reads this brace inside the scan; HSTeX hands it to
           the main loop so that one machinery opens every group, and marks
           it as one the main loop is not to draw. */
        engine->mandatory_brace = true;
        return 0;
    }
    tex_error(engine, help, "Missing { inserted");
    /* The brace is PUT IN rather than put back, so it does not undo a
       reading any count has already seen. */
    if (hstex_source_push_one(
            &engine->sources,
            hstex_token_character((uint8_t)HSTEX_CAT_BEGIN_GROUP, (uint8_t)'{'),
            location, error, error_capacity) != 0) {
        return -1;
    }
    engine->mandatory_brace = true;
    return 0;
}

static int execute_math_choice(struct hstex_engine *engine, char *error,
                               size_t error_capacity)
{
    struct hstex_math_builder *builder = current_math_list(engine);
    if (engine->mode != HSTEX_MODE_MATH || builder == NULL) {
        return set_error(error, error_capacity,
                         "\\mathchoice is only allowed in a formula");
    }
    if (builder->choice_remaining != 0U) {
        return set_error(error, error_capacity,
                         "one \\mathchoice followed another");
    }
    struct hstex_noad noad = {.kind = (uint8_t)HSTEX_NOAD_CHOICE};
    if (math_append(engine, &noad, error, error_capacity) != 0) {
        return -1;
    }
    builder->choice_remaining = 4U;
    builder->choice_index = 0U;
    builder->choice_noad = builder->count - 1U;
    return require_left_brace(engine, error, error_capacity);
}

/* \delimiter names a small and a large variant. Used on its own it is the
   small one, which is the top fifteen bits of the number; see
   docs/DECISIONS.md, delimiters. */
static int execute_delimiter(struct hstex_engine *engine, char *error,
                             size_t error_capacity)
{
    int32_t code = 0;
    if (scan_twenty_seven_bit_int(engine, &code, error, error_capacity) != 0) {
        return -1;
    }
    if (engine->mode != HSTEX_MODE_MATH) {
        return set_error(error, error_capacity,
                         "a delimiter is only allowed in a formula");
    }
    return math_append_code(engine, code / 4096, error, error_capacity);
}

static int execute_math_class(struct hstex_engine *engine, int32_t class_code,
                              char *error, size_t error_capacity)
{
    struct hstex_math_builder *builder = current_math_list(engine);
    if (engine->mode != HSTEX_MODE_MATH || builder == NULL) {
        return set_error(error, error_capacity,
                         "a math class is only allowed in a formula");
    }
    builder->forced_class = class_code;
    return 0;
}

static int execute_math_skip(struct hstex_engine *engine, bool kern,
                             char *error, size_t error_capacity)
{
    if (engine->mode != HSTEX_MODE_MATH) {
        return set_error(error, error_capacity,
                         "math glue is only allowed in a formula");
    }
    struct hstex_glue glue = {0};
    if (scan_math_glue(engine, &glue, error, error_capacity) != 0) {
        return -1;
    }
    struct hstex_noad noad = {0};
    if (kern) {
        noad.kind = (uint8_t)HSTEX_NOAD_MU_KERN;
        noad.kern = glue.width;
    } else {
        noad.kind = (uint8_t)HSTEX_NOAD_MU_GLUE;
        noad.glue = glue;
    }
    return math_append(engine, &noad, error, error_capacity);
}

/* ---------------------------------------------------------------------- */
/* Alignments.                                                            */
/*                                                                        */
/* \halign reads a preamble of column templates, then rows of entries.    */
/* Each entry is packaged at its natural width; once every row has been   */
/* read the columns are as wide as their widest entry, and the entries    */
/* are set again to that width. See docs/DECISIONS.md, alignments.        */
/* ---------------------------------------------------------------------- */

static void destroy_align_columns(struct hstex_align_column *columns,
                                  size_t count)
{
    for (size_t index = 0U; index < count; ++index) {
        free(columns[index].before);
        free(columns[index].after);
    }
    free(columns);
}

static void destroy_align_rows(struct hstex_align_row *rows, size_t count)
{
    for (size_t index = 0U; index < count; ++index) {
        free(rows[index].cells);
        free(rows[index].items);
        free(rows[index].migrated);
    }
    free(rows);
}

/* The preamble is read without expanding anything, the way the reference
   does, except that a \tabskip assignment is carried out where it stands and
   sets the glue for the boundary it appears at. */
static int scan_align_preamble(struct hstex_engine *engine,
                               struct hstex_align_column **out_columns,
                               size_t *out_count, size_t *out_loop,
                               char *error, size_t error_capacity)
{
    *out_loop = SIZE_MAX;
    struct hstex_align_column *columns = NULL;
    size_t count = 0U;
    size_t capacity = 0U;
    struct hstex_token_vector before = {0};
    struct hstex_token_vector after = {0};
    bool seen_marker = false;
    /* A tab or a \cr inside braces belongs to whatever the braces hold and
       does not end a column: trip line 332 writes a whole \halign inside a
       template. See tests/trip/probes/what-ends-a-preamble-column.tex. The
       count is kept where the reader can reach it, so that a brace the
       preamble read anywhere -- inside a conditional it skipped, inside a
       macro it expanded -- is counted; and it runs BELOW NOUGHT as readily
       as above it, which is what leaves a `\cr' standing in a template
       rather than dividing a column. */
    int depth = 0;
    int *previous_nesting = engine->preamble_nesting;
    engine->preamble_nesting = &depth;
    int status = 0;

    for (;;) {
        hstex_token token = 0U;
        struct hstex_source_location location;
        enum hstex_engine_result result =
            raw_next(engine, &token, &location, error, error_capacity);
        if (result != HSTEX_ENGINE_TOKEN) {
            status = set_error(error, error_capacity,
                               "input ended inside an alignment preamble");
            break;
        }
        /* A template starts where the last one ended, and the spaces that
           lay out the preamble across the page are no part of it: the
           reference passes over a space where a template would begin, at the
           opening brace and after every tab. A control space is a control
           sequence and is kept. See docs/DECISIONS.md,
           where-a-template-begins. */
        if (!seen_marker && before.count == 0U && token_is_space(token)) {
            continue;
        }
        if (hstex_token_is_control_sequence(token) &&
            token_is_outer_macro(engine, token)) {
            /* An \outer macro may not stand in a preamble either. The
               reference names the alignment, inserts the `\cr }' that would
               have closed it, and reads the macro again -- which is how
               trip line 363's runaway preamble is stopped at all. */
            static const char *const help[] = {
                "I suspect you have forgotten a `}', causing me",
                "to read past where you wanted me to stop.",
                "I'll try to recover; but if the error is serious,",
                "you'd better type `E' or `X' now and fix your file.", NULL};
            hstex_token close = hstex_token_character(
                (uint8_t)HSTEX_CAT_END_GROUP, (uint8_t)'}');
            hstex_token carriage = 0U;
            static const uint8_t cr_name[] = "cr";
            hstex_cs_id cr_id = 0U;
            if (hstex_symbol_intern(&engine->lexical_state.symbols,
                                    HSTEX_SYMBOL_REGULAR, cr_name,
                                    sizeof(cr_name) - 1U, &cr_id, error,
                                    error_capacity) != 0) {
                status = -1;
                break;
            }
            carriage = hstex_token_control_sequence(cr_id);
            /* Asked for from the pool, because the source layer gives an
               owned run back by its LENGTH alone: a bare malloc of two
               tokens is filed as the eight-token block that length rounds
               up to, and the next taker of an eight-token block writes off
               the end of it. */
            hstex_token *inserted = token_block_alloc(2U);
            if (inserted == NULL) {
                status = set_error(error, error_capacity,
                                   "preamble recovery allocation failed");
                break;
            }
            inserted[0] = carriage;
            inserted[1] = close;
            /* The two go in as ONE inserted list, which is how the context
               shows them: `<inserted text> \cr }'. */
            if (push_one(engine, token, location, error, error_capacity) != 0 ||
                hstex_source_push_owned_tokens(&engine->sources, inserted, 2U,
                                               location, error,
                                               error_capacity) != 0) {
                token_block_free(inserted, 2U);
                status = -1;
                break;
            }
            hstex_source_name_top(&engine->sources,
                                  (uint8_t)HSTEX_TOKEN_SOURCE_INSERTED, 0U);
            /* The braces that were left open are what the runaway ran
               through; the inserted \cr closes the column whatever depth
               they had reached. */
            depth = 0;
            char named[128];
            describe_token(engine, engine->executing_token, named,
                           sizeof(named));
            /* What had been read of the template it was met in is shown
               first, the way a runaway definition's body is. */
            report_runaway_list(engine, "preamble", NULL, NULL,
                                seen_marker ? &after : &before);
            tex_error(engine, help,
                      "Forbidden control sequence found while scanning "
                      "preamble of %s",
                      named);
            continue;
        }
        if (hstex_token_is_control_sequence(token)) {
            const struct hstex_meaning *meaning = hstex_engine_meaning(
                engine, hstex_token_control_sequence_id(token));
            if (meaning->command == HSTEX_COMMAND_GLUE_PARAMETER &&
                meaning->value.integer == (int32_t)HSTEX_GLUE_TAB_SKIP) {
                struct hstex_glue glue = {0};
                if (scan_optional_equals(engine, error, error_capacity) != 0 ||
                    scan_glue(engine, &glue, error, error_capacity) != 0 ||
                    assign_glue_parameter(engine,
                                          (uint32_t)HSTEX_GLUE_TAB_SKIP, glue,
                                          false, error, error_capacity) != 0) {
                    status = -1;
                    break;
                }
                continue;
            }
            if (meaning->command == HSTEX_COMMAND_SPAN) {
                /* \span in a preamble expands the token after it once, which
                   is how amsmath hands \halign a preamble it built as a
                   macro; see docs/DECISIONS.md, preamble-expansion. */
                hstex_token next = 0U;
                struct hstex_source_location where;
                if (raw_next(engine, &next, &where, error, error_capacity) !=
                    HSTEX_ENGINE_TOKEN) {
                    status = set_error(error, error_capacity,
                                       "input ended after \\span in a "
                                       "preamble");
                    break;
                }
                if (expand_token_once(engine, next, where, error,
                                      error_capacity) != 0) {
                    status = -1;
                    break;
                }
                continue;
            }
            if (meaning->command == HSTEX_COMMAND_CR && depth == 0) {
                /* A column with no # gets one at the end of what was read,
                   so the whole of it becomes the part before the entry and
                   the part after is empty. */
                if (!seen_marker) {
                    static const char *const help[] = {
                        "There should be exactly one # between &'s, when an",
                        "\\halign or \\valign is being set up. In this case you had",
                        "none, so I've put one in; maybe that will work.", NULL};
                    /* PUT BACK AND READ AGAIN: the reference backs the \cr
                       up before it complains, so the fault's context names
                       it, and the column then ends on the second reading
                       with nothing in its second half. */
                    if (push_one(engine, token, location, error,
                                 error_capacity) != 0) {
                        status = -1;
                        break;
                    }
                    tex_error(engine, help,
                              "Missing # inserted in alignment preamble");
                    seen_marker = true;
                    continue;
                }
                status = 0;
                goto finish_column;
            }
        }
        if (token_is_effective_category(engine, token,
                                        (uint8_t)HSTEX_CAT_PARAMETER)) {
            if (seen_marker) {
                /* The reference keeps the first and drops the rest, one
                   message per extra #. trip line 333 writes \d#\d, which
                   comes to ## once the glue scan on that line has expanded
                   it. */
                static const char *const help[] = {
                    "There should be exactly one # between &'s, when an",
                    "\\halign or \\valign is being set up. In this case you had",
                    "more than one, so I'm ignoring all but the first.", NULL};
                tex_error(engine, help, "Only one # is allowed per tab");
                continue;
            }
            seen_marker = true;
            continue;
        }
        if (depth == 0 &&
            token_is_effective_category(engine, token,
                                        (uint8_t)HSTEX_CAT_ALIGNMENT_TAB)) {
            /* A tab where a column would start marks the point the preamble
               repeats from -- that is what && means, and a preamble that
               begins with one repeats from its first column. */
            if (!seen_marker && before.count == 0U &&
                *out_loop == SIZE_MAX) {
                *out_loop = count;
                continue;
            }
            if (!seen_marker) {
                static const char *const help[] = {
                    "There should be exactly one # between &'s, when an",
                    "\\halign or \\valign is being set up. In this case you had",
                    "none, so I've put one in; maybe that will work.", NULL};
                /* Put back and read again, as above. */
                if (push_one(engine, token, location, error,
                             error_capacity) != 0) {
                    status = -1;
                    break;
                }
                tex_error(engine, help,
                          "Missing # inserted in alignment preamble");
                seen_marker = true;
                continue;
            }
            goto finish_column;
        }
        if (vector_push(seen_marker ? &after : &before, token, error,
                        error_capacity) != 0) {
            status = -1;
            break;
        }
        continue;

    finish_column:
        if (count == capacity) {
            size_t next = capacity == 0U ? 4U : capacity * 2U;
            if (next > SIZE_MAX / sizeof(*columns)) {
                status = set_error(error, error_capacity,
                                   "alignment column overflow");
                break;
            }
            void *allocation = realloc(columns, next * sizeof(*columns));
            if (allocation == NULL) {
                status = set_error(error, error_capacity,
                                   "alignment column allocation failed");
                break;
            }
            columns = allocation;
            capacity = next;
        }
        struct hstex_align_column *column = &columns[count++];
        memset(column, 0, sizeof(*column));
        column->before = before.data;
        column->before_count = before.count;
        column->after = after.data;
        column->after_count = after.count;
        column->tabskip = engine->glue_parameters[HSTEX_GLUE_TAB_SKIP];
        memset(&before, 0, sizeof(before));
        memset(&after, 0, sizeof(after));
        seen_marker = false;
        if (hstex_token_is_control_sequence(token)) {
            /* \cr ended the preamble. */
            engine->preamble_nesting = previous_nesting;
            *out_columns = columns;
            *out_count = count;
            return 0;
        }
    }
    engine->preamble_nesting = previous_nesting;
    vector_destroy(&before);
    vector_destroy(&after);
    destroy_align_columns(columns, count);
    return status == 0 ? -1 : status;
}

/* An alignment met inside an alignment entry is its own affair. The entry
   outside it is suspended for the whole of it, so that the inner
   preamble's and rows' braces are not counted as the outer entry's. */
static int execute_alignment_inner(struct hstex_engine *engine, bool vertical,
                                   char *error, size_t error_capacity);

static int execute_alignment(struct hstex_engine *engine, bool vertical,
                             char *error, size_t error_capacity)
{
    struct hstex_align_entry *outer = engine->alignment_entry;
    /* The line an alignment's rows are reported against is the line the
       alignment itself began on, so one alignment inside another's entry
       must give the outer one its line back. */
    int32_t outer_line = engine->alignment_line;
    /* And a mark of its own, so that its templates are told from the ones
       it is being read out of. */
    uint32_t outer_generation = engine->alignment_generation;
    engine->alignment_generation = ++engine->alignment_generations_made;
    engine->alignment_entry = NULL;
    int status = execute_alignment_inner(engine, vertical, error,
                                         error_capacity);
    engine->alignment_entry = outer;
    engine->alignment_line = outer_line;
    engine->alignment_generation = outer_generation;
    return status;
}

/* Repeat the preamble from its && point until the wanted column exists. */
static int extend_align_columns(struct hstex_align_column **columns,
                                size_t *count, size_t *capacity,
                                size_t loop_start, size_t preamble_count,
                                size_t wanted, char *error,
                                size_t error_capacity)
{
    if (wanted < *count) {
        return 0;
    }
    if (loop_start == SIZE_MAX || loop_start >= preamble_count) {
        /* There is no repeating part to draw another column from, so the
           row has asked for one that cannot exist. The caller reports it
           and ends the row. */
        return 1;
    }
    /* The period is the preamble's own repeating part, not what the
       columns have grown to. */
    size_t period = preamble_count - loop_start;
    while (wanted >= *count) {
        if (*count == *capacity) {
            size_t next = *capacity == 0U ? 4U : *capacity * 2U;
            if (next > SIZE_MAX / sizeof(**columns)) {
                return set_error(error, error_capacity,
                                 "alignment column overflow");
            }
            void *allocation = realloc(*columns, next * sizeof(**columns));
            if (allocation == NULL) {
                return set_error(error, error_capacity,
                                 "alignment column allocation failed");
            }
            *columns = allocation;
            *capacity = next;
        }
        const struct hstex_align_column *source =
            &(*columns)[loop_start + (*count - loop_start) % period];
        struct hstex_align_column copy = *source;
        copy.before = NULL;
        copy.after = NULL;
        copy.width = 0;
        if (source->before_count != 0U) {
            copy.before = malloc(source->before_count * sizeof(*copy.before));
            if (copy.before == NULL) {
                return set_error(error, error_capacity,
                                 "alignment column allocation failed");
            }
            memcpy(copy.before, source->before,
                   source->before_count * sizeof(*copy.before));
        }
        if (source->after_count != 0U) {
            copy.after = malloc(source->after_count * sizeof(*copy.after));
            if (copy.after == NULL) {
                free(copy.before);
                return set_error(error, error_capacity,
                                 "alignment column allocation failed");
            }
            memcpy(copy.after, source->after,
                   source->after_count * sizeof(*copy.after));
        }
        (*columns)[(*count)++] = copy;
    }
    return 0;
}

enum hstex_align_end {
    HSTEX_ALIGN_END_TAB = 0,
    HSTEX_ALIGN_END_SPAN,
    HSTEX_ALIGN_END_CR,
};

/* End the entry being read, from wherever the tab or \cr turned up. The v
   part goes in behind a boundary and is read where it stands, so a template
   that opened a box closes it before the entry is finished; see
   docs/DECISIONS.md, alignment-entries. */
static int end_alignment_entry(struct hstex_engine *engine,
                               enum hstex_align_end ending, char *error,
                               size_t error_capacity)
{
    struct hstex_align_entry *entry = engine->alignment_entry;
    if (entry == NULL) {
        return set_error(error, error_capacity,
                         "an alignment entry ended outside one");
    }
    if (entry->after_pushed) {
        return set_error(error, error_capacity,
                         "an alignment template ended the entry twice");
    }
    entry->ending = (uint8_t)ending;
    entry->after_pushed = true;
    struct hstex_source_location origin = {0};
    if (hstex_source_push_boundary(&engine->sources, error, error_capacity) !=
        0) {
        return -1;
    }
    /* THE TEMPLATE ENDS WITH A TOKEN OF ITS OWN, part of the same list as
       the rest of it: the reference's context writes it -- `<template>
       \endtemplate' for a column with nothing else in its second half --
       and a macro called at the end of an entry can take it as an argument.
       trip line 422 hands one to \trap that way. */
    hstex_token ending_token = 0U;
    if (end_template_token(engine, &ending_token, error, error_capacity) != 0) {
        return -1;
    }
    const hstex_token *after = NULL;
    size_t after_count = 0U;
    if (!entry->omit && entry->column < entry->column_count) {
        after = entry->columns[entry->column].after;
        after_count = entry->columns[entry->column].after_count;
    }
    hstex_token *whole = token_block_alloc(after_count + 1U);
    if (whole == NULL) {
        return set_error(error, error_capacity,
                         "alignment template allocation failed");
    }
    if (after_count != 0U) {
        memcpy(whole, after, after_count * sizeof(*whole));
    }
    whole[after_count] = ending_token;
    if (hstex_source_push_owned_tokens(&engine->sources, whole,
                                       after_count + 1U, origin, error,
                                       error_capacity) != 0) {
        return -1;
    }
    hstex_source_name_top(&engine->sources,
                          (uint8_t)HSTEX_TOKEN_SOURCE_TEMPLATE_AFTER,
                          engine->alignment_generation);
    return 0;
}

/* What an alignment entry makes of a token as it is read, before whoever
   asked for it sees it. Returns 1 when the token ended the entry, so that
   the template's text after it is what the caller gets. */
static int note_alignment_token(struct hstex_engine *engine, hstex_token token,
                                bool from_template, bool from_pushback,
                                char *error, size_t error_capacity)
{
    engine->alignment_token_from_template = from_template;
    /* A preamble counts every brace it reads, wherever it was read from. */
    if (engine->preamble_nesting != NULL) {
        if (token_is_effective_category(engine, token,
                                        (uint8_t)HSTEX_CAT_BEGIN_GROUP)) {
            ++*engine->preamble_nesting;
        } else if (token_is_effective_category(engine, token,
                                               (uint8_t)HSTEX_CAT_END_GROUP)) {
            --*engine->preamble_nesting;
        }
    }
    struct hstex_align_entry *entry = engine->alignment_entry;
    if (entry == NULL || entry->after_pushed) {
        return 0;
    }
    /* A brace of the template's own is not one of the entry's: measured,
       `\halign{\l{#}\cr A\cr}' is an ordinary alignment, though the u part
       leaves a brace open across the whole entry. */
    if (from_template) {
        return 0;
    }
    if (token_is_category(token, HSTEX_CAT_BEGIN_GROUP) ||
        token_is_category(token, HSTEX_CAT_END_GROUP)) {
        /* Counted once, at its first reading. A brace that several scanners
           look at in turn is put back between them and read again -- \hbox
           reads its `{' three times over, once for each thing the token
           might have been -- and only the first of those is the entry's. */
        (void)from_pushback;
        /* The count runs below nought as readily as above it. A cell may
           close a brace it did not open -- the opening one having been
           swallowed by whatever put the cell's text together -- and holding
           the count at nought there loses the closing, so the next `{'
           leaves it looking one deep for good. */
        if (token_is_category(token, HSTEX_CAT_BEGIN_GROUP)) {
            ++entry->nesting;
        } else {
            --entry->nesting;
        }
        return 0;
    }
    enum hstex_align_end ending;
    if (token_is_category(token, HSTEX_CAT_ALIGNMENT_TAB)) {
        ending = HSTEX_ALIGN_END_TAB;
    } else if (hstex_token_is_control_sequence(token)) {
        const struct hstex_meaning *meaning = hstex_engine_meaning(
            engine, hstex_token_control_sequence_id(token));
        if (meaning->command == HSTEX_COMMAND_CR) {
            ending = HSTEX_ALIGN_END_CR;
        } else if (meaning->command == HSTEX_COMMAND_SPAN) {
            ending = HSTEX_ALIGN_END_SPAN;
        } else {
            return 0;
        }
    } else {
        return 0;
    }
    if (entry->nesting > 0) {
        /* NOT YET: the reference puts in the } the column wants and reads
           the tab again -- "Missing } inserted". The count is right for the
           corpus but for the amsmath align family, which still ends a cell
           holding a brace it never opened. See
           tests/trip/probes/a-brace-in-an-alignment-template.tex. */
        return 0;
    }
    if (entry->nesting < 0) {
        /* The entry has closed a brace it never opened, so it is not whole
           and this tab does not end it: the reference puts the opening brace
           in and reads the tab again. THE TAB IS A COMMAND HERE, not a token
           the entry swallows -- the reference lets it through to be obeyed,
           so \tracingcommands draws it before the fault. */
        trace_command(engine, token);
        struct hstex_source_location where = {0};
        if (insert_missing_brace_for_align(engine, token, where, true, error,
                                           error_capacity) != 0) {
            return -1;
        }
        return 1;
    }
    if (end_alignment_entry(engine, ending, error, error_capacity) != 0) {
        return -1;
    }
    return 1;
}


/* Run one entry. The templates around it are pushed as token lists, so the
   entry sees exactly what the reference's u and v parts give it. \span
   carries on into the next column with the same box. */
static int evaluate_align_cell(struct hstex_engine *engine, bool vertical,
                               const struct hstex_align_column *columns,
                               size_t column_count, size_t first_column,
                               bool omit, struct hstex_hbox_builder *builder,
                               struct hstex_vbox_builder *vertical_builder,
                               enum hstex_align_end *ending, uint32_t *span,
                               char *error, size_t error_capacity)
{
    uint32_t base_group_level = engine->group_level;
    uint32_t previous_group_floor = engine->output_group_floor;
    size_t previous_conditional_floor = engine->output_conditional_floor;
    struct hstex_hbox_builder *previous_builder = engine->active_hbox_builder;
    enum hstex_mode previous_mode = engine->mode;
    bool previous_inner_mode = engine->inner_mode;
    uint32_t previous_stop_level = engine->group_stop_level;
    bool previous_stop_armed = engine->group_stop_armed;
    bool previous_stop_hit = engine->group_stop_hit;
    size_t previous_math_depth = engine->math_depth;
    size_t previous_math_floor = engine->math_floor;
    bool previous_displayed = engine->displayed_math;
    /* A body is not part of whatever paragraph encloses it; it gets a list
       of its own if it starts one. */
    bool previous_building_paragraph = engine->building_paragraph;
    struct hstex_hbox_builder *previous_paragraph = engine->paragraph_builder;
    int32_t previous_space_factor = engine->space_factor;
    bool previous_has_pending = engine->has_pending_character;
    bool previous_building = engine->building_alignment;
    struct hstex_vbox_builder *previous_vbox_builder =
        engine->active_vbox_builder;
    int32_t previous_depth = engine->prev_depth;
    int32_t previous_graf = engine->prev_graf;

    /* THE ENTRY'S OWN GROUP. A `}' that would close this one closes nothing
       a document opened, so the reference guesses a \cr instead. */
    if (begin_group(engine, HSTEX_GROUP_ALIGN, error, error_capacity) != 0) {
        return -1;
    }
    engine->output_group_floor = engine->group_level;
    engine->output_conditional_floor = engine->conditional_count;
    engine->group_stop_armed = false;
    engine->group_stop_hit = false;
    engine->math_floor = engine->math_depth;
    engine->displayed_math = false;
    engine->building_paragraph = false;
    engine->paragraph_builder = NULL;
    engine->building_alignment = true;
    if (nest_push(engine, error, error_capacity) != 0) {
        return -1;
    }
    if (vertical) {
        /* An entry of a \\valign is a vertical list of its own, the way a
           \\vbox body is: it starts its own paragraphs and its own
           \\prevdepth. */
        engine->active_hbox_builder = NULL;
        engine->active_vbox_builder = vertical_builder;
        engine->mode = HSTEX_MODE_VERTICAL;
        engine->inner_mode = true;
        engine->prev_depth = HSTEX_IGNORE_DEPTH;
        if (normal_paragraph(engine, error, error_capacity) != 0) {
            return -1;
        }
    } else {
        engine->active_hbox_builder = builder;
        engine->mode = HSTEX_MODE_HORIZONTAL;
        engine->inner_mode = true;
        engine->space_factor = 1000;
        engine->has_pending_character = false;
    }

    size_t column = first_column;
    *span = 1U;
    *ending = HSTEX_ALIGN_END_CR;
    int status = 0;
    bool finished = false;
    bool segment_omit = omit;
    struct hstex_source_location origin = {0};
    struct hstex_align_entry entry = {
        .columns = columns,
        .column_count = column_count,
        .column = first_column,
        .omit = omit,
    };
    struct hstex_align_entry *previous_entry = engine->alignment_entry;
    engine->alignment_entry = &entry;
    if (!omit && column < column_count && columns[column].before_count != 0U) {
        if (hstex_source_push_tokens(&engine->sources, columns[column].before,
                                     columns[column].before_count, origin,
                                     error, error_capacity) != 0) {
            status = -1;
        } else {
            hstex_source_name_top(&engine->sources,
                                  (uint8_t)HSTEX_TOKEN_SOURCE_TEMPLATE,
                              engine->alignment_generation);
        }
    }
    while (status == 0 && !finished) {
        hstex_token token = 0U;
        struct hstex_source_location location;
        enum hstex_engine_result result = hstex_engine_next_output(
            engine, &token, &location, error, error_capacity);
        if (result == HSTEX_ENGINE_ERROR) {
            status = -1;
            break;
        }
        if (result == HSTEX_ENGINE_EOF) {
            if (!entry.after_pushed) {
                status = set_error(error, error_capacity,
                                   "input ended inside an alignment entry");
                break;
            }
            /* The v part is exhausted: the entry, or this span of it, ends.
               The reference reads a frozen \endtemplate HERE, behind the v
               part rather than in front of it, and traces it as a command of
               its own -- so `#\span\A Y' draws {the letter X}, {the letter
               Y} and only then {end of alignment template}. */
            if (engine->integer_parameters[HSTEX_INTEGER_TRACING_COMMANDS] >
                0) {
                trace_words(engine, "end of alignment template");
            }
            /* A vertical entry that was still filling a paragraph ends it
               HERE, at the boundary the template ran out on, rather than
               when the whole entry is done: a \span carries on into the
               next column with the paragraph already broken and the mode
               back to internal vertical, so the endv that follows draws
               its mode. trip line 337 spans this way twice. */
            if (vertical && engine->building_paragraph) {
                status = finish_paragraph(engine, error, error_capacity);
                if (status != 0) {
                    break;
                }
            }
            /* The spent half of the template stays standing: the reference
               has no boundary there, and a fault drawn as soon as the entry
               is done with names the template it came out of. See
               docs/DECISIONS.md, where-an-extra-tab-is-found. */
            if (hstex_source_pop_boundary_keeping_template(
                    &engine->sources, error, error_capacity) != 0) {
                status = -1;
                break;
            }
            entry.after_pushed = false;
            *ending = (enum hstex_align_end)entry.ending;
            if (*ending != HSTEX_ALIGN_END_SPAN) {
                finished = true;
                break;
            }
            ++column;
            ++*span;
            entry.column = column;
            entry.ending = (uint8_t)HSTEX_ALIGN_END_CR;
            /* \omit may follow \span, and drops the next column's
               templates just as it does at the start of an entry. */
            segment_omit = false;
            entry.omit = false;
            hstex_token next = 0U;
            struct hstex_source_location where;
            enum hstex_engine_result got =
                align_peek_token(engine, &next, &where, error, error_capacity);
            if (got == HSTEX_ENGINE_ERROR) {
                status = -1;
                break;
            }
            if (got == HSTEX_ENGINE_TOKEN) {
                if (hstex_token_is_control_sequence(next) &&
                    hstex_engine_meaning(
                        engine, hstex_token_control_sequence_id(next))
                            ->command == HSTEX_COMMAND_OMIT) {
                    segment_omit = true;
                    entry.omit = true;
                } else if (push_one(engine, next, where, error,
                                    error_capacity) != 0) {
                    status = -1;
                    break;
                }
            }
            if (!segment_omit && column < column_count &&
                columns[column].before_count != 0U) {
                if (hstex_source_push_tokens(&engine->sources,
                                             columns[column].before,
                                             columns[column].before_count,
                                             origin, error,
                                             error_capacity) != 0) {
                    status = -1;
                } else {
                    hstex_source_name_top(
                        &engine->sources,
                        (uint8_t)HSTEX_TOKEN_SOURCE_TEMPLATE,
                        engine->alignment_generation);
                }
            }
            continue;
        }
        if (vertical) {
            status = handle_vertical_list_token(engine, token, location, error,
                                                error_capacity);
            continue;
        }
        if (token_is_space(token)) {
            status = flush_pending_character(engine, error, error_capacity);
            if (status == 0) {
                status = append_interword_glue(engine, error, error_capacity);
            }
            continue;
        }
        if (!hstex_token_is_character(token)) {
            char found_name[128];
            describe_token(engine, token, found_name, sizeof(found_name));
            status = set_error(error, error_capacity,
                               "%s is not supported inside an alignment entry",
                               found_name);
            break;
        }
        status = append_horizontal_character(
            engine, hstex_token_character_code(token), error, error_capacity);
    }
    /* A vertical entry ends any paragraph it was still filling, the way an
       implied \\par would. */
    if (status == 0 && vertical && engine->building_paragraph) {
        status = finish_paragraph(engine, error, error_capacity);
    }
    if (status == 0 && !vertical) {
        status = flush_pending_character(engine, error, error_capacity);
    }
    nest_pop(engine);
    engine->space_factor = previous_space_factor;
    engine->has_pending_character = previous_has_pending;
    engine->active_vbox_builder = previous_vbox_builder;
    engine->prev_depth = previous_depth;
    engine->prev_graf = previous_graf;
    engine->active_hbox_builder = previous_builder;
    engine->mode = previous_mode;
    engine->inner_mode = previous_inner_mode;
    engine->output_group_floor = previous_group_floor;
    engine->output_conditional_floor = previous_conditional_floor;
    engine->group_stop_level = previous_stop_level;
    engine->group_stop_armed = previous_stop_armed;
    engine->group_stop_hit = previous_stop_hit;
    engine->building_alignment = previous_building;
    engine->alignment_entry = previous_entry;
    while (engine->math_depth > previous_math_depth) {
        pop_math_list(engine);
    }
    engine->math_depth = previous_math_depth;
    engine->math_floor = previous_math_floor;
    engine->displayed_math = previous_displayed;
    if (engine->paragraph_builder != NULL &&
        engine->paragraph_builder != previous_paragraph) {
        free(engine->paragraph_builder->node_identifiers);
        free(engine->paragraph_builder);
    }
    engine->paragraph_builder = previous_paragraph;
    engine->building_paragraph = previous_building_paragraph;
    while (engine->group_level > base_group_level) {
        if (end_group(engine, error, error_capacity) < 0) {
            status = -1;
            break;
        }
    }
    return status;
}

/* The columns are as wide as their widest single entry; an entry that spans
   several columns widens the last one it covers when it does not fit. Then
   every row becomes an hbox of tabskip, entry, tabskip, ... set to the width
   the whole alignment came to. */
static int finish_alignment(struct hstex_engine *engine, bool vertical,
                            struct hstex_align_column *columns,
                            size_t column_count, struct hstex_glue leading,
                            const struct hstex_align_row *rows,
                            size_t row_count, bool matched_to,
                            bool matched_spread, int32_t requested_width,
                            int32_t shift, bool display, char *error,
                            size_t error_capacity)
{
    /* A column of the preamble that no row ever reached is not part of the
       alignment: it settles nothing and its \tabskip is not counted in the
       width. See docs/DECISIONS.md, a-row-that-stops-early. */
    size_t reached = 0U;
    for (size_t index = 0U; index < row_count; ++index) {
        if (rows[index].noalign) {
            continue;
        }
        size_t used = 0U;
        for (size_t cell = 0U; cell < rows[index].cell_count; ++cell) {
            used += rows[index].cells[cell].span;
        }
        if (used > reached) {
            reached = used;
        }
    }
    /* The preamble keeps every column it declared, however few a row
       reached: the ones past the last one used stand in the row the
       preamble is packed as, with no width and NO TABSKIP AFTER THEM. Only
       the display needs them, so the count the rows are built from is still
       the one that was reached. */
    size_t preamble_columns = column_count;
    if (reached < column_count) {
        column_count = reached;
    }
    for (size_t index = 0U; index < column_count; ++index) {
        columns[index].width = 0;
        columns[index].measured = false;
        columns[index].started = false;
    }
    /* NOTHING STANDS IN FRONT OF A COLUMN NO ROW BEGINS IN. A column that
       every row only spans INTO is never the start of an entry, and the
       reference puts no \tabskip before it -- so the column keeps the whole
       of what the entry spanning into it came to, rather than the entry's
       extent less the glue.

       Measured, over `\valign to -5pt' and over \halign alike, with three
       columns and every row written `A\span&C': the glue in front of column
       one is 0.0 and the glue in front of column two, which the rows do
       begin in, is the \tabskip in full. And with one row that spans and
       one that does not, every column is begun in somewhere and every glue
       is drawn in full. See
       tests/trip/probes/what-a-valign-puts-between-the-columns-one-entry-spans.tex.

       It has to be settled here, in the column's own record, rather than
       where the glue is drawn: the measuring loop below counts what a span
       already covers as the columns it covers plus the glue between them,
       and the row the preamble is packed as draws the same glue again. One
       rule in the record gives all three. */
    for (size_t index = 0U; index < row_count; ++index) {
        if (rows[index].noalign) {
            continue;
        }
        size_t column = 0U;
        for (size_t cell = 0U; cell < rows[index].cell_count; ++cell) {
            if (column >= column_count) {
                break;
            }
            columns[column].started = true;
            column += rows[index].cells[cell].span;
        }
    }
    for (size_t index = 1U; index < column_count; ++index) {
        if (!columns[index].started) {
            struct hstex_glue none = {0};
            columns[index - 1U].tabskip = none;
        }
    }
    /* Short spans first, so that a wide one only has to make up what the
       columns it covers still lack. */
    for (size_t pass = 1U; pass <= column_count; ++pass) {
        for (size_t index = 0U; index < row_count; ++index) {
            if (rows[index].noalign) {
                continue;
            }
            size_t column = 0U;
            for (size_t cell = 0U; cell < rows[index].cell_count; ++cell) {
                const struct hstex_align_cell *entry = &rows[index].cells[cell];
                if (entry->span == pass &&
                    column + entry->span <= column_count) {
                    int64_t covered = 0;
                    for (size_t step = 0U; step < entry->span; ++step) {
                        covered += columns[column + step].width;
                        if (step + 1U < entry->span) {
                            covered += columns[column + step].tabskip.width;
                        }
                    }
                    struct hstex_align_column *last =
                        &columns[column + entry->span - 1U];
                    if (!last->measured || (int64_t)entry->width > covered) {
                        last->width +=
                            (int32_t)((int64_t)entry->width - covered);
                        last->measured = true;
                    }
                }
                column += entry->span;
            }
        }
    }

    int64_t natural = leading.width;
    for (size_t index = 0U; index < column_count; ++index) {
        natural += columns[index].width;
        natural += columns[index].tabskip.width;
    }
    int64_t final_width = natural;
    if (matched_to) {
        final_width = requested_width;
    } else if (matched_spread) {
        final_width = natural + requested_width;
    }
    if (final_width < -INT64_C(1073741823) ||
        final_width > INT64_C(1073741823)) {
        return set_error(error, error_capacity,
                         "alignment width exceeds TeX's dimension range");
    }
    /* THE ROWS ARE SET, NOT PACKED: what the reference packs is the
       preamble, and every row takes the glue setting that packing came to
       rather than one worked out from what the row itself holds. See
       docs/DECISIONS.md, what-a-row-is-set-with. */
    struct hstex_glue preamble = leading;
    for (size_t index = 0U; index < column_count; ++index) {
        struct hstex_glue skip = columns[index].tabskip;
        preamble.stretch += skip.stretch;
        preamble.shrink += skip.shrink;
        if (skip.stretch_order > preamble.stretch_order) {
            preamble.stretch_order = skip.stretch_order;
            preamble.stretch = skip.stretch;
        }
        if (skip.shrink_order > preamble.shrink_order) {
            preamble.shrink_order = skip.shrink_order;
            preamble.shrink = skip.shrink;
        }
    }
    struct hstex_glue_set prototype =
        packing_glue_set(natural, (int32_t)final_width, &preamble);
    /* The reference packs the preamble once, to settle the tabskip glue,
       and that is the one packing of an alignment it reports -- against the
       line the alignment began on. Its rows and entries it sets rather than
       packs, and says nothing of them. See docs/DECISIONS.md,
       boxes-that-do-not-fit. */
    if (matched_to || matched_spread) {
        struct hstex_box whole = {0};
        /* The row of a \valign runs downwards, so what the alignment was set
           to is its HEIGHT: measuring it as a width would report every row
           against nothing at all. */
        if (vertical) {
            whole.height = (int32_t)final_width;
        } else {
            whole.width = (int32_t)final_width;
        }
        whole.glue = prototype;
        engine->badness =
            packing_badness(natural, (int32_t)final_width, &preamble);
        /* The row is a \tabskip and a column, over and over, and one last
           \tabskip: the columns stand in it as UNSET BOXES, since what they
           are set to is settled a row at a time and not here. That list is
           what the reference shows when it reports this packing, so it has
           to exist even though nothing else ever looks at it. */
        uint32_t *row =
            preamble_columns == 0U
                ? NULL
                : calloc(2U * preamble_columns + 1U, sizeof(*row));
        size_t row_length = 0U;
        if (row != NULL) {
            for (size_t index = 0U; index <= preamble_columns; ++index) {
                struct hstex_glue skip = {0};
                if (index == 0U) {
                    skip = leading;
                } else if (index <= column_count) {
                    skip = columns[index - 1U].tabskip;
                }
                struct hstex_node glue_node = {
                    .kind = HSTEX_NODE_GLUE,
                    .width = skip.width,
                    .value.glue = {
                        .stretch = skip.stretch,
                        .shrink = skip.shrink,
                        .stretch_order = skip.stretch_order,
                        .shrink_order = skip.shrink_order,
                        .parameter = (uint8_t)(HSTEX_GLUE_TAB_SKIP + 1),
                    },
                };
                if (store_node(engine, &glue_node, &row[row_length], error,
                               error_capacity) != 0) {
                    free(row);
                    return -1;
                }
                ++row_length;
                if (index == preamble_columns) {
                    break;
                }
                int32_t extent =
                    index < column_count ? columns[index].width : 0;
                struct hstex_node column_node = {.kind = HSTEX_NODE_UNSET};
                if (vertical) {
                    column_node.height = extent;
                } else {
                    column_node.width = extent;
                }
                if (store_node(engine, &column_node, &row[row_length], error,
                               error_capacity) != 0) {
                    free(row);
                    return -1;
                }
                ++row_length;
            }
        }
        int32_t previous_pack = engine->pack_begin_line;
        engine->pack_begin_line = -engine->alignment_line;
        bool previous_quiet = engine->packing_quietly;
        engine->packing_quietly = false;
        /* A \valign's columns are vertical lists, so the row the preamble
           makes is a \vbox and the reference names it one: "Underfull
           \vbox ... in alignment". */
        report_packing(engine, &whole, natural, &preamble, vertical, row,
                       row_length);
        engine->packing_quietly = previous_quiet;
        engine->pack_begin_line = previous_pack;
        free(row);
    }

    for (size_t index = 0U; index < row_count; ++index) {
        if (rows[index].noalign) {
            for (size_t item = 0U; item < rows[index].item_count; ++item) {
                /* A rule \noalign left in the alignment's own list takes
                   whatever it does not settle for itself FROM THE BOX THE
                   PREAMBLE IS PACKED AS -- as wide as a \halign, as tall as
                   a \valign, and no deeper than either. See
                   docs/DECISIONS.md, a-rule-between-rows. */
                uint32_t held = rows[index].items[item];
                if (held != 0U && (size_t)held <= engine->node_count &&
                    engine->nodes[held - 1U].kind == HSTEX_NODE_RULE) {
                    struct hstex_node *shaped = &engine->nodes[held - 1U];
                    if (shaped->width == HSTEX_RUNNING_DIMEN) {
                        shaped->width = vertical ? 0 : (int32_t)final_width;
                    }
                    if (shaped->height == HSTEX_RUNNING_DIMEN) {
                        shaped->height = vertical ? (int32_t)final_width : 0;
                    }
                    if (shaped->depth == HSTEX_RUNNING_DIMEN) {
                        shaped->depth = 0;
                    }
                }
                if (vertical) {
                    /* Between the columns of a \\valign, \\noalign leaves
                       horizontal material. */
                    uint32_t held_item = rows[index].items[item];
                    if (held_item != 0U &&
                        (size_t)held_item <= engine->node_count &&
                        append_hbox_node(engine,
                                         &engine->nodes[held_item - 1U], error,
                                         error_capacity) != 0) {
                        return -1;
                    }
                    continue;
                }
                if (append_vbox_item(engine, rows[index].items[item], error,
                                     error_capacity) != 0) {
                    return -1;
                }
            }
            /* \prevdepth is what the \noalign left it at, which may be an
               assignment of its own; see docs/DECISIONS.md,
               prevdepth-inside-noalign. */
            engine->prev_depth = rows[index].prev_depth;
            continue;
        }
        struct hstex_hbox_builder line = {0};
        struct hstex_vbox_builder stack = {0};
        struct hstex_hbox_builder *previous = engine->active_hbox_builder;
        struct hstex_vbox_builder *previous_stack = engine->active_vbox_builder;
        enum hstex_mode previous_mode = engine->mode;
        int32_t previous_depth = engine->prev_depth;
        if (vertical) {
            engine->active_hbox_builder = NULL;
            engine->active_vbox_builder = &stack;
            engine->mode = HSTEX_MODE_VERTICAL;
            engine->prev_depth = HSTEX_IGNORE_DEPTH;
        } else {
            engine->active_hbox_builder = &line;
            engine->mode = HSTEX_MODE_HORIZONTAL;
        }
        int status = 0;
        struct hstex_glue skip = leading;
        size_t column = 0U;
        for (size_t cell = 0U; status == 0 && cell < rows[index].cell_count;
             ++cell) {
            status = vertical
                         ? emit_parameter_glue_vertically(
                               engine, skip, HSTEX_GLUE_TAB_SKIP, error,
                               error_capacity)
                         : emit_parameter_glue(engine, skip,
                                               HSTEX_GLUE_TAB_SKIP, error,
                                               error_capacity);
            if (status != 0) {
                break;
            }
            const struct hstex_align_cell *entry = &rows[index].cells[cell];
            if (entry->box == 0U || entry->box > engine->node_count) {
                status = set_error(error, error_capacity,
                                   "an alignment entry lost its box");
                break;
            }
            struct hstex_node set = engine->nodes[entry->box - 1U];
            /* AN ENTRY THAT SPANS SEVERAL COLUMNS IS SET TO THE FIRST OF
               THEM, and the columns behind it are filled in with their own
               \tabskip and an EMPTY box of each one's width. See
               docs/DECISIONS.md, what-an-entry-that-spans-is-set-to. */
            int64_t width = column < column_count ? columns[column].width : 0;
            /* AN ENTRY THAT SPANS IS SET TO FILL ALL THE COLUMNS IT COVERS
               even though the box it becomes is only as wide as the first of
               them: what it is measured against is those columns and the
               \tabskip between them AS THE ROW'S OWN GLUE SETTING LEAVES
               THEM. */
            int64_t reach = width;
            for (size_t step = 1U; step < entry->span; ++step) {
                size_t at = column + step;
                reach += tabskip_set_width(at - 1U < column_count
                                               ? columns[at - 1U].tabskip
                                               : leading,
                                           prototype);
                reach += at < column_count ? columns[at].width : 0;
            }
            /* The entry is set to the column's width, so its glue takes up
               whatever the column is wider by; see docs/DECISIONS.md,
               the-entries-of-a-row. */
            if ((size_t)set.value.list.node_start + set.value.list.node_count <=
                engine->list_item_count) {
                struct hstex_glue spare = list_total_glue(
                    engine, engine->list_items + set.value.list.node_start,
                    set.value.list.node_count);
                set.value.list.glue =
                    packing_glue_set(entry->width, (int32_t)reach, &spare);
            }
            if (vertical) {
                /* The entry is set to the height its row came to, and is as
                   wide as the column it stands in. A column is not a stack
                   of baselines -- the \\tabskip between the rows is all the
                   spacing there is -- so no interline glue comes with it. */
                set.height = (int32_t)width;
                set.depth = 0;
                engine->prev_depth = HSTEX_IGNORE_DEPTH;
                status = append_vbox_node(engine, &set, error, error_capacity);
            } else {
                set.width = (int32_t)width;
                status = append_hbox_node(engine, &set, error, error_capacity);
            }
            for (size_t step = 1U; status == 0 && step < entry->span; ++step) {
                size_t at = column + step;
                struct hstex_glue between =
                    at - 1U < column_count ? columns[at - 1U].tabskip : leading;
                int32_t extent = at < column_count ? columns[at].width : 0;
                struct hstex_node pad = {
                    .kind = HSTEX_NODE_LIST,
                    .value.list = {.box_kind = vertical ? HSTEX_BOX_VLIST
                                                        : HSTEX_BOX_HLIST,
                                   .spanned_over = true},
                };
                if (vertical) {
                    pad.height = extent;
                    status = emit_parameter_glue_vertically(
                        engine, between, HSTEX_GLUE_TAB_SKIP, error,
                        error_capacity);
                    if (status == 0) {
                        engine->prev_depth = HSTEX_IGNORE_DEPTH;
                        status = append_vbox_node(engine, &pad, error,
                                                  error_capacity);
                    }
                } else {
                    pad.width = extent;
                    status = emit_parameter_glue(engine, between,
                                                 HSTEX_GLUE_TAB_SKIP, error,
                                                 error_capacity);
                    if (status == 0) {
                        status = append_hbox_node(engine, &pad, error,
                                                  error_capacity);
                    }
                }
            }
            size_t last = column + entry->span - 1U;
            skip = last < column_count ? columns[last].tabskip : leading;
            column += entry->span;
        }
        /* The row ends with the glue that follows its own last column, and
           nothing of the columns it never reached; see docs/DECISIONS.md,
           a-row-that-stops-early. */
        if (status == 0) {
            status = vertical
                         ? emit_parameter_glue_vertically(
                               engine, skip, HSTEX_GLUE_TAB_SKIP, error,
                               error_capacity)
                         : emit_parameter_glue(engine, skip,
                                               HSTEX_GLUE_TAB_SKIP, error,
                                               error_capacity);
        }
        struct hstex_box packed = {0};
        if (status == 0) {
            /* The reference sets the glue of an alignment's boxes itself
               rather than packing them, so nothing is reported of them. */
            bool previous_quiet = engine->packing_quietly;
            engine->packing_quietly = true;
            status = vertical
                         ? finalize_vbox(engine, &stack, true, false,
                                         (int32_t)final_width, &packed, error,
                                         error_capacity)
                         : finalize_hbox(engine, &line, true, false,
                                         (int32_t)final_width, &packed, error,
                                         error_capacity);
            engine->packing_quietly = previous_quiet;
        }
        free(line.node_identifiers);
        free(stack.node_identifiers);
        engine->active_hbox_builder = previous;
        engine->active_vbox_builder = previous_stack;
        engine->mode = previous_mode;
        engine->prev_depth = previous_depth;
        if (status != 0) {
            return -1;
        }
        /* And the row is SET rather than packed: it takes the glue setting
           the preamble's packing came to. */
        packed.glue = prototype;
        /* Every entry of a row is as tall and as deep as the row itself; see
           docs/DECISIONS.md, the-entries-of-a-row. */
        for (size_t item = 0U;
             item < packed.node_count &&
             (size_t)packed.node_start + packed.node_count <=
                 engine->list_item_count;
             ++item) {
            uint32_t identifier = engine->list_items[packed.node_start + item];
            if (identifier == 0U || (size_t)identifier > engine->node_count) {
                continue;
            }
            struct hstex_node *entry = &engine->nodes[identifier - 1U];
            if (entry->kind != HSTEX_NODE_LIST ||
                entry->value.list.spanned_over) {
                continue;
            }
            if (vertical) {
                entry->width = packed.width;
            } else {
                entry->height = packed.height;
                entry->depth = packed.depth;
            }
        }
        if (vertical) {
            /* The columns go side by side into the list the alignment
               joined, with nothing between them: a \\valign's \\tabskip is
               inside each column rather than between them. */
            struct hstex_node node = {
                .kind = HSTEX_NODE_LIST,
                .width = packed.width,
                .height = packed.height,
                .depth = packed.depth,
                .value.list = {
                    .node_start = packed.node_start,
                    .node_count = packed.node_count,
                    .box_kind = packed.kind,
                    .glue = packed.glue,
                },
            };
            if (append_hbox_node(engine, &node, error, error_capacity) != 0) {
                return -1;
            }
            continue;
        }
        if (append_shifted_box_node(engine, &packed, shift, error,
                                    error_capacity) != 0) {
            return -1;
        }
        /* And what moved out of the row's entries stands behind the row. */
        for (size_t item = 0U; item < rows[index].migrated_count; ++item) {
            if (append_vbox_item(engine, rows[index].migrated[item], error,
                                 error_capacity) != 0) {
                return -1;
            }
        }
        /* A row of a displayed alignment is a display line, and says so; see
           docs/DECISIONS.md, display-alignments. */
        struct hstex_vbox_builder *list = engine->active_vbox_builder;
        if (display && list != NULL && list->count != 0U) {
            uint32_t row_node = list->node_identifiers[list->count - 1U];
            if (row_node != 0U && (size_t)row_node <= engine->node_count) {
                engine->nodes[row_node - 1U].value.list.display = true;
            }
        }
    }
    return 0;
}

/* \everycr is read once the preamble has been scanned and again after every
   \cr that ends a row; a redundant \crcr does not fire it. See
   docs/DECISIONS.md, everycr. */
static int insert_every_cr(struct hstex_engine *engine, char *error,
                           size_t error_capacity)
{
    uint32_t every = engine->token_parameters[HSTEX_TOKEN_EVERY_CR];
    if (every == 0U) {
        return 0;
    }
    const struct hstex_token_list *list = token_list_by_identifier(engine, every);
    struct hstex_source_location location = {0};
    if (list == NULL ||
        hstex_source_push_tokens(&engine->sources, list->tokens, list->count,
                                 location, error, error_capacity) != 0) {
        return set_error(error, error_capacity,
                         "could not install everycr tokens");
    }
    hstex_source_name_top(&engine->sources,
                          (uint8_t)HSTEX_TOKEN_SOURCE_TOKEN_PARAMETER,
                          (uint32_t)HSTEX_TOKEN_EVERY_CR);
    trace_token_parameter(engine, (size_t)HSTEX_TOKEN_EVERY_CR);
    return 0;
}

static int reserve_align_rows(struct hstex_align_row **rows, size_t *capacity,
                              size_t required, char *error,
                              size_t error_capacity)
{
    if (required <= *capacity) {
        return 0;
    }
    size_t next = *capacity == 0U ? 8U : *capacity;
    while (next < required) {
        if (next > SIZE_MAX / 2U) {
            return set_error(error, error_capacity, "alignment row overflow");
        }
        next *= 2U;
    }
    if (next > SIZE_MAX / sizeof(**rows)) {
        return set_error(error, error_capacity, "alignment row overflow");
    }
    void *allocation = realloc(*rows, next * sizeof(**rows));
    if (allocation == NULL) {
        return set_error(error, error_capacity,
                         "alignment row allocation failed");
    }
    *rows = allocation;
    *capacity = next;
    return 0;
}

/* \halign: read the preamble, read every row at its natural width, then set
   the columns to the width of their widest entry and put the rows in the
   enclosing vertical list.

   An alignment may also be the whole of a display, which is how amsmath sets
   align and gather. The rows are then gathered aside so that the display's
   penalties and skips can be read at the closing $$; see
   docs/DECISIONS.md, display-alignments. */
/* The `to <dimen>' or `spread <dimen>' an alignment may be given, and the
   brace that opens its preamble. */
static int scan_alignment_spec(struct hstex_engine *engine, bool *matched_to,
                               bool *matched_spread, int32_t *requested_width,
                               char *error, size_t error_capacity)
{
    if (try_keyword(engine, "to", matched_to, error, error_capacity) != 0) {
        return -1;
    }
    if (!*matched_to &&
        try_keyword(engine, "spread", matched_spread, error,
                    error_capacity) != 0) {
        return -1;
    }
    if ((*matched_to || *matched_spread) &&
        scan_dimension(engine, requested_width, error, error_capacity) != 0) {
        return -1;
    }
    /* The body's brace is sought as any other mandatory one is: \relax is
       stepped over, a control sequence \let to a `{' will do, and where
       there is none the reference says "Missing { inserted" and reads the
       token again as the first of the preamble. */
    return scan_left_brace(engine, error, error_capacity);
}

static int execute_alignment_inner(struct hstex_engine *engine, bool vertical,
                                   char *error, size_t error_capacity)
{
    if (engine->pending_global || engine->pending_macro_flags != 0U) {
        return set_error(error, error_capacity,
                         "an alignment does not accept prefixes");
    }
    bool display = false;
    if (vertical) {
        /* \valign builds columns side by side, so it belongs where boxes
           stand side by side. */
        if (ensure_horizontal_mode(engine, error, error_capacity) != 0 ||
            flush_pending_character(engine, error, error_capacity) != 0) {
            return -1;
        }
    } else if (engine->mode == HSTEX_MODE_MATH) {
        const struct hstex_math_builder *list = current_math_list(engine);
        if (!engine->displayed_math || engine->reading_equation_number ||
            list == NULL || engine->math_depth != engine->math_floor + 1U) {
            return set_error(error, error_capacity,
                             "\\halign requires vertical mode");
        }
        if (list->count != 0U) {
            static const char *const help[] = {
                "Displays can use special alignments (like \\eqalignno)",
                "only if nothing but the alignment itself is between $$'s.",
                "So I've deleted the formulas that preceded this alignment.",
                NULL};
            tex_error(engine, help, "Improper \\halign inside $$'s");
            current_math_list(engine)->count = 0U;
        }
        display = true;
    } else if (engine->mode != HSTEX_MODE_VERTICAL) {
        return set_error(error, error_capacity,
                         "\\halign requires vertical mode");
    }
    bool matched_to = false;
    bool matched_spread = false;
    int32_t requested_width = 0;
    /* The mode changes before the spec is read, not after: whatever the
       alignment was met in, its spec is scanned in the mode its entries will
       run in -- internal vertical for \halign, restricted horizontal for
       \valign.  That is visible in \tracingcommands, which names the mode
       for `to\the\hsize'.  See docs/DECISIONS.md,
       the-mode-an-alignment-spec-is-read-in. */
    enum hstex_mode outer_mode = engine->mode;
    bool outer_inner = engine->inner_mode;
    engine->mode = vertical ? HSTEX_MODE_HORIZONTAL : HSTEX_MODE_VERTICAL;
    engine->inner_mode = true;
    int spec = scan_alignment_spec(engine, &matched_to, &matched_spread,
                                   &requested_width, error, error_capacity);
    engine->mode = outer_mode;
    engine->inner_mode = outer_inner;
    if (spec != 0) {
        return -1;
    }

    /* The alignment gathers its rows in a list of its own, which runs across
       the direction its entries do. See docs/DECISIONS.md, showlists. */
    if (nest_push_fixed(engine,
                        vertical ? HSTEX_MODE_HORIZONTAL : HSTEX_MODE_VERTICAL,
                        error, error_capacity) != 0) {
        return -1;
    }
    engine->alignment_line =
        (int32_t)engine->nest[engine->nest_count - 1U].line;
    uint32_t base_group_level = engine->group_level;
    /* The glue before the first column is \tabskip as it stood when the
       alignment began; the preamble's own assignments set the later ones. */
    struct hstex_glue leading = engine->glue_parameters[HSTEX_GLUE_TAB_SKIP];
    int32_t shift = 0;
    if (display) {
        /* The formula the display was going to hold is empty and goes away;
           what is left is a vertical list, gathered aside until the closing
           $$ says what surrounds it. \prevdepth is carried over, so the
           first row is spaced from the line above it as any box would be. */
        pop_math_list(engine);
        engine->mode = HSTEX_MODE_VERTICAL;
        engine->inner_mode = false;
        engine->displayed_math = false;
        shift = engine->dimen_parameters[HSTEX_DIMEN_DISPLAY_INDENT];
        engine->display_outer_vbox = engine->active_vbox_builder;
        engine->display_rows = calloc(1U, sizeof(*engine->display_rows));
        if (engine->display_rows == NULL) {
            return set_error(error, error_capacity,
                             "display alignment allocation failed");
        }
        engine->active_vbox_builder = engine->display_rows;
    }
    if (begin_group(engine, HSTEX_GROUP_BRACE, error, error_capacity) != 0) {
        return -1;
    }
    struct hstex_align_column *columns = NULL;
    size_t column_count = 0U;
    size_t column_capacity = 0U;
    size_t loop_start = SIZE_MAX;
    struct hstex_align_row *rows = NULL;
    size_t row_count = 0U;
    size_t row_capacity = 0U;
    /* The depth of the row last read, which is what \prevdepth stands at
       inside a \noalign; before the first row it is what the list the
       alignment joins stood at. See docs/DECISIONS.md,
       prevdepth-inside-noalign. */
    int32_t row_depth = engine->prev_depth;
    /* And the alignment's OWN space factor, which a \valign leaves behind
       it. It begins at the enclosing list's, a \noalign reads and writes
       it, and a row leaves it at 1000. See docs/DECISIONS.md,
       what-an-alignment-leaves-behind. */
    int32_t row_space_factor = engine->space_factor;
    /* The preamble is read in the alignment's own mode too. Nothing in it
       is expanded unless \span asks for it, and what \span expands is
       traced there: trip line 331 writes `\span\iftrue' in a \halign
       preamble and the reference names internal vertical mode for it. The
       templates themselves are kept unexpanded and run later, in the
       entry's mode, which is why an \iftrue written plainly in a preamble
       is traced in restricted horizontal mode instead. */
    enum hstex_mode mode_before_rows = engine->mode;
    bool inner_before_rows = engine->inner_mode;
    engine->mode = vertical ? HSTEX_MODE_HORIZONTAL : HSTEX_MODE_VERTICAL;
    engine->inner_mode = true;
    int status = scan_align_preamble(engine, &columns, &column_count,
                                     &loop_start, error, error_capacity);
    column_capacity = column_count;
    /* What the preamble itself declared, which is what the repeating part is
       measured against; see docs/DECISIONS.md, a-repeating-preamble. */
    size_t preamble_columns = column_count;
    if (status == 0) {
        status = insert_every_cr(engine, error, error_capacity);
    }
    /* What stood before the alignment stands again once the rows are done;
       the peek below puts the alignment's own mode back before each row. */
    engine->mode = mode_before_rows;
    engine->inner_mode = inner_before_rows;
    bool previous_building = engine->building_alignment;
    engine->building_alignment = true;

    while (status == 0) {
        hstex_token token = 0U;
        struct hstex_source_location peek;
        /* Between rows the engine stands in the alignment's own list, and
           the peek that looks for the next row expands where it stands: an
           \iftrue at the head of an entry is traced in internal vertical
           mode for \halign and in restricted horizontal for \valign, not in
           the mode the entry before it ran in. */
        engine->mode = vertical ? HSTEX_MODE_HORIZONTAL : HSTEX_MODE_VERTICAL;
        engine->inner_mode = true;
        enum hstex_engine_result peeked =
            align_peek_token(engine, &token, &peek, error, error_capacity);
        if (peeked == HSTEX_ENGINE_ERROR) {
            status = -1;
            break;
        }
        if (peeked == HSTEX_ENGINE_EOF) {
            status = set_error(error, error_capacity,
                               "input ended inside an alignment");
            break;
        }
        if (token_is_effective_end_group(engine, token)) {
            break;
        }
        if (hstex_token_is_control_sequence(token)) {
            const struct hstex_meaning *meaning = hstex_engine_meaning(
                engine, hstex_token_control_sequence_id(token));
            if (meaning->command == HSTEX_COMMAND_CR &&
                meaning->value.integer != 0) {
                continue; /* \crcr between rows does nothing */
            }
            if (meaning->command == HSTEX_COMMAND_NO_ALIGN) {
                hstex_token brace = 0U;
                struct hstex_source_location where;
                if (expanded_next_non_space_unrestricted(
                        engine, &brace, &where, error, error_capacity) !=
                        HSTEX_ENGINE_TOKEN ||
                    !token_is_effective_begin_group(engine, brace)) {
                    status = set_error(error, error_capacity,
                                       "\\noalign requires a braced list");
                    break;
                }
                struct hstex_vbox_builder between = {0};
                struct hstex_hbox_builder between_across = {0};
                uint32_t *items = NULL;
                size_t item_count = 0U;
                int32_t settled = row_depth;
                if (vertical) {
                    /* A \valign's rows are columns, so what stands between
                       them is a horizontal list, and the reference is in
                       restricted horizontal mode there. Measured:
                       \ifhmode is true inside a \valign's \noalign and
                       false inside a \halign's. */
                    status = evaluate_hbox_contents(
                        engine, &between_across, row_space_factor,
                        &row_space_factor, error, error_capacity);
                    items = between_across.node_identifiers;
                    item_count = between_across.count;
                } else {
                    /* The alignment's list already holds the rows before
                       this one, so a paragraph starting here is not the
                       first thing in it. */
                    between.continues = row_count != 0U;
                    /* \noalign material sits in the alignment's own vertical
                       list, so \prevdepth is the depth of the row before it;
                       see docs/DECISIONS.md, prevdepth-inside-noalign. */
                    int32_t enclosing_depth = engine->prev_depth;
                    status = evaluate_vbox_contents(engine, &between,
                                                    row_depth, &settled, NULL,
                                                    false, error,
                                                    error_capacity);
                    engine->prev_depth = enclosing_depth;
                    items = between.node_identifiers;
                    item_count = between.count;
                }
                if (status == 0) {
                    status = reserve_align_rows(&rows, &row_capacity,
                                                row_count + 1U, error,
                                                error_capacity);
                }
                if (status != 0) {
                    free(items);
                    break;
                }
                struct hstex_align_row *entry = &rows[row_count++];
                memset(entry, 0, sizeof(*entry));
                entry->noalign = true;
                entry->items = items;
                entry->item_count = item_count;
                entry->prev_depth = settled;
                row_depth = settled;
                continue;
            }
        }
        if (push_one(engine, token, peek, error, error_capacity) != 0) {
            status = -1;
            break;
        }
        /* One row. */
        if (reserve_align_rows(&rows, &row_capacity, row_count + 1U, error,
                               error_capacity) != 0) {
            status = -1;
            break;
        }
        struct hstex_align_row *row = &rows[row_count++];
        memset(row, 0, sizeof(*row));
        if (nest_push_fixed(engine,
                            vertical ? HSTEX_MODE_VERTICAL
                                     : HSTEX_MODE_HORIZONTAL,
                            error, error_capacity) != 0) {
            status = -1;
            break;
        }
        {
            /* A row begins with the alignment's leading \tabskip already in
               it, and with the count the row's direction keeps standing at
               NOTHING rather than at the usual value: a \halign row starts
               at space factor 0, a \valign row at prevdepth 0. See
               docs/DECISIONS.md, a-row-of-an-alignment. */
            struct hstex_nest_level *row_level =
                &engine->nest[engine->nest_count - 1U];
            row_level->row_tabskip_known = true;
            row_level->row_tabskip = leading;
            if (vertical) {
                row_level->prev_depth = 0;
            } else {
                row_level->space_factor = 0;
            }
        }
        size_t cell_capacity = 0U;
        size_t column = 0U;
        for (;;) {
            hstex_token first = 0U;
            struct hstex_source_location start;
            enum hstex_engine_result got = align_peek_token(
                engine, &first, &start, error, error_capacity);
            if (got != HSTEX_ENGINE_TOKEN) {
                status = set_error(error, error_capacity,
                                   "input ended inside an alignment row");
                break;
            }
            /* Whether the column exists is settled before anything of the
               entry is read, so that where it does not the row ends with
               nothing taken. */
            int extended = extend_align_columns(&columns, &column_count,
                                                &column_capacity, loop_start,
                                                preamble_columns, column,
                                                error, error_capacity);
            if (extended < 0) {
                status = -1;
                break;
            }
            if (extended > 0) {
                /* The reference turns the tab that asked for it into a \cr,
                   so the row ends here and what follows begins the next
                   one. */
                static const char *const help[] = {
                    "You have given more \\span or & marks than there were",
                    "in the preamble to the \\halign or \\valign now in "
                    "progress.",
                    "So I'll assume that you meant to type \\cr instead.",
                    NULL};
                if (push_one(engine, first, start, error, error_capacity) !=
                    0) {
                    status = -1;
                    break;
                }
                tex_error(engine, help,
                          "Extra alignment tab has been changed to \\cr");
                break;
            }
            bool omit = false;
            if (hstex_token_is_control_sequence(first) &&
                hstex_engine_meaning(engine,
                                     hstex_token_control_sequence_id(first))
                        ->command == HSTEX_COMMAND_OMIT) {
                omit = true;
            } else if (push_one(engine, first, start, error, error_capacity) !=
                       0) {
                status = -1;
                break;
            }
            struct hstex_hbox_builder cell = {0};
            struct hstex_vbox_builder vertical_cell = {0};
            enum hstex_align_end ending = HSTEX_ALIGN_END_CR;
            uint32_t span = 1U;
            status = evaluate_align_cell(engine, vertical, columns,
                                         column_count, column, omit, &cell,
                                         &vertical_cell, &ending, &span, error,
                                         error_capacity);
            struct hstex_box box = {0};
            if (status == 0) {
                status = vertical ? finalize_vbox(engine, &vertical_cell,
                                                  false, false, 0, &box, error,
                                                  error_capacity)
                                  : finalize_hbox(engine, &cell, false, false,
                                                  0, &box, error,
                                                  error_capacity);
            }
            free(cell.node_identifiers);
            free(vertical_cell.node_identifiers);
            if (status != 0) {
                break;
            }
            /* WHAT AN ENTRY LEAVES BEHIND MOVES OUT OF IT AS IT IS
               PACKED and stands behind the row. Only a \halign's entries:
               a \valign's are packed as vertical lists, which keep what
               they hold. See docs/DECISIONS.md,
               what-migrates-out-of-an-alignment-entry. */
            if (!vertical) {
                uint32_t *moved = NULL;
                size_t moved_count = 0U;
                if (migrate_out_of_hbox(engine, &box, &moved, &moved_count,
                                        error, error_capacity) != 0) {
                    status = -1;
                    break;
                }
                if (moved_count != 0U) {
                    void *grown = realloc(
                        row->migrated,
                        (row->migrated_count + moved_count) *
                            sizeof(*row->migrated));
                    if (grown == NULL) {
                        free(moved);
                        status = set_error(error, error_capacity,
                                           "alignment migration allocation "
                                           "failed");
                        break;
                    }
                    row->migrated = grown;
                    for (size_t move = 0U; move < moved_count; ++move) {
                        row->migrated[row->migrated_count++] = moved[move];
                    }
                }
                free(moved);
            }
            uint32_t identifier = 0U;
            if (store_box_node(engine, &box, 0, &identifier, error,
                               error_capacity) != 0) {
                status = -1;
                break;
            }
            if (row->cell_count == cell_capacity) {
                size_t next = cell_capacity == 0U ? 4U : cell_capacity * 2U;
                void *allocation =
                    realloc(row->cells, next * sizeof(*row->cells));
                if (allocation == NULL) {
                    status = set_error(error, error_capacity,
                                       "alignment entry allocation failed");
                    break;
                }
                row->cells = allocation;
                cell_capacity = next;
            }
            struct hstex_align_cell *entry = &row->cells[row->cell_count++];
            entry->box = identifier;
            /* What the entry measures is the direction the alignment runs
               across: a row's entries are measured by width, a column's by
               how tall and deep they are together. */
            entry->width = vertical ? box.height + box.depth : box.width;
            entry->span = span;
            column += span;
            if (ending == HSTEX_ALIGN_END_CR) {
                break;
            }
            /* THE TAB THAT ENDED THE ENTRY IS WHERE AN EXTRA ONE IS FOUND,
               not the token that would begin the next entry: the reference
               looks for the column as soon as the entry is done with, while
               the template that tab put in is still standing, so that is what
               its context draws. See docs/DECISIONS.md, where-an-extra-tab-
               is-found. */
            int further = extend_align_columns(&columns, &column_count,
                                               &column_capacity, loop_start,
                                               preamble_columns, column, error,
                                               error_capacity);
            if (further < 0) {
                status = -1;
                break;
            }
            if (further > 0) {
                static const char *const help[] = {
                    "You have given more \\span or & marks than there were",
                    "in the preamble to the \\halign or \\valign now in "
                    "progress.",
                    "So I'll assume that you meant to type \\cr instead.",
                    NULL};
                tex_error(engine, help,
                          "Extra alignment tab has been changed to \\cr");
                break;
            }
        }
        if (status != 0) {
            break;
        }
        /* The row's depth is the deepest of its entries, which is what a
           \noalign after it measures from. */
        row_depth = 0;
        for (size_t cell = 0U; cell < row->cell_count; ++cell) {
            uint32_t held = row->cells[cell].box;
            if (held == 0U || (size_t)held > engine->node_count) {
                continue;
            }
            int32_t depth = packed_dimen(engine->nodes[held - 1U].depth);
            if (depth > row_depth) {
                row_depth = depth;
            }
        }
        /* And a row leaves the alignment's own space factor at 1000. */
        row_space_factor = 1000;
        nest_pop(engine);
        status = insert_every_cr(engine, error, error_capacity);
    }
    engine->mode = mode_before_rows;
    engine->inner_mode = inner_before_rows;
    engine->building_alignment = previous_building;
    /* The alignment's own groups end BEFORE its preamble is packed and its
       rows are set: what the preamble assigned is restored first, so the
       report of that packing stands behind the restores rather than in
       front of them, and the rows are put down under the parameters that
       surround the alignment rather than the ones inside it. */
    while (engine->group_level > base_group_level) {
        if (end_group(engine, error, error_capacity) < 0) {
            status = -1;
            break;
        }
    }
    if (status == 0) {
        status = finish_alignment(engine, vertical, columns, column_count,
                                  leading, rows, row_count, matched_to,
                                  matched_spread, requested_width, shift,
                                  display, error, error_capacity);
        /* What the rows left \prevdepth at, which is what follows the
           display; see docs/DECISIONS.md, prevdepth-inside-noalign. */
        engine->display_prev_depth = engine->prev_depth;
    }
    /* A \valign's own list is a horizontal one, so what it leaves behind in
       the list it joins is the space factor rather than \prevdepth. */
    if (vertical) {
        engine->space_factor = row_space_factor;
    }
    nest_pop(engine);
    destroy_align_columns(columns, column_count);
    destroy_align_rows(rows, row_count);
    /* An alignment's rows reach the page as any box does, so the page
       builder runs the moment the last of them is down rather than when the
       next thing to be read happens to call it. */
    if (status == 0) {
        status = contribute_page(engine, error, error_capacity);
    }
    if (display) {
        engine->active_vbox_builder = engine->display_outer_vbox;
        if (status == 0) {
            engine->display_alignment = true;
            /* The display is not over: the alignment's finish stands where
               the display stood, and what it reads before the closing $$ is
               read in display math mode. \tracingcommands=2 says so for an
               expandable inside one of those assignments. end_display_
               alignment puts vertical mode back. */
            engine->mode = HSTEX_MODE_MATH;
            engine->inner_mode = false;
        } else {
            free(engine->display_rows->node_identifiers);
            free(engine->display_rows);
            engine->display_rows = NULL;
        }
    }
    return status;
}

/* \accent puts an accent over the character that follows it. The two kerns
   around the accent cancel, so the pair is exactly as wide as the accented
   character; what shows is the accent being raised to sit above it. See
   docs/DECISIONS.md, accents. */
static int execute_accent(struct hstex_engine *engine, char *error,
                          size_t error_capacity)
{
    if (engine->mode == HSTEX_MODE_MATH) {
        /* The reference reports before it reads anything, and then goes on
           as \mathaccent -- which scans its own operands, so what follows
           is read by that and not by this. */
        static const char *const help[] = {
            "I'm changing \\accent to \\mathaccent here; wish me luck.",
            "(Accents are not the same in formulas as they are in text.)",
            NULL};
        tex_error(engine, help,
                  "Please use \\mathaccent for accents in math mode");
        return execute_math_accent(engine, error, error_capacity);
    }
    int32_t code = 0;
    if (scan_integer(engine, &code, error, error_capacity) != 0) {
        return -1;
    }
    if (code < 0 || code > 255) {
        return set_error(error, error_capacity, "bad accent code (%d)", code);
    }
    if (ensure_horizontal_mode(engine, error, error_capacity) != 0 ||
        flush_pending_character(engine, error, error_capacity) != 0) {
        return -1;
    }
    const struct hstex_font *font =
        font_by_identifier(engine, engine->current_font);
    /* A character the font does not have is dropped, as any other missing
       character is, and the accent is dropped WITH it: nothing waits for a
       character, no assignment is read for it, and the space factor is left
       where it stood. What is read next is read by the main loop, and
       traced there. The ligature run is broken all the same, because
       \accent is a command and the word ended when it was met -- so
       `f\accent200 i' is an f and an i and not the fi ligature. See
       docs/DECISIONS.md, what-may-stand-between-an-accent-and-its-character. */
    bool have_accent = font != NULL && font->characters != NULL &&
                       font->characters[code].tag >= 0;
    if (font == NULL) {
        font = font_by_identifier(engine, engine->current_font);
    }
    if (!have_accent) {
        char_warning(engine, font, (uint8_t)code);
        return 0;
    }
    /* The accent itself is set in the font that was in force where \\accent
       was read, whatever an assignment after it changes the font to. */
    engine->pending_accent.font = engine->current_font;
    engine->pending_accent.code = code;
    engine->pending_accent.present = have_accent;
    engine->pending_accent.metric =
        have_accent ? font->characters[code] : (struct hstex_char_metric){0};
    engine->pending_accent.x_height =
        font != NULL && font->dimen_count >= 5U ? font->dimens[4] : 0;
    engine->pending_accent.slant =
        font != NULL && font->dimen_count >= 1U ? font->dimens[0] : 0;
    /* What stands between the accent and its character is read by the main
       loop, so that the assignments the reference carries out there really
       are carried out. See docs/DECISIONS.md,
       what-may-stand-between-an-accent-and-its-character. */
    engine->accent_pending = true;
    return 0;
}

/* The character the accent goes over, once the main loop has found it.
   `accented' is its code, or -1 when there is none. */
static int finish_accent(struct hstex_engine *engine, int32_t accented,
                         char *error, size_t error_capacity)
{
    uint32_t accent_font = engine->pending_accent.font;
    int32_t code = engine->pending_accent.code;
    bool have_accent = engine->pending_accent.present;
    struct hstex_char_metric accent = engine->pending_accent.metric;
    int32_t x_height = engine->pending_accent.x_height;
    int32_t slant = engine->pending_accent.slant;
    const struct hstex_font *font = font_by_identifier(engine, accent_font);
    engine->accent_pending = false;

    /* The character under the accent belongs to the font in force now, which
       an assignment in between may have changed. */
    const struct hstex_font *base_font =
        font_by_identifier(engine, engine->current_font);
    if (base_font == NULL || base_font->characters == NULL) {
        base_font = font;
    }
    /* A base character the font does not have is dropped too, and then the
       accent stands alone: `\accent23 \char200' is just the accent. */
    if (accented >= 0 &&
        (accented > 255 || base_font == NULL ||
         base_font->characters == NULL ||
         base_font->characters[accented].tag < 0)) {
        accented = -1;
    }
    if (!have_accent) {
        /* Nothing to set above, so what is left is the character below --
           as a character of its own, since the accent broke the run. */
        engine->space_factor = 1000;
        if (accented < 0) {
            return 0;
        }
        struct hstex_char_metric alone = base_font->characters[accented];
        struct hstex_node bare = {
            .kind = HSTEX_NODE_CHARACTER,
            .width = alone.width,
            .height = alone.height,
            .depth = alone.depth,
            .value.character = {.font = engine->current_font,
                                .character = (uint32_t)accented},
        };
        return append_hbox_node(engine, &bare, error, error_capacity);
    }

    struct hstex_node accent_node = {
        .kind = HSTEX_NODE_CHARACTER,
        .width = accent.width,
        .height = accent.height,
        .depth = accent.depth,
        .value.character = {
            .font = accent_font,
            .character = (uint32_t)code,
        },
    };
    if (accented < 0) {
        /* Nothing to accent: the accent is an ordinary character. */
        engine->space_factor = 1000;
        return append_hbox_node(engine, &accent_node, error, error_capacity);
    }

    struct hstex_char_metric under = base_font->characters[accented];
    int32_t lift = x_height - under.height;
    /* The reference works this out in one figure and rounds it once, so the
       halving and the slant cannot each lose their own scaled point; see
       docs/DECISIONS.md, accent-kerns. */
    /* The height term is scaled by the slant of the font the character under
       the accent is in, the x-height term by the accent's own. The two are
       the same font unless an assignment stood between them, which is why
       one slant did for both until \\t came along. */
    int32_t under_slant =
        base_font->dimen_count >= 1U ? base_font->dimens[0] : 0;
    int64_t numerator =
        INT64_C(65536) * ((int64_t)under.width - accent.width) +
        2 * ((int64_t)under.height * (int64_t)under_slant -
             (int64_t)x_height * (int64_t)slant);
    int64_t delta = numerator >= 0
                        ? (numerator + INT64_C(65536)) / INT64_C(131072)
                        : -((-numerator + INT64_C(65536)) / INT64_C(131072));
    /* The two kerns an accent rides between are of a kind of their own, which
       \showbox says so of; see docs/DECISIONS.md, accent-kerns. */
    struct hstex_node before = {
        .kind = HSTEX_NODE_KERN,
        .width = (int32_t)delta,
        .value.kern = {.margin = 3U},
    };
    struct hstex_node after = {
        .kind = HSTEX_NODE_KERN,
        .width = (int32_t)(-(int64_t)accent.width - delta),
        .value.kern = {.margin = 3U},
    };
    if (append_hbox_node(engine, &before, error, error_capacity) != 0) {
        return -1;
    }
    if (lift == 0) {
        if (append_hbox_node(engine, &accent_node, error, error_capacity) != 0) {
            return -1;
        }
    } else {
        /* The accent rides in a box of its own so that it can be raised. */
        struct hstex_hbox_builder builder = {0};
        struct hstex_hbox_builder *previous = engine->active_hbox_builder;
        engine->active_hbox_builder = &builder;
        int status = append_hbox_node(engine, &accent_node, error,
                                      error_capacity);
        engine->active_hbox_builder = previous;
        struct hstex_box box = {0};
        if (status == 0) {
            status = finalize_hbox(engine, &builder, false, false, 0, &box,
                                   error, error_capacity);
        }
        free(builder.node_identifiers);
        if (status != 0) {
            return -1;
        }
        struct hstex_node raised = {
            .kind = HSTEX_NODE_LIST,
            .width = box.width,
            .height = box.height,
            .depth = box.depth,
            .shift = lift,
            .value.list = {
                .node_start = box.node_start,
                .node_count = box.node_count,
                .box_kind = box.kind,
                .glue = box.glue,
            },
        };
        if (append_hbox_node(engine, &raised, error, error_capacity) != 0) {
            return -1;
        }
    }
    struct hstex_node body = {
        .kind = HSTEX_NODE_CHARACTER,
        .width = under.width,
        .height = under.height,
        .depth = under.depth,
        .value.character = {
            .font = engine->current_font,
            .character = (uint32_t)accented,
        },
    };
    if (append_hbox_node(engine, &after, error, error_capacity) != 0 ||
        append_hbox_node(engine, &body, error, error_capacity) != 0) {
        return -1;
    }
    engine->space_factor = 1000;
    return 0;
}

/* A write to a stream that is not open goes to the log, and also to the
   terminal unless the stream number is negative. \typeout relies on this: it
   writes to an allocated but never opened stream. HSTeX has one diagnostic
   surface so far, so both destinations are where \message writes. */
static int write_stream_bytes(struct hstex_engine *engine, int32_t stream,
                              const uint8_t *bytes, size_t byte_count,
                              char *error, size_t error_capacity)
{
    if (stream >= 0 && stream < 16 &&
        engine->write_streams[(size_t)stream] != NULL) {
        FILE *destination = engine->write_streams[(size_t)stream];
        if ((byte_count != 0U &&
             fwrite(bytes, 1U, byte_count, destination) != byte_count) ||
            fputc('\n', destination) == EOF || fflush(destination) != 0) {
            return set_error(error, error_capacity, "write stream failed");
        }
        return 0;
    }
    /* A stream that was never opened writes where the diagnostics go, on a
       line of its own; see docs/DECISIONS.md, the-print-line. A NEGATIVE
       stream number goes to the log alone, so the terminal keeps its column
       across it -- which is what the reference does by dropping its selector
       to the log for the write and putting it back after. */
    bool saved_selector = begin_log_only(engine, stream < 0);
    print_fresh_line(engine);
    print_bytes(engine, (const char *)bytes, byte_count);
    print_line(engine);
    end_log_only(engine, saved_selector);
    if (fflush(diagnostic_stream(engine)) != 0) {
        return set_error(error, error_capacity, "write stream failed");
    }
    return 0;
}

struct hstex_system_arguments {
    char *storage;
    char **items;
    size_t count;
    size_t capacity;
};

static void destroy_system_arguments(struct hstex_system_arguments *arguments)
{
    free(arguments->storage);
    free(arguments->items);
    memset(arguments, 0, sizeof(*arguments));
}

static bool system_argument_space(uint8_t byte)
{
    return byte == (uint8_t)' ' || byte == (uint8_t)'\t' ||
           byte == (uint8_t)'\n' || byte == (uint8_t)'\r';
}

static int append_system_argument(struct hstex_system_arguments *arguments,
                                  char *word, char *error,
                                  size_t error_capacity)
{
    if (arguments->count + 2U > arguments->capacity) {
        size_t capacity = arguments->capacity == 0U
                              ? 8U
                              : arguments->capacity * 2U;
        if (capacity < arguments->capacity ||
            capacity > SIZE_MAX / sizeof(*arguments->items)) {
            return set_error(error, error_capacity,
                             "system command has too many arguments");
        }
        char **grown = realloc(arguments->items,
                               capacity * sizeof(*arguments->items));
        if (grown == NULL) {
            return set_error(error, error_capacity,
                             "system argument allocation failed");
        }
        arguments->items = grown;
        arguments->capacity = capacity;
    }
    arguments->items[arguments->count++] = word;
    arguments->items[arguments->count] = NULL;
    return 0;
}

/* Restricted shell escape is parsed into an argv and executed directly.
   Quotes and backslashes group arguments, but no byte is interpreted by a
   command shell, so a filename cannot append a second command. */
static int parse_system_arguments(const uint8_t *bytes, size_t byte_count,
                                  struct hstex_system_arguments *arguments,
                                  char *error, size_t error_capacity)
{
    memset(arguments, 0, sizeof(*arguments));
    arguments->storage = malloc(byte_count + 1U);
    if (arguments->storage == NULL) {
        return set_error(error, error_capacity,
                         "system command allocation failed");
    }
    size_t cursor = 0U;
    size_t used = 0U;
    while (cursor < byte_count) {
        while (cursor < byte_count && system_argument_space(bytes[cursor])) {
            ++cursor;
        }
        if (cursor == byte_count) {
            break;
        }
        if (append_system_argument(arguments, arguments->storage + used, error,
                                   error_capacity) != 0) {
            destroy_system_arguments(arguments);
            return -1;
        }
        uint8_t quote = 0U;
        while (cursor < byte_count) {
            uint8_t byte = bytes[cursor];
            if (byte == 0U) {
                destroy_system_arguments(arguments);
                return 1;
            }
            if (quote == 0U && system_argument_space(byte)) {
                break;
            }
            if (quote == 0U &&
                (byte == (uint8_t)'\'' || byte == (uint8_t)'"')) {
                quote = byte;
                ++cursor;
                continue;
            }
            if (quote != 0U && byte == quote) {
                quote = 0U;
                ++cursor;
                continue;
            }
            if (byte == (uint8_t)'\\' && quote != (uint8_t)'\'') {
                ++cursor;
                if (cursor == byte_count || bytes[cursor] == 0U) {
                    destroy_system_arguments(arguments);
                    return 1;
                }
                byte = bytes[cursor];
            }
            arguments->storage[used++] = (char)byte;
            ++cursor;
        }
        if (quote != 0U) {
            destroy_system_arguments(arguments);
            return 1;
        }
        arguments->storage[used++] = '\0';
    }
    if (arguments->count == 0U) {
        destroy_system_arguments(arguments);
        return 1;
    }
    return 0;
}

static bool restricted_program_allowed(const struct hstex_engine *engine,
                                       const char *program)
{
    if (program[0] == '\0' || strchr(program, '/') != NULL ||
        engine->shell_escape_commands == NULL) {
        return false;
    }
    const char *cursor = engine->shell_escape_commands;
    while (*cursor != '\0') {
        while (*cursor == ',' || system_argument_space((uint8_t)*cursor)) {
            ++cursor;
        }
        const char *start = cursor;
        while (*cursor != '\0' && *cursor != ',') {
            ++cursor;
        }
        const char *end = cursor;
        while (end > start &&
               system_argument_space((uint8_t)end[-1])) {
            --end;
        }
        size_t length = (size_t)(end - start);
        if (strlen(program) == length &&
            memcmp(program, start, length) == 0) {
            return true;
        }
    }
    return false;
}

static int report_system_command(struct hstex_engine *engine,
                                 const uint8_t *bytes, size_t byte_count,
                                 const char *result, char *error,
                                 size_t error_capacity)
{
    print_fresh_line(engine);
    print_text(engine, "runsystem(");
    print_bytes(engine, (const char *)bytes, byte_count);
    print_text(engine, ")...");
    print_text(engine, result);
    print_line(engine);
    if (fflush(diagnostic_stream(engine)) != 0) {
        return set_error(error, error_capacity,
                         "system command diagnostic failed");
    }
    return 0;
}

static int execute_system_command(struct hstex_engine *engine,
                                  const uint8_t *bytes, size_t byte_count,
                                  char *error, size_t error_capacity)
{
    if (engine->shell_escape_mode == 0) {
        return report_system_command(engine, bytes, byte_count, "disabled.",
                                     error, error_capacity);
    }
    struct hstex_system_arguments arguments;
    int parsed = parse_system_arguments(bytes, byte_count, &arguments, error,
                                        error_capacity);
    if (parsed < 0) {
        return -1;
    }
    if (parsed > 0) {
        destroy_system_arguments(&arguments);
        return report_system_command(engine, bytes, byte_count,
                                     "disabled (restricted).", error,
                                     error_capacity);
    }
    if (load_restricted_shell_commands(engine, error, error_capacity) != 0) {
        destroy_system_arguments(&arguments);
        return -1;
    }
    if (!restricted_program_allowed(engine, arguments.items[0])) {
        destroy_system_arguments(&arguments);
        return report_system_command(engine, bytes, byte_count,
                                     "disabled (restricted).", error,
                                     error_capacity);
    }

    FILE *messages = diagnostic_stream(engine);
    (void)fflush(messages);
    posix_spawn_file_actions_t actions;
    if (posix_spawn_file_actions_init(&actions) != 0) {
        destroy_system_arguments(&arguments);
        return set_error(error, error_capacity,
                         "cannot prepare restricted system command");
    }
    int descriptor = fileno(messages);
    int action_status = 0;
    if (descriptor >= 0) {
        if (descriptor != STDOUT_FILENO) {
            action_status = posix_spawn_file_actions_adddup2(
                &actions, descriptor, STDOUT_FILENO);
        }
        if (action_status == 0 && descriptor != STDERR_FILENO) {
            action_status = posix_spawn_file_actions_adddup2(
                &actions, descriptor, STDERR_FILENO);
        }
    }
    pid_t child = 0;
    int spawned = action_status != 0
                      ? action_status
                      : posix_spawnp(&child, arguments.items[0], &actions,
                                     NULL, arguments.items, environ);
    (void)posix_spawn_file_actions_destroy(&actions);
    int child_status = 0;
    while (spawned == 0 && waitpid(child, &child_status, 0) < 0 &&
           errno == EINTR) {
    }
    (void)child_status;
    ++engine->file_generation;
    ++engine->external_file_generation;
    destroy_system_arguments(&arguments);
    return report_system_command(engine, bytes, byte_count,
                                 "executed safely (allowed).", error,
                                 error_capacity);
}

static int execute_write(struct hstex_engine *engine, bool immediate,
                         char *error, size_t error_capacity)
{
    int32_t stream = 0;
    /* \write accepts any stream number; only 0..15 can name an open file. */
    if (scan_integer(engine, &stream, error, error_capacity) != 0) {
        return -1;
    }
    bool system_command = stream == 18;
    if (!immediate) {
        /* The text is kept as it was written and expanded when the page is
           shipped, which is what lets \write{\thepage} name the page it
           landed on. See docs/DECISIONS.md, whatsits. */
        struct hstex_token_vector text = {0};
        uint32_t tokens = 0U;
        if (scan_general_text(engine, &text, error, error_capacity) != 0) {
            return -1;
        }
        if (store_token_list(engine, &text, &tokens, error, error_capacity) !=
            0) {
            vector_destroy(&text);
            return -1;
        }
        return new_whatsit(engine,
                           system_command ? HSTEX_WHATSIT_SYSTEM
                                          : HSTEX_WHATSIT_WRITE,
                           stream, tokens, error, error_capacity);
    }
    uint8_t *bytes = NULL;
    size_t byte_count = 0U;
    bool outer_no_mode = engine->in_no_mode;
    engine->in_no_mode = true;
    int expanded = scan_expanded_general_text(engine, &bytes, &byte_count,
                                              error, error_capacity);
    engine->in_no_mode = outer_no_mode;
    if (expanded != 0) {
        free(bytes);
        return -1;
    }
    int status = system_command
                     ? execute_system_command(engine, bytes, byte_count, error,
                                              error_capacity)
                     : write_stream_bytes(engine, stream, bytes, byte_count,
                                          error, error_capacity);
    free(bytes);
    return status;
}

/* \special is expanded where it stands, and only its writing waits for the
   page; see docs/DECISIONS.md, whatsits. */
/* The reference keeps a hyphenmin between one and sixty-three, whatever the
   parameter says. */
static uint8_t normalised_hyphen_min(int32_t value)
{
    if (value <= 0) {
        return 1U;
    }
    return value >= 63 ? 63U : (uint8_t)value;
}

/* \setlanguage: the words after it are hyphenated in the language it names,
   with the two hyphenmins as they stand here rather than as they stand when
   the paragraph is broken. A language outside 0..255 means language 0. See
   docs/DECISIONS.md, setlanguage. */
static int execute_set_language(struct hstex_engine *engine, char *error,
                                size_t error_capacity)
{
    int32_t language = 0;
    if (scan_integer(engine, &language, error, error_capacity) != 0) {
        return -1;
    }
    if (engine->mode != HSTEX_MODE_HORIZONTAL) {
        report_illegal_case(engine, engine->executing_token);
        return 0;
    }
    if (flush_pending_character(engine, error, error_capacity) != 0) {
        return -1;
    }
    if (language <= 0 || language > 255) {
        language = 0;
    }
    /* The list is now setting that language, so nothing needs to say so
       again until \\language moves on. */
    if (engine->nest_count != 0U) {
        engine->nest[engine->nest_count - 1U].current_language = language;
    }
    struct hstex_node node = {
        .kind = HSTEX_NODE_WHATSIT,
        .value.whatsit = {
            .kind = (uint8_t)HSTEX_WHATSIT_LANGUAGE,
            .stream = normalised_hyphen_min(
                engine->integer_parameters[HSTEX_INTEGER_LEFT_HYPHEN_MIN]),
            .action = normalised_hyphen_min(
                engine->integer_parameters[HSTEX_INTEGER_RIGHT_HYPHEN_MIN]),
            .number = language,
        },
    };
    return append_hbox_node(engine, &node, error, error_capacity);
}

static int execute_special(struct hstex_engine *engine, char *error,
                           size_t error_capacity)
{
    uint8_t *bytes = NULL;
    size_t byte_count = 0U;
    if (scan_general_text_expanding(engine, &bytes, &byte_count, error,
                                   error_capacity) != 0) {
        free(bytes);
        return -1;
    }
    struct hstex_token_vector tokens = {0};
    for (size_t index = 0U; index < byte_count; ++index) {
        uint8_t category = bytes[index] == (uint8_t)' '
                               ? (uint8_t)HSTEX_CAT_SPACE
                               : (uint8_t)HSTEX_CAT_OTHER;
        if (vector_push(&tokens,
                        hstex_token_character(category, bytes[index]), error,
                        error_capacity) != 0) {
            vector_destroy(&tokens);
            free(bytes);
            return -1;
        }
    }
    free(bytes);
    uint32_t identifier = 0U;
    if (store_token_list(engine, &tokens, &identifier, error, error_capacity) !=
        0) {
        vector_destroy(&tokens);
        return -1;
    }
    return new_whatsit(engine, HSTEX_WHATSIT_SPECIAL, 0, identifier, error,
                       error_capacity);
}

/* Gathers the whatsits of a shipped box, innermost list last, so that they
   can be done in the order they were written. The identifiers are collected
   first because doing one of them may expand macros and move the arenas. */
static int collect_whatsits(struct hstex_engine *engine, const uint32_t *items,
                            size_t count, uint32_t **found, size_t *found_count,
                            size_t *capacity, char *error,
                            size_t error_capacity)
{
    for (size_t index = 0U; index < count; ++index) {
        uint32_t identifier = items[index];
        if (identifier == 0U || (size_t)identifier > engine->node_count) {
            continue;
        }
        const struct hstex_node *node = &engine->nodes[identifier - 1U];
        if (node->kind == HSTEX_NODE_WHATSIT) {
            if (*found_count == *capacity) {
                size_t next = *capacity == 0U ? 8U : *capacity * 2U;
                uint32_t *grown = realloc(*found, next * sizeof(**found));
                if (grown == NULL) {
                    return set_error(error, error_capacity,
                                     "whatsit list allocation failed");
                }
                *found = grown;
                *capacity = next;
            }
            (*found)[(*found_count)++] = identifier;
        } else if (node->kind == HSTEX_NODE_LIST &&
                   node->value.list.node_count != 0U &&
                   (size_t)node->value.list.node_start +
                           node->value.list.node_count <=
                       engine->list_item_count &&
                   collect_whatsits(engine,
                                    engine->list_items +
                                        node->value.list.node_start,
                                    node->value.list.node_count, found,
                                    found_count, capacity, error,
                                    error_capacity) != 0) {
            return -1;
        }
    }
    return 0;
}

static int perform_whatsit(struct hstex_engine *engine, uint32_t identifier,
                           char *error, size_t error_capacity)
{
    if (identifier == 0U || (size_t)identifier > engine->node_count) {
        return 0;
    }
    /* The node is read again after each step, because expansion may move the
       arena out from under a pointer. */
    uint8_t kind = engine->nodes[identifier - 1U].value.whatsit.kind;
    uint8_t stored = engine->nodes[identifier - 1U].value.whatsit.stream;
    uint32_t tokens = engine->nodes[identifier - 1U].value.whatsit.tokens;
    /* Seventeen is how a negative stream was stored. */
    int32_t stream = stored == 17U ? -1 : (int32_t)stored;
    if (kind == (uint8_t)HSTEX_WHATSIT_CLOSE_OUT) {
        return close_write_stream(engine, stream, error, error_capacity);
    }
    if (kind == (uint8_t)HSTEX_WHATSIT_LITERAL) {
        uint8_t action =
            engine->nodes[identifier - 1U].value.whatsit.action;
        if (engine->integer_parameters[HSTEX_INTEGER_PDF_OUTPUT] > 0 &&
            (action & (uint8_t)HSTEX_PDF_LITERAL_SHIPOUT) != 0U) {
            return queue_pdf_shipout_literal(engine, tokens, error,
                                             error_capacity);
        }
        return 0;
    }
    if (kind == (uint8_t)HSTEX_WHATSIT_SPECIAL ||
        kind == (uint8_t)HSTEX_WHATSIT_COLOR_STACK ||
        kind == (uint8_t)HSTEX_WHATSIT_PDF_DEST ||
        kind == (uint8_t)HSTEX_WHATSIT_PDF_SAVE ||
        kind == (uint8_t)HSTEX_WHATSIT_PDF_SET_MATRIX ||
        kind == (uint8_t)HSTEX_WHATSIT_PDF_RESTORE ||
        kind == (uint8_t)HSTEX_WHATSIT_START_LINK ||
        kind == (uint8_t)HSTEX_WHATSIT_END_LINK ||
        kind == (uint8_t)HSTEX_WHATSIT_ANNOT) {
        /* What these carry belongs in the page description, not in a
           stream. See docs/DECISIONS.md, whatsits. */
        return 0;
    }
    uint8_t *bytes = NULL;
    size_t byte_count = 0U;
    if (kind == (uint8_t)HSTEX_WHATSIT_OPEN_OUT) {
        if (stored_token_list_text(engine, tokens, &bytes, &byte_count, 0U,
                                   NULL, error, error_capacity) != 0) {
            return -1;
        }
        char *filename = malloc(byte_count + 1U);
        if (filename == NULL) {
            free(bytes);
            return set_error(error, error_capacity,
                             "output path allocation failed");
        }
        memcpy(filename, bytes, byte_count);
        filename[byte_count] = '\0';
        free(bytes);
        return open_write_stream(engine, stream, filename, error,
                                 error_capacity);
    }
    bool outer_no_mode = engine->in_no_mode;
    engine->in_no_mode = true;
    int expanded = expand_stored_token_list(engine, tokens, &bytes,
                                            &byte_count, error,
                                            error_capacity);
    engine->in_no_mode = outer_no_mode;
    if (expanded != 0) {
        return -1;
    }
    int status = kind == (uint8_t)HSTEX_WHATSIT_SYSTEM
                     ? execute_system_command(engine, bytes, byte_count, error,
                                              error_capacity)
                     : write_stream_bytes(engine, stream, bytes, byte_count,
                                          error, error_capacity);
    free(bytes);
    return status;
}

static int perform_shipout_whatsits(struct hstex_engine *engine,
                                    const struct hstex_box *box, char *error,
                                    size_t error_capacity)
{
    if (box->kind == HSTEX_BOX_VOID || box->node_count == 0U ||
        (size_t)box->node_start + box->node_count > engine->list_item_count) {
        return 0;
    }
    uint32_t *found = NULL;
    size_t found_count = 0U;
    size_t capacity = 0U;
    int status = collect_whatsits(engine, engine->list_items + box->node_start,
                                  box->node_count, &found, &found_count,
                                  &capacity, error, error_capacity);
    for (size_t index = 0U; status == 0 && index < found_count; ++index) {
        status = perform_whatsit(engine, found[index], error, error_capacity);
    }
    free(found);
    return status;
}

static int execute_message(struct hstex_engine *engine, char *error,
                           size_t error_capacity)
{
    uint8_t *bytes = NULL;
    size_t byte_count = 0U;
    if (scan_general_text_expanding(engine, &bytes, &byte_count, error,
                                   error_capacity) != 0) {
        free(bytes);
        return -1;
    }
    /* A message that will not fit on the line starts a new one; one that
       fits keeps its distance from what is already there. See
       docs/DECISIONS.md, the-print-line. */
    if ((int64_t)engine->message_column + (int64_t)byte_count >
        HSTEX_PRINT_LINE - 2) {
        print_line(engine);
    } else if (engine->message_column > 0) {
        print_byte(engine, ' ');
    }
    print_bytes(engine, (const char *)bytes, byte_count);
    int status = 0;
    if (fflush(diagnostic_stream(engine)) != 0) {
        status = set_error(error, error_capacity, "message output failed");
    }
    free(bytes);
    return status;
}

static int execute_error_message(struct hstex_engine *engine, char *error,
                                 size_t error_capacity)
{
    uint8_t *bytes = NULL;
    size_t byte_count = 0U;
    if (scan_general_text_expanding(engine, &bytes, &byte_count, error,
                                   error_capacity) != 0) {
        free(bytes);
        return -1;
    }
    int precision = byte_count > (size_t)INT_MAX ? INT_MAX : (int)byte_count;
    /* The reference reports what the document said and carries on, so an
       \errmessage is a fault of the document's rather than the end of the
       run. Its help is \errhelp when that holds anything, and otherwise
       the reference's own four lines. LaTeX's \GenericError prints its
       diagnosis itself and then raises an \errmessage with nothing in it,
       which is why an empty message is not a bug. */
    static const char *const fallback[] = {
        "This error message was generated by an \\errmessage",
        "command, so I can't give any explicit help.",
        "Pretend that you're Hercule Poirot: Examine all clues,",
        "and deduce the truth by order and method.", NULL};
    /* Those four lines are worth writing once. Every \errmessage after the
       first that falls back to them is told only that there was another,
       and an \errhelp standing between does not bring them back. */
    static const char *const again[] = {"(That was another \\errmessage.)",
                                        NULL};
    uint8_t *given = NULL;
    size_t given_count = 0U;
    const char *offered[2] = {NULL, NULL};
    const char *const *help = engine->long_help_seen ? again : fallback;
    bool fell_back = true;
    uint32_t errhelp = engine->token_parameters[HSTEX_TOKEN_ERROR_HELP];
    if (errhelp != 0U &&
        stored_token_list_text(engine, errhelp, &given, &given_count, 0U, NULL,
                               error, error_capacity) == 0 &&
        given_count != 0U) {
        /* The help is handed on as a C string, and what \errhelp holds is
           counted bytes with no terminator: without one the printer reads
           past the end of the allocation. */
        uint8_t *terminated = realloc(given, given_count + 1U);
        if (terminated != NULL) {
            given = terminated;
            given[given_count] = (uint8_t)'\0';
            offered[0] = (const char *)given;
            help = offered;
            fell_back = false;
        }
    }
    if (fell_back) {
        engine->long_help_seen = true;
    }
    tex_error(engine, help, "%.*s", precision,
              bytes == NULL ? "" : (const char *)bytes);
    free(given);
    int status = 0;
    free(bytes);
    return status;
}

static int execute_open_in(struct hstex_engine *engine, char *error,
                           size_t error_capacity)
{
    int32_t stream = 0;
    char *filename = NULL;
    if (scan_four_bit_int(engine, &stream, error, error_capacity) != 0 ||
        scan_optional_equals(engine, error, error_capacity) != 0 ||
        scan_input_filename(engine, &filename, false, error,
                            error_capacity) != 0) {
        free(filename);
        return -1;
    }
    if (stream < 0 || stream >= 16) {
        free(filename);
        return 0;
    }
    if (engine->read_streams[(size_t)stream] != NULL) {
        (void)fclose(engine->read_streams[(size_t)stream]);
        engine->read_streams[(size_t)stream] = NULL;
    }
    char *path = resolve_input_path(engine, filename);
    free(filename);
    if (path != NULL) {
        engine->read_streams[(size_t)stream] = fopen(path, "rb");
    }
    free(path);
    return 0;
}

static int execute_close_in(struct hstex_engine *engine, char *error,
                            size_t error_capacity)
{
    int32_t stream = 0;
    if (scan_four_bit_int(engine, &stream, error, error_capacity) != 0) {
        return -1;
    }
    if (stream >= 0 && stream < 16 &&
        engine->read_streams[(size_t)stream] != NULL) {
        if (fclose(engine->read_streams[(size_t)stream]) != 0) {
            engine->read_streams[(size_t)stream] = NULL;
            return set_error(error, error_capacity,
                             "failed to close input stream");
        }
        engine->read_streams[(size_t)stream] = NULL;
    }
    return 0;
}

static int scan_keyword_to(struct hstex_engine *engine, char *error,
                           size_t error_capacity)
{
    static const uint8_t keyword[] = {'t', 'o'};
    for (size_t index = 0U; index < sizeof(keyword); ++index) {
        hstex_token token = 0U;
        struct hstex_source_location location;
        enum hstex_engine_result result =
            index == 0U
                ? expanded_next_non_space(engine, &token, &location, error,
                                          error_capacity)
                : hstex_engine_next_expanded(engine, &token, &location, error,
                                             error_capacity);
        if (result != HSTEX_ENGINE_TOKEN ||
            !token_has_character(token, keyword[index])) {
            return set_error(error, error_capacity, "read requires keyword to");
        }
    }
    return 0;
}

static int define_read_tokens(struct hstex_engine *engine, hstex_cs_id target,
                              struct hstex_token_vector *replacement, char *error,
                              size_t error_capacity)
{
    if (reserve_macros(engine, engine->macro_count + 1U, error,
                       error_capacity) != 0) {
        vector_destroy(replacement);
        return -1;
    }
    struct hstex_macro *macro = &engine->macros[engine->macro_count];
    memset(macro, 0, sizeof(*macro));
    macro->replacement = replacement->data;
    macro->replacement_count = replacement->count;
    count_macro_body(macro);
    memset(replacement, 0, sizeof(*replacement));
    ++engine->macro_count;
    struct hstex_meaning meaning = {
        .command = HSTEX_COMMAND_MACRO,
        .level = 0U,
        .value = {.macro_identifier = (uint32_t)engine->macro_count},
    };
    return set_meaning(engine, target, meaning,
                       assignment_is_global(engine, engine->pending_global),
                       error, error_capacity);
}

/* One line of a \read, added to what has been read so far. A \read takes
   whole braced texts, so a line that leaves a brace open wants another
   line after it, and a `}' that closes nothing ends the \read where it
   stands -- measured, a line reading `close } here' yields `close ' and
   the rest of it is gone. */
static int append_read_line(struct hstex_engine *engine, hstex_cs_id target,
                            struct hstex_token_vector *replacement,
                            const uint8_t *line, size_t length,
                            int32_t *balance, char *error,
                            size_t error_capacity)
{
    /* AN EMPTY LINE IS STILL A LINE. A valid \endlinechar makes it a \par
       when that character has end-of-line catcode; a negative value makes it
       empty. The mouth reads lines out of a buffer and a buffer with nothing
       in it holds no line at all, so a terminator goes behind the line for it
       to find. */
    uint8_t *buffer = malloc(length + 1U);
    if (buffer == NULL) {
        return set_error(error, error_capacity, "read line allocation failed");
    }
    if (length != 0U) {
        memcpy(buffer, line, length);
    }
    buffer[length] = (uint8_t)'\n';
    struct hstex_mouth mouth;
    hstex_mouth_init(&mouth, buffer, length + 1U, &engine->lexical_state);
    /* Where in the stack this line stands, so that a fault raised while it
       is being read names it. */
    const struct hstex_mouth *previous_reading = engine->reading_mouth;
    int32_t previous_stream = engine->reading_stream;
    size_t previous_base = engine->reading_base;
    engine->reading_mouth = &mouth;
    engine->reading_base = engine->sources.count;
    /* A LINE THAT HAS GONE WRONG IS STILL READ TO ITS END. Where a brace
       closes what the line never opened, or an \outer name turns up, the
       reference stops taking tokens for the macro but goes on ASKING for
       them until the line runs out -- so an invalid character further along
       the same line is still reported. trip's tripos.tex has both on one
       line: `\uppercase {0{\outputpenalty }}' with \uppercase made \outer
       and `0' made invalid. */
    bool draining = false;
    for (;;) {
        hstex_token token = 0U;
        struct hstex_source_location location;
        enum hstex_mouth_result result = hstex_mouth_next(
            &mouth, &token, &location, error, error_capacity);
        if (result == HSTEX_MOUTH_EOF) {
            break;
        }
        if (result == HSTEX_MOUTH_INVALID) {
            static const char *const help[] = {
                "A funny symbol that I can't read has just been input.",
                "Continue, and I'll forget that it ever happened.", NULL};
            tex_error(engine, help,
                      "Text line contains an invalid character");
            continue;
        }
        if (result == HSTEX_MOUTH_ERROR) {
            engine->reading_mouth = previous_reading;
            engine->reading_stream = previous_stream;
            engine->reading_base = previous_base;
            hstex_mouth_destroy(&mouth);
            free(buffer);
            return -1;
        }
        if (draining) {
            continue;
        }
        /* A \read builds a definition, and an \outer macro may no more
           stand in one of those than in any other: measured, a line reading
           `text \lz more' with \lz declared \outer gives a macro holding
           `text ' and draws the fault. */
        if (hstex_token_is_control_sequence(token) &&
            token_is_outer_macro(engine, token)) {
            static const char *const help[] = {
                "I suspect you have forgotten a `}', causing me",
                "to read past where you wanted me to stop.",
                "I'll try to recover; but if the error is serious,",
                "you'd better type `E' or `X' now and fix your file.", NULL};
            char named[128];
            describe_token(engine, hstex_token_control_sequence(target), named,
                           sizeof(named));
            /* What has been read so far is shown BEFORE the name becomes
               anything, so the space is not in it. */
            report_runaway_list(engine, "definition", NULL, "->", replacement);
            /* THE NAME ITSELF BECOMES A SPACE, which is why a line reading
               `a\lz' gives `a ' and one reading `\lz more' gives a single
               space. */
            hstex_token ending =
                hstex_token_character((uint8_t)HSTEX_CAT_SPACE, (uint8_t)' ');
            if (vector_push(replacement, ending, error, error_capacity) != 0) {
                engine->reading_mouth = previous_reading;
                engine->reading_stream = previous_stream;
                engine->reading_base = previous_base;
                hstex_mouth_destroy(&mouth);
                free(buffer);
                return -1;
            }
            /* AND A `}' IS PUT IN BEHIND IT, which is read like any other:
               where the line has a `{' still open the brace closes it and the
               line is read on, and where it has not the line is given up.
               The reference puts it on the input stack, where the fault's
               context names it, and reads it back from there; HSTeX reads
               the line beside the stack, so the frame stands only for as
               long as the fault is being drawn. */
            hstex_token closer = hstex_token_character(
                (uint8_t)HSTEX_CAT_END_GROUP, (uint8_t)'}');
            bool drawn = hstex_source_push_tokens(&engine->sources, &closer,
                                                  1U, location, NULL, 0U) == 0;
            if (drawn) {
                hstex_source_name_top(&engine->sources,
                                      (uint8_t)HSTEX_TOKEN_SOURCE_INSERTED,
                                      0U);
            }
            tex_error(engine, help,
                      "Forbidden control sequence found while scanning "
                      "definition of %s",
                      named);
            if (drawn) {
                hstex_source_pop(&engine->sources);
            }
            token = closer;
        }
        if (token_is_category(token, HSTEX_CAT_BEGIN_GROUP)) {
            ++*balance;
        } else if (token_is_category(token, HSTEX_CAT_END_GROUP)) {
            if (*balance == 0) {
                draining = true;
                continue;
            }
            --*balance;
        }
        if (vector_push(replacement, token, error, error_capacity) != 0) {
            engine->reading_mouth = previous_reading;
            engine->reading_stream = previous_stream;
            engine->reading_base = previous_base;
            hstex_mouth_destroy(&mouth);
            free(buffer);
            return -1;
        }
    }
    engine->reading_mouth = previous_reading;
    engine->reading_stream = previous_stream;
    engine->reading_base = previous_base;
    hstex_mouth_destroy(&mouth);
    free(buffer);
    return 0;
}

static int define_other_read_line(struct hstex_engine *engine,
                                  hstex_cs_id target, const uint8_t *line,
                                  size_t length, char *error,
                                  size_t error_capacity)
{
    while (length != 0U && line[length - 1U] == (uint8_t)' ') {
        --length;
    }
    struct hstex_token_vector replacement = {0};
    for (size_t index = 0U; index < length; ++index) {
        uint8_t category = line[index] == (uint8_t)' '
                               ? (uint8_t)HSTEX_CAT_SPACE
                               : (uint8_t)HSTEX_CAT_OTHER;
        if (vector_push(&replacement,
                        hstex_token_character(category, line[index]), error,
                        error_capacity) != 0) {
            vector_destroy(&replacement);
            return -1;
        }
    }
    int32_t end_line =
        engine->integer_parameters[HSTEX_INTEGER_END_LINE_CHARACTER];
    if (end_line >= 0 && end_line <= 255) {
        uint8_t character = (uint8_t)end_line;
        uint8_t category = character == (uint8_t)' '
                               ? (uint8_t)HSTEX_CAT_SPACE
                               : (uint8_t)HSTEX_CAT_OTHER;
        if (vector_push(&replacement,
                        hstex_token_character(category, character), error,
                        error_capacity) != 0) {
            vector_destroy(&replacement);
            return -1;
        }
    }
    return define_read_tokens(engine, target, &replacement, error,
                              error_capacity);
}

static int execute_read_kind(struct hstex_engine *engine, bool other_catcodes,
                             char *error, size_t error_capacity)
{
    int32_t stream = 0;
    if (scan_read_stream_number(engine, &stream, error, error_capacity) != 0 ||
        scan_keyword_to(engine, error, error_capacity) != 0) {
        return -1;
    }
    hstex_cs_id target = 0U;
    if (scan_definition_target(engine, &target, error, error_capacity) != 0) {
        return -1;
    }
    int status = 0;
    struct hstex_token_vector replacement = {0};
    int32_t balance = 0;
    for (;;) {
        char *line = NULL;
        size_t capacity = 0U;
        ssize_t length = -1;
        FILE *source =
            engine->terminal_input == NULL ? stdin : engine->terminal_input;
        if (stream >= 0 && stream < 16 &&
            engine->read_streams[(size_t)stream] != NULL) {
            source = engine->read_streams[(size_t)stream];
        }
        length = getline(&line, &capacity, source);
        bool ended = length < 0;
        if (length < 0) {
            length = 0;
        }
        while (length > 0 &&
               (line[length - 1] == '\n' || line[length - 1] == '\r')) {
            --length;
        }
        if (other_catcodes) {
            status = define_other_read_line(engine, target,
                                            (const uint8_t *)line,
                                            (size_t)length, error,
                                            error_capacity);
            free(line);
            vector_destroy(&replacement);
            engine->pending_global = false;
            engine->pending_macro_flags = 0U;
            return status;
        }
        if (ended) {
            /* THE FILE HAS NO MORE LINES. Where braces are still open the
               reference says so; then, either way, the end of the file
               stands for an empty logical line under the current
               \endlinechar. That line goes on after the fault is reported,
               so what the fault shows does not have it. */
            free(line);
            if (balance > 0) {
                static const char *const help[] = {
                    "This \\read has unbalanced braces.", NULL};
                report_runaway_list(engine, "definition", NULL, "->",
                                    &replacement);
                /* The reference has already begun reading the line that
                   turned out not to be there, so the fault's context names
                   the stream with nothing on it. */
                struct hstex_mouth blank;
                hstex_mouth_init(&blank, NULL, 0U, &engine->lexical_state);
                const struct hstex_mouth *held = engine->reading_mouth;
                int32_t held_stream = engine->reading_stream;
                size_t held_base = engine->reading_base;
                engine->reading_mouth = &blank;
                engine->reading_stream = stream;
                engine->reading_base = engine->sources.count;
                tex_error(engine, help, "File ended within \\read");
                engine->reading_mouth = held;
                engine->reading_stream = held_stream;
                engine->reading_base = held_base;
                hstex_mouth_destroy(&blank);
            }
            engine->reading_stream = stream;
            status = append_read_line(engine, target, &replacement, NULL, 0U,
                                      &balance, error, error_capacity);
            break;
        }
        engine->reading_stream = stream;
        status = append_read_line(engine, target, &replacement,
                                  (const uint8_t *)line, (size_t)length,
                                  &balance, error, error_capacity);
        free(line);
        if (status != 0) {
            break;
        }
        if (balance <= 0) {
            break;
        }
    }
    if (status == 0) {
        status = define_read_tokens(engine, target, &replacement, error,
                                    error_capacity);
    } else {
        vector_destroy(&replacement);
    }
    engine->pending_global = false;
    engine->pending_macro_flags = 0U;
    return status;
}

static int execute_read(struct hstex_engine *engine, char *error,
                        size_t error_capacity)
{
    return execute_read_kind(engine, false, error, error_capacity);
}

static int execute_read_line(struct hstex_engine *engine, char *error,
                             size_t error_capacity)
{
    return execute_read_kind(engine, true, error, error_capacity);
}

static int scan_if_eof(struct hstex_engine *engine, char *error,
                       size_t error_capacity)
{
    size_t conditional = 0U;
    if (push_conditional(engine, &conditional, error, error_capacity) != 0) {
        return -1;
    }
    int32_t stream = 0;
    if (scan_four_bit_int(engine, &stream, error, error_capacity) != 0) {
        engine->conditional_count = conditional;
        return -1;
    }
    bool at_end = stream < 0 || stream >= 16 ||
                  engine->read_streams[(size_t)stream] == NULL ||
                  feof(engine->read_streams[(size_t)stream]) != 0;
    return finish_conditional(engine, conditional, at_end, error,
                              error_capacity);
}

static int scan_if_defined(struct hstex_engine *engine, char *error,
                           size_t error_capacity)
{
    size_t conditional = 0U;
    if (push_conditional(engine, &conditional, error, error_capacity) != 0) {
        return -1;
    }
    hstex_token subject = 0U;
    struct hstex_source_location location;
    if (raw_next(engine, &subject, &location, error, error_capacity) !=
        HSTEX_ENGINE_TOKEN) {
        engine->conditional_count = conditional;
        return set_error(error, error_capacity, "end of input in ifdefined");
    }
    bool defined = hstex_token_is_control_sequence(subject) &&
                   hstex_engine_meaning(
                       engine, hstex_token_control_sequence_id(subject))
                           ->command != HSTEX_COMMAND_UNDEFINED;
    return finish_conditional(engine, conditional, defined, error,
                              error_capacity);
}

static int scan_if_cs_name(struct hstex_engine *engine, char *error,
                           size_t error_capacity)
{
    size_t conditional = 0U;
    if (push_conditional(engine, &conditional, error, error_capacity) != 0) {
        return -1;
    }
    uint8_t *name = NULL;
    size_t name_count = 0U;
    if (scan_cs_name_bytes(engine, &name, &name_count, error, error_capacity) !=
        0) {
        engine->conditional_count = conditional;
        return -1;
    }
    hstex_cs_id identifier = 0U;
    bool defined =
        hstex_symbol_find(&engine->lexical_state.symbols, HSTEX_SYMBOL_REGULAR,
                          name, name_count, &identifier) == 1 &&
        hstex_engine_meaning(engine, identifier)->command !=
            HSTEX_COMMAND_UNDEFINED;
    release_cs_name(engine, name);
    return finish_conditional(engine, conditional, defined, error,
                              error_capacity);
}

static bool command_starts_conditional(enum hstex_command command)
{
    return command == HSTEX_COMMAND_IF_NUM || command == HSTEX_COMMAND_IF_DIM ||
           command == HSTEX_COMMAND_IF_H_MODE ||
           command == HSTEX_COMMAND_IF_V_MODE ||
           command == HSTEX_COMMAND_IF_M_MODE ||
           command == HSTEX_COMMAND_IF_INNER ||
           command == HSTEX_COMMAND_IF_X ||
           command == HSTEX_COMMAND_IF_CHAR || command == HSTEX_COMMAND_IF_CAT ||
           command == HSTEX_COMMAND_IF_ODD ||
           command == HSTEX_COMMAND_IF_CASE ||
           command == HSTEX_COMMAND_IF_TRUE ||
           command == HSTEX_COMMAND_IF_FALSE ||
           command == HSTEX_COMMAND_IF_EOF ||
           command == HSTEX_COMMAND_IF_DEFINED ||
           command == HSTEX_COMMAND_IF_FONT_CHAR ||
           command == HSTEX_COMMAND_IF_BOX ||
           command == HSTEX_COMMAND_IF_CS_NAME;
}

/* Two stored token lists mean the same thing when they hold the same tokens.
   A token handed out of a token register carries a one-shot mark saying it
   has already been through expansion, and that mark is no part of what the
   token means: \\def\\P{#1} against \\the\\toks0 stores a marked character
   where \\def\\N{a} stores a plain one, and \\ifx must still call them equal.
   See docs/DECISIONS.md, a-token-out-of-a-register. */
static bool stored_token_lists_equal(const hstex_token *left,
                                     const hstex_token *right, size_t count)
{
    if (count == 0U) {
        return true;
    }
    if (memcmp(left, right, count * sizeof(*left)) == 0) {
        return true;
    }
    for (size_t index = 0U; index < count; ++index) {
        if (normalize_one_shot_token(left[index]) !=
            normalize_one_shot_token(right[index])) {
            return false;
        }
    }
    return true;
}

static bool meanings_equal(const struct hstex_engine *engine,
                           const struct hstex_meaning *left,
                           const struct hstex_meaning *right)
{
    if (left->command != right->command) {
        return false;
    }
    switch (left->command) {
    case HSTEX_COMMAND_MACRO: {
        uint32_t left_identifier = left->value.macro_identifier;
        uint32_t right_identifier = right->value.macro_identifier;
        if (left_identifier == 0U || right_identifier == 0U ||
            (size_t)left_identifier > engine->macro_count ||
            (size_t)right_identifier > engine->macro_count) {
            return left_identifier == right_identifier;
        }
        const struct hstex_macro *left_macro =
            &engine->macros[left_identifier - 1U];
        const struct hstex_macro *right_macro =
            &engine->macros[right_identifier - 1U];
        return left_macro->flags == right_macro->flags &&
               left_macro->parameter_count == right_macro->parameter_count &&
               left_macro->parameter_count_tokens ==
                   right_macro->parameter_count_tokens &&
               left_macro->replacement_count == right_macro->replacement_count &&
               stored_token_lists_equal(left_macro->parameter_text,
                                        right_macro->parameter_text,
                                        left_macro->parameter_count_tokens) &&
               stored_token_lists_equal(left_macro->replacement,
                                        right_macro->replacement,
                                        left_macro->replacement_count);
    }
    case HSTEX_COMMAND_TOKEN_ALIAS:
        return left->value.token == right->value.token;
    case HSTEX_COMMAND_UNDEFINED:
        return true;
    default:
        /* A whole family of primitives shares one command and is told apart
           by its subtype, so the subtype is part of the meaning: this is what
           keeps \hfil unequal to \hfill and \mathbin unequal to \mathpunct.
           A primitive with no subtype carries zero and still compares equal.
           LaTeX's \DeclareMathSymbol asks exactly this question. */
        return left->value.integer == right->value.integer;
    }
}

/* A token \noexpand marked comes through as ITSELF when its meaning cannot
   be expanded -- a \chardef, a register, a primitive, \relax -- and as
   something \relax-like but not \relax when it can. So
   `\expandafter\ifx\noexpand\x\x' is true exactly when \x is
   unexpandable, which is how expl3 tells one of its variables from a macro
   in a V-expansion. */
static hstex_token normalize_noexpand_for_comparison(
    const struct hstex_engine *engine, hstex_token token)
{
    if (!hstex_token_is_frozen_control_sequence(token)) {
        return token;
    }
    const struct hstex_meaning *meaning =
        hstex_engine_meaning(engine, hstex_token_control_sequence_id(token));
    if (command_is_expandable(meaning->command) ||
        meaning->command == HSTEX_COMMAND_UNDEFINED) {
        return token;
    }
    return hstex_token_control_sequence(
        hstex_token_control_sequence_id(token));
}

static bool ifx_tokens_equal(const struct hstex_engine *engine,
                             hstex_token left, hstex_token right)
{
    left = normalize_one_shot_token(left);
    right = normalize_one_shot_token(right);
    left = normalize_noexpand_for_comparison(engine, left);
    right = normalize_noexpand_for_comparison(engine, right);
    /* A control sequence \\let to a character is that character as far as
       \\ifx is concerned; LaTeX's prime machinery turns on it. */
    if (hstex_token_is_control_sequence(left) &&
        hstex_token_is_character(right)) {
        const struct hstex_meaning *meaning = hstex_engine_meaning(
            engine, hstex_token_control_sequence_id(left));
        return meaning->command == HSTEX_COMMAND_TOKEN_ALIAS &&
               meaning->value.token == right;
    }
    if (hstex_token_is_control_sequence(right) &&
        hstex_token_is_character(left)) {
        const struct hstex_meaning *meaning = hstex_engine_meaning(
            engine, hstex_token_control_sequence_id(right));
        return meaning->command == HSTEX_COMMAND_TOKEN_ALIAS &&
               meaning->value.token == left;
    }
    if (hstex_token_is_character(left) || hstex_token_is_character(right)) {
        return left == right;
    }
    if (!hstex_token_is_control_sequence(left) ||
        !hstex_token_is_control_sequence(right)) {
        return false;
    }
    return meanings_equal(
        engine,
        hstex_engine_meaning(engine, hstex_token_control_sequence_id(left)),
        hstex_engine_meaning(engine, hstex_token_control_sequence_id(right)));
}

static int skip_conditional(struct hstex_engine *engine, size_t target,
                            bool stop_at_else, char *error,
                            size_t error_capacity)
{
    if (target >= engine->conditional_count) {
        return set_error(error, error_capacity,
                         "conditional skip target is not active");
    }
    size_t active_nested = engine->conditional_count - target - 1U;
    size_t skipped_depth = 0U;
    for (;;) {
        /* Nothing but a control sequence can end the skip, so where the
           skipped text stands in a list already it is read where it stands:
           the corpus passes over 58.5 million control sequences this way,
           and asking for each of them costs more than looking at it. */
        hstex_token token = 0U;
        bool found = false;
        /* TeX still obtains every skipped token through its ordinary reader.
           Inside an alignment that is semantic: braces change the entry's
           nesting, and a tab at depth zero can end it. Keep the direct-list
           shortcut only where no alignment counter is active. See
           docs/DECISIONS.md, conditional-skipping-inside-alignments. */
        bool alignment_sensitive = engine->alignment_entry != NULL ||
                                   engine->preamble_nesting != NULL;
        if (!alignment_sensitive && engine->sources.count != 0U) {
            struct hstex_source_frame *frame =
                &engine->sources.frames[engine->sources.count - 1U];
            if (frame->kind == HSTEX_SOURCE_TOKEN_LIST) {
                struct hstex_token_source *source = &frame->value.token_list;
                uint32_t cursor = source->cursor;
                while (cursor < source->count) {
                    hstex_token seen = normalize_unexpanded_control_sequence(
                        source->tokens[cursor]);
                    ++cursor;
                    if (hstex_token_is_control_sequence(seen)) {
                        token = seen;
                        found = true;
                        break;
                    }
                }
                source->cursor = cursor;
            }
        }
        if (!found) {
            struct hstex_source_location location;
            if (raw_next(engine, &token, &location, error, error_capacity) !=
                HSTEX_ENGINE_TOKEN) {
                return set_error(error, error_capacity,
                                 "end of input while skipping a conditional");
            }
            token = normalize_unexpanded_control_sequence(token);
            if (!hstex_token_is_control_sequence(token)) {
                continue;
            }
        }
        if (token_is_outer_macro(engine, token)) {
            if (report_forbidden_in_skipped_text(engine, target, token, error,
                                                 error_capacity) != 0) {
                return -1;
            }
            continue;
        }
        enum hstex_command command =
            hstex_engine_meaning(engine,
                                 hstex_token_control_sequence_id(token))
                ->command;
        if (command_starts_conditional(command)) {
            ++skipped_depth;
        } else if (command == HSTEX_COMMAND_FI) {
            if (skipped_depth != 0U) {
                --skipped_depth;
                continue;
            }
            if (active_nested != 0U) {
                if (engine->conditional_count <= target + 1U) {
                    return set_error(error, error_capacity,
                                     "conditional stack underflow");
                }
                --engine->conditional_count;
                --active_nested;
                continue;
            }
            if (engine->conditional_count != target + 1U) {
                return set_error(error, error_capacity,
                                 "conditional stack mismatch while skipping");
            }
            engine->conditional_count = target;
            return 0;
        } else if (command == HSTEX_COMMAND_ELSE && skipped_depth == 0U) {
            if (active_nested != 0U) {
                struct hstex_conditional *nested =
                    &engine->conditionals[engine->conditional_count - 1U];
                if (nested->else_seen) {
                    continue;
                }
                nested->else_seen = true;
                continue;
            }
            if (!stop_at_else) {
                /* Nothing in skipped text is obeyed or reported, an \else
                   past the first no more than anything else: measured,
                   `\iftrue A\else B\else C\fi' sets the A in silence. */
                continue;
            }
            engine->conditionals[target].else_seen = true;
            return 0;
        }
    }
}

static int skip_case_to_branch(struct hstex_engine *engine, size_t target,
                               int32_t selection, char *error,
                               size_t error_capacity)
{
    if (target >= engine->conditional_count) {
        return set_error(error, error_capacity,
                         "ifcase skip target is not active");
    }
    size_t active_nested = engine->conditional_count - target - 1U;
    size_t skipped_depth = 0U;
    int32_t remaining = selection;
    for (;;) {
        hstex_token token = 0U;
        struct hstex_source_location location;
        if (raw_next(engine, &token, &location, error, error_capacity) !=
            HSTEX_ENGINE_TOKEN) {
            return set_error(error, error_capacity,
                             "end of input while skipping ifcase branches");
        }
        token = normalize_unexpanded_control_sequence(token);
        if (!hstex_token_is_control_sequence(token)) {
            continue;
        }
        if (token_is_outer_macro(engine, token)) {
            if (report_forbidden_in_skipped_text(engine, target, token, error,
                                                 error_capacity) != 0) {
                return -1;
            }
            continue;
        }
        enum hstex_command command =
            hstex_engine_meaning(engine,
                                 hstex_token_control_sequence_id(token))
                ->command;
        if (command_starts_conditional(command)) {
            ++skipped_depth;
            continue;
        }
        if (command == HSTEX_COMMAND_FI) {
            if (skipped_depth != 0U) {
                --skipped_depth;
                continue;
            }
            if (active_nested != 0U) {
                --engine->conditional_count;
                --active_nested;
                continue;
            }
            engine->conditional_count = target;
            return 0;
        }
        if (skipped_depth != 0U || active_nested != 0U) {
            continue;
        }
        if (command == HSTEX_COMMAND_OR && remaining > 0) {
            --remaining;
            if (remaining == 0) {
                engine->conditionals[target].branch_true = true;
                return 0;
            }
            continue;
        }
        if (command == HSTEX_COMMAND_ELSE) {
            engine->conditionals[target].else_seen = true;
            engine->conditionals[target].branch_true = true;
            return 0;
        }
    }
}

/* An \outer macro in skipped text: the reference takes it as a sign the
   \fi was forgotten, inserts one, and reads the macro again. */
static int report_forbidden_in_skipped_text(struct hstex_engine *engine,
                                            size_t target, hstex_token token,
                                            char *error, size_t error_capacity)
{
    static const char *const help[] = {
        "A forbidden control sequence occurred in skipped text.",
        "This kind of error happens when you say `\\if...' and forget",
        "the matching `\\fi'. I've inserted a `\\fi'; this might work.", NULL};
    const struct hstex_conditional *opened = &engine->conditionals[target];
    char named[128] = "\\if";
    if (opened->opener != 0U) {
        describe_token(engine, hstex_token_control_sequence(opened->opener),
                       named, sizeof(named));
    }
    static const uint8_t fi_name[] = "fi";
    hstex_cs_id fi = 0U;
    struct hstex_source_location where = {0};
    if (hstex_symbol_intern(&engine->lexical_state.symbols,
                            HSTEX_SYMBOL_REGULAR, fi_name,
                            sizeof(fi_name) - 1U, &fi, error,
                            error_capacity) != 0 ||
        push_one(engine, token, where, error, error_capacity) != 0) {
        return -1;
    }
    /* The \fi is PUT IN, so it stands in an inserted text of its own; the
       macro that gave it away is put BACK and is read again. */
    hstex_token inserted = hstex_token_control_sequence(fi);
    if (hstex_source_push_tokens(&engine->sources, &inserted, 1U, where, error,
                                 error_capacity) != 0) {
        return -1;
    }
    tex_error(engine, help,
              "Incomplete %s; all text was ignored after line %u", named,
              (unsigned int)opened->line);
    return 0;
}

static int skip_case_remainder(struct hstex_engine *engine, size_t target,
                               char *error, size_t error_capacity)
{
    if (target >= engine->conditional_count) {
        return set_error(error, error_capacity,
                         "ifcase remainder target is not active");
    }
    size_t active_nested = engine->conditional_count - target - 1U;
    size_t skipped_depth = 0U;
    for (;;) {
        hstex_token token = 0U;
        struct hstex_source_location location;
        if (raw_next(engine, &token, &location, error, error_capacity) !=
            HSTEX_ENGINE_TOKEN) {
            return set_error(error, error_capacity,
                             "end of input while skipping ifcase remainder");
        }
        token = normalize_unexpanded_control_sequence(token);
        if (!hstex_token_is_control_sequence(token)) {
            continue;
        }
        if (token_is_outer_macro(engine, token)) {
            if (report_forbidden_in_skipped_text(engine, target, token, error,
                                                 error_capacity) != 0) {
                return -1;
            }
            continue;
        }
        enum hstex_command command =
            hstex_engine_meaning(engine,
                                 hstex_token_control_sequence_id(token))
                ->command;
        if (command_starts_conditional(command)) {
            ++skipped_depth;
        } else if (command == HSTEX_COMMAND_FI) {
            if (skipped_depth != 0U) {
                --skipped_depth;
                continue;
            }
            if (active_nested != 0U) {
                --engine->conditional_count;
                --active_nested;
                continue;
            }
            engine->conditional_count = target;
            return 0;
        } else if (command == HSTEX_COMMAND_ELSE && skipped_depth == 0U &&
                   active_nested == 0U) {
            if (engine->conditionals[target].else_seen) {
                return set_error(error, error_capacity,
                                 "second else in one ifcase");
            }
            engine->conditionals[target].else_seen = true;
        }
    }
}

/* The innermost file being read, and the line reached in it. */
static const char *current_source_line(const struct hstex_engine *engine,
                                       uint32_t *line)
{
    /* The stack says where its innermost file stands, so this is a look
       rather than a walk: every definition and every conditional asks, and
       the corpus makes seven million of the one and more of the other. */
    size_t top = engine->sources.file_top;
    if (top != 0U && top <= engine->sources.count) {
        const struct hstex_source_frame *frame =
            &engine->sources.frames[top - 1U];
        *line = frame->value.file->mouth.line_number;
        return frame->value.file->path;
    }
    *line = 0U;
    return "<no file>";
}

static int push_conditional(struct hstex_engine *engine, size_t *index,
                            char *error, size_t error_capacity)
{
    if (reserve_conditionals(engine, engine->conditional_count + 1U, error,
                             error_capacity) != 0) {
        return -1;
    }
    *index = engine->conditional_count++;
    struct hstex_conditional *entry = &engine->conditionals[*index];
    entry->branch_true = false;
    entry->else_seen = false;
    entry->case_conditional = false;
    entry->negate = engine->negate_next_conditional;
    entry->evaluated = false;
    entry->origin = current_source_line(engine, &entry->line);
    entry->opener = engine->conditional_opener;
    engine->negate_next_conditional = false;
    return 0;
}

/* Put the token back and stand a \relax in front of it. */
static int push_relax_before(struct hstex_engine *engine, hstex_token token,
                             struct hstex_source_location location, char *error,
                             size_t error_capacity)
{
    hstex_cs_id relax = 0U;
    if (hstex_symbol_find(&engine->lexical_state.symbols, HSTEX_SYMBOL_REGULAR,
                          (const uint8_t *)"relax", 5U, &relax) != 1) {
        return set_error(error, error_capacity, "relax is not defined");
    }
    /* Each goes back ON ITS OWN, the token first and the \relax over it:
       the reference backs them up one at a time, so the frame the \relax
       stood in is spent and gone by the time anything below it is shown. */
    if (push_one(engine, token, location, error, error_capacity) != 0) {
        return -1;
    }
    return push_one(engine, hstex_token_control_sequence(relax), location,
                    error, error_capacity);
}

/* \else, \or, and \fi met while the innermost conditional is still scanning
   its own test stand for \relax: they terminate whatever is being scanned and
   stay in the input for the conditional to find afterwards. `\ifnum ...>20\else`
   with no space between the number and \else depends on this. */
static bool conditional_test_pending(const struct hstex_engine *engine)
{
    return engine->conditional_count != 0U &&
           !engine->conditionals[engine->conditional_count - 1U].evaluated;
}

static int finish_conditional(struct hstex_engine *engine, size_t index,
                              bool condition, char *error,
                              size_t error_capacity)
{
    if (index >= engine->conditional_count) {
        return set_error(error, error_capacity,
                         "conditional disappeared while scanning its test");
    }
    if (engine->conditionals[index].negate) {
        condition = !condition;
    }
    engine->conditionals[index].evaluated = true;
    engine->conditionals[index].branch_true = condition;
    /* The trace says which way a conditional went, on a line of its own
       after the \if that asked. */
    if (engine->integer_parameters[HSTEX_INTEGER_TRACING_COMMANDS] > 1) {
        trace_words(engine, condition ? "true" : "false");
    }
    if (!condition) {
        return skip_conditional(engine, index, true, error, error_capacity);
    }
    return 0;
}

static int start_conditional(struct hstex_engine *engine, bool condition,
                             char *error, size_t error_capacity)
{
    size_t conditional = 0U;
    if (push_conditional(engine, &conditional, error, error_capacity) != 0) {
        return -1;
    }
    return finish_conditional(engine, conditional, condition, error,
                              error_capacity);
}

static int scan_if_num(struct hstex_engine *engine, char *error,
                       size_t error_capacity)
{
    size_t conditional = 0U;
    if (push_conditional(engine, &conditional, error, error_capacity) != 0) {
        return -1;
    }
    int32_t left = 0;
    int32_t right = 0;
    hstex_token relation = 0U;
    struct hstex_source_location location;
    if (scan_integer(engine, &left, error, error_capacity) != 0) {
        engine->conditional_count = conditional;
        return -1;
    }
    enum hstex_engine_result result = expanded_next_non_space(
        engine, &relation, &location, error, error_capacity);
    if (result != HSTEX_ENGINE_TOKEN) {
        engine->conditional_count = conditional;
        if (result == HSTEX_ENGINE_ERROR) {
            return -1;
        }
        return set_error(error, error_capacity,
                         "end of input while scanning an ifnum relation");
    }
    /* The relation is looked at before the right-hand side is scanned,
       because that is the order the reference reports in: a token that is
       none of the three draws "Missing = inserted" and is read again as
       the start of the right-hand side. */
    if (!token_is_other_character(relation, (uint8_t)'<') &&
        !token_is_other_character(relation, (uint8_t)'=') &&
        !token_is_other_character(relation, (uint8_t)'>')) {
        static const char *const help[] = {
            "I was expecting to see `<', `=', or `>'. Didn't.", NULL};
        if (push_one(engine, relation, location, error, error_capacity) != 0) {
            engine->conditional_count = conditional;
            return -1;
        }
        relation = hstex_token_character((uint8_t)HSTEX_CAT_OTHER,
                                         (uint8_t)'=');
        tex_error(engine, help, "Missing = inserted for %s", "\\ifnum");
    }
    if (scan_integer(engine, &right, error, error_capacity) != 0) {
        engine->conditional_count = conditional;
        return -1;
    }
    bool condition;
    if (token_is_other_character(relation, (uint8_t)'<')) {
        condition = left < right;
    } else if (token_is_other_character(relation, (uint8_t)'=')) {
        condition = left == right;
    } else if (token_is_other_character(relation, (uint8_t)'>')) {
        condition = left > right;
    } else {
        condition = false;
    }
    return finish_conditional(engine, conditional, condition, error,
                              error_capacity);
}

static int scan_if_dim(struct hstex_engine *engine, char *error,
                       size_t error_capacity)
{
    size_t conditional = 0U;
    if (push_conditional(engine, &conditional, error, error_capacity) != 0) {
        return -1;
    }
    int32_t left = 0;
    int32_t right = 0;
    hstex_token relation = 0U;
    struct hstex_source_location location;
    if (scan_dimension(engine, &left, error, error_capacity) != 0) {
        engine->conditional_count = conditional;
        return -1;
    }
    enum hstex_engine_result result = expanded_next_non_space(
        engine, &relation, &location, error, error_capacity);
    if (result != HSTEX_ENGINE_TOKEN) {
        engine->conditional_count = conditional;
        if (result == HSTEX_ENGINE_ERROR) {
            return -1;
        }
        return set_error(error, error_capacity,
                         "end of input while scanning an ifdim relation");
    }
    /* The relation is looked at before the right-hand side is scanned,
       because that is the order the reference reports in: a token that is
       none of the three draws "Missing = inserted" and is read again as
       the start of the right-hand side. */
    if (!token_is_other_character(relation, (uint8_t)'<') &&
        !token_is_other_character(relation, (uint8_t)'=') &&
        !token_is_other_character(relation, (uint8_t)'>')) {
        static const char *const help[] = {
            "I was expecting to see `<', `=', or `>'. Didn't.", NULL};
        if (push_one(engine, relation, location, error, error_capacity) != 0) {
            engine->conditional_count = conditional;
            return -1;
        }
        relation = hstex_token_character((uint8_t)HSTEX_CAT_OTHER,
                                         (uint8_t)'=');
        tex_error(engine, help, "Missing = inserted for %s", "\\ifdim");
    }
    if (scan_dimension(engine, &right, error, error_capacity) != 0) {
        engine->conditional_count = conditional;
        return -1;
    }
    bool condition;
    if (token_is_other_character(relation, (uint8_t)'<')) {
        condition = left < right;
    } else if (token_is_other_character(relation, (uint8_t)'=')) {
        condition = left == right;
    } else if (token_is_other_character(relation, (uint8_t)'>')) {
        condition = left > right;
    } else {
        condition = false;
    }
    return finish_conditional(engine, conditional, condition, error,
                              error_capacity);
}

static int scan_if_x(struct hstex_engine *engine, char *error,
                     size_t error_capacity)
{
    size_t conditional = 0U;
    if (push_conditional(engine, &conditional, error, error_capacity) != 0) {
        return -1;
    }
    hstex_token left = 0U;
    hstex_token right = 0U;
    struct hstex_source_location location;
    if (raw_next(engine, &left, &location, error, error_capacity) !=
            HSTEX_ENGINE_TOKEN ||
        raw_next(engine, &right, &location, error, error_capacity) !=
            HSTEX_ENGINE_TOKEN) {
        engine->conditional_count = conditional;
        return set_error(error, error_capacity, "end of input in ifx");
    }
    return finish_conditional(engine, conditional,
                              ifx_tokens_equal(engine, left, right), error,
                              error_capacity);
}

static int scan_if_odd(struct hstex_engine *engine, char *error,
                       size_t error_capacity)
{
    size_t conditional = 0U;
    if (push_conditional(engine, &conditional, error, error_capacity) != 0) {
        return -1;
    }
    int32_t value = 0;
    if (scan_integer(engine, &value, error, error_capacity) != 0) {
        engine->conditional_count = conditional;
        return set_error(error, error_capacity, "invalid ifodd integer");
    }
    return finish_conditional(engine, conditional, value % 2 != 0, error,
                              error_capacity);
}

/* \iffontchar asks whether the font defines a character at all. */
static int scan_if_font_char(struct hstex_engine *engine, char *error,
                             size_t error_capacity)
{
    size_t conditional = 0U;
    if (push_conditional(engine, &conditional, error, error_capacity) != 0) {
        return -1;
    }
    uint32_t identifier = 0U;
    int32_t code = 0;
    if (scan_font_identifier(engine, &identifier, error, error_capacity) != 0 ||
        scan_integer(engine, &code, error, error_capacity) != 0) {
        engine->conditional_count = conditional;
        return -1;
    }
    if (code < 0 || (size_t)code >= HSTEX_FONT_CHARACTER_COUNT) {
        engine->conditional_count = conditional;
        return set_error(error, error_capacity, "bad character code (%d)",
                         code);
    }
    const struct hstex_font *font = font_by_identifier(engine, identifier);
    bool defined = font != NULL && font->characters != NULL &&
                   font->characters[(size_t)code].tag >= 0;
    return finish_conditional(engine, conditional, defined, error,
                              error_capacity);
}

/* \ifhbox, \ifvbox and \ifvoid each ask one question about a register. */
static int scan_if_box(struct hstex_engine *engine, int32_t subtype,
                       char *error, size_t error_capacity)
{
    size_t conditional = 0U;
    if (push_conditional(engine, &conditional, error, error_capacity) != 0) {
        return -1;
    }
    int32_t index = 0;
    if (scan_integer(engine, &index, error, error_capacity) != 0 || index < 0 ||
        (size_t)index >= engine->count_capacity) {
        engine->conditional_count = conditional;
        return set_error(error, error_capacity,
                         "box register %d is outside 0..%zu", index,
                         engine->count_capacity - 1U);
    }
    enum hstex_box_kind kind = engine->boxes[(size_t)index].kind;
    bool condition = subtype == (int32_t)HSTEX_IF_BOX_HORIZONTAL
                         ? kind == HSTEX_BOX_HLIST
                         : subtype == (int32_t)HSTEX_IF_BOX_VERTICAL
                               ? kind == HSTEX_BOX_VLIST
                               : kind == HSTEX_BOX_VOID;
    return finish_conditional(engine, conditional, condition, error,
                              error_capacity);
}

static int scan_if_case(struct hstex_engine *engine, char *error,
                        size_t error_capacity)
{
    size_t conditional = 0U;
    if (push_conditional(engine, &conditional, error, error_capacity) != 0) {
        return -1;
    }
    engine->conditionals[conditional].case_conditional = true;
    int32_t selection = 0;
    if (scan_integer(engine, &selection, error, error_capacity) != 0) {
        engine->conditional_count = conditional;
        /* Keep the scanner's own diagnosis rather than masking it. */
        return -1;
    }
    engine->conditionals[conditional].evaluated = true;
    /* An \ifcase says which case it took rather than true or false. */
    if (engine->integer_parameters[HSTEX_INTEGER_TRACING_COMMANDS] > 1) {
        char said[64];
        (void)snprintf(said, sizeof(said), "case %d", (int)selection);
        trace_words(engine, said);
    }
    if (selection == 0) {
        engine->conditionals[conditional].branch_true = true;
        return 0;
    }
    return skip_case_to_branch(engine, conditional, selection, error,
                               error_capacity);
}

/* A TOKEN \noexpand HELD BACK stands for what it MEANS unless what it means
   is expandable -- and one that is expandable stands for nothing at all,
   EXCEPT where the token is an ACTIVE CHARACTER, which stands for that
   character. `\if\string~\noexpand~' is true. See docs/DECISIONS.md,
   what-a-noexpand-holds-back. */
static bool held_back_active_character(const struct hstex_engine *engine,
                                       hstex_token token, bool held,
                                       uint8_t *character)
{
    if (!held || !hstex_token_is_control_sequence(token)) {
        return false;
    }
    hstex_cs_id identifier = hstex_token_control_sequence_id(token);
    const struct hstex_meaning *meaning =
        hstex_engine_meaning(engine, identifier);
    if (!command_is_expandable(meaning->command) &&
        meaning->command != HSTEX_COMMAND_UNDEFINED) {
        return false;
    }
    enum hstex_symbol_kind kind = HSTEX_SYMBOL_REGULAR;
    const uint8_t *name = NULL;
    size_t length = 0U;
    if (hstex_symbol_name(&((struct hstex_engine *)engine)
                               ->lexical_state.symbols,
                          identifier, &kind, &name, &length) != 0 ||
        kind != HSTEX_SYMBOL_ACTIVE || length != 1U || name == NULL) {
        return false;
    }
    *character = name[0];
    return true;
}

static int if_character_code(const struct hstex_engine *engine,
                             hstex_token token, bool held)
{
    uint8_t active = 0U;
    if (held_back_active_character(engine, token, held, &active)) {
        return (int)active;
    }
    if (hstex_token_is_character(token)) {
        return (int)hstex_token_character_code(token);
    }
    if (!hstex_token_is_control_sequence(token)) {
        return 256;
    }
    const struct hstex_meaning *meaning = hstex_engine_meaning(
        engine, hstex_token_control_sequence_id(token));
    if (meaning->command == HSTEX_COMMAND_CHAR_GIVEN &&
        meaning->value.integer >= 0 && meaning->value.integer <= 255) {
        return (int)meaning->value.integer;
    }
    if (meaning->command == HSTEX_COMMAND_TOKEN_ALIAS &&
        hstex_token_is_character(meaning->value.token)) {
        return (int)hstex_token_character_code(meaning->value.token);
    }
    return 256;
}

static int scan_if_char(struct hstex_engine *engine, char *error,
                        size_t error_capacity)
{
    size_t conditional = 0U;
    if (push_conditional(engine, &conditional, error, error_capacity) != 0) {
        return -1;
    }
    hstex_token left = 0U;
    hstex_token right = 0U;
    /* \if reads its two operands the same way \ifcat does, undefined
       control sequences and all. */
    bool left_held = false;
    bool right_held = false;
    if (next_conditional_operand(engine, &left_held, &left, error,
                                 error_capacity) != 0 ||
        next_conditional_operand(engine, &right_held, &right, error,
                                 error_capacity) != 0) {
        engine->conditional_count = conditional;
        return -1;
    }
    return finish_conditional(engine, conditional,
                              if_character_code(engine, left, left_held) ==
                                  if_character_code(engine, right, right_held),
                              error, error_capacity);
}

static int next_conditional_operand(struct hstex_engine *engine, bool *held,
                                    hstex_token *token, char *error,
                                    size_t error_capacity)
{
    struct hstex_source_location location;
    *held = false;
    /* An undefined control sequence met while expanding is reported and
       GONE -- "I'll forget about whatever was undefined" -- so the operand
       is whatever follows it, not a \relax standing in its place.
       Measured: `\ifcat\missing\relax T\else F\fi' reads \relax and T
       as its two operands and comes out false. */
    for (;;) {
        if (hstex_engine_next_expanded(engine, token, &location, error,
                                       error_capacity) != HSTEX_ENGINE_TOKEN) {
            return set_error(error, error_capacity,
                             "end of input in a conditional");
        }
        if (engine->returned_unexpanded ||
            !hstex_token_is_control_sequence(*token) ||
            hstex_engine_meaning(engine,
                                 hstex_token_control_sequence_id(*token))
                    ->command != HSTEX_COMMAND_UNDEFINED) {
            *held = engine->returned_unexpanded;
            return 0;
        }
        report_undefined_control_sequence(engine);
    }
}

static int if_category_code(const struct hstex_engine *engine,
                            hstex_token token, bool held)
{
    uint8_t active = 0U;
    if (held_back_active_character(engine, token, held, &active)) {
        return (int)HSTEX_CAT_ACTIVE;
    }
    if (hstex_token_is_character(token)) {
        return (int)hstex_token_category(token);
    }
    if (hstex_token_is_control_sequence(token)) {
        const struct hstex_meaning *meaning = hstex_engine_meaning(
            engine, hstex_token_control_sequence_id(token));
        if (meaning->command == HSTEX_COMMAND_TOKEN_ALIAS &&
            hstex_token_is_character(meaning->value.token)) {
            return (int)hstex_token_category(meaning->value.token);
        }
    }
    return 16;
}

static int scan_if_cat(struct hstex_engine *engine, char *error,
                       size_t error_capacity)
{
    size_t conditional = 0U;
    if (push_conditional(engine, &conditional, error, error_capacity) != 0) {
        return -1;
    }
    hstex_token left = 0U;
    hstex_token right = 0U;
    bool left_held = false;
    bool right_held = false;
    if (next_conditional_operand(engine, &left_held, &left, error,
                                 error_capacity) != 0 ||
        next_conditional_operand(engine, &right_held, &right, error,
                                 error_capacity) != 0) {
        engine->conditional_count = conditional;
        return -1;
    }
    return finish_conditional(
        engine, conditional,
        if_category_code(engine, left, left_held) ==
            if_category_code(engine, right, right_held),
        error,
        error_capacity);
}

/* What closes the group now open, or a brace when none is. */
static enum hstex_group_kind current_group_kind(
    const struct hstex_engine *engine)
{
    if (engine->group_level == 0U ||
        (size_t)engine->group_level > engine->group_kind_capacity) {
        return HSTEX_GROUP_BRACE;
    }
    return (enum hstex_group_kind)
        engine->group_kinds[engine->group_level - 1U];
}

static const char *group_closer_name(enum hstex_group_kind kind)
{
    switch (kind) {
    case HSTEX_GROUP_SEMI_SIMPLE:
        return "\\endgroup";
    case HSTEX_GROUP_MATH_SHIFT:
        return "$";
    default:
        return "}";
    }
}

/* Whether a command assigns. The reference lets an alignment that filled a
   display be followed by assignments and \relax and nothing else before the
   $$ that closes it, so this is the list of what may stand there --
   measured, command by command, against pdftex: every assignment is
   admitted, including the prefixes, \parshape, \textfont, \patterns and
   the interaction modes, while \message, \mark, \penalty, \unskip,
   \showthe, \lowercase, \ignorespaces, \setlanguage, \afterassignment
   and \aftergroup are not. See tests/trip/probes,
   what-may-follow-a-display-alignment. */
static bool command_assigns(enum hstex_command command)
{
    switch (command) {
    case HSTEX_COMMAND_ADVANCE:
    case HSTEX_COMMAND_BOX_DIMEN:
    case HSTEX_COMMAND_CAT_CODE:
    case HSTEX_COMMAND_CHAR_DEF:
    case HSTEX_COMMAND_COUNT:
    case HSTEX_COMMAND_COUNT_DEF:
    case HSTEX_COMMAND_COUNT_REGISTER:
    case HSTEX_COMMAND_DEF:
    case HSTEX_COMMAND_DEL_CODE:
    case HSTEX_COMMAND_DIMEN:
    case HSTEX_COMMAND_DIMEN_DEF:
    case HSTEX_COMMAND_DIMEN_PARAMETER:
    case HSTEX_COMMAND_DIMEN_REGISTER:
    case HSTEX_COMMAND_DIVIDE:
    case HSTEX_COMMAND_EDEF:
    case HSTEX_COMMAND_FONT:
    case HSTEX_COMMAND_FONT_CHAR_CODE:
    case HSTEX_COMMAND_FONT_DIMEN:
    case HSTEX_COMMAND_FONT_GIVEN:
    case HSTEX_COMMAND_FUTURE_LET:
    case HSTEX_COMMAND_GDEF:
    case HSTEX_COMMAND_GLOBAL:
    case HSTEX_COMMAND_GLUE_PARAMETER:
    case HSTEX_COMMAND_HYPHENATION:
    case HSTEX_COMMAND_HYPHEN_CHAR:
    case HSTEX_COMMAND_INTEGER_PARAMETER:
    case HSTEX_COMMAND_INTERACTION_MODE:
    case HSTEX_COMMAND_LC_CODE:
    case HSTEX_COMMAND_LET:
    case HSTEX_COMMAND_LONG:
    case HSTEX_COMMAND_MATH_CHAR_DEF:
    case HSTEX_COMMAND_MATH_CODE:
    case HSTEX_COMMAND_MATH_FONT:
    case HSTEX_COMMAND_MUGLUE_PARAMETER:
    case HSTEX_COMMAND_MULTIPLY:
    case HSTEX_COMMAND_MUSKIP:
    case HSTEX_COMMAND_MUSKIP_DEF:
    case HSTEX_COMMAND_MUSKIP_REGISTER:
    case HSTEX_COMMAND_OUTER:
    case HSTEX_COMMAND_PAGE_DIMEN:
    case HSTEX_COMMAND_PAGE_INTEGER:
    case HSTEX_COMMAND_PAR_SHAPE:
    case HSTEX_COMMAND_PATTERNS:
    case HSTEX_COMMAND_PREV_DEPTH:
    case HSTEX_COMMAND_PREV_GRAF:
    case HSTEX_COMMAND_PROTECTED:
    case HSTEX_COMMAND_READ:
    case HSTEX_COMMAND_READ_LINE:
    case HSTEX_COMMAND_SET_BOX:
    case HSTEX_COMMAND_SF_CODE:
    case HSTEX_COMMAND_SKEW_CHAR:
    case HSTEX_COMMAND_SKIP:
    case HSTEX_COMMAND_SKIP_DEF:
    case HSTEX_COMMAND_SKIP_REGISTER:
    case HSTEX_COMMAND_SPACE_FACTOR:
    case HSTEX_COMMAND_TOKEN_PARAMETER:
    case HSTEX_COMMAND_TOKS:
    case HSTEX_COMMAND_TOKS_DEF:
    case HSTEX_COMMAND_TOKS_REGISTER:
    case HSTEX_COMMAND_UC_CODE:
    case HSTEX_COMMAND_XDEF:
        return true;
    default:
        return false;
    }
}

/* The reference closes a group that a command cannot live in: it inserts
   the group's own closing token, says which one, and reads the command
   again. The log shows the closer as <inserted text>.

   Measured: `$$\begingroup\halign{...}' says "Missing \endgroup inserted"
   and then obeys the \halign; `$\begingroup x$' says the same for the $.
   trip line 250 is the first of these. */
/* A vertical command met inside a formula. The reference puts a $ in front
   of it and reads it again, so the formula closes and the command does what
   it came to do. Measured: \par, \vskip, \hrule, \unvbox and \end all
   draw "Missing $ inserted"; in a display the inserted $ then draws
   "Display math should end with $$" as well, which is the reference's own
   pair of messages. */
static bool command_wants_a_dollar(const struct hstex_meaning *meaning)
{
    switch (meaning->command) {
    case HSTEX_COMMAND_PAR:
    case HSTEX_COMMAND_VSKIP:
    case HSTEX_COMMAND_HRULE:
    case HSTEX_COMMAND_END:
        return true;
    case HSTEX_COMMAND_UNBOX:
        return meaning->value.integer == (int32_t)HSTEX_UNBOX_VERTICAL ||
               meaning->value.integer == (int32_t)HSTEX_UNBOX_VERTICAL_COPY;
    default:
        return false;
    }
}

/* A command that only a formula can hold. Met outside one, the reference
   puts a $ in front of it and reads it again, in the same words it uses for
   a vertical command met inside one -- so `A\mathchar"141' opens a formula
   rather than stopping. Measured, command by command, against pdftex:
   every math command here does it, while \discretionary, which is
   horizontal, does not, and \eqno is refused by name instead. */
static bool command_needs_a_formula(enum hstex_command command)
{
    switch (command) {
    case HSTEX_COMMAND_MATH_CHAR:
    case HSTEX_COMMAND_MATH_CHAR_GIVEN:
    case HSTEX_COMMAND_MATH_CLASS:
    case HSTEX_COMMAND_MATH_LIMITS:
    case HSTEX_COMMAND_MATH_STYLE:
    case HSTEX_COMMAND_MATH_CHOICE:
    case HSTEX_COMMAND_MATH_ACCENT:
    case HSTEX_COMMAND_MATH_SKIP:
    case HSTEX_COMMAND_MATH_KERN:
    case HSTEX_COMMAND_FRACTION:
    case HSTEX_COMMAND_LEFT_RIGHT:
    case HSTEX_COMMAND_RADICAL:
    case HSTEX_COMMAND_DELIMITER:
    case HSTEX_COMMAND_NON_SCRIPT:
    case HSTEX_COMMAND_VCENTER:
    case HSTEX_COMMAND_OVER_UNDER_LINE:
        return true;
    default:
        return false;
    }
}

static int insert_math_shift(struct hstex_engine *engine, hstex_token offending,
                             struct hstex_source_location location, char *error,
                             size_t error_capacity)
{
    static const char *const help[] = {
        "I've inserted a begin-math/end-math symbol since I think",
        "you left one out. Proceed, with fingers crossed.", NULL};
    hstex_token shift =
        hstex_token_character((uint8_t)HSTEX_CAT_MATH_SHIFT, (uint8_t)'$');
    if (push_one(engine, offending, location, error, error_capacity) != 0 ||
        push_one(engine, shift, location, error, error_capacity) != 0) {
        return -1;
    }
    /* The $ is inserted rather than put back, and the context says so: it
       stands as <inserted text> both while it is waiting and once it has
       been read, where a token put back would say <to be read again> and
       then <recently read>. */
    hstex_source_name_top(&engine->sources,
                          (uint8_t)HSTEX_TOKEN_SOURCE_INSERTED, 0U);
    tex_error(engine, help, "Missing $ inserted");
    return 0;
}

/* An alignment that filled a display is closed by $$, and a command that
   may not stand before it closes the display first and is read again. The
   reference names the pair, not one shift. */
static int insert_display_close(struct hstex_engine *engine,
                                hstex_token offending,
                                struct hstex_source_location location,
                                char *error, size_t error_capacity)
{
    /* Two lines, where "Improper \\halign inside $$'s" has three: nothing
       is deleted here, so the reference does not say it is. */
    static const char *const help[] = {
        "Displays can use special alignments (like \\eqalignno)",
        "only if nothing but the alignment itself is between $$'s.", NULL};
    /* Nothing is really inserted, whatever the message says: the reference
       puts the offending command back and lets the alignment's own finish
       close the display, so the context names that command and not a
       shift. */
    if (push_one(engine, offending, location, error, error_capacity) != 0) {
        return -1;
    }
    tex_error(engine, help, "Missing $$ inserted");
    return end_display_alignment(engine, error, error_capacity);
}

/* A formula closed while a \left group is still open. The reference puts
   `\right.' in front of the closing token and reads it again, one such
   insertion per open \left, until the formula's own list is on top. The
   closer is two tokens, where every other group's is one. */
static int insert_right_delimiter(struct hstex_engine *engine,
                                  hstex_token offending,
                                  struct hstex_source_location location,
                                  char *error, size_t error_capacity)
{
    static const char *const help[] = {
        "I've inserted something that you may have forgotten.",
        "(See the <inserted text> above.)",
        "With luck, this will get me unwedged. But if you",
        "really didn't forget anything, try typing `2' now; then",
        "my insertion and my current dilemma will both disappear.", NULL};
    static const uint8_t name[] = "right";
    hstex_cs_id identifier = 0U;
    if (hstex_symbol_intern(&engine->lexical_state.symbols,
                            HSTEX_SYMBOL_REGULAR, name, sizeof(name) - 1U,
                            &identifier, error, error_capacity) != 0) {
        return -1;
    }
    hstex_token stop =
        hstex_token_character((uint8_t)HSTEX_CAT_OTHER, (uint8_t)'.');
    /* The token that was too early is put BACK, so it stands in a frame of
       its own that the context calls `<to be read again>'. The two that are
       put IN are ONE inserted text, which is what the context names above
       it: `<inserted text> \right .' on one line, not two frames. */
    hstex_token inserted[2] = {hstex_token_control_sequence(identifier), stop};
    if (push_one(engine, offending, location, error, error_capacity) != 0 ||
        hstex_source_push_tokens(&engine->sources, inserted, 2U, location,
                                 error, error_capacity) != 0) {
        return -1;
    }
    tex_error(engine, help, "Missing \\right. inserted");
    return 0;
}

/* A `}' that would close an alignment ENTRY'S own group closes nothing a
   document opened. The reference hands the brace back, guesses that a \cr
   was meant, and puts one in front of it. */
static int insert_missing_cr(struct hstex_engine *engine, hstex_token offending,
                             struct hstex_source_location location,
                             char *error, size_t error_capacity)
{
    static const char *const help[] = {
        "I'm guessing that you meant to end an alignment here.", NULL};
    static const uint8_t name[] = "cr";
    hstex_cs_id identifier = 0U;
    if (hstex_symbol_intern(&engine->lexical_state.symbols,
                            HSTEX_SYMBOL_REGULAR, name, sizeof(name) - 1U,
                            &identifier, error, error_capacity) != 0 ||
        push_one(engine, offending, location, error, error_capacity) != 0 ||
        push_one(engine, hstex_token_control_sequence(identifier), location,
                 error, error_capacity) != 0) {
        return -1;
    }
    hstex_source_name_top(&engine->sources,
                          (uint8_t)HSTEX_TOKEN_SOURCE_INSERTED, 0U);
    tex_error(engine, help, "Missing \\cr inserted");
    return 0;
}

/* A tab or a \cr that turns up where the braces of the entry it is in do
   not come out even. The reference puts in the brace that would even them,
   hands the tab back, and reads it again -- so the same tab ends the entry
   once the column is whole. */
static int insert_missing_brace_for_align(struct hstex_engine *engine,
                                          hstex_token offending,
                                          struct hstex_source_location location,
                                          bool opening, char *error,
                                          size_t error_capacity)
{
    static const char *const help[] = {
        "I've put in what seems to be necessary to fix",
        "the current column of the current alignment.",
        "Try to go on, since this might almost work.", NULL};
    hstex_token brace = hstex_token_character(
        opening ? (uint8_t)HSTEX_CAT_BEGIN_GROUP : (uint8_t)HSTEX_CAT_END_GROUP,
        opening ? (uint8_t)'{' : (uint8_t)'}');
    /* The brace is PUT IN rather than put back: it is not one the entry's
       count has already seen, so it does not undo a reading. */
    if (push_one(engine, offending, location, error, error_capacity) != 0 ||
        hstex_source_push_one(&engine->sources, brace, location, error,
                              error_capacity) != 0) {
        return -1;
    }
    hstex_source_name_top(&engine->sources,
                          (uint8_t)HSTEX_TOKEN_SOURCE_INSERTED, 0U);
    tex_error(engine, help, "Missing %c inserted", opening ? '{' : '}');
    return 0;
}

static int off_save(struct hstex_engine *engine, hstex_token offending,
                    struct hstex_source_location location, char *error,
                    size_t error_capacity)
{
    static const char *const help[] = {
        "I've inserted something that you may have forgotten.",
        "(See the <inserted text> above.)",
        "With luck, this will get me unwedged. But if you",
        "really didn't forget anything, try typing `2' now; then",
        "my insertion and my current dilemma will both disappear.", NULL};
    if (engine->group_level == 0U) {
        /* There is nothing to close. Inserting a closer here would draw
           "Too many }'s" and leave the command to be read again in the same
           mode, which is a loop rather than a recovery, so the command is
           named and dropped instead. A well-formed document does not reach
           this; trip does, by way of the brace trickery on line 420. */
        report_illegal_case(engine, offending);
        return 0;
    }
    enum hstex_group_kind kind = current_group_kind(engine);
    hstex_token closer;
    if (kind == HSTEX_GROUP_SEMI_SIMPLE) {
        static const uint8_t name[] = "endgroup";
        hstex_cs_id identifier = 0U;
        if (hstex_symbol_intern(&engine->lexical_state.symbols,
                                HSTEX_SYMBOL_REGULAR, name,
                                sizeof(name) - 1U, &identifier, error,
                                error_capacity) != 0) {
            return -1;
        }
        closer = hstex_token_control_sequence(identifier);
    } else if (kind == HSTEX_GROUP_MATH_SHIFT) {
        closer = hstex_token_character((uint8_t)HSTEX_CAT_MATH_SHIFT,
                                       (uint8_t)'$');
    } else {
        closer = hstex_token_character((uint8_t)HSTEX_CAT_END_GROUP,
                                       (uint8_t)'}');
    }
    /* The command is read again after the closer, so it goes back first.
       The closer is PUT IN rather than put back: it is not a token any
       count has already seen, so it does not undo a reading -- which
       matters inside an alignment entry, where the braces are counted. */
    if (push_one(engine, offending, location, error, error_capacity) != 0 ||
        hstex_source_push_one(&engine->sources, closer, location, error,
                              error_capacity) != 0) {
        return -1;
    }
    /* What is put in is inserted, and the context says so. */
    hstex_source_name_top(&engine->sources,
                          (uint8_t)HSTEX_TOKEN_SOURCE_INSERTED, 0U);
    tex_error(engine, help, "Missing %s inserted", group_closer_name(kind));
    return 0;
}

static int begin_group(struct hstex_engine *engine, enum hstex_group_kind kind,
                       char *error, size_t error_capacity)
{
    if (engine->group_level == UINT32_MAX) {
        return set_error(error, error_capacity, "group nesting overflow");
    }
    if ((size_t)engine->group_level + 1U > engine->group_kind_capacity) {
        size_t capacity = engine->group_kind_capacity == 0U
                              ? 32U
                              : engine->group_kind_capacity * 2U;
        while (capacity < (size_t)engine->group_level + 1U) {
            capacity *= 2U;
        }
        uint8_t *grown =
            realloc(engine->group_kinds, capacity * sizeof(*grown));
        if (grown == NULL) {
            return set_error(error, error_capacity,
                             "group-kind allocation failed");
        }
        engine->group_kinds = grown;
        engine->group_kind_capacity = capacity;
    }
    engine->group_kinds[engine->group_level] = (uint8_t)kind;
    ++engine->group_level;
    return 0;
}

/* Whether a global assignment inside the group has taken the value over.
   When it has, the save is let go rather than put back, and the reference
   writes `retaining' with the value that stands instead of `restoring' with
   the one saved: measured, `{\count5=14 \global\count5=15}' writes
   {retaining \count5=15}. `standing' is filled with the value that took
   over, so that the same tracing can name it. */
static bool save_was_taken_over(const struct hstex_engine *engine,
                                const struct hstex_save_entry *save,
                                uint32_t leaving_level,
                                struct hstex_save_entry *standing)
{
    *standing = *save;
    uint32_t level = leaving_level;
    switch (save->kind) {
    case HSTEX_SAVE_MEANING:
        level = engine->meanings[save->index - 1U].level;
        standing->previous.meaning = engine->meanings[save->index - 1U];
        break;
    case HSTEX_SAVE_CAT_CODE:
        level = engine->catcode_levels[save->index];
        standing->previous.category = hstex_catcode_get(
            &engine->lexical_state.catcodes, (uint8_t)save->index);
        break;
    case HSTEX_SAVE_COUNT:
        level = engine->count_levels[save->index];
        standing->previous.integer = engine->counts[save->index];
        break;
    case HSTEX_SAVE_INTEGER_PARAMETER:
        level = engine->integer_parameter_levels[save->index];
        standing->previous.integer = engine->integer_parameters[save->index];
        break;
    case HSTEX_SAVE_DIMEN:
        level = engine->dimen_levels[save->index];
        standing->previous.integer = engine->dimens[save->index];
        break;
    case HSTEX_SAVE_DIMEN_PARAMETER:
        level = engine->dimen_parameter_levels[save->index];
        standing->previous.integer = engine->dimen_parameters[save->index];
        break;
    case HSTEX_SAVE_GLUE:
        level = engine->glue_levels[save->index];
        standing->previous.glue = engine->glues[save->index];
        break;
    case HSTEX_SAVE_MUGLUE:
        level = engine->muglue_levels[save->index];
        standing->previous.glue = engine->muglues[save->index];
        break;
    case HSTEX_SAVE_GLUE_PARAMETER:
        level = engine->glue_parameter_levels[save->index];
        standing->previous.glue = engine->glue_parameters[save->index];
        break;
    case HSTEX_SAVE_MUGLUE_PARAMETER:
        level = engine->muglue_parameter_levels[save->index];
        standing->previous.glue = engine->muglue_parameters[save->index];
        break;
    case HSTEX_SAVE_CODE: {
        uint32_t table = save->index / 256U;
        uint32_t character = save->index % 256U;
        level = engine->code_levels[table][character];
        standing->previous.integer = engine->code_tables[table][character];
        break;
    }
    case HSTEX_SAVE_TOKEN_REGISTER:
        level = engine->token_register_levels[save->index];
        standing->previous.token_list_identifier =
            engine->token_registers[save->index];
        break;
    case HSTEX_SAVE_TOKEN_PARAMETER:
        level = engine->token_parameter_levels[save->index];
        standing->previous.token_list_identifier =
            engine->token_parameters[save->index];
        break;
    case HSTEX_SAVE_BOX:
        level = engine->box_levels[save->index];
        standing->previous.box = engine->boxes[save->index];
        break;
    case HSTEX_SAVE_MATH_FONT: {
        size_t size = save->index / 16U;
        size_t family = save->index % 16U;
        level = engine->math_font_levels[size][family];
        standing->previous.integer =
            (int32_t)engine->math_fonts[size][family];
        break;
    }
    case HSTEX_SAVE_PAR_SHAPE:
        level = engine->parshape_level;
        standing->previous.integer = (int32_t)engine->parshape;
        break;
    case HSTEX_SAVE_FONT:
        level = engine->current_font_level;
        standing->previous.integer = (int32_t)engine->current_font;
        break;
    case HSTEX_SAVE_AFTER_GROUP:
        break;
    }
    return level != leaving_level;
}

/* Returns 1 when there was no group to end, so the brace is simply gone. */
static int end_group(struct hstex_engine *engine, char *error,
                     size_t error_capacity)
{
    if (engine->group_level == 0U) {
        static const char *const help[] = {
            "You've closed more groups than you opened.",
            "Such booboos are generally harmless, so keep going.", NULL};
        tex_error(engine, help, "Too many }'s");
        return 1;
    }
    /* A character held back for the ligature program is taken into the list
       before anything is restored, so that it is set in the font it was read
       in. This is also why f{}i is not a ligature. */
    if (flush_pending_character(engine, error, error_capacity) != 0) {
        return -1;
    }
    uint32_t leaving_level = engine->group_level;
    while (engine->save_count != 0U &&
           engine->saves[engine->save_count - 1U].level == leaving_level) {
        struct hstex_save_entry save = engine->saves[--engine->save_count];
        /* What \aftergroup put by draws nothing. The font in use DOES draw a
           line -- `{restoring current font=\ff}' -- which no probe had shown
           because they were all run under the preloaded pdftex format, where
           selecting a font is an assignment like any other and the eTeX
           rule about assigning what is already there hides it. Under
           `pdftex -ini' it is drawn every time. See
           tests/trip/probes/what-tracingrestores-writes.tex. */
        if (save.kind != HSTEX_SAVE_AFTER_GROUP) {
            struct hstex_save_entry standing;
            bool taken_over =
                save_was_taken_over(engine, &save, leaving_level, &standing);
            trace_restore(engine, taken_over ? &standing : &save, taken_over);
        }
        switch (save.kind) {
        case HSTEX_SAVE_MEANING: {
            struct hstex_meaning *current =
                &engine->meanings[save.index - 1U];
            if (current->level == leaving_level) {
                struct hstex_meaning previous = *current;
                *current = save.previous.meaning;
                release_macro(engine, &previous);
            } else {
                /* Something global took the control sequence over, so what
                   was being kept for this group is let go instead. */
                release_macro(engine, &save.previous.meaning);
            }
            break;
        }
        case HSTEX_SAVE_CAT_CODE:
            if (engine->catcode_levels[save.index] == leaving_level) {
                if (hstex_catcode_set(&engine->lexical_state.catcodes,
                                      save.index,
                                      save.previous.category) != 0) {
                    return set_error(error, error_capacity,
                                     "failed to restore catcode");
                }
                engine->catcode_levels[save.index] = save.previous_level;
            }
            break;
        case HSTEX_SAVE_PAR_SHAPE:
            if (engine->parshape_level == leaving_level) {
                engine->parshape = (uint32_t)save.previous.integer;
                engine->parshape_level = save.previous_level;
            }
            break;
        case HSTEX_SAVE_FONT:
            if (engine->current_font_level == leaving_level) {
                engine->current_font = (uint32_t)save.previous.integer;
                engine->current_font_level = save.previous_level;
            }
            break;
        case HSTEX_SAVE_MATH_FONT: {
            size_t size = save.index / 16U;
            size_t family = save.index % 16U;
            if (engine->math_font_levels[size][family] == leaving_level) {
                engine->math_fonts[size][family] =
                    (uint32_t)save.previous.integer;
                engine->math_font_levels[size][family] = save.previous_level;
            }
            break;
        }
        case HSTEX_SAVE_COUNT:
            if (engine->count_levels[save.index] == leaving_level) {
                engine->counts[save.index] = save.previous.integer;
                engine->count_levels[save.index] = save.previous_level;
            }
            break;
        case HSTEX_SAVE_INTEGER_PARAMETER:
            if (engine->integer_parameter_levels[save.index] == leaving_level) {
                engine->integer_parameters[save.index] = save.previous.integer;
                engine->integer_parameter_levels[save.index] =
                    save.previous_level;
                if (save.index ==
                    (uint32_t)HSTEX_INTEGER_END_LINE_CHARACTER) {
                    engine->lexical_state.end_line_character =
                        save.previous.integer;
                }
            }
            break;
        case HSTEX_SAVE_DIMEN:
            if (engine->dimen_levels[save.index] == leaving_level) {
                engine->dimens[save.index] = save.previous.integer;
                engine->dimen_levels[save.index] = save.previous_level;
            }
            break;
        case HSTEX_SAVE_GLUE:
            if (engine->glue_levels[save.index] == leaving_level) {
                engine->glues[save.index] = save.previous.glue;
                engine->glue_levels[save.index] = save.previous_level;
            }
            break;
        case HSTEX_SAVE_MUGLUE:
            if (engine->muglue_levels[save.index] == leaving_level) {
                engine->muglues[save.index] = save.previous.glue;
                engine->muglue_levels[save.index] = save.previous_level;
            }
            break;
        case HSTEX_SAVE_DIMEN_PARAMETER:
            if (engine->dimen_parameter_levels[save.index] == leaving_level) {
                engine->dimen_parameters[save.index] = save.previous.integer;
                engine->dimen_parameter_levels[save.index] =
                    save.previous_level;
            }
            break;
        case HSTEX_SAVE_GLUE_PARAMETER:
            if (engine->glue_parameter_levels[save.index] == leaving_level) {
                engine->glue_parameters[save.index] = save.previous.glue;
                engine->glue_parameter_levels[save.index] =
                    save.previous_level;
            }
            break;
        case HSTEX_SAVE_MUGLUE_PARAMETER:
            if (engine->muglue_parameter_levels[save.index] == leaving_level) {
                engine->muglue_parameters[save.index] = save.previous.glue;
                engine->muglue_parameter_levels[save.index] =
                    save.previous_level;
            }
            break;
        case HSTEX_SAVE_CODE: {
            uint32_t table = save.index / 256U;
            uint32_t character = save.index % 256U;
            if (engine->code_levels[table][character] == leaving_level) {
                engine->code_tables[table][character] = save.previous.integer;
                engine->code_levels[table][character] = save.previous_level;
            }
            break;
        }
        case HSTEX_SAVE_TOKEN_REGISTER:
            if (engine->token_register_levels[save.index] == leaving_level) {
                engine->token_registers[save.index] =
                    save.previous.token_list_identifier;
                engine->token_register_levels[save.index] =
                    save.previous_level;
            }
            break;
        case HSTEX_SAVE_TOKEN_PARAMETER:
            if (engine->token_parameter_levels[save.index] == leaving_level) {
                engine->token_parameters[save.index] =
                    save.previous.token_list_identifier;
                engine->token_parameter_levels[save.index] =
                    save.previous_level;
            }
            break;
        case HSTEX_SAVE_BOX:
            if (engine->box_levels[save.index] == leaving_level) {
                engine->boxes[save.index] = save.previous.box;
                engine->box_levels[save.index] = save.previous_level;
            }
            break;
        case HSTEX_SAVE_AFTER_GROUP:
            if (push_one(engine, save.previous.after_group.token,
                         save.previous.after_group.location, error,
                         error_capacity) != 0) {
                return -1;
            }
            break;
        }
    }
    --engine->group_level;
    return 0;
}

/* The reference reports an undefined control sequence and forgets it,
   which is what lets a document with one misspelling still be set. The
   name is not in the message: it is at the end of the context line above
   it, which is what the help refers to. */
static void report_undefined_control_sequence(struct hstex_engine *engine)
{
    static const char *const help[] = {
        "The control sequence at the end of the top line",
        "of your error message was never \\def'ed. If you have",
        "misspelled it (e.g., `\\hobx'), type `I' and the correct",
        "spelling (e.g., `I\\hbox'). Otherwise just continue,",
        "and I'll forget about whatever was undefined.", NULL};
    tex_error(engine, help, "Undefined control sequence");
}

static int execute_ignore_spaces(struct hstex_engine *engine, char *error,
                                 size_t error_capacity)
{
    for (;;) {
        hstex_token token = 0U;
        struct hstex_source_location location;
        enum hstex_engine_result result = hstex_engine_next_expanded(
            engine, &token, &location, error, error_capacity);
        if (result == HSTEX_ENGINE_EOF) {
            return 0;
        }
        if (result == HSTEX_ENGINE_ERROR) {
            return -1;
        }
        if (token_is_effective_space(engine, token)) {
            continue;
        }
        if (engine->returned_unexpanded &&
            !engine->returned_unexpanded_executable &&
            hstex_token_is_control_sequence(token)) {
            token = hstex_token_frozen_control_sequence(
                hstex_token_control_sequence_id(token));
        }
        return push_one(engine, token, location, error, error_capacity);
    }
}

/* Run the document: everything the executor does not handle itself belongs
   to the main vertical list, which is built exactly as a \vbox body is. See
   docs/DECISIONS.md, the-main-vertical-list. */
void hstex_engine_set_terminal_input(struct hstex_engine *engine, FILE *stream)
{
    engine->terminal_input = stream;
}

void hstex_engine_set_message_stream(struct hstex_engine *engine,
                                     FILE *stream)
{
    engine->message_stream = stream;
}

static void hstex_engine_release_chunks(struct hstex_engine *engine);
static void finish_a_chunk(struct hstex_engine *engine);


/* ---- The aux delta, written by the engine itself -----------------------
   A parked chunk carries the labels its run read; the run being served
   reads newer ones. The difference is a file of assignments, and the
   verifier writes it by comparing the aux the fleet was parked with -- a
   copy taken before the parking run read it -- against the aux on disk
   now. Only \newlabel and \bibcite become definitions when an aux is
   read, so only they are compared. */

struct aux_line {
    uint64_t name_hash;
    uint64_t body_hash;
    const char *name;
    size_t name_length;
    const char *body;
    size_t body_length;
    char prefix;
};

static char *spec_read_whole(const char *path, size_t *length)
{
    FILE *in = fopen(path, "rb");
    if (in == NULL) {
        *length = 0U;
        return NULL;
    }
    if (fseek(in, 0L, SEEK_END) != 0) {
        (void)fclose(in);
        *length = 0U;
        return NULL;
    }
    long told = ftell(in);
    rewind(in);
    if (told < 0L) {
        (void)fclose(in);
        *length = 0U;
        return NULL;
    }
    char *bytes = malloc((size_t)told + 1U);
    if (bytes == NULL || fread(bytes, 1U, (size_t)told, in) != (size_t)told) {
        free(bytes);
        (void)fclose(in);
        *length = 0U;
        return NULL;
    }
    (void)fclose(in);
    bytes[told] = '\0';
    *length = (size_t)told;
    return bytes;
}

static size_t spec_harvest_aux(const char *text, size_t length,
                               struct aux_line **out)
{
    size_t capacity = 256U;
    size_t count = 0U;
    struct aux_line *lines = malloc(capacity * sizeof(*lines));
    if (lines == NULL) {
        *out = NULL;
        return 0U;
    }
    const char *at = text;
    const char *end = text + length;
    while (at < end) {
        const char *line_end = memchr(at, '\n', (size_t)(end - at));
        if (line_end == NULL) {
            line_end = end;
        }
        char prefix = 0;
        const char *rest = NULL;
        if ((size_t)(line_end - at) > 10U &&
            memcmp(at, "\\newlabel{", 10U) == 0) {
            prefix = 'r';
            rest = at + 10U;
        } else if ((size_t)(line_end - at) > 9U &&
                   memcmp(at, "\\bibcite{", 9U) == 0) {
            prefix = 'b';
            rest = at + 9U;
        }
        if (prefix != 0) {
            const char *name_end = memchr(rest, '}', (size_t)(line_end - rest));
            if (name_end != NULL && name_end + 1 < line_end &&
                name_end[1] == '{') {
                const char *body = name_end + 2;
                const char *body_end = line_end;
                while (body_end > body && (body_end[-1] == '\r' ||
                                           body_end[-1] == ' ')) {
                    --body_end;
                }
                if (body_end > body && body_end[-1] == '}') {
                    --body_end;
                    if (count == capacity) {
                        capacity *= 2U;
                        struct aux_line *grown =
                            realloc(lines, capacity * sizeof(*lines));
                        if (grown == NULL) {
                            break;
                        }
                        lines = grown;
                    }
                    struct aux_line *entry = &lines[count++];
                    entry->prefix = prefix;
                    entry->name = rest;
                    entry->name_length = (size_t)(name_end - rest);
                    entry->body = body;
                    entry->body_length = (size_t)(body_end - body);
                    uint64_t hash = UINT64_C(0xcbf29ce484222325);
                    digest_bytes(&hash, &prefix, 1U);
                    digest_bytes(&hash, rest, entry->name_length);
                    entry->name_hash = hash;
                    hash = UINT64_C(0xcbf29ce484222325);
                    digest_bytes(&hash, body, entry->body_length);
                    entry->body_hash = hash;
                }
            }
        }
        at = line_end < end ? line_end + 1 : end;
    }
    *out = lines;
    return count;
}

static const struct aux_line *spec_find_aux(const struct aux_line *lines,
                                            size_t count, uint64_t name_hash)
{
    for (size_t index = 0U; index < count; ++index) {
        if (lines[index].name_hash == name_hash) {
            return &lines[index];
        }
    }
    return NULL;
}

/* The labels a parking run will read are kept beside the fleet, so that a
   later verifier can say how the fleet's labels differ from its own. Taken
   before the document reads anything: what is on disk now is what this run
   will read. */
static void spec_snapshot_aux(struct hstex_engine *engine)
{
    const char *job = engine->job_name == NULL ? "texput" : engine->job_name;
    char aux_name[512];
    (void)snprintf(aux_name, sizeof(aux_name), "%s.aux", job);
    char *aux_path = output_path(engine, aux_name);
    if (aux_path == NULL) {
        return;
    }
    char parked_name[600];
    spec_path(engine, parked_name, sizeof(parked_name), "aux-parked", -1);
    size_t length = 0U;
    char *text = spec_read_whole(aux_path, &length);
    free(aux_path);
    FILE *out = fopen(parked_name, "w");
    if (out != NULL) {
        if (text != NULL && length != 0U) {
            (void)fwrite(text, 1U, length, out);
        }
        (void)fclose(out);
    }
    free(text);
}

/* Write the patch turning the parked labels into the current ones, and say
   whether one was needed at all. */
static bool spec_write_aux_patch(struct hstex_engine *engine,
                                 const char *patch_path)
{
    char parked_name[600];
    spec_path(engine, parked_name, sizeof(parked_name), "aux-parked", -1);
    size_t old_length = 0U;
    char *old_text = spec_read_whole(parked_name, &old_length);
    const char *job = engine->job_name == NULL ? "texput" : engine->job_name;
    char aux_name[512];
    (void)snprintf(aux_name, sizeof(aux_name), "%s.aux", job);
    char *aux_path = output_path(engine, aux_name);
    size_t new_length = 0U;
    char *new_text =
        aux_path == NULL ? NULL : spec_read_whole(aux_path, &new_length);
    free(aux_path);
    struct aux_line *old_lines = NULL;
    struct aux_line *new_lines = NULL;
    size_t old_count = spec_harvest_aux(old_text == NULL ? "" : old_text,
                                        old_length, &old_lines);
    size_t new_count = spec_harvest_aux(new_text == NULL ? "" : new_text,
                                        new_length, &new_lines);
    FILE *out = fopen(patch_path, "w");
    size_t emitted = 0U;
    if (out != NULL) {
        for (size_t index = 0U; index < new_count; ++index) {
            const struct aux_line *entry = &new_lines[index];
            const struct aux_line *before =
                spec_find_aux(old_lines, old_count, entry->name_hash);
            if (before != NULL && before->body_hash == entry->body_hash) {
                continue;
            }
            (void)fprintf(out,
                          "\\global\\expandafter\\def\\csname %c@%.*s"
                          "\\endcsname{%.*s}%%\n",
                          entry->prefix, (int)entry->name_length, entry->name,
                          (int)entry->body_length, entry->body);
            ++emitted;
        }
        for (size_t index = 0U; index < old_count; ++index) {
            const struct aux_line *entry = &old_lines[index];
            if (spec_find_aux(new_lines, new_count, entry->name_hash) ==
                NULL) {
                (void)fprintf(out,
                              "\\global\\expandafter\\let\\csname "
                              "%c@%.*s\\endcsname\\relax %%\n",
                              entry->prefix, (int)entry->name_length,
                              entry->name);
                ++emitted;
            }
        }
        (void)fclose(out);
    }
    free(old_lines);
    free(new_lines);
    free(old_text);
    free(new_text);
    return emitted != 0U;
}

/* The verifier lets the parked fleet go: down each chunk's named pipe goes
   the patch, and the chunks begin reading the disk as it now stands. A pipe
   with no reader is a chunk that died, and its range is simply never
   validated. */
static void spec_release_fleet(struct hstex_engine *engine)
{
    spec_load_pages(engine);
    /* What the last round said is the last round's business. */
    static const char *const stale_prefixes[] = {"entry", "marker", "valid",
                                                 "stale", "tainted"};
    for (size_t index = 0U; index < engine->spec_page_count; ++index) {
        for (size_t which = 0U; which < 5U; ++which) {
            char name[600];
            spec_path(engine, name, sizeof(name), stale_prefixes[which],
                      engine->spec_pages[index]);
            (void)unlink(name);
        }
    }
    {
        char name[600];
        spec_path(engine, name, sizeof(name), "end-done", -1);
        (void)unlink(name);
    }
    char written_patch[600];
    const char *patch = getenv("HSTEX_PATCH");
    if (patch == NULL) {
        spec_path(engine, written_patch, sizeof(written_patch), "patch", -1);
        if (spec_write_aux_patch(engine, written_patch)) {
            patch = written_patch;
        }
    }
    int32_t patch_length =
        patch == NULL ? 0 : (int32_t)strlen(patch);
    if (patch_length >= 4096) {
        patch_length = 0;
    }
    for (size_t index = 0U; index < engine->spec_page_count; ++index) {
        char gate_name[600];
        spec_path(engine, gate_name, sizeof(gate_name), "go",
                  engine->spec_pages[index]);
        int gate = open(gate_name, O_WRONLY | O_NONBLOCK);
        if (gate < 0) {
            continue;
        }
        ssize_t wrote = write(gate, &patch_length, sizeof(patch_length));
        if (patch_length > 0) {
            wrote = write(gate, patch, (size_t)patch_length);
        }
        (void)wrote;
        (void)close(gate);
    }
}

int hstex_engine_run(struct hstex_engine *engine,
                     struct hstex_source_location *last, char *error,
                     size_t error_capacity)
{
    if (engine->verifying) {
        spec_release_fleet(engine);
    }
    if (engine->parallel_chunk != 0) {
        int done[2];
        if (pipe(done) != 0) {
            engine->parallel_chunk = 0;
        } else {
            engine->parallel_done_read = done[0];
            engine->parallel_done_write = done[1];
        }
    }
    struct hstex_source_location location = {0};
    for (;;) {
        hstex_token token = 0U;
        enum hstex_engine_result result = hstex_engine_next_output(
            engine, &token, &location, error, error_capacity);
        if (last != NULL) {
            *last = location;
        }
        if (result == HSTEX_ENGINE_EOF) {
            break;
        }
        if (result == HSTEX_ENGINE_ERROR) {
            return -1;
        }
        if (handle_vertical_list_token(engine, token, location, error,
                                       error_capacity) != 0) {
            return -1;
        }
    }
    /* Whatever files are still being read have their brackets closed, each
       behind a space, the way the reference finishes a run. */
    while (engine->open_parens != 0U) {
        print_text(engine, " )");
        --engine->open_parens;
    }
    /* A group still open when \end is read is said so, once, on a line of
       its own -- the level is how many are open, and the name is written
       with whatever \escapechar says. */
    if (engine->end_requested && engine->group_level != 0U) {
        print_fresh_line(engine);
        print_byte(engine, '(');
        print_escaped_name(engine, "end");
        print_formatted(engine, " occurred inside a group at level %u)",
                        (unsigned)engine->group_level);
        print_line(engine);
    }
    /* And each conditional still open, innermost first, named by the \if it
       was and the line it began on. See docs/DECISIONS.md,
       what-a-run-says-at-its-end. */
    if (engine->end_requested) {
        for (size_t index = engine->conditional_count; index != 0U; --index) {
            const struct hstex_conditional *opened =
                &engine->conditionals[index - 1U];
            char named[128] = "";
            if (opened->opener != 0U) {
                describe_token(engine,
                               hstex_token_control_sequence(opened->opener),
                               named, sizeof(named));
            }
            print_fresh_line(engine);
            print_byte(engine, '(');
            print_escaped_name(engine, "end");
            print_formatted(engine, " occurred when %s", named);
            if (opened->line != 0U) {
                print_formatted(engine, " on line %u", (unsigned)opened->line);
            }
            print_text(engine, " was incomplete)");
            print_line(engine);
        }
        engine->conditional_count = 0U;
    }
    (void)fflush(diagnostic_stream(engine));
    /* The reference stops where the input stops: a paragraph still being
       filled is not ended, and no page is sent off, because neither \end nor
       \par was ever read. What has been written of the page description is
       finished off. */
    if (dvi_close(engine, error, error_capacity) != 0) {
        return -1;
    }
    int closed = pdf_close(engine, error, error_capacity);
    /* "no output PDF file produced" has to be true of the directory and not
       only of the log, so what was written of one is taken away again. */
    if (engine->halted && engine->output_name != NULL) {
        (void)remove(engine->output_name);
    }
    /* What the reference says a run came to. See docs/DECISIONS.md,
       what-a-run-says-at-its-end. */
    if (!engine->parallel_is_worker) {
        print_fresh_line(engine);
        if (engine->halted) {
            print_text(engine,
                       "!  ==> Fatal error occurred, no output PDF file "
                       "produced!");
        } else if (engine->shipped_pages == 0 || engine->output_name == NULL) {
            print_text(engine, "No pages of output.");
        } else {
            size_t bytes = engine->pdf_written != 0U ? engine->pdf_written
                                                     : engine->dvi_written;
            print_formatted(engine, "Output written on %s (%d page%s, %zu bytes).",
                            engine->output_name, engine->shipped_pages,
                            engine->shipped_pages == 1 ? "" : "s", bytes);
        }
        print_line(engine);
        (void)fflush(diagnostic_stream(engine));
    }
    if (engine->parallel_is_worker) {
        if (engine->speculating) {
            /* A carrier that ran all the way says so; a chunk that reached
               the end without meeting the chunk after it stops the usual
               way, its stop page being the document's end. */
            spec_flush(engine);
            if (engine->spec_carrier) {
                spec_touch(engine, "end-done", -1, NULL);
                _exit(0);
            }
            spec_chunk_stop(engine);
            spec_touch(engine, "end-done", -1, NULL);
            _exit(0);
        }
        /* The last chunk has no boundary to stop at, so it stops here. */
        finish_a_chunk(engine);
    }
    hstex_engine_release_chunks(engine);
    if (engine->verifying) {
        spec_finalize(engine);
    }
    return closed;
}

/* A display closed by a single $. The reference reports it, reads the
   offending token again, and goes on as though $$ had been typed both
   times -- so the token is pushed back rather than swallowed. Measured on
   trip line 206, `$$\eqno^{}$\scriptfont3=...', where the reference shows
   \scriptfont as <to be read again> and then obeys it. */
static int report_single_shift_closing_display(
    struct hstex_engine *engine, bool have_token, hstex_token token,
    struct hstex_source_location where, char *error, size_t error_capacity)
{
    static const char *const help[] = {
        "The `$' that I just saw supposedly matches a previous `$$'.",
        "So I shall assume that you typed `$$' both times.", NULL};
    if (have_token &&
        push_one(engine, token, where, error, error_capacity) != 0) {
        return -1;
    }
    tex_error(engine, help, "Display math should end with $$");
    return 0;
}

static const char *const misplaced_tab_help[] = {
    "I can't figure out why you would want to use a tab mark",
    "or \\cr or \\span just now. If something like a right brace",
    "up above has ended a previous alignment prematurely,",
    "you're probably due for more error messages, and you",
    "might try typing `S' now just to see what is salvageable.", NULL};

static const char *const misplaced_ampersand_help[] = {
    "I can't figure out why you would want to use a tab mark",
    "here. If you just want an ampersand, the remedy is",
    "simple: Just type `I\\&' now. But if some right brace",
    "up above has ended a previous alignment prematurely,",
    "you're probably due for more error messages, and you",
    "might try typing `S' now just to see what is salvageable.", NULL};

static const char *const misplaced_noalign_help[] = {
    "I expect to see \\noalign only after the \\cr of",
    "an alignment. Proceed, and I'll ignore this case.", NULL};

static const char *const misplaced_omit_help[] = {
    "I expect to see \\omit only after tab marks or the \\cr of",
    "an alignment. Proceed, and I'll ignore this case.", NULL};

/* Anything that belongs to an alignment, met outside one: the reference
   names it and ignores it. */
static void report_misplaced(struct hstex_engine *engine, hstex_token token,
                             const char *const *help)
{
    char named[128];
    describe_token(engine, token, named, sizeof(named));
    tex_error(engine, help, "Misplaced %s", named);
}

static enum hstex_engine_result next_output(
    struct hstex_engine *engine, hstex_token *token,
    struct hstex_source_location *location, char *error,
    size_t error_capacity)
{
    if (engine->dump_requested || engine->end_requested) {
        return HSTEX_ENGINE_EOF;
    }
    for (;;) {
        engine->command_traced = false;
        enum hstex_engine_result result = hstex_engine_next_expanded(
            engine, token, location, error, error_capacity);
        if (result == HSTEX_ENGINE_EOF) {
            if (engine->group_stop_hit) {
                return result;
            }
            /* A group or a conditional may be opened on one side of a
               box or an alignment entry and closed on the other -- LaTeX's
               \\[2mm] in a table ends the row from inside an \\ifdim -- so
               neither is checked where the reading stops at a boundary
               rather than at the end of everything. See
               docs/DECISIONS.md, conditionals-across-boxes. */
            if (hstex_source_at_boundary(&engine->sources)) {
                return result;
            }
            if (engine->group_level != engine->output_group_floor) {
                (void)set_error(error, error_capacity,
                                "end of input inside a group");
                return HSTEX_ENGINE_ERROR;
            }
            if (engine->conditional_count >
                engine->output_conditional_floor) {
                (void)set_error(error, error_capacity,
                                "end of input inside a conditional");
                return HSTEX_ENGINE_ERROR;
            }
            return result;
        }
        if (result == HSTEX_ENGINE_ERROR) {
            return result;
        }
        if (engine->returned_unexpanded &&
            hstex_token_is_control_sequence(*token)) {
            if (engine->returned_unexpanded_executable) {
                if (push_one(engine, *token, *location, error,
                             error_capacity) != 0) {
                    return HSTEX_ENGINE_ERROR;
                }
                continue;
            }
            /* A NAME \noexpand HELD BACK IS \relax FOR THIS ONE READING.
               The reference obeys that \relax -- which does nothing, and
               spends no prefix waiting for a command -- and traces it, so
               `\noexpand\undefined' draws `{\relax}' and no fault. */
            static const uint8_t name[] = "relax";
            hstex_cs_id identifier = 0U;
            if (hstex_symbol_intern(&engine->lexical_state.symbols,
                                    HSTEX_SYMBOL_REGULAR, name,
                                    sizeof(name) - 1U, &identifier, error,
                                    error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            trace_command(engine, hstex_token_control_sequence(identifier));
            continue;
        }

handle_token:
        /* A prefix wants a command it can prefix. Blanks and \relax stand
           between without spending it; anything else is named, the prefix
           is forgotten, and the command is read again. */
        if ((engine->pending_global || engine->pending_macro_flags != 0U) &&
            !token_is_space(*token)) {
            bool prefixable = false;
            if (hstex_token_is_control_sequence(*token)) {
                const struct hstex_meaning *after = hstex_engine_meaning(
                    engine, hstex_token_control_sequence_id(*token));
                prefixable = after->command == HSTEX_COMMAND_RELAX ||
                             command_assigns(after->command);
            }
            if (!prefixable) {
                /* The reference names the three prefixes TeX82 has and
                   not the \protected eTeX adds. */
                static const char *const help[] = {
                    "I'll pretend you didn't say \\long or \\outer or "
                    "\\global.", NULL};
                char named[128];
                describe_token(engine, *token, named, sizeof(named));
                if (push_one(engine, *token, *location, error,
                             error_capacity) != 0) {
                    return HSTEX_ENGINE_ERROR;
                }
                engine->pending_global = false;
                engine->pending_macro_flags = 0U;
                tex_error(engine, help, "You can't use a prefix with `%s'",
                          named);
                continue;
            }
        }
        /* An \accent waits here for its character, while the main loop
           carries out the assignments the reference allows in between. A
           blank is skipped, \relax and any assignment are obeyed and the
           accent goes on waiting, and anything else is the character --
           or, if it is not a character at all, the end of the search. */
        if (engine->accent_pending) {
            if (token_is_space(*token)) {
                continue;
            }
            int32_t accented = -1;
            bool finish = true;
            if (hstex_token_is_character(*token)) {
                if (token_is_category(*token, HSTEX_CAT_LETTER) ||
                    token_is_category(*token, HSTEX_CAT_OTHER)) {
                    accented = (int32_t)hstex_token_character_code(*token);
                } else if (push_one(engine, *token, *location, error,
                                    error_capacity) != 0) {
                    return HSTEX_ENGINE_ERROR;
                }
            } else {
                const struct hstex_meaning *between = hstex_engine_meaning(
                    engine, hstex_token_control_sequence_id(*token));
                if (between->command == HSTEX_COMMAND_RELAX ||
                    command_assigns(between->command)) {
                    finish = false;
                } else if (between->command == HSTEX_COMMAND_CHAR_GIVEN) {
                    accented = between->value.integer;
                } else if (between->command == HSTEX_COMMAND_CHAR) {
                    if (scan_integer(engine, &accented, error,
                                     error_capacity) != 0) {
                        return HSTEX_ENGINE_ERROR;
                    }
                } else if (push_one(engine, *token, *location, error,
                                    error_capacity) != 0) {
                    return HSTEX_ENGINE_ERROR;
                }
            }
            if (finish) {
                if (finish_accent(engine, accented, error, error_capacity) !=
                    0) {
                    return HSTEX_ENGINE_ERROR;
                }
                continue;
            }
        }
        /* An alignment that filled a display admits only $$, an assignment
           and \relax before the display closes; anything else closes it
           first and is read again. */
        if (engine->display_alignment &&
            !token_is_category(*token, HSTEX_CAT_MATH_SHIFT) &&
            !token_is_space(*token)) {
            /* Blanks stand between the assignments the reference allows
               here -- an alignment usually ends a line -- and it skips
               them rather than closing the display on one. */
            bool allowed = false;
            if (hstex_token_is_control_sequence(*token)) {
                const struct hstex_meaning *what = hstex_engine_meaning(
                    engine, hstex_token_control_sequence_id(*token));
                allowed = what->command == HSTEX_COMMAND_RELAX ||
                          command_assigns(what->command);
            }
            if (!allowed) {
                if (insert_display_close(engine, *token, *location, error,
                                         error_capacity) != 0) {
                    return HSTEX_ENGINE_ERROR;
                }
                continue;
            }
        }
        /* A VERTICAL command where a formula is waiting for a field is read
           as the field first: the reference is inside its field scan when
           the token arrives, so `$\mathaccent"7016 \vfill$' draws
           "Missing { inserted" and only then, inside the braces that made,
           "Missing $ inserted". Everything else a field may not be is
           caught further down, where the spaces and the \relax that stand
           in front of a field have already been stepped over. */
        if (engine->mode == HSTEX_MODE_MATH && math_field_is_wanted(engine) &&
            hstex_token_is_control_sequence(*token) &&
            command_wants_a_dollar(hstex_engine_meaning(
                engine, hstex_token_control_sequence_id(*token))) &&
            !token_can_be_math_field(engine, *token)) {
            if (insert_math_field_brace(engine, *token, *location, error,
                                        error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        }
        /* A vertical command inside a formula closes it first, and a math
           command outside one opens it: both put a $ in front of the
           command and read it again. Without the first an unclosed display
           never ends -- \end would be met again and again with the formula
           still open. */
        if (hstex_token_is_control_sequence(*token)) {
            const struct hstex_meaning *across = hstex_engine_meaning(
                engine, hstex_token_control_sequence_id(*token));
            bool crosses = engine->mode == HSTEX_MODE_MATH
                               ? command_wants_a_dollar(across)
                               : command_needs_a_formula(across->command);
            if (crosses) {
                /* Traced where it was met AND again after the $ has been
                   read, because it is read again there: measured on `$z\par'
                   in math mode, which draws {\par}, the fault, {math shift
                   character $} and then {horizontal mode: \par}. */
                if (!engine->command_traced && !engine->pending_global &&
                    engine->pending_macro_flags == 0U) {
                    trace_command(engine, *token);
                }
                if (insert_math_shift(engine, *token, *location, error,
                                      error_capacity) != 0) {
                    return HSTEX_ENGINE_ERROR;
                }
                continue;
            }
        }
        /* A macro parameter character has no meaning outside a definition
           or an alignment preamble: the reference names it and ignores it.
           Measured in every mode, and for ## as well as #. */
        if (token_is_category(*token, HSTEX_CAT_PARAMETER)) {
            /* Named first and refused after: the trace says what the main
               loop was given, whatever it then makes of it. */
            if (!engine->command_traced && !engine->pending_global &&
                engine->pending_macro_flags == 0U &&
                !engine->display_alignment && !engine->accent_pending) {
                trace_command(engine, *token);
            }
            report_illegal_case(engine, *token);
            continue;
        }
        /* A script mark belongs to a formula too. */
        if (engine->mode != HSTEX_MODE_MATH &&
            (token_is_category(*token, HSTEX_CAT_SUPERSCRIPT) ||
             token_is_category(*token, HSTEX_CAT_SUBSCRIPT))) {
            /* Traced here and again after the $, as above. */
            if (!engine->command_traced && !engine->pending_global &&
                engine->pending_macro_flags == 0U) {
                trace_command(engine, *token);
            }
            if (insert_math_shift(engine, *token, *location, error,
                                  error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        }
        if (hstex_token_is_character(*token)) {
            /* Unless this character is standing in for the control sequence
               that meant it -- one \let to a brace, one \chardef'd -- which
               was traced already. The reference draws one line for
               `\let\bg={ \bg', not two. Nor is anything traced while a
               prefix is waiting: what \global prefixes it reads itself. */
            /* Nor anything an alignment that stood in for a display reads
               before that display closes -- the blanks, the assignments,
               and both shifts of the closing $$ -- nor the assignments an
               \accent reads while it waits for its character. Their own
               finishes read them, so none of them reaches the main loop
               for it to draw. */
            if (!engine->command_traced && !engine->pending_global &&
                engine->pending_macro_flags == 0U &&
                !engine->display_alignment && !engine->accent_pending &&
                !engine->mandatory_brace) {
                trace_command(engine, *token);
            }
            engine->mandatory_brace = false;
            /* A formula is delimited by math shifts rather than braces, so
               the executor recognises them itself; see docs/DECISIONS.md,
               math-mode. */
            if (token_is_category(*token, HSTEX_CAT_ALIGNMENT_TAB)) {
                /* A tab that came from a TEMPLATE divides nothing: no
                   separator can be met while a template is being read, so
                   the reference names it and drops it. */
                if (engine->alignment_token_from_template) {
                    report_misplaced(engine, *token, misplaced_ampersand_help);
                    continue;
                }
                if (engine->alignment_entry != NULL &&
                    !engine->alignment_entry->after_pushed) {
                    if (end_alignment_entry(engine, HSTEX_ALIGN_END_TAB, error,
                                            error_capacity) != 0) {
                        return HSTEX_ENGINE_ERROR;
                    }
                    continue;
                }
                /* A tab with no alignment to divide is named and ignored,
                   in words of its own -- the reference offers `I\&' there,
                   which it has no reason to offer for \cr or \span. */
                if (!engine->building_alignment) {
                    report_misplaced(engine, *token,
                                     misplaced_ampersand_help);
                    continue;
                }
            }
            if (token_is_category(*token, HSTEX_CAT_MATH_SHIFT)) {
                /* An alignment that stood in for a whole display leaves the
                   engine in vertical mode, so the $$ that closes it is
                   recognised before anything else. */
                if (engine->display_alignment) {
                    hstex_token second = 0U;
                    struct hstex_source_location where;
                    /* The second $ is fetched WITH EXPANSION, so a macro
                       standing for it will do: measured on `$$y$\dollar'
                       with \def\dollar{$}, which closes the display and
                       reports nothing. */
                    int taken = (int)hstex_engine_next_expanded(
                        engine, &second, &where, error, error_capacity);
                    if (taken != HSTEX_ENGINE_TOKEN ||
                        !token_is_effective_category(
                            engine, second, (uint8_t)HSTEX_CAT_MATH_SHIFT)) {
                        if (report_single_shift_closing_display(
                                engine, taken == HSTEX_ENGINE_TOKEN, second,
                                where, error, error_capacity) != 0) {
                            return HSTEX_ENGINE_ERROR;
                        }
                    }
                    if (end_display_alignment(engine, error, error_capacity) !=
                        0) {
                        return HSTEX_ENGINE_ERROR;
                    }
                    continue;
                }
                /* Math shift starts a paragraph in vertical mode, and like
                   every other horizontal command it is read again once
                   \everypar has run. */
                if (engine->mode == HSTEX_MODE_VERTICAL) {
                    if (push_one(engine, *token, *location, error,
                                 error_capacity) != 0 ||
                        start_paragraph(engine, true, error, error_capacity) !=
                            0) {
                        return HSTEX_ENGINE_ERROR;
                    }
                    continue;
                }
                if (engine->mode == HSTEX_MODE_MATH) {
                    /* A formula can only be closed from its own group, so a
                       group opened inside it is closed first and the $ read
                       again. */
                    if (current_group_kind(engine) != HSTEX_GROUP_MATH_SHIFT) {
                        if (off_save(engine, *token, *location, error,
                                     error_capacity) != 0) {
                            return HSTEX_ENGINE_ERROR;
                        }
                        continue;
                    }
                    /* A \left opens no group of its own, only an inner math
                       list, so it is asked about separately. */
                    if (engine->math_depth > engine->math_floor + 1U) {
                        if (insert_right_delimiter(engine, *token, *location,
                                                   error, error_capacity) !=
                            0) {
                            return HSTEX_ENGINE_ERROR;
                        }
                        continue;
                    }
                    /* A display closes on the second of two shifts. */
                    if (engine->displayed_math) {
                        /* The formula in hand is measured FIRST -- the
                           number's, where there is one -- because the
                           reference reports its `Insufficient extension
                           fonts' before it complains about the single $. */
                        struct hstex_box packaged = {0};
                        /* WHETHER THE FORMULA CAN BE SET AT ALL is settled
                           first of all: the reference looks for the fonts a
                           formula is measured against before it goes looking
                           for the second $, so what it says of them stands
                           in front of whatever that reading expands. */
                        bool deleted = math_fonts_are_missing(engine);
                        /* The formula's own list is finished with by the
                           time the second $ is looked for, so the mode there
                           is the one the list it was part of is built in. For
                           the display that is the vertical list it will join
                           -- internal vertical inside a \vbox; for an
                           equation NUMBER it is the display itself, which is
                           still standing. \tracingcommands names either for
                           an \expandafter between the two $. */
                        if (engine->reading_equation_number) {
                            engine->mode = HSTEX_MODE_MATH;
                            engine->inner_mode = false;
                        } else {
                            engine->displayed_math = false;
                            engine->mode = HSTEX_MODE_VERTICAL;
                            engine->inner_mode = vertical_list_is_inner(engine);
                        }
                        hstex_token second = 0U;
                        struct hstex_source_location where;
                        /* With expansion, as above. */
                        int taken = (int)hstex_engine_next_expanded(
                            engine, &second, &where, error, error_capacity);
                        if (taken != HSTEX_ENGINE_TOKEN ||
                            !token_is_effective_category(
                                engine, second,
                                (uint8_t)HSTEX_CAT_MATH_SHIFT)) {
                            if (report_single_shift_closing_display(
                                    engine, taken == HSTEX_ENGINE_TOKEN,
                                    second, where, error, error_capacity) != 0) {
                                return HSTEX_ENGINE_ERROR;
                            }
                        }
                        /* AND IT IS SET ONLY ONCE THAT SECOND $ IS IN: what
                           the setting reports -- a character the family's
                           font has not got, an undefined family -- stands
                           after whatever reading the second $ expanded. See
                           docs/DECISIONS.md, when-a-display-is-set. */
                        if (package_displayed_formula(engine, deleted,
                                                      &packaged, error,
                                                      error_capacity) != 0) {
                            return HSTEX_ENGINE_ERROR;
                        }
                        if (end_display_math(engine, packaged, error,
                                             error_capacity) != 0) {
                            return HSTEX_ENGINE_ERROR;
                        }
                        continue;
                    }
                    if (end_math(engine, error, error_capacity) != 0) {
                        return HSTEX_ENGINE_ERROR;
                    }
                    continue;
                }
                /* Two shifts in an outer paragraph open a display. */
                if (!engine->inner_mode) {
                    hstex_token second = 0U;
                    struct hstex_source_location where;
                    enum hstex_engine_result twice =
                        raw_next(engine, &second, &where, error,
                                 error_capacity);
                    if (twice == HSTEX_ENGINE_ERROR) {
                        return HSTEX_ENGINE_ERROR;
                    }
                    if (twice == HSTEX_ENGINE_TOKEN) {
                        if (token_is_effective_category(
                                engine, second,
                                (uint8_t)HSTEX_CAT_MATH_SHIFT)) {
                            if (begin_display_math(engine, error,
                                                   error_capacity) != 0) {
                                return HSTEX_ENGINE_ERROR;
                            }
                            continue;
                        }
                        if (push_one(engine, second, where, error,
                                     error_capacity) != 0) {
                            return HSTEX_ENGINE_ERROR;
                        }
                    }
                }
                if (begin_math(engine, error, error_capacity) != 0) {
                    return HSTEX_ENGINE_ERROR;
                }
                continue;
            }
            if (token_is_category(*token, HSTEX_CAT_BEGIN_GROUP)) {
                /* A brace ends the run of characters a ligature or a kern is
                   made across, opening one as much as closing one: the
                   reference sets `f{f}' as two letters and `A{V}' with no
                   kern between them. See docs/DECISIONS.md,
                   a-brace-ends-a-run-of-characters. */
                if (flush_pending_character(engine, error, error_capacity) !=
                    0) {
                    return HSTEX_ENGINE_ERROR;
                }
                if (engine->mode == HSTEX_MODE_MATH &&
                    begin_math_group(engine, error, error_capacity) != 0) {
                    return HSTEX_ENGINE_ERROR;
                }
                if (begin_group(engine, HSTEX_GROUP_BRACE, error, error_capacity) != 0) {
                    return HSTEX_ENGINE_ERROR;
                }
                continue;
            }
            if (token_is_category(*token, HSTEX_CAT_END_GROUP)) {
                /* A brace that would close an alignment entry's own group
                   closes nothing a document opened: the reference guesses a
                   \cr instead. */
                if (current_group_kind(engine) == HSTEX_GROUP_ALIGN) {
                    if (insert_missing_cr(engine, *token, *location, error,
                                          error_capacity) != 0) {
                        return HSTEX_ENGINE_ERROR;
                    }
                    continue;
                }
                /* A brace where \endgroup belongs is deleted, in the same
                   words the reference uses for one inside a formula. */
                if (current_group_kind(engine) == HSTEX_GROUP_SEMI_SIMPLE) {
                    static const char *const spurious[] = {
                        "I've deleted a group-closing symbol because it seems to be",
                        "spurious, as in `$x}$'. But perhaps the } is legitimate and",
                        "you forgot something else, as in `\\hbox{$x}'. In such cases",
                        "the way to recover is to insert both the forgotten and the",
                        "deleted material, e.g., by typing `I$}'.", NULL};
                    tex_error(engine, spurious,
                              "Extra }, or forgotten \\endgroup");
                    continue;
                }
                if (engine->mode == HSTEX_MODE_MATH) {
                    int closed =
                        finish_math_group(engine, error, error_capacity);
                    if (closed < 0) {
                        return HSTEX_ENGINE_ERROR;
                    }
                    /* A brace that closed nothing was deleted, so no group
                       ends here either. */
                    if (closed > 0) {
                        continue;
                    }
                }
                /* A brace that ends a box body ends the paragraph inside it
                   first, while the parameters that paragraph was set with
                   are still in force. */
                if (engine->building_paragraph && engine->group_stop_armed &&
                    engine->group_level == engine->group_stop_level + 1U &&
                    finish_paragraph(engine, error, error_capacity) != 0) {
                    return HSTEX_ENGINE_ERROR;
                }
                /* Read here, while the group's own bindings are still in
                   force: an insertion records what these were inside its
                   braces, not outside them. */
                if (engine->group_stop_armed &&
                    engine->group_level == engine->group_stop_level + 1U) {
                    engine->closing_split_top_skip =
                        engine->glue_parameters[HSTEX_GLUE_SPLIT_TOP_SKIP];
                    engine->closing_split_max_depth =
                        engine->dimen_parameters[HSTEX_DIMEN_SPLIT_MAX_DEPTH];
                    engine->closing_float_cost =
                        engine->integer_parameters
                            [HSTEX_INTEGER_FLOATING_PENALTY];
                }
                /* THE `}' THAT CLOSES AN OUTPUT ROUTINE ends it, and what
                   the routine's text still has to give is material its own
                   braces do not account for. The reference says so unless
                   the closer was the last token of that text, or the last of
                   a list something put back -- a number scan reading one
                   digit too far puts the `}' back, and that is not the
                   routine's fault. */
                bool closing_output =
                    current_group_kind(engine) == HSTEX_GROUP_OUTPUT;
                if (closing_output) {
                    bool unbalanced = true;
                    if (engine->sources.count != 0U) {
                        const struct hstex_source_frame *frame =
                            &engine->sources
                                 .frames[engine->sources.count - 1U];
                        if (frame->kind == HSTEX_SOURCE_TOKEN_LIST) {
                            const struct hstex_token_source *list =
                                &frame->value.token_list;
                            unbalanced =
                                list->cursor < list->count ||
                                !(list->source_kind ==
                                      (uint8_t)
                                          HSTEX_TOKEN_SOURCE_BACKED_UP ||
                                  (list->source_kind ==
                                       (uint8_t)
                                           HSTEX_TOKEN_SOURCE_TOKEN_PARAMETER &&
                                   list->frame_name ==
                                       (uint32_t)HSTEX_TOKEN_OUTPUT));
                        }
                    }
                    engine->output_group_unbalanced = unbalanced;
                    if (unbalanced) {
                        static const char *const sneaky[] = {
                            "Your sneaky output routine has problematic {'s "
                            "and/or }'s.",
                            "I can't handle that very well; good luck.",
                            NULL};
                        tex_error(engine, sneaky, "Unbalanced output routine");
                    }
                }
                /* WHAT \boxmaxdepth SAYS INSIDE A BOX is what limits it,
                   and it is taken BEFORE the box's own group is closed --
                   which is here, one step before the restore. See
                   docs/DECISIONS.md, what-boxmaxdepth-is-read-when. */
                if (engine->group_stop_armed &&
                    engine->group_level <= engine->group_stop_level + 1U &&
                    engine->active_vbox_builder != NULL) {
                    engine->active_vbox_builder->max_depth =
                        engine->dimen_parameters[HSTEX_DIMEN_BOX_MAX_DEPTH];
                    engine->active_vbox_builder->max_depth_known = true;
                }
                if (end_group(engine, error, error_capacity) < 0) {
                    return HSTEX_ENGINE_ERROR;
                }
                if (closing_output) {
                    /* The routine is over: what its text still holds is not
                       material for the list it was building. */
                    engine->output_group_closed = true;
                    return HSTEX_ENGINE_EOF;
                }
                /* A box body is executed on the live input; when the group it
                   opened closes, the box is complete and the builder takes
                   over again. */
                if (engine->group_stop_armed &&
                    engine->group_level <= engine->group_stop_level) {
                    engine->group_stop_hit = true;
                    return HSTEX_ENGINE_EOF;
                }
                continue;
            }
            if ((engine->pending_global || engine->pending_macro_flags != 0U) &&
                token_is_space(*token)) {
                continue;
            }
            if (engine->pending_global || engine->pending_macro_flags != 0U) {
                (void)set_error(error, error_capacity,
                                "definition prefix followed by a character");
                return HSTEX_ENGINE_ERROR;
            }
            /* Inside a formula a character is an atom, not something the
               enclosing list builder should see. Spaces are ignored. */
            if (engine->mode == HSTEX_MODE_MATH) {
                if (token_is_space(*token)) {
                    continue;
                }
                if (token_is_category(*token, HSTEX_CAT_SUPERSCRIPT) ||
                    token_is_category(*token, HSTEX_CAT_SUBSCRIPT)) {
                    if (begin_math_script(
                            engine,
                            token_is_category(*token, HSTEX_CAT_SUPERSCRIPT),
                            error, error_capacity) != 0) {
                        return HSTEX_ENGINE_ERROR;
                    }
                    continue;
                }
                /* A mathcode of "8000 makes the character behave as an
                   active one; see docs/DECISIONS.md, math-active. */
                int table = code_table_index(HSTEX_COMMAND_MATH_CODE);
                uint8_t character = hstex_token_character_code(*token);
                if (table >= 0 &&
                    engine->code_tables[(size_t)table][character] == 0x8000) {
                    hstex_cs_id active = 0U;
                    if (hstex_symbol_intern(&engine->lexical_state.symbols,
                                            HSTEX_SYMBOL_ACTIVE, &character,
                                            1U, &active, error,
                                            error_capacity) != 0 ||
                        reserve_meanings(engine, (size_t)active, error,
                                         error_capacity) != 0 ||
                        push_one(engine,
                                 hstex_token_control_sequence(active),
                                 *location, error, error_capacity) != 0) {
                        return HSTEX_ENGINE_ERROR;
                    }
                    continue;
                }
                if (math_append_character(engine, character, error,
                                          error_capacity) != 0) {
                    return HSTEX_ENGINE_ERROR;
                }
                continue;
            }
            return HSTEX_ENGINE_TOKEN;
        }

        const struct hstex_meaning *meaning = hstex_engine_meaning(
            engine, hstex_token_control_sequence_id(*token));
        /* THE TOKEN AN ALIGNMENT TEMPLATE ENDS WITH. The reference reads it
           the way it reads anything else -- so a macro called at the end of
           an entry can take it as an argument, and the context names it --
           and what it stands for is the end of the entry's material. It is
           not traced for itself: what the reference traces is the \endv it
           turns into, which the entry's own ending writes. */
        if (meaning->command == HSTEX_COMMAND_END_TEMPLATE &&
            engine->alignment_entry != NULL &&
            engine->alignment_entry->after_pushed) {
            return HSTEX_ENGINE_EOF;
        }
        /* Anything that is not a character ends the pair the ligature and
           kerning program was waiting on -- but a control sequence that
           stands for a character is a character, and goes on with the word
           rather than ending it. See docs/DECISIONS.md,
           a-chardef-inside-a-word. */
        /* A tab or \cr that ends an alignment entry does not end the run of
           characters: the template's own text after the entry carries on
           from it, so `\halign{#Y\cr A\cr}' kerns the A against the Y just
           as `\hbox{AY}' does. */
        bool ends_an_entry =
            (meaning->command == HSTEX_COMMAND_CR ||
             meaning->command == HSTEX_COMMAND_SPAN) &&
            /* One that came from a template ends nothing and IS traced, the
               way any command the main loop obeyed is. */
            !engine->alignment_token_from_template &&
            engine->alignment_entry != NULL &&
            !engine->alignment_entry->after_pushed;
        if (engine->has_pending_character && !ends_an_entry &&
            meaning->command != HSTEX_COMMAND_CHAR_GIVEN &&
            meaning->command != HSTEX_COMMAND_CHAR &&
            /* \\noboundary ends the word itself, and without the character
               beyond its right end, so it must not be ended here first. */
            meaning->command != HSTEX_COMMAND_NO_BOUNDARY &&
            flush_pending_character(engine, error, error_capacity) != 0) {
            return HSTEX_ENGINE_ERROR;
        }
        if (engine->mode == HSTEX_MODE_VERTICAL &&
            !engine->pending_global && engine->pending_macro_flags == 0U &&
            command_starts_paragraph(meaning)) {
            /* Traced where it was met AND again once the paragraph has
               started, because it is read again there. Measured: `\valign'
               in vertical mode draws {\valign} and then
               {horizontal mode: \valign}, the way a character that begins a
               paragraph draws two lines. */
            trace_command(engine, *token);
            if (push_one(engine, *token, *location, error, error_capacity) !=
                    0 ||
                start_paragraph(engine, true, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        }
        if (engine->mode == HSTEX_MODE_HORIZONTAL &&
            engine->building_paragraph && !engine->pending_global &&
            engine->pending_macro_flags == 0U &&
            command_ends_paragraph(meaning)) {
            /* Traced here as well as after the \par, for the same reason. */
            trace_command(engine, *token);
            /* What goes in front of it is the \par token itself, so that
               whatever \par means at this moment is what runs; see
               docs/DECISIONS.md, ending-a-paragraph. */
            hstex_token paragraph = hstex_token_control_sequence(
                engine->lexical_state.paragraph_control_sequence);
            if (push_one(engine, *token, *location, error, error_capacity) !=
                    0 ||
                push_one(engine, paragraph, *location, error,
                         error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        }
        /* A math field that is neither a character nor a list gets a `{'
           in front of it, so that it becomes a list of its own. \relax is
           stepped over before the field is looked for, so it does not draw
           one. */
        if (meaning->command != HSTEX_COMMAND_RELAX &&
            math_field_is_wanted(engine) &&
            !token_can_be_math_field(engine, *token)) {
            if (insert_math_field_brace(engine, *token, *location, error,
                                        error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        }
        /* \immediate reads the command it stands in front of itself, so
           that command is not one the main loop obeyed and is not traced.
           Measured: \immediate\write and \immediate\openout draw one line
           where \immediate\special and \immediate\relax draw two, because
           those two are put back and met again here. A prefix reads what it
           prefixes the same way: `\global\count5=1' draws {\global} and
           nothing for the \count, and so do \long, \outer, a second
           prefix, and a \relax standing between. */
        if ((!engine->pending_global && engine->pending_macro_flags == 0U) &&
            /* And an alignment that stood in for a display, and an \accent
               waiting for its character, read the assignments in front of
               them themselves, so those are not traced either. */
            !engine->display_alignment && !engine->accent_pending &&
            /* A tab or \cr that ends an entry is taken by the scanner, on
               its way to putting the template's other half in front of what
               follows -- it is never a command the main loop obeyed, so it
               draws no line however it was reached. */
            !ends_an_entry &&
            (!engine->immediate_pending ||
            (meaning->command != (int)HSTEX_COMMAND_WRITE &&
             meaning->command != (int)HSTEX_COMMAND_OPEN_OUT &&
             meaning->command != (int)HSTEX_COMMAND_CLOSE_OUT))) {
            trace_command(engine, *token);
            engine->command_traced = true;
        }
        record_executing_name(engine, *token);
        /* \immediate reaches exactly as far as the command it stands in
           front of; see docs/DECISIONS.md, whatsits. */
        bool immediate = engine->immediate_pending;
        engine->immediate_pending = false;
        switch (meaning->command) {
        case HSTEX_COMMAND_END_TEMPLATE:
            /* Only a lookahead ever sees this, and a lookahead puts it
               nowhere: an entry ends at its own boundary here rather than
               by a token being obeyed. Reached only if a document \let
               something to what it looked at and then wrote that. */
            continue;
        case HSTEX_COMMAND_RELAX:
            /* \relax stands between a prefix and what it prefixes without
               spending it: the reference carries \global past a \relax and
               complains about whatever comes after. */
            continue;
        case HSTEX_COMMAND_DEF:
            if (finish_assignment(
                    engine,
                    scan_definition(engine, false, false, error,
                                    error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_GDEF:
            if (finish_assignment(
                    engine,
                    scan_definition(engine, true, false, error,
                                    error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_EDEF:
            if (finish_assignment(
                    engine,
                    scan_definition(engine, false, true, error,
                                    error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_XDEF:
            if (finish_assignment(
                    engine,
                    scan_definition(engine, true, true, error,
                                    error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_LET:
            if (finish_assignment(engine,
                                  scan_let(engine, error, error_capacity), error,
                                  error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_FUTURE_LET:
            if (finish_assignment(
                    engine, scan_future_let(engine, error, error_capacity), error,
                    error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_AFTER_ASSIGNMENT:
            if (scan_after_assignment(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_AFTER_GROUP:
            if (scan_after_group(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_LONG:
            engine->pending_macro_flags |= (uint8_t)HSTEX_MACRO_LONG;
            continue;
        case HSTEX_COMMAND_OUTER:
            engine->pending_macro_flags |= (uint8_t)HSTEX_MACRO_OUTER;
            continue;
        case HSTEX_COMMAND_PROTECTED:
            engine->pending_macro_flags |= (uint8_t)HSTEX_MACRO_PROTECTED;
            continue;
        case HSTEX_COMMAND_GLOBAL:
            engine->pending_global = true;
            continue;
        case HSTEX_COMMAND_UNLESS:
            if (expand_unless(engine, *location, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_BEGIN_GROUP:
            if (begin_group(engine, HSTEX_GROUP_SEMI_SIMPLE, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_END_GROUP:
            if (engine->group_level == 0U) {
                static const char *const spare[] = {
                    "Things are pretty mixed up, but I think the worst is over.",
                    NULL};
                tex_error(engine, spare, "Extra \\endgroup");
                continue;
            }
            /* A group of another kind is closed the way it opened, and the
               \endgroup is then read again. */
            if (current_group_kind(engine) != HSTEX_GROUP_SEMI_SIMPLE) {
                if (off_save(engine, *token, *location, error,
                             error_capacity) != 0) {
                    return HSTEX_ENGINE_ERROR;
                }
                continue;
            }
            if (end_group(engine, error, error_capacity) < 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_LOWER_CASE:
        case HSTEX_COMMAND_UPPER_CASE:
            if (execute_case_shift(
                    engine,
                    meaning->command == HSTEX_COMMAND_LOWER_CASE ? 1U : 2U,
                    *location, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_IGNORE_SPACES:
            if (engine->pending_global || engine->pending_macro_flags != 0U) {
                return (enum hstex_engine_result)set_error(
                    error, error_capacity,
                    "definition prefix followed by ignorespaces");
            }
            if (execute_ignore_spaces(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_INTERACTION_MODE:
            if (meaning->value.integer < (int32_t)HSTEX_INTERACTION_BATCH ||
                meaning->value.integer >
                    (int32_t)HSTEX_INTERACTION_ERROR_STOP ||
                engine->pending_global || engine->pending_macro_flags != 0U) {
                return (enum hstex_engine_result)set_error(
                    error, error_capacity, "invalid interaction-mode command");
            }
            /* A line ends where the mode changes, whatever stands on it and
               even where nothing does: `\message{one}\nonstopmode
               \nonstopmode\message{three}' writes `one', a blank line, and
               `three'. trip changes the mode four times. */
            print_line(engine);
            engine->interaction_mode =
                (enum hstex_interaction_mode)meaning->value.integer;
            continue;
        case HSTEX_COMMAND_DUMP:
            if (engine->pending_global || engine->pending_macro_flags != 0U ||
                engine->group_level != 0U ||
                engine->conditional_count != 0U) {
                return (enum hstex_engine_result)set_error(
                    error, error_capacity, "dump requested in nested state");
            }
            engine->dump_requested = true;
            if (report_the_dump(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            return HSTEX_ENGINE_EOF;
        case HSTEX_COMMAND_CAT_CODE:
            if (finish_assignment(
                    engine, scan_catcode_assignment(engine, error, error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_SF_CODE:
        case HSTEX_COMMAND_LC_CODE:
        case HSTEX_COMMAND_UC_CODE:
        case HSTEX_COMMAND_MATH_CODE:
        case HSTEX_COMMAND_DEL_CODE:
            if (finish_assignment(
                    engine,
                    scan_code_assignment(engine, meaning->command, error,
                                         error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_CHAR_DEF:
            if (finish_assignment(
                    engine, scan_char_definition(engine, error, error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_MATH_FONT:
            if (execute_math_font(engine, meaning->value.integer, error,
                                  error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_MATH_CHAR:
            if (execute_math_char(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_MATH_CLASS:
            if (execute_math_class(engine, meaning->value.integer, error,
                                   error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_MATH_STYLE:
            if (execute_math_style(engine, meaning->value.integer, error,
                                   error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_MATH_CHOICE:
            if (execute_math_choice(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_DELIMITER:
            if (execute_delimiter(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_LEFT_RIGHT:
            if (execute_left_right(engine, meaning->value.integer, error,
                                   error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_ACCENT:
            if (execute_accent(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_VCENTER:
            if (execute_vcenter(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_MARK:
            if (execute_mark(engine, meaning->value.integer != 0, error,
                             error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_INSERT:
            if (execute_insert(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_MARK_TEXT:
            /* Expandable: it should never reach the list builder. */
            return HSTEX_ENGINE_TOKEN;
        case HSTEX_COMMAND_EQUATION_NUMBER:
            if (execute_equation_number(engine, meaning->value.integer != 0,
                                        error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_SET_LANGUAGE:
            if (execute_set_language(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_NO_BOUNDARY:
            /* The word before it ends without the character beyond its right
               end, and the word after it begins without the one beyond its
               left end. See docs/DECISIONS.md, boundary-characters. */
            engine->cancel_boundary = true;
            if (flush_pending_character(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            /* Only a character that actually follows has its left boundary
               cancelled; the reference looks to see. */
            {
                hstex_token next = 0U;
                struct hstex_source_location where;
                enum hstex_engine_result got = hstex_engine_next_expanded(
                    engine, &next, &where, error, error_capacity);
                if (got == HSTEX_ENGINE_ERROR) {
                    return HSTEX_ENGINE_ERROR;
                }
                if (got == HSTEX_ENGINE_TOKEN) {
                    engine->cancel_boundary = character_follows(engine, next);
                    if (push_one(engine, next, where, error,
                                 error_capacity) != 0) {
                        return HSTEX_ENGINE_ERROR;
                    }
                }
            }
            continue;
        case HSTEX_COMMAND_HALIGN:
        case HSTEX_COMMAND_VALIGN:
            if (engine->mode == HSTEX_MODE_MATH) {
                /* Only a display may hold an alignment, and only from its
                   own list. A { in math makes the mode internal, and there
                   -- as in any inline formula -- the reference refuses the
                   alignment outright rather than closing anything. */
                if (!engine->displayed_math || engine->reading_equation_number ||
                    engine->math_depth != engine->math_floor + 1U) {
                    report_illegal_case(engine, *token);
                    continue;
                }
                /* An alignment stands for a whole display, so it can only
                   begin from the display's own group; a \begingroup opened
                   inside the display is closed first and the alignment read
                   again. */
                if (current_group_kind(engine) != HSTEX_GROUP_MATH_SHIFT) {
                    if (off_save(engine, *token, *location, error,
                                 error_capacity) != 0) {
                        return HSTEX_ENGINE_ERROR;
                    }
                    continue;
                }
            }
            if (meaning->command == HSTEX_COMMAND_HALIGN &&
                engine->mode == HSTEX_MODE_HORIZONTAL && engine->inner_mode) {
                if (off_save(engine, *token, *location, error,
                             error_capacity) != 0) {
                    return HSTEX_ENGINE_ERROR;
                }
                continue;
            }
            if (execute_alignment(engine,
                                  meaning->command == HSTEX_COMMAND_VALIGN,
                                  error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_CR:
        case HSTEX_COMMAND_SPAN:
            /* One that came from a TEMPLATE divides nothing; see the tab
               above. */
            if (engine->alignment_token_from_template) {
                report_misplaced(engine, *token, misplaced_tab_help);
                continue;
            }
            /* A tab or \cr ends the entry from wherever it turns up, which
               may be inside a box the entry's template opened. */
            if (engine->alignment_entry != NULL &&
                !engine->alignment_entry->after_pushed) {
                if (end_alignment_entry(
                        engine,
                        meaning->command == HSTEX_COMMAND_SPAN
                            ? HSTEX_ALIGN_END_SPAN
                            : HSTEX_ALIGN_END_CR,
                        error, error_capacity) != 0) {
                    return HSTEX_ENGINE_ERROR;
                }
                continue;
            }
            if (!engine->building_alignment) {
                report_misplaced(engine, *token, misplaced_tab_help);
                continue;
            }
            return HSTEX_ENGINE_TOKEN;
        case HSTEX_COMMAND_NO_ALIGN:
        case HSTEX_COMMAND_OMIT:
            /* These belong to an alignment, which reads them itself. */
            if (!engine->building_alignment) {
                report_misplaced(engine, *token,
                                 meaning->command == HSTEX_COMMAND_NO_ALIGN
                                     ? misplaced_noalign_help
                                     : misplaced_omit_help);
                continue;
            }
            return HSTEX_ENGINE_TOKEN;
        case HSTEX_COMMAND_MATH_LIMITS: {
            /* \limits and its two companions belong to the large operator
               just read; see docs/DECISIONS.md, large-operators. */
            struct hstex_math_builder *builder = current_math_list(engine);
            if (engine->mode != HSTEX_MODE_MATH || builder == NULL ||
                builder->count == 0U ||
                builder->noads[builder->count - 1U].atom_class !=
                    (uint8_t)HSTEX_ATOM_OP) {
                /* The reference ignores one that follows no operator.
                   trip line 276 writes \displaylimits after a fraction. */
                static const char *const help[] = {
                    "I'm ignoring this misplaced \\limits or \\nolimits command.",
                    NULL};
                tex_error(engine, help,
                          "Limit controls must follow a math operator");
                continue;
            }
            /* The primitives are numbered nolimits, limits, displaylimits;
               the noad keeps 0 for the last of those, which is what an
               operator does anyway. */
            builder->noads[builder->count - 1U].limits =
                meaning->value.integer == 1
                    ? 1U
                    : (meaning->value.integer == 0 ? 2U : 0U);
            continue;
        }
        case HSTEX_COMMAND_MATH_SKIP:
        case HSTEX_COMMAND_MATH_KERN:
            if (execute_math_skip(engine,
                                  meaning->command == HSTEX_COMMAND_MATH_KERN,
                                  error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_MATH_CHAR_DEF:
            if (finish_assignment(
                    engine,
                    scan_math_char_definition(engine, error, error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_PATTERNS:
        case HSTEX_COMMAND_HYPHENATION:
            if (finish_assignment(
                    engine,
                    scan_hyphen_data(
                        engine, meaning->command == HSTEX_COMMAND_PATTERNS,
                        error, error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_COUNT_DEF:
            if (finish_assignment(
                    engine, scan_count_definition(engine, error, error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_DIMEN_DEF:
            if (finish_assignment(
                    engine,
                    scan_register_definition(engine, HSTEX_COMMAND_DIMEN_REGISTER,
                                             error, error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_SKIP_DEF:
            if (finish_assignment(
                    engine,
                    scan_register_definition(engine, HSTEX_COMMAND_SKIP_REGISTER,
                                             error, error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_MUSKIP_DEF:
            if (finish_assignment(
                    engine,
                    scan_register_definition(engine, HSTEX_COMMAND_MUSKIP_REGISTER,
                                             error, error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_TOKS_DEF:
            if (finish_assignment(
                    engine,
                    scan_register_definition(engine, HSTEX_COMMAND_TOKS_REGISTER,
                                             error, error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_FONT:
            if (finish_assignment(
                    engine, scan_font_definition(engine, error, error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_SET_BOX:
            if (finish_assignment(
                    engine, execute_set_box(engine, error, error_capacity), error,
                    error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_HBOX:
        case HSTEX_COMMAND_VBOX:
        case HSTEX_COMMAND_VTOP:
        case HSTEX_COMMAND_VSPLIT:
        case HSTEX_COMMAND_LAST_BOX:
            if (execute_box_constructor(engine, meaning->command, error,
                                        error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_FONT_CHAR_CODE:
            if (finish_assignment(
                    engine,
                    scan_font_char_code_assignment(
                        engine, meaning->value.integer, error, error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_FONT_CHAR_DIMEN:
            return (enum hstex_engine_result)set_error(
                error, error_capacity,
                "font character dimensions cannot be assigned");
        case HSTEX_COMMAND_MARGIN_KERN:
            return (enum hstex_engine_result)set_error(
                error, error_capacity, "a margin kern cannot be assigned");
        case HSTEX_COMMAND_BOX_DIMEN:
            if (finish_assignment(
                    engine,
                    scan_box_dimen_assignment(engine, meaning->value.integer,
                                              error, error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_SHIFT_BOX:
            if (execute_shift_box(engine, meaning->value.integer, error,
                                  error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_UNBOX:
            if ((meaning->value.integer == (int32_t)HSTEX_UNBOX_VERTICAL ||
                 meaning->value.integer ==
                     (int32_t)HSTEX_UNBOX_VERTICAL_COPY) &&
                engine->mode == HSTEX_MODE_HORIZONTAL && engine->inner_mode) {
                if (off_save(engine, *token, *location, error,
                             error_capacity) != 0) {
                    return HSTEX_ENGINE_ERROR;
                }
                continue;
            }
            if (execute_unbox(engine, meaning->value.integer, error,
                              error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_BOX:
        case HSTEX_COMMAND_COPY:
            if (execute_box_reference(engine, meaning->command, error,
                                      error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_SPACE_FACTOR: {
            if (engine->mode != HSTEX_MODE_HORIZONTAL) {
                /* Nothing is read, so the value stands as text; see
                   scan_prev_depth_assignment. */
                report_illegal_case(engine, engine->executing_token);
                engine->pending_global = false;
                engine->pending_macro_flags = 0U;
                continue;
            }
            int32_t factor = 0;
            if (finish_assignment(
                    engine,
                    scan_optional_equals(engine, error, error_capacity) != 0 ||
                            scan_integer(engine, &factor, error,
                                         error_capacity) != 0
                        ? -1
                        : 0,
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            if (factor <= 0 || factor > 32767) {
                /* Reported and replaced by the ordinary one, not refused:
                   trip line 289 writes `\spacefactor=0'. Nothing is put
                   back, so the context names only the line. */
                static const char *const help[] = {
                    "I allow only values in the range 1..32767 here.", NULL};
                tex_error(engine, help, "Bad space factor (%d)", factor);
                factor = 1000;
            }
            engine->space_factor = factor;
            engine->pending_global = false;
            engine->pending_macro_flags = 0U;
            continue;
        }
        case HSTEX_COMMAND_PREV_GRAF: {
            int32_t lines = 0;
            if (finish_assignment(
                    engine,
                    scan_optional_equals(engine, error, error_capacity) != 0 ||
                            scan_integer(engine, &lines, error,
                                         error_capacity) != 0
                        ? -1
                        : 0,
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            if (lines < 0) {
                /* Named and ignored: the reference leaves \prevgraf as it
                   was. */
                static const char *const help[] = {
                    "I allow only nonnegative values here.", NULL};
                tex_error(engine, help, "Bad \\prevgraf (%d)", lines);
            } else {
                /* \prevgraf BELONGS TO THE NEAREST VERTICAL LIST, not to the
                   one the assignment stands in: the reference walks out of
                   boxes, formulas and horizontal lists until it meets a list
                   being built in vertical mode, and counts the lines there.
                   See docs/DECISIONS.md, where-a-line-count-is-kept. */
                nest_note(engine);
                size_t at = engine->nest_count;
                while (at != 0U && engine->nest[at - 1U].mode !=
                                       (uint8_t)HSTEX_MODE_VERTICAL) {
                    --at;
                }
                engine->prev_graf = lines;
                if (at != 0U) {
                    engine->nest[at - 1U].prev_graf = lines;
                }
            }
            /* The prefix this assignment may have carried is spent. */
            engine->pending_global = false;
            engine->pending_macro_flags = 0U;
            continue;
        }
        case HSTEX_COMMAND_REMOVE_LAST:
            if (execute_remove_last(engine, meaning->value.integer, error,
                                    error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_CONTROL_SPACE:
            if (execute_control_space(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_DISCRETIONARY:
            if (execute_discretionary(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_DISCRETIONARY_HYPHEN:
            if (execute_discretionary_hyphen(engine, error, error_capacity) !=
                0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_ITALIC_CORRECTION:
            if (execute_italic_correction(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_CHAR:
            if (execute_char(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_INDENT:
            if (execute_indent(engine, meaning->value.integer != 0, error,
                               error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_VSKIP:
        case HSTEX_COMMAND_HSKIP:
            /* A vertical command met inside an \hbox. The reference closes
               the box -- "Missing } inserted" -- and reads the command
               again, so it does what it came to do in the mode outside.
               Measured: `\hbox{A\vfill B}' sets a box holding the A alone,
               then the \vfill, then a paragraph for the B, and the source's
               own } is left over as "Too many }'s". */
            if (meaning->command == HSTEX_COMMAND_VSKIP &&
                engine->mode == HSTEX_MODE_HORIZONTAL && engine->inner_mode) {
                if (off_save(engine, *token, *location, error,
                             error_capacity) != 0) {
                    return HSTEX_ENGINE_ERROR;
                }
                continue;
            }
            if (execute_glue(engine, meaning->value.integer,
                             meaning->command == HSTEX_COMMAND_VSKIP, error,
                             error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_LEADERS:
            if (execute_leaders(engine, meaning->value.integer, error,
                                error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_PENALTY:
            if (execute_penalty(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_VRULE:
            if (execute_vrule(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_HRULE:
            /* Unlike the other vertical commands, a rule closes nothing:
               the reference names it and goes on with the horizontal list
               it was already building. */
            if (engine->mode == HSTEX_MODE_HORIZONTAL) {
                static const char *const rule_help[] = {
                    "To put a horizontal rule in an hbox or an alignment,",
                    "you should use \\leaders or \\hrulefill (see The "
                    "TeXbook).", NULL};
                tex_error(engine, rule_help,
                          "You can't use `\\hrule' here except with leaders");
                continue;
            }
            if (execute_hrule(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_KERN:
            if (execute_kern(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_PDF_CATALOG:
        case HSTEX_COMMAND_PDF_INFO:
            if (execute_pdf_dictionary(
                    engine, meaning->command == HSTEX_COMMAND_PDF_CATALOG,
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_PDF_TRAILER_ID:
            if (execute_pdf_trailer_id(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_PDF_OBJECT:
            if (execute_pdf_object(engine, immediate, error, error_capacity) !=
                0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_PDF_FONT_ATTRIBUTE:
            if (finish_assignment(
                    engine,
                    execute_pdf_font_attribute(engine, error, error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_PDF_NO_BUILTIN_TO_UNICODE:
            if (finish_assignment(
                    engine,
                    execute_pdf_no_builtin_to_unicode(engine, error,
                                                      error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_PDF_REF_OBJECT:
            if (execute_pdf_ref_object(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_PDF_LITERAL:
            if (execute_pdf_literal(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_PDF_SAVE:
        case HSTEX_COMMAND_PDF_SET_MATRIX:
        case HSTEX_COMMAND_PDF_RESTORE: {
            uint8_t kind = meaning->command == HSTEX_COMMAND_PDF_SAVE
                               ? (uint8_t)HSTEX_WHATSIT_PDF_SAVE
                               : meaning->command == HSTEX_COMMAND_PDF_SET_MATRIX
                                     ? (uint8_t)HSTEX_WHATSIT_PDF_SET_MATRIX
                                     : (uint8_t)HSTEX_WHATSIT_PDF_RESTORE;
            if (execute_pdf_transform(engine, kind, error, error_capacity) !=
                0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        }
        case HSTEX_COMMAND_PDF_DEST:
            if (execute_pdf_dest(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_PDF_START_LINK:
            if (execute_pdf_start_link(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_PDF_END_LINK:
            if (execute_pdf_end_link(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_PDF_OUTLINE:
            if (execute_pdf_outline(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_PDF_XFORM:
            if (execute_pdf_xform(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_PDF_ANNOT:
            if (execute_pdf_annot(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_PDF_COLOR_STACK:
            if (execute_pdf_color_stack(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_PDF_LAST_NUMBER:
            return (enum hstex_engine_result)set_error(
                error, error_capacity, "pdf counters cannot be assigned");
        case HSTEX_COMMAND_LAST_ITEM:
            return (enum hstex_engine_result)set_error(
                error, error_capacity, "last-item queries cannot be assigned");
        case HSTEX_COMMAND_FONT_DIMEN:
            if (finish_assignment(
                    engine,
                    scan_font_dimen_assignment(engine, error, error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_HYPHEN_CHAR:
        case HSTEX_COMMAND_SKEW_CHAR:
            if (finish_assignment(
                    engine,
                    scan_font_integer_assignment(engine, meaning->command, error,
                                                 error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_TOKS_REGISTER:
            if (finish_assignment(
                    engine,
                    scan_token_register_assignment(
                        engine, meaning->value.integer, error, error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_TOKS:
            if (finish_assignment(
                    engine,
                    scan_token_family_assignment(engine, error, error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_TOKEN_PARAMETER:
            if (finish_assignment(
                    engine,
                    scan_token_parameter_assignment(
                        engine, meaning->value.integer, error, error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_COUNT:
            if (finish_assignment(
                    engine,
                    scan_count_family_assignment(engine, error, error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_COUNT_REGISTER:
            if (finish_assignment(
                    engine,
                    scan_count_assignment(engine, meaning->value.integer, error,
                                          error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_INTEGER_PARAMETER:
            if (finish_assignment(
                    engine,
                    scan_integer_parameter_assignment(
                        engine, meaning->value.integer, error, error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_PAGE_INTEGER:
            if (finish_assignment(
                    engine,
                    scan_page_integer_assignment(engine, meaning->value.integer,
                                                 error, error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_PAGE_DIMEN:
            if (finish_assignment(
                    engine,
                    scan_page_dimen_assignment(engine, meaning->value.integer,
                                               error, error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_DIMEN_REGISTER:
            if (finish_assignment(
                    engine,
                    scan_dimen_assignment(engine, meaning->value.integer, error,
                                          error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_DIMEN:
            if (finish_assignment(
                    engine,
                    scan_dimen_family_assignment(engine, error, error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_SKIP_REGISTER:
            if (finish_assignment(
                    engine,
                    scan_glue_assignment(engine, meaning->value.integer, error,
                                         error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_MUSKIP_REGISTER:
            if (finish_assignment(
                    engine,
                    scan_muglue_assignment(engine, meaning->value.integer, error,
                                           error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_SKIP:
            if (finish_assignment(
                    engine,
                    scan_glue_family_assignment(engine, error, error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_MUSKIP:
            if (finish_assignment(
                    engine,
                    scan_muglue_family_assignment(engine, error, error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_DIMEN_PARAMETER:
            if (finish_assignment(
                    engine,
                    scan_dimen_parameter_assignment(
                        engine, meaning->value.integer, error, error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_PREV_DEPTH:
            if (finish_assignment(
                    engine,
                    scan_prev_depth_assignment(engine, error, error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_GLUE_PARAMETER:
            if (finish_assignment(
                    engine,
                    scan_glue_parameter_assignment(
                        engine, meaning->value.integer, error, error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_MUGLUE_PARAMETER:
            if (finish_assignment(
                    engine,
                    scan_muglue_parameter_assignment(
                        engine, meaning->value.integer, error, error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_ADVANCE:
        case HSTEX_COMMAND_MULTIPLY:
        case HSTEX_COMMAND_DIVIDE:
            if (finish_assignment(
                    engine,
                    execute_arithmetic(engine, meaning->command, error,
                                       error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_IMMEDIATE:
            engine->immediate_pending = true;
            continue;
        case HSTEX_COMMAND_MESSAGE:
            if (execute_message(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_OPEN_OUT:
            if (execute_open_out(engine, immediate, error, error_capacity) !=
                0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_WRITE:
            if (execute_write(engine, immediate, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_CLOSE_OUT:
            if (execute_close_out(engine, immediate, error, error_capacity) !=
                0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_SPECIAL:
            if (execute_special(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_OPEN_IN:
            if (execute_open_in(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_READ:
            if (finish_assignment(engine,
                                  execute_read(engine, error, error_capacity),
                                  error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_READ_LINE:
            if (finish_assignment(
                    engine, execute_read_line(engine, error, error_capacity),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_CLOSE_IN:
            if (execute_close_in(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_IF_NUM:
            if (scan_if_num(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_IF_DIM:
            if (scan_if_dim(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_IF_H_MODE:
        case HSTEX_COMMAND_IF_V_MODE:
        case HSTEX_COMMAND_IF_M_MODE:
        case HSTEX_COMMAND_IF_INNER:
        case HSTEX_COMMAND_IF_IN_CS_NAME:
            if (start_conditional(
                    engine, mode_conditional_value(engine, meaning->command),
                    error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_IF_X:
            if (scan_if_x(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_IF_CHAR:
            if (scan_if_char(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_IF_CAT:
            if (scan_if_cat(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_IF_ODD:
            if (scan_if_odd(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_IF_CASE:
            if (scan_if_case(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_IF_FONT_CHAR:
            if (scan_if_font_char(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_IF_BOX:
            if (scan_if_box(engine, meaning->value.integer, error,
                            error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_IF_EOF:
            if (scan_if_eof(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_IF_DEFINED:
            if (scan_if_defined(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_IF_CS_NAME:
            if (scan_if_cs_name(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_IF_TRUE:
            if (start_conditional(engine, true, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_IF_FALSE:
            if (start_conditional(engine, false, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_ELSE: {
            if (execute_else(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        }
        case HSTEX_COMMAND_OR:
            if (execute_or(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_FI:
            if (execute_fi(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_TOKEN_ALIAS:
            *token = meaning->value.token;
            engine->command_traced = true;
            goto handle_token;
        case HSTEX_COMMAND_MACRO:
            return HSTEX_ENGINE_TOKEN;
        case HSTEX_COMMAND_CHAR_GIVEN:
            if (meaning->value.integer < 0 || meaning->value.integer > 255) {
                (void)set_error(error, error_capacity,
                                "invalid chardef meaning");
                return HSTEX_ENGINE_ERROR;
            }
            *token = hstex_token_character(
                (uint8_t)HSTEX_CAT_OTHER, (uint8_t)meaning->value.integer);
            engine->command_traced = true;
            goto handle_token;
        case HSTEX_COMMAND_MATH_CHAR_GIVEN:
            /* A \mathchardef is an atom wherever a \mathchar would be. */
            if (engine->mode == HSTEX_MODE_MATH) {
                if (math_append_code(engine, meaning->value.integer, error,
                                     error_capacity) != 0) {
                    return HSTEX_ENGINE_ERROR;
                }
                continue;
            }
            return HSTEX_ENGINE_TOKEN;
        case HSTEX_COMMAND_PAR_SHAPE:
            if (execute_parshape(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_FRACTION:
            if (execute_fraction(engine, meaning->value.integer, error,
                                 error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_OVER_UNDER_LINE:
            if (execute_over_under_line(engine, meaning->value.integer == 0,
                                        error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_VADJUST:
            if (execute_vadjust(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_SHOW_BOX:
            if (execute_show_box(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_SHOW:
            if (execute_show(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_SHOW_THE:
            if (execute_show_the(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_SHOW_LISTS:
            if (execute_show_lists(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_SHIP_OUT: {
            struct hstex_box shipped = {0};
            if (scan_box_operand(engine, &shipped, error, error_capacity) !=
                0) {
                return HSTEX_ENGINE_ERROR;
            }
            if (ship_out(engine, &shipped, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        }
        case HSTEX_COMMAND_NON_SCRIPT:
            if (execute_non_script(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_RADICAL:
            if (execute_radical(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_MATH_ACCENT:
            if (execute_math_accent(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_MATH_PRIMITIVE:
            return HSTEX_ENGINE_TOKEN;
        case HSTEX_COMMAND_FONT_GIVEN:
            if (meaning->value.integer <= 0 ||
                font_by_identifier(engine,
                                   (uint32_t)meaning->value.integer) == NULL) {
                return (enum hstex_engine_result)set_error(
                    error, error_capacity, "invalid font meaning");
            }
            if (select_font(engine, (uint32_t)meaning->value.integer, error,
                            error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            if (finish_assignment(engine, 0, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_PAR:
            /* A \par met while the entry it stands in has closed a brace it
               never opened is not a paragraph's end but an alignment's: the
               reference closes what is open and reads the \par again. trip
               line 409 is a blank line in exactly that state. */
            if (engine->alignment_entry != NULL &&
                !engine->alignment_entry->after_pushed &&
                engine->alignment_entry->nesting < 0) {
                if (off_save(engine, *token, *location, error,
                             error_capacity) != 0) {
                    return HSTEX_ENGINE_ERROR;
                }
                continue;
            }
            if (engine->building_paragraph) {
                if (finish_paragraph(engine, error, error_capacity) != 0) {
                    return HSTEX_ENGINE_ERROR;
                }
                continue;
            }
            /* \par in a vertical list clears the shape the next paragraph
               would otherwise inherit, AND runs the page builder -- so
               whatever is waiting to be contributed goes down at the \par
               rather than at whatever comes after it. trip line 389 reaches
               a \par through an \else in vertical mode. */
            if (engine->mode == HSTEX_MODE_VERTICAL &&
                (normal_paragraph(engine, error, error_capacity) != 0 ||
                 contribute_page(engine, error, error_capacity) != 0)) {
                return HSTEX_ENGINE_ERROR;
            }
            /* Inside an \hbox there is no paragraph to end and nothing to
               clear, and the reference says nothing at all about it. */
            if (engine->mode == HSTEX_MODE_HORIZONTAL && engine->inner_mode) {
                continue;
            }
            return HSTEX_ENGINE_TOKEN;
        case HSTEX_COMMAND_UNDEFINED:
            report_undefined_control_sequence(engine);
            continue;
        case HSTEX_COMMAND_EXPAND_AFTER:
        case HSTEX_COMMAND_NO_EXPAND:
        case HSTEX_COMMAND_CS_NAME:
        case HSTEX_COMMAND_EXPANDED:
        case HSTEX_COMMAND_UNEXPANDED:
        case HSTEX_COMMAND_DETOKENIZE:
        case HSTEX_COMMAND_PDF_FILE_MOD_DATE:
        case HSTEX_COMMAND_PDF_FILE_SIZE:
        case HSTEX_COMMAND_PDF_MD5_SUM:
        case HSTEX_COMMAND_PDF_STRING_COMPARE:
        case HSTEX_COMMAND_SCAN_TOKENS:
        case HSTEX_COMMAND_PDF_COLOR_STACK_INIT:
        case HSTEX_COMMAND_PDF_MATCH:
        case HSTEX_COMMAND_PDF_LAST_MATCH:
        case HSTEX_COMMAND_PDF_ESCAPE_STRING:
        case HSTEX_COMMAND_PDF_ESCAPE_NAME:
        case HSTEX_COMMAND_PDF_ESCAPE_HEX:
        case HSTEX_COMMAND_PDF_UNESCAPE_HEX:
        case HSTEX_COMMAND_PDF_CREATION_DATE:
        case HSTEX_COMMAND_PDF_PAGE_REF:
        case HSTEX_COMMAND_PDF_UNIFORM_DEVIATE:
        case HSTEX_COMMAND_E_TEX_REVISION:
        case HSTEX_COMMAND_PDF_TEX_REVISION:
        case HSTEX_COMMAND_THE:
        case HSTEX_COMMAND_NUMBER:
        case HSTEX_COMMAND_ROMAN_NUMERAL:
        case HSTEX_COMMAND_MEANING:
        case HSTEX_COMMAND_STRING:
        case HSTEX_COMMAND_JOB_NAME:
        case HSTEX_COMMAND_FONT_NAME:
            return (enum hstex_engine_result)set_error(
                error, error_capacity, "expandable primitive escaped expansion");
        case HSTEX_COMMAND_END_CS_NAME: {
            static const char *const help[] = {
                "I'm ignoring this, since I wasn't doing a \\csname.", NULL};
            tex_error(engine, help, "Extra \\endcsname");
            continue;
        }
        case HSTEX_COMMAND_INPUT:
            if (execute_input(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_PDF_GLYPH_TO_UNICODE:
            if (execute_pdf_glyph_to_unicode(engine, error, error_capacity) !=
                0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_PDF_SET_RANDOM_SEED:
            if (execute_pdf_set_random_seed(engine, error, error_capacity) !=
                0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_END:
            /* Inside a box there is no job to finish. In a RESTRICTED
               horizontal list the reference closes the box and reads the
               \end again -- "Missing } inserted" -- the way it does for a
               vertical command met there; in an INTERNAL vertical list it
               names the mode and drops it. trip line 442 ends inside an
               \hbox. */
            if (engine->mode == HSTEX_MODE_HORIZONTAL && engine->inner_mode) {
                if (off_save(engine, *token, *location, error,
                             error_capacity) != 0) {
                    return HSTEX_ENGINE_ERROR;
                }
                continue;
            }
            if (engine->mode == HSTEX_MODE_VERTICAL &&
                engine->active_vbox_builder != engine->contribution_builder) {
                report_illegal_case(engine, *token);
                continue;
            }
            /* \end finishes the job only once the page and what is waiting
               for it are empty and no output cycle is pending. Otherwise it
               is read again behind material that forces the last pages out;
               see docs/DECISIONS.md, the-output-routine. */
            if (engine->page_builder->count == 0U &&
                engine->contribution_builder->count == 0U &&
                engine->page_integers[HSTEX_PAGE_DEAD_CYCLES] == 0) {
                engine->end_requested = true;
                return HSTEX_ENGINE_EOF;
            }
            if (push_one(engine, *token, *location, error, error_capacity) !=
                    0 ||
                eject_last_pages(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_END_INPUT:
            if (hstex_source_end_current_file(&engine->sources, error,
                                              error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_ERROR_MESSAGE:
            /* A fault of the document's, not the end of the run. */
            if (execute_error_message(engine, error, error_capacity) != 0) {
                return HSTEX_ENGINE_ERROR;
            }
            continue;
        case HSTEX_COMMAND_INPUT_LINE_NUMBER:
        case HSTEX_COMMAND_INTEGER_CONSTANT:
        case HSTEX_COMMAND_ENGINE_STATE_INTEGER:
        case HSTEX_COMMAND_NUM_EXPR:
        case HSTEX_COMMAND_DIM_EXPR:
        case HSTEX_COMMAND_GLUE_EXPR:
        case HSTEX_COMMAND_MU_EXPR:
        case HSTEX_COMMAND_GLUE_COMPONENT_DIMEN:
        case HSTEX_COMMAND_GLUE_COMPONENT_ORDER:
            /* A quantity, met where a command was expected. */
            report_illegal_case(engine, *token);
            continue;
        case HSTEX_COMMAND_MATH_GROUP:
        case HSTEX_COMMAND_LANGUAGE:
        case HSTEX_COMMAND_PENALTY_ARRAY:
            return (enum hstex_engine_result)set_error(
                error, error_capacity,
                "non-integer register execution is not implemented");
        }
    }
}

/* A box body is read on the live input, so this loop runs again inside
   itself while one is being built, and the builders it is holding then stand
   in calls of its own. What a page leaves behind is given back only where no
   such call is running, which is where this loop is entered from outside. */
/* A run handed to another process where it stands. The loop this is called
   from is the one place a run holds nothing in a call of its own -- the same
   place what a page leaves behind is given back -- so everything the run is
   is in the engine and in the files it has open, and `fork` copies both.
   Where in the document that falls is not a file boundary but a page
   boundary, which is what makes it a checkpoint inside a file.

   The parent writes nothing more. It has buffers the child now has a copy
   of, so it leaves by `_exit`, which does not flush them: whatever was
   pending is written once, by the child, at the offset the two of them
   share. See docs/DECISIONS.md, a-checkpoint-inside-a-file. */
/* What the run is, in eight bytes. A chunk started from a guess at its own
   beginning is only sound if the guess turns out to be the state the chunk
   before it actually reached, and the two stand in different processes, so
   what is compared is a digest of them rather than the states themselves.
   It is also what says a run taken up elsewhere is the same run: the four
   files agreeing at the end says the output matched, and this says the
   engine did. See docs/DECISIONS.md, a-checkpoint-inside-a-file. */
static void digest_bytes(uint64_t *digest, const void *bytes, size_t length)
{
    const uint8_t *at = bytes;
    uint64_t value = *digest;
    for (size_t index = 0U; index < length; ++index) {
        value ^= at[index];
        value *= UINT64_C(0x100000001b3);
    }
    *digest = value;
}

/* A control sequence's meaning, by content rather than by the numbers the
   allocators happened to hand out. Two runs that agree in every meaning may
   still disagree in every macro index and every interning order, because
   their histories differ where their pages did; a digest that read those
   numbers would then never say "same" again. So a macro is hashed by its
   parameter text, its body and its flags; a token register by its tokens; a
   box by its measurements; and each is folded in under its NAME, combined so
   that the order names were met in does not matter. */
/* Names whose meanings the digest is told to pass over: the scratch a page
   leaves in \@tempa and its kin, which nothing reads across a page
   boundary, and which would otherwise say two equal states differ. The
   list is the waiver's whole content, and the waiver is only as sound as
   the claim that nothing on it is read before it is written. */
static uint64_t name_only_hash(enum hstex_symbol_kind kind,
                               const uint8_t *name, size_t length)
{
    uint64_t hash = UINT64_C(0xcbf29ce484222325);
    digest_bytes(&hash, &kind, sizeof(kind));
    if (length != 0U) {
        digest_bytes(&hash, name, length);
    }
    return hash;
}

static void load_soft_names(struct hstex_engine *engine)
{
    const char *path = getenv("HSTEX_DIGEST_SOFT");
    if (path == NULL) {
        return;
    }
    FILE *in = fopen(path, "r");
    if (in == NULL) {
        return;
    }
    free(engine->soft_names);
    engine->soft_names = NULL;
    engine->soft_name_count = 0U;
    engine->soft_names_from_environment = 1;
    char line[512];
    size_t capacity = 0U;
    while (fgets(line, sizeof(line), in) != NULL) {
        size_t length = strlen(line);
        while (length != 0U &&
               (line[length - 1U] == '\n' || line[length - 1U] == '\r')) {
            line[--length] = '\0';
        }
        if (length < 3U || line[1] != ' ') {
            continue;
        }
        enum hstex_symbol_kind kind =
            (enum hstex_symbol_kind)(line[0] - '0');
        if (engine->soft_name_count == capacity) {
            capacity = capacity == 0U ? 128U : capacity * 2U;
            uint64_t *grown = realloc(engine->soft_names,
                                      capacity * sizeof(*grown));
            if (grown == NULL) {
                break;
            }
            engine->soft_names = grown;
        }
        engine->soft_names[engine->soft_name_count++] =
            name_only_hash(kind, (const uint8_t *)line + 2, length - 2U);
    }
    (void)fclose(in);
}

static bool name_is_soft(const struct hstex_engine *engine,
                         uint64_t name_hash)
{
    for (size_t index = 0U; index < engine->soft_name_count; ++index) {
        if (engine->soft_names[index] == name_hash) {
            return true;
        }
    }
    return false;
}

/* A node by its content, never by the numbers the arenas happened to hand
   out: its kind, its measurements, what a character is of, what a glue
   stretches by, and its children by recursion. Two runs whose histories
   differ lay their arenas out differently while meaning the same lists,
   and this is what lets the digest see through that. */
static void digest_node(uint64_t *digest, const struct hstex_engine *engine,
                        uint32_t identifier);
static void digest_token_list(uint64_t *digest,
                              const struct hstex_engine *engine,
                              uint32_t identifier);

static void digest_node_run(uint64_t *digest,
                            const struct hstex_engine *engine, uint32_t start,
                            uint32_t count)
{
    digest_bytes(digest, &count, sizeof(count));
    for (uint32_t index = 0U; index < count; ++index) {
        if ((size_t)start + index >= engine->list_item_count) {
            break;
        }
        digest_node(digest, engine, engine->list_items[start + index]);
    }
}

static void digest_node(uint64_t *digest, const struct hstex_engine *engine,
                        uint32_t identifier)
{
    if (identifier == 0U || (size_t)identifier > engine->node_count) {
        return;
    }
    const struct hstex_node *node = &engine->nodes[identifier - 1U];
    /* Both are bit-fields, which have no address of their own: copy each out
       before it is hashed. The digest is over what a node says, not over how
       it is laid out, so the width taken here is the width of the value. */
    uint8_t digest_kind = (uint8_t)node->kind;
    uint8_t digest_explicit = node->explicit_kern ? 1U : 0U;
    digest_bytes(digest, &digest_kind, sizeof(digest_kind));
    digest_bytes(digest, &digest_explicit, sizeof(digest_explicit));
    digest_bytes(digest, &node->width, sizeof(node->width));
    digest_bytes(digest, &node->height, sizeof(node->height));
    digest_bytes(digest, &node->depth, sizeof(node->depth));
    digest_bytes(digest, &node->shift, sizeof(node->shift));
    switch (node->kind) {
    case HSTEX_NODE_CHARACTER:
    case HSTEX_NODE_LIGATURE:
        digest_bytes(digest, &node->value.character.font,
                     sizeof(node->value.character.font));
        digest_bytes(digest, &node->value.character.character,
                     sizeof(node->value.character.character));
        digest_bytes(digest, node->value.character.originals,
                     node->value.character.original_count);
        break;
    case HSTEX_NODE_GLUE:
        digest_bytes(digest, &node->value.glue.stretch,
                     sizeof(node->value.glue.stretch));
        digest_bytes(digest, &node->value.glue.shrink,
                     sizeof(node->value.glue.shrink));
        digest_bytes(digest, &node->value.glue.stretch_order,
                     sizeof(node->value.glue.stretch_order));
        digest_bytes(digest, &node->value.glue.shrink_order,
                     sizeof(node->value.glue.shrink_order));
        digest_bytes(digest, &node->value.glue.leader_kind,
                     sizeof(node->value.glue.leader_kind));
        digest_bytes(digest, &node->value.glue.parameter,
                     sizeof(node->value.glue.parameter));
        if (node->value.glue.leader != 0U) {
            digest_node(digest, engine, node->value.glue.leader);
        }
        break;
    case HSTEX_NODE_LIST: {
        /* Bit-fields have no address of their own: copied out to be hashed,
           each by the width of its value rather than of its storage. */
        uint8_t digest_box_kind = (uint8_t)node->value.list.box_kind;
        digest_bytes(digest, &digest_box_kind, sizeof(digest_box_kind));
        /* Field by field: the record is padded, and padding is whatever the
           process left there. */
        digest_bytes(digest, &node->value.list.glue.needed,
                     sizeof(node->value.list.glue.needed));
        digest_bytes(digest, &node->value.list.glue.total,
                     sizeof(node->value.list.glue.total));
        digest_bytes(digest, &node->value.list.glue.sign,
                     sizeof(node->value.list.glue.sign));
        digest_bytes(digest, &node->value.list.glue.order,
                     sizeof(node->value.list.glue.order));
        uint8_t digest_display = node->value.list.display ? 1U : 0U;
        digest_bytes(digest, &digest_display, sizeof(digest_display));
        digest_node_run(digest, engine, node->value.list.node_start,
                        node->value.list.node_count);
        break;
    }
    case HSTEX_NODE_DISCRETIONARY:
        digest_bytes(digest, &node->value.disc.replace_count,
                     sizeof(node->value.disc.replace_count));
        digest_node_run(digest, engine, node->value.disc.pre_start,
                        node->value.disc.pre_count);
        digest_node_run(digest, engine, node->value.disc.post_start,
                        node->value.disc.post_count);
        break;
    case HSTEX_NODE_MATH:
        digest_bytes(digest, &node->value.math.after,
                     sizeof(node->value.math.after));
        break;
    case HSTEX_NODE_KERN:
        digest_bytes(digest, &node->value.kern.margin,
                     sizeof(node->value.kern.margin));
        break;
    case HSTEX_NODE_MARK:
        digest_bytes(digest, &node->value.mark.class_number,
                     sizeof(node->value.mark.class_number));
        digest_token_list(digest, engine, node->value.mark.tokens);
        break;
    case HSTEX_NODE_INSERT:
        digest_bytes(digest, &node->value.insert.number,
                     sizeof(node->value.insert.number));
        /* Hashed by what it says rather than by where it is kept: the index
           is this run's own, while what it points at is the insertion. */
        struct hstex_insert_detail held = insert_detail_of(engine, node);
        digest_bytes(digest, &held.split_top_skip, sizeof(held.split_top_skip));
        digest_bytes(digest, &held.split_max_depth,
                     sizeof(held.split_max_depth));
        digest_bytes(digest, &held.float_cost, sizeof(held.float_cost));
        digest_node_run(digest, engine, node->value.insert.node_start,
                        node->value.insert.node_count);
        break;
    case HSTEX_NODE_WHATSIT:
        digest_bytes(digest, &node->value.whatsit.kind,
                     sizeof(node->value.whatsit.kind));
        digest_bytes(digest, &node->value.whatsit.stream,
                     sizeof(node->value.whatsit.stream));
        digest_bytes(digest, &node->value.whatsit.action,
                     sizeof(node->value.whatsit.action));
        digest_bytes(digest, &node->value.whatsit.detail,
                     sizeof(node->value.whatsit.detail));
        digest_bytes(digest, &node->value.whatsit.number,
                     sizeof(node->value.whatsit.number));
        digest_bytes(digest, &node->value.whatsit.structure,
                     sizeof(node->value.whatsit.structure));
        digest_token_list(digest, engine, node->value.whatsit.tokens);
        break;
    case HSTEX_NODE_PENALTY:
        digest_bytes(digest, &node->value.penalty,
                     sizeof(node->value.penalty));
        break;
    case HSTEX_NODE_RULE:
    default:
        break;
    }
}

static uint64_t canonical_meaning_hash(const struct hstex_engine *engine,
                                       hstex_cs_id identifier)
{
    const struct hstex_meaning *meaning =
        hstex_engine_meaning(engine, identifier);
    if (meaning->command == HSTEX_COMMAND_UNDEFINED) {
        return 0U;
    }
    uint64_t hash = UINT64_C(0xcbf29ce484222325);
    enum hstex_symbol_kind kind;
    const uint8_t *name = NULL;
    size_t length = 0U;
    if (hstex_symbol_name(&engine->lexical_state.symbols, identifier, &kind,
                          &name, &length) != 0) {
        return 0U;
    }
    uint64_t named = name_only_hash(kind, name, length);
    if (engine->soft_name_count != 0U && name_is_soft(engine, named)) {
        return 0U;
    }
    digest_bytes(&hash, &kind, sizeof(kind));
    if (length != 0U) {
        digest_bytes(&hash, name, length);
    }
    digest_bytes(&hash, &meaning->command, sizeof(meaning->command));
    digest_bytes(&hash, &meaning->level, sizeof(meaning->level));
    if (meaning->command == HSTEX_COMMAND_MACRO &&
        meaning->value.macro_identifier != 0U &&
        (size_t)meaning->value.macro_identifier <= engine->macro_count) {
        const struct hstex_macro *macro =
            &engine->macros[meaning->value.macro_identifier - 1U];
        digest_bytes(&hash, &macro->flags, sizeof(macro->flags));
        digest_bytes(&hash, &macro->parameter_count,
                     sizeof(macro->parameter_count));
        if (macro->parameter_count_tokens != 0U) {
            digest_bytes(&hash, macro->parameter_text,
                         macro->parameter_count_tokens *
                             sizeof(*macro->parameter_text));
        }
        if (macro->replacement_count != 0U) {
            digest_bytes(&hash, macro->replacement,
                         macro->replacement_count *
                             sizeof(*macro->replacement));
        }
    } else {
        digest_bytes(&hash, &meaning->value, sizeof(meaning->value));
    }
    return hash;
}

static void digest_token_list(uint64_t *digest,
                              const struct hstex_engine *engine,
                              uint32_t identifier)
{
    const struct hstex_token_list *list =
        token_list_by_identifier((struct hstex_engine *)(uintptr_t)engine,
                                 identifier);
    size_t count = list == NULL ? 0U : list->count;
    digest_bytes(digest, &count, sizeof(count));
    if (list != NULL && count != 0U) {
        digest_bytes(digest, list->tokens, count * sizeof(*list->tokens));
    }
}

static void digest_box_shape(uint64_t *digest, const struct hstex_box *box)
{
    digest_bytes(digest, &box->kind, sizeof(box->kind));
    if (box->kind != HSTEX_BOX_VOID) {
        digest_bytes(digest, &box->width, sizeof(box->width));
        digest_bytes(digest, &box->height, sizeof(box->height));
        digest_bytes(digest, &box->depth, sizeof(box->depth));
        digest_bytes(digest, &box->node_count, sizeof(box->node_count));
    }
}

/* The state in two halves: what the run MEANS at this boundary -- every
   meaning, register, parameter, and where the reading stands -- and where
   its OUTPUT has got to -- the byte the file has reached, the number the
   next object takes. A guessed chunk may mean the right thing and still be
   standing at the wrong place in the file, and what machinery the guessing
   needs depends on which of the two fails. */
static void page_state_digest_split(const struct hstex_engine *engine,
                                    uint64_t *semantic, uint64_t *placement);

static void page_state_digest_split_parts(const struct hstex_engine *engine,
                                          uint64_t *semantic,
                                          uint64_t *placement,
                                          uint64_t parts[6])
{
    /* The digest reads every meaning to hash it, and reading is exactly
       what the taint check watches, so the check is stood down while the
       digest looks. What the digest reads it does not act on. */
    size_t watched = engine->taint_pending;
    ((struct hstex_engine *)(uintptr_t)engine)->taint_pending = 0U;
    uint64_t digest = UINT64_C(0xcbf29ce484222325);
#define DIGEST_VALUE(field) digest_bytes(&digest, &(field), sizeof(field))
    DIGEST_VALUE(engine->shipped_pages);
    DIGEST_VALUE(engine->group_level);
    DIGEST_VALUE(engine->save_count);
    DIGEST_VALUE(engine->conditional_count);
    DIGEST_VALUE(engine->mode);
    DIGEST_VALUE(engine->prev_depth);
    DIGEST_VALUE(engine->space_factor);
    DIGEST_VALUE(engine->font_count);
    DIGEST_VALUE(engine->current_font);
    DIGEST_VALUE(engine->page_integers);
    DIGEST_VALUE(engine->page_dimens);
    DIGEST_VALUE(engine->integer_parameters);
    DIGEST_VALUE(engine->dimen_parameters);
    DIGEST_VALUE(engine->glue_parameters);
    DIGEST_VALUE(engine->muglue_parameters);
    DIGEST_VALUE(engine->code_tables);
    DIGEST_VALUE(engine->math_fonts);
    DIGEST_VALUE(engine->lexical_state.catcodes);
    parts[0] = digest;
    /* Every named meaning, by content, order-independent: interning order
       differs where histories did. */
    uint64_t names = 0U;
    for (hstex_cs_id identifier = 1U;
         (size_t)identifier <= engine->meaning_capacity; ++identifier) {
        names ^= canonical_meaning_hash(engine, identifier);
    }
    DIGEST_VALUE(names);
    parts[1] = names;
    if (engine->counts != NULL) {
        digest_bytes(&digest, engine->counts,
                     engine->count_capacity * sizeof(*engine->counts));
        digest_bytes(&digest, engine->dimens,
                     engine->count_capacity * sizeof(*engine->dimens));
        digest_bytes(&digest, engine->glues,
                     engine->count_capacity * sizeof(*engine->glues));
        digest_bytes(&digest, engine->muglues,
                     engine->count_capacity * sizeof(*engine->muglues));
        for (size_t index = 0U; index < engine->count_capacity; ++index) {
            digest_token_list(&digest, engine,
                              engine->token_registers[index]);
        }
        for (size_t index = 0U; index < engine->count_capacity; ++index) {
            digest_box_shape(&digest, &engine->boxes[index]);
        }
    }
    parts[2] = digest;
    for (size_t index = 0U; index < HSTEX_TOKEN_PARAMETER_COUNT; ++index) {
        digest_token_list(&digest, engine, engine->token_parameters[index]);
    }
    parts[3] = digest;
    /* What is half built at this boundary: the paragraph being filled, the
       contributions the page builder has not taken, the page so far, the
       marks and the insertions. Two states that agree in every meaning can
       still differ here, and one that did cost a wrong page. */
    DIGEST_VALUE(engine->building_paragraph);
    DIGEST_VALUE(engine->prev_graf);
    if (engine->paragraph_builder != NULL) {
        size_t held = engine->paragraph_builder->count;
        DIGEST_VALUE(held);
        for (size_t index = 0U; index < held; ++index) {
            digest_node(&digest, engine,
                        engine->paragraph_builder->node_identifiers[index]);
        }
    }
    const struct hstex_vbox_builder *vertical[2];
    vertical[0] = engine->contribution_builder;
    vertical[1] = engine->page_builder;
    for (size_t which = 0U; which < 2U; ++which) {
        if (vertical[which] == NULL) {
            continue;
        }
        size_t held = vertical[which]->count;
        DIGEST_VALUE(held);
        for (size_t index = 0U; index < held; ++index) {
            digest_node(&digest, engine,
                        vertical[which]->node_identifiers[index]);
        }
    }
    for (size_t index = 0U; index < engine->mark_class_count; ++index) {
        const struct hstex_mark_class *mark = &engine->mark_classes[index];
        DIGEST_VALUE(mark->number);
        digest_token_list(&digest, engine, mark->top);
        digest_token_list(&digest, engine, mark->first);
        digest_token_list(&digest, engine, mark->bot);
    }
    for (size_t index = 0U; index < engine->page_insert_count; ++index) {
        const struct hstex_page_insert *insert = &engine->page_inserts[index];
        DIGEST_VALUE(insert->number);
        DIGEST_VALUE(insert->held);
        DIGEST_VALUE(insert->split);
    }
    parts[4] = digest;
    /* Where the reading has got to in every file that is open. A token
       frame read to its end is a husk the next read will clear; when it is
       cleared is representation, not meaning -- but skipping husks is only
       sound now that the half-built lists above are hashed. The first time
       it was tried without them, a husk was the one thing distinguishing a
       chunk whose paragraph-in-progress differed, and the relay shipped a
       wrong page. Anything weakened here must survive tools/relay-demo.sh
       against a golden run first. */
    for (size_t index = 0U; index < engine->sources.count; ++index) {
        const struct hstex_source_frame *frame = &engine->sources.frames[index];
        if (frame->kind == HSTEX_SOURCE_TOKEN_LIST &&
            frame->value.token_list.cursor >= frame->value.token_list.count) {
            continue;
        }
        DIGEST_VALUE(frame->kind);
        if (frame->kind == HSTEX_SOURCE_FILE) {
            digest_bytes(&digest, frame->value.file->path,
                         strlen(frame->value.file->path));
            DIGEST_VALUE(frame->value.file->mouth.line_number);
            DIGEST_VALUE(frame->value.file->mouth.line_cursor);
            /* And what the file still holds from the current line on: a
               state is only the same as another if the text each will now
               read is the same text. What was already consumed needs no
               hash -- its effects are the rest of this digest -- and a file
               not yet opened is read fresh from disk by whoever opens it,
               so an edit refuses exactly the chunks that straddle it. */
            const struct hstex_mouth *mouth = &frame->value.file->mouth;
            if (mouth->data != NULL && mouth->line_start < mouth->length) {
                size_t remaining = mouth->length - mouth->line_start;
                DIGEST_VALUE(remaining);
                digest_bytes(&digest, mouth->data + mouth->line_start,
                             remaining);
            }
        } else if (frame->kind == HSTEX_SOURCE_TOKEN_LIST) {
            DIGEST_VALUE(frame->value.token_list.count);
            DIGEST_VALUE(frame->value.token_list.cursor);
        }
    }
    *semantic = digest;
    /* Where the output stands: the byte the file has reached, the number
       the next object will take, what the cross-reference tables hold, and
       where each file being written has got to. */
    digest = UINT64_C(0xcbf29ce484222325);
    DIGEST_VALUE(engine->pdf_written);
    DIGEST_VALUE(engine->pdf_object_counter);
    DIGEST_VALUE(engine->pdf_dest_count);
    DIGEST_VALUE(engine->pdf_annot_count);
    DIGEST_VALUE(engine->pdf_outline_count);
    DIGEST_VALUE(engine->pdf_page_count);
    for (size_t index = 0U; index < 16U; ++index) {
        long reached = engine->parallel_is_worker
                           ? engine->parallel_reached[index]
                           : engine->write_streams[index] == NULL
                                 ? -1L
                                 : ftell(engine->write_streams[index]);
        DIGEST_VALUE(reached);
    }
#undef DIGEST_VALUE
    parts[5] = digest;
    *placement = digest;
    ((struct hstex_engine *)(uintptr_t)engine)->taint_pending = watched;
}



static void maybe_dump_meanings(const struct hstex_engine *engine);

static void page_state_digest_split(const struct hstex_engine *engine,
                                    uint64_t *semantic, uint64_t *placement)
{
    uint64_t parts[6];
    page_state_digest_split_parts(engine, semantic, placement, parts);
}

static void note_page_digest(const struct hstex_engine *engine)
{
    static FILE *log;
    static int asked;
    if (asked == 0) {
        asked = getenv("HSTEX_PAGE_DIGEST") != NULL ? 1 : -1;
    }
    if (asked < 0) {
        return;
    }
    if (log == NULL) {
        const char *path = getenv("HSTEX_PAGE_DIGEST");
        log = fopen(path[0] == '\0' ? "page-digest.txt" : path, "w");
        if (log == NULL) {
            asked = -1;
            return;
        }
    }
    uint64_t semantic = 0U;
    uint64_t placement = 0U;
    uint64_t parts[6];
    page_state_digest_split_parts(engine, &semantic, &placement, parts);
    (void)fprintf(log,
                  "%d %016llx %016llx %016llx %016llx %016llx %016llx\n",
                  engine->shipped_pages, (unsigned long long)semantic,
                  (unsigned long long)placement,
                  (unsigned long long)parts[0],
                  (unsigned long long)parts[1],
                  (unsigned long long)parts[2],
                  (unsigned long long)parts[3]);
    (void)fprintf(log, "part4 %d %016llx\n", engine->shipped_pages,
                  (unsigned long long)parts[4]);
    maybe_dump_meanings(engine);
    (void)fflush(log);
}

/* Beside each checkpoint, note where in the file being read it stands: the
   file, the byte the reading has reached, and a hash of everything before that
   byte. An incremental rebuild reads these to find the last checkpoint whose
   consumed prefix an edit left untouched -- so an edit deep in one long file
   still reuses the checkpoints before it, not merely those before the file
   opened. */
static void record_checkpoint_position(struct hstex_engine *engine,
                                       const char *dir, int32_t page)
{
    struct hstex_file_source *file = hstex_source_current_file(&engine->sources);
    if (file == NULL || file->path == NULL || file->mouth.data == NULL) {
        return;
    }
    size_t cursor = file->mouth.next_line_offset;
    if (cursor > file->mouth.length) {
        cursor = file->mouth.length;
    }
    uint64_t hash = 0xcbf29ce484222325ULL; /* FNV-1a */
    for (size_t index = 0U; index < cursor; ++index) {
        hash ^= file->mouth.data[index];
        hash *= 0x100000001b3ULL;
    }
    char path[600];
    (void)snprintf(path, sizeof(path), "%s/positions", dir);
    FILE *out = fopen(path, "ab");
    if (out != NULL) {
        (void)fprintf(out, "%d\t%zu\t%llu\t%s\n", page, cursor,
                      (unsigned long long)hash, file->path);
        (void)fclose(out);
    }
}

/* At a page boundary, drop a checkpoint if one was asked for. HSTEX_CKPT is
   `<page>:<file>' -- one checkpoint, when that many pages have shipped;
   HSTEX_CKPT_EVERY is `<stride>:<dir>' -- one every `stride' pages, named
   `<dir>/ck-<page>.bin', which the chapter-parallel driver takes up. */
static void maybe_write_checkpoint(struct hstex_engine *engine)
{
    static int parsed = 0;
    static int32_t target_page = -1;
    static char target_path[512] = {0};
    static int32_t stride = 0;
    static char stride_dir[400] = {0};
    if (parsed == 0) {
        parsed = 1;
        const char *one = getenv("HSTEX_CKPT");
        if (one != NULL) {
            const char *colon = strchr(one, ':');
            if (colon != NULL) {
                target_page = (int32_t)strtol(one, NULL, 10);
                (void)snprintf(target_path, sizeof(target_path), "%s",
                               colon + 1);
            }
        }
        const char *every = getenv("HSTEX_CKPT_EVERY");
        if (every != NULL) {
            const char *colon = strchr(every, ':');
            if (colon != NULL) {
                stride = (int32_t)strtol(every, NULL, 10);
                (void)snprintf(stride_dir, sizeof(stride_dir), "%s", colon + 1);
            }
        }
    }
    /* The schedule is per-run, so a settle-the-aux driver that compiles several
       times in one process starts each run's stride afresh. */
    if (stride > 0 && engine->checkpoint_disk_next == 0) {
        engine->checkpoint_disk_next = stride;
    }
    char err[256];
    if (target_page >= 0 && engine->shipped_pages == target_page &&
        target_path[0] != '\0') {
        if (hstex_engine_write_checkpoint(engine, target_path, err,
                                          sizeof(err)) != 0 &&
            getenv("HSTEX_CKPT_DEBUG") != NULL) {
            (void)fprintf(stderr, "CKPT write failed at %d: %s\n",
                          engine->shipped_pages, err);
        }
        target_page = -1;
    }
    /* Page zero: the post-preamble state, dropped the first clean moment the
       body has put something on page one (page_has_box, still shipped_pages
       zero). A warm run's first chunk resumes this instead of re-reading the
       whole preamble; if no clean moment comes before page one ships, ck-0 is
       simply absent and that chunk falls back to a fresh preamble read. */
    if (stride > 0 && stride_dir[0] != '\0' && engine->shipped_pages == 0 &&
        engine->page_has_box && !engine->checkpoint_zero_done) {
        char path[600];
        (void)snprintf(path, sizeof(path), "%s/ck-0.bin", stride_dir);
        if (hstex_engine_write_checkpoint(engine, path, err, sizeof(err)) == 0) {
            engine->checkpoint_zero_done = true;
            record_checkpoint_position(engine, stride_dir, 0);
        } else if (getenv("HSTEX_CKPT_DEBUG") != NULL) {
            (void)fprintf(stderr, "CKPT page-0 declined: %s\n", err);
        }
    }
    /* A checkpoint every `stride' pages, but a page boundary that sits inside
       an open construct (math, alignment, a box, a conditional) has no clean
       state to serialize and is declined. Rather than skip the whole window,
       keep trying each following page until one takes; the file is named for
       the page it actually lands on, and the parallel driver discovers those
       pages by listing the cache, so an off-stride boundary is fine. */
    if (stride > 0 && stride_dir[0] != '\0' && engine->shipped_pages > 0 &&
        engine->checkpoint_disk_next > 0 &&
        engine->shipped_pages >= engine->checkpoint_disk_next) {
        char path[600];
        (void)snprintf(path, sizeof(path), "%s/ck-%d.bin", stride_dir,
                       engine->shipped_pages);
        if (hstex_engine_write_checkpoint(engine, path, err, sizeof(err)) == 0) {
            record_checkpoint_position(engine, stride_dir,
                                       engine->shipped_pages);
            engine->checkpoint_disk_next = engine->shipped_pages + stride;
        } else if (getenv("HSTEX_CKPT_DEBUG") != NULL) {
            (void)fprintf(stderr, "CKPT declined at %d: %s\n",
                          engine->shipped_pages, err);
        }
    }
}

/* A resumed chunk stops when it has shipped up to HSTEX_RESUME_STOP, so it
   typesets its own range of a document and no more; finishing there closes its
   PDF without reaching \end{document}, whose aux dance belongs to the last
   chunk alone. */
static int maybe_stop_at_resume_page(struct hstex_engine *engine)
{
    static int parsed = 0;
    static int32_t stop = -1;
    if (parsed == 0) {
        parsed = 1;
        const char *ask = getenv("HSTEX_RESUME_STOP");
        if (ask != NULL) {
            stop = (int32_t)strtol(ask, NULL, 10);
        }
    }
    if (stop >= 0 && engine->shipped_pages >= stop) {
        /* A chunk that tiles into a shared PDF and stops here has written only
           its pages; the deferred objects, catalogue and xref are the finishing
           chunk's to write, so mark this one so pdf_close leaves them alone. */
        if (getenv("HSTEX_TILE") != NULL) {
            engine->tile_middle = true;
        }
        return 1;
    }
    return 0;
}

/* A chunk parked where a run may be taken up. Everything the run is stands
   in the child, which then waits on a gate the whole fleet shares; when the
   gate opens they all go at once, each running as far as the next boundary
   and no further. What that costs is what the run would cost if the state
   every chunk begins in could be guessed rightly. */
/* Every chunk writes into one file, each at the place its own bytes begin,
   so nothing has to be joined together afterwards. Each opens the file for
   itself rather than sharing the run's, because a shared one has a single
   position that they would all be moving. */
static const char *fleet_file_name(struct hstex_engine *engine, char *room,
                                   size_t capacity)
{
    const char *job = engine->job_name == NULL ? "texput" : engine->job_name;
    (void)snprintf(room, capacity, "%s-fleet.pdf", job);
    return room;
}

/* The other files a run writes are taken up the same way: each chunk opens
   the same file for itself and seeks to where its own bytes begin, which is
   where the run had reached when the chunk was parked. */
static void redirect_the_write_streams(struct hstex_engine *engine,
                                       const long *reached)
{
    for (size_t index = 0U; index < 16U; ++index) {
        FILE *open_stream = engine->write_streams[index];
        if (open_stream == NULL || reached[index] < 0L ||
            engine->write_stream_paths[index] == NULL) {
            continue;
        }
        /* A chunk serving the same run writes into the file itself; a chunk
           serving a run that has not happened yet writes into a fleet copy,
           because the file itself is that run's INPUT and must not change
           under it. */
        char *where = engine->write_stream_paths[index];
        char fleet[600];
        if (engine->speculating) {
            (void)snprintf(fleet, sizeof(fleet), "%s-fleet", where);
            where = fleet;
        }
        FILE *own = fopen(where, "r+b");
        if (own == NULL && engine->speculating) {
            own = fopen(where, "w+b");
        }
        if (own == NULL) {
            continue;
        }
        if (fseek(own, reached[index], SEEK_SET) != 0) {
            (void)fclose(own);
            continue;
        }
        (void)close(fileno(open_stream));
        engine->write_streams[index] = own;
        if (engine->speculating) {
            free(engine->write_stream_paths[index]);
            engine->write_stream_paths[index] = strdup(where);
        }
    }
}

static void redirect_to_the_fleet_file(struct hstex_engine *engine)
{
    char name[512];
    char *path = output_path(engine,
                             fleet_file_name(engine, name, sizeof(name)));
    if (path == NULL) {
        return;
    }
    FILE *own = fopen(path, "r+b");
    if (own == NULL) {
        /* The last round's assembly renamed the fleet file into place, so
           the first writer of a new round starts it afresh. */
        own = fopen(path, "w+b");
    }
    free(path);
    if (own == NULL) {
        return;
    }
    if (fseek(own, (long)engine->parallel_offset, SEEK_SET) != 0) {
        (void)fclose(own);
        return;
    }
    /* Dropped rather than closed: closing would flush this copy of what the
       run above is still holding. */
    if (engine->pdf_file != NULL) {
        (void)close(fileno(engine->pdf_file));
    }
    engine->pdf_file = own;
}

/* A chunk is done: what it still holds goes into the file, it says so, and
   it leaves. Its replacement is already parked. */
static void finish_a_chunk(struct hstex_engine *engine)
{
    char ignored[256];
    (void)pdf_flush(engine, ignored, sizeof(ignored));
    if (engine->pdf_file != NULL) {
        (void)fflush(engine->pdf_file);
    }
    for (size_t index = 0U; index < 16U; ++index) {
        if (engine->write_streams[index] != NULL) {
            (void)fflush(engine->write_streams[index]);
        }
    }
    if (engine->parallel_done_write >= 0) {
        char done = 1;
        ssize_t said = write(engine->parallel_done_write, &done, 1);
        (void)said;
    }
    _exit(0);
}

static int apply_state_patch(struct hstex_engine *engine, const char *path);
static void probe_and_leave(struct hstex_engine *engine);
static void spec_write_state(const struct hstex_engine *engine,
                             const char *prefix, int32_t page);
static void speculation_boundary(struct hstex_engine *engine);

static void park_a_chunk(struct hstex_engine *engine)
{
    if (engine->parallel_chunk == 0) {
        return;
    }
    if (engine->parallel_is_worker) {
        if (!engine->speculating && engine->parallel_stop > 0 &&
            engine->shipped_pages >= engine->parallel_stop) {
            finish_a_chunk(engine);
        }
        return;
    }
    if (engine->shipped_pages == 0 || engine->parallel_workers >= 256) {
        return;
    }
    if (engine->parallel_stride_ns != 0ULL) {
        struct timespec now;
        (void)clock_gettime(CLOCK_MONOTONIC, &now);
        uint64_t at = (uint64_t)now.tv_sec * 1000000000ULL +
                      (uint64_t)now.tv_nsec;
        if (engine->parallel_parked_at == 0ULL) {
            /* The first boundary starts the clock rather than parks: what
               came before it is the preamble, not a chunk. */
            engine->parallel_parked_at = at;
            return;
        }
        if (at - engine->parallel_parked_at < engine->parallel_stride_ns) {
            return;
        }
        engine->parallel_parked_at = at;
    } else if (engine->shipped_pages % engine->parallel_chunk != 0) {
        return;
    }
    long reached[16];
    int gate[2];
    if (pipe(gate) != 0) {
        return;
    }
    pid_t child = fork();
    if (child < 0) {
        (void)close(gate[0]);
        (void)close(gate[1]);
        return;
    }
    if (child == 0) {
        engine->parallel_is_worker = 1;
        engine->parallel_gate_read = gate[0];
        (void)close(gate[1]);
        (void)close(engine->parallel_done_read);
        /* The run keeps one tool alive to ask where files are, on a pipe of
           its own. A fleet of chunks would all be asking down the same pipe
           and reading each other's answers, so a chunk forgets the one it
           inherited and starts its own when it first needs to ask. The
           descriptors are dropped rather than closed: closing would flush
           this copy of the buffer into the tool the run above is still
           talking to. */
        if (engine->finder.questions != NULL) {
            (void)close(fileno(engine->finder.questions));
        }
        if (engine->finder.answers != NULL) {
            (void)close(fileno(engine->finder.answers));
        }
        engine->finder.questions = NULL;
        engine->finder.answers = NULL;
        engine->finder.child = 0;
        engine->finder.marker_answer = NULL;
        engine->finder.pending_held = 0U;
        engine->finder.broken = false;
        /* The bytes still in hand belong to the chunk before this one, which
           will write them itself; this chunk's own begin where the run had
           reached when it was parked. */
        engine->parallel_offset = engine->pdf_written;
        engine->pdf_out_count = 0U;
        engine->parallel_redirect = engine->pdf_file != NULL;
        for (size_t index = 0U; index < 16U; ++index) {
            reached[index] = engine->write_streams[index] == NULL
                                 ? -1L
                                 : ftell(engine->write_streams[index]);
            engine->parallel_reached[index] = reached[index];
        }
        /* Parked. Each time the gate opens, this chunk leaves a copy of
           itself parked on the same gate -- taken before any work is done,
           so the copy holds the state the chunk began in -- and then goes on
           to do the work itself. The fleet therefore serves one run after
           another rather than one only. */
        for (;;) {
            /* What comes down the gate is where this chunk is to stop: the
               page the chunk after it was parked at, or zero for the last,
               which runs to the end. Only the run above knows, because a
               chunk parked by the clock does not know where the next fell. */
            int32_t header[2] = {0, 0};
            size_t have = 0U;
            while (have < sizeof(header)) {
                ssize_t got =
                    read(engine->parallel_gate_read, (char *)header + have,
                         sizeof(header) - have);
                if (got < 0 && errno == EINTR) {
                    continue;
                }
                if (got <= 0) {
                    _exit(0);
                }
                have += (size_t)got;
            }
            engine->parallel_stop = header[0];
            engine->parallel_one_shot = getenv("HSTEX_SPECULATE") != NULL;
            size_t patch_length =
                header[1] > 0 && header[1] < 4096 ? (size_t)header[1] : 0U;
            engine->parallel_patch[0] = '\0';
            if (patch_length != 0U) {
                have = 0U;
                while (have < patch_length) {
                    ssize_t got = read(engine->parallel_gate_read,
                                       engine->parallel_patch + have,
                                       patch_length - have);
                    if (got < 0 && errno == EINTR) {
                        continue;
                    }
                    if (got <= 0) {
                        _exit(0);
                    }
                    have += (size_t)got;
                }
                engine->parallel_patch[patch_length] = '\0';
            }
            if (engine->parallel_one_shot) {
                break;
            }
            pid_t again = fork();
            if (again < 0) {
                break;
            }
            if (again != 0) {
                break;
            }
        }
        const char *speculate = getenv("HSTEX_SPECULATE");
        if (speculate == NULL && engine->parking) {
            speculate = engine->spec_dir;
        }
        if (speculate != NULL) {
            /* A speculative chunk must not run yet: what it will read from
               disk belongs to the run it will serve, which has not begun --
               the document may be edited between the parking and the
               serving. It reports in to the run that parked it, then parks
               again on a named pipe only the serving run's verifier opens;
               what comes down the pipe is the patch. */
            engine->speculating = 1;
            engine->spec_start = engine->shipped_pages;
            if (speculate != engine->spec_dir) {
                (void)snprintf(engine->spec_dir, sizeof(engine->spec_dir),
                               "%s", speculate);
            }
            char done = 1;
            ssize_t said = write(engine->parallel_done_write, &done, 1);
            (void)said;
            (void)close(engine->parallel_done_write);
            engine->parallel_done_write = -1;
            char gate_name[600];
            spec_path(engine, gate_name, sizeof(gate_name), "go",
                      engine->spec_start);
            (void)mkfifo(gate_name, 0600);
            if (getenv("HSTEX_FLEET_DEBUG") != NULL) {
                (void)fprintf(stderr, "FLEETDBG park %d pid=%d\n",
                              engine->spec_start, (int)getpid());
            }
            for (;;) {
                int lane = open(gate_name, O_RDONLY);
                if (lane < 0) {
                    _exit(1);
                }
                int32_t patch_length = 0;
                size_t have = 0U;
                bool hung_up = false;
                while (have < sizeof(patch_length)) {
                    ssize_t got = read(lane, (char *)&patch_length + have,
                                       sizeof(patch_length) - have);
                    if (got < 0 && errno == EINTR) {
                        continue;
                    }
                    if (got <= 0) {
                        hung_up = true;
                        break;
                    }
                    have += (size_t)got;
                }
                if (hung_up) {
                    /* An open with no bytes is not a release: a passer-by
                       opened and closed the pipe. Park again. */
                    (void)close(lane);
                    continue;
                }
                engine->parallel_patch[0] = '\0';
                if (patch_length > 0 && (size_t)patch_length <
                                            sizeof(engine->parallel_patch)) {
                    have = 0U;
                    while (have < (size_t)patch_length) {
                        ssize_t got =
                            read(lane, engine->parallel_patch + have,
                                 (size_t)patch_length - have);
                        if (got < 0 && errno == EINTR) {
                            continue;
                        }
                        if (got <= 0) {
                            _exit(0);
                        }
                        have += (size_t)got;
                    }
                    engine->parallel_patch[patch_length] = '\0';
                }
                (void)close(lane);
                if (getenv("HSTEX_FLEET_DEBUG") != NULL) {
                    (void)fprintf(stderr,
                                  "FLEETDBG woken %d pid=%d patch=%d\n",
                                  engine->spec_start, (int)getpid(),
                                  (int)patch_length);
                }
                /* A copy stays parked, holding the state as parked -- before
                   any patch -- so the fleet serves run after run. */
                pid_t successor = fork();
                if (successor == 0) {
                    engine->parallel_patch[0] = '\0';
                    continue;
                }
                break;
            }
        }
        if (engine->parallel_patch[0] != '\0' &&
            apply_state_patch(engine, engine->parallel_patch) != 0) {
            _exit(1);
        }
        probe_and_leave(engine);
        if (engine->speculating) {
            spec_write_state(engine, "entry", engine->spec_start);
            if (getenv("HSTEX_FLEET_DEBUG") != NULL) {
                (void)fprintf(stderr, "FLEETDBG entry %d pid=%d\n",
                              engine->spec_start, (int)getpid());
            }
            taint_arm(engine);
        }
        if (engine->parallel_redirect) {
            redirect_to_the_fleet_file(engine);
        }
        redirect_the_write_streams(engine, reached);
        return;
    }
    if (engine->parallel_workers == 0) {
        /* Where the first chunk's bytes end, which is where everything the
           run wrote before any chunk was parked comes to. */
        engine->parallel_first_offset = engine->pdf_written;
    }
    (void)close(gate[0]);
    engine->parallel_pages[engine->parallel_workers] = engine->shipped_pages;
    engine->parallel_gates[engine->parallel_workers++] = gate[1];
}

/* The gate the parked chunks wait on, opened once the run that parked them
   is done. What it reports is the wall clock of the chunks alone. */
/* The file the chunks write into is laid out before they are let go: what
   the run wrote before the first of them was parked, and then a stretch of
   a byte no page description contains, so that anything no chunk writes
   shows up as itself rather than as a plausible zero. */
static void lay_out_the_fleet_file(struct hstex_engine *engine)
{
    const char *job = engine->job_name == NULL ? "texput" : engine->job_name;
    char sequential_name[512];
    char fleet_name[512];
    (void)snprintf(sequential_name, sizeof(sequential_name), "%s.pdf", job);
    (void)snprintf(fleet_name, sizeof(fleet_name), "%s-fleet.pdf", job);
    char *from = output_path(engine, sequential_name);
    char *to = output_path(engine, fleet_name);
    if (from == NULL || to == NULL) {
        free(from);
        free(to);
        return;
    }
    FILE *source = fopen(from, "rb");
    FILE *target = fopen(to, "wb");
    free(from);
    free(to);
    if (source == NULL || target == NULL) {
        if (source != NULL) {
            (void)fclose(source);
        }
        if (target != NULL) {
            (void)fclose(target);
        }
        return;
    }
    static uint8_t room[1U << 16];
    size_t left = engine->parallel_first_offset;
    while (left != 0U) {
        size_t want = left < sizeof(room) ? left : sizeof(room);
        size_t got = fread(room, 1U, want, source);
        if (got == 0U || fwrite(room, 1U, got, target) != got) {
            break;
        }
        left -= got;
    }
    if (fseek(source, 0L, SEEK_END) == 0) {
        long total = ftell(source);
        memset(room, 0xEE, sizeof(room));
        size_t rest = total > 0L && (size_t)total > engine->parallel_first_offset
                          ? (size_t)total - engine->parallel_first_offset
                          : 0U;
        while (rest != 0U) {
            size_t want = rest < sizeof(room) ? rest : sizeof(room);
            if (fwrite(room, 1U, want, target) != want) {
                break;
            }
            rest -= want;
        }
    }
    (void)fclose(source);
    (void)fclose(target);
}

static void release_them_once(struct hstex_engine *engine)
{
    struct timespec before;
    struct timespec after;
    (void)clock_gettime(CLOCK_MONOTONIC, &before);
    const char *speculate = getenv("HSTEX_SPECULATE");
    if (speculate == NULL && engine->parking) {
        speculate = engine->spec_dir;
    }
    if (speculate != NULL) {
        char name[600];
        (void)snprintf(name, sizeof(name), "%s/pages.txt", speculate);
        FILE *manifest = fopen(name, "w");
        if (manifest != NULL) {
            for (int index = 0; index < engine->parallel_workers; ++index) {
                (void)fprintf(manifest, "%d\n",
                              engine->parallel_pages[index]);
            }
            (void)fclose(manifest);
        }
    }
    const char *patch = getenv("HSTEX_PATCH");
    size_t patch_length = patch == NULL ? 0U : strlen(patch);
    if (patch_length >= 4096U) {
        patch_length = 0U;
    }
    for (int index = 0; index < engine->parallel_workers; ++index) {
        int32_t header[2];
        header[0] = index + 1 < engine->parallel_workers
                        ? engine->parallel_pages[index + 1]
                        : 0;
        header[1] = (int32_t)patch_length;
        ssize_t wrote =
            write(engine->parallel_gates[index], header, sizeof(header));
        if (patch_length != 0U) {
            wrote = write(engine->parallel_gates[index], patch, patch_length);
        }
        (void)wrote;
    }
    /* Counted back rather than waited for: a chunk's replacement is a child
       of the chunk, so the run above is not its parent and cannot wait for
       it. Waiting for any child at all would wait for the file-finding
       tool, which never ends. */
    for (int index = 0; index < engine->parallel_workers; ++index) {
        char done = 0;
        ssize_t got;
        do {
            got = read(engine->parallel_done_read, &done, 1);
        } while (got < 0 && errno == EINTR);
        if (got <= 0) {
            break;
        }
    }
    (void)clock_gettime(CLOCK_MONOTONIC, &after);
    (void)fprintf(stderr, "PARALLEL chunks=%d pages=%d seconds=%.3f\n",
                  engine->parallel_workers, engine->parallel_chunk,
                  (double)(after.tv_sec - before.tv_sec) +
                      (double)(after.tv_nsec - before.tv_nsec) / 1e9);
}

/* The fleet is let go as many times as it is asked for. Each chunk leaves a
   replacement parked before it works, so what the second round costs is what
   a run costs once the fleet is standing: the persistent mode the benchmark
   contract reports on its own. */
static void hstex_engine_release_chunks(struct hstex_engine *engine)
{
    if (engine->parallel_is_worker || engine->parallel_workers == 0) {
        return;
    }
    /* The file the chunks write into is laid out once. Every release
       rewrites every page deterministically, so laying it out again would
       only copy fifty megabytes to say what is already there. */
    lay_out_the_fleet_file(engine);
    const char *asked = getenv("HSTEX_PARALLEL_ROUNDS");
    long rounds = asked == NULL ? 1L : strtol(asked, NULL, 10);
    if (rounds < 1L || rounds > 100L) {
        rounds = 1L;
    }
    for (long round = 0; round < rounds; ++round) {
        release_them_once(engine);
    }
}

static int handle_vertical_list_token(struct hstex_engine *engine,
                                      hstex_token token,
                                      struct hstex_source_location location,
                                      char *error, size_t error_capacity);
/* What a woken chunk is told besides where to stop: a file of assignments
   that turns the state it inherited into a guess at the state a different
   run would have reached here -- the labels a later pass reads differently,
   say. It is read the way an output routine's tokens are read: behind a
   boundary, so that it ends where it ends and the document is not touched. */
static int apply_state_patch(struct hstex_engine *engine, const char *path)
{
    char error[512] = {0};
    if (hstex_source_push_boundary(&engine->sources, error, sizeof(error)) !=
        0) {
        return -1;
    }
    if (hstex_source_push_file(&engine->sources, path, error, sizeof(error)) !=
        0) {
        (void)hstex_source_pop_boundary(&engine->sources, NULL, 0U);
        return -1;
    }
    int status = 0;
    for (;;) {
        hstex_token token = 0U;
        struct hstex_source_location where;
        enum hstex_engine_result result = hstex_engine_next_output(
            engine, &token, &where, error, sizeof(error));
        if (result == HSTEX_ENGINE_EOF) {
            break;
        }
        if (result == HSTEX_ENGINE_ERROR) {
            status = -1;
            break;
        }
        if (handle_vertical_list_token(engine, token, where, error,
                                       sizeof(error)) != 0) {
            status = -1;
            break;
        }
    }
    if (hstex_source_pop_boundary(&engine->sources, error, sizeof(error)) !=
        0) {
        status = -1;
    }
    return status;
}

/* Every named meaning and its content hash, and each scalar block's hash,
   so that two runs' states at the same page can be diffed name by name.
   This is the tool the soft list is grown with: where two states that
   should agree do not, the dump names the meaning that differs.
   HSTEX_MEANING_DUMP is "<path>:<page>". */
static void maybe_dump_meanings(const struct hstex_engine *engine)
{
    const char *asked = getenv("HSTEX_MEANING_DUMP");
    if (asked == NULL) {
        return;
    }
    const char *colon = strrchr(asked, ':');
    if (colon == NULL || atoi(colon + 1) != engine->shipped_pages) {
        return;
    }
    char path[512];
    size_t length = (size_t)(colon - asked);
    if (length >= sizeof(path)) {
        return;
    }
    memcpy(path, asked, length);
    path[length] = '\0';
    FILE *out = fopen(path, "w");
    if (out == NULL) {
        return;
    }
#define DUMP_SCALAR(field) \
    do { \
        uint64_t one = UINT64_C(0xcbf29ce484222325); \
        digest_bytes(&one, &(field), sizeof(field)); \
        (void)fprintf(out, "%016llx 9 SCALAR:%s\n", (unsigned long long)one, \
                      #field); \
    } while (0)
    DUMP_SCALAR(engine->group_level);
    DUMP_SCALAR(engine->save_count);
    DUMP_SCALAR(engine->conditional_count);
    DUMP_SCALAR(engine->mode);
    DUMP_SCALAR(engine->prev_depth);
    DUMP_SCALAR(engine->space_factor);
    DUMP_SCALAR(engine->font_count);
    DUMP_SCALAR(engine->current_font);
    DUMP_SCALAR(engine->page_integers);
    DUMP_SCALAR(engine->page_dimens);
    DUMP_SCALAR(engine->integer_parameters);
    DUMP_SCALAR(engine->dimen_parameters);
    DUMP_SCALAR(engine->glue_parameters);
    DUMP_SCALAR(engine->muglue_parameters);
    DUMP_SCALAR(engine->code_tables);
    DUMP_SCALAR(engine->math_fonts);
    DUMP_SCALAR(engine->lexical_state.catcodes);
#undef DUMP_SCALAR
    (void)fprintf(out, "0000000000000000 9 OUTPUT: pdf_written=%zu objects=%d\n",
                  engine->pdf_written, engine->pdf_object_counter);
    if (engine->contribution_builder != NULL) {
        (void)fprintf(out, "0000000000000000 9 CONTRIB: count=%zu\n",
                      engine->contribution_builder->count);
        for (size_t index = 0U;
             index < engine->contribution_builder->count && index < 40U;
             ++index) {
            uint32_t identifier =
                engine->contribution_builder->node_identifiers[index];
            if (identifier == 0U ||
                (size_t)identifier > engine->node_count) {
                continue;
            }
            const struct hstex_node *node =
                &engine->nodes[identifier - 1U];
            (void)fprintf(out,
                          "0000000000000000 9 CONTRIB[%zu]: kind=%d w=%d h=%d d=%d\n",
                          index, (int)node->kind, node->width, node->height,
                          node->depth);
        }
    }
    if (engine->page_builder != NULL) {
        (void)fprintf(out, "0000000000000000 9 PAGE: count=%zu\n",
                      engine->page_builder->count);
        for (size_t index = 0U; index < engine->page_builder->count &&
                                index < 40U; ++index) {
            uint32_t identifier =
                engine->page_builder->node_identifiers[index];
            if (identifier == 0U || (size_t)identifier > engine->node_count) {
                continue;
            }
            const struct hstex_node *node = &engine->nodes[identifier - 1U];
            (void)fprintf(out,
                          "0000000000000000 9 PAGEN[%zu]: kind=%d w=%d h=%d d=%d s=%d\n",
                          index, (int)node->kind, node->width, node->height,
                          node->depth, node->shift);
        }
    }
    (void)fprintf(out, "0000000000000000 9 PAR: building=%d count=%zu\n",
                  engine->building_paragraph,
                  engine->paragraph_builder == NULL
                      ? (size_t)0
                      : engine->paragraph_builder->count);
    if (engine->paragraph_builder != NULL) {
        for (size_t index = 0U; index < engine->paragraph_builder->count &&
                                index < 60U; ++index) {
            uint32_t identifier =
                engine->paragraph_builder->node_identifiers[index];
            if (identifier == 0U || (size_t)identifier > engine->node_count) {
                continue;
            }
            const struct hstex_node *node = &engine->nodes[identifier - 1U];
            (void)fprintf(out,
                          "0000000000000000 9 PARN[%zu]: kind=%d w=%d h=%d d=%d\n",
                          index, (int)node->kind, node->width, node->height,
                          node->depth);
        }
    }
    for (size_t index = 0U; index < engine->sources.count; ++index) {
        const struct hstex_source_frame *frame = &engine->sources.frames[index];
        if (frame->kind == HSTEX_SOURCE_FILE) {
            (void)fprintf(out, "0000000000000000 9 SOURCE[%zu]: file %s line %u cursor %zu\n",
                          index, frame->value.file->path,
                          frame->value.file->mouth.line_number,
                          frame->value.file->mouth.line_cursor);
        } else if (frame->kind == HSTEX_SOURCE_TOKEN_LIST) {
            (void)fprintf(out, "0000000000000000 9 SOURCE[%zu]: tokens count=%u cursor=%u definition=%u flags=%u\n",
                          index, frame->value.token_list.count,
                          frame->value.token_list.cursor,
                          frame->value.token_list.definition,
                          frame->value.token_list.flags);
        } else {
            (void)fprintf(out, "0000000000000000 9 SOURCE[%zu]: boundary\n", index);
        }
    }
    for (hstex_cs_id identifier = 1U;
         (size_t)identifier <= engine->meaning_capacity; ++identifier) {
        uint64_t hash = canonical_meaning_hash(engine, identifier);
        if (hash == 0U) {
            continue;
        }
        enum hstex_symbol_kind kind;
        const uint8_t *name = NULL;
        size_t name_length = 0U;
        if (hstex_symbol_name(&engine->lexical_state.symbols, identifier,
                              &kind, &name, &name_length) != 0) {
            continue;
        }
        (void)fprintf(out, "%016llx %d %.*s\n", (unsigned long long)hash,
                      (int)kind, (int)name_length, (const char *)name);
    }
    (void)fclose(out);
}

/* A waived name was read while it still held what the boundary left in it:
   the wager behind the waiver -- written before read -- failed for this
   chunk, so its pages may depend on scratch from across the boundary and it
   disqualifies itself. The carrier will rewrite its range. */
static void taint_read_before_write(struct hstex_engine *engine,
                                    hstex_cs_id identifier)
{
    engine->taint_pending = 0U;
    if (!engine->taint_violated) {
        engine->taint_violated = 1;
        enum hstex_symbol_kind kind;
        const uint8_t *name = NULL;
        size_t length = 0U;
        char content[128];
        content[0] = '\0';
        if (hstex_symbol_name(&engine->lexical_state.symbols, identifier,
                              &kind, &name, &length) == 0 &&
            length < sizeof(content) - 2U) {
            (void)snprintf(content, sizeof(content), "%.*s\n", (int)length,
                           (const char *)name);
        }
        spec_touch(engine, "tainted", engine->spec_start,
                   content[0] == '\0' ? NULL : content);
    }
}

/* Arm the check: every control sequence whose name is on the waiver gets a
   byte saying "not yet written". The walk over the symbol table happens
   once, at the chunk's wake. */
static void taint_arm(struct hstex_engine *engine)
{
    if (engine->soft_name_count == 0U) {
        return;
    }
    free(engine->taint_map);
    engine->taint_map_capacity = engine->meaning_capacity;
    engine->taint_map = calloc(engine->taint_map_capacity, 1U);
    if (engine->taint_map == NULL) {
        engine->taint_map_capacity = 0U;
        return;
    }
    engine->taint_pending = 0U;
    engine->taint_violated = 0;
    size_t names = engine->lexical_state.symbols.entry_count;
    for (hstex_cs_id identifier = 1U; (size_t)identifier <= names;
         ++identifier) {
        enum hstex_symbol_kind kind;
        const uint8_t *name = NULL;
        size_t length = 0U;
        if (hstex_symbol_name(&engine->lexical_state.symbols, identifier,
                              &kind, &name, &length) != 0) {
            continue;
        }
        if ((size_t)identifier <= engine->taint_map_capacity &&
            name_is_soft(engine, name_only_hash(kind, name, length))) {
            engine->taint_map[identifier - 1U] = 1U;
            ++engine->taint_pending;
        }
    }
}

/* A probe reports the state a patched chunk would begin in, and leaves: what
   it is for is comparing that state against the run the guess is about. */
static void probe_and_leave(struct hstex_engine *engine)
{
    const char *directory = getenv("HSTEX_FLEET_PROBE");
    if (directory == NULL) {
        return;
    }
    char name[512];
    (void)snprintf(name, sizeof(name), "%s/entry-%d.txt", directory,
                   engine->shipped_pages);
    FILE *out = fopen(name, "w");
    if (out != NULL) {
        uint64_t semantic = 0U;
        uint64_t placement = 0U;
        uint64_t parts[6];
        page_state_digest_split_parts(engine, &semantic, &placement, parts);
        (void)fprintf(out,
                      "%d %016llx %016llx %016llx %016llx %016llx %016llx\n",
                      engine->shipped_pages, (unsigned long long)semantic,
                      (unsigned long long)placement,
                      (unsigned long long)parts[0],
                      (unsigned long long)parts[1],
                      (unsigned long long)parts[2],
                      (unsigned long long)parts[3]);
        (void)fprintf(out, "part4 %016llx\n", (unsigned long long)parts[4]);
        (void)fclose(out);
    }
    maybe_dump_meanings(engine);
    char done = 1;
    ssize_t said = write(engine->parallel_done_write, &done, 1);
    (void)said;
    _exit(0);
}


/* ---- The relay ----------------------------------------------------------
   One run at a time carries the truth. Parked chunks each typeset their own
   range on a guess; the carrier walks the document from the front, and at
   every parked page compares its state with the chunk's patched beginning.
   Equal means everything that chunk wrote is right, so the carrier confers
   validity and stops; the chunk, told it was valid, either rests -- its own
   end matched the next beginning -- or takes the baton and reruns what the
   chunk after it got wrong. Verdicts flow strictly forward from the
   verifier, so there is exactly one carrier at any moment, and a stale
   region is rewritten only after the chunk that wrote it has said it is
   done writing. Everything meets in a directory of small files:

     pages.txt          the parked pages, one per line
     entry-<P>.txt      the patched state a chunk began in
     marker-<P>.txt     written when the chunk that began at P stops writing
     valid-<P>.txt      the carrier's verdict: everything from P stands
     stale-<P>.txt      the carrier's verdict: P was wrong and is rewritten
     end-done.txt       a carrier ran all the way to the end
*/

static void spec_path(const struct hstex_engine *engine, char *room,
                      size_t capacity, const char *prefix, int32_t page)
{
    if (page >= 0) {
        (void)snprintf(room, capacity, "%s/%s-%d.txt", engine->spec_dir,
                       prefix, page);
    } else {
        (void)snprintf(room, capacity, "%s/%s.txt", engine->spec_dir, prefix);
    }
}

static bool spec_exists(const struct hstex_engine *engine, const char *prefix,
                        int32_t page)
{
    char name[600];
    spec_path(engine, name, sizeof(name), prefix, page);
    return access(name, F_OK) == 0;
}

static void spec_wait(const struct hstex_engine *engine, const char *prefix,
                      int32_t page)
{
    char name[600];
    spec_path(engine, name, sizeof(name), prefix, page);
    struct timespec nap = {0, 2000000L};
    while (access(name, F_OK) != 0) {
        (void)nanosleep(&nap, NULL);
    }
}

static void spec_touch(const struct hstex_engine *engine, const char *prefix,
                       int32_t page, const char *content)
{
    char name[600];
    char temporary[640];
    spec_path(engine, name, sizeof(name), prefix, page);
    (void)snprintf(temporary, sizeof(temporary), "%s.tmp", name);
    FILE *out = fopen(temporary, "w");
    if (out == NULL) {
        return;
    }
    if (content != NULL) {
        (void)fputs(content, out);
    }
    (void)fclose(out);
    (void)rename(temporary, name);
}

static void spec_write_state(const struct hstex_engine *engine,
                             const char *prefix, int32_t page)
{
    uint64_t semantic = 0U;
    uint64_t placement = 0U;
    page_state_digest_split(engine, &semantic, &placement);
    char line[64];
    (void)snprintf(line, sizeof(line), "%016llx %016llx\n",
                   (unsigned long long)semantic,
                   (unsigned long long)placement);
    spec_touch(engine, prefix, page, line);
}

static bool spec_read_state(const struct hstex_engine *engine,
                            const char *prefix, int32_t page,
                            uint64_t *semantic, uint64_t *placement)
{
    char name[600];
    spec_path(engine, name, sizeof(name), prefix, page);
    FILE *in = fopen(name, "r");
    if (in == NULL) {
        return false;
    }
    unsigned long long a = 0U;
    unsigned long long b = 0U;
    int got = fscanf(in, "%llx %llx", &a, &b);
    (void)fclose(in);
    if (got != 2) {
        return false;
    }
    *semantic = a;
    *placement = b;
    return true;
}

static void spec_load_pages(struct hstex_engine *engine)
{
    if (engine->spec_pages != NULL) {
        return;
    }
    char name[600];
    spec_path(engine, name, sizeof(name), "pages", -1);
    FILE *in = fopen(name, "r");
    if (in == NULL) {
        return;
    }
    size_t capacity = 16U;
    engine->spec_pages = malloc(capacity * sizeof(*engine->spec_pages));
    long page = 0L;
    while (engine->spec_pages != NULL && fscanf(in, "%ld", &page) == 1) {
        if (engine->spec_page_count == capacity) {
            capacity *= 2U;
            int32_t *grown = realloc(engine->spec_pages,
                                     capacity * sizeof(*grown));
            if (grown == NULL) {
                break;
            }
            engine->spec_pages = grown;
        }
        engine->spec_pages[engine->spec_page_count++] = (int32_t)page;
    }
    (void)fclose(in);
}

static bool spec_is_parked_page(struct hstex_engine *engine, int32_t page)
{
    spec_load_pages(engine);
    for (size_t index = 0U; index < engine->spec_page_count; ++index) {
        if (engine->spec_pages[index] == page) {
            return true;
        }
    }
    return false;
}

/* Everything written so far goes to the file, so that a marker or a stop
   means what it says. */
/* A worker's digest reads the offsets snapshotted at its fork, because a
   forked copy's ftell can alias the shared descriptor. Once the worker has
   opened its fleet copies, the streams are its own and the snapshot is what
   is stale, so it is brought up to date before a digest is taken. */
static void spec_refresh_reached(struct hstex_engine *engine)
{
    for (size_t index = 0U; index < 16U; ++index) {
        if (engine->write_streams[index] != NULL) {
            engine->parallel_reached[index] =
                ftell(engine->write_streams[index]);
        }
    }
}

static void spec_flush(struct hstex_engine *engine)
{
    char ignored[256];
    (void)pdf_flush(engine, ignored, sizeof(ignored));
    if (engine->pdf_file != NULL) {
        (void)fflush(engine->pdf_file);
    }
    for (size_t index = 0U; index < 16U; ++index) {
        if (engine->write_streams[index] != NULL) {
            (void)fflush(engine->write_streams[index]);
        }
    }
}

/* A speculative chunk has reached the page the chunk after it began at: its
   own writing is done. It says so, then waits to be told whether it was
   right about the world -- valid, and it rests or takes the baton; stale,
   and everything it wrote will be rewritten by whoever said so. */
static void spec_chunk_stop(struct hstex_engine *engine)
{
    spec_refresh_reached(engine);
    spec_flush(engine);
    uint64_t semantic = 0U;
    uint64_t placement = 0U;
    page_state_digest_split(engine, &semantic, &placement);
    uint64_t entry_semantic = 0U;
    uint64_t entry_placement = 0U;
    bool matched =
        spec_read_state(engine, "entry", engine->shipped_pages,
                        &entry_semantic, &entry_placement) &&
        semantic == entry_semantic && placement == entry_placement;
    spec_write_state(engine, "marker", engine->spec_start);
    for (;;) {
        if (spec_exists(engine, "valid", engine->spec_start)) {
            if (matched) {
                spec_touch(engine, "valid", engine->shipped_pages, NULL);
                _exit(0);
            }
            /* The chunk after this one began somewhere this run did not
               reach, so this run -- the true one, as it now knows -- takes
               the baton and rewrites it. At the document's end there is no
               chunk after: nothing to disown, nothing to wait for. */
            if (spec_exists(engine, "entry", engine->shipped_pages)) {
                spec_touch(engine, "stale", engine->shipped_pages, NULL);
                spec_wait(engine, "marker", engine->shipped_pages);
            }
            engine->spec_carrier = 1;
            engine->parallel_stop = 0;
            return;
        }
        if (spec_exists(engine, "stale", engine->spec_start)) {
            _exit(0);
        }
        struct timespec nap = {0, 2000000L};
        (void)nanosleep(&nap, NULL);
    }
}

/* The carrier at a parked page. Its state is the truth; the entry file is
   what the chunk that began here guessed. Equal: everything from here on
   stands, and the carrier's work is over. Not equal: the chunk was wrong,
   and the carrier waits for it to stop writing and then rewrites its range. */
static void spec_carrier_boundary(struct hstex_engine *engine)
{
    if (engine->shipped_pages == engine->spec_start ||
        !spec_is_parked_page(engine, engine->shipped_pages)) {
        return;
    }
    if (engine->parallel_is_worker) {
        spec_refresh_reached(engine);
    }
    uint64_t semantic = 0U;
    uint64_t placement = 0U;
    page_state_digest_split(engine, &semantic, &placement);
    uint64_t entry_semantic = 0U;
    uint64_t entry_placement = 0U;
    if (!spec_exists(engine, "tainted", engine->shipped_pages) &&
        spec_read_state(engine, "entry", engine->shipped_pages,
                        &entry_semantic, &entry_placement) &&
        semantic == entry_semantic && placement == entry_placement) {
        spec_flush(engine);
        spec_touch(engine, "valid", engine->shipped_pages, NULL);
        if (engine->verifying) {
            engine->spec_finished = 1;
            return;
        }
        _exit(0);
    }
    spec_touch(engine, "stale", engine->shipped_pages, NULL);
    spec_wait(engine, "marker", engine->shipped_pages);
}

static void speculation_boundary(struct hstex_engine *engine)
{
    if (engine->spec_carrier) {
        spec_carrier_boundary(engine);
        return;
    }
    if (engine->speculating && engine->parallel_stop > 0 &&
        engine->shipped_pages >= engine->parallel_stop) {
        spec_chunk_stop(engine);
    }
}

/* The verifier has stopped -- by handing off, or by running to the end. The
   final files are assembled from the fleet copies once every parked page has
   a verdict and every writer has said it is done. */
static void spec_finalize(struct hstex_engine *engine)
{
    spec_load_pages(engine);
    bool tail_is_stale = false;
    for (size_t index = 0U; index < engine->spec_page_count; ++index) {
        int32_t page = engine->spec_pages[index];
        struct timespec nap = {0, 2000000L};
        while (!spec_exists(engine, "valid", page) &&
               !spec_exists(engine, "stale", page)) {
            (void)nanosleep(&nap, NULL);
        }
        spec_wait(engine, "marker", page);
        if (index + 1U == engine->spec_page_count) {
            tail_is_stale = spec_exists(engine, "stale", page);
        }
    }
    /* A stale tail was rewritten by whoever carried the truth last. When
       the verifier itself carried to the end -- it never handed off -- the
       rewriting is its own, already flushed, and there is nobody to wait
       for. */
    if (tail_is_stale && engine->spec_finished &&
        !spec_exists(engine, "end-done", -1)) {
        spec_wait(engine, "end-done", -1);
    }
    /* The fleet copies become the real files. */
    for (size_t index = 0U; index < 16U; ++index) {
        if (engine->write_streams[index] == NULL ||
            engine->write_stream_paths[index] == NULL) {
            continue;
        }
        (void)fclose(engine->write_streams[index]);
        engine->write_streams[index] = NULL;
        char *fleet = engine->write_stream_paths[index];
        size_t length = strlen(fleet);
        if (length > 6U && strcmp(fleet + length - 6U, "-fleet") == 0) {
            char *real = strndup(fleet, length - 6U);
            if (real != NULL) {
                (void)rename(fleet, real);
                free(real);
            }
        }
    }
    {
        if (engine->pdf_file != NULL) {
            (void)fclose(engine->pdf_file);
            engine->pdf_file = NULL;
        }
        const char *job = engine->job_name == NULL ? "texput"
                                                   : engine->job_name;
        char fleet_name[512];
        char real_name[512];
        (void)snprintf(fleet_name, sizeof(fleet_name), "%s-fleet.pdf", job);
        (void)snprintf(real_name, sizeof(real_name), "%s.pdf", job);
        char *from = output_path(engine, fleet_name);
        char *to = output_path(engine, real_name);
        if (from != NULL && to != NULL) {
            (void)rename(from, to);
        }
        free(from);
        free(to);
    }
}

static void take_up_elsewhere(struct hstex_engine *engine)
{
    if (engine->checkpoint_page == 0 ||
        engine->shipped_pages != engine->checkpoint_page) {
        return;
    }
    /* Moved on before the fork, so that the child takes up the run looking
       for the next one rather than this one again. */
    engine->checkpoint_page = engine->checkpoint_stride == 0
                                  ? 0
                                  : engine->checkpoint_page +
                                        engine->checkpoint_stride;
    pid_t child = fork();
    if (child < 0) {
        return;
    }
    if (child != 0) {
        int status = 0;
        while (waitpid(child, &status, 0) < 0 && errno == EINTR) {
        }
        _exit(WIFEXITED(status) ? WEXITSTATUS(status) : 1);
    }
}

enum hstex_engine_result hstex_engine_next_output(
    struct hstex_engine *engine, hstex_token *token,
    struct hstex_source_location *location, char *error,
    size_t error_capacity)
{
    if (engine->output_depth == 0U && engine->shipped_pages == 0 &&
        engine->page_has_box && !engine->checkpoint_zero_done) {
        /* The preamble is behind us and page one has begun: drop the
           post-preamble checkpoint so a warm run's first chunk need not read
           the preamble again. */
        maybe_write_checkpoint(engine);
    }
    if (engine->output_depth == 0U &&
        engine->shipped_pages != engine->last_page_boundary) {
        /* What nothing can reach is given back every eighth page rather
           than every page: what one page leaves behind is half a megabyte,
           and walking everything that is still alive costs the same however
           little is dead. A run that is being asked whether the walk's list
           of roots is complete walks at every page, as it always did, so
           the answer means what it meant. */
        int32_t stride =
            engine->dead_node_check == HSTEX_DEAD_NODES_GIVEN_BACK ? 8 : 1;
        engine->last_page_boundary = engine->shipped_pages;
        if (engine->shipped_pages - engine->compacted_pages >= stride) {
            engine->compacted_pages = engine->shipped_pages;
            compact_nodes(engine);
        }
        note_page_digest(engine);
        maybe_write_checkpoint(engine);
        if (maybe_stop_at_resume_page(engine)) {
            /* A resumed chunk stops here at its own boundary and finishes its
               PDF the ordinary way -- not the fleet's spec_finished hand-off,
               which leaves the trailer to chunks that are not there. */
            return HSTEX_ENGINE_EOF;
        }
        take_up_elsewhere(engine);
        park_a_chunk(engine);
        speculation_boundary(engine);
        if (engine->spec_finished) {
            return HSTEX_ENGINE_EOF;
        }
    }
    ++engine->output_depth;
    enum hstex_engine_result result =
        next_output(engine, token, location, error, error_capacity);
    --engine->output_depth;
    return result;
}
